export type UserRole = 'ADMIN' | 'TEACHER' | 'PARENT';

export interface User {
  id: string;
  name: string;
  role: UserRole;
  department?: string;
}

export type AttendanceStatus = 'PRESENT' | 'LATE' | 'ABSENT' | 'LEAVE';

export interface Student {
  id: string;
  studentId: string;
  name: string;
  level: string; // ปวช. 1, ปวช. 2, ปวส. 1
  department: string; // ช่างยนต์, เทคโนโลยีสารสนเทศ
  room: string;
  behaviorScore: number;
}

export interface AttendanceRecord {
  id: string;
  studentId: string;
  date: string;
  type: 'MORNING' | 'SUBJECT';
  subjectId?: string;
  status: AttendanceStatus;
  timestamp: string;
}

export interface Subject {
  id: string;
  name: string;
  code: string;
  teacherId: string;
}

export interface BehaviorRecord {
  id: string;
  studentId: string;
  type: 'ADD' | 'DEDUCT';
  score: number;
  reason: string;
  date: string;
  recordedBy: string;
}

