import React, { useState } from 'react';
import { MENU_ITEMS, COLORS } from '../constants';
import { LogOut, Menu, X, User } from 'lucide-react';

interface LayoutProps {
  children: React.ReactNode;
  activeMenu: string;
  setActiveMenu: (menu: string) => void;
  user: any;
  onLogout: () => void;
}

const Layout: React.FC<LayoutProps> = ({ children, activeMenu, setActiveMenu, user, onLogout }) => {
  const [isSidebarOpen, setSidebarOpen] = useState(false);

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden">
      {/* Sidebar Overlay for Mobile */}
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-black bg-opacity-50 z-20 md:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-30 w-64 bg-slate-900 text-white transform transition-transform duration-300 ease-in-out
        md:relative md:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-6">
          <h1 className="text-2xl font-bold text-blue-400 flex items-center gap-2">
            EduSmart <span className="text-white text-sm font-normal bg-blue-600 px-2 py-0.5 rounded">CMS</span>
          </h1>
        </div>

        <nav className="mt-6 px-4 space-y-2">
          {MENU_ITEMS.map((item) => (
            <button
              key={item.id}
              onClick={() => {
                setActiveMenu(item.id);
                setSidebarOpen(false);
              }}
              className={`
                w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all
                ${activeMenu === item.id 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/20' 
                  : 'text-slate-400 hover:bg-slate-800 hover:text-white'}
              `}
            >
              {React.cloneElement(item.icon as React.ReactElement, { size: 20 })}
              <span className="font-medium">{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="absolute bottom-0 w-full p-4 border-t border-slate-800">
          <button 
            onClick={onLogout}
            className="w-full flex items-center gap-3 px-4 py-3 text-slate-400 hover:text-red-400 hover:bg-red-900/10 rounded-xl transition-all"
          >
            <LogOut size={20} />
            <span className="font-medium">ออกจากระบบ</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Header */}
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-6 shrink-0 z-10">
          <div className="flex items-center gap-4">
            <button 
              className="md:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-lg"
              onClick={() => setSidebarOpen(true)}
            >
              <Menu size={24} />
            </button>
            <h2 className="text-xl font-semibold text-slate-800">
              {MENU_ITEMS.find(i => i.id === activeMenu)?.label}
            </h2>
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden sm:block text-right">
              <p className="text-sm font-medium text-slate-900">{user.name}</p>
              <p className="text-xs text-slate-500">{user.department || 'อาจารย์'}</p>
            </div>
            <div className="w-10 h-10 rounded-full bg-slate-100 border border-slate-200 flex items-center justify-center text-slate-500">
              <User size={20} />
            </div>
          </div>
        </header>

        {/* Page Content */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
          {children}
        </div>
      </main>
    </div>
  );
};

export default Layout;

import React, { useState, useEffect } from 'react';
import { MOCK_STUDENTS } from '../data/mockData';
import { AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { Search, Save, CheckCircle2, Filter } from 'lucide-react';

const MorningAttendance: React.FC = () => {
  const [level, setLevel] = useState<string>(ThaiLevel.VCC1);
  const [dept, setDept] = useState<string>(Department.IT);
  const [room, setRoom] = useState<string>('1');
  const [searchTerm, setSearchTerm] = useState('');
  const [attendance, setAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [isSaved, setIsSaved] = useState(false);

  // Filter students based on selection
  const filteredStudents = MOCK_STUDENTS.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room &&
    (s.name.includes(searchTerm) || s.studentId.includes(searchTerm))
  );

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setAttendance(prev => ({
      ...prev,
      [studentId]: status
    }));
    setIsSaved(false);
  };

  const handleSave = () => {
    // In a real app, this would send data to an API
    console.log('Saving attendance:', attendance);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 3000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => {
      newBatch[s.id] = status;
    });
    setAttendance(prev => ({ ...prev, ...newBatch }));
  };

  return (
    <div className="space-y-6">
      {/* Filters */}
      <div className="bg-white p-4 md:p-6 rounded-2xl border border-slate-200 shadow-sm">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-500 uppercase">ระดับชั้น</label>
            <select 
              value={level}
              onChange={(e) => setLevel(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
            >
              {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-500 uppercase">แผนกวิชา</label>
            <select 
              value={dept}
              onChange={(e) => setDept(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
            >
              {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-500 uppercase">ห้อง</label>
            <select 
              value={room}
              onChange={(e) => setRoom(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="1">ห้อง 1</option>
              <option value="2">ห้อง 2</option>
              <option value="3">ห้อง 3</option>
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-semibold text-slate-500 uppercase">ค้นหาชื่อ/รหัส</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="พิมพ์ชื่อ..."
                className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-10 pr-3 py-2 outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
          </div>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-2">
          <span className="text-sm text-slate-500 font-medium">ทางลัด:</span>
          <button onClick={() => markAll('PRESENT')} className="px-3 py-1 bg-green-50 text-green-700 rounded-lg text-xs font-semibold border border-green-200 hover:bg-green-100">มาทุกคน</button>
          <button onClick={() => markAll('ABSENT')} className="px-3 py-1 bg-red-50 text-red-700 rounded-lg text-xs font-semibold border border-red-200 hover:bg-red-100">ขาดทุกคน</button>
        </div>

        <button 
          onClick={handleSave}
          disabled={filteredStudents.length === 0}
          className={`flex items-center gap-2 px-6 py-2 rounded-xl text-white font-bold transition-all shadow-lg ${isSaved ? 'bg-green-600' : 'bg-blue-600 hover:bg-blue-700'} active:scale-95`}
        >
          {isSaved ? <CheckCircle2 size={20} /> : <Save size={20} />}
          {isSaved ? 'บันทึกสำเร็จ' : 'บันทึกการเช็คชื่อ'}
        </button>
      </div>

      {/* Student List */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {filteredStudents.length > 0 ? (
          filteredStudents.map((student, index) => (
            <div key={student.id} className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm hover:border-blue-300 transition-colors">
              <div className="flex items-start justify-between mb-4">
                <div className="flex gap-3">
                  <div className="w-12 h-12 bg-slate-100 rounded-xl flex items-center justify-center font-bold text-slate-500">
                    {index + 1}
                  </div>
                  <div>
                    <h4 className="font-bold text-slate-900">{student.name}</h4>
                    <p className="text-xs text-slate-500">รหัส: {student.studentId}</p>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-4 gap-2">
                {Object.entries(STATUS_LABELS).map(([key, value]) => (
                  <button
                    key={key}
                    onClick={() => handleStatusChange(student.id, key as AttendanceStatus)}
                    className={`
                      flex flex-col items-center gap-1 p-2 rounded-xl transition-all border
                      ${attendance[student.id] === key 
                        ? value.color + ' border-current scale-105 shadow-md ring-2 ring-blue-500 ring-offset-2' 
                        : 'bg-slate-50 border-slate-100 text-slate-400 grayscale hover:grayscale-0 hover:bg-white'}
                    `}
                  >
                    {value.icon}
                    <span className="text-[10px] font-bold uppercase">{value.label}</span>
                  </button>
                ))}
              </div>
            </div>
          ))
        ) : (
          <div className="col-span-full py-12 text-center text-slate-400">
            <Filter size={48} className="mx-auto mb-4 opacity-20" />
            <p className="text-lg font-medium">ไม่พบข้อมูลนักเรียนในระดับชั้น/ห้องนี้</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default MorningAttendance;

import React, { useState } from 'react';
