                          onClick={() => handleStatusChange(student.id, status)}
                          className={`
                            px-4 py-1.5 rounded-lg text-xs font-bold transition-all border
                            ${attendance[student.id] === status 
                              ? STATUS_LABELS[status].color + ' border-current'
                              : 'bg-white text-slate-400 border-slate-200 hover:border-slate-300'}
                          `}
                        >
                          {STATUS_LABELS[status].label}
                        </button>
                      ))}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center justify-center gap-3">
                      <div className="w-24 bg-slate-100 h-2 rounded-full overflow-hidden">
                        <div className="bg-blue-600 h-full" style={{ width: '95%' }}></div>
                      </div>
                      <span className="text-xs font-bold text-slate-700">95%</span>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

