import React, { useState, useEffect } from 'react';
import { MOCK_STUDENTS } from '../data/mockData';
import { AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { Search, Save, CheckCircle2, Filter } from 'lucide-react';

const MorningAttendance: React.FC = () => {
  const [level, setLevel] = useState<string>(ThaiLevel.VCC1);
  const [dept, setDept] = useState<string>(Department.IT);
  const [room, setRoom] = useState<string>('1');
  const [searchTerm, setSearchTerm] = useState('');
  const [attendance, setAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [isSaved, setIsSaved] = useState(false);

  // Filter students based on selection
  const filteredStudents = MOCK_STUDENTS.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room &&
    (s.name.includes(searchTerm) || s.studentId.includes(searchTerm))
  );

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setAttendance(prev => ({
      ...prev,
      [studentId]: status
    }));
    setIsSaved(false);
  };

  const handleSave = () => {
    // In a real app, this would send data to an API
    console.log('Saving attendance:', attendance);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 3000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => {
      newBatch[s.id] = status;
    });
    setAttendance(prev => ({ ...prev, ...newBatch }));
  };

  return (
    <div className="space-y-6">
      {/* Filters */}
      <div className="bg-white p-4 md:p-6 rounded-2xl border border-slate-200 shadow-sm">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="space-y-1">
            <label className="text-xs font-black text-black uppercase">ระดับชั้น</label>
            <select 
              value={level}
              onChange={(e) => setLevel(e.target.value)}
              className="w-full bg-slate-50 border border-slate-300 rounded-xl px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black"
            >
              {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-black text-black uppercase">แผนกวิชา</label>
            <select 
              value={dept}
              onChange={(e) => setDept(e.target.value)}
              className="w-full bg-slate-50 border border-slate-300 rounded-xl px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black"
            >
              {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-black text-black uppercase">ห้อง</label>
            <select 
              value={room}
              onChange={(e) => setRoom(e.target.value)}
              className="w-full bg-slate-50 border border-slate-300 rounded-xl px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black"
            >
              <option value="1">ห้อง 1</option>
              <option value="2">ห้อง 2</option>
              <option value="3">ห้อง 3</option>
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-black text-black uppercase">ค้นหาชื่อ/รหัส</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-900" size={18} />
              <input 
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="พิมพ์ชื่อ..."
                className="w-full bg-slate-50 border border-slate-300 rounded-xl pl-10 pr-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black"
              />
            </div>
          </div>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-2">
          <span className="text-sm text-black font-black">ทางลัด:</span>
          <button onClick={() => markAll('PRESENT')} className="px-3 py-1 bg-green-100 text-green-800 rounded-lg text-xs font-black border border-green-300 hover:bg-green-200">มาทุกคน</button>
          <button onClick={() => markAll('ABSENT')} className="px-3 py-1 bg-red-100 text-red-800 rounded-lg text-xs font-black border border-red-300 hover:bg-red-200">ขาดทุกคน</button>
        </div>

        <button 
          onClick={handleSave}
          disabled={filteredStudents.length === 0}
