import React, { useState } from 'react';
import { MOCK_STUDENTS } from '../data/mockData';
import { AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { Search, Save, CheckCircle2, Filter, Plus, X } from 'lucide-react';

const MorningAttendance: React.FC = () => {
  // Dynamic lists for filters
  const [levels, setLevels] = useState<string[]>(Object.values(ThaiLevel));
  const [depts, setDepts] = useState<string[]>(Object.values(Department));
  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);

  const [level, setLevel] = useState<string>(levels[0]);
  const [dept, setDept] = useState<string>(depts[0]);
  const [room, setRoom] = useState<string>(rooms[0]);

  const [searchTerm, setSearchTerm] = useState('');
  const [attendance, setAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [isSaved, setIsSaved] = useState(false);

  // Modal State
  const [showAddModal, setShowAddModal] = useState<{ type: 'LEVEL' | 'DEPT' | 'ROOM' | null }>({ type: null });
  const [newValue, setNewValue] = useState('');

  // Filter students based on selection
  const filteredStudents = MOCK_STUDENTS.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room &&
    (s.name.includes(searchTerm) || s.studentId.includes(searchTerm))
  );

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setAttendance(prev => ({
      ...prev,
      [studentId]: status
    }));
    setIsSaved(false);
  };

  const handleSave = () => {
    console.log('Saving attendance:', attendance);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 3000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => {
      newBatch[s.id] = status;
    });
    setAttendance(prev => ({ ...prev, ...newBatch }));
  };

  const handleAddNew = () => {
    if (!newValue.trim()) return;

    if (showAddModal.type === 'LEVEL') {
      setLevels([...levels, newValue]);
      setLevel(newValue);
    } else if (showAddModal.type === 'DEPT') {
      setDepts([...depts, newValue]);
      setDept(newValue);
    } else if (showAddModal.type === 'ROOM') {
      setRooms([...rooms, newValue]);
      setRoom(newValue);
    }

    setNewValue('');
    setShowAddModal({ type: null });
  };

  return (
    <div className="space-y-6">
      {/* Filters */}
      <div className="bg-white p-4 md:p-6 rounded-2xl border border-slate-200 shadow-sm relative">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          {/* Level Filter */}
          <div className="space-y-1">
            <div className="flex justify-between items-center">
              <label className="text-xs font-black text-black uppercase">ระดับชั้น</label>
              <button 
                onClick={() => setShowAddModal({ type: 'LEVEL' })}
                className="p-1 hover:bg-blue-50 text-blue-600 rounded-md transition-colors"
                title="เพิ่มระดับชั้น"
              >
                <Plus size={14} strokeWidth={3} />
              </button>
            </div>
            <select 
              value={level}
              onChange={(e) => setLevel(e.target.value)}
              className="w-full bg-slate-50 border border-slate-300 rounded-xl px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black appearance-none"
            >
              {levels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>

          {/* Department Filter */}
          <div className="space-y-1">
            <div className="flex justify-between items-center">
              <label className="text-xs font-black text-black uppercase">แผนกวิชา</label>
              <button 
                onClick={() => setShowAddModal({ type: 'DEPT' })}
                className="p-1 hover:bg-blue-50 text-blue-600 rounded-md transition-colors"
                title="เพิ่มแผนกวิชา"
              >
                <Plus size={14} strokeWidth={3} />
              </button>
            </div>
            <select 
              value={dept}
              onChange={(e) => setDept(e.target.value)}
              className="w-full bg-slate-50 border border-slate-300 rounded-xl px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black appearance-none"
            >
              {depts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>

          {/* Room Filter */}
          <div className="space-y-1">
            <div className="flex justify-between items-center">
              <label className="text-xs font-black text-black uppercase">ห้อง</label>
              <button 
                onClick={() => setShowAddModal({ type: 'ROOM' })}
                className="p-1 hover:bg-blue-50 text-blue-600 rounded-md transition-colors"
                title="เพิ่มห้อง"
              >
                <Plus size={14} strokeWidth={3} />
              </button>
            </div>
            <select 
              value={room}
              onChange={(e) => setRoom(e.target.value)}
              className="w-full bg-slate-50 border border-slate-300 rounded-xl px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black appearance-none"
            >
              {rooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
            </select>
          </div>

          {/* Search Filter */}
          <div className="space-y-1">
            <label className="text-xs font-black text-black uppercase">ค้นหาชื่อ/รหัส</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-900" size={18} />
              <input 
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="พิมพ์ชื่อ..."
                className="w-full bg-slate-50 border border-slate-300 rounded-xl pl-10 pr-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black"
              />
            </div>
          </div>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-2">
          <span className="text-sm text-black font-black">ทางลัด:</span>
          <button onClick={() => markAll('PRESENT')} className="px-3 py-1 bg-green-100 text-green-800 rounded-lg text-xs font-black border border-green-300 hover:bg-green-200 transition-all">มาทุกคน</button>
          <button onClick={() => markAll('ABSENT')} className="px-3 py-1 bg-red-100 text-red-800 rounded-lg text-xs font-black border border-red-300 hover:bg-red-200 transition-all">ขาดทุกคน</button>
        </div>

        <button 
          onClick={handleSave}
          disabled={filteredStudents.length === 0}
          className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-white font-black transition-all shadow-lg ${isSaved ? 'bg-green-600' : 'bg-blue-600 hover:bg-blue-700'} active:scale-95`}
        >
          {isSaved ? <CheckCircle2 size={20} /> : <Save size={20} />}
          {isSaved ? 'บันทึกสำเร็จ' : 'บันทึกการเช็คชื่อ'}
        </button>
      </div>

      {/* Student List */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {filteredStudents.length > 0 ? (
          filteredStudents.map((student, index) => (
            <div key={student.id} className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm hover:border-blue-400 transition-colors">
              <div className="flex items-start justify-between mb-4">
                <div className="flex gap-3">
                  <div className="w-12 h-12 bg-slate-900 rounded-xl flex items-center justify-center font-black text-white">
                    {index + 1}
                  </div>
                  <div>
                    <h4 className="font-black text-black">{student.name}</h4>
                    <p className="text-xs text-slate-800 font-bold uppercase tracking-wide">รหัส: {student.studentId}</p>
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-4 gap-2">
                {Object.entries(STATUS_LABELS).map(([key, value]) => (
                  <button
                    key={key}
                    onClick={() => handleStatusChange(student.id, key as AttendanceStatus)}
                    className={`
                      flex flex-col items-center gap-1 p-2 rounded-xl transition-all border
                      ${attendance[student.id] === key 
                        ? value.color + ' border-current scale-105 shadow-md ring-2 ring-blue-500 ring-offset-2' 
                        : 'bg-white border-slate-300 text-slate-800 grayscale hover:grayscale-0 hover:bg-slate-50'}
                    `}
                  >
                    {value.icon}
                    <span className="text-[10px] font-black uppercase">{value.label}</span>
                  </button>
                ))}
              </div>
            </div>
          ))
        ) : (
          <div className="col-span-full py-20 text-center text-slate-400 bg-white rounded-2xl border border-slate-200 shadow-inner">
            <Filter size={64} className="mx-auto mb-4 opacity-10" />
            <p className="text-xl font-black text-black">ไม่พบข้อมูลนักเรียน</p>
            <p className="text-slate-700 font-bold">กรุณาเลือก ระดับชั้น/ห้องเรียน ใหม่อีกครั้ง หรือเพิ่มข้อมูลใหม่</p>
          </div>
        )}
      </div>

      {/* Add Category Modal */}
      {showAddModal.type && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-sm rounded-[32px] overflow-hidden shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="p-8">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xl font-black text-black uppercase tracking-tight">
                  เพิ่ม{showAddModal.type === 'LEVEL' ? 'ระดับชั้น' : showAddModal.type === 'DEPT' ? 'แผนกวิชา' : 'ห้องเรียน'}
                </h3>
                <button 
                  onClick={() => setShowAddModal({ type: null })}
                  className="p-2 hover:bg-slate-100 rounded-full transition-colors"
                >
                  <X size={20} className="text-black" />
                </button>
              </div>

              <div className="space-y-4">
                <div className="space-y-2">
                  <label className="text-xs font-black text-black uppercase tracking-widest ml-1">ชื่อข้อมูลใหม่</label>
                  <input 
                    type="text"
                    autoFocus
                    value={newValue}
                    onChange={(e) => setNewValue(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleAddNew()}
                    placeholder={showAddModal.type === 'ROOM' ? "ระบุหมายเลขห้อง เช่น 4" : "พิมพ์ชื่อที่ต้องการเพิ่ม..."}
                    className="w-full bg-slate-50 border-2 border-slate-200 rounded-2xl px-5 py-4 outline-none focus:border-blue-600 focus:bg-white transition-all font-black text-black text-lg"
                  />
                </div>

                <div className="flex gap-3 pt-4">
                  <button 
                    onClick={() => setShowAddModal({ type: null })}
                    className="flex-1 py-4 font-black text-black bg-slate-100 hover:bg-slate-200 rounded-2xl transition-all border-2 border-slate-200 uppercase text-sm"
                  >
                    ยกเลิก
                  </button>
                  <button 
                    onClick={handleAddNew}
                    className="flex-1 py-4 font-black text-white bg-blue-600 hover:bg-blue-700 rounded-2xl transition-all shadow-lg shadow-blue-600/20 active:scale-95 uppercase text-sm"
                  >
                    เพิ่มข้อมูล
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

