import React, { useState } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import MorningAttendance from './components/MorningAttendance';
import ClassAttendance from './components/ClassAttendance';
import BehaviorSystem from './components/BehaviorSystem';
import StudentManagement from './components/StudentManagement';
import Login from './components/Login';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [activeMenu, setActiveMenu] = useState('dashboard');

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  const renderContent = () => {
    switch (activeMenu) {
      case 'dashboard':
        return <Dashboard />;
      case 'students':
        return <StudentManagement />;
      case 'morning':
        return <MorningAttendance />;
      case 'subject':
        return <ClassAttendance />;
      case 'behavior':
        return <BehaviorSystem />;
      case 'report':
        return (
          <div className="flex flex-col items-center justify-center py-20 text-slate-400 bg-white rounded-2xl border border-slate-200">
            <p className="text-xl font-black text-black mb-2 uppercase tracking-tighter">ระบบสรุปรายงาน</p>
            <p className="text-sm text-slate-700 font-bold">กำลังอยู่ในช่วงพัฒนา... ฟีเจอร์ส่งออก Excel/PDF</p>
          </div>
        );
      default:
        return <Dashboard />;
    }
  };

  return (
    <Layout 
      activeMenu={activeMenu} 
      setActiveMenu={setActiveMenu} 
      user={user}
      onLogout={() => setUser(null)}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { MOCK_STUDENTS } from '../data/mockData';
import { Student } from '../types';
import { 
  FileSpreadsheet, 
  Download, 
  Upload, 
  CheckCircle2, 
  AlertCircle, 
  Search, 
  Trash2, 
  UserPlus,
  Info
} from 'lucide-react';

const StudentManagement: React.FC = () => {
  const [students, setStudents] = useState<Student[]>(MOCK_STUDENTS);
  const [searchTerm, setSearchTerm] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const [importStatus, setImportStatus] = useState<null | 'success' | 'error'>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredStudents = students.filter(s => 
    s.name.includes(searchTerm) || s.studentId.includes(searchTerm)
  );

  const downloadTemplate = () => {
    const headers = "studentId,name,level,department,room\n";
    const example = "661007,นายมานะ อดทน,ปวช. 1,เทคโนโลยีสารสนเทศ,1\n661008,นางสาวชูใจ ใจดี,ปวช. 1,เทคโนโลยีสารสนเทศ,1";
    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" + headers + example;
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "student_template.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    setImportStatus(null);

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const lines = text.split('\n');
        const newStudents: Student[] = [];

        // Simple CSV parser logic
        for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;
          const [studentId, name, level, department, room] = line.split(',');

          if (studentId && name) {
            newStudents.push({
              id: (students.length + newStudents.length + 1).toString(),
              studentId,
              name,
              level: level || 'ปวช. 1',
              department: department || 'เทคโนโลยีสารสนเทศ',
              room: room || '1',
              behaviorScore: 100
            });
          }
        }

        if (newStudents.length > 0) {
          setStudents([...newStudents, ...students]);
          setImportStatus('success');
        } else {
          setImportStatus('error');
        }
      } catch (err) {
        setImportStatus('error');
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsText(file);
  };

  const deleteStudent = (id: string) => {
    if (window.confirm('คุณแน่ใจหรือไม่ว่าต้องการลบรายชื่อนักเรียนนี้?')) {
      setStudents(students.filter(s => s.id !== id));
    }
  };

  return (
    <div className="space-y-6">
      {/* Header with Import Actions */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm">
          <div className="flex items-center gap-3 mb-6">
            <div className="p-3 bg-blue-600 rounded-2xl text-white shadow-lg">
              <FileSpreadsheet size={24} />
            </div>
            <div>
              <h3 className="text-2xl font-black text-black tracking-tight uppercase">นำเข้าข้อมูลนักเรียน</h3>
              <p className="text-slate-800 font-bold text-sm tracking-tight">รองรับไฟล์ Excel (.csv) เพื่อเพิ่มรายชื่อนักเรียนจำนวนมาก</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="p-6 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200 flex flex-col items-center justify-center text-center space-y-4 hover:border-blue-400 hover:bg-blue-50 transition-all cursor-pointer group"
                 onClick={() => fileInputRef.current?.click()}>
              <input 
                type="file" 
                ref={fileInputRef} 
                className="hidden" 
                accept=".csv"
                onChange={handleFileUpload}
              />
              <div className="p-4 bg-white rounded-full shadow-md group-hover:scale-110 transition-transform">
                <Upload size={32} className="text-blue-600" />
              </div>
              <div>
                <p className="font-black text-black">คลิกเพื่ออัปโหลดไฟล์</p>
                <p className="text-xs text-slate-700 font-bold">นามสกุลไฟล์ที่รองรับ: .csv</p>
              </div>
            </div>

            <div className="flex flex-col justify-center space-y-4">
              <div className="bg-blue-50 p-4 rounded-2xl border border-blue-100">
                <div className="flex gap-2 text-blue-700 mb-2">
                  <Info size={18} />
                  <p className="text-xs font-black uppercase tracking-wider">คำแนะนำการใช้งาน</p>
                </div>
                <ul className="text-xs font-bold text-blue-800 space-y-1 list-disc ml-4">
                  <li>จัดเรียงลำดับคอลัมน์ตามเทมเพลต</li>
                  <li>ไฟล์ต้องเข้ารหัสเป็น UTF-8</li>
                  <li>ระบบจะเพิ่มนักเรียนเข้าสู่ระบบทันทีหลังอัปโหลด</li>
                </ul>
              </div>

              <button 
                onClick={downloadTemplate}
                className="w-full flex items-center justify-center gap-2 py-4 bg-slate-900 text-white rounded-2xl font-black hover:bg-black transition-all shadow-lg active:scale-95 uppercase text-sm tracking-wider"
              >
                <Download size={20} /> ดาวน์โหลดไฟล์เทมเพลต
              </button>
            </div>
          </div>

          {importStatus && (
            <div className={`mt-6 p-4 rounded-2xl flex items-center gap-3 animate-in fade-in slide-in-from-top-2 border ${
              importStatus === 'success' ? 'bg-green-50 border-green-200 text-green-800' : 'bg-red-50 border-red-200 text-red-800'
            }`}>
              {importStatus === 'success' ? <CheckCircle2 size={24} /> : <AlertCircle size={24} />}
              <div className="flex-1">
                <p className="font-black">
                  {importStatus === 'success' ? 'นำเข้าข้อมูลสำเร็จ!' : 'เกิดข้อผิดพลาดในการนำเข้าข้อมูล'}
                </p>
                <p className="text-xs font-bold">
                  {importStatus === 'success' ? 'ตรวจสอบรายชื่อที่เพิ่มเข้ามาในตารางด้านล่าง' : 'โปรดตรวจสอบรูปแบบไฟล์ให้ถูกต้องตามเทมเพลต'}
                </p>
              </div>
              <button onClick={() => setImportStatus(null)} className="p-2 hover:bg-white/50 rounded-lg">
                <Trash2 size={16} />
              </button>
            </div>
          )}
        </div>

        {/* Quick Summary Card */}
        <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm flex flex-col justify-between">
           <div>
              <h4 className="text-sm font-black text-black uppercase tracking-[0.2em] mb-4">สรุปรายชื่อล่าสุด</h4>
              <div className="space-y-4">
                <div className="flex justify-between items-end border-b-2 border-slate-100 pb-2">
                  <span className="text-xs font-bold text-slate-800">จำนวนนักเรียนทั้งหมด</span>
                  <span className="text-3xl font-black text-black">{students.length}</span>
                </div>
                <div className="flex justify-between items-end border-b-2 border-slate-100 pb-2">
                  <span className="text-xs font-bold text-slate-800">นักเรียนใหม่ (เดือนนี้)</span>
                  <span className="text-3xl font-black text-blue-600">+12</span>
                </div>
              </div>
           </div>
           <button className="w-full mt-8 py-4 bg-blue-100 text-blue-700 font-black rounded-2xl hover:bg-blue-200 transition-all border-2 border-blue-200 flex items-center justify-center gap-2 uppercase text-sm">
             <UserPlus size={18} /> เพิ่มรายบุคคล
           </button>
        </div>
      </div>

      {/* Student List Table */}
      <div className="bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-slate-200 flex flex-wrap items-center justify-between gap-4 bg-slate-50/50">
          <div className="flex items-center gap-2">
            <span className="font-black text-black text-xl uppercase tracking-tighter">รายชื่อนักเรียนในระบบ</span>
          </div>
          <div className="relative w-full md:w-80">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-black" size={18} />
            <input 
              type="text" 
              placeholder="ค้นหาชื่อ หรือ รหัสประจำตัว..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-white border-2 border-slate-200 rounded-2xl pl-12 pr-4 py-3 outline-none focus:border-blue-600 font-bold text-black text-sm"
            />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-100/50">
                <th className="px-8 py-5 text-xs font-black text-black uppercase tracking-widest">รหัสประจำตัว</th>
                <th className="px-8 py-5 text-xs font-black text-black uppercase tracking-widest">ชื่อ-นามสกุล</th>
                <th className="px-8 py-5 text-xs font-black text-black uppercase tracking-widest">ระดับชั้น</th>
                <th className="px-8 py-5 text-xs font-black text-black uppercase tracking-widest">แผนกวิชา / ห้อง</th>
