  const [showAddModal, setShowAddModal] = useState<{ type: 'LEVEL' | 'DEPT' | 'ROOM' | null }>({ type: null });
  const [newValue, setNewValue] = useState('');

  // Filter students based on selection
  const filteredStudents = MOCK_STUDENTS.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room &&
    (s.name.includes(searchTerm) || s.studentId.includes(searchTerm))
  );

  // Filter history based on selection
  const historyRecords = MOCK_ATTENDANCE.filter(record => {
    const student = MOCK_STUDENTS.find(s => s.id === record.studentId);
    return record.type === 'MORNING' && 
           student?.level === level && 
           student?.department === dept && 
           student?.room === room;
