import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import MorningAttendance from './components/MorningAttendance';
import ClassAttendance from './components/ClassAttendance';
import BehaviorSystem from './components/BehaviorSystem';
import StudentManagement from './components/StudentManagement';
import Reports from './components/Reports';
import Login from './components/Login';
import { MOCK_STUDENTS, MOCK_ATTENDANCE, MOCK_BEHAVIOR, MOCK_SUBJECTS } from './data/mockData';
import { Student, AttendanceRecord, BehaviorRecord } from './types';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [activeMenu, setActiveMenu] = useState('dashboard');

  // Central States
  const [students, setStudents] = useState<Student[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [behaviorRecords, setBehaviorRecords] = useState<BehaviorRecord[]>([]);
  const [subjects] = useState(MOCK_SUBJECTS);

  // Initialize data from LocalStorage or Mock
  useEffect(() => {
    const savedStudents = localStorage.getItem('cms_students');
    const savedAttendance = localStorage.getItem('cms_attendance');
    const savedBehavior = localStorage.getItem('cms_behavior');

    if (savedStudents) setStudents(JSON.parse(savedStudents));
    else setStudents(MOCK_STUDENTS);

    if (savedAttendance) setAttendance(JSON.parse(savedAttendance));
    else setAttendance(MOCK_ATTENDANCE);

    if (savedBehavior) setBehaviorRecords(JSON.parse(savedBehavior));
    else setBehaviorRecords(MOCK_BEHAVIOR);
  }, []);

  // Save to LocalStorage whenever state changes
  useEffect(() => {
    if (students.length > 0) localStorage.setItem('cms_students', JSON.stringify(students));
    localStorage.setItem('cms_attendance', JSON.stringify(attendance));
    localStorage.setItem('cms_behavior', JSON.stringify(behaviorRecords));
  }, [students, attendance, behaviorRecords]);

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  const renderContent = () => {
    switch (activeMenu) {
      case 'dashboard':
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} />;
      case 'students':
        return (
          <StudentManagement 
            students={students} 
            setStudents={setStudents} 
          />
        );
      case 'morning':
        return (
          <MorningAttendance 
            students={students} 
            attendanceRecords={attendance}
            setAttendanceRecords={setAttendance}
          />
        );
      case 'subject':
        return (
          <ClassAttendance 
            students={students} 
            subjects={subjects}
            attendanceRecords={attendance}
            setAttendanceRecords={setAttendance}
          />
        );
      case 'behavior':
        return (
          <BehaviorSystem 
            students={students} 
            setStudents={setStudents}
            behaviorRecords={behaviorRecords}
            setBehaviorRecords={setBehaviorRecords}
          />
        );
      case 'report':
        return (
          <Reports 
            students={students} 
            attendance={attendance} 
            behavior={behaviorRecords} 
          />
        );
      default:
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} />;
    }
  };

  return (
    <Layout 
      activeMenu={activeMenu} 
      setActiveMenu={setActiveMenu} 
      user={user}
      onLogout={() => setUser(null)}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import React from 'react';
import { 
  Users, 
  CheckCircle, 
  AlertTriangle, 
  TrendingUp,
  Award
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { Student, AttendanceRecord, BehaviorRecord } from '../types';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: BehaviorRecord[];
}

const StatCard = ({ title, value, sub, icon, color }: any) => (
  <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex items-start justify-between">
    <div>
      <p className="text-slate-800 text-sm font-bold mb-1">{title}</p>
      <h3 className="text-3xl font-black text-black">{value}</h3>
      <p className="text-xs text-slate-700 mt-2 flex items-center gap-1 font-medium">
        {sub}
      </p>
    </div>
    <div className={`p-3 rounded-xl ${color} text-white shadow-lg`}>
      {icon}
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ students, attendance, behavior }) => {
  // Real-time calculations
  const totalStudents = students.length;
  const today = new Date().toISOString().split('T')[0];
  const todayAttendance = attendance.filter(a => a.date === today && a.type === 'MORNING');
  const presentToday = todayAttendance.filter(a => a.status === 'PRESENT').length;
  const attendanceRate = todayAttendance.length > 0 ? Math.round((presentToday / todayAttendance.length) * 100) : 0;

  const avgBehavior = students.length > 0 
    ? Math.round(students.reduce((acc, s) => acc + s.behaviorScore, 0) / students.length)
    : 0;

  const chartData = [
    { name: 'จ.', count: 95 },
    { name: 'อ.', count: 92 },
    { name: 'พ.', count: 88 },
    { name: 'พฤ.', count: 94 },
    { name: 'ศ.', count: attendanceRate || 85 },
  ];

  const behaviorDist = [
    { name: 'ดีมาก (90+)', value: students.filter(s => s.behaviorScore >= 90).length, color: '#22c55e' },
    { name: 'ดี (70-89)', value: students.filter(s => s.behaviorScore >= 70 && s.behaviorScore < 90).length, color: '#3b82f6' },
    { name: 'พอใช้ (50-69)', value: students.filter(s => s.behaviorScore >= 50 && s.behaviorScore < 70).length, color: '#f59e0b' },
    { name: 'ปรับปรุง (<50)', value: students.filter(s => s.behaviorScore < 50).length, color: '#ef4444' },
  ];

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="นักเรียนทั้งหมด" 
          value={totalStudents} 
          sub="รายชื่อในระบบปัจจุบัน" 
          icon={<Users size={24} />} 
          color="bg-blue-600"
        />
        <StatCard 
          title="เช็คชื่อเช้านี้" 
          value={`${attendanceRate}%`} 
          sub={`มาเรียน ${presentToday} คน`} 
          icon={<CheckCircle size={24} />} 
          color="bg-green-600"
        />
        <StatCard 
          title="ต้องการติดตาม" 
          value={students.filter(s => s.behaviorScore < 60).length} 
          sub="คะแนนต่ำกว่าเกณฑ์" 
          icon={<AlertTriangle size={24} />} 
          color="bg-orange-600"
        />
        <StatCard 
          title="คะแนนเฉลี่ย" 
          value={avgBehavior} 
          sub="พฤติกรรมวิทยาลัย" 
          icon={<Award size={24} />} 
          color="bg-purple-600"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <div className="flex items-center justify-between mb-6">
            <h3 className="font-black text-black text-lg flex items-center gap-2">
              <TrendingUp size={20} className="text-blue-600" />
              สถิติการมาเรียนรายสัปดาห์ (%)
            </h3>
          </div>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#000', fontSize: 12, fontWeight: 'bold'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#000', fontSize: 12, fontWeight: 'bold'}} domain={[0, 100]} />
                <Tooltip cursor={{fill: '#f1f5f9'}} />
                <Bar dataKey="count" fill="#3b82f6" radius={[4, 4, 0, 0]} barSize={40} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <h3 className="font-black text-black text-lg mb-6 flex items-center gap-2">
            <Award size={20} className="text-purple-600" />
            การกระจายคะแนนพฤติกรรม
          </h3>
          <div className="h-[250px] w-full relative">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={behaviorDist} innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                  {behaviorDist.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
              <span className="text-2xl font-black text-black">{totalStudents}</span>
              <span className="text-xs text-slate-800 font-bold uppercase">คน</span>
            </div>
          </div>
          <div className="mt-4 space-y-2">
            {behaviorDist.map((item) => (
              <div key={item.name} className="flex items-center justify-between text-sm">
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 rounded-full" style={{backgroundColor: item.color}} />
                  <span className="text-slate-800 font-bold">{item.name}</span>
                </div>
                <span className="font-black text-black">{item.value} คน</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Student, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { Search, Save, CheckCircle2, Filter, Plus, X, History, ClipboardCheck, Calendar } from 'lucide-react';

interface MorningAttendanceProps {
  students: Student[];
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
}

const MorningAttendance: React.FC<MorningAttendanceProps> = ({ students, attendanceRecords, setAttendanceRecords }) => {
  const [levels, setLevels] = useState<string[]>(Object.values(ThaiLevel));
  const [depts, setDepts] = useState<string[]>(Object.values(Department));
  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);

  const [level, setLevel] = useState<string>(levels[0]);
  const [dept, setDept] = useState<string>(depts[0]);
  const [room, setRoom] = useState<string>(rooms[0]);

  const [searchTerm, setSearchTerm] = useState('');
  const [currentSession, setCurrentSession] = useState<Record<string, AttendanceStatus>>({});
  const [isSaved, setIsSaved] = useState(false);
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');

  const [showAddModal, setShowAddModal] = useState<{ type: 'LEVEL' | 'DEPT' | 'ROOM' | null }>({ type: null });
  const [newValue, setNewValue] = useState('');

  const filteredStudents = students.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room &&
    (s.name.includes(searchTerm) || s.studentId.includes(searchTerm))
  );

  const historyRecords = attendanceRecords.filter(record => {
    const student = students.find(s => s.id === record.studentId);
    return record.type === 'MORNING' && 
           student?.level === level && 
           student?.department === dept && 
           student?.room === room;
  }).sort((a, b) => b.date.localeCompare(a.date));

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setCurrentSession(prev => ({ ...prev, [studentId]: status }));
    setIsSaved(false);
  };

  const handleSave = () => {
    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    const newRecords: AttendanceRecord[] = Object.entries(currentSession).map(([studentId, status]) => ({
      id: `MORNING_${Date.now()}_${studentId}`,
      studentId,
      date: today,
      type: 'MORNING',
      status,
      timestamp
    }));

    setAttendanceRecords(prev => [...newRecords, ...prev]);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 3000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setCurrentSession(prev => ({ ...prev, ...newBatch }));
  };

  const handleAddNew = () => {
    if (!newValue.trim()) return;
    if (showAddModal.type === 'LEVEL') setLevels([...levels, newValue]);
    else if (showAddModal.type === 'DEPT') setDepts([...depts, newValue]);
    else if (showAddModal.type === 'ROOM') setRooms([...rooms, newValue]);
    setNewValue('');
    setShowAddModal({ type: null });
  };

  return (
    <div className="space-y-6">
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit">
        <button onClick={() => setViewMode('checkin')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-600 hover:bg-slate-50'}`}>
          <ClipboardCheck size={18} /> เช็คชื่อวันนี้
        </button>
        <button onClick={() => setViewMode('history')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-600 hover:bg-slate-50'}`}>
          <History size={18} /> ประวัติการเช็คชื่อ
        </button>
      </div>

      <div className="bg-white p-4 md:p-6 rounded-3xl border border-slate-200 shadow-sm relative">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="space-y-1">
            <div className="flex justify-between items-center">
              <label className="text-xs font-black text-black uppercase tracking-wider">ระดับชั้น</label>
              <button onClick={() => setShowAddModal({ type: 'LEVEL' })} className="p-1 hover:bg-blue-50 text-blue-600 rounded-md"><Plus size={14} /></button>
            </div>
            <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-300 rounded-xl px-3 py-2.5 font-bold text-black appearance-none">
              {levels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <div className="flex justify-between items-center">
              <label className="text-xs font-black text-black uppercase tracking-wider">แผนกวิชา</label>
              <button onClick={() => setShowAddModal({ type: 'DEPT' })} className="p-1 hover:bg-blue-50 text-blue-600 rounded-md"><Plus size={14} /></button>
            </div>
            <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border border-slate-300 rounded-xl px-3 py-2.5 font-bold text-black appearance-none">
              {depts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <div className="flex justify-between items-center">
              <label className="text-xs font-black text-black uppercase tracking-wider">ห้อง</label>
              <button onClick={() => setShowAddModal({ type: 'ROOM' })} className="p-1 hover:bg-blue-50 text-blue-600 rounded-md"><Plus size={14} /></button>
            </div>
            <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border border-slate-300 rounded-xl px-3 py-2.5 font-bold text-black appearance-none">
              {rooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
            </select>
          </div>
          <div className="space-y-1">
            <label className="text-xs font-black text-black uppercase tracking-wider">ค้นหาชื่อ/รหัส</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-900" size={18} />
              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อนักเรียน..." className="w-full bg-slate-50 border border-slate-300 rounded-xl pl-10 pr-3 py-2.5 font-bold text-black" />
            </div>
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <>
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div className="flex items-center gap-2">
              <span className="text-sm text-black font-black">ทางลัด:</span>
              <button onClick={() => markAll('PRESENT')} className="px-3 py-1 bg-green-100 text-green-800 rounded-lg text-xs font-black border border-green-300">มาทุกคน</button>
              <button onClick={() => markAll('ABSENT')} className="px-3 py-1 bg-red-100 text-red-800 rounded-lg text-xs font-black border border-red-300">ขาดทุกคน</button>
            </div>
            <button onClick={handleSave} disabled={filteredStudents.length === 0} className={`flex items-center gap-2 px-8 py-3 rounded-2xl text-white font-black transition-all shadow-xl ${isSaved ? 'bg-green-600' : 'bg-blue-600 hover:bg-blue-700'}`}>
              {isSaved ? <CheckCircle2 size={20} /> : <Save size={20} />} {isSaved ? 'บันทึกสำเร็จ' : 'บันทึกการเช็คชื่อ'}
            </button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
            {filteredStudents.length > 0 ? (
              filteredStudents.map((student, index) => (
                <div key={student.id} className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm hover:border-blue-400 transition-all group">
                  <div className="flex items-start justify-between mb-4">
                    <div className="flex gap-4">
                      <div className="w-12 h-12 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-white">{index + 1}</div>
                      <div>
                        <h4 className="font-black text-black text-lg leading-tight">{student.name}</h4>
                        <p className="text-xs text-slate-800 font-bold uppercase mt-1">รหัส: {student.studentId}</p>
                      </div>
                    </div>
                  </div>
                  <div className="grid grid-cols-4 gap-2">
                    {Object.entries(STATUS_LABELS).map(([key, value]) => (
                      <button key={key} onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} className={`flex flex-col items-center gap-1.5 p-2.5 rounded-2xl transition-all border ${currentSession[student.id] === key ? value.color + ' border-current scale-105 shadow-md ring-2 ring-blue-500 ring-offset-2' : 'bg-white border-slate-200 text-slate-800 grayscale hover:grayscale-0'}`}>
                        {value.icon} <span className="text-[10px] font-black uppercase tracking-tighter">{value.label}</span>
                      </button>
                    ))}
                  </div>
                </div>
              ))
            ) : (
              <div className="col-span-full py-24 text-center text-slate-400 bg-white rounded-[40px] border border-slate-200">
                <Filter size={64} className="mx-auto mb-6 opacity-10" />
                <p className="text-2xl font-black text-black">ไม่พบข้อมูลนักเรียน</p>
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
            <h3 className="font-black text-black text-xl flex items-center gap-2"><Calendar size={22} className="text-blue-600" /> ประวัติการเช็คชื่อ</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-100">
                  <th className="px-8 py-5 text-xs font-black text-slate-400 uppercase">วันที่</th>
                  <th className="px-8 py-5 text-xs font-black text-slate-400 uppercase">ชื่อนักเรียน</th>
                  <th className="px-8 py-5 text-xs font-black text-slate-400 uppercase">สถานะ</th>
                  <th className="px-8 py-5 text-xs font-black text-slate-400 uppercase">เวลาที่บันทึก</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {historyRecords.length > 0 ? (
                  historyRecords.map((record) => {
                    const student = students.find(s => s.id === record.studentId);
                    return (
                      <tr key={record.id} className="hover:bg-slate-50/80">
                        <td className="px-8 py-5 font-bold text-black">{record.date}</td>
                        <td className="px-8 py-5"><p className="font-black text-black">{student?.name}</p></td>
                        <td className="px-8 py-5">
                          <span className={`px-4 py-1.5 rounded-xl text-xs font-black border flex items-center gap-2 w-fit ${STATUS_LABELS[record.status].color}`}>
                            {STATUS_LABELS[record.status].label}
                          </span>
                        </td>
                        <td className="px-8 py-5 text-sm font-bold text-slate-700">{record.timestamp}</td>
                      </tr>
                    );
                  })
                ) : (
                  <tr><td colSpan={4} className="py-24 text-center text-slate-400">ไม่พบประวัติการเช็คชื่อ</td></tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {showAddModal.type && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white w-full max-w-sm rounded-[40px] p-10 shadow-2xl animate-in zoom-in-95">
            <h3 className="text-2xl font-black text-black mb-8 uppercase">เพิ่มข้อมูลใหม่</h3>
            <input type="text" autoFocus value={newValue} onChange={(e) => setNewValue(e.target.value)} className="w-full bg-slate-50 border-2 border-slate-200 rounded-2xl px-6 py-4 font-black text-black text-xl mb-6 outline-none focus:border-blue-600" />
            <div className="flex gap-4">
              <button onClick={() => setShowAddModal({ type: null })} className="flex-1 py-4 font-black bg-slate-100 rounded-2xl uppercase text-sm">ยกเลิก</button>
              <button onClick={handleAddNew} className="flex-1 py-4 font-black text-white bg-blue-600 rounded-2xl uppercase text-sm">ยืนยัน</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MorningAttendance;

import React, { useState, useRef } from 'react';
import { Student } from '../types';
import { 
  FileSpreadsheet, 
  Download, 
  Upload, 
  CheckCircle2, 
  AlertCircle, 
  Search, 
  Trash2, 
  UserPlus,
  Info
} from 'lucide-react';

interface StudentManagementProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
}

const StudentManagement: React.FC<StudentManagementProps> = ({ students, setStudents }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const [importStatus, setImportStatus] = useState<null | 'success' | 'error'>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredStudents = students.filter(s => 
    s.name.includes(searchTerm) || s.studentId.includes(searchTerm)
  );

  const downloadTemplate = () => {
    const headers = "studentId,name,level,department,room\n";
    const example = "661007,นายมานะ อดทน,ปวช. 1,เทคโนโลยีสารสนเทศ,1\n661008,นางสาวชูใจ ใจดี,ปวช. 1,เทคโนโลยีสารสนเทศ,1";
    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" + headers + example;
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "student_template.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const lines = text.split('\n');
        const newStudents: Student[] = [];

        for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;
          const [studentId, name, level, department, room] = line.split(',');

          if (studentId && name) {
            newStudents.push({
              id: `ID_${Date.now()}_${i}`,
              studentId,
              name,
              level: level || 'ปวช. 1',
              department: department || 'เทคโนโลยีสารสนเทศ',
              room: room || '1',
              behaviorScore: 100
            });
          }
        }

        if (newStudents.length > 0) {
          setStudents(prev => [...newStudents, ...prev]);
          setImportStatus('success');
        } else setImportStatus('error');
      } catch (err) { setImportStatus('error'); }
      finally { setIsImporting(false); if (fileInputRef.current) fileInputRef.current.value = ''; }
    };
    reader.readAsText(file);
  };

  const deleteStudent = (id: string) => {
    if (window.confirm('ยืนยันการลบรายชื่อนักเรียน?')) {
      setStudents(prev => prev.filter(s => s.id !== id));
    }
  };

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm">
          <div className="flex items-center gap-3 mb-6">
            <div className="p-3 bg-blue-600 rounded-2xl text-white"><FileSpreadsheet size={24} /></div>
            <div>
              <h3 className="text-2xl font-black text-black tracking-tight">นำเข้าข้อมูลนักเรียน</h3>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div onClick={() => fileInputRef.current?.click()} className="p-6 bg-slate-50 rounded-2xl border-2 border-dashed border-slate-200 flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 transition-all">
              <input type="file" ref={fileInputRef} className="hidden" accept=".csv" onChange={handleFileUpload} />
              <Upload size={32} className="text-blue-600 mb-2" />
