          <div className="flex-1 overflow-y-auto space-y-1">
            {filteredStudents.map(s => (
              <button key={s.id} onClick={() => setSelectedStudent(s)} className={`w-full text-left p-3 rounded-xl border transition-all ${selectedStudent?.id === s.id ? 'bg-blue-600 border-blue-700 text-white' : 'bg-white hover:bg-slate-50 text-black'}`}>
                <p className="font-black text-xs truncate">{s.name}</p>
                <p className="text-[10px] font-bold opacity-60">{s.studentId}</p>
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="lg:col-span-3 space-y-6">
        {selectedStudent ? (
          <>
            <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-slate-900 rounded-2xl flex items-center justify-center text-white"><User size={32} /></div>
                <div><h2 className="text-2xl font-black text-black leading-tight">{selectedStudent.name}</h2><p className="text-slate-600 font-bold uppercase text-xs tracking-widest">{selectedStudent.level} • {selectedStudent.department}</p></div>
              </div>
              <button onClick={exportToExcel} className="flex items-center gap-2 bg-green-600 text-white font-black px-6 py-3.5 rounded-2xl shadow-lg"><Download size={20} /> ส่งออก Excel</button>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="bg-white p-6 rounded-[24px] border shadow-sm flex items-center gap-4"><div className="p-4 bg-blue-100 text-blue-600 rounded-2xl"><BarChart3 size={24} /></div><div><p className="text-xs font-black uppercase">การมาเรียน</p><p className="text-3xl font-black text-black">{attendanceRate}%</p></div></div>
              <div className="bg-white p-6 rounded-[24px] border shadow-sm flex items-center gap-4"><div className="p-4 bg-purple-100 text-purple-600 rounded-2xl"><Award size={24} /></div><div><p className="text-xs font-black uppercase">คะแนนสะสม</p><p className="text-3xl font-black text-black">{selectedStudent.behaviorScore}</p></div></div>
              <div className="bg-white p-6 rounded-[24px] border shadow-sm flex items-center gap-4"><div className="p-4 bg-orange-100 text-orange-600 rounded-2xl"><Calendar size={24} /></div><div><p className="text-xs font-black uppercase">รายการเช็คชื่อ</p><p className="text-xl font-black text-black">{studentAttendance.length} รายการ</p></div></div>
            </div>
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
              <div className="bg-white rounded-[24px] border overflow-hidden">
                <div className="p-5 bg-slate-50 border-b flex items-center gap-2"><TrendingUp size={18} className="text-blue-600" /><h4 className="font-black text-black uppercase">ประวัติการมาเรียน</h4></div>
                <div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead><tr className="border-b"><th className="px-5 py-3 font-black text-slate-400 text-[10px]">วันที่</th><th className="px-5 py-3 font-black text-slate-400 text-[10px]">สถานะ</th></tr></thead><tbody>{studentAttendance.map(a => (<tr key={a.id} className="border-b"><td className="px-5 py-3 font-bold">{a.date}</td><td className="px-5 py-3"><span className={`px-2 py-0.5 rounded-lg text-[10px] font-black ${STATUS_LABELS[a.status].color}`}>{STATUS_LABELS[a.status].label}</span></td></tr>))}</tbody></table></div>
              </div>
              <div className="bg-white rounded-[24px] border overflow-hidden">
                <div className="p-5 bg-slate-50 border-b flex items-center gap-2"><Award size={18} className="text-purple-600" /><h4 className="font-black text-black uppercase">ประวัติพฤติกรรม</h4></div>
                <div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead><tr className="border-b"><th className="px-5 py-3 font-black text-slate-400 text-[10px]">วันที่</th><th className="px-5 py-3 font-black text-slate-400 text-[10px]">เหตุผล</th><th className="px-5 py-3 font-black text-slate-400 text-[10px] text-center">+/-</th></tr></thead><tbody>{studentBehavior.map(b => (<tr key={b.id} className="border-b"><td className="px-5 py-3 font-bold">{b.date}</td><td className="px-5 py-3 font-black">{b.reason}</td><td className={`px-5 py-3 text-center font-black ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>{b.type === 'ADD' ? '+' : '-'}{b.score}</td></tr>))}</tbody></table></div>
              </div>
            </div>
          </>
        ) : (
          <div className="h-[calc(100vh-140px)] bg-white rounded-[32px] border flex flex-col items-center justify-center p-20 text-center"><FileText size={48} className="opacity-10 mb-4" /><h3 className="text-2xl font-black text-black mb-2">ยังไม่ได้เลือกนักเรียน</h3></div>
        )}
      </div>
    </div>
  );
};

