              ))
            ) : (
              <div className="col-span-full py-32 text-center text-slate-400 bg-white rounded-[40px] border border-slate-200 border-dashed">
                <Filter size={64} className="mx-auto mb-6 opacity-5" />
                <p className="text-2xl font-black text-slate-900">ไม่พบคลาสเรียนที่ต้องการ</p>
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-300">
          <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/30">
            <h3 className="font-black text-slate-900 text-2xl flex items-center gap-4">
              <Calendar size={28} className="text-blue-600" /> 
              สมุดบันทึกย้อนหลัง
            </h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-100">
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">วันที่</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">นักเรียน</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">สถานะ</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">หมายเหตุ</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">เวลาที่บันทึก</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {historyRecords.length > 0 ? (
                  historyRecords.map((record) => {
                    const student = students.find(s => s.id === record.studentId);
                    return (
                      <tr key={record.id} className="hover:bg-slate-50/80 transition-colors">
                        <td className="px-10 py-6 font-extrabold text-slate-900 text-lg">{record.date}</td>
                        <td className="px-10 py-6">
                          <p className="font-black text-slate-900 text-lg">{student?.name}</p>
                          <p className="text-xs text-slate-500 font-bold uppercase">{student?.studentId}</p>
                        </td>
                        <td className="px-10 py-6">
                          <span className={`px-6 py-2 rounded-full text-xs font-black border flex items-center gap-2 w-fit ${STATUS_LABELS[record.status].color}`}>
                            {STATUS_LABELS[record.status].label}
                          </span>
                        </td>
                        <td className="px-10 py-6">
                          <p className="text-sm font-bold text-slate-900">{record.remark || '-'}</p>
                        </td>
                        <td className="px-10 py-6 text-sm font-bold text-slate-600">{record.timestamp}</td>
                      </tr>
                    );
                  })
                ) : (
                  <tr>
                    <td colSpan={5} className="py-32 text-center text-slate-400">
                      <History size={64} className="mx-auto mb-6 opacity-5" />
                      <p className="text-2xl font-black text-slate-900">ยังไม่มีข้อมูลในระบบ</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {showAddModal.type && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-md">
          <div className="bg-white w-full max-w-md rounded-[48px] p-12 shadow-2xl animate-in zoom-in-95 duration-300">
            <h3 className="text-3xl font-black text-slate-900 mb-10 text-center uppercase tracking-tight">เพิ่มรายการใหม่</h3>
            <input 
              type="text" 
              autoFocus 
              value={newValue} 
              onChange={(e) => setNewValue(e.target.value)} 
              className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-6 font-black text-slate-900 text-2xl mb-10 outline-none transition-all placeholder:text-slate-300"
              placeholder="ระบุข้อความที่นี่..."
            />
            <div className="flex gap-6">
              <button onClick={() => setShowAddModal({ type: null })} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-sm tracking-widest hover:bg-slate-200 transition-colors">ยกเลิก</button>
              <button onClick={handleAddNew} className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-sm tracking-widest hover:bg-blue-700 transition-colors">ตกลง</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MorningAttendance;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import MorningAttendance from './components/MorningAttendance';
import ClassAttendance from './components/ClassAttendance';
import BehaviorSystem from './components/BehaviorSystem';
import StudentManagement from './components/StudentManagement';
import Reports from './components/Reports';
import Login from './components/Login';
import { MOCK_STUDENTS, MOCK_ATTENDANCE, MOCK_BEHAVIOR, MOCK_SUBJECTS } from './data/mockData';
import { Student, AttendanceRecord, BehaviorRecord } from './types';

const App: React.FC = () => {
  const [user, setUser] = useState<any>(null);
  const [activeMenu, setActiveMenu] = useState('dashboard');

  // Central States
  const [students, setStudents] = useState<Student[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [behaviorRecords, setBehaviorRecords] = useState<BehaviorRecord[]>([]);
  const [subjects] = useState(MOCK_SUBJECTS);

  // Initialize data from LocalStorage or Mock
  useEffect(() => {
    const savedStudents = localStorage.getItem('cms_students');
    const savedAttendance = localStorage.getItem('cms_attendance');
    const savedBehavior = localStorage.getItem('cms_behavior');

    if (savedStudents) setStudents(JSON.parse(savedStudents));
    else setStudents(MOCK_STUDENTS);

    if (savedAttendance) setAttendance(JSON.parse(savedAttendance));
    else setAttendance(MOCK_ATTENDANCE);

    if (savedBehavior) setBehaviorRecords(JSON.parse(savedBehavior));
    else setBehaviorRecords(MOCK_BEHAVIOR);
  }, []);

  // Save to LocalStorage whenever state changes
  useEffect(() => {
    if (students.length > 0) localStorage.setItem('cms_students', JSON.stringify(students));
    localStorage.setItem('cms_attendance', JSON.stringify(attendance));
    localStorage.setItem('cms_behavior', JSON.stringify(behaviorRecords));
  }, [students, attendance, behaviorRecords]);

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  const renderContent = () => {
    switch (activeMenu) {
      case 'dashboard':
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} />;
      case 'students':
        return (
          <StudentManagement 
            students={students} 
            setStudents={setStudents} 
          />
        );
      case 'morning':
        return (
          <MorningAttendance 
            students={students} 
            setStudents={setStudents}
            attendanceRecords={attendance}
            setAttendanceRecords={setAttendance}
          />
        );
      case 'subject':
        return (
          <ClassAttendance 
            students={students} 
            setStudents={setStudents}
            subjects={subjects}
            attendanceRecords={attendance}
            setAttendanceRecords={setAttendance}
          />
        );
      case 'behavior':
        return (
          <BehaviorSystem 
            students={students} 
            setStudents={setStudents}
            behaviorRecords={behaviorRecords}
            setBehaviorRecords={setBehaviorRecords}
          />
        );
      case 'report':
        return (
          <Reports 
            students={students} 
            attendance={attendance} 
            behavior={behaviorRecords} 
          />
        );
      default:
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} />;
    }
  };

  return (
    <Layout 
      activeMenu={activeMenu} 
      setActiveMenu={setActiveMenu} 
      user={user}
      onLogout={() => setUser(null)}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Student, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { Search, Save, CheckCircle2, Filter, Plus, X, History, ClipboardCheck, Calendar, MessageSquare, Clock, UserPlus } from 'lucide-react';

interface MorningAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
}

const MorningAttendance: React.FC<MorningAttendanceProps> = ({ students, setStudents, attendanceRecords, setAttendanceRecords }) => {
  const [levels, setLevels] = useState<string[]>(Object.values(ThaiLevel));
  const [depts, setDepts] = useState<string[]>(Object.values(Department));
  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);

  const [level, setLevel] = useState<string>(levels[0]);
  const [dept, setDept] = useState<string>(depts[0]);
  const [room, setRoom] = useState<string>(rooms[0]);

  const [searchTerm, setSearchTerm] = useState('');
  const [currentSession, setCurrentSession] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');
  const [currentTime, setCurrentTime] = useState(new Date());

  const [showAddModal, setShowAddModal] = useState<{ type: 'LEVEL' | 'DEPT' | 'ROOM' | 'STUDENT' | null }>({ type: null });
  const [newValue, setNewValue] = useState('');
  const [newStudent, setNewStudent] = useState({ studentId: '', name: '' });

  // Update clock every second
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const filteredStudents = students.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room &&
    (s.name.includes(searchTerm) || s.studentId.includes(searchTerm))
  );

  const historyRecords = attendanceRecords.filter(record => {
    const student = students.find(s => s.id === record.studentId);
    return record.type === 'MORNING' && 
           student?.level === level && 
           student?.department === dept && 
           student?.room === room;
  }).sort((a, b) => b.date.localeCompare(a.date));

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setCurrentSession(prev => ({ ...prev, [studentId]: status }));
    setIsSaved(false);
    // Clear remark if status is PRESENT
    if (status === 'PRESENT') {
      setRemarks(prev => {
        const next = { ...prev };
        delete next[studentId];
        return next;
      });
    }
  };

  const handleRemarkChange = (studentId: string, text: string) => {
    setRemarks(prev => ({ ...prev, [studentId]: text }));
  };

  const handleSave = () => {
    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    const newRecords: AttendanceRecord[] = Object.entries(currentSession).map(([studentId, status]) => ({
      id: `MORNING_${Date.now()}_${studentId}`,
      studentId,
      date: today,
      type: 'MORNING' as const,
      status: status as AttendanceStatus,
      remark: remarks[studentId] || '',
      timestamp
    }));

    setAttendanceRecords(prev => [...newRecords, ...prev]);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 3000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setCurrentSession(prev => ({ ...prev, ...newBatch }));
    if (status === 'PRESENT') setRemarks({});
  };

  const handleAddNew = () => {
    if (showAddModal.type === 'STUDENT') {
      if (!newStudent.studentId || !newStudent.name) return;
      const student: Student = {
        id: `STU_${Date.now()}`,
        studentId: newStudent.studentId,
        name: newStudent.name,
        level: level,
        department: dept,
        room: room,
        behaviorScore: 100
      };
      setStudents(prev => [...prev, student]);
      setNewStudent({ studentId: '', name: '' });
      setShowAddModal({ type: null });
      return;
    }

    if (!newValue.trim()) return;
    if (showAddModal.type === 'LEVEL') setLevels([...levels, newValue]);
    else if (showAddModal.type === 'DEPT') setDepts([...depts, newValue]);
    else if (showAddModal.type === 'ROOM') setRooms([...rooms, newValue]);
    setNewValue('');
    setShowAddModal({ type: null });
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex bg-white p-2 rounded-[24px] border border-slate-200 shadow-sm w-fit">
        <button 
          onClick={() => setViewMode('checkin')} 
          className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <ClipboardCheck size={20} /> เช็คชื่อวันนี้
        </button>
        <button 
          onClick={() => setViewMode('history')} 
          className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <History size={20} /> ประวัติย้อนหลัง
        </button>
      </div>

      <div className="bg-white p-6 md:p-8 rounded-[40px] border border-slate-200 shadow-sm">
        <div className="flex flex-col md:flex-row gap-8">
          <div className="flex-1 grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">ระดับชั้น</label>
                <button onClick={() => setShowAddModal({ type: 'LEVEL' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {levels.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">แผนกวิชา</label>
                <button onClick={() => setShowAddModal({ type: 'DEPT' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {depts.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">ห้องเรียน</label>
                <button onClick={() => setShowAddModal({ type: 'ROOM' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {rooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest ml-1">ค้นหารายชื่อ</label>
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อ-รหัส..." className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl pl-12 pr-4 py-3 font-bold text-slate-900 outline-none" />
              </div>
            </div>
          </div>

          {/* Clock Display */}
          <div className="w-full md:w-64 bg-slate-900 p-6 rounded-[32px] border border-slate-800 flex flex-col justify-center shadow-xl">
            <div className="flex items-center gap-2 text-blue-400 mb-2">
              <Clock size={18} />
              <span className="text-[10px] font-black uppercase tracking-[0.2em]">เวลาปัจจุบัน</span>
            </div>
            <p className="text-4xl font-black text-white tabular-nums tracking-tighter">
              {currentTime.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
            </p>
            <p className="text-sm text-slate-400 font-bold mt-1">
              {currentTime.toLocaleDateString('th-TH', { dateStyle: 'long' })}
            </p>
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <>
          <div className="flex flex-wrap items-center justify-between gap-6 px-2">
            <div className="flex items-center gap-3">
              <span className="text-sm text-slate-500 font-black uppercase tracking-wider">เช็คชื่อด่วน:</span>
              <button onClick={() => markAll('PRESENT')} className="px-5 py-2 bg-green-50 text-green-700 rounded-full text-xs font-black border-2 border-green-200 hover:bg-green-100 transition-all">มาทุกคน</button>
              <button onClick={() => markAll('ABSENT')} className="px-5 py-2 bg-red-50 text-red-700 rounded-full text-xs font-black border-2 border-red-200 hover:bg-red-100 transition-all">ขาดทุกคน</button>
              <button 
                onClick={() => setShowAddModal({ type: 'STUDENT' })}
                className="flex items-center gap-2 px-5 py-2 bg-blue-50 text-blue-700 rounded-full text-xs font-black border-2 border-blue-200 hover:bg-blue-100 transition-all"
              >
                <UserPlus size={14} /> เพิ่มนักเรียนรายคน
              </button>
            </div>
            <button 
              onClick={handleSave} 
              disabled={filteredStudents.length === 0} 
              className={`flex items-center gap-3 px-10 py-4 rounded-2xl text-white font-black transition-all shadow-xl hover:-translate-y-1 active:translate-y-0 ${isSaved ? 'bg-green-600 shadow-green-200' : 'bg-slate-900 shadow-slate-200'}`}
            >
              {isSaved ? <CheckCircle2 size={24} /> : <Save size={24} />} 
              <span className="text-lg">{isSaved ? 'บันทึกเรียบร้อย' : 'บันทึกข้อมูลวันนี้'}</span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-2 gap-6">
            {filteredStudents.length > 0 ? (
              filteredStudents.map((student, index) => (
                <div key={student.id} className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm hover:border-blue-300 transition-all group flex flex-col justify-between">
                  <div className="flex flex-col md:flex-row md:items-start justify-between gap-5 mb-6">
                    <div className="flex items-start gap-4">
                      <div className="w-14 h-14 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-lg group-hover:bg-blue-600 transition-colors shrink-0">
                        {index + 1}
                      </div>
                      <div>
                        <h4 className="font-black text-slate-900 text-xl leading-tight">{student.name}</h4>
                        <p className="text-xs text-slate-500 font-extrabold uppercase mt-1.5 tracking-widest">รหัส: {student.studentId}</p>
                      </div>
                    </div>
                    {/* Status selection buttons */}
                    <div className="grid grid-cols-5 gap-2 w-full md:w-auto">
                      {Object.entries(STATUS_LABELS).map(([key, value]) => (
                        <button 
                          key={key} 
                          onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} 
                          className={`flex flex-col items-center gap-1.5 p-2 rounded-xl transition-all border-2 ${currentSession[student.id] === key ? value.color + ' border-current scale-105 shadow-md ring-4 ring-blue-500/10' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-300'}`}
                          title={value.label}
                        >
                          <div className="scale-125">{value.icon}</div>
                          <span className="text-[10px] font-black uppercase text-center">{value.label}</span>
                        </button>
                      ))}
                    </div>
                  </div>

                  {/* Remark field for non-present status */}
                  {currentSession[student.id] && currentSession[student.id] !== 'PRESENT' && (
                    <div className="mt-2 animate-in slide-in-from-top-2">
                      <div className="relative">
                        <MessageSquare className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                        <input 
                          type="text"
                          value={remarks[student.id] || ''}
                          onChange={(e) => handleRemarkChange(student.id, e.target.value)}
                          placeholder={`ระบุสาเหตุที่${STATUS_LABELS[currentSession[student.id]].label}...`}
                          className="w-full bg-slate-50 border-2 border-slate-200 focus:border-blue-400 rounded-xl pl-11 pr-4 py-3 font-bold text-slate-900 outline-none text-sm"
                        />
                      </div>
                    </div>
                  )}
                </div>
              ))
            ) : (
              <div className="col-span-full py-32 text-center text-slate-400 bg-white rounded-[40px] border border-slate-200 border-dashed">
                <Filter size={64} className="mx-auto mb-6 opacity-5" />
                <p className="text-2xl font-black text-slate-900">ไม่พบคลาสเรียนที่ต้องการ</p>
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-300">
          <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/30">
            <h3 className="font-black text-slate-900 text-2xl flex items-center gap-4">
              <Calendar size={28} className="text-blue-600" /> 
              สมุดบันทึกย้อนหลัง
            </h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-100">
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">วันที่</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">นักเรียน</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">สถานะ</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">หมายเหตุ</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">เวลาที่บันทึก</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {historyRecords.length > 0 ? (
                  historyRecords.map((record) => {
                    const student = students.find(s => s.id === record.studentId);
                    return (
                      <tr key={record.id} className="hover:bg-slate-50/80 transition-colors">
                        <td className="px-10 py-6 font-extrabold text-slate-900 text-lg">{record.date}</td>
                        <td className="px-10 py-6">
                          <p className="font-black text-slate-900 text-lg">{student?.name}</p>
                          <p className="text-xs text-slate-500 font-bold uppercase">{student?.studentId}</p>
                        </td>
                        <td className="px-10 py-6">
                          <span className={`px-6 py-2 rounded-full text-xs font-black border flex items-center gap-2 w-fit ${STATUS_LABELS[record.status].color}`}>
                            {STATUS_LABELS[record.status].label}
                          </span>
                        </td>
                        <td className="px-10 py-6">
                          <p className="text-sm font-bold text-slate-900">{record.remark || '-'}</p>
                        </td>
                        <td className="px-10 py-6 text-sm font-bold text-slate-600">{record.timestamp}</td>
                      </tr>
                    );
                  })
