  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setCurrentSession(prev => ({ ...prev, ...newBatch }));
    if (status === 'PRESENT') setRemarks({});
  };

  const handleAddNew = () => {
    if (showAddModal.type === 'STUDENT') {
      if (!newStudent.studentId || !newStudent.name) return;
      const student: Student = {
        id: `STU_${Date.now()}`,
        studentId: newStudent.studentId,
        name: newStudent.name,
        level: level,
        department: dept,
        room: room,
        behaviorScore: 100
      };
      setStudents(prev => [...prev, student]);
      setNewStudent({ studentId: '', name: '' });
      setShowAddModal({ type: null });
      return;
    }

    if (!newValue.trim()) return;
    if (showAddModal.type === 'LEVEL') setLevels([...levels, newValue]);
    else if (showAddModal.type === 'DEPT') setDepts([...depts, newValue]);
    else if (showAddModal.type === 'ROOM') setRooms([...rooms, newValue]);
    setNewValue('');
    setShowAddModal({ type: null });
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex bg-white p-2 rounded-[24px] border border-slate-200 shadow-sm w-fit">
        <button 
          onClick={() => setViewMode('checkin')} 
          className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <ClipboardCheck size={20} /> เช็คชื่อวันนี้
        </button>
        <button 
          onClick={() => setViewMode('history')} 
          className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <History size={20} /> ประวัติย้อนหลัง
        </button>
      </div>

      <div className="bg-white p-6 md:p-8 rounded-[40px] border border-slate-200 shadow-sm">
        <div className="flex flex-col md:flex-row gap-8">
          <div className="flex-1 grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">ระดับชั้น</label>
                <button onClick={() => setShowAddModal({ type: 'LEVEL' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {levels.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">แผนกวิชา</label>
                <button onClick={() => setShowAddModal({ type: 'DEPT' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {depts.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">ห้องเรียน</label>
                <button onClick={() => setShowAddModal({ type: 'ROOM' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {rooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest ml-1">ค้นหารายชื่อ</label>
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อ-รหัส..." className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl pl-12 pr-4 py-3 font-bold text-slate-900 outline-none" />
              </div>
            </div>
          </div>

          {/* Clock Display */}
          <div className="w-full md:w-64 bg-slate-900 p-6 rounded-[32px] border border-slate-800 flex flex-col justify-center shadow-xl">
            <div className="flex items-center gap-2 text-blue-400 mb-2">
              <Clock size={18} />
              <span className="text-[10px] font-black uppercase tracking-[0.2em]">เวลาปัจจุบัน</span>
            </div>
            <p className="text-4xl font-black text-white tabular-nums tracking-tighter">
              {currentTime.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
            </p>
            <p className="text-sm text-slate-400 font-bold mt-1">
              {currentTime.toLocaleDateString('th-TH', { dateStyle: 'long' })}
            </p>
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <>
          <div className="flex flex-wrap items-center justify-between gap-6 px-2">
            <div className="flex items-center gap-3">
              <span className="text-sm text-slate-500 font-black uppercase tracking-wider">เช็คชื่อด่วน:</span>
              <button onClick={() => markAll('PRESENT')} className="px-5 py-2 bg-green-50 text-green-700 rounded-full text-xs font-black border-2 border-green-200 hover:bg-green-100 transition-all">มาทุกคน</button>
              <button onClick={() => markAll('ABSENT')} className="px-5 py-2 bg-red-50 text-red-700 rounded-full text-xs font-black border-2 border-red-200 hover:bg-red-100 transition-all">ขาดทุกคน</button>
              <button 
                onClick={() => setShowAddModal({ type: 'STUDENT' })}
                className="flex items-center gap-2 px-5 py-2 bg-blue-50 text-blue-700 rounded-full text-xs font-black border-2 border-blue-200 hover:bg-blue-100 transition-all"
              >
                <UserPlus size={14} /> เพิ่มนักเรียนรายคน
              </button>
            </div>
            <button 
              onClick={handleSave} 
              disabled={filteredStudents.length === 0} 
              className={`flex items-center gap-3 px-10 py-4 rounded-2xl text-white font-black transition-all shadow-xl hover:-translate-y-1 active:translate-y-0 ${isSaved ? 'bg-green-600 shadow-green-200' : 'bg-slate-900 shadow-slate-200'}`}
            >
              {isSaved ? <CheckCircle2 size={24} /> : <Save size={24} />} 
              <span className="text-lg">{isSaved ? 'บันทึกเรียบร้อย' : 'บันทึกข้อมูลวันนี้'}</span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-2 gap-6">
            {filteredStudents.length > 0 ? (
              filteredStudents.map((student, index) => (
                <div key={student.id} className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm hover:border-blue-300 transition-all group flex flex-col justify-between">
                  <div className="flex flex-col md:flex-row md:items-start justify-between gap-5 mb-6">
                    <div className="flex items-start gap-4">
                      <div className="w-14 h-14 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-lg group-hover:bg-blue-600 transition-colors shrink-0">
                        {index + 1}
                      </div>
                      <div>
                        <h4 className="font-black text-slate-900 text-xl leading-tight">{student.name}</h4>
                        <p className="text-xs text-slate-500 font-extrabold uppercase mt-1.5 tracking-widest">รหัส: {student.studentId}</p>
                      </div>
                    </div>
                    {/* Status selection buttons */}
                    <div className="grid grid-cols-5 gap-2 w-full md:w-auto">
                      {Object.entries(STATUS_LABELS).map(([key, value]) => (
                        <button 
                          key={key} 
                          onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} 
                          className={`flex flex-col items-center gap-1.5 p-2 rounded-xl transition-all border-2 ${currentSession[student.id] === key ? value.color + ' border-current scale-105 shadow-md ring-4 ring-blue-500/10' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-300'}`}
                          title={value.label}
                        >
                          <div className="scale-125">{value.icon}</div>
                          <span className="text-[10px] font-black uppercase text-center">{value.label}</span>
                        </button>
                      ))}
                    </div>
                  </div>

                  {/* Remark field for non-present status */}
                  {currentSession[student.id] && currentSession[student.id] !== 'PRESENT' && (
                    <div className="mt-2 animate-in slide-in-from-top-2">
                      <div className="relative">
                        <MessageSquare className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                        <input 
                          type="text"
                          value={remarks[student.id] || ''}
                          onChange={(e) => handleRemarkChange(student.id, e.target.value)}
                          placeholder={`ระบุสาเหตุที่${STATUS_LABELS[currentSession[student.id]].label}...`}
                          className="w-full bg-slate-50 border-2 border-slate-200 focus:border-blue-400 rounded-xl pl-11 pr-4 py-3 font-bold text-slate-900 outline-none text-sm"
                        />
                      </div>
                    </div>
                  )}
                </div>
              ))
            ) : (
              <div className="col-span-full py-32 text-center text-slate-400 bg-white rounded-[40px] border border-slate-200 border-dashed">
                <Filter size={64} className="mx-auto mb-6 opacity-5" />
                <p className="text-2xl font-black text-slate-900">ไม่พบคลาสเรียนที่ต้องการ</p>
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-300">
          <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/30">
            <h3 className="font-black text-slate-900 text-2xl flex items-center gap-4">
              <Calendar size={28} className="text-blue-600" /> 
              สมุดบันทึกย้อนหลัง
            </h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-100">
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">วันที่</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">นักเรียน</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">สถานะ</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">หมายเหตุ</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">เวลาที่บันทึก</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {historyRecords.length > 0 ? (
                  historyRecords.map((record) => {
                    const student = students.find(s => s.id === record.studentId);
                    return (
                      <tr key={record.id} className="hover:bg-slate-50/80 transition-colors">
                        <td className="px-10 py-6 font-extrabold text-slate-900 text-lg">{record.date}</td>
                        <td className="px-10 py-6">
                          <p className="font-black text-slate-900 text-lg">{student?.name}</p>
                          <p className="text-xs text-slate-500 font-bold uppercase">{student?.studentId}</p>
                        </td>
                        <td className="px-10 py-6">
                          <span className={`px-6 py-2 rounded-full text-xs font-black border flex items-center gap-2 w-fit ${STATUS_LABELS[record.status].color}`}>
                            {STATUS_LABELS[record.status].label}
                          </span>
                        </td>
                        <td className="px-10 py-6">
                          <p className="text-sm font-bold text-slate-900">{record.remark || '-'}</p>
                        </td>
                        <td className="px-10 py-6 text-sm font-bold text-slate-600">{record.timestamp}</td>
                      </tr>
                    );
                  })
                ) : (
                  <tr>
                    <td colSpan={5} className="py-32 text-center text-slate-400">
                      <History size={64} className="mx-auto mb-6 opacity-5" />
                      <p className="text-2xl font-black text-slate-900">ยังไม่มีข้อมูลในระบบ</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {showAddModal.type && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-md">
          <div className="bg-white w-full max-w-md rounded-[48px] p-12 shadow-2xl animate-in zoom-in-95 duration-300">
            {showAddModal.type === 'STUDENT' ? (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-2 text-center uppercase tracking-tight">เพิ่มนักเรียนใหม่</h3>
                <p className="text-center text-slate-500 font-bold mb-8">{level} {dept} ห้อง {room}</p>
                <div className="space-y-4 mb-10">
                  <div className="space-y-1">
                    <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">รหัสประจำตัว</label>
                    <input 
                      type="text" 
                      value={newStudent.studentId} 
                      onChange={(e) => setNewStudent({...newStudent, studentId: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[24px] px-6 py-4 font-black text-slate-900 text-xl outline-none"
                      placeholder="เช่น 661001"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ-นามสกุล</label>
                    <input 
                      type="text" 
                      value={newStudent.name} 
                      onChange={(e) => setNewStudent({...newStudent, name: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[24px] px-6 py-4 font-black text-slate-900 text-xl outline-none"
                      placeholder="นายสมมติ นามสกุล"
                    />
                  </div>
                </div>
              </>
            ) : (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-10 text-center uppercase tracking-tight">เพิ่มรายการใหม่</h3>
                <input 
                  type="text" 
                  autoFocus 
                  value={newValue} 
                  onChange={(e) => setNewValue(e.target.value)} 
                  className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-6 font-black text-slate-900 text-2xl mb-10 outline-none transition-all placeholder:text-slate-300"
                  placeholder="ระบุข้อความที่นี่..."
                />
              </>
            )}
            <div className="flex gap-6">
              <button onClick={() => setShowAddModal({ type: null })} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-sm tracking-widest hover:bg-slate-200 transition-colors">ยกเลิก</button>
              <button onClick={handleAddNew} className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-sm tracking-widest hover:bg-blue-700 transition-colors">ตกลง</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MorningAttendance;

import React, { useState } from 'react';
import { Student, Subject, AttendanceRecord, AttendanceStatus } from '../types';
import { STATUS_LABELS } from '../constants';
import { Save, BookOpen, Clock, Users, MessageSquare, UserPlus, X, Plus } from 'lucide-react';

interface ClassAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  subjects: Subject[];
  setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  currentUser: any;
}

const ClassAttendance: React.FC<ClassAttendanceProps> = ({ 
  students: allStudents, 
  setStudents,
  subjects, 
  setSubjects,
  rooms,
  setRooms,
  attendanceRecords, 
  setAttendanceRecords,
  currentUser
}) => {
  const [subjectId, setSubjectId] = useState(subjects.length > 0 ? subjects[0].id : '');
  const [room, setRoom] = useState(rooms.length > 0 ? rooms[0] : '1');
  const [sessionAttendance, setSessionAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);

  const [showAddModal, setShowAddModal] = useState<'STUDENT' | 'SUBJECT' | 'ROOM' | null>(null);
  const [newStudent, setNewStudent] = useState({ studentId: '', name: '' });
  const [newSubject, setNewSubject] = useState({ code: '', name: '' });
  const [newRoomValue, setNewRoomValue] = useState('');

  const students = allStudents.filter(s => s.room === room);

  // Try to find the most common level/dept in this room to prepopulate
  const currentRoomStudents = allStudents.filter(s => s.room === room);
  const guessedLevel = currentRoomStudents.length > 0 ? currentRoomStudents[0].level : 'ปวช. 1';
  const guessedDept = currentRoomStudents.length > 0 ? currentRoomStudents[0].department : 'เทคโนโลยีสารสนเทศ';

  const handleStatusChange = (id: string, status: AttendanceStatus) => {
    setSessionAttendance(prev => ({ ...prev, [id]: status }));
    if (status === 'PRESENT') {
      setRemarks(prev => {
        const next = { ...prev };
        delete next[id];
        return next;
      });
    }
  };

  const handleRemarkChange = (id: string, text: string) => {
    setRemarks(prev => ({ ...prev, [id]: text }));
  };

  const handleSave = () => {
    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    const newRecords: AttendanceRecord[] = Object.entries(sessionAttendance).map(([studentId, status]) => ({
      id: `SUBJECT_${Date.now()}_${studentId}_${subjectId}`,
      studentId,
      date: today,
      type: 'SUBJECT' as const,
      subjectId: subjectId,
      status: status as AttendanceStatus,
      remark: remarks[studentId] || '',
      timestamp
    }));

    setAttendanceRecords(prev => [...newRecords, ...prev]);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const handleAddStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStudent.studentId || !newStudent.name) return;

    const student: Student = {
      id: `STU_${Date.now()}`,
      studentId: newStudent.studentId,
      name: newStudent.name,
      level: guessedLevel,
      department: guessedDept,
      room: room,
      behaviorScore: 100
    };

    setStudents(prev => [...prev, student]);
    setNewStudent({ studentId: '', name: '' });
    setShowAddModal(null);
  };

  const handleAddSubject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newSubject.code || !newSubject.name) return;

    const subject: Subject = {
      id: `SUB_${Date.now()}`,
      code: newSubject.code,
      name: newSubject.name,
      teacherId: currentUser.id
    };

    setSubjects(prev => [...prev, subject]);
    setSubjectId(subject.id);
    setNewSubject({ code: '', name: '' });
    setShowAddModal(null);
  };

  const handleAddRoom = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newRoomValue.trim()) return;

    if (!rooms.includes(newRoomValue)) {
      setRooms(prev => [...prev, newRoomValue]);
      setRoom(newRoomValue);
    }
    setNewRoomValue('');
    setShowAddModal(null);
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
        <div className="flex flex-col md:flex-row gap-6">
          <div className="flex-1 space-y-4">
            <div className="flex items-center gap-2 text-blue-600 font-black mb-2 text-lg">
              <BookOpen size={20} />
              <span>เลือกรายวิชาและห้องเรียน</span>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-1">
                <div className="flex justify-between items-center mb-1">
                  <label className="text-xs font-black text-black uppercase">รายวิชา</label>
                  <button 
                    onClick={() => setShowAddModal('SUBJECT')}
                    className="p-1 text-blue-600 hover:bg-blue-50 rounded transition-colors"
                  >
                    <Plus size={14} />
                  </button>
                </div>
                <select 
                  value={subjectId}
                  onChange={(e) => setSubjectId(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-300 rounded-xl px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black"
                >
                  {subjects.length === 0 && <option value="">ยังไม่มีรายวิชา</option>}
                  {subjects.map(s => <option key={s.id} value={s.id}>{s.code} - {s.name}</option>)}
                </select>
              </div>
              <div className="space-y-1">
                <div className="flex justify-between items-center mb-1">
                  <label className="text-xs font-black text-black uppercase">ห้องเรียน</label>
                  <button 
                    onClick={() => setShowAddModal('ROOM')}
                    className="p-1 text-blue-600 hover:bg-blue-50 rounded transition-colors"
                  >
                    <Plus size={14} />
                  </button>
                </div>
                <select 
                  value={room}
                  onChange={(e) => setRoom(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-300 rounded-xl px-3 py-2.5 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-black"
                >
                  {rooms.map(r => <option key={r} value={r}>ห้อง {r}</option>)}
                </select>
              </div>
            </div>
          </div>

          <div className="w-full md:w-64 bg-slate-900 p-4 rounded-2xl border border-slate-800 flex flex-col justify-center shadow-lg">
            <div className="flex items-center gap-2 text-blue-400 mb-2">
              <Clock size={16} />
              <span className="text-xs font-black uppercase tracking-widest">เวลาปัจจุบัน</span>
            </div>
            <p className="text-3xl font-black text-white">{new Date().toLocaleTimeString('th-TH')}</p>
            <p className="text-sm text-slate-400 font-bold">{new Date().toLocaleDateString('th-TH', { dateStyle: 'long' })}</p>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-4 bg-slate-50 border-b border-slate-200 flex flex-wrap items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
              <Users size={18} className="text-black" />
              <span className="font-black text-black text-lg">รายชื่อนักเรียน ({students.length} คน)</span>
            </div>
            <button 
              onClick={() => setShowAddModal('STUDENT')}
              className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 rounded-xl text-xs font-black border border-blue-200 hover:bg-blue-100 transition-all"
            >
              <UserPlus size={16} /> เพิ่มนักเรียนรายคน
            </button>
          </div>
          <button 
            onClick={handleSave}
            disabled={students.length === 0}
            className={`px-6 py-2.5 rounded-xl text-white font-black transition-all ${isSaved ? 'bg-green-600' : 'bg-blue-600 disabled:bg-slate-300'} flex items-center gap-2 shadow-lg`}
          >
            <Save size={18} />
            {isSaved ? 'บันทึกแล้ว' : 'บันทึกการเช็คชื่อ'}
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-100/50">
                <th className="px-6 py-4 text-sm font-black text-black uppercase">ลำดับ</th>
                <th className="px-6 py-4 text-sm font-black text-black uppercase">นักเรียน</th>
                <th className="px-6 py-4 text-sm font-black text-black uppercase">สถานะเข้าเรียน & หมายเหตุ</th>
                <th className="px-6 py-4 text-sm font-black text-black uppercase text-center">สถิติ (%)</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {students.map((student, idx) => (
                <tr key={student.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4 text-sm font-black text-black align-top">{idx + 1}</td>
                  <td className="px-6 py-4 align-top">
                    <p className="font-black text-black">{student.name}</p>
                    <p className="text-xs text-slate-800 font-bold uppercase">{student.studentId}</p>
                  </td>
                  <td className="px-6 py-4 align-top">
                    <div className="flex flex-col gap-3">
                      <div className="flex flex-wrap gap-2">
                        {(['PRESENT', 'LATE', 'ABSENT', 'BUSINESS_LEAVE', 'SICK_LEAVE'] as AttendanceStatus[]).map((status) => (
                          <button
                            key={status}
                            onClick={() => handleStatusChange(student.id, status)}
                            className={`
                              px-4 py-2 rounded-xl text-xs font-black transition-all border-2
                              ${sessionAttendance[student.id] === status 
                                ? STATUS_LABELS[status].color + ' border-current shadow-sm'
                                : 'bg-white text-slate-800 border-slate-100 hover:border-slate-300'}
                            `}
                          >
                            {STATUS_LABELS[status].label}
                          </button>
                        ))}
                      </div>

                      {/* Remark entry field */}
                      {sessionAttendance[student.id] && sessionAttendance[student.id] !== 'PRESENT' && (
                        <div className="relative animate-in slide-in-from-top-1 max-w-md">
                          <MessageSquare className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                          <input 
                            type="text"
                            value={remarks[student.id] || ''}
                            onChange={(e) => handleRemarkChange(student.id, e.target.value)}
                            placeholder={`ระบุสาเหตุเพิ่มเติมสำหรับการ${STATUS_LABELS[sessionAttendance[student.id]].label}...`}
                            className="w-full bg-slate-50 border border-slate-200 focus:border-blue-400 rounded-lg pl-9 pr-3 py-2 text-xs font-bold text-slate-900 outline-none"
                          />
                        </div>
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4 align-top">
                    <div className="flex items-center justify-center gap-3">
                      <div className="w-20 bg-slate-200 h-2.5 rounded-full overflow-hidden shadow-inner">
                        <div className="bg-blue-600 h-full shadow-[0_0_8px_rgba(37,99,235,0.4)]" style={{ width: '95%' }}></div>
                      </div>
                      <span className="text-sm font-black text-black">95%</span>
                    </div>
                  </td>
                </tr>
              ))}
              {students.length === 0 && (
                <tr>
                  <td colSpan={4} className="py-20 text-center text-slate-400 font-bold">
                    ยังไม่มีนักเรียนในห้องนี้
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modals */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-md">
          <div className="bg-white w-full max-w-md rounded-[48px] p-12 shadow-2xl animate-in zoom-in-95 duration-300 relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-8 right-8 text-slate-400 hover:text-slate-900 transition-colors">
              <X size={24} />
            </button>

            {showAddModal === 'STUDENT' && (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-2 text-center uppercase tracking-tight">เพิ่มนักเรียนใหม่</h3>
                <p className="text-center text-slate-500 font-bold mb-8 italic">จะถูกเพิ่มเข้าห้อง {room} อัตโนมัติ</p>

                <form onSubmit={handleAddStudent} className="space-y-6">
                  <div className="space-y-1">
                    <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">รหัสประจำตัว</label>
                    <input 
                      type="text" required value={newStudent.studentId} 
                      onChange={(e) => setNewStudent({...newStudent, studentId: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[24px] px-6 py-4 font-black text-slate-900 text-xl outline-none"
                      placeholder="เช่น 661001"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ-นามสกุล</label>
                    <input 
                      type="text" required value={newStudent.name} 
                      onChange={(e) => setNewStudent({...newStudent, name: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[24px] px-6 py-4 font-black text-slate-900 text-xl outline-none"
                      placeholder="นายสมมติ นามสกุล"
                    />
                  </div>
                  <div className="flex gap-4 pt-4">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-sm tracking-widest hover:bg-slate-200 transition-colors">ยกเลิก</button>
                    <button type="submit" className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-sm tracking-widest hover:bg-blue-700 transition-colors">บันทึก</button>
                  </div>
                </form>
              </>
            )}

            {showAddModal === 'SUBJECT' && (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-8 text-center uppercase tracking-tight">เพิ่มรายวิชาใหม่</h3>
                <form onSubmit={handleAddSubject} className="space-y-6">
                  <div className="space-y-1">
                    <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">รหัสวิชา</label>
                    <input 
                      type="text" required value={newSubject.code} 
                      onChange={(e) => setNewSubject({...newSubject, code: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[24px] px-6 py-4 font-black text-slate-900 text-xl outline-none"
                      placeholder="เช่น IT30201"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อรายวิชา</label>
                    <input 
                      type="text" required value={newSubject.name} 
                      onChange={(e) => setNewSubject({...newSubject, name: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[24px] px-6 py-4 font-black text-slate-900 text-xl outline-none"
                      placeholder="เช่น การเขียนโปรแกรมเว็บ"
                    />
                  </div>
                  <div className="flex gap-4 pt-4">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-sm tracking-widest hover:bg-slate-200 transition-colors">ยกเลิก</button>
                    <button type="submit" className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-sm tracking-widest hover:bg-blue-700 transition-colors">บันทึก</button>
                  </div>
                </form>
              </>
            )}

            {showAddModal === 'ROOM' && (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-8 text-center uppercase tracking-tight">เพิ่มห้องเรียนใหม่</h3>
                <form onSubmit={handleAddRoom} className="space-y-6">
                  <div className="space-y-1">
                    <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ/หมายเลขห้อง</label>
                    <input 
                      type="text" required value={newRoomValue} 
                      onChange={(e) => setNewRoomValue(e.target.value)} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[24px] px-6 py-4 font-black text-slate-900 text-xl outline-none"
                      placeholder="เช่น 4, 5 หรือ 101"
                      autoFocus
                    />
                  </div>
                  <div className="flex gap-4 pt-4">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-sm tracking-widest hover:bg-slate-200 transition-colors">ยกเลิก</button>
                    <button type="submit" className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-sm tracking-widest hover:bg-blue-700 transition-colors">บันทึก</button>
                  </div>
                </form>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default ClassAttendance;

import React, { useState } from 'react';
import { Student, Subject, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { Save, BookOpen, Clock, Users, MessageSquare, UserPlus, X, Plus, Filter } from 'lucide-react';

interface ClassAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  subjects: Subject[];
  setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  currentUser: any;
}

const ClassAttendance: React.FC<ClassAttendanceProps> = ({ 
  students: allStudents, 
  setStudents,
  subjects, 
  setSubjects,
  rooms,
  setRooms,
  attendanceRecords, 
  setAttendanceRecords,
  currentUser
}) => {
  // Filters State
  const [level, setLevel] = useState<string>(Object.values(ThaiLevel)[0]);
  const [dept, setDept] = useState<string>(Object.values(Department)[0]);
  const [room, setRoom] = useState(rooms.length > 0 ? rooms[0] : '1');
  const [subjectId, setSubjectId] = useState(subjects.length > 0 ? subjects[0].id : '');

  // UI State
  const [sessionAttendance, setSessionAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);

  const [showAddModal, setShowAddModal] = useState<'STUDENT' | 'SUBJECT' | 'ROOM' | null>(null);
  const [newStudent, setNewStudent] = useState({ studentId: '', name: '' });
  const [newSubject, setNewSubject] = useState({ code: '', name: '' });
  const [newRoomValue, setNewRoomValue] = useState('');

  // Filtered Students
  const filteredStudents = allStudents.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room
  );

  const handleStatusChange = (id: string, status: AttendanceStatus) => {
    setSessionAttendance(prev => ({ ...prev, [id]: status }));
    if (status === 'PRESENT') {
      setRemarks(prev => {
        const next = { ...prev };
        delete next[id];
        return next;
      });
    }
  };

  const handleRemarkChange = (id: string, text: string) => {
    setRemarks(prev => ({ ...prev, [id]: text }));
  };

  const handleSave = () => {
    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    const newRecords: AttendanceRecord[] = Object.entries(sessionAttendance).map(([studentId, status]) => ({
      id: `SUBJECT_${Date.now()}_${studentId}_${subjectId}`,
      studentId,
      date: today,
      type: 'SUBJECT' as const,
      subjectId: subjectId,
      status: status as AttendanceStatus,
      remark: remarks[studentId] || '',
      timestamp
    }));

    setAttendanceRecords(prev => [...newRecords, ...prev]);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const handleAddStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStudent.studentId || !newStudent.name) return;

    const student: Student = {
      id: `STU_${Date.now()}`,
      studentId: newStudent.studentId,
      name: newStudent.name,
      level: level,
      department: dept,
      room: room,
      behaviorScore: 100
    };

    setStudents(prev => [...prev, student]);
    setNewStudent({ studentId: '', name: '' });
    setShowAddModal(null);
  };

  const handleAddSubject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newSubject.code || !newSubject.name) return;

    const subject: Subject = {
      id: `SUB_${Date.now()}`,
      code: newSubject.code,
      name: newSubject.name,
      teacherId: currentUser.id
    };

    setSubjects(prev => [...prev, subject]);
    setSubjectId(subject.id);
    setNewSubject({ code: '', name: '' });
    setShowAddModal(null);
  };

  const handleAddRoom = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newRoomValue.trim()) return;

    if (!rooms.includes(newRoomValue)) {
      setRooms(prev => [...prev, newRoomValue]);
      setRoom(newRoomValue);
    }
    setNewRoomValue('');
    setShowAddModal(null);
  };

  return (
    <div className="space-y-6">
      {/* Filters Header */}
      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
        <div className="flex flex-col xl:flex-row gap-8">
          <div className="flex-1">
            <div className="flex items-center gap-2 text-blue-600 font-black mb-6 text-lg">
              <Filter size={20} />
              <span>ตัวกรองการเช็คชื่อเข้าเรียน</span>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {/* Level Filter */}
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
                <select 
                  value={level}
                  onChange={(e) => setLevel(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 transition-all"
                >
                  {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>

              {/* Department Filter */}
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
                <select 
                  value={dept}
                  onChange={(e) => setDept(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 transition-all"
                >
                  {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>

              {/* Room Filter */}
              <div className="space-y-1.5">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ห้องเรียน</label>
                  <button onClick={() => setShowAddModal('ROOM')} className="text-blue-600 hover:bg-blue-50 p-0.5 rounded transition-colors">
                    <Plus size={14} />
                  </button>
                </div>
                <select 
                  value={room}
                  onChange={(e) => setRoom(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 transition-all"
                >
                  {rooms.map(r => <option key={r} value={r}>ห้อง {r}</option>)}
                </select>
              </div>

              {/* Subject Filter */}
              <div className="space-y-1.5">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">รายวิชา</label>
                  <button onClick={() => setShowAddModal('SUBJECT')} className="text-blue-600 hover:bg-blue-50 p-0.5 rounded transition-colors">
                    <Plus size={14} />
                  </button>
                </div>
                <select 
                  value={subjectId}
                  onChange={(e) => setSubjectId(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 transition-all"
                >
                  {subjects.length === 0 && <option value="">ยังไม่มีรายวิชา</option>}
                  {subjects.map(s => <option key={s.id} value={s.id}>{s.code} - {s.name}</option>)}
                </select>
              </div>
            </div>
          </div>

          {/* Clock Info */}
          <div className="w-full xl:w-72 bg-slate-900 p-6 rounded-[32px] border border-slate-800 flex flex-col justify-center shadow-xl shrink-0">
            <div className="flex items-center gap-2 text-blue-400 mb-2">
              <Clock size={18} />
              <span className="text-[10px] font-black uppercase tracking-[0.2em]">เวลาปัจจุบัน</span>
            </div>
            <p className="text-4xl font-black text-white tabular-nums tracking-tighter">
              {new Date().toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit' })}
            </p>
            <p className="text-xs text-slate-400 font-bold mt-1 uppercase tracking-wider">
              {new Date().toLocaleDateString('th-TH', { dateStyle: 'medium' })}
            </p>
          </div>
        </div>
      </div>

      {/* Student List Section */}
      <div className="bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-6 bg-slate-50/50 border-b border-slate-200 flex flex-wrap items-center justify-between gap-6">
          <div className="flex flex-wrap items-center gap-6">
            <div className="flex items-center gap-3">
              <Users size={22} className="text-slate-900" />
              <span className="font-black text-slate-900 text-xl tracking-tight">รายชื่อนักเรียน ({filteredStudents.length} คน)</span>
            </div>
            <button 
              onClick={() => setShowAddModal('STUDENT')}
              className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-2xl text-xs font-black shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all hover:-translate-y-0.5 active:translate-y-0"
            >
              <UserPlus size={16} /> เพิ่มนักเรียนรายคน
            </button>
          </div>
          <button 
            onClick={handleSave}
            disabled={filteredStudents.length === 0}
            className={`px-10 py-3.5 rounded-2xl text-white font-black transition-all shadow-xl flex items-center gap-3 uppercase tracking-widest text-sm ${isSaved ? 'bg-green-600 shadow-green-100' : 'bg-slate-900 shadow-slate-200 disabled:bg-slate-300 disabled:shadow-none'}`}
          >
            <Save size={20} />
            {isSaved ? 'บันทึกสำเร็จ' : 'ยืนยันการเช็คชื่อ'}
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white border-b border-slate-100">
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">ลำดับ</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">ข้อมูลนักเรียน</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">สถานะการเข้าเรียน และ หมายเหตุ</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-center">สถิติ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredStudents.map((student, idx) => (
                <tr key={student.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-10 py-6 text-base font-black text-slate-900 align-top">{idx + 1}</td>
                  <td className="px-10 py-6 align-top">
                    <p className="font-black text-slate-900 text-lg leading-tight">{student.name}</p>
                    <p className="text-xs text-slate-500 font-extrabold uppercase mt-1.5 tracking-widest">รหัส: {student.studentId}</p>
                  </td>
                  <td className="px-10 py-6 align-top">
                    <div className="flex flex-col gap-4">
                      <div className="flex flex-wrap gap-2">
                        {(['PRESENT', 'LATE', 'ABSENT', 'BUSINESS_LEAVE', 'SICK_LEAVE'] as AttendanceStatus[]).map((status) => (
                          <button
                            key={status}
                            onClick={() => handleStatusChange(student.id, status)}
                            className={`
                              px-5 py-2.5 rounded-xl text-[11px] font-black transition-all border-2
                              ${sessionAttendance[student.id] === status 
                                ? STATUS_LABELS[status].color + ' border-current shadow-md scale-105'
                                : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}
                            `}
                          >
                            {STATUS_LABELS[status].label}
                          </button>
                        ))}
                      </div>

                      {/* Remark entry field */}
                      {sessionAttendance[student.id] && sessionAttendance[student.id] !== 'PRESENT' && (
                        <div className="relative animate-in slide-in-from-top-2 max-w-lg">
                          <MessageSquare className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                          <input 
                            type="text"
                            value={remarks[student.id] || ''}
                            onChange={(e) => handleRemarkChange(student.id, e.target.value)}
                            placeholder={`ระบุหมายเหตุสำหรับ: ${STATUS_LABELS[sessionAttendance[student.id]].label}...`}
                            className="w-full bg-slate-50 border-2 border-slate-200 focus:border-blue-400 rounded-2xl pl-12 pr-4 py-3 text-sm font-bold text-slate-900 outline-none transition-all shadow-inner"
                          />
                        </div>
                      )}
                    </div>
                  </td>
                  <td className="px-10 py-6 align-top">
                    <div className="flex flex-col items-center justify-center gap-2">
                      <div className="w-24 bg-slate-100 h-3 rounded-full overflow-hidden shadow-inner border border-slate-200/50">
                        <div className="bg-blue-600 h-full shadow-[0_0_12px_rgba(37,99,235,0.4)]" style={{ width: '95%' }}></div>
                      </div>
                      <span className="text-xs font-black text-slate-900">95%</span>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr>
                  <td colSpan={4} className="py-32 text-center text-slate-400">
                    <Users size={64} className="mx-auto mb-6 opacity-5" />
                    <p className="text-2xl font-black text-slate-900">ไม่พบนักเรียนในห้องเรียนนี้</p>
                    <p className="text-slate-500 font-bold mt-2">กรุณาปรับตัวกรอง หรือ เพิ่มนักเรียนใหม่</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modals Management */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-md">
          <div className="bg-white w-full max-w-md rounded-[48px] p-12 shadow-2xl animate-in zoom-in-95 duration-300 relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-10 right-10 text-slate-400 hover:text-slate-900 transition-colors">
              <X size={28} />
            </button>

            {showAddModal === 'STUDENT' && (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-2 text-center uppercase tracking-tight">เพิ่มนักเรียนใหม่</h3>
                <p className="text-center text-slate-500 font-bold mb-8 italic text-sm">{level} • {dept} • ห้อง {room}</p>

                <form onSubmit={handleAddStudent} className="space-y-6">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">รหัสประจำตัว</label>
                    <input 
                      type="text" required value={newStudent.studentId} 
                      onChange={(e) => setNewStudent({...newStudent, studentId: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="เช่น 661001"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ-นามสกุล</label>
                    <input 
                      type="text" required value={newStudent.name} 
                      onChange={(e) => setNewStudent({...newStudent, name: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="นายสมมติ นามสกุล"
                    />
                  </div>
                  <div className="flex gap-4 pt-4">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-[0.2em] hover:bg-slate-200 transition-colors">ยกเลิก</button>
                    <button type="submit" className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-xs tracking-[0.2em] hover:bg-blue-700 transition-colors">บันทึก</button>
                  </div>
                </form>
              </>
            )}

            {showAddModal === 'SUBJECT' && (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-8 text-center uppercase tracking-tight">เพิ่มรายวิชาใหม่</h3>
                <form onSubmit={handleAddSubject} className="space-y-6">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">รหัสวิชา</label>
                    <input 
                      type="text" required value={newSubject.code} 
                      onChange={(e) => setNewSubject({...newSubject, code: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="เช่น IT30201"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อรายวิชา</label>
                    <input 
                      type="text" required value={newSubject.name} 
                      onChange={(e) => setNewSubject({...newSubject, name: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="เช่น การเขียนโปรแกรมเว็บ"
                    />
                  </div>
                  <div className="flex gap-4 pt-4">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-[0.2em] hover:bg-slate-200 transition-colors">ยกเลิก</button>
                    <button type="submit" className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-xs tracking-[0.2em] hover:bg-blue-700 transition-colors">บันทึก</button>
                  </div>
                </form>
              </>
            )}

            {showAddModal === 'ROOM' && (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-8 text-center uppercase tracking-tight">เพิ่มห้องเรียนใหม่</h3>
                <form onSubmit={handleAddRoom} className="space-y-6">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ/หมายเลขห้อง</label>
                    <input 
                      type="text" required value={newRoomValue} 
                      onChange={(e) => setNewRoomValue(e.target.value)} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="เช่น 4, 5 หรือ 101"
                      autoFocus
                    />
                  </div>
                  <div className="flex gap-4 pt-4">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-[0.2em] hover:bg-slate-200 transition-colors">ยกเลิก</button>
                    <button type="submit" className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-xs tracking-[0.2em] hover:bg-blue-700 transition-colors">บันทึก</button>
                  </div>
                </form>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default ClassAttendance;

import React, { useState, useEffect } from 'react';
import { Student, Subject, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { Save, BookOpen, Clock, Users, MessageSquare, UserPlus, X, Plus, Filter } from 'lucide-react';

interface ClassAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  subjects: Subject[];
  setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  currentUser: any;
}

const ClassAttendance: React.FC<ClassAttendanceProps> = ({ 
  students: allStudents, 
  setStudents,
  subjects, 
  setSubjects,
  rooms,
  setRooms,
  attendanceRecords, 
  setAttendanceRecords,
  currentUser
}) => {
  // Filters State
  const [level, setLevel] = useState<string>(Object.values(ThaiLevel)[0]);
  const [dept, setDept] = useState<string>(Object.values(Department)[0]);
  const [room, setRoom] = useState(rooms.length > 0 ? rooms[0] : '1');
  const [subjectId, setSubjectId] = useState(subjects.length > 0 ? subjects[0].id : '');

  // UI State
  const [sessionAttendance, setSessionAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date());

  const [showAddModal, setShowAddModal] = useState<'STUDENT' | 'SUBJECT' | 'ROOM' | null>(null);
  const [newStudent, setNewStudent] = useState({ studentId: '', name: '' });
  const [newSubject, setNewSubject] = useState({ code: '', name: '' });
  const [newRoomValue, setNewRoomValue] = useState('');

  // Update clock every second
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Filtered Students
  const filteredStudents = allStudents.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room
  );

  const handleStatusChange = (id: string, status: AttendanceStatus) => {
    setSessionAttendance(prev => ({ ...prev, [id]: status }));
    if (status === 'PRESENT') {
      setRemarks(prev => {
        const next = { ...prev };
        delete next[id];
        return next;
      });
    }
  };

  const handleRemarkChange = (id: string, text: string) => {
    setRemarks(prev => ({ ...prev, [id]: text }));
  };

  const handleSave = () => {
    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    const newRecords: AttendanceRecord[] = Object.entries(sessionAttendance).map(([studentId, status]) => ({
      id: `SUBJECT_${Date.now()}_${studentId}_${subjectId}`,
      studentId,
      date: today,
      type: 'SUBJECT' as const,
      subjectId: subjectId,
      status: status as AttendanceStatus,
      remark: remarks[studentId] || '',
      timestamp
    }));

    setAttendanceRecords(prev => [...newRecords, ...prev]);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const handleAddStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStudent.studentId || !newStudent.name) return;

    const student: Student = {
      id: `STU_${Date.now()}`,
      studentId: newStudent.studentId,
      name: newStudent.name,
      level: level,
      department: dept,
      room: room,
      behaviorScore: 100
    };

    setStudents(prev => [...prev, student]);
    setNewStudent({ studentId: '', name: '' });
    setShowAddModal(null);
  };

  const handleAddSubject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newSubject.code || !newSubject.name) return;

    const subject: Subject = {
      id: `SUB_${Date.now()}`,
      code: newSubject.code,
      name: newSubject.name,
      teacherId: currentUser.id
    };

    setSubjects(prev => [...prev, subject]);
    setSubjectId(subject.id);
    setNewSubject({ code: '', name: '' });
    setShowAddModal(null);
  };

  const handleAddRoom = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newRoomValue.trim()) return;

    if (!rooms.includes(newRoomValue)) {
      setRooms(prev => [...prev, newRoomValue]);
      setRoom(newRoomValue);
    }
    setNewRoomValue('');
    setShowAddModal(null);
  };

  return (
    <div className="space-y-6">
      {/* Filters Header */}
      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
        <div className="flex flex-col xl:flex-row gap-8">
          <div className="flex-1">
            <div className="flex items-center gap-2 text-blue-600 font-black mb-6 text-lg">
              <Filter size={20} />
              <span>ตัวกรองการเช็คชื่อเข้าเรียน</span>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {/* Level Filter */}
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
                <select 
                  value={level}
                  onChange={(e) => setLevel(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 transition-all"
                >
                  {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>

              {/* Department Filter */}
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
                <select 
                  value={dept}
                  onChange={(e) => setDept(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 transition-all"
                >
                  {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>

              {/* Room Filter */}
              <div className="space-y-1.5">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ห้องเรียน</label>
                  <button onClick={() => setShowAddModal('ROOM')} className="text-blue-600 hover:bg-blue-50 p-0.5 rounded transition-colors">
                    <Plus size={14} />
                  </button>
                </div>
                <select 
                  value={room}
                  onChange={(e) => setRoom(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 transition-all"
                >
                  {rooms.map(r => <option key={r} value={r}>ห้อง {r}</option>)}
                </select>
              </div>

              {/* Subject Filter */}
              <div className="space-y-1.5">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">รายวิชา</label>
                  <button onClick={() => setShowAddModal('SUBJECT')} className="text-blue-600 hover:bg-blue-50 p-0.5 rounded transition-colors">
                    <Plus size={14} />
                  </button>
                </div>
                <select 
                  value={subjectId}
                  onChange={(e) => setSubjectId(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 transition-all"
                >
                  {subjects.length === 0 && <option value="">ยังไม่มีรายวิชา</option>}
                  {subjects.map(s => <option key={s.id} value={s.id}>{s.code} - {s.name}</option>)}
                </select>
              </div>
            </div>
          </div>

          {/* Clock Info */}
          <div className="w-full xl:w-72 bg-slate-900 p-6 rounded-[32px] border border-slate-800 flex flex-col justify-center shadow-xl shrink-0">
            <div className="flex items-center gap-2 text-blue-400 mb-2">
              <Clock size={18} />
              <span className="text-[10px] font-black uppercase tracking-[0.2em]">เวลาปัจจุบัน</span>
            </div>
            <p className="text-4xl font-black text-white tabular-nums tracking-tighter">
              {currentTime.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
            </p>
            <p className="text-xs text-slate-400 font-bold mt-1 uppercase tracking-wider">
              {currentTime.toLocaleDateString('th-TH', { dateStyle: 'medium' })}
            </p>
          </div>
        </div>
      </div>

      {/* Student List Section */}
      <div className="bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-6 bg-slate-50/50 border-b border-slate-200 flex flex-wrap items-center justify-between gap-6">
          <div className="flex flex-wrap items-center gap-6">
            <div className="flex items-center gap-3">
              <Users size={22} className="text-slate-900" />
              <span className="font-black text-slate-900 text-xl tracking-tight">รายชื่อนักเรียน ({filteredStudents.length} คน)</span>
            </div>
            <button 
              onClick={() => setShowAddModal('STUDENT')}
              className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-2xl text-xs font-black shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all hover:-translate-y-0.5 active:translate-y-0"
            >
              <UserPlus size={16} /> เพิ่มนักเรียนรายคน
            </button>
          </div>
          <button 
            onClick={handleSave}
            disabled={filteredStudents.length === 0}
            className={`px-10 py-3.5 rounded-2xl text-white font-black transition-all shadow-xl flex items-center gap-3 uppercase tracking-widest text-sm ${isSaved ? 'bg-green-600 shadow-green-100' : 'bg-slate-900 shadow-slate-200 disabled:bg-slate-300 disabled:shadow-none'}`}
          >
            <Save size={20} />
            {isSaved ? 'บันทึกสำเร็จ' : 'ยืนยันการเช็คชื่อ'}
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white border-b border-slate-100">
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">ลำดับ</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">ข้อมูลนักเรียน</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">สถานะการเข้าเรียน และ หมายเหตุ</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-center">สถิติ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredStudents.map((student, idx) => (
                <tr key={student.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-10 py-6 text-base font-black text-slate-900 align-top">{idx + 1}</td>
                  <td className="px-10 py-6 align-top">
                    <p className="font-black text-slate-900 text-lg leading-tight">{student.name}</p>
                    <p className="text-xs text-slate-500 font-extrabold uppercase mt-1.5 tracking-widest">รหัส: {student.studentId}</p>
                  </td>
                  <td className="px-10 py-6 align-top">
                    <div className="flex flex-col gap-4">
                      <div className="flex flex-wrap gap-2">
                        {(['PRESENT', 'LATE', 'ABSENT', 'BUSINESS_LEAVE', 'SICK_LEAVE'] as AttendanceStatus[]).map((status) => (
                          <button
                            key={status}
                            onClick={() => handleStatusChange(student.id, status)}
                            className={`
                              px-5 py-2.5 rounded-xl text-[11px] font-black transition-all border-2
                              ${sessionAttendance[student.id] === status 
                                ? STATUS_LABELS[status].color + ' border-current shadow-md scale-105'
                                : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}
                            `}
                          >
                            {STATUS_LABELS[status].label}
                          </button>
                        ))}
                      </div>

                      {/* Remark entry field */}
                      {sessionAttendance[student.id] && sessionAttendance[student.id] !== 'PRESENT' && (
                        <div className="relative animate-in slide-in-from-top-2 max-w-lg">
                          <MessageSquare className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                          <input 
                            type="text"
                            value={remarks[student.id] || ''}
                            onChange={(e) => handleRemarkChange(student.id, e.target.value)}
                            placeholder={`ระบุหมายเหตุสำหรับ: ${STATUS_LABELS[sessionAttendance[student.id]].label}...`}
                            className="w-full bg-slate-50 border-2 border-slate-200 focus:border-blue-400 rounded-2xl pl-12 pr-4 py-3 text-sm font-bold text-slate-900 outline-none transition-all shadow-inner"
                          />
                        </div>
                      )}
                    </div>
                  </td>
                  <td className="px-10 py-6 align-top">
                    <div className="flex flex-col items-center justify-center gap-2">
                      <div className="w-24 bg-slate-100 h-3 rounded-full overflow-hidden shadow-inner border border-slate-200/50">
                        <div className="bg-blue-600 h-full shadow-[0_0_12px_rgba(37,99,235,0.4)]" style={{ width: '95%' }}></div>
                      </div>
                      <span className="text-xs font-black text-slate-900">95%</span>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredStudents.length === 0 && (
                <tr>
                  <td colSpan={4} className="py-32 text-center text-slate-400">
                    <Users size={64} className="mx-auto mb-6 opacity-5" />
                    <p className="text-2xl font-black text-slate-900">ไม่พบระเบียนนักเรียน</p>
                    <p className="text-slate-500 font-bold mt-2">กรุณาปรับตัวกรอง หรือ เพิ่มนักเรียนใหม่</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modals Management */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-md">
          <div className="bg-white w-full max-w-md rounded-[48px] p-12 shadow-2xl animate-in zoom-in-95 duration-300 relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-10 right-10 text-slate-400 hover:text-slate-900 transition-colors">
              <X size={28} />
            </button>

            {showAddModal === 'STUDENT' && (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-2 text-center uppercase tracking-tight">เพิ่มนักเรียนใหม่</h3>
                <p className="text-center text-slate-500 font-bold mb-8 italic text-sm">{level} • {dept} • ห้อง {room}</p>

                <form onSubmit={handleAddStudent} className="space-y-6">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">รหัสประจำตัว</label>
                    <input 
                      type="text" required value={newStudent.studentId} 
                      onChange={(e) => setNewStudent({...newStudent, studentId: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="เช่น 661001"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ-นามสกุล</label>
                    <input 
                      type="text" required value={newStudent.name} 
                      onChange={(e) => setNewStudent({...newStudent, name: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="นายสมมติ นามสกุล"
                    />
                  </div>
                  <div className="flex gap-4 pt-4">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-[0.2em] hover:bg-slate-200 transition-colors">ยกเลิก</button>
                    <button type="submit" className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-xs tracking-[0.2em] hover:bg-blue-700 transition-colors">บันทึก</button>
                  </div>
                </form>
              </>
            )}

            {showAddModal === 'SUBJECT' && (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-8 text-center uppercase tracking-tight">เพิ่มรายวิชาใหม่</h3>
                <form onSubmit={handleAddSubject} className="space-y-6">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">รหัสวิชา</label>
                    <input 
                      type="text" required value={newSubject.code} 
                      onChange={(e) => setNewSubject({...newSubject, code: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="เช่น IT30201"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อรายวิชา</label>
                    <input 
                      type="text" required value={newSubject.name} 
                      onChange={(e) => setNewSubject({...newSubject, name: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="เช่น การเขียนโปรแกรมเว็บ"
                    />
                  </div>
                  <div className="flex gap-4 pt-4">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-[0.2em] hover:bg-slate-200 transition-colors">ยกเลิก</button>
                    <button type="submit" className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-xs tracking-[0.2em] hover:bg-blue-700 transition-colors">บันทึก</button>
                  </div>
                </form>
              </>
            )}

            {showAddModal === 'ROOM' && (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-8 text-center uppercase tracking-tight">เพิ่มห้องเรียนใหม่</h3>
                <form onSubmit={handleAddRoom} className="space-y-6">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ/หมายเลขห้อง</label>
                    <input 
                      type="text" required value={newRoomValue} 
                      onChange={(e) => setNewRoomValue(e.target.value)} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="เช่น 4, 5 หรือ 101"
                      autoFocus
                    />
                  </div>
                  <div className="flex gap-4 pt-4">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-[0.2em] hover:bg-slate-200 transition-colors">ยกเลิก</button>
                    <button type="submit" className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-xs tracking-[0.2em] hover:bg-blue-700 transition-colors">บันทึก</button>
                  </div>
                </form>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default ClassAttendance;

import React, { useState, useEffect } from 'react';
import { Student, Subject, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { Save, BookOpen, Clock, Users, MessageSquare, UserPlus, X, Plus, Filter, History, ClipboardCheck, Calendar } from 'lucide-react';

interface ClassAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  subjects: Subject[];
  setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  currentUser: any;
}

const ClassAttendance: React.FC<ClassAttendanceProps> = ({ 
  students: allStudents, 
  setStudents,
  subjects, 
  setSubjects,
  rooms,
  setRooms,
  attendanceRecords, 
  setAttendanceRecords,
  currentUser
}) => {
  // Navigation State
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');

  // Filters State
  const [level, setLevel] = useState<string>(Object.values(ThaiLevel)[0]);
  const [dept, setDept] = useState<string>(Object.values(Department)[0]);
  const [room, setRoom] = useState(rooms.length > 0 ? rooms[0] : '1');
  const [subjectId, setSubjectId] = useState(subjects.length > 0 ? subjects[0].id : '');

  // UI State
  const [sessionAttendance, setSessionAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date());

  const [showAddModal, setShowAddModal] = useState<'STUDENT' | 'SUBJECT' | 'ROOM' | null>(null);
  const [newStudent, setNewStudent] = useState({ studentId: '', name: '' });
  const [newSubject, setNewSubject] = useState({ code: '', name: '' });
  const [newRoomValue, setNewRoomValue] = useState('');

  // Update clock every second
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Filtered Students for Current Check-in
  const filteredStudents = allStudents.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room
  );

  // Filtered History Records
  const historyRecords = attendanceRecords.filter(record => {
    const student = allStudents.find(s => s.id === record.studentId);
    return record.type === 'SUBJECT' && 
           record.subjectId === subjectId &&
           student?.level === level && 
           student?.department === dept && 
           student?.room === room;
  }).sort((a, b) => b.date.localeCompare(a.date) || b.timestamp.localeCompare(a.timestamp));

  const handleStatusChange = (id: string, status: AttendanceStatus) => {
    setSessionAttendance(prev => ({ ...prev, [id]: status }));
    if (status === 'PRESENT') {
      setRemarks(prev => {
        const next = { ...prev };
        delete next[id];
        return next;
      });
    }
  };

  const handleRemarkChange = (id: string, text: string) => {
    setRemarks(prev => ({ ...prev, [id]: text }));
  };

  const handleSave = () => {
    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    const newRecords: AttendanceRecord[] = Object.entries(sessionAttendance).map(([studentId, status]) => ({
      id: `SUBJECT_${Date.now()}_${studentId}_${subjectId}`,
      studentId,
      date: today,
      type: 'SUBJECT' as const,
      subjectId: subjectId,
      status: status as AttendanceStatus,
      remark: remarks[studentId] || '',
      timestamp
    }));

    setAttendanceRecords(prev => [...newRecords, ...prev]);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const handleAddStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStudent.studentId || !newStudent.name) return;

    const student: Student = {
      id: `STU_${Date.now()}`,
      studentId: newStudent.studentId,
      name: newStudent.name,
      level: level,
      department: dept,
      room: room,
      behaviorScore: 100
    };

    setStudents(prev => [...prev, student]);
    setNewStudent({ studentId: '', name: '' });
    setShowAddModal(null);
  };

  const handleAddSubject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newSubject.code || !newSubject.name) return;

    const subject: Subject = {
      id: `SUB_${Date.now()}`,
      code: newSubject.code,
      name: newSubject.name,
      teacherId: currentUser.id
    };

    setSubjects(prev => [...prev, subject]);
    setSubjectId(subject.id);
    setNewSubject({ code: '', name: '' });
    setShowAddModal(null);
  };

  const handleAddRoom = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newRoomValue.trim()) return;

    if (!rooms.includes(newRoomValue)) {
      setRooms(prev => [...prev, newRoomValue]);
      setRoom(newRoomValue);
    }
    setNewRoomValue('');
    setShowAddModal(null);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
      {/* Navigation Tabs */}
      <div className="flex bg-white p-2 rounded-[24px] border border-slate-200 shadow-sm w-fit">
        <button 
          onClick={() => setViewMode('checkin')} 
          className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <ClipboardCheck size={20} /> เช็คชื่อรายวิชา
        </button>
        <button 
          onClick={() => setViewMode('history')} 
          className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <History size={20} /> ประวัติย้อนหลัง
        </button>
      </div>

      {/* Filters Header */}
      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
        <div className="flex flex-col xl:flex-row gap-8">
          <div className="flex-1">
            <div className="flex items-center gap-2 text-blue-600 font-black mb-6 text-lg">
              <Filter size={20} />
              <span>ตัวกรองข้อมูล {viewMode === 'history' ? 'ประวัติย้อนหลัง' : 'การเช็คชื่อ'}</span>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              {/* Level Filter */}
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
                <select 
                  value={level}
                  onChange={(e) => setLevel(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 transition-all"
                >
                  {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>

              {/* Department Filter */}
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
                <select 
                  value={dept}
                  onChange={(e) => setDept(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 transition-all"
                >
                  {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>

              {/* Room Filter */}
              <div className="space-y-1.5">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ห้องเรียน</label>
                  <button onClick={() => setShowAddModal('ROOM')} className="text-blue-600 hover:bg-blue-50 p-0.5 rounded transition-colors">
                    <Plus size={14} />
                  </button>
                </div>
                <select 
                  value={room}
                  onChange={(e) => setRoom(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 transition-all"
                >
                  {rooms.map(r => <option key={r} value={r}>ห้อง {r}</option>)}
                </select>
              </div>

              {/* Subject Filter */}
              <div className="space-y-1.5">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">รายวิชา</label>
                  <button onClick={() => setShowAddModal('SUBJECT')} className="text-blue-600 hover:bg-blue-50 p-0.5 rounded transition-colors">
                    <Plus size={14} />
                  </button>
                </div>
                <select 
                  value={subjectId}
                  onChange={(e) => setSubjectId(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 transition-all"
                >
                  {subjects.length === 0 && <option value="">ยังไม่มีรายวิชา</option>}
                  {subjects.map(s => <option key={s.id} value={s.id}>{s.code} - {s.name}</option>)}
                </select>
              </div>
            </div>
          </div>

          {/* Clock Info */}
          <div className="w-full xl:w-72 bg-slate-900 p-6 rounded-[32px] border border-slate-800 flex flex-col justify-center shadow-xl shrink-0">
            <div className="flex items-center gap-2 text-blue-400 mb-2">
              <Clock size={18} />
              <span className="text-[10px] font-black uppercase tracking-[0.2em]">เวลาปัจจุบัน</span>
            </div>
            <p className="text-4xl font-black text-white tabular-nums tracking-tighter">
              {currentTime.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
            </p>
            <p className="text-xs text-slate-400 font-bold mt-1 uppercase tracking-wider">
              {currentTime.toLocaleDateString('th-TH', { dateStyle: 'medium' })}
            </p>
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <div className="bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-300">
          <div className="p-6 bg-slate-50/50 border-b border-slate-200 flex flex-wrap items-center justify-between gap-6">
            <div className="flex flex-wrap items-center gap-6">
              <div className="flex items-center gap-3">
                <Users size={22} className="text-slate-900" />
                <span className="font-black text-slate-900 text-xl tracking-tight">รายชื่อนักเรียน ({filteredStudents.length} คน)</span>
              </div>
              <button 
                onClick={() => setShowAddModal('STUDENT')}
                className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-2xl text-xs font-black shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all hover:-translate-y-0.5 active:translate-y-0"
              >
                <UserPlus size={16} /> เพิ่มนักเรียนรายคน
              </button>
            </div>
            <button 
              onClick={handleSave}
              disabled={filteredStudents.length === 0}
              className={`px-10 py-3.5 rounded-2xl text-white font-black transition-all shadow-xl flex items-center gap-3 uppercase tracking-widest text-sm ${isSaved ? 'bg-green-600 shadow-green-100' : 'bg-slate-900 shadow-slate-200 disabled:bg-slate-300 disabled:shadow-none'}`}
            >
              <Save size={20} />
              {isSaved ? 'บันทึกสำเร็จ' : 'ยืนยันการเช็คชื่อ'}
            </button>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-white border-b border-slate-100">
                  <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">ลำดับ</th>
                  <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">ข้อมูลนักเรียน</th>
                  <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">สถานะการเข้าเรียน และ หมายเหตุ</th>
                  <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-center">สถิติ</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {filteredStudents.map((student, idx) => (
                  <tr key={student.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-10 py-6 text-base font-black text-slate-900 align-top">{idx + 1}</td>
                    <td className="px-10 py-6 align-top">
                      <p className="font-black text-slate-900 text-lg leading-tight">{student.name}</p>
                      <p className="text-xs text-slate-500 font-extrabold uppercase mt-1.5 tracking-widest">รหัส: {student.studentId}</p>
                    </td>
                    <td className="px-10 py-6 align-top">
                      <div className="flex flex-col gap-4">
                        <div className="flex flex-wrap gap-2">
                          {(['PRESENT', 'LATE', 'ABSENT', 'BUSINESS_LEAVE', 'SICK_LEAVE'] as AttendanceStatus[]).map((status) => (
                            <button
                              key={status}
                              onClick={() => handleStatusChange(student.id, status)}
                              className={`
                                px-5 py-2.5 rounded-xl text-[11px] font-black transition-all border-2
                                ${sessionAttendance[student.id] === status 
                                  ? STATUS_LABELS[status].color + ' border-current shadow-md scale-105'
                                  : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}
                              `}
                            >
                              {STATUS_LABELS[status].label}
                            </button>
                          ))}
                        </div>

                        {/* Remark entry field */}
                        {sessionAttendance[student.id] && sessionAttendance[student.id] !== 'PRESENT' && (
                          <div className="relative animate-in slide-in-from-top-2 max-w-lg">
                            <MessageSquare className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                            <input 
                              type="text"
                              value={remarks[student.id] || ''}
                              onChange={(e) => handleRemarkChange(student.id, e.target.value)}
                              placeholder={`ระบุหมายเหตุสำหรับ: ${STATUS_LABELS[sessionAttendance[student.id]].label}...`}
                              className="w-full bg-slate-50 border-2 border-slate-200 focus:border-blue-400 rounded-2xl pl-12 pr-4 py-3 text-sm font-bold text-slate-900 outline-none transition-all shadow-inner"
                            />
                          </div>
                        )}
                      </div>
                    </td>
                    <td className="px-10 py-6 align-top">
                      <div className="flex flex-col items-center justify-center gap-2">
                        <div className="w-24 bg-slate-100 h-3 rounded-full overflow-hidden shadow-inner border border-slate-200/50">
                          <div className="bg-blue-600 h-full shadow-[0_0_12px_rgba(37,99,235,0.4)]" style={{ width: '95%' }}></div>
                        </div>
                        <span className="text-xs font-black text-slate-900">95%</span>
                      </div>
                    </td>
                  </tr>
                ))}
                {filteredStudents.length === 0 && (
                  <tr>
                    <td colSpan={4} className="py-32 text-center text-slate-400">
                      <Users size={64} className="mx-auto mb-6 opacity-5" />
                      <p className="text-2xl font-black text-slate-900">ไม่พบระเบียนนักเรียน</p>
                      <p className="text-slate-500 font-bold mt-2">กรุณาปรับตัวกรอง หรือ เพิ่มนักเรียนใหม่</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-300">
          <div className="p-7 bg-slate-50/50 border-b border-slate-200 flex items-center justify-between">
            <h3 className="font-black text-slate-900 text-2xl flex items-center gap-4">
              <Calendar size={28} className="text-blue-600" /> 
              สมุดบันทึกรายวิชา
            </h3>
            <div className="text-right">
              <p className="text-xs font-black text-slate-500 uppercase tracking-widest">วิชาที่เลือก</p>
              <p className="text-sm font-black text-slate-900">
                {subjects.find(s => s.id === subjectId)?.name || 'กรุณาเลือกวิชา'}
              </p>
            </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-white border-b border-slate-100">
                  <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">วันที่</th>
                  <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">นักเรียน</th>
                  <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">สถานะ</th>
                  <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">หมายเหตุ</th>
                  <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">บันทึกเมื่อ</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {historyRecords.length > 0 ? (
                  historyRecords.map((record) => {
                    const student = allStudents.find(s => s.id === record.studentId);
                    return (
                      <tr key={record.id} className="hover:bg-slate-50/80 transition-colors">
                        <td className="px-10 py-6 font-black text-slate-900 text-lg whitespace-nowrap">{record.date}</td>
                        <td className="px-10 py-6">
                          <p className="font-black text-slate-900 text-lg leading-tight">{student?.name}</p>
                          <p className="text-xs text-slate-500 font-bold uppercase mt-1 tracking-widest">{student?.studentId}</p>
                        </td>
                        <td className="px-10 py-6">
                          <span className={`px-5 py-2 rounded-xl text-[11px] font-black border-2 flex items-center gap-2 w-fit ${STATUS_LABELS[record.status].color}`}>
                            {STATUS_LABELS[record.status].label}
                          </span>
                        </td>
                        <td className="px-10 py-6">
                          <p className="text-sm font-bold text-slate-900">{record.remark || '-'}</p>
                        </td>
                        <td className="px-10 py-6 text-xs font-bold text-slate-500 whitespace-nowrap">
                          {record.timestamp}
                        </td>
                      </tr>
                    );
                  })
                ) : (
                  <tr>
                    <td colSpan={5} className="py-32 text-center text-slate-400">
                      <History size={64} className="mx-auto mb-6 opacity-5" />
                      <p className="text-2xl font-black text-slate-900">ยังไม่มีข้อมูลประวัติในวิชานี้</p>
                      <p className="text-slate-500 font-bold mt-2">กรุณาเลือก รายวิชา แผนก และห้องเรียนที่ต้องการตรวจสอบ</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Modals Management */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-md">
          <div className="bg-white w-full max-w-md rounded-[48px] p-12 shadow-2xl animate-in zoom-in-95 duration-300 relative">
            <button onClick={() => setShowAddModal(null)} className="absolute top-10 right-10 text-slate-400 hover:text-slate-900 transition-colors">
              <X size={28} />
            </button>

            {showAddModal === 'STUDENT' && (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-2 text-center uppercase tracking-tight">เพิ่มนักเรียนใหม่</h3>
                <p className="text-center text-slate-500 font-bold mb-8 italic text-sm">{level} • {dept} • ห้อง {room}</p>

                <form onSubmit={handleAddStudent} className="space-y-6">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">รหัสประจำตัว</label>
                    <input 
                      type="text" required value={newStudent.studentId} 
                      onChange={(e) => setNewStudent({...newStudent, studentId: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="เช่น 661001"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ-นามสกุล</label>
                    <input 
                      type="text" required value={newStudent.name} 
                      onChange={(e) => setNewStudent({...newStudent, name: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="นายสมมติ นามสกุล"
                    />
                  </div>
                  <div className="flex gap-4 pt-4">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-[0.2em] hover:bg-slate-200 transition-colors">ยกเลิก</button>
                    <button type="submit" className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-xs tracking-[0.2em] hover:bg-blue-700 transition-colors">บันทึก</button>
                  </div>
                </form>
              </>
            )}

            {showAddModal === 'SUBJECT' && (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-8 text-center uppercase tracking-tight">เพิ่มรายวิชาใหม่</h3>
                <form onSubmit={handleAddSubject} className="space-y-6">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">รหัสวิชา</label>
                    <input 
                      type="text" required value={newSubject.code} 
                      onChange={(e) => setNewSubject({...newSubject, code: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="เช่น IT30201"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อรายวิชา</label>
                    <input 
                      type="text" required value={newSubject.name} 
                      onChange={(e) => setNewSubject({...newSubject, name: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="เช่น การเขียนโปรแกรมเว็บ"
                    />
                  </div>
                  <div className="flex gap-4 pt-4">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-[0.2em] hover:bg-slate-200 transition-colors">ยกเลิก</button>
                    <button type="submit" className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-xs tracking-[0.2em] hover:bg-blue-700 transition-colors">บันทึก</button>
                  </div>
                </form>
              </>
            )}

            {showAddModal === 'ROOM' && (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-8 text-center uppercase tracking-tight">เพิ่มห้องเรียนใหม่</h3>
                <form onSubmit={handleAddRoom} className="space-y-6">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ/หมายเลขห้อง</label>
                    <input 
                      type="text" required value={newRoomValue} 
                      onChange={(e) => setNewRoomValue(e.target.value)} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-5 font-black text-slate-900 text-xl outline-none transition-all"
                      placeholder="เช่น 4, 5 หรือ 101"
                      autoFocus
                    />
                  </div>
                  <div className="flex gap-4 pt-4">
                    <button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-[0.2em] hover:bg-slate-200 transition-colors">ยกเลิก</button>
                    <button type="submit" className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-xs tracking-[0.2em] hover:bg-blue-700 transition-colors">บันทึก</button>
                  </div>
                </form>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default ClassAttendance;

import React, { useState, useEffect } from 'react';
import { Student, Subject, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { Save, BookOpen, Clock, Users, MessageSquare, UserPlus, X, Plus, Filter, History, ClipboardCheck, Calendar, ChevronRight } from 'lucide-react';

interface ClassAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  subjects: Subject[];
  setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  currentUser: any;
}

const ClassAttendance: React.FC<ClassAttendanceProps> = ({ 
  students: allStudents, 
  setStudents,
  subjects, 
  setSubjects,
  rooms,
  setRooms,
  attendanceRecords, 
  setAttendanceRecords,
  currentUser
}) => {
  // Navigation State
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');

  // Filters State
  const [level, setLevel] = useState<string>(Object.values(ThaiLevel)[0]);
  const [dept, setDept] = useState<string>(Object.values(Department)[0]);
  const [room, setRoom] = useState(rooms.length > 0 ? rooms[0] : '1');
  const [subjectId, setSubjectId] = useState(subjects.length > 0 ? subjects[0].id : '');

  // UI State
  const [sessionAttendance, setSessionAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date());

  const [showAddModal, setShowAddModal] = useState<'STUDENT' | 'SUBJECT' | 'ROOM' | null>(null);
  const [newStudent, setNewStudent] = useState({ studentId: '', name: '' });
  const [newSubject, setNewSubject] = useState({ code: '', name: '' });
  const [newRoomValue, setNewRoomValue] = useState('');

  // Update clock every second
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Filtered Students for Current Check-in
  const filteredStudents = allStudents.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room
  );

  // Filtered History Records
  const historyRecords = attendanceRecords.filter(record => {
    const student = allStudents.find(s => s.id === record.studentId);
    return record.type === 'SUBJECT' && 
           record.subjectId === subjectId &&
           student?.level === level && 
           student?.department === dept && 
           student?.room === room;
  }).sort((a, b) => b.date.localeCompare(a.date) || b.timestamp.localeCompare(a.timestamp));

  const handleStatusChange = (id: string, status: AttendanceStatus) => {
    setSessionAttendance(prev => ({ ...prev, [id]: status }));
    if (status === 'PRESENT') {
      setRemarks(prev => {
        const next = { ...prev };
        delete next[id];
        return next;
      });
    }
  };

  const handleRemarkChange = (id: string, text: string) => {
    setRemarks(prev => ({ ...prev, [id]: text }));
  };

  const handleSave = () => {
    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    const newRecords: AttendanceRecord[] = Object.entries(sessionAttendance).map(([studentId, status]) => ({
      id: `SUBJECT_${Date.now()}_${studentId}_${subjectId}`,
      studentId,
      date: today,
      type: 'SUBJECT' as const,
      subjectId: subjectId,
      status: status as AttendanceStatus,
      remark: remarks[studentId] || '',
      timestamp
    }));

    setAttendanceRecords(prev => [...newRecords, ...prev]);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const handleAddStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStudent.studentId || !newStudent.name) return;

    const student: Student = {
      id: `STU_${Date.now()}`,
      studentId: newStudent.studentId,
      name: newStudent.name,
      level: level,
      department: dept,
      room: room,
      behaviorScore: 100
    };

    setStudents(prev => [...prev, student]);
    setNewStudent({ studentId: '', name: '' });
    setShowAddModal(null);
  };

  const handleAddSubject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newSubject.code || !newSubject.name) return;

    const subject: Subject = {
      id: `SUB_${Date.now()}`,
      code: newSubject.code,
      name: newSubject.name,
      teacherId: currentUser.id
    };

    setSubjects(prev => [...prev, subject]);
    setSubjectId(subject.id);
    setNewSubject({ code: '', name: '' });
    setShowAddModal(null);
  };

  const handleAddRoom = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newRoomValue.trim()) return;

    if (!rooms.includes(newRoomValue)) {
      setRooms(prev => [...prev, newRoomValue]);
      setRoom(newRoomValue);
    }
    setNewRoomValue('');
    setShowAddModal(null);
  };

  return (
    <div className="space-y-4 md:space-y-6 animate-in slide-in-from-bottom-4 duration-500 max-w-[1600px] mx-auto pb-20">
      {/* Navigation Tabs - Full width on Mobile */}
      <div className="flex bg-white p-1 md:p-2 rounded-2xl md:rounded-[24px] border border-slate-200 shadow-sm w-full md:w-fit overflow-hidden">
        <button 
          onClick={() => setViewMode('checkin')} 
          className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-4 md:px-8 py-3 rounded-xl md:rounded-[18px] text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <ClipboardCheck size={18} /> <span className="hidden xs:inline">เช็คชื่อ</span>
        </button>
        <button 
          onClick={() => setViewMode('history')} 
          className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-4 md:px-8 py-3 rounded-xl md:rounded-[18px] text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <History size={18} /> <span className="hidden xs:inline">ประวัติ</span>
        </button>
      </div>

      {/* Filters Header - Adaptive Grid */}
      <div className="bg-white p-4 md:p-6 rounded-[24px] md:rounded-[32px] border border-slate-200 shadow-sm">
        <div className="flex flex-col lg:flex-row gap-6 md:gap-8">
          <div className="flex-1">
            <div className="flex items-center gap-2 text-blue-600 font-black mb-4 md:mb-6 text-base md:text-lg">
              <Filter size={18} />
              <span>ตัวกรองข้อมูล</span>
            </div>

            <div className="grid grid-cols-1 xs:grid-cols-2 md:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
                <select 
                  value={level}
                  onChange={(e) => setLevel(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl md:rounded-2xl px-3 py-2.5 md:px-4 md:py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 text-sm transition-all appearance-none"
                >
                  {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
                <select 
                  value={dept}
                  onChange={(e) => setDept(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl md:rounded-2xl px-3 py-2.5 md:px-4 md:py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 text-sm transition-all appearance-none"
                >
                  {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>

              <div className="space-y-1.5">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ห้องเรียน</label>
                  <button onClick={() => setShowAddModal('ROOM')} className="text-blue-600 hover:bg-blue-50 p-1 rounded transition-colors">
                    <Plus size={14} />
                  </button>
                </div>
                <select 
                  value={room}
                  onChange={(e) => setRoom(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl md:rounded-2xl px-3 py-2.5 md:px-4 md:py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 text-sm transition-all appearance-none"
                >
                  {rooms.map(r => <option key={r} value={r}>ห้อง {r}</option>)}
                </select>
              </div>

              <div className="space-y-1.5">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">รายวิชา</label>
                  <button onClick={() => setShowAddModal('SUBJECT')} className="text-blue-600 hover:bg-blue-50 p-1 rounded transition-colors">
                    <Plus size={14} />
                  </button>
                </div>
                <select 
                  value={subjectId}
                  onChange={(e) => setSubjectId(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl md:rounded-2xl px-3 py-2.5 md:px-4 md:py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 text-sm transition-all appearance-none"
                >
                  {subjects.length === 0 && <option value="">ยังไม่มีรายวิชา</option>}
                  {subjects.map(s => <option key={s.id} value={s.id}>{s.code} - {s.name}</option>)}
                </select>
              </div>
            </div>
          </div>

          {/* Clock Info - Compact on Mobile */}
          <div className="w-full lg:w-64 xl:w-72 bg-slate-900 p-4 md:p-6 rounded-[24px] md:rounded-[32px] border border-slate-800 flex flex-row lg:flex-col items-center lg:items-start justify-between lg:justify-center shadow-xl shrink-0">
            <div className="flex items-center gap-2 text-blue-400">
              <Clock size={16} />
              <span className="text-[9px] md:text-[10px] font-black uppercase tracking-[0.2em] hidden xs:inline">เวลาปัจจุบัน</span>
            </div>
            <div className="lg:mt-2 text-right lg:text-left">
              <p className="text-2xl md:text-4xl font-black text-white tabular-nums tracking-tighter leading-none">
                {currentTime.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
              </p>
              <p className="text-[10px] md:text-xs text-slate-400 font-bold mt-1 uppercase tracking-wider hidden lg:block">
                {currentTime.toLocaleDateString('th-TH', { dateStyle: 'medium' })}
              </p>
            </div>
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <div className="bg-white rounded-[24px] md:rounded-[32px] border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-300">
          {/* List Header */}
          <div className="p-4 md:p-6 bg-slate-50/50 border-b border-slate-200 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <Users size={20} className="text-slate-900" />
              <span className="font-black text-slate-900 text-lg md:text-xl tracking-tight">นักเรียน ({filteredStudents.length})</span>
            </div>
            <div className="flex items-center gap-3 w-full sm:w-auto">
              <button 
                onClick={() => setShowAddModal('STUDENT')}
                className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-2.5 bg-blue-50 text-blue-600 rounded-xl text-xs font-black border border-blue-200 hover:bg-blue-100 transition-all"
              >
                <UserPlus size={14} /> เพิ่มรายคน
              </button>
              <button 
                onClick={handleSave}
                disabled={filteredStudents.length === 0}
                className={`flex-1 sm:flex-none px-6 py-2.5 rounded-xl text-white font-black transition-all shadow-lg flex items-center justify-center gap-2 uppercase tracking-widest text-[10px] md:text-xs ${isSaved ? 'bg-green-600 shadow-green-100' : 'bg-slate-900 shadow-slate-200 disabled:bg-slate-300 disabled:shadow-none'}`}
              >
                <Save size={16} />
                {isSaved ? 'บันทึกสำเร็จ' : 'ยืนยัน'}
              </button>
            </div>
          </div>

          {/* Student List - Card for Mobile, Table for Tablet/Desktop */}
          <div className="block md:hidden p-4 space-y-4">
            {filteredStudents.length > 0 ? (
              filteredStudents.map((student, idx) => (
                <div key={student.id} className="bg-white border-2 border-slate-100 rounded-2xl p-4 space-y-4 hover:border-blue-300 transition-all shadow-sm">
                  <div className="flex items-start justify-between">
                    <div className="flex gap-3">
                      <div className="w-10 h-10 bg-slate-900 text-white flex items-center justify-center rounded-xl font-black text-sm shrink-0">
                        {idx + 1}
                      </div>
                      <div>
                        <h4 className="font-black text-slate-900 text-base leading-tight">{student.name}</h4>
                        <p className="text-[10px] text-slate-500 font-extrabold uppercase mt-1">รหัส: {student.studentId}</p>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">สถิติ</p>
                      <p className="text-xs font-black text-blue-600">95%</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 xs:grid-cols-5 gap-2">
                    {(['PRESENT', 'LATE', 'ABSENT', 'BUSINESS_LEAVE', 'SICK_LEAVE'] as AttendanceStatus[]).map((status) => (
                      <button
                        key={status}
                        onClick={() => handleStatusChange(student.id, status)}
                        className={`
                          py-2 px-1 rounded-lg text-[9px] font-black transition-all border-2 flex flex-col items-center justify-center gap-1
                          ${sessionAttendance[student.id] === status 
                            ? STATUS_LABELS[status].color + ' border-current scale-105 shadow-sm'
                            : 'bg-white text-slate-400 border-slate-50 hover:border-slate-200'}
                        `}
                      >
                        <span className="opacity-70 scale-110">{STATUS_LABELS[status].icon}</span>
                        <span className="truncate w-full text-center">{STATUS_LABELS[status].label}</span>
                      </button>
                    ))}
                  </div>

                  {sessionAttendance[student.id] && sessionAttendance[student.id] !== 'PRESENT' && (
                    <div className="relative animate-in slide-in-from-top-1">
                      <MessageSquare className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                      <input 
                        type="text"
                        value={remarks[student.id] || ''}
                        onChange={(e) => handleRemarkChange(student.id, e.target.value)}
                        placeholder="สาเหตุ..."
                        className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-9 pr-3 py-2 text-xs font-bold text-slate-900 outline-none"
                      />
                    </div>
                  )}
                </div>
              ))
            ) : (
