        <div className="bg-slate-900 p-6 rounded-[32px] text-white shadow-xl">
          <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-50 mb-1">ผู้ใช้ทั้งหมด</p>
          <p className="text-4xl font-black">{users.length}</p>
        </div>
        <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
          <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">แอดมิน</p>
          <p className="text-4xl font-black text-indigo-600">{users.filter(u => u.role === 'ADMIN').length}</p>
        </div>
        <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
          <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">คณาจารย์</p>
          <p className="text-4xl font-black text-blue-600">{users.filter(u => u.role === 'TEACHER').length}</p>
        </div>
        <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
          <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">ผู้ปกครอง</p>
          <p className="text-4xl font-black text-pink-600">{users.filter(u => u.role === 'PARENT').length}</p>
        </div>
      </div>

      {/* Main Actions */}
      <div className="bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-6 md:p-8 bg-slate-50/50 border-b flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <Shield size={24} className="text-indigo-600" />
            <h2 className="font-black text-slate-900 text-xl tracking-tight">รายชื่อผู้ใช้งานระบบ</h2>
          </div>

          <div className="flex items-center gap-3 w-full md:w-auto">
            <div className="relative flex-1 md:w-64">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="ค้นหาชื่อ หรือ สิทธิ์..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-white border-2 border-slate-100 rounded-2xl pl-11 pr-4 py-3 text-sm font-bold text-slate-900 outline-none focus:border-indigo-500 transition-all"
              />
            </div>
            <button 
              onClick={() => setShowAddModal(true)}
              className="px-6 py-3 bg-indigo-600 text-white rounded-2xl text-sm font-black flex items-center gap-2 shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95"
            >
              <UserPlus size={18} />
              <span className="hidden sm:inline">เพิ่มผู้ใช้งาน</span>
            </button>
          </div>
        </div>

        {/* User Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white border-b border-slate-100">
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">ข้อมูลผู้ใช้งาน</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">ระดับสิทธิ์</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">การเชื่อมโยง (ลูก)</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">จัดการ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredUsers.map((u) => (
                <tr key={u.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-4">
                      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-white shadow-sm ${u.role === 'ADMIN' ? 'bg-indigo-600' : u.role === 'PARENT' ? 'bg-pink-600' : 'bg-slate-800'}`}>
                        {u.name.charAt(0)}
                      </div>
                      <div>
                        <p className="font-black text-slate-900 text-base">{u.name}</p>
                        <p className="text-xs text-slate-500 font-bold">{u.email || 'ไม่มีอีเมลสำรอง'}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-10 py-6">
                    <span className={`px-4 py-1.5 rounded-xl text-[10px] font-black border-2 uppercase tracking-widest ${getRoleBadge(u.role)}`}>
                      {u.role}
                    </span>
                  </td>
                  <td className="px-10 py-6">
                    {u.role === 'PARENT' ? (
                      <div className="flex items-center gap-2 text-pink-600">
                        <Link2 size={16} />
                        <span className="text-sm font-black">รหัส: {u.studentId || 'ยังไม่ระบุ'}</span>
                      </div>
                    ) : (
                      <p className="text-sm font-bold text-slate-400 italic">เฉพาะผู้ปกครอง</p>
                    )}
                  </td>
                  <td className="px-10 py-6 text-right">
                    <div className="flex items-center justify-end gap-2">
                      <button className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all">
                        <Edit3 size={18} />
                      </button>
                      <button 
                        onClick={() => deleteUser(u.id)}
                        className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all"
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add User Modal */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md overflow-y-auto">
          <div className="bg-white w-full max-w-md rounded-[48px] p-10 shadow-2xl animate-in zoom-in-95 relative my-8">
            <button onClick={() => setShowAddModal(false)} className="absolute top-8 right-8 text-slate-400 hover:text-slate-900 transition-colors">
              <X size={24} />
            </button>
            <h3 className="text-2xl font-black text-slate-900 mb-8 text-center uppercase tracking-tight">ลงทะเบียนผู้ใช้ใหม่</h3>

            <form onSubmit={handleAddUser} className="space-y-6">
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ-นามสกุล</label>
                <input 
                  type="text" required 
                  value={newUser.name}
                  onChange={(e) => setNewUser({...newUser, name: e.target.value})}
                  className="w-full bg-slate-50 border-2 border-slate-100 focus:border-indigo-500 rounded-2xl px-6 py-4 font-black text-slate-900 outline-none"
                  placeholder="เช่น นายมานะ อดทน"
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">สิทธิ์การเข้าใช้งาน</label>
                <select 
                  value={newUser.role}
                  onChange={(e) => setNewUser({...newUser, role: e.target.value as UserRole})}
                  className="w-full bg-slate-50 border-2 border-slate-100 focus:border-indigo-500 rounded-2xl px-6 py-4 font-black text-slate-900 outline-none appearance-none"
                >
                  <option value="TEACHER">TEACHER (อาจารย์)</option>
                  <option value="ADMIN">ADMIN (ผู้ดูแลระบบ)</option>
                  <option value="PARENT">PARENT (ผู้ปกครอง)</option>
                </select>
              </div>

              {/* แสดงฟิลด์ระบุรหัสนักเรียนเฉพาะเมื่อเลือก PARENT */}
              {newUser.role === 'PARENT' && (
                <div className="space-y-1.5 animate-in slide-in-from-top-2">
                  <label className="text-[10px] font-black text-pink-600 uppercase tracking-widest ml-1">รหัสประจำตัวนักเรียน (ลูก)</label>
                  <div className="relative">
                    <Link2 className="absolute left-5 top-1/2 -translate-y-1/2 text-pink-400" size={18} />
                    <input 
                      type="text" required 
                      value={newUser.studentId}
                      onChange={(e) => setNewUser({...newUser, studentId: e.target.value})}
                      className="w-full bg-pink-50 border-2 border-pink-100 focus:border-pink-500 rounded-2xl pl-12 pr-6 py-4 font-black text-slate-900 outline-none"
                      placeholder="เช่น 661001"
                    />
