                  <p className="text-[10px] text-slate-400 font-bold ml-1 mt-1">* ระบบจะดึงข้อมูลลูกจากรหัสนี้มาแสดงในแอปผู้ปกครอง</p>
                </div>
              )}

              {newUser.role !== 'PARENT' && (
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา/สังกัด</label>
                  <select 
                    value={newUser.department}
                    onChange={(e) => setNewUser({...newUser, department: e.target.value})}
                    className="w-full bg-slate-50 border-2 border-slate-100 focus:border-indigo-500 rounded-2xl px-6 py-4 font-black text-slate-900 outline-none appearance-none"
                  >
                    {Object.values(Department).map(d => <option key={d} value={d}>{d}</option>)}
                  </select>
