            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default UserManagement;

import React, { useState, useRef } from 'react';
import { User, UserRole, Department } from '../types';
import { 
  UserPlus, 
  Shield, 
  Trash2, 
  Edit3, 
  X, 
  Search, 
  Link2, 
  FileSpreadsheet, 
  Upload, 
  Download,
  CheckCircle2,
  AlertCircle
} from 'lucide-react';

interface UserManagementProps {
  users: any[];
  setUsers: React.Dispatch<React.SetStateAction<any[]>>;
}

const UserManagement: React.FC<UserManagementProps> = ({ users, setUsers }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showAddModal, setShowAddModal] = useState(false);
  const [importStatus, setImportStatus] = useState<{ type: 'success' | 'error'; message: string } | null>(null);

  const teacherFileInputRef = useRef<HTMLInputElement>(null);
  const parentFileInputRef = useRef<HTMLInputElement>(null);

  const [newUser, setNewUser] = useState({
    name: '',
    role: 'TEACHER' as UserRole,
    department: Object.values(Department)[0],
    email: '',
    studentId: ''
  });

  const filteredUsers = users.filter(u => 
    u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    u.role.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleAddUser = (e: React.FormEvent) => {
    e.preventDefault();
    const user = {
      id: `USR_${Date.now()}`,
      ...newUser
    };
    setUsers(prev => [...prev, user]);
    setShowAddModal(false);
    setNewUser({ name: '', role: 'TEACHER', department: Object.values(Department)[0], email: '', studentId: '' });
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, targetRole: UserRole) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const lines = text.split('\n');
        const newUsers: any[] = [];

        // Skip header line
        for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;

          const columns = line.split(',');
          if (targetRole === 'TEACHER') {
            const [name, email, department] = columns;
            if (name) {
              newUsers.push({
                id: `USR_T_${Date.now()}_${i}`,
                name: name.trim(),
                email: email?.trim() || '',
                department: department?.trim() || 'เทคโนโลยีสารสนเทศ',
                role: 'TEACHER'
              });
            }
          } else if (targetRole === 'PARENT') {
            const [name, email, studentId] = columns;
            if (name && studentId) {
              newUsers.push({
                id: `USR_P_${Date.now()}_${i}`,
                name: name.trim(),
                email: email?.trim() || '',
                studentId: studentId.trim(),
                role: 'PARENT'
              });
            }
          }
        }

        if (newUsers.length > 0) {
          setUsers(prev => [...prev, ...newUsers]);
          setImportStatus({ type: 'success', message: `นำเข้าข้อมูล ${newUsers.length} รายการสำเร็จ` });
        } else {
          setImportStatus({ type: 'error', message: 'ไม่พบข้อมูลที่ถูกต้องในไฟล์' });
        }
      } catch (err) {
        setImportStatus({ type: 'error', message: 'เกิดข้อผิดพลาดในการอ่านไฟล์' });
      } finally {
        if (e.target) e.target.value = '';
        setTimeout(() => setImportStatus(null), 4000);
      }
    };
    reader.readAsText(file);
  };

  const downloadTemplate = (role: UserRole) => {
    let headers = "";
    let example = "";

    if (role === 'TEACHER') {
      headers = "name,email,department\n";
      example = "อ.สมหมาย สายเสมอ,sommai@edu.com,เทคโนโลยีสารสนเทศ\nอ.มาลี เรียนดี,malee@edu.com,การบัญชี";
    } else {
      headers = "name,email,studentId\n";
      example = "คุณแม่ มณี,manee@home.com,661001\nคุณพ่อ ประหยัด,prayad@home.com,661002";
    }

    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" + headers + example;
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `template_users_${role.toLowerCase()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const deleteUser = (id: string) => {
    if (window.confirm('คุณต้องการลบผู้ใช้นี้ออกจากระบบหรือไม่?')) {
      setUsers(prev => prev.filter(u => u.id !== id));
    }
  };

  const getRoleBadge = (role: UserRole) => {
    switch (role) {
      case 'ADMIN': return 'bg-indigo-100 text-indigo-700 border-indigo-200';
      case 'TEACHER': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'PARENT': return 'bg-pink-100 text-pink-700 border-pink-200';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      {/* Import Section */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Teacher Import Card */}
        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex items-center gap-4 mb-6">
            <div className="p-4 bg-blue-600 rounded-[24px] text-white shadow-lg shadow-blue-100">
              <FileSpreadsheet size={24} />
            </div>
            <div>
              <h3 className="font-black text-slate-900 text-xl tracking-tight">นำเข้าอาจารย์</h3>
              <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-0.5">Bulk Teacher Import</p>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <button 
              onClick={() => teacherFileInputRef.current?.click()}
              className="flex items-center justify-center gap-3 py-4 bg-slate-50 text-slate-900 rounded-2xl font-black border-2 border-dashed border-slate-200 hover:border-blue-500 hover:bg-blue-50 transition-all text-sm"
            >
              <Upload size={18} /> อัปโหลด CSV
              <input type="file" ref={teacherFileInputRef} className="hidden" accept=".csv" onChange={(e) => handleFileUpload(e, 'TEACHER')} />
            </button>
            <button 
              onClick={() => downloadTemplate('TEACHER')}
              className="flex items-center justify-center gap-3 py-4 bg-slate-900 text-white rounded-2xl font-black hover:bg-black transition-all text-sm shadow-xl shadow-slate-200"
            >
              <Download size={18} /> เทมเพลต
            </button>
          </div>
        </div>

        {/* Parent Import Card */}
        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex items-center gap-4 mb-6">
            <div className="p-4 bg-pink-600 rounded-[24px] text-white shadow-lg shadow-pink-100">
              <UserPlus size={24} />
            </div>
            <div>
              <h3 className="font-black text-slate-900 text-xl tracking-tight">นำเข้าผู้ปกครอง</h3>
              <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-0.5">Bulk Parent Import</p>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <button 
              onClick={() => parentFileInputRef.current?.click()}
              className="flex items-center justify-center gap-3 py-4 bg-slate-50 text-slate-900 rounded-2xl font-black border-2 border-dashed border-slate-200 hover:border-pink-500 hover:bg-pink-50 transition-all text-sm"
            >
              <Upload size={18} /> อัปโหลด CSV
              <input type="file" ref={parentFileInputRef} className="hidden" accept=".csv" onChange={(e) => handleFileUpload(e, 'PARENT')} />
            </button>
            <button 
              onClick={() => downloadTemplate('PARENT')}
              className="flex items-center justify-center gap-3 py-4 bg-slate-900 text-white rounded-2xl font-black hover:bg-black transition-all text-sm shadow-xl shadow-slate-200"
            >
              <Download size={18} /> เทมเพลต
            </button>
          </div>
        </div>
      </div>

      {importStatus && (
        <div className={`p-4 rounded-[24px] flex items-center gap-3 border animate-in slide-in-from-top-4 ${importStatus.type === 'success' ? 'bg-green-50 border-green-200 text-green-800' : 'bg-red-50 border-red-200 text-red-800'}`}>
          {importStatus.type === 'success' ? <CheckCircle2 size={24} /> : <AlertCircle size={24} />}
          <p className="font-black text-sm">{importStatus.message}</p>
        </div>
      )}

      {/* Main Actions & Table */}
      <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden mt-8">
        <div className="p-6 md:p-10 bg-slate-50/50 border-b flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <Shield size={28} className="text-indigo-600" />
            <div>
              <h2 className="font-black text-slate-900 text-2xl tracking-tight">รายชื่อผู้ใช้งานระบบ</h2>
              <p className="text-sm font-bold text-slate-500">จัดการข้อมูลและระดับการเข้าถึงทั้งหมด</p>
            </div>
          </div>

          <div className="flex items-center gap-4 w-full md:w-auto">
            <div className="relative flex-1 md:w-80">
              <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
              <input 
                type="text" 
                placeholder="ค้นหาชื่อ, สิทธิ์ หรือแผนก..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full bg-white border-2 border-slate-100 rounded-[20px] pl-14 pr-6 py-4 text-sm font-bold text-slate-900 outline-none focus:border-indigo-500 transition-all shadow-inner"
              />
            </div>
            <button 
              onClick={() => setShowAddModal(true)}
              className="px-8 py-4 bg-indigo-600 text-white rounded-[20px] text-sm font-black flex items-center gap-3 shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95"
            >
              <UserPlus size={20} />
              <span className="hidden sm:inline uppercase tracking-widest text-xs">เพิ่มรายคน</span>
            </button>
          </div>
        </div>

        {/* User Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white border-b border-slate-100">
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ข้อมูลผู้ใช้งาน</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ระดับสิทธิ์</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">สังกัด/ลูก</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">จัดการ</th>
              </tr>
            </thead>
