            <button onClick={() => setShowModal(null)} className="absolute top-10 right-10 text-slate-400 hover:text-slate-900 transition-colors"><X size={28} /></button>
            <h3 className="text-3xl font-black text-slate-900 mb-10 text-center uppercase tracking-tight">
              {showModal === 'ADD' ? 'ลงทะเบียนผู้ใช้ใหม่' : 'แก้ไขข้อมูลผู้ใช้'}
            </h3>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ-นามสกุล</label>
                  <input type="text" required value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} className="w-full bg-slate-50 border-2 border-slate-100 focus:border-indigo-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none transition-all" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">สิทธิ์การใช้งาน</label>
                  <select value={formData.role} onChange={(e) => setFormData({...formData, role: e.target.value as UserRole})} className="w-full bg-slate-50 border-2 border-slate-100 focus:border-indigo-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none cursor-pointer">
                    <option value="TEACHER">TEACHER (อาจารย์)</option>
                    <option value="ADMIN">ADMIN (ผู้ดูแลระบบ)</option>
                    <option value="PARENT">PARENT (ผู้ปกครอง)</option>
