  const [reportDept, setReportDept] = useState<string>(Object.values(Department)[0]);
  const [reportRoom, setReportRoom] = useState<string>('1');
  const [reportDate, setReportDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [reportMonth, setReportMonth] = useState<number>(new Date().getMonth());
  const [reportYear, setReportYear] = useState<number>(new Date().getFullYear());
  const [roomViewMode, setRoomViewMode] = useState<'daily' | 'monthly'>('daily');

