                        const dayAtt = attendance.find(a => a.studentId === s.id && a.date === reportDate && a.type === 'MORNING');
                        return (
                          <tr key={s.id} className="hover:bg-slate-50/50 transition-colors">
                            <td className="px-10 py-6 font-bold text-slate-500">{s.studentId}</td>
                            <td className="px-10 py-6 font-black text-slate-900 text-lg">{s.name}</td>
                            <td className="px-10 py-6">
                              {dayAtt ? (
                                <span className={`px-4 py-1.5 rounded-full text-[11px] font-black border-2 ${STATUS_LABELS[dayAtt.status].color}`}>
                                  {STATUS_LABELS[dayAtt.status].label}
                                </span>
                              ) : <span className="text-slate-300 font-bold">- ไม่มีข้อมูล -</span>}
                            </td>
                            <td className="px-10 py-6 text-sm font-bold text-slate-500">{dayAtt?.remark || '-'}</td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                ) : (
                  /* Monthly Matrix View */
                  <table className="w-full text-left border-collapse">
                    <thead>
                      <tr className="bg-slate-900 text-white">
                        <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest sticky left-0 z-10 bg-slate-900 min-w-[220px]">รายชื่อนักเรียน</th>
                        {Array.from({ length: getDaysInMonth(reportMonth, reportYear) }).map((_, i) => (
                          <th key={i} className="px-3 py-5 text-[10px] font-black text-center min-w-[40px] border-l border-slate-800">{i + 1}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {roomStudents.map(s => (
                        <tr key={s.id} className="hover:bg-slate-50 group">
                          <td className="px-6 py-5 font-black text-slate-900 text-sm sticky left-0 z-10 bg-white group-hover:bg-slate-50 border-r border-slate-100 shadow-[2px_0_5px_rgba(0,0,0,0.05)]">
                            {s.name}
                            <p className="text-[10px] font-bold text-slate-400 mt-0.5">{s.studentId}</p>
                          </td>
                          {Array.from({ length: getDaysInMonth(reportMonth, reportYear) }).map((_, i) => {
                            const dateStr = `${reportYear}-${String(reportMonth + 1).padStart(2, '0')}-${String(i + 1).padStart(2, '0')}`;
                            const att = attendance.find(a => a.studentId === s.id && a.date === dateStr && a.type === 'MORNING');
                            return (
                              <td key={i} className="p-1 border-l border-slate-50 text-center">
                                <div className={`w-8 h-8 flex items-center justify-center rounded-lg text-xs font-black mx-auto transition-transform ${getStatusColorClass(att?.status || '')}`}>
                                  {getStatusInitial(att?.status || '')}
                                </div>
                              </td>
                            );
                          })}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                )}
              </div>

              {/* Legend for Monthly View */}
              {roomViewMode === 'monthly' && (
                <div className="p-8 bg-slate-50 border-t border-slate-100">
                   <div className="flex flex-wrap gap-8">
                     {Object.entries(STATUS_LABELS).map(([key, val]) => (
                       <div key={key} className="flex items-center gap-3">
                         <div className={`w-8 h-8 flex items-center justify-center rounded-lg text-xs font-black ${getStatusColorClass(key)}`}>
                            {getStatusInitial(key)}
                         </div>
                         <span className="text-xs font-black text-slate-700 uppercase tracking-widest">{val.label}</span>
                       </div>
                     ))}
                   </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Reports;

import React, { useState, useMemo } from 'react';
import { 
  Users, 
  CheckCircle, 
  AlertTriangle, 
  TrendingUp,
  Award,
  Heart,
  CalendarDays,
  Search,
  ArrowLeft,
  User,
  Activity,
  Filter,
  Calendar,
  Layers
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, LineChart, Line } from 'recharts';
import { Student, AttendanceRecord, ThaiLevel, Department } from '../types';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  user: any;
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex items-start justify-between hover:shadow-md transition-shadow group">
    <div className="space-y-2">
      <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em]">{title}</p>
      <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'}`}>{value}</h3>
      <p className="text-xs text-slate-400 font-bold">{sub}</p>
    </div>
    <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
      {icon}
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ students, attendance, behavior, user }) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // New Filter States
  const [selectedLevel, setSelectedLevel] = useState<string>('ALL');
  const [selectedDept, setSelectedDept] = useState<string>('ALL');
  const [selectedRoom, setSelectedRoom] = useState<string>('ALL');
  const [timeframe, setTimeframe] = useState<'daily' | 'weekly' | 'monthly'>('weekly');

  // Logic to filter students based on Room Selection
  const filteredStudentsByRoom = useMemo(() => {
    return students.filter(s => {
      const levelMatch = selectedLevel === 'ALL' || s.level === selectedLevel;
      const deptMatch = selectedDept === 'ALL' || s.department === selectedDept;
      const roomMatch = selectedRoom === 'ALL' || s.room === selectedRoom;
      return levelMatch && deptMatch && roomMatch;
    });
  }, [students, selectedLevel, selectedDept, selectedRoom]);

  const studentIdsInRoom = useMemo(() => filteredStudentsByRoom.map(s => s.id), [filteredStudentsByRoom]);

  // Individual Student View
  const renderIndividualView = (studentId: string) => {
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return null;

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;
    const latestBehavior = behavior.filter(b => b.studentId === student.id).slice(0, 5);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between gap-4">
          <button 
            onClick={() => setViewingStudentId(null)}
            className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-black text-sm hover:bg-slate-50 transition-all shadow-sm"
          >
            <ArrowLeft size={18} /> กลับสู่ภาพรวม
          </button>
          <div className="flex items-center gap-3 text-right">
            <div>
              <p className="text-xs font-black text-slate-400 uppercase tracking-widest">มุมมองรายบุคคล</p>
              <p className="text-lg font-black text-slate-900">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-100">
              <User size={24} />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard 
            title="เปอร์เซ็นต์การมาเรียน" 
            value={`${attRate}%`} 
            sub={`จากทั้งหมด ${studentAttendance.length} ครั้ง`} 
            icon={<TrendingUp size={28} />} 
            color="bg-blue-600"
            textColor="text-blue-600"
          />
          <StatCard 
            title="คะแนนพฤติกรรม" 
            value={student.behaviorScore} 
            sub="สถานะ: ปกติ" 
            icon={<Heart size={28} />} 
            color="bg-pink-600"
            textColor="text-pink-600"
          />
          <StatCard 
            title="ระดับชั้น" 
            value={student.level} 
            sub={student.department} 
            icon={<Activity size={28} />} 
            color="bg-indigo-600"
            textColor="text-indigo-600"
          />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-black text-slate-900 text-xl mb-8 flex items-center gap-3">
              <TrendingUp size={24} className="text-blue-600" />
              กราฟการมาเรียนย้อนหลัง
            </h3>
            <div className="h-[300px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={studentAttendance.slice(-7).map(a => ({ name: a.date, val: a.status === 'PRESENT' ? 100 : 0 }))}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 700}} />
                  <YAxis hide />
                  <Tooltip 
                    cursor={{fill: '#f8fafc'}}
                    contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                  />
                  <Bar dataKey="val" fill="#2563eb" radius={[10, 10, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-black text-slate-900 text-xl mb-6 flex items-center gap-3">
              <Award size={24} className="text-indigo-600" />
              บันทึกพฤติกรรมล่าสุด
            </h3>
            <div className="space-y-4">
              {latestBehavior.length > 0 ? latestBehavior.map(b => (
                <div key={b.id} className="p-4 bg-slate-50 rounded-2xl flex items-center justify-between border border-slate-100">
                   <div>
                     <p className="font-black text-slate-900 text-sm">{b.reason}</p>
                     <p className="text-[10px] font-bold text-slate-500 uppercase mt-1 tracking-widest">{b.date}</p>
                   </div>
                   <span className={`font-black text-lg ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                     {b.type === 'ADD' ? '+' : '-'}{b.score}
                   </span>
                </div>
              )) : (
                <div className="py-20 text-center flex flex-col items-center opacity-30">
                  <Heart size={48} className="mb-2" />
                  <p className="font-bold">ยังไม่มีบันทึกพฤติกรรม</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  };

  if (user.role === 'PARENT') {
    return renderIndividualView(user.studentId);
  }

  if (viewingStudentId) {
    return renderIndividualView(viewingStudentId);
  }

  // --- OVERVIEW / ROOM VIEW LOGIC ---

  // Calculate stats based on filtered room and timeframe
  const today = new Date().toISOString().split('T')[0];
  const roomAttendance = attendance.filter(a => studentIdsInRoom.includes(a.studentId));

  const todayRoomAtt = roomAttendance.filter(a => a.date === today && a.type === 'MORNING');
  const presentTodayCount = todayRoomAtt.filter(a => a.status === 'PRESENT').length;
  const attendanceRate = todayRoomAtt.length > 0 ? Math.round((presentTodayCount / todayRoomAtt.length) * 100) : 0;

  const avgBehavior = filteredStudentsByRoom.length > 0 
    ? Math.round(filteredStudentsByRoom.reduce((acc, s) => acc + s.behaviorScore, 0) / filteredStudentsByRoom.length)
    : 0;

  // Chart Data Generation based on Timeframe
  const getChartData = () => {
    if (timeframe === 'monthly') {
      return [
        { name: 'สัปดาห์ 1', count: 92 },
        { name: 'สัปดาห์ 2', count: 88 },
        { name: 'สัปดาห์ 3', count: 95 },
        { name: 'สัปดาห์ 4', count: attendanceRate || 90 },
      ];
    }
    // Default / Weekly
    return [
      { name: 'จ.', count: 95 },
      { name: 'อ.', count: 92 },
      { name: 'พ.', count: 88 },
      { name: 'พฤ.', count: 94 },
      { name: 'ศ.', count: attendanceRate || 85 },
    ];
  };

  const behaviorDist = [
    { name: 'ดีมาก (90+)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 90).length, color: '#16a34a' },
    { name: 'ปกติ (70-89)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 70 && s.behaviorScore < 90).length, color: '#2563eb' },
    { name: 'เฝ้าระวัง (<70)', value: filteredStudentsByRoom.filter(s => s.behaviorScore < 70).length, color: '#dc2626' },
  ];

  const searchResults = searchTerm.trim() 
    ? students.filter(s => s.name.includes(searchTerm) || s.studentId.includes(searchTerm)).slice(0, 5)
    : [];

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Header with Search & Filter Toggle */}
      <div className="flex flex-col xl:flex-row gap-6">
        <div className="relative flex-1 group">
          <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600 transition-colors">
            <Search size={22} />
          </div>
          <input 
            type="text" 
            placeholder="ค้นหานักเรียนรายบุคคลเพื่อดูข้อมูลเชิงลึก... (ชื่อ หรือ รหัส)" 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border-2 border-slate-100 rounded-[28px] pl-16 pr-6 py-5 text-lg font-black text-slate-900 outline-none focus:border-blue-500 shadow-xl shadow-slate-100/50"
          />

          {searchResults.length > 0 && (
            <div className="absolute top-full left-0 right-0 mt-3 bg-white border border-slate-200 rounded-[32px] shadow-2xl z-50 overflow-hidden animate-in slide-in-from-top-4">
              {searchResults.map(s => (
                <button 
                  key={s.id}
                  onClick={() => { setViewingStudentId(s.id); setSearchTerm(''); }}
                  className="w-full flex items-center justify-between px-8 py-5 hover:bg-blue-50 transition-all border-b border-slate-50 last:border-0 text-left group"
                >
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-slate-900 rounded-xl flex items-center justify-center text-white font-black group-hover:bg-blue-600">{s.name.charAt(0)}</div>
                    <div>
                      <p className="font-black text-slate-900 text-lg">{s.name}</p>
                      <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">{s.studentId} • {s.level}</p>
                    </div>
                  </div>
                  <ArrowLeft size={20} className="rotate-180 text-slate-300 group-hover:text-blue-600 group-hover:translate-x-1 transition-all" />
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Timeframe Toggle */}
        <div className="flex bg-white p-2 rounded-[28px] border-2 border-slate-100 shadow-sm self-start">
          <button onClick={() => setTimeframe('daily')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'daily' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายวัน</button>
          <button onClick={() => setTimeframe('weekly')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'weekly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายสัปดาห์</button>
          <button onClick={() => setTimeframe('monthly')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'monthly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายเดือน</button>
        </div>
      </div>

      {/* Room Selection Filters */}
      <div className="bg-white p-6 rounded-[32px] border-2 border-slate-100 shadow-sm">
        <div className="flex items-center gap-3 mb-6 px-2">
          <Layers size={20} className="text-indigo-600" />
          <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest">กรองข้อมูลรายห้องเรียน</h4>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">ระดับชั้น</label>
            <select value={selectedLevel} onChange={(e) => setSelectedLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all cursor-pointer">
              <option value="ALL">ทุกระดับชั้น</option>
              {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">แผนกวิชา</label>
            <select value={selectedDept} onChange={(e) => setSelectedDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all cursor-pointer">
              <option value="ALL">ทุกแผนกวิชา</option>
              {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">ห้อง</label>
            <select value={selectedRoom} onChange={(e) => setSelectedRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-indigo-500 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all cursor-pointer">
              <option value="ALL">ทุกห้อง</option>
              {['1', '2', '3', '4', '5'].map(v => <option key={v} value={v}>ห้อง {v}</option>)}
            </select>
          </div>
        </div>
      </div>

      {/* Main Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="นักเรียนในกลุ่ม" 
          value={filteredStudentsByRoom.length} 
          sub="จำนวนที่ลงทะเบียน" 
          icon={<Users size={28} />} 
          color="bg-slate-900"
        />
        <StatCard 
          title={`การมาเรียน (${timeframe === 'daily' ? 'วันนี้' : timeframe === 'weekly' ? 'สัปดาห์นี้' : 'เดือนนี้'})`} 
          value={`${attendanceRate}%`} 
          sub={timeframe === 'daily' ? `มาแล้ว ${presentTodayCount} คน` : 'จากค่าเฉลี่ย'} 
          icon={<CheckCircle size={28} />} 
          color="bg-blue-600"
          textColor="text-blue-600"
        />
        <StatCard 
          title="เฝ้าระวังพฤติกรรม" 
          value={filteredStudentsByRoom.filter(s => s.behaviorScore < 70).length} 
          sub="คะแนนต่ำกว่าเกณฑ์" 
          icon={<AlertTriangle size={28} />} 
          color="bg-orange-600"
          textColor="text-orange-600"
        />
        <StatCard 
          title="คะแนนเฉลี่ยกลุ่ม" 
          value={avgBehavior} 
          sub="พฤติกรรมภาพรวม" 
          icon={<Award size={28} />} 
          color="bg-indigo-600"
          textColor="text-indigo-600"
        />
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex items-center justify-between mb-8">
            <h3 className="font-black text-slate-900 text-xl flex items-center gap-3">
              <TrendingUp size={24} className="text-blue-600" />
              แนวโน้มการมาเรียน ({timeframe === 'monthly' ? 'รายเดือน' : 'รายสัปดาห์'})
            </h3>
          </div>
          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={getChartData()}>
                <CartesianGrid strokeDasharray="4 4" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} domain={[0, 100]} dx={-10} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                />
                <Bar dataKey="count" fill="#2563eb" radius={[12, 12, 0, 0]} barSize={timeframe === 'monthly' ? 80 : 50}>
                  {getChartData().map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index === getChartData().length - 1 ? '#2563eb' : '#cbd5e1'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h3 className="font-black text-slate-900 text-xl mb-8 flex items-center gap-3">
            <Award size={24} className="text-indigo-600" />
            ระดับพฤติกรรมในกลุ่ม
          </h3>
          <div className="h-[280px] w-full relative">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={behaviorDist} innerRadius={75} outerRadius={105} paddingAngle={10} dataKey="value">
                  {behaviorDist.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
              <span className="text-4xl font-black text-slate-900">{filteredStudentsByRoom.length}</span>
              <span className="text-[10px] text-slate-400 font-extrabold uppercase tracking-widest">นักเรียน</span>
            </div>
          </div>
          <div className="mt-8 space-y-4">
            {behaviorDist.map((item) => (
              <div key={item.name} className="flex items-center justify-between p-3 rounded-2xl bg-slate-50 border border-slate-100">
                <div className="flex items-center gap-3">
                  <div className="w-3 h-3 rounded-full" style={{backgroundColor: item.color}} />
                  <span className="text-slate-700 font-bold text-xs">{item.name}</span>
                </div>
                <span className="font-black text-slate-900 text-sm">{item.value} คน</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

