              <PieChart>
                <Pie data={behaviorDist} innerRadius={75} outerRadius={105} paddingAngle={10} dataKey="value">
                  {behaviorDist.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
              <span className="text-4xl font-black text-slate-900">{filteredStudentsByRoom.length}</span>
              <span className="text-[10px] text-slate-400 font-extrabold uppercase tracking-widest">นักเรียน</span>
            </div>
          </div>
          <div className="mt-8 space-y-4">
            {behaviorDist.map((item) => (
              <div key={item.name} className="flex items-center justify-between p-3 rounded-2xl bg-slate-50 border border-slate-100">
                <div className="flex items-center gap-3">
                  <div className="w-3 h-3 rounded-full" style={{backgroundColor: item.color}} />
                  <span className="text-slate-700 font-bold text-xs">{item.name}</span>
                </div>
                <span className="font-black text-slate-900 text-sm">{item.value} คน</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  Users, 
  CheckCircle, 
  AlertTriangle, 
  TrendingUp,
  Award,
  Heart,
  CalendarDays,
  Search,
  ArrowLeft,
  User,
  Activity,
  Filter,
  Calendar,
  Layers,
  ChevronLeft,
  ChevronRight
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { Student, AttendanceRecord, ThaiLevel, Department } from '../types';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  user: any;
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex items-start justify-between hover:shadow-md transition-shadow group">
    <div className="space-y-2">
      <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em]">{title}</p>
      <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'}`}>{value}</h3>
      <p className="text-xs text-slate-400 font-bold">{sub}</p>
    </div>
    <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
      {icon}
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ students, attendance, behavior, user }) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Filter States
  const [selectedLevel, setSelectedLevel] = useState<string>('ALL');
  const [selectedDept, setSelectedDept] = useState<string>('ALL');
  const [selectedRoom, setSelectedRoom] = useState<string>('ALL');
  const [timeframe, setTimeframe] = useState<'daily' | 'weekly' | 'monthly'>('weekly');

  // Period Selection States
  const [targetDate, setTargetDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [targetMonth, setTargetMonth] = useState<number>(new Date().getMonth());
  const [targetYear, setTargetYear] = useState<number>(new Date().getFullYear());

  const months = [
    "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
    "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
  ];

  // Logic to filter students based on Room Selection
  const filteredStudentsByRoom = useMemo(() => {
    return students.filter(s => {
      const levelMatch = selectedLevel === 'ALL' || s.level === selectedLevel;
      const deptMatch = selectedDept === 'ALL' || s.department === selectedDept;
      const roomMatch = selectedRoom === 'ALL' || s.room === selectedRoom;
      return levelMatch && deptMatch && roomMatch;
    });
  }, [students, selectedLevel, selectedDept, selectedRoom]);

  const studentIdsInRoom = useMemo(() => filteredStudentsByRoom.map(s => s.id), [filteredStudentsByRoom]);

  // Individual Student View
  const renderIndividualView = (studentId: string) => {
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return null;

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;
    const latestBehavior = behavior.filter(b => b.studentId === student.id).slice(0, 5);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between gap-4">
          <button 
            onClick={() => setViewingStudentId(null)}
            className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-black text-sm hover:bg-slate-50 transition-all shadow-sm"
          >
            <ArrowLeft size={18} /> กลับสู่ภาพรวม
          </button>
          <div className="flex items-center gap-3 text-right">
            <div>
              <p className="text-xs font-black text-slate-400 uppercase tracking-widest">มุมมองรายบุคคล</p>
              <p className="text-lg font-black text-slate-900">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-100">
              <User size={24} />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard 
            title="เปอร์เซ็นต์การมาเรียน" 
            value={`${attRate}%`} 
            sub={`จากทั้งหมด ${studentAttendance.length} ครั้ง`} 
            icon={<TrendingUp size={28} />} 
            color="bg-blue-600"
            textColor="text-blue-600"
          />
          <StatCard 
            title="คะแนนพฤติกรรม" 
            value={student.behaviorScore} 
            sub="สถานะ: ปกติ" 
            icon={<Heart size={28} />} 
            color="bg-pink-600"
            textColor="text-pink-600"
          />
          <StatCard 
            title="ระดับชั้น" 
            value={student.level} 
            sub={student.department} 
            icon={<Activity size={28} />} 
            color="bg-indigo-600"
            textColor="text-indigo-600"
          />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-black text-slate-900 text-xl mb-8 flex items-center gap-3">
              <TrendingUp size={24} className="text-blue-600" />
              กราฟการมาเรียนย้อนหลัง
            </h3>
            <div className="h-[300px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={studentAttendance.slice(-7).map(a => ({ name: a.date, val: a.status === 'PRESENT' ? 100 : 0 }))}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 700}} />
                  <YAxis hide />
                  <Tooltip 
                    cursor={{fill: '#f8fafc'}}
                    contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                  />
                  <Bar dataKey="val" fill="#2563eb" radius={[10, 10, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-black text-slate-900 text-xl mb-6 flex items-center gap-3">
              <Award size={24} className="text-indigo-600" />
              บันทึกพฤติกรรมล่าสุด
            </h3>
            <div className="space-y-4">
              {latestBehavior.length > 0 ? latestBehavior.map(b => (
                <div key={b.id} className="p-4 bg-slate-50 rounded-2xl flex items-center justify-between border border-slate-100">
                   <div>
                     <p className="font-black text-slate-900 text-sm">{b.reason}</p>
                     <p className="text-[10px] font-bold text-slate-500 uppercase mt-1 tracking-widest">{b.date}</p>
                   </div>
                   <span className={`font-black text-lg ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                     {b.type === 'ADD' ? '+' : '-'}{b.score}
                   </span>
                </div>
              )) : (
                <div className="py-20 text-center flex flex-col items-center opacity-30">
                  <Heart size={48} className="mb-2" />
                  <p className="font-bold">ยังไม่มีบันทึกพฤติกรรม</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  };

  if (user.role === 'PARENT') {
    return renderIndividualView(user.studentId);
  }

  if (viewingStudentId) {
    return renderIndividualView(viewingStudentId);
  }

  // --- OVERVIEW / ROOM VIEW LOGIC ---

  // Calculate stats based on filtered room and timeframe
  const roomAttendance = attendance.filter(a => studentIdsInRoom.includes(a.studentId));

  // Filter attendance by Target Date/Period
  const periodAttendance = useMemo(() => {
    if (timeframe === 'daily') {
      return roomAttendance.filter(a => a.date === targetDate && a.type === 'MORNING');
    } else if (timeframe === 'monthly') {
      return roomAttendance.filter(a => {
        const d = new Date(a.date);
        return d.getMonth() === targetMonth && d.getFullYear() === targetYear && a.type === 'MORNING';
      });
    }
    // Weekly - approximate logic (last 7 days from target date)
    const end = new Date(targetDate);
    const start = new Date(targetDate);
    start.setDate(end.getDate() - 6);
    return roomAttendance.filter(a => {
      const d = new Date(a.date);
      return d >= start && d <= end && a.type === 'MORNING';
    });
  }, [roomAttendance, targetDate, targetMonth, targetYear, timeframe]);

  const presentCount = periodAttendance.filter(a => a.status === 'PRESENT').length;
  const attendanceRate = periodAttendance.length > 0 ? Math.round((presentCount / periodAttendance.length) * 100) : 0;

  const avgBehavior = filteredStudentsByRoom.length > 0 
    ? Math.round(filteredStudentsByRoom.reduce((acc, s) => acc + s.behaviorScore, 0) / filteredStudentsByRoom.length)
    : 0;

  // Chart Data Generation based on Timeframe
  const getChartData = () => {
    if (timeframe === 'monthly') {
      return [
        { name: 'สัปดาห์ 1', count: 92 },
        { name: 'สัปดาห์ 2', count: 88 },
        { name: 'สัปดาห์ 3', count: 95 },
        { name: 'สัปดาห์ 4', count: attendanceRate || 90 },
      ];
    }
    if (timeframe === 'daily') {
      const d = new Date(targetDate);
      const labels = [];
      for (let i = 6; i >= 0; i--) {
        const temp = new Date(targetDate);
        temp.setDate(d.getDate() - i);
        labels.push(`${temp.getDate()} ${months[temp.getMonth()].substring(0, 3)}.`);
      }
      return labels.map((label, idx) => ({
        name: label,
        count: idx === 6 ? (attendanceRate || 95) : Math.floor(Math.random() * 15) + 85
      }));
    }
    // Default / Weekly
    return [
      { name: 'จ.', count: 95 },
      { name: 'อ.', count: 92 },
      { name: 'พ.', count: 88 },
      { name: 'พฤ.', count: 94 },
      { name: 'ศ.', count: attendanceRate || 85 },
    ];
  };

  const behaviorDist = [
    { name: 'ดีมาก (90+)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 90).length, color: '#16a34a' },
    { name: 'ปกติ (70-89)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 70 && s.behaviorScore < 90).length, color: '#2563eb' },
    { name: 'เฝ้าระวัง (<70)', value: filteredStudentsByRoom.filter(s => s.behaviorScore < 70).length, color: '#dc2626' },
  ];

  const searchResults = searchTerm.trim() 
    ? students.filter(s => s.name.includes(searchTerm) || s.studentId.includes(searchTerm)).slice(0, 5)
    : [];

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Search & Main Timeframe */}
      <div className="flex flex-col xl:flex-row gap-6">
        <div className="relative flex-1 group">
          <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600 transition-colors">
            <Search size={22} />
          </div>
          <input 
            type="text" 
            placeholder="ค้นหานักเรียนรายบุคคลเพื่อดูข้อมูลเชิงลึก..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border-2 border-slate-100 rounded-[28px] pl-16 pr-6 py-5 text-lg font-black text-slate-900 outline-none focus:border-blue-500 shadow-xl shadow-slate-100/50"
          />

          {searchResults.length > 0 && (
            <div className="absolute top-full left-0 right-0 mt-3 bg-white border border-slate-200 rounded-[32px] shadow-2xl z-50 overflow-hidden animate-in slide-in-from-top-4">
              {searchResults.map(s => (
                <button 
                  key={s.id}
                  onClick={() => { setViewingStudentId(s.id); setSearchTerm(''); }}
                  className="w-full flex items-center justify-between px-8 py-5 hover:bg-blue-50 transition-all border-b border-slate-50 last:border-0 text-left group"
                >
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-slate-900 rounded-xl flex items-center justify-center text-white font-black group-hover:bg-blue-600">{s.name.charAt(0)}</div>
                    <div>
                      <p className="font-black text-slate-900 text-lg">{s.name}</p>
                      <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">{s.studentId} • {s.level}</p>
                    </div>
                  </div>
                  <ArrowLeft size={20} className="rotate-180 text-slate-300 group-hover:text-blue-600 transition-all" />
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="flex bg-white p-2 rounded-[28px] border-2 border-slate-100 shadow-sm self-start">
          <button onClick={() => setTimeframe('daily')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'daily' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายวัน</button>
          <button onClick={() => setTimeframe('weekly')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'weekly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายสัปดาห์</button>
          <button onClick={() => setTimeframe('monthly')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'monthly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายเดือน</button>
        </div>
      </div>

      {/* Advanced Filter Section with Date Picker */}
      <div className="bg-white p-8 rounded-[40px] border-2 border-slate-100 shadow-sm">
        <div className="flex flex-col lg:flex-row items-end gap-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-1 w-full">
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">ระดับชั้น</label>
              <select value={selectedLevel} onChange={(e) => setSelectedLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all">
                <option value="ALL">ทุกระดับชั้น</option>
                {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">แผนกวิชา</label>
              <select value={selectedDept} onChange={(e) => setSelectedDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all">
                <option value="ALL">ทุกแผนกวิชา</option>
                {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">ห้อง</label>
              <select value={selectedRoom} onChange={(e) => setSelectedRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all">
                <option value="ALL">ทุกห้อง</option>
                {['1', '2', '3', '4', '5'].map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
          </div>

          {/* Period Selector Component */}
          <div className="w-full lg:w-fit p-4 bg-slate-50 rounded-3xl border border-slate-100 flex items-center justify-between gap-4">
             <div className="flex items-center gap-3">
               <Calendar size={20} className="text-blue-600" />
               {timeframe === 'monthly' ? (
                 <div className="flex gap-2">
                    <select value={targetMonth} onChange={(e) => setTargetMonth(parseInt(e.target.value))} className="bg-transparent font-black text-slate-900 outline-none text-sm">
                      {months.map((m, i) => <option key={m} value={i}>{m}</option>)}
                    </select>
                    <select value={targetYear} onChange={(e) => setTargetYear(parseInt(e.target.value))} className="bg-transparent font-black text-slate-900 outline-none text-sm">
                      {[2024, 2025].map(y => <option key={y} value={y}>{y}</option>)}
                    </select>
                 </div>
               ) : (
                 <input 
                  type="date" 
                  value={targetDate} 
                  onChange={(e) => setTargetDate(e.target.value)} 
                  className="bg-transparent font-black text-slate-900 outline-none text-sm cursor-pointer" 
                 />
               )}
             </div>
             {timeframe === 'weekly' && (
               <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest border-l pl-4 border-slate-200">
                 สถิติจนถึงวันที่เลือก
               </div>
             )}
          </div>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="นักเรียนในกลุ่ม" 
          value={filteredStudentsByRoom.length} 
          sub="จำนวนที่ลงทะเบียน" 
          icon={<Users size={28} />} 
          color="bg-slate-900"
        />
        <StatCard 
          title="เปอร์เซ็นต์การมาเรียน" 
          value={`${attendanceRate}%`} 
          sub={timeframe === 'daily' ? `มาแล้ว ${presentCount} คน` : timeframe === 'weekly' ? 'สถิติ 7 วันย้อนหลัง' : `สถิติเดือน ${months[targetMonth]}`} 
          icon={<CheckCircle size={28} />} 
          color="bg-blue-600"
          textColor="text-blue-600"
        />
        <StatCard 
          title="เฝ้าระวังพฤติกรรม" 
          value={filteredStudentsByRoom.filter(s => s.behaviorScore < 70).length} 
          sub="คะแนนต่ำกว่าเกณฑ์" 
          icon={<AlertTriangle size={28} />} 
          color="bg-orange-600"
          textColor="text-orange-600"
        />
        <StatCard 
          title="คะแนนเฉลี่ยกลุ่ม" 
          value={avgBehavior} 
          sub="ความประพฤติภาพรวม" 
          icon={<Award size={28} />} 
          color="bg-indigo-600"
          textColor="text-indigo-600"
        />
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h3 className="font-black text-slate-900 text-xl flex items-center gap-3 mb-8">
            <TrendingUp size={24} className="text-blue-600" />
            แนวโน้มการมาเรียน ({timeframe === 'monthly' ? 'รายเดือน' : timeframe === 'weekly' ? 'รายสัปดาห์' : 'รายวัน'})
          </h3>
          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={getChartData()}>
                <CartesianGrid strokeDasharray="4 4" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} domain={[0, 100]} dx={-10} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                />
                <Bar dataKey="count" fill="#2563eb" radius={[12, 12, 0, 0]} barSize={timeframe === 'monthly' ? 80 : 50}>
                  {getChartData().map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index === getChartData().length - 1 ? '#2563eb' : '#cbd5e1'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h3 className="font-black text-slate-900 text-xl mb-8 flex items-center gap-3">
            <Award size={24} className="text-indigo-600" />
            ระดับพฤติกรรมในกลุ่ม
          </h3>
          <div className="h-[280px] w-full relative">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={behaviorDist} innerRadius={75} outerRadius={105} paddingAngle={10} dataKey="value">
                  {behaviorDist.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
              <span className="text-4xl font-black text-slate-900">{filteredStudentsByRoom.length}</span>
              <span className="text-[10px] text-slate-400 font-extrabold uppercase tracking-widest">นักเรียน</span>
            </div>
          </div>
          <div className="mt-8 space-y-4">
            {behaviorDist.map((item) => (
              <div key={item.name} className="flex items-center justify-between p-3 rounded-2xl bg-slate-50 border border-slate-100">
                <div className="flex items-center gap-3">
                  <div className="w-3 h-3 rounded-full" style={{backgroundColor: item.color}} />
                  <span className="text-slate-700 font-bold text-xs">{item.name}</span>
                </div>
                <span className="font-black text-slate-900 text-sm">{item.value} คน</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  Users, 
  CheckCircle, 
  AlertTriangle, 
  TrendingUp,
  Award,
  Heart,
  CalendarDays,
  Search,
  ArrowLeft,
  User,
  Activity,
  Filter,
  Calendar,
  Layers,
  ChevronLeft,
  ChevronRight
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { Student, AttendanceRecord, ThaiLevel, Department, AttendanceStatus } from '../types';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  user: any;
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex items-start justify-between hover:shadow-md transition-shadow group">
    <div className="space-y-2">
      <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em]">{title}</p>
      <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'}`}>{value}</h3>
      <p className="text-xs text-slate-400 font-bold">{sub}</p>
    </div>
    <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
      {icon}
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ students, attendance, behavior, user }) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Filter States
  const [selectedLevel, setSelectedLevel] = useState<string>('ALL');
  const [selectedDept, setSelectedDept] = useState<string>('ALL');
  const [selectedRoom, setSelectedRoom] = useState<string>('ALL');
  const [timeframe, setTimeframe] = useState<'daily' | 'weekly' | 'monthly'>('weekly');

  // Period Selection States
  const [targetDate, setTargetDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [targetMonth, setTargetMonth] = useState<number>(new Date().getMonth());
  const [targetYear, setTargetYear] = useState<number>(new Date().getFullYear());

  const months = [
    "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
    "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
  ];

  const daysOfWeek = ["อา.", "จ.", "อ.", "พ.", "พฤ.", "ศ.", "ส."];

  // Logic to filter students based on Room Selection
  const filteredStudentsByRoom = useMemo(() => {
    return students.filter(s => {
      const levelMatch = selectedLevel === 'ALL' || s.level === selectedLevel;
      const deptMatch = selectedDept === 'ALL' || s.department === selectedDept;
      const roomMatch = selectedRoom === 'ALL' || s.room === selectedRoom;
      return levelMatch && deptMatch && roomMatch;
    });
  }, [students, selectedLevel, selectedDept, selectedRoom]);

  const studentIdsInRoom = useMemo(() => filteredStudentsByRoom.map(s => s.id), [filteredStudentsByRoom]);

  // All attendance for this filtered group
  const roomAttendance = useMemo(() => 
    attendance.filter(a => studentIdsInRoom.includes(a.studentId)), 
    [attendance, studentIdsInRoom]
  );

  // Helper to calculate percentage for a specific set of records
  const calculateRate = (records: AttendanceRecord[]) => {
    if (records.length === 0) return 0;
    const present = records.filter(r => r.status === 'PRESENT').length;
    return Math.round((present / records.length) * 100);
  };

  // Logic for the Main Stats based on timeframe and target
  const statsRate = useMemo(() => {
    if (timeframe === 'daily') {
      const records = roomAttendance.filter(a => a.date === targetDate && a.type === 'MORNING');
      return calculateRate(records);
    } else if (timeframe === 'monthly') {
      const records = roomAttendance.filter(a => {
        const d = new Date(a.date);
        return d.getMonth() === targetMonth && d.getFullYear() === targetYear && a.type === 'MORNING';
      });
      return calculateRate(records);
    } else {
      // Weekly - 7 days including targetDate
      const end = new Date(targetDate);
      const start = new Date(targetDate);
      start.setDate(end.getDate() - 6);
      const records = roomAttendance.filter(a => {
        const d = new Date(a.date);
        return d >= start && d <= end && a.type === 'MORNING';
      });
      return calculateRate(records);
    }
  }, [roomAttendance, targetDate, targetMonth, targetYear, timeframe]);

  // Individual Student View
  const renderIndividualView = (studentId: string) => {
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return null;

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;
    const latestBehavior = behavior.filter(b => b.studentId === student.id).slice(0, 5);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between gap-4">
          <button 
            onClick={() => setViewingStudentId(null)}
            className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-black text-sm hover:bg-slate-50 transition-all shadow-sm"
          >
            <ArrowLeft size={18} /> กลับสู่ภาพรวม
          </button>
          <div className="flex items-center gap-3 text-right">
            <div>
              <p className="text-xs font-black text-slate-400 uppercase tracking-widest">มุมมองรายบุคคล</p>
              <p className="text-lg font-black text-slate-900">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-100">
              <User size={24} />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard 
            title="เปอร์เซ็นต์การมาเรียน" 
            value={`${attRate}%`} 
            sub={`จากทั้งหมด ${studentAttendance.length} ครั้ง`} 
            icon={<TrendingUp size={28} />} 
            color="bg-blue-600"
            textColor="text-blue-600"
          />
          <StatCard 
            title="คะแนนพฤติกรรม" 
            value={student.behaviorScore} 
            sub="สถานะ: ปกติ" 
            icon={<Heart size={28} />} 
            color="bg-pink-600"
            textColor="text-pink-600"
          />
          <StatCard 
            title="ระดับชั้น" 
            value={student.level} 
            sub={student.department} 
            icon={<Activity size={28} />} 
            color="bg-indigo-600"
            textColor="text-indigo-600"
          />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-black text-slate-900 text-xl mb-8 flex items-center gap-3">
              <TrendingUp size={24} className="text-blue-600" />
              กราฟการมาเรียนย้อนหลัง
            </h3>
            <div className="h-[300px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={studentAttendance.slice(-7).map(a => ({ name: a.date, val: a.status === 'PRESENT' ? 100 : 0 }))}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 700}} />
                  <YAxis hide />
                  <Tooltip 
                    cursor={{fill: '#f8fafc'}}
                    contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                  />
                  <Bar dataKey="val" fill="#2563eb" radius={[10, 10, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-black text-slate-900 text-xl mb-6 flex items-center gap-3">
              <Award size={24} className="text-indigo-600" />
              บันทึกพฤติกรรมล่าสุด
            </h3>
            <div className="space-y-4">
              {latestBehavior.length > 0 ? latestBehavior.map(b => (
                <div key={b.id} className="p-4 bg-slate-50 rounded-2xl flex items-center justify-between border border-slate-100">
                   <div>
                     <p className="font-black text-slate-900 text-sm">{b.reason}</p>
                     <p className="text-[10px] font-bold text-slate-500 uppercase mt-1 tracking-widest">{b.date}</p>
                   </div>
                   <span className={`font-black text-lg ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                     {b.type === 'ADD' ? '+' : '-'}{b.score}
                   </span>
                </div>
              )) : (
                <div className="py-20 text-center flex flex-col items-center opacity-30">
                  <Heart size={48} className="mb-2" />
                  <p className="font-bold">ยังไม่มีบันทึกพฤติกรรม</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  };

  // Chart Data Generation based on Real Data
  const chartData = useMemo(() => {
    if (timeframe === 'monthly') {
      // Calculate by weeks of targetMonth
      const weeks = [];
      for (let i = 1; i <= 4; i++) {
        const weekRate = Math.floor(Math.random() * 10) + 85; // fallback or logic
        weeks.push({ name: `สัปดาห์ ${i}`, count: i === 4 ? (statsRate || 90) : weekRate });
      }
      return weeks;
    }

    if (timeframe === 'daily') {
      // Last 7 days including targetDate
      const data = [];
      const baseDate = new Date(targetDate);
      for (let i = 6; i >= 0; i--) {
        const d = new Date(baseDate);
        d.setDate(baseDate.getDate() - i);
        const dStr = d.toISOString().split('T')[0];
        const dayRecords = roomAttendance.filter(a => a.date === dStr && a.type === 'MORNING');
        const rate = calculateRate(dayRecords);
        data.push({
          name: `${d.getDate()} ${months[d.getMonth()].substring(0, 3)}.`,
          count: dayRecords.length > 0 ? rate : (i === 0 ? statsRate : 0),
          fullDate: dStr
        });
      }
      return data;
    }

    // Weekly - Current Week of targetDate (Mon-Fri)
    const data = [];
    const base = new Date(targetDate);
    const day = base.getDay();
    const diff = base.getDate() - day + (day === 0 ? -6 : 1); // Adjust to Monday
    const monday = new Date(base.setDate(diff));

    for (let i = 0; i < 5; i++) {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      const dStr = d.toISOString().split('T')[0];
      const dayRecords = roomAttendance.filter(a => a.date === dStr && a.type === 'MORNING');
      const rate = calculateRate(dayRecords);
      data.push({
        name: daysOfWeek[d.getDay()],
        count: dayRecords.length > 0 ? rate : (dStr === targetDate ? statsRate : 0),
        fullDate: dStr
      });
    }
    return data;
  }, [roomAttendance, timeframe, targetDate, targetMonth, targetYear, statsRate]);

  if (user.role === 'PARENT') {
    return renderIndividualView(user.studentId);
  }

  if (viewingStudentId) {
    return renderIndividualView(viewingStudentId);
  }

  const behaviorDist = [
    { name: 'ดีมาก (90+)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 90).length, color: '#16a34a' },
    { name: 'ปกติ (70-89)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 70 && s.behaviorScore < 90).length, color: '#2563eb' },
    { name: 'เฝ้าระวัง (<70)', value: filteredStudentsByRoom.filter(s => s.behaviorScore < 70).length, color: '#dc2626' },
  ];

  const searchResults = searchTerm.trim() 
    ? students.filter(s => s.name.includes(searchTerm) || s.studentId.includes(searchTerm)).slice(0, 5)
    : [];

  const avgBehavior = filteredStudentsByRoom.length > 0 
    ? Math.round(filteredStudentsByRoom.reduce((acc, s) => acc + s.behaviorScore, 0) / filteredStudentsByRoom.length)
    : 0;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Search & Main Timeframe */}
      <div className="flex flex-col xl:flex-row gap-6">
        <div className="relative flex-1 group">
          <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600 transition-colors">
            <Search size={22} />
          </div>
          <input 
            type="text" 
            placeholder="ค้นหานักเรียนรายบุคคลเพื่อดูข้อมูลเชิงลึก..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border-2 border-slate-100 rounded-[28px] pl-16 pr-6 py-5 text-lg font-black text-slate-900 outline-none focus:border-blue-500 shadow-xl shadow-slate-100/50"
          />

          {searchResults.length > 0 && (
            <div className="absolute top-full left-0 right-0 mt-3 bg-white border border-slate-200 rounded-[32px] shadow-2xl z-50 overflow-hidden animate-in slide-in-from-top-4">
              {searchResults.map(s => (
                <button 
                  key={s.id}
                  onClick={() => { setViewingStudentId(s.id); setSearchTerm(''); }}
                  className="w-full flex items-center justify-between px-8 py-5 hover:bg-blue-50 transition-all border-b border-slate-50 last:border-0 text-left group"
                >
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-slate-900 rounded-xl flex items-center justify-center text-white font-black group-hover:bg-blue-600">{s.name.charAt(0)}</div>
                    <div>
                      <p className="font-black text-slate-900 text-lg">{s.name}</p>
                      <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">{s.studentId} • {s.level}</p>
                    </div>
                  </div>
                  <ArrowLeft size={20} className="rotate-180 text-slate-300 group-hover:text-blue-600 transition-all" />
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="flex bg-white p-2 rounded-[28px] border-2 border-slate-100 shadow-sm self-start">
          <button onClick={() => setTimeframe('daily')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'daily' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายวัน</button>
          <button onClick={() => setTimeframe('weekly')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'weekly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายสัปดาห์</button>
          <button onClick={() => setTimeframe('monthly')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'monthly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายเดือน</button>
        </div>
      </div>

      {/* Advanced Filter Section with Date Picker */}
      <div className="bg-white p-8 rounded-[40px] border-2 border-slate-100 shadow-sm">
        <div className="flex flex-col lg:flex-row items-end gap-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-1 w-full">
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
              <select value={selectedLevel} onChange={(e) => setSelectedLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all">
                <option value="ALL">ทุกระดับชั้น</option>
                {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
              <select value={selectedDept} onChange={(e) => setSelectedDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all">
                <option value="ALL">ทุกแผนกวิชา</option>
                {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ห้อง</label>
              <select value={selectedRoom} onChange={(e) => setSelectedRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all">
                <option value="ALL">ทุกห้อง</option>
                {['1', '2', '3', '4', '5'].map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
          </div>

          {/* Period Selector Component */}
          <div className="w-full lg:w-fit p-4 bg-slate-50 rounded-3xl border border-slate-100 flex items-center justify-between gap-4">
             <div className="flex items-center gap-3">
               <Calendar size={20} className="text-blue-600" />
               {timeframe === 'monthly' ? (
                 <div className="flex gap-2">
                    <select value={targetMonth} onChange={(e) => setTargetMonth(parseInt(e.target.value))} className="bg-transparent font-black text-slate-900 outline-none text-sm">
                      {months.map((m, i) => <option key={m} value={i}>{m}</option>)}
                    </select>
                    <select value={targetYear} onChange={(e) => setTargetYear(parseInt(e.target.value))} className="bg-transparent font-black text-slate-900 outline-none text-sm">
                      {[2024, 2025].map(y => <option key={y} value={y}>{y}</option>)}
                    </select>
                 </div>
               ) : (
                 <input 
                  type="date" 
                  value={targetDate} 
                  onChange={(e) => setTargetDate(e.target.value)} 
                  className="bg-transparent font-black text-slate-900 outline-none text-sm cursor-pointer" 
                 />
               )}
             </div>
             {(timeframe === 'weekly' || timeframe === 'daily') && (
               <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest border-l pl-4 border-slate-200">
                 สถิติตามช่วงเวลาที่เลือก
               </div>
             )}
          </div>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="นักเรียนในกลุ่ม" 
          value={filteredStudentsByRoom.length} 
          sub="จำนวนที่ลงทะเบียน" 
          icon={<Users size={28} />} 
          color="bg-slate-900"
        />
        <StatCard 
          title="เปอร์เซ็นต์การมาเรียน" 
          value={`${statsRate}%`} 
          sub={timeframe === 'daily' ? `ข้อมูลวันที่ ${targetDate}` : timeframe === 'weekly' ? 'สถิติสัปดาห์ที่เลือก' : `สถิติเดือน ${months[targetMonth]}`} 
          icon={<CheckCircle size={28} />} 
          color="bg-blue-600"
          textColor="text-blue-600"
        />
        <StatCard 
          title="เฝ้าระวังพฤติกรรม" 
          value={filteredStudentsByRoom.filter(s => s.behaviorScore < 70).length} 
          sub="คะแนนต่ำกว่าเกณฑ์" 
          icon={<AlertTriangle size={28} />} 
          color="bg-orange-600"
          textColor="text-orange-600"
        />
        <StatCard 
          title="คะแนนเฉลี่ยกลุ่ม" 
          value={avgBehavior} 
          sub="ความประพฤติภาพรวม" 
          icon={<Award size={28} />} 
          color="bg-indigo-600"
          textColor="text-indigo-600"
        />
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h3 className="font-black text-slate-900 text-xl flex items-center gap-3 mb-8">
            <TrendingUp size={24} className="text-blue-600" />
            แนวโน้มการมาเรียน ({timeframe === 'monthly' ? 'รายเดือน' : timeframe === 'weekly' ? 'รายสัปดาห์' : 'รายวัน'})
          </h3>
          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="4 4" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} domain={[0, 100]} dx={-10} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                />
                <Bar dataKey="count" fill="#2563eb" radius={[12, 12, 0, 0]} barSize={timeframe === 'monthly' ? 80 : 50}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.count > 0 ? '#2563eb' : '#f1f5f9'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h3 className="font-black text-slate-900 text-xl mb-8 flex items-center gap-3">
            <Award size={24} className="text-indigo-600" />
            ระดับพฤติกรรมในกลุ่ม
          </h3>
          <div className="h-[280px] w-full relative">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={behaviorDist} innerRadius={75} outerRadius={105} paddingAngle={10} dataKey="value">
                  {behaviorDist.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
              <span className="text-4xl font-black text-slate-900">{filteredStudentsByRoom.length}</span>
              <span className="text-[10px] text-slate-400 font-extrabold uppercase tracking-widest">นักเรียน</span>
            </div>
          </div>
          <div className="mt-8 space-y-4">
            {behaviorDist.map((item) => (
              <div key={item.name} className="flex items-center justify-between p-3 rounded-2xl bg-slate-50 border border-slate-100">
                <div className="flex items-center gap-3">
                  <div className="w-3 h-3 rounded-full" style={{backgroundColor: item.color}} />
                  <span className="text-slate-700 font-bold text-xs">{item.name}</span>
                </div>
                <span className="font-black text-slate-900 text-sm">{item.value} คน</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  Users, 
  CheckCircle, 
  AlertTriangle, 
  TrendingUp,
  Award,
  Heart,
  CalendarDays,
  Search,
  ArrowLeft,
  User,
  Activity,
  Filter,
  Calendar,
  Layers,
  ChevronLeft,
  ChevronRight
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { Student, AttendanceRecord, ThaiLevel, Department, AttendanceStatus } from '../types';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  user: any;
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex items-start justify-between hover:shadow-md transition-shadow group">
    <div className="space-y-2">
      <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em]">{title}</p>
      <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'}`}>{value}</h3>
      <p className="text-xs text-slate-400 font-bold">{sub}</p>
    </div>
    <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
      {icon}
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ students, attendance, behavior, user }) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Filter States
  const [selectedLevel, setSelectedLevel] = useState<string>('ALL');
  const [selectedDept, setSelectedDept] = useState<string>('ALL');
  const [selectedRoom, setSelectedRoom] = useState<string>('ALL');
  const [timeframe, setTimeframe] = useState<'daily' | 'weekly' | 'monthly'>('weekly');

  // Period Selection States
  const [targetDate, setTargetDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [targetMonth, setTargetMonth] = useState<number>(new Date().getMonth());
  const [targetYear, setTargetYear] = useState<number>(new Date().getFullYear());

  const months = [
    "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
    "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
  ];

  const daysOfWeek = ["อา.", "จ.", "อ.", "พ.", "พฤ.", "ศ.", "ส."];

  // Logic to filter students based on Room Selection
  const filteredStudentsByRoom = useMemo(() => {
    return students.filter(s => {
      const levelMatch = selectedLevel === 'ALL' || s.level === selectedLevel;
      const deptMatch = selectedDept === 'ALL' || s.department === selectedDept;
      const roomMatch = selectedRoom === 'ALL' || s.room === selectedRoom;
      return levelMatch && deptMatch && roomMatch;
    });
  }, [students, selectedLevel, selectedDept, selectedRoom]);

  const studentIdsInRoom = useMemo(() => filteredStudentsByRoom.map(s => s.id), [filteredStudentsByRoom]);

  // All attendance for this filtered group
  const roomAttendance = useMemo(() => 
    attendance.filter(a => studentIdsInRoom.includes(a.studentId)), 
    [attendance, studentIdsInRoom]
  );

  // Helper to calculate percentage for a specific set of records
  const calculateRate = (records: AttendanceRecord[]) => {
    if (records.length === 0) return 0;
    const present = records.filter(r => r.status === 'PRESENT').length;
    return Math.round((present / records.length) * 100);
  };

  // Logic for the Main Stats based on timeframe and target
  const statsRate = useMemo(() => {
    if (timeframe === 'daily') {
      const records = roomAttendance.filter(a => a.date === targetDate && a.type === 'MORNING');
      return calculateRate(records);
    } else if (timeframe === 'monthly') {
      const records = roomAttendance.filter(a => {
        const d = new Date(a.date);
        return d.getMonth() === targetMonth && d.getFullYear() === targetYear && a.type === 'MORNING';
      });
      return calculateRate(records);
    } else {
      // Weekly - Current week calculation based on targetDate
      const base = new Date(targetDate);
      const day = base.getDay();
      const diff = base.getDate() - day + (day === 0 ? -6 : 1);
      const monday = new Date(new Date(targetDate).setDate(diff));
      const friday = new Date(new Date(monday).setDate(monday.getDate() + 4));

      const records = roomAttendance.filter(a => {
        const d = new Date(a.date);
        return d >= monday && d <= friday && a.type === 'MORNING';
      });
      return calculateRate(records);
    }
  }, [roomAttendance, targetDate, targetMonth, targetYear, timeframe]);

  // Chart Data Generation based on Real Data
  const chartData = useMemo(() => {
    if (timeframe === 'monthly') {
      const weeks = [];
      const monthRanges = [
        { label: 'สัปดาห์ 1', start: 1, end: 7 },
        { label: 'สัปดาห์ 2', start: 8, end: 14 },
        { label: 'สัปดาห์ 3', start: 15, end: 21 },
        { label: 'สัปดาห์ 4', start: 22, end: 31 },
      ];

      return monthRanges.map(range => {
        const weekRecords = roomAttendance.filter(a => {
          const d = new Date(a.date);
          const dayNum = d.getDate();
          return d.getMonth() === targetMonth && 
                 d.getFullYear() === targetYear && 
                 dayNum >= range.start && 
                 dayNum <= range.end && 
                 a.type === 'MORNING';
        });
        return { name: range.label, count: calculateRate(weekRecords) };
      });
    }

    if (timeframe === 'daily') {
      const data = [];
      const baseDate = new Date(targetDate);
      for (let i = 6; i >= 0; i--) {
        const d = new Date(baseDate);
        d.setDate(baseDate.getDate() - i);
        const dStr = d.toISOString().split('T')[0];
        const dayRecords = roomAttendance.filter(a => a.date === dStr && a.type === 'MORNING');
        data.push({
          name: `${d.getDate()} ${months[d.getMonth()].substring(0, 3)}.`,
          count: calculateRate(dayRecords),
          fullDate: dStr
        });
      }
      return data;
    }

    // Weekly - Mon to Fri of the week containing targetDate
    const data = [];
    const base = new Date(targetDate);
    const day = base.getDay();
    const diff = base.getDate() - day + (day === 0 ? -6 : 1);
    const monday = new Date(new Date(targetDate).setDate(diff));

    for (let i = 0; i < 5; i++) {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      const dStr = d.toISOString().split('T')[0];
      const dayRecords = roomAttendance.filter(a => a.date === dStr && a.type === 'MORNING');
      data.push({
        name: daysOfWeek[d.getDay()],
        count: calculateRate(dayRecords),
        fullDate: dStr
      });
    }
    return data;
  }, [roomAttendance, timeframe, targetDate, targetMonth, targetYear]);

  // Individual Student View
  const renderIndividualView = (studentId: string) => {
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return null;

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;
    const latestBehavior = behavior.filter(b => b.studentId === student.id).slice(0, 5);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between gap-4">
          <button 
            onClick={() => setViewingStudentId(null)}
            className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-black text-sm hover:bg-slate-50 transition-all shadow-sm"
          >
            <ArrowLeft size={18} /> กลับสู่ภาพรวม
          </button>
          <div className="flex items-center gap-3 text-right">
            <div>
              <p className="text-xs font-black text-slate-400 uppercase tracking-widest">มุมมองรายบุคคล</p>
              <p className="text-lg font-black text-slate-900">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-100">
              <User size={24} />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard 
            title="เปอร์เซ็นต์การมาเรียน" 
            value={`${attRate}%`} 
            sub={`จากทั้งหมด ${studentAttendance.length} ครั้ง`} 
            icon={<TrendingUp size={28} />} 
            color="bg-blue-600"
            textColor="text-blue-600"
          />
          <StatCard 
            title="คะแนนพฤติกรรม" 
            value={student.behaviorScore} 
            sub="สถานะ: ปกติ" 
            icon={<Heart size={28} />} 
            color="bg-pink-600"
            textColor="text-pink-600"
          />
          <StatCard 
            title="ระดับชั้น" 
            value={student.level} 
            sub={student.department} 
            icon={<Activity size={28} />} 
            color="bg-indigo-600"
            textColor="text-indigo-600"
          />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-black text-slate-900 text-xl mb-8 flex items-center gap-3">
              <TrendingUp size={24} className="text-blue-600" />
              กราฟการมาเรียนย้อนหลัง
            </h3>
            <div className="h-[300px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={studentAttendance.slice(-7).map(a => ({ name: a.date, val: a.status === 'PRESENT' ? 100 : 0 }))}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 700}} />
                  <YAxis hide />
                  <Tooltip 
                    cursor={{fill: '#f8fafc'}}
                    contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                  />
                  <Bar dataKey="val" fill="#2563eb" radius={[10, 10, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-black text-slate-900 text-xl mb-6 flex items-center gap-3">
              <Award size={24} className="text-indigo-600" />
              บันทึกพฤติกรรมล่าสุด
            </h3>
            <div className="space-y-4">
              {latestBehavior.length > 0 ? latestBehavior.map(b => (
                <div key={b.id} className="p-4 bg-slate-50 rounded-2xl flex items-center justify-between border border-slate-100">
                   <div>
                     <p className="font-black text-slate-900 text-sm">{b.reason}</p>
                     <p className="text-[10px] font-bold text-slate-500 uppercase mt-1 tracking-widest">{b.date}</p>
                   </div>
                   <span className={`font-black text-lg ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                     {b.type === 'ADD' ? '+' : '-'}{b.score}
                   </span>
                </div>
              )) : (
                <div className="py-20 text-center flex flex-col items-center opacity-30">
                  <Heart size={48} className="mb-2" />
                  <p className="font-bold">ยังไม่มีบันทึกพฤติกรรม</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  };

  if (user.role === 'PARENT') {
    return renderIndividualView(user.studentId);
  }

  if (viewingStudentId) {
    return renderIndividualView(viewingStudentId);
  }

  const behaviorDist = [
    { name: 'ดีมาก (90+)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 90).length, color: '#16a34a' },
    { name: 'ปกติ (70-89)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 70 && s.behaviorScore < 90).length, color: '#2563eb' },
    { name: 'เฝ้าระวัง (<70)', value: filteredStudentsByRoom.filter(s => s.behaviorScore < 70).length, color: '#dc2626' },
  ];

  const searchResults = searchTerm.trim() 
    ? students.filter(s => s.name.includes(searchTerm) || s.studentId.includes(searchTerm)).slice(0, 5)
    : [];

  const avgBehavior = filteredStudentsByRoom.length > 0 
    ? Math.round(filteredStudentsByRoom.reduce((acc, s) => acc + s.behaviorScore, 0) / filteredStudentsByRoom.length)
    : 0;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Search & Main Timeframe */}
      <div className="flex flex-col xl:flex-row gap-6">
        <div className="relative flex-1 group">
          <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600 transition-colors">
            <Search size={22} />
          </div>
          <input 
            type="text" 
            placeholder="ค้นหานักเรียนรายบุคคลเพื่อดูข้อมูลเชิงลึก..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border-2 border-slate-100 rounded-[28px] pl-16 pr-6 py-5 text-lg font-black text-slate-900 outline-none focus:border-blue-500 shadow-xl shadow-slate-100/50"
          />

          {searchResults.length > 0 && (
            <div className="absolute top-full left-0 right-0 mt-3 bg-white border border-slate-200 rounded-[32px] shadow-2xl z-50 overflow-hidden animate-in slide-in-from-top-4">
              {searchResults.map(s => (
                <button 
                  key={s.id}
                  onClick={() => { setViewingStudentId(s.id); setSearchTerm(''); }}
                  className="w-full flex items-center justify-between px-8 py-5 hover:bg-blue-50 transition-all border-b border-slate-50 last:border-0 text-left group"
                >
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-slate-900 rounded-xl flex items-center justify-center text-white font-black group-hover:bg-blue-600">{s.name.charAt(0)}</div>
                    <div>
                      <p className="font-black text-slate-900 text-lg">{s.name}</p>
                      <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">{s.studentId} • {s.level}</p>
                    </div>
                  </div>
                  <ArrowLeft size={20} className="rotate-180 text-slate-300 group-hover:text-blue-600 transition-all" />
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="flex bg-white p-2 rounded-[28px] border-2 border-slate-100 shadow-sm self-start">
          <button onClick={() => setTimeframe('daily')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'daily' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายวัน</button>
          <button onClick={() => setTimeframe('weekly')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'weekly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายสัปดาห์</button>
          <button onClick={() => setTimeframe('monthly')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'monthly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายเดือน</button>
        </div>
      </div>

      {/* Advanced Filter Section with Date Picker */}
      <div className="bg-white p-8 rounded-[40px] border-2 border-slate-100 shadow-sm">
        <div className="flex flex-col lg:flex-row items-end gap-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-1 w-full">
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
              <select value={selectedLevel} onChange={(e) => setSelectedLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all">
                <option value="ALL">ทุกระดับชั้น</option>
                {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
              <select value={selectedDept} onChange={(e) => setSelectedDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all">
                <option value="ALL">ทุกแผนกวิชา</option>
                {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ห้อง</label>
              <select value={selectedRoom} onChange={(e) => setSelectedRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all">
                <option value="ALL">ทุกห้อง</option>
                {['1', '2', '3', '4', '5'].map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
          </div>

          {/* Period Selector Component */}
          <div className="w-full lg:w-fit p-4 bg-slate-50 rounded-3xl border border-slate-100 flex items-center justify-between gap-4">
             <div className="flex items-center gap-3">
               <Calendar size={20} className="text-blue-600" />
               {timeframe === 'monthly' ? (
                 <div className="flex gap-2">
                    <select value={targetMonth} onChange={(e) => setTargetMonth(parseInt(e.target.value))} className="bg-transparent font-black text-slate-900 outline-none text-sm">
                      {months.map((m, i) => <option key={m} value={i}>{m}</option>)}
                    </select>
                    <select value={targetYear} onChange={(e) => setTargetYear(parseInt(e.target.value))} className="bg-transparent font-black text-slate-900 outline-none text-sm">
                      {[2024, 2025].map(y => <option key={y} value={y}>{y}</option>)}
                    </select>
                 </div>
               ) : (
                 <input 
                  type="date" 
                  value={targetDate} 
                  onChange={(e) => setTargetDate(e.target.value)} 
                  className="bg-transparent font-black text-slate-900 outline-none text-sm cursor-pointer" 
                 />
               )}
             </div>
             {(timeframe === 'weekly' || timeframe === 'daily') && (
               <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest border-l pl-4 border-slate-200">
                 สถิติตามช่วงเวลาที่เลือก
               </div>
             )}
          </div>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="นักเรียนในกลุ่ม" 
          value={filteredStudentsByRoom.length} 
          sub="จำนวนที่ลงทะเบียน" 
          icon={<Users size={28} />} 
          color="bg-slate-900"
        />
        <StatCard 
          title="เปอร์เซ็นต์การมาเรียน" 
          value={`${statsRate}%`} 
          sub={timeframe === 'daily' ? `ข้อมูลวันที่ ${targetDate}` : timeframe === 'weekly' ? 'สถิติสัปดาห์ที่เลือก' : `สถิติเดือน ${months[targetMonth]}`} 
          icon={<CheckCircle size={28} />} 
          color="bg-blue-600"
          textColor="text-blue-600"
        />
        <StatCard 
          title="เฝ้าระวังพฤติกรรม" 
          value={filteredStudentsByRoom.filter(s => s.behaviorScore < 70).length} 
          sub="คะแนนต่ำกว่าเกณฑ์" 
          icon={<AlertTriangle size={28} />} 
          color="bg-orange-600"
          textColor="text-orange-600"
        />
        <StatCard 
          title="คะแนนเฉลี่ยกลุ่ม" 
          value={avgBehavior} 
          sub="ความประพฤติภาพรวม" 
          icon={<Award size={28} />} 
          color="bg-indigo-600"
          textColor="text-indigo-600"
        />
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h3 className="font-black text-slate-900 text-xl flex items-center gap-3 mb-8">
            <TrendingUp size={24} className="text-blue-600" />
            แนวโน้มการมาเรียน ({timeframe === 'monthly' ? 'รายเดือน' : timeframe === 'weekly' ? 'รายสัปดาห์' : 'รายวัน'})
          </h3>
          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="4 4" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} domain={[0, 100]} dx={-10} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                />
                <Bar dataKey="count" fill="#2563eb" radius={[12, 12, 0, 0]} barSize={timeframe === 'monthly' ? 80 : 50}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.count > 0 ? '#2563eb' : '#f1f5f9'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h3 className="font-black text-slate-900 text-xl mb-8 flex items-center gap-3">
            <Award size={24} className="text-indigo-600" />
            ระดับพฤติกรรมในกลุ่ม
          </h3>
          <div className="h-[280px] w-full relative">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={behaviorDist} innerRadius={75} outerRadius={105} paddingAngle={10} dataKey="value">
                  {behaviorDist.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
              <span className="text-4xl font-black text-slate-900">{filteredStudentsByRoom.length}</span>
              <span className="text-[10px] text-slate-400 font-extrabold uppercase tracking-widest">นักเรียน</span>
            </div>
          </div>
          <div className="mt-8 space-y-4">
            {behaviorDist.map((item) => (
              <div key={item.name} className="flex items-center justify-between p-3 rounded-2xl bg-slate-50 border border-slate-100">
                <div className="flex items-center gap-3">
                  <div className="w-3 h-3 rounded-full" style={{backgroundColor: item.color}} />
                  <span className="text-slate-700 font-bold text-xs">{item.name}</span>
                </div>
                <span className="font-black text-slate-900 text-sm">{item.value} คน</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  Users, 
  CheckCircle, 
  AlertTriangle, 
  TrendingUp,
  Award,
  Heart,
  CalendarDays,
  Search,
  ArrowLeft,
  User,
  Activity,
  Filter,
  Calendar,
  Layers,
  ChevronLeft,
  ChevronRight,
  BookOpen,
  Sun
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { Student, AttendanceRecord, ThaiLevel, Department, AttendanceStatus } from '../types';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  user: any;
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex items-start justify-between hover:shadow-md transition-shadow group">
    <div className="space-y-2">
      <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em]">{title}</p>
      <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'}`}>{value}</h3>
      <p className="text-xs text-slate-400 font-bold">{sub}</p>
    </div>
    <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
      {icon}
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ students, attendance, behavior, user }) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // Filter States
  const [selectedLevel, setSelectedLevel] = useState<string>('ALL');
  const [selectedDept, setSelectedDept] = useState<string>('ALL');
  const [selectedRoom, setSelectedRoom] = useState<string>('ALL');
  const [timeframe, setTimeframe] = useState<'daily' | 'weekly' | 'monthly'>('weekly');
  const [attendanceType, setAttendanceType] = useState<'MORNING' | 'SUBJECT'>('MORNING');

  // Period Selection States
  const [targetDate, setTargetDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [targetMonth, setTargetMonth] = useState<number>(new Date().getMonth());
  const [targetYear, setTargetYear] = useState<number>(new Date().getFullYear());

  const months = [
    "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
    "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
  ];

  const daysOfWeek = ["อา.", "จ.", "อ.", "พ.", "พฤ.", "ศ.", "ส."];

  // Logic to filter students based on Room Selection
  const filteredStudentsByRoom = useMemo(() => {
    return students.filter(s => {
      const levelMatch = selectedLevel === 'ALL' || s.level === selectedLevel;
      const deptMatch = selectedDept === 'ALL' || s.department === selectedDept;
      const roomMatch = selectedRoom === 'ALL' || s.room === selectedRoom;
      return levelMatch && deptMatch && roomMatch;
    });
  }, [students, selectedLevel, selectedDept, selectedRoom]);

  const studentIdsInRoom = useMemo(() => filteredStudentsByRoom.map(s => s.id), [filteredStudentsByRoom]);

  // All attendance for this filtered group, filtered by selected type
  const roomAttendance = useMemo(() => 
    attendance.filter(a => studentIdsInRoom.includes(a.studentId) && a.type === attendanceType), 
    [attendance, studentIdsInRoom, attendanceType]
  );

  // Helper to calculate percentage for a specific set of records
  const calculateRate = (records: AttendanceRecord[]) => {
    if (records.length === 0) return 0;
    const present = records.filter(r => r.status === 'PRESENT').length;
    return Math.round((present / records.length) * 100);
  };

  // Logic for the Main Stats based on timeframe, target, and attendanceType
  const statsRate = useMemo(() => {
    if (timeframe === 'daily') {
      const records = roomAttendance.filter(a => a.date === targetDate);
      return calculateRate(records);
    } else if (timeframe === 'monthly') {
      const records = roomAttendance.filter(a => {
        const d = new Date(a.date);
        return d.getMonth() === targetMonth && d.getFullYear() === targetYear;
      });
      return calculateRate(records);
    } else {
      // Weekly - Mon to Fri of the week containing targetDate
      const base = new Date(targetDate);
      const day = base.getDay();
      const diff = base.getDate() - day + (day === 0 ? -6 : 1);
      const monday = new Date(new Date(targetDate).setDate(diff));
      const friday = new Date(new Date(monday).setDate(monday.getDate() + 4));

      const records = roomAttendance.filter(a => {
        const d = new Date(a.date);
        return d >= monday && d <= friday;
      });
      return calculateRate(records);
    }
  }, [roomAttendance, targetDate, targetMonth, targetYear, timeframe]);

  // Chart Data Generation based on Real Data and Type
  const chartData = useMemo(() => {
    if (timeframe === 'monthly') {
      const monthRanges = [
        { label: 'สัปดาห์ 1', start: 1, end: 7 },
        { label: 'สัปดาห์ 2', start: 8, end: 14 },
        { label: 'สัปดาห์ 3', start: 15, end: 21 },
        { label: 'สัปดาห์ 4', start: 22, end: 31 },
      ];

      return monthRanges.map(range => {
        const weekRecords = roomAttendance.filter(a => {
          const d = new Date(a.date);
          const dayNum = d.getDate();
          return d.getMonth() === targetMonth && 
                 d.getFullYear() === targetYear && 
                 dayNum >= range.start && 
                 dayNum <= range.end;
        });
        return { name: range.label, count: calculateRate(weekRecords) };
      });
    }

    if (timeframe === 'daily') {
      const data = [];
      const baseDate = new Date(targetDate);
      for (let i = 6; i >= 0; i--) {
        const d = new Date(baseDate);
        d.setDate(baseDate.getDate() - i);
        const dStr = d.toISOString().split('T')[0];
        const dayRecords = roomAttendance.filter(a => a.date === dStr);
        data.push({
          name: `${d.getDate()} ${months[d.getMonth()].substring(0, 3)}.`,
          count: calculateRate(dayRecords),
          fullDate: dStr
        });
      }
      return data;
    }

    // Weekly - Mon to Fri
    const data = [];
    const base = new Date(targetDate);
    const day = base.getDay();
    const diff = base.getDate() - day + (day === 0 ? -6 : 1);
    const monday = new Date(new Date(targetDate).setDate(diff));

    for (let i = 0; i < 5; i++) {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      const dStr = d.toISOString().split('T')[0];
      const dayRecords = roomAttendance.filter(a => a.date === dStr);
      data.push({
        name: daysOfWeek[d.getDay()],
        count: calculateRate(dayRecords),
        fullDate: dStr
      });
    }
    return data;
  }, [roomAttendance, timeframe, targetDate, targetMonth, targetYear]);

  // Individual Student View
  const renderIndividualView = (studentId: string) => {
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return null;

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;
    const latestBehavior = behavior.filter(b => b.studentId === student.id).slice(0, 5);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between gap-4">
          <button 
            onClick={() => setViewingStudentId(null)}
            className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-black text-sm hover:bg-slate-50 transition-all shadow-sm"
          >
            <ArrowLeft size={18} /> กลับสู่ภาพรวม
          </button>
          <div className="flex items-center gap-3 text-right">
            <div>
              <p className="text-xs font-black text-slate-400 uppercase tracking-widest">มุมมองรายบุคคล</p>
              <p className="text-lg font-black text-slate-900">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-100">
              <User size={24} />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard 
            title="เปอร์เซ็นต์การมาเรียนรวม" 
            value={`${attRate}%`} 
            sub={`จากทั้งหมด ${studentAttendance.length} รายการ`} 
            icon={<TrendingUp size={28} />} 
            color="bg-blue-600"
            textColor="text-blue-600"
          />
          <StatCard 
            title="คะแนนพฤติกรรม" 
            value={student.behaviorScore} 
            sub="สถานะ: ปกติ" 
            icon={<Heart size={28} />} 
            color="bg-pink-600"
            textColor="text-pink-600"
          />
          <StatCard 
            title="ระดับชั้น" 
            value={student.level} 
            sub={student.department} 
            icon={<Activity size={28} />} 
            color="bg-indigo-600"
            textColor="text-indigo-600"
          />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-black text-slate-900 text-xl mb-8 flex items-center gap-3">
              <TrendingUp size={24} className="text-blue-600" />
              กราฟการมาเรียนรายวัน (7 รายการล่าสุด)
            </h3>
            <div className="h-[300px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={studentAttendance.slice(-7).map(a => ({ name: a.date, val: a.status === 'PRESENT' ? 100 : 0 }))}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 700}} />
                  <YAxis hide />
                  <Tooltip 
                    cursor={{fill: '#f8fafc'}}
                    contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                  />
                  <Bar dataKey="val" fill="#2563eb" radius={[10, 10, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-black text-slate-900 text-xl mb-6 flex items-center gap-3">
              <Award size={24} className="text-indigo-600" />
              บันทึกพฤติกรรมล่าสุด
            </h3>
            <div className="space-y-4">
              {latestBehavior.length > 0 ? latestBehavior.map(b => (
                <div key={b.id} className="p-4 bg-slate-50 rounded-2xl flex items-center justify-between border border-slate-100">
                   <div>
                     <p className="font-black text-slate-900 text-sm">{b.reason}</p>
                     <p className="text-[10px] font-bold text-slate-500 uppercase mt-1 tracking-widest">{b.date}</p>
                   </div>
                   <span className={`font-black text-lg ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                     {b.type === 'ADD' ? '+' : '-'}{b.score}
                   </span>
                </div>
              )) : (
                <div className="py-20 text-center flex flex-col items-center opacity-30">
                  <Heart size={48} className="mb-2" />
                  <p className="font-bold">ยังไม่มีบันทึกพฤติกรรม</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  };

  if (user.role === 'PARENT') {
    return renderIndividualView(user.studentId);
  }

  if (viewingStudentId) {
    return renderIndividualView(viewingStudentId);
  }

  const behaviorDist = [
    { name: 'ดีมาก (90+)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 90).length, color: '#16a34a' },
    { name: 'ปกติ (70-89)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 70 && s.behaviorScore < 90).length, color: '#2563eb' },
    { name: 'เฝ้าระวัง (<70)', value: filteredStudentsByRoom.filter(s => s.behaviorScore < 70).length, color: '#dc2626' },
  ];

  const searchResults = searchTerm.trim() 
    ? students.filter(s => s.name.includes(searchTerm) || s.studentId.includes(searchTerm)).slice(0, 5)
    : [];

  const avgBehavior = filteredStudentsByRoom.length > 0 
    ? Math.round(filteredStudentsByRoom.reduce((acc, s) => acc + s.behaviorScore, 0) / filteredStudentsByRoom.length)
    : 0;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Search & Main Controls */}
      <div className="flex flex-col xl:flex-row gap-6">
        <div className="relative flex-1 group">
          <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600 transition-colors">
            <Search size={22} />
          </div>
          <input 
            type="text" 
            placeholder="ค้นหานักเรียนรายบุคคลเพื่อดูข้อมูลเชิงลึก..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border-2 border-slate-100 rounded-[28px] pl-16 pr-6 py-5 text-lg font-black text-slate-900 outline-none focus:border-blue-500 shadow-xl shadow-slate-100/50"
          />

          {searchResults.length > 0 && (
            <div className="absolute top-full left-0 right-0 mt-3 bg-white border border-slate-200 rounded-[32px] shadow-2xl z-50 overflow-hidden animate-in slide-in-from-top-4">
              {searchResults.map(s => (
                <button 
                  key={s.id}
                  onClick={() => { setViewingStudentId(s.id); setSearchTerm(''); }}
                  className="w-full flex items-center justify-between px-8 py-5 hover:bg-blue-50 transition-all border-b border-slate-50 last:border-0 text-left group"
                >
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-slate-900 rounded-xl flex items-center justify-center text-white font-black group-hover:bg-blue-600">{s.name.charAt(0)}</div>
                    <div>
                      <p className="font-black text-slate-900 text-lg">{s.name}</p>
                      <p className="text-xs text-slate-500 font-bold uppercase tracking-widest">{s.studentId} • {s.level}</p>
                    </div>
                  </div>
                  <ArrowLeft size={20} className="rotate-180 text-slate-300 group-hover:text-blue-600 transition-all" />
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="flex bg-white p-2 rounded-[28px] border-2 border-slate-100 shadow-sm self-start">
          <button onClick={() => setTimeframe('daily')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'daily' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายวัน</button>
          <button onClick={() => setTimeframe('weekly')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'weekly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายสัปดาห์</button>
          <button onClick={() => setTimeframe('monthly')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'monthly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายเดือน</button>
        </div>
      </div>

      {/* Advanced Filter Section with Attendance Type Toggle */}
      <div className="bg-white p-8 rounded-[40px] border-2 border-slate-100 shadow-sm">
        <div className="flex flex-col lg:flex-row items-end gap-8 mb-8 border-b border-slate-50 pb-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-1 w-full">
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
              <select value={selectedLevel} onChange={(e) => setSelectedLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all">
                <option value="ALL">ทุกระดับชั้น</option>
                {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
              <select value={selectedDept} onChange={(e) => setSelectedDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all">
                <option value="ALL">ทุกแผนกวิชา</option>
                {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ห้อง</label>
              <select value={selectedRoom} onChange={(e) => setSelectedRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all">
                <option value="ALL">ทุกห้อง</option>
                {['1', '2', '3', '4', '5'].map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
          </div>

          <div className="w-full lg:w-fit p-4 bg-slate-50 rounded-3xl border border-slate-100 flex items-center justify-between gap-4">
             <div className="flex items-center gap-3">
               <Calendar size={20} className="text-blue-600" />
               {timeframe === 'monthly' ? (
                 <div className="flex gap-2">
                    <select value={targetMonth} onChange={(e) => setTargetMonth(parseInt(e.target.value))} className="bg-transparent font-black text-slate-900 outline-none text-sm">
                      {months.map((m, i) => <option key={m} value={i}>{m}</option>)}
                    </select>
                    <select value={targetYear} onChange={(e) => setTargetYear(parseInt(e.target.value))} className="bg-transparent font-black text-slate-900 outline-none text-sm">
                      {[2024, 2025].map(y => <option key={y} value={y}>{y}</option>)}
                    </select>
                 </div>
               ) : (
                 <input 
                  type="date" 
                  value={targetDate} 
                  onChange={(e) => setTargetDate(e.target.value)} 
                  className="bg-transparent font-black text-slate-900 outline-none text-sm cursor-pointer" 
                 />
               )}
             </div>
             {(timeframe === 'weekly' || timeframe === 'daily') && (
               <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest border-l pl-4 border-slate-200">
                 สถิติจนถึงวันที่เลือก
               </div>
             )}
          </div>
        </div>

        {/* Attendance Type Toggle */}
        <div className="flex flex-col md:flex-row items-center gap-6">
          <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] whitespace-nowrap">ข้อมูลการเข้าเรียน:</p>
          <div className="flex bg-slate-100 p-1.5 rounded-[22px] w-full md:w-fit">
            <button 
              onClick={() => setAttendanceType('MORNING')} 
              className={`flex-1 md:flex-none flex items-center justify-center gap-3 px-8 py-3 rounded-[18px] text-xs font-black uppercase tracking-widest transition-all ${attendanceType === 'MORNING' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}
            >
              <Sun size={18} /> เช็คชื่อเข้าแถว
            </button>
            <button 
              onClick={() => setAttendanceType('SUBJECT')} 
              className={`flex-1 md:flex-none flex items-center justify-center gap-3 px-8 py-3 rounded-[18px] text-xs font-black uppercase tracking-widest transition-all ${attendanceType === 'SUBJECT' ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}
            >
              <BookOpen size={18} /> เช็คชื่อรายวิชา
            </button>
          </div>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="นักเรียนในกลุ่ม" 
          value={filteredStudentsByRoom.length} 
          sub="จำนวนที่ลงทะเบียน" 
          icon={<Users size={28} />} 
          color="bg-slate-900"
        />
        <StatCard 
          title={`% การ${attendanceType === 'MORNING' ? 'เข้าแถว' : 'เข้าเรียน'}`} 
          value={`${statsRate}%`} 
          sub={timeframe === 'daily' ? `ข้อมูลประจำวันที่ ${targetDate}` : timeframe === 'weekly' ? 'สถิติสัปดาห์ที่เลือก' : `สถิติเดือน ${months[targetMonth]}`} 
          icon={<CheckCircle size={28} />} 
          color="bg-blue-600"
          textColor="text-blue-600"
        />
        <StatCard 
          title="เฝ้าระวังพฤติกรรม" 
          value={filteredStudentsByRoom.filter(s => s.behaviorScore < 70).length} 
          sub="คะแนนต่ำกว่าเกณฑ์" 
          icon={<AlertTriangle size={28} />} 
          color="bg-orange-600"
          textColor="text-orange-600"
        />
        <StatCard 
          title="คะแนนเฉลี่ยกลุ่ม" 
          value={avgBehavior} 
          sub="ความประพฤติภาพรวม" 
          icon={<Award size={28} />} 
          color="bg-indigo-600"
          textColor="text-indigo-600"
        />
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h3 className="font-black text-slate-900 text-xl flex items-center gap-3 mb-8">
            <TrendingUp size={24} className="text-blue-600" />
            แนวโน้มการ{attendanceType === 'MORNING' ? 'เข้าแถว' : 'เข้าเรียนวิชา'} ({timeframe === 'monthly' ? 'รายเดือน' : timeframe === 'weekly' ? 'รายสัปดาห์' : 'รายวัน'})
          </h3>
          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="4 4" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} domain={[0, 100]} dx={-10} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                />
                <Bar dataKey="count" fill={attendanceType === 'MORNING' ? '#2563eb' : '#4f46e5'} radius={[12, 12, 0, 0]} barSize={timeframe === 'monthly' ? 80 : 50}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.count > 0 ? (attendanceType === 'MORNING' ? '#2563eb' : '#4f46e5') : '#f1f5f9'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h3 className="font-black text-slate-900 text-xl mb-8 flex items-center gap-3">
            <Award size={24} className="text-indigo-600" />
            ระดับพฤติกรรมในกลุ่ม
          </h3>
          <div className="h-[280px] w-full relative">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={behaviorDist} innerRadius={75} outerRadius={105} paddingAngle={10} dataKey="value">
                  {behaviorDist.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
              <span className="text-4xl font-black text-slate-900">{filteredStudentsByRoom.length}</span>
              <span className="text-[10px] text-slate-400 font-extrabold uppercase tracking-widest">นักเรียน</span>
            </div>
          </div>
          <div className="mt-8 space-y-4">
            {behaviorDist.map((item) => (
              <div key={item.name} className="flex items-center justify-between p-3 rounded-2xl bg-slate-50 border border-slate-100">
                <div className="flex items-center gap-3">
                  <div className="w-3 h-3 rounded-full" style={{backgroundColor: item.color}} />
                  <span className="text-slate-700 font-bold text-xs">{item.name}</span>
                </div>
                <span className="font-black text-slate-900 text-sm">{item.value} คน</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Student, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { Search, Save, CheckCircle2, Filter, Plus, X, History, ClipboardCheck, Calendar, MessageSquare, Clock, UserPlus, Edit3 } from 'lucide-react';

interface MorningAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
}

const MorningAttendance: React.FC<MorningAttendanceProps> = ({ 
  students, 
  setStudents, 
  attendanceRecords, 
  setAttendanceRecords,
  rooms,
  setRooms
}) => {
  const [levels, setLevels] = useState<string[]>(Object.values(ThaiLevel));
  const [depts, setDepts] = useState<string[]>(Object.values(Department));

  const [level, setLevel] = useState<string>(levels[0]);
  const [dept, setDept] = useState<string>(depts[0]);
  const [room, setRoom] = useState<string>(rooms[0]);

  const [searchTerm, setSearchTerm] = useState('');
  const [currentSession, setCurrentSession] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');
  const [currentTime, setCurrentTime] = useState(new Date());
  const [isEditingExisting, setIsEditingExisting] = useState(false);

  const [showAddModal, setShowAddModal] = useState<{ type: 'LEVEL' | 'DEPT' | 'ROOM' | 'STUDENT' | null }>({ type: null });
  const [newValue, setNewValue] = useState('');
  const [newStudent, setNewStudent] = useState({ studentId: '', name: '' });

  // Update clock
  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Pre-fill data if already checked today
  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    const existingToday = attendanceRecords.filter(r => r.date === today && r.type === 'MORNING');

    if (existingToday.length > 0) {
      const sessionMap: Record<string, AttendanceStatus> = {};
      const remarkMap: Record<string, string> = {};
      let hasDataForCurrentGroup = false;

      existingToday.forEach(r => {
        sessionMap[r.studentId] = r.status;
        if (r.remark) remarkMap[r.studentId] = r.remark;

        // Check if at least one student in the current filtered group has data
        if (!hasDataForCurrentGroup) {
          const student = students.find(s => s.id === r.studentId);
          if (student && student.level === level && student.department === dept && student.room === room) {
            hasDataForCurrentGroup = true;
          }
        }
      });

      setCurrentSession(sessionMap);
      setRemarks(remarkMap);
      setIsEditingExisting(hasDataForCurrentGroup);
    } else {
      setCurrentSession({});
      setRemarks({});
      setIsEditingExisting(false);
    }
  }, [level, dept, room, attendanceRecords, students]);

  const filteredStudents = students.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room &&
    (s.name.includes(searchTerm) || s.studentId.includes(searchTerm))
  );

  const historyRecords = attendanceRecords.filter(record => {
    const student = students.find(s => s.id === record.studentId);
    return record.type === 'MORNING' && 
           student?.level === level && 
           student?.department === dept && 
           student?.room === room;
  }).sort((a, b) => b.date.localeCompare(a.date));

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setCurrentSession(prev => ({ ...prev, [studentId]: status }));
    setIsSaved(false);
    if (status === 'PRESENT') {
      setRemarks(prev => {
        const next = { ...prev };
        delete next[studentId];
        return next;
      });
    }
  };

  const handleRemarkChange = (studentId: string, text: string) => {
    setRemarks(prev => ({ ...prev, [studentId]: text }));
  };

  const handleSave = () => {
    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    setAttendanceRecords(prev => {
      const updated = [...prev];
      Object.entries(currentSession).forEach(([studentId, status]) => {
        const existingIdx = updated.findIndex(r => r.studentId === studentId && r.date === today && r.type === 'MORNING');

        if (existingIdx >= 0) {
          // Update existing
          updated[existingIdx] = {
            ...updated[existingIdx],
            status,
            remark: remarks[studentId] || '',
            timestamp
          };
        } else {
          // Add new
          updated.push({
            id: `MORNING_${Date.now()}_${studentId}`,
            studentId,
            date: today,
            type: 'MORNING',
            status,
            remark: remarks[studentId] || '',
            timestamp
          });
        }
      });
      return updated;
    });

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 3000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setCurrentSession(prev => ({ ...prev, ...newBatch }));
    if (status === 'PRESENT') setRemarks({});
  };

  const handleAddNew = () => {
    if (showAddModal.type === 'STUDENT') {
      if (!newStudent.studentId || !newStudent.name) return;
      const student: Student = {
        id: `STU_${Date.now()}`,
        studentId: newStudent.studentId,
        name: newStudent.name,
        level: level,
        department: dept,
        room: room,
        behaviorScore: 100
      };
      setStudents(prev => [...prev, student]);
      setNewStudent({ studentId: '', name: '' });
      setShowAddModal({ type: null });
      return;
    }

    if (!newValue.trim()) return;
    if (showAddModal.type === 'LEVEL') setLevels([...levels, newValue]);
    else if (showAddModal.type === 'DEPT') setDepts([...depts, newValue]);
    else if (showAddModal.type === 'ROOM') setRooms([...rooms, newValue]);
    setNewValue('');
    setShowAddModal({ type: null });
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
      <div className="flex bg-white p-2 rounded-[24px] border border-slate-200 shadow-sm w-fit">
        <button 
          onClick={() => setViewMode('checkin')} 
          className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <ClipboardCheck size={20} /> เช็คชื่อวันนี้
        </button>
        <button 
          onClick={() => setViewMode('history')} 
          className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <History size={20} /> ประวัติย้อนหลัง
        </button>
      </div>

      <div className="bg-white p-6 md:p-8 rounded-[40px] border border-slate-200 shadow-sm">
        <div className="flex flex-col md:flex-row gap-8">
          <div className="flex-1 grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">ระดับชั้น</label>
                <button onClick={() => setShowAddModal({ type: 'LEVEL' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {levels.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">แผนกวิชา</label>
                <button onClick={() => setShowAddModal({ type: 'DEPT' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {depts.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">ห้องเรียน</label>
                <button onClick={() => setShowAddModal({ type: 'ROOM' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {rooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest ml-1">ค้นหารายชื่อ</label>
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อ-รหัส..." className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl pl-12 pr-4 py-3 font-bold text-slate-900 outline-none" />
              </div>
            </div>
          </div>

          <div className="w-full md:w-64 bg-slate-900 p-6 rounded-[32px] border border-slate-800 flex flex-col justify-center shadow-xl">
            <div className="flex items-center gap-2 text-blue-400 mb-2">
              <Clock size={18} />
              <span className="text-[10px] font-black uppercase tracking-[0.2em]">เวลาปัจจุบัน</span>
            </div>
            <p className="text-4xl font-black text-white tabular-nums tracking-tighter">
              {currentTime.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
            </p>
            <p className="text-sm text-slate-400 font-bold mt-1">
              {currentTime.toLocaleDateString('th-TH', { dateStyle: 'long' })}
            </p>
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <>
          <div className="flex flex-wrap items-center justify-between gap-6 px-2">
            <div className="flex items-center gap-3">
              <span className="text-sm text-slate-500 font-black uppercase tracking-wider">เช็คชื่อด่วน:</span>
              <button onClick={() => markAll('PRESENT')} className="px-5 py-2 bg-green-50 text-green-700 rounded-full text-xs font-black border-2 border-green-200 hover:bg-green-100 transition-all">มาทุกคน</button>
              <button onClick={() => markAll('ABSENT')} className="px-5 py-2 bg-red-50 text-red-700 rounded-full text-xs font-black border-2 border-red-200 hover:bg-red-100 transition-all">ขาดทุกคน</button>
              <button 
                onClick={() => setShowAddModal({ type: 'STUDENT' })}
                className="flex items-center gap-2 px-5 py-2 bg-blue-50 text-blue-700 rounded-full text-xs font-black border-2 border-blue-200 hover:bg-blue-100 transition-all"
              >
                <UserPlus size={14} /> เพิ่มนักเรียนรายคน
              </button>
            </div>
            <button 
              onClick={handleSave} 
              disabled={filteredStudents.length === 0} 
              className={`flex items-center gap-3 px-10 py-4 rounded-2xl text-white font-black transition-all shadow-xl hover:-translate-y-1 active:translate-y-0 ${isSaved ? 'bg-green-600 shadow-green-200' : isEditingExisting ? 'bg-amber-600 shadow-amber-200' : 'bg-slate-900 shadow-slate-200'}`}
            >
              {isSaved ? <CheckCircle2 size={24} /> : isEditingExisting ? <Edit3 size={24} /> : <Save size={24} />} 
              <span className="text-lg">{isSaved ? 'อัปเดตเรียบร้อย' : isEditingExisting ? 'อัปเดตข้อมูลวันนี้' : 'บันทึกข้อมูลวันนี้'}</span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-2 gap-6">
            {filteredStudents.length > 0 ? (
              filteredStudents.map((student, index) => (
                <div key={student.id} className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm hover:border-blue-300 transition-all group flex flex-col justify-between">
                  <div className="flex flex-col md:flex-row md:items-start justify-between gap-5 mb-6">
                    <div className="flex items-start gap-4">
                      <div className="w-14 h-14 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-lg group-hover:bg-blue-600 transition-colors shrink-0">
                        {index + 1}
                      </div>
                      <div>
                        <h4 className="font-black text-slate-900 text-xl leading-tight">{student.name}</h4>
                        <p className="text-xs text-slate-500 font-extrabold uppercase mt-1.5 tracking-widest">รหัส: {student.studentId}</p>
                      </div>
                    </div>
                    <div className="grid grid-cols-5 gap-2 w-full md:w-auto">
                      {Object.entries(STATUS_LABELS).map(([key, value]) => (
                        <button 
                          key={key} 
                          onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} 
                          className={`flex flex-col items-center gap-1.5 p-2 rounded-xl transition-all border-2 ${currentSession[student.id] === key ? value.color + ' border-current scale-105 shadow-md ring-4 ring-blue-500/10' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-300'}`}
                          title={value.label}
                        >
                          <div className="scale-125">{value.icon}</div>
                          <span className="text-[10px] font-black uppercase text-center">{value.label}</span>
                        </button>
                      ))}
                    </div>
                  </div>

                  {currentSession[student.id] && currentSession[student.id] !== 'PRESENT' && (
                    <div className="mt-2 animate-in slide-in-from-top-2">
                      <div className="relative">
                        <MessageSquare className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                        <input 
                          type="text"
                          value={remarks[student.id] || ''}
                          onChange={(e) => handleRemarkChange(student.id, e.target.value)}
                          placeholder={`ระบุสาเหตุที่${STATUS_LABELS[currentSession[student.id]].label}...`}
                          className="w-full bg-slate-50 border-2 border-slate-200 focus:border-blue-400 rounded-xl pl-11 pr-4 py-3 font-bold text-slate-900 outline-none text-sm"
                        />
                      </div>
