import React, { useState, useEffect } from 'react';
import { Student, Subject, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { Save, BookOpen, Clock, Users, MessageSquare, UserPlus, X, Plus, Filter, History, ClipboardCheck, Calendar, Edit3 } from 'lucide-react';

interface ClassAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  subjects: Subject[];
  setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  currentUser: any;
}

const ClassAttendance: React.FC<ClassAttendanceProps> = ({ 
  students: allStudents, 
  setStudents,
  subjects, 
  setSubjects,
  rooms,
  setRooms,
  attendanceRecords, 
  setAttendanceRecords,
  currentUser
}) => {
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');
  const [level, setLevel] = useState<string>(Object.values(ThaiLevel)[0]);
  const [dept, setDept] = useState<string>(Object.values(Department)[0]);
  const [room, setRoom] = useState(rooms.length > 0 ? rooms[0] : '1');
  const [subjectId, setSubjectId] = useState(subjects.length > 0 ? subjects[0].id : '');
  const [sessionAttendance, setSessionAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [isEditingExisting, setIsEditingExisting] = useState(false);

  const [showAddModal, setShowAddModal] = useState<'STUDENT' | 'SUBJECT' | 'ROOM' | null>(null);
  const [newStudent, setNewStudent] = useState({ studentId: '', name: '' });
  const [newSubject, setNewSubject] = useState({ code: '', name: '' });
  const [newRoomValue, setNewRoomValue] = useState('');

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Sync session with existing records
  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    const existing = attendanceRecords.filter(r => r.date === today && r.type === 'SUBJECT' && r.subjectId === subjectId);

    if (existing.length > 0) {
      const attMap: Record<string, AttendanceStatus> = {};
      const remMap: Record<string, string> = {};
      let hasDataInGroup = false;

      existing.forEach(r => {
        attMap[r.studentId] = r.status;
        if (r.remark) remMap[r.studentId] = r.remark;

        if (!hasDataInGroup) {
          const s = allStudents.find(stu => stu.id === r.studentId);
          if (s && s.level === level && s.department === dept && s.room === room) hasDataInGroup = true;
        }
      });

      setSessionAttendance(attMap);
      setRemarks(remMap);
      setIsEditingExisting(hasDataInGroup);
    } else {
      setSessionAttendance({});
      setRemarks({});
      setIsEditingExisting(false);
    }
  }, [level, dept, room, subjectId, attendanceRecords, allStudents]);

  const filteredStudents = allStudents.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room
  );

  const historyRecords = attendanceRecords.filter(record => {
    const student = allStudents.find(s => s.id === record.studentId);
    return record.type === 'SUBJECT' && 
           record.subjectId === subjectId &&
           student?.level === level && 
           student?.department === dept && 
           student?.room === room;
  }).sort((a, b) => b.date.localeCompare(a.date) || b.timestamp.localeCompare(a.timestamp));

  const handleStatusChange = (id: string, status: AttendanceStatus) => {
    setSessionAttendance(prev => ({ ...prev, [id]: status }));
    setIsSaved(false);
    if (status === 'PRESENT') {
      setRemarks(prev => {
        const next = { ...prev };
        delete next[id];
        return next;
      });
    }
  };

  const handleRemarkChange = (id: string, text: string) => {
    setRemarks(prev => ({ ...prev, [id]: text }));
  };

  const handleSave = () => {
    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    setAttendanceRecords(prev => {
      const updated = [...prev];
      Object.entries(sessionAttendance).forEach(([studentId, status]) => {
        const existingIdx = updated.findIndex(r => r.studentId === studentId && r.date === today && r.type === 'SUBJECT' && r.subjectId === subjectId);

        if (existingIdx >= 0) {
          updated[existingIdx] = {
            ...updated[existingIdx],
            status,
            remark: remarks[studentId] || '',
            timestamp
          };
        } else {
          updated.push({
            id: `SUBJECT_${Date.now()}_${studentId}_${subjectId}`,
            studentId,
            date: today,
            type: 'SUBJECT',
            subjectId: subjectId,
            status: status as AttendanceStatus,
            remark: remarks[studentId] || '',
            timestamp
          });
        }
      });
      return updated;
    });

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const handleAddStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStudent.studentId || !newStudent.name) return;
    const student: Student = {
      id: `STU_${Date.now()}`,
      studentId: newStudent.studentId,
      name: newStudent.name,
      level: level,
      department: dept,
      room: room,
      behaviorScore: 100
    };
    setStudents(prev => [...prev, student]);
    setNewStudent({ studentId: '', name: '' });
    setShowAddModal(null);
  };

  const handleAddSubject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newSubject.code || !newSubject.name) return;
    const subject: Subject = {
      id: `SUB_${Date.now()}`,
      code: newSubject.code,
      name: newSubject.name,
      teacherId: currentUser.id
    };
    setSubjects(prev => [...prev, subject]);
    setSubjectId(subject.id);
    setNewSubject({ code: '', name: '' });
    setShowAddModal(null);
  };

  const handleAddRoom = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newRoomValue.trim()) return;
    if (!rooms.includes(newRoomValue)) {
      setRooms(prev => [...prev, newRoomValue]);
      setRoom(newRoomValue);
    }
    setNewRoomValue('');
    setShowAddModal(null);
  };

  return (
    <div className="space-y-4 md:space-y-6 animate-in slide-in-from-bottom-4 duration-500 max-w-[1600px] mx-auto pb-20">
      <div className="flex bg-white p-1 md:p-2 rounded-2xl md:rounded-[24px] border border-slate-200 shadow-sm w-full md:w-fit overflow-hidden">
        <button 
          onClick={() => setViewMode('checkin')} 
          className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-4 md:px-8 py-3 rounded-xl md:rounded-[18px] text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <ClipboardCheck size={18} /> <span className="hidden xs:inline">เช็คชื่อ</span>
        </button>
        <button 
          onClick={() => setViewMode('history')} 
          className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-4 md:px-8 py-3 rounded-xl md:rounded-[18px] text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <History size={18} /> <span className="hidden xs:inline">ประวัติ</span>
        </button>
      </div>

      <div className="bg-white p-4 md:p-6 rounded-[24px] md:rounded-[32px] border border-slate-200 shadow-sm">
        <div className="flex flex-col lg:flex-row gap-6 md:gap-8">
          <div className="flex-1">
            <div className="flex items-center gap-2 text-blue-600 font-black mb-4 md:mb-6 text-base md:text-lg">
              <Filter size={18} />
              <span>ตัวกรองข้อมูล</span>
            </div>
            <div className="grid grid-cols-1 xs:grid-cols-2 md:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
                <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl md:rounded-2xl px-3 py-2.5 md:px-4 md:py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 text-sm appearance-none">
                  {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
                <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl md:rounded-2xl px-3 py-2.5 md:px-4 md:py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 text-sm appearance-none">
                  {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>
              <div className="space-y-1.5">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ห้องเรียน</label>
                  <button onClick={() => setShowAddModal('ROOM')} className="text-blue-600 hover:bg-blue-50 p-1 rounded transition-colors"><Plus size={14} /></button>
                </div>
                <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl md:rounded-2xl px-3 py-2.5 md:px-4 md:py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 text-sm appearance-none">
                  {rooms.map(r => <option key={r} value={r}>ห้อง {r}</option>)}
                </select>
              </div>
              <div className="space-y-1.5">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">รายวิชา</label>
                  <button onClick={() => setShowAddModal('SUBJECT')} className="text-blue-600 hover:bg-blue-50 p-1 rounded transition-colors"><Plus size={14} /></button>
                </div>
                <select value={subjectId} onChange={(e) => setSubjectId(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl md:rounded-2xl px-3 py-2.5 md:px-4 md:py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 text-sm appearance-none">
                  {subjects.map(s => <option key={s.id} value={s.id}>{s.code} - {s.name}</option>)}
                </select>
              </div>
            </div>
          </div>
          <div className="w-full lg:w-64 xl:w-72 bg-slate-900 p-4 md:p-6 rounded-[24px] md:rounded-[32px] border border-slate-800 flex flex-row lg:flex-col items-center lg:items-start justify-between lg:justify-center shadow-xl shrink-0">
            <div className="flex items-center gap-2 text-blue-400">
              <Clock size={16} />
              <span className="text-[9px] md:text-[10px] font-black uppercase tracking-[0.2em] hidden xs:inline">เวลาปัจจุบัน</span>
            </div>
            <div className="lg:mt-2 text-right lg:text-left">
              <p className="text-2xl md:text-4xl font-black text-white tabular-nums tracking-tighter leading-none">
                {currentTime.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
              </p>
              <p className="text-[10px] md:text-xs text-slate-400 font-bold mt-1 uppercase tracking-wider hidden lg:block">
                {currentTime.toLocaleDateString('th-TH', { dateStyle: 'medium' })}
              </p>
            </div>
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <div className="bg-white rounded-[24px] md:rounded-[32px] border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-300">
          <div className="p-4 md:p-6 bg-slate-50/50 border-b border-slate-200 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <Users size={20} className="text-slate-900" />
              <span className="font-black text-slate-900 text-lg md:text-xl tracking-tight">นักเรียน ({filteredStudents.length})</span>
              {isEditingExisting && <span className="px-3 py-1 bg-amber-100 text-amber-700 text-[10px] font-black rounded-lg uppercase tracking-widest animate-pulse">โหมดแก้ไข</span>}
            </div>
            <div className="flex items-center gap-3 w-full sm:w-auto">
              <button onClick={() => setShowAddModal('STUDENT')} className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-2.5 bg-blue-50 text-blue-600 rounded-xl text-xs font-black border border-blue-200 hover:bg-blue-100 transition-all"><UserPlus size={14} /> เพิ่มรายคน</button>
              <button 
                onClick={handleSave}
                disabled={filteredStudents.length === 0}
                className={`flex-1 sm:flex-none px-6 py-2.5 rounded-xl text-white font-black transition-all shadow-lg flex items-center justify-center gap-2 uppercase tracking-widest text-[10px] md:text-xs ${isSaved ? 'bg-green-600' : isEditingExisting ? 'bg-amber-600 shadow-amber-200' : 'bg-slate-900 shadow-slate-200'}`}
              >
                {isSaved ? <CheckCircle2 size={16} /> : isEditingExisting ? <Edit3 size={16} /> : <Save size={16} />}
                {isSaved ? 'อัปเดตสำเร็จ' : isEditingExisting ? 'อัปเดตข้อมูล' : 'ยืนยันการเช็คชื่อ'}
              </button>
            </div>
          </div>

          <div className="hidden md:block overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-white border-b border-slate-100">
                  <th className="px-6 lg:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">ลำดับ</th>
                  <th className="px-6 lg:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">นักเรียน</th>
                  <th className="px-6 lg:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">สถานะ และ หมายเหตุ</th>
                  <th className="px-6 lg:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-center">สถิติ</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {filteredStudents.map((student, idx) => (
                  <tr key={student.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 lg:px-10 py-5 text-sm font-black text-slate-900 align-top">{idx + 1}</td>
                    <td className="px-6 lg:px-10 py-5 align-top">
                      <p className="font-black text-slate-900 text-base leading-tight">{student.name}</p>
                      <p className="text-[10px] text-slate-500 font-extrabold uppercase mt-1 tracking-widest">รหัส: {student.studentId}</p>
                    </td>
                    <td className="px-6 lg:px-10 py-5 align-top">
                      <div className="flex flex-col gap-3">
                        <div className="flex flex-wrap gap-2">
                          {(['PRESENT', 'LATE', 'ABSENT', 'BUSINESS_LEAVE', 'SICK_LEAVE'] as AttendanceStatus[]).map((status) => (
                            <button
                              key={status}
                              onClick={() => handleStatusChange(student.id, status)}
                              className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all border-2 flex items-center gap-1.5 ${sessionAttendance[student.id] === status ? STATUS_LABELS[status].color + ' border-current shadow-md' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}
                            >
                              {STATUS_LABELS[status].icon}
                              {STATUS_LABELS[status].label}
                            </button>
                          ))}
                        </div>
                        {sessionAttendance[student.id] && sessionAttendance[student.id] !== 'PRESENT' && (
                          <div className="relative animate-in slide-in-from-top-2 max-w-md">
                            <MessageSquare className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                            <input type="text" value={remarks[student.id] || ''} onChange={(e) => handleRemarkChange(student.id, e.target.value)} placeholder="ระบุหมายเหตุเพิ่มเติม..." className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-400 rounded-xl pl-9 pr-3 py-2 text-xs font-bold text-slate-900 outline-none" />
                          </div>
                        )}
                      </div>
                    </td>
                    <td className="px-6 lg:px-10 py-5 align-top text-center">
                      <span className="text-[10px] font-black text-slate-900">95%</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-[24px] md:rounded-[32px] border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-300">
          <div className="p-5 md:p-7 bg-slate-50/50 border-b flex items-center justify-between">
            <h3 className="font-black text-slate-900 text-lg md:text-2xl flex items-center gap-3 md:gap-4"><Calendar size={22} className="text-blue-600" /> สมุดบันทึกรายวิชา</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left min-w-[600px]">
              <thead>
                <tr className="bg-white border-b border-slate-100">
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">วันที่</th>
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">นักเรียน</th>
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">สถานะ</th>
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">หมายเหตุ</th>
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-center">จัดการ</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {historyRecords.map((record) => {
                  const student = allStudents.find(s => s.id === record.studentId);
                  return (
                    <tr key={record.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-6 md:px-10 py-5 font-black text-slate-900">{record.date}</td>
                      <td className="px-6 md:px-10 py-5">
                        <p className="font-black text-slate-900">{student?.name}</p>
                        <p className="text-[10px] text-slate-500">{student?.studentId}</p>
                      </td>
                      <td className="px-6 md:px-10 py-5"><span className={`px-4 py-1.5 rounded-lg text-[10px] font-black border-2 ${STATUS_LABELS[record.status].color}`}>{STATUS_LABELS[record.status].label}</span></td>
                      <td className="px-6 md:px-10 py-5 text-xs font-bold">{record.remark || '-'}</td>
                      <td className="px-6 md:px-10 py-5 text-center">
                         <button onClick={() => setViewMode('checkin')} className="p-3 text-slate-400 hover:text-blue-600 rounded-2xl transition-all" title="แก้ไขข้อมูลวันนี้"><Edit3 size={18} /></button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-[32px] p-8 shadow-2xl animate-in zoom-in-95">
            <button onClick={() => setShowAddModal(null)} className="absolute top-6 right-6 text-slate-400"><X size={24} /></button>
            <h3 className="text-2xl font-black text-slate-900 mb-6 text-center uppercase">เพิ่มข้อมูล</h3>
            <form onSubmit={showAddModal === 'STUDENT' ? handleAddStudent : showAddModal === 'SUBJECT' ? handleAddSubject : handleAddRoom} className="space-y-4">
              <input type="text" required value={showAddModal === 'STUDENT' ? newStudent.name : showAddModal === 'SUBJECT' ? newSubject.name : newRoomValue} onChange={(e) => showAddModal === 'STUDENT' ? setNewStudent({...newStudent, name: e.target.value}) : showAddModal === 'SUBJECT' ? setNewSubject({...newSubject, name: e.target.value}) : setNewRoomValue(e.target.value)} className="w-full bg-slate-50 border-2 rounded-2xl px-6 py-4 font-black" placeholder="ชื่อ..." />
              <div className="flex gap-4"><button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-4 bg-slate-100 rounded-2xl">ยกเลิก</button><button type="submit" className="flex-1 py-4 bg-blue-600 text-white rounded-2xl shadow-lg">บันทึก</button></div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ClassAttendance;

import React, { useState, useEffect } from 'react';
import { Student, Subject, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
// Added missing CheckCircle2 import from lucide-react
import { Save, BookOpen, Clock, Users, MessageSquare, UserPlus, X, Plus, Filter, History, ClipboardCheck, Calendar, Edit3, CheckCircle2 } from 'lucide-react';

interface ClassAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  subjects: Subject[];
  setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  currentUser: any;
}

const ClassAttendance: React.FC<ClassAttendanceProps> = ({ 
  students: allStudents, 
  setStudents,
  subjects, 
  setSubjects,
  rooms,
  setRooms,
  attendanceRecords, 
  setAttendanceRecords,
  currentUser
}) => {
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');
  const [level, setLevel] = useState<string>(Object.values(ThaiLevel)[0]);
  const [dept, setDept] = useState<string>(Object.values(Department)[0]);
  const [room, setRoom] = useState(rooms.length > 0 ? rooms[0] : '1');
  const [subjectId, setSubjectId] = useState(subjects.length > 0 ? subjects[0].id : '');
  const [sessionAttendance, setSessionAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [isEditingExisting, setIsEditingExisting] = useState(false);

  const [showAddModal, setShowAddModal] = useState<'STUDENT' | 'SUBJECT' | 'ROOM' | null>(null);
  const [newStudent, setNewStudent] = useState({ studentId: '', name: '' });
  const [newSubject, setNewSubject] = useState({ code: '', name: '' });
  const [newRoomValue, setNewRoomValue] = useState('');

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Sync session with existing records
  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    const existing = attendanceRecords.filter(r => r.date === today && r.type === 'SUBJECT' && r.subjectId === subjectId);

    if (existing.length > 0) {
      const attMap: Record<string, AttendanceStatus> = {};
      const remMap: Record<string, string> = {};
      let hasDataInGroup = false;

      existing.forEach(r => {
        attMap[r.studentId] = r.status;
        if (r.remark) remMap[r.studentId] = r.remark;

        if (!hasDataInGroup) {
          const s = allStudents.find(stu => stu.id === r.studentId);
          if (s && s.level === level && s.department === dept && s.room === room) hasDataInGroup = true;
        }
      });

      setSessionAttendance(attMap);
      setRemarks(remMap);
      setIsEditingExisting(hasDataInGroup);
    } else {
      setSessionAttendance({});
      setRemarks({});
      setIsEditingExisting(false);
    }
  }, [level, dept, room, subjectId, attendanceRecords, allStudents]);

  const filteredStudents = allStudents.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room
  );

  const historyRecords = attendanceRecords.filter(record => {
    const student = allStudents.find(s => s.id === record.studentId);
    return record.type === 'SUBJECT' && 
           record.subjectId === subjectId &&
           student?.level === level && 
           student?.department === dept && 
           student?.room === room;
  }).sort((a, b) => b.date.localeCompare(a.date) || b.timestamp.localeCompare(a.timestamp));

  const handleStatusChange = (id: string, status: AttendanceStatus) => {
    setSessionAttendance(prev => ({ ...prev, [id]: status }));
    setIsSaved(false);
    if (status === 'PRESENT') {
      setRemarks(prev => {
        const next = { ...prev };
        delete next[id];
        return next;
      });
    }
  };

  const handleRemarkChange = (id: string, text: string) => {
    setRemarks(prev => ({ ...prev, [id]: text }));
  };

  const handleSave = () => {
    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    setAttendanceRecords(prev => {
      const updated = [...prev];
      Object.entries(sessionAttendance).forEach(([studentId, status]) => {
        const existingIdx = updated.findIndex(r => r.studentId === studentId && r.date === today && r.type === 'SUBJECT' && r.subjectId === subjectId);

        if (existingIdx >= 0) {
          updated[existingIdx] = {
            ...updated[existingIdx],
            status,
            remark: remarks[studentId] || '',
            timestamp
          };
        } else {
          updated.push({
            id: `SUBJECT_${Date.now()}_${studentId}_${subjectId}`,
            studentId,
            date: today,
            type: 'SUBJECT',
            subjectId: subjectId,
            status: status as AttendanceStatus,
            remark: remarks[studentId] || '',
            timestamp
          });
        }
      });
      return updated;
    });

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const handleAddStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStudent.studentId || !newStudent.name) return;
    const student: Student = {
      id: `STU_${Date.now()}`,
