import React, { useState, useEffect, useMemo } from 'react';
import { Student, AttendanceRecord, BehaviorRecord, ThaiLevel, Department } from '../types';
import { 
  FileText, 
  Search, 
  Download, 
  User, 
  Calendar, 
  Award, 
  TrendingUp,
  BarChart3,
  ShieldAlert,
  Users,
  Grid3X3,
  ChevronLeft,
  ChevronRight,
  Filter,
  Star
} from 'lucide-react';
import { STATUS_LABELS } from '../constants';

interface ReportsProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: BehaviorRecord[];
  user: any;
}

const Reports: React.FC<ReportsProps> = ({ students, attendance, behavior, user }) => {
  const [activeTab, setActiveTab] = useState<'individual' | 'room'>('individual');

  // Individual Report State
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

  // Room Report State
  const [reportLevel, setReportLevel] = useState<string>(Object.values(ThaiLevel)[0]);
  const [reportDept, setReportDept] = useState<string>(Object.values(Department)[0]);
  const [reportRoom, setReportRoom] = useState<string>('1');
  const [reportDate, setReportDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [reportMonth, setReportMonth] = useState<number>(new Date().getMonth());
  const [reportYear, setReportYear] = useState<number>(new Date().getFullYear());
  const [roomViewMode, setRoomViewMode] = useState<'daily' | 'monthly'>('daily');

  // Initial Logic for Parent
  useEffect(() => {
    if (user.role === 'PARENT') {
      const child = students.find(s => s.studentId === user.studentId);
      if (child) setSelectedStudent(child);
      setActiveTab('individual');
    }
  }, [user, students]);

  const filteredStudentsForSidebar = students.filter(s => 
    s.name.includes(searchTerm) || s.studentId.includes(searchTerm)
  );

  const roomStudents = students.filter(s => 
    s.level === reportLevel && s.department === reportDept && s.room === reportRoom
  );

  const getDaysInMonth = (month: number, year: number) => {
    return new Date(year, month + 1, 0).getDate();
  };

  const getStatusInitial = (status: string) => {
    switch(status) {
      case 'PRESENT': return 'ม';
      case 'LATE': return 'ส';
      case 'ABSENT': return 'ข';
      case 'BUSINESS_LEAVE': return 'ก';
      case 'SICK_LEAVE': return 'ป';
      default: return '-';
    }
  };

  const getStatusColorClass = (status: string) => {
    switch(status) {
      case 'PRESENT': return 'text-green-600 bg-green-50';
      case 'LATE': return 'text-amber-600 bg-amber-50';
      case 'ABSENT': return 'text-red-600 bg-red-50';
      case 'BUSINESS_LEAVE': return 'text-blue-600 bg-blue-50';
      case 'SICK_LEAVE': return 'text-purple-600 bg-purple-50';
      default: return 'text-slate-300';
    }
  };

  // Helper to calculate score for a single student in a specific month
  const calculateStudentMorningScore = (studentId: string, month: number, year: number) => {
    const records = attendance.filter(a => 
      a.studentId === studentId && 
      a.type === 'MORNING' && 
      new Date(a.date).getMonth() === month && 
      new Date(a.date).getFullYear() === year
    );

    if (records.length === 0) return 0;
    const totalScore = records.reduce((acc, rec) => {
      if (rec.status === 'PRESENT') return acc + 1;
      if (rec.status === 'LATE') return acc + 0.5;
      return acc;
    }, 0);

    return (totalScore / records.length) * 5;
  };

  const exportToExcel = () => {
    if (!selectedStudent) return;
    let csvContent = "data:text/csv;charset=utf-8,\uFEFF";
    csvContent += `รายงานข้อมูลนักเรียนรายบุคคล\nรหัสประจำตัว,${selectedStudent.studentId}\nชื่อ-นามสกุล,${selectedStudent.name}\nระดับชั้น,${selectedStudent.level}\nแผนกวิชา,${selectedStudent.department}\nคะแนนพฤติกรรมสะสม,${selectedStudent.behaviorScore}\n\n`;
    csvContent += `ประวัติการเข้าแถว/เข้าเรียน\nวันที่,ประเภท,สถานะ,หมายเหตุ,เวลา\n`;
    const studentAttendance = attendance.filter(a => a.studentId === selectedStudent.id);
    studentAttendance.forEach(a => { 
      csvContent += `${a.date},${a.type === 'MORNING' ? 'เข้าแถว' : 'รายวิชา'},${STATUS_LABELS[a.status].label},"${a.remark || ''}",${a.timestamp}\n`; 
    });
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a"); 
    link.setAttribute("href", encodedUri); 
    link.setAttribute("download", `รายงาน_${selectedStudent.studentId}.csv`); 
    link.click();
  };

  const months = [
    "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
    "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
  ];

