          <button 
            onClick={() => setActiveTab('individual')} 
            className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${activeTab === 'individual' ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <User size={18} /> รายบุคคล
          </button>
          <button 
            onClick={() => setActiveTab('room')} 
            className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${activeTab === 'room' ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <Users size={18} /> รายห้อง
          </button>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {activeTab === 'individual' ? (
          <>
            {/* Sidebar - Individual */}
            {user.role !== 'PARENT' && (
              <div className="lg:col-span-1 space-y-6">
                <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm h-[calc(100vh-220px)] flex flex-col">
                  <h3 className="font-black text-slate-900 uppercase tracking-[0.2em] text-xs mb-6 px-1">รายชื่อนักเรียน</h3>
                  <div className="relative mb-6">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input 
                      type="text" 
                      placeholder="รหัส หรือ ชื่อ..." 
                      value={searchTerm} 
                      onChange={(e) => setSearchTerm(e.target.value)} 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl pl-11 pr-4 py-3.5 font-bold text-slate-900 text-sm outline-none transition-all" 
                    />
                  </div>
                  <div className="flex-1 overflow-y-auto space-y-2 pr-2">
                    {filteredStudentsForSidebar.map(s => (
                      <button 
                        key={s.id} 
                        onClick={() => setSelectedStudent(s)} 
                        className={`w-full text-left p-4 rounded-2xl border-2 transition-all ${selectedStudent?.id === s.id ? 'bg-slate-900 border-slate-900 text-white shadow-xl' : 'bg-white border-transparent hover:bg-slate-50 text-slate-900'}`}
                      >
                        <p className="font-black text-sm truncate">{s.name}</p>
                        <p className={`text-[10px] font-extrabold uppercase mt-1 tracking-widest ${selectedStudent?.id === s.id ? 'text-slate-400' : 'text-slate-500'}`}>{s.studentId}</p>
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}

            {/* Content - Individual */}
