              {selectedStudent ? (
                <div className="animate-in slide-in-from-right-4 duration-500">
                  {user.role === 'PARENT' && (
                    <div className="bg-indigo-600 p-6 rounded-[32px] text-white flex items-center gap-4 mb-6 shadow-xl shadow-indigo-100">
                      <ShieldAlert size={24} className="shrink-0" />
                      <p className="font-black text-sm uppercase tracking-wider">โหมดการดูข้อมูลผู้ปกครอง: ข้อมูลของบุตรหลานของท่าน</p>
                    </div>
