                  <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6 mb-8">
                    <div className="flex items-center gap-6">
                      <div className="w-20 h-20 bg-slate-900 rounded-[28px] flex items-center justify-center text-white shadow-xl"><User size={40} /></div>
                      <div>
                        <h2 className="text-3xl font-black text-slate-900 leading-tight">{selectedStudent.name}</h2>
                        <p className="text-slate-500 font-extrabold uppercase text-xs tracking-[0.2em] mt-2">{selectedStudent.level} • {selectedStudent.department} (ห้อง {selectedStudent.room})</p>
                      </div>
                    </div>
                    <button 
