                            <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">วันที่</th>
                            <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">ประเภท</th>
                            <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">สถานะ</th>
                            <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">หมายเหตุ</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                          {attendance.filter(a => a.studentId === selectedStudent.id).sort((a,b) => b.date.localeCompare(a.date)).map(a => (
                            <tr key={a.id} className="hover:bg-slate-50 transition-colors">
                              <td className="px-8 py-5 font-extrabold text-slate-900 text-base">{a.date}</td>
                              <td className="px-8 py-5 text-xs font-bold text-slate-500">{a.type === 'MORNING' ? 'เข้าแถว' : 'รายวิชา'}</td>
                              <td className="px-8 py-5">
                                <span className={`px-4 py-1.5 rounded-full text-[11px] font-black border-2 ${STATUS_LABELS[a.status].color}`}>
                                  {STATUS_LABELS[a.status].label}
                                </span>
                              </td>
                              <td className="px-8 py-5 text-xs font-bold text-slate-700">{a.remark || '-'}</td>
