                    <User size={64} className="text-slate-200" />
                  </div>
                  <h3 className="text-3xl font-black text-slate-900 mb-4 uppercase tracking-tighter">เลือกนักเรียนที่ต้องการ</h3>
                  <p className="text-slate-500 font-bold max-w-sm text-lg">ค้นหาจากรายชื่อเพื่อเรียกดูประวัติอย่างละเอียด</p>
                </div>
              )}
            </div>
          </>
        ) : (
          /* Content - Room Report */
          <div className="lg:col-span-4 space-y-8 animate-in slide-in-from-bottom-4 duration-500">
            {/* Room Filter Header */}
            <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
              <div className="flex flex-col xl:flex-row gap-8 items-end">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-1 w-full">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
                    <select value={reportLevel} onChange={(e) => setReportLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none transition-all">
                      {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
                    <select value={reportDept} onChange={(e) => setReportDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none transition-all">
                      {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ห้องเรียน</label>
                    <select value={reportRoom} onChange={(e) => setReportRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none transition-all">
                      {[1,2,3,4,5].map(v => <option key={v} value={v}>ห้อง {v}</option>)}
                    </select>
                  </div>
                </div>

                <div className="flex bg-slate-100 p-2 rounded-[24px] w-full xl:w-fit shrink-0">
                  <button onClick={() => setRoomViewMode('daily')} className={`flex-1 xl:flex-none px-6 py-3.5 rounded-[18px] text-xs font-black tracking-widest uppercase transition-all ${roomViewMode === 'daily' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500'}`}>รายวัน</button>
                  <button onClick={() => setRoomViewMode('monthly')} className={`flex-1 xl:flex-none px-6 py-3.5 rounded-[18px] text-xs font-black tracking-widest uppercase transition-all ${roomViewMode === 'monthly' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500'}`}>รายเดือน</button>
                </div>
              </div>

              {/* View Specific Filters */}
              <div className="mt-8 pt-8 border-t border-slate-100 flex flex-col md:flex-row items-center justify-between gap-6">
                {roomViewMode === 'daily' ? (
                  <div className="flex items-center gap-4">
                    <Calendar className="text-blue-600" />
                    <input type="date" value={reportDate} onChange={(e) => setReportDate(e.target.value)} className="bg-slate-50 border-none font-black text-slate-900 px-6 py-3 rounded-2xl outline-none" />
                  </div>
                ) : (
                  <div className="flex items-center gap-4">
                    <Calendar className="text-blue-600" />
                    <div className="flex gap-2">
                      <select value={reportMonth} onChange={(e) => setReportMonth(parseInt(e.target.value))} className="bg-slate-50 border-none font-black text-slate-900 px-6 py-3 rounded-2xl outline-none">
                        {months.map((m, i) => <option key={m} value={i}>{m}</option>)}
                      </select>
                      <select value={reportYear} onChange={(e) => setReportYear(parseInt(e.target.value))} className="bg-slate-50 border-none font-black text-slate-900 px-6 py-3 rounded-2xl outline-none">
                        {[2024, 2025].map(y => <option key={y} value={y}>{y}</option>)}
                      </select>
                    </div>
                  </div>
                )}

                <div className="flex items-center gap-8">
                   <div className="text-right">
                     <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">จำนวนนักเรียนในห้อง</p>
                     <p className="text-2xl font-black text-slate-900">{roomStudents.length} คน</p>
                   </div>
                </div>
              </div>
            </div>

            {/* Matrix View */}
            <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
              <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/30">
                <h3 className="font-black text-slate-900 text-xl flex items-center gap-3">
                  <Grid3X3 size={24} className="text-indigo-600" /> 
                  ตารางสรุปพฤติกรรมการเข้าเรียน {roomViewMode === 'daily' ? 'รายวัน' : 'รายเดือน'}
                </h3>
              </div>

              <div className="overflow-x-auto">
                {roomViewMode === 'daily' ? (
                  <table className="w-full text-left">
                    <thead>
                      <tr className="bg-white border-b border-slate-100">
                        <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">รหัสนักเรียน</th>
                        <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ชื่อ-นามสกุล</th>
                        <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">เช็คชื่อเช้า</th>
                        <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">คะแนน (5.0)</th>
                        <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">หมายเหตุ</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {roomStudents.map(s => {
                        const dayAtt = attendance.find(a => a.studentId === s.id && a.date === reportDate && a.type === 'MORNING');
                        let score = 0;
                        if (dayAtt?.status === 'PRESENT') score = 5.0;
                        else if (dayAtt?.status === 'LATE') score = 2.5;

                        return (
                          <tr key={s.id} className="hover:bg-slate-50/50 transition-colors">
                            <td className="px-10 py-6 font-bold text-slate-500">{s.studentId}</td>
                            <td className="px-10 py-6 font-black text-slate-900 text-lg">{s.name}</td>
                            <td className="px-10 py-6">
                              {dayAtt ? (
                                <span className={`px-4 py-1.5 rounded-full text-[11px] font-black border-2 ${STATUS_LABELS[dayAtt.status].color}`}>
                                  {STATUS_LABELS[dayAtt.status].label}
                                </span>
                              ) : <span className="text-slate-300 font-bold">- ไม่มีข้อมูล -</span>}
                            </td>
                            <td className="px-10 py-6">
                               <span className={`text-lg font-black ${score >= 4 ? 'text-green-600' : score >= 2.5 ? 'text-amber-600' : 'text-red-600'}`}>
                                 {score.toFixed(1)}
                               </span>
                            </td>
                            <td className="px-10 py-6 text-sm font-bold text-slate-500">{dayAtt?.remark || '-'}</td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                ) : (
                  /* Monthly Matrix View */
                  <table className="w-full text-left border-collapse">
                    <thead>
                      <tr className="bg-slate-900 text-white">
                        <th className="px-6 py-5 text-[10px] font-black uppercase tracking-widest sticky left-0 z-10 bg-slate-900 min-w-[220px]">รายชื่อนักเรียน</th>
                        <th className="px-4 py-5 text-[10px] font-black text-center min-w-[60px] bg-amber-600 sticky right-0 z-10">คะแนน (5.0)</th>
                        {Array.from({ length: getDaysInMonth(reportMonth, reportYear) }).map((_, i) => (
                          <th key={i} className="px-3 py-5 text-[10px] font-black text-center min-w-[40px] border-l border-slate-800">{i + 1}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {roomStudents.map(s => {
                        const monthlyScore = calculateStudentMorningScore(s.id, reportMonth, reportYear);
                        return (
                          <tr key={s.id} className="hover:bg-slate-50 group">
                            <td className="px-6 py-5 font-black text-slate-900 text-sm sticky left-0 z-10 bg-white group-hover:bg-slate-50 border-r border-slate-100 shadow-[2px_0_5px_rgba(0,0,0,0.05)]">
                              {s.name}
                              <p className="text-[10px] font-bold text-slate-400 mt-0.5">{s.studentId}</p>
                            </td>
                            <td className="px-4 py-5 font-black text-center sticky right-0 z-10 bg-amber-50 group-hover:bg-amber-100 border-l border-amber-200">
                               <span className={`text-sm ${monthlyScore >= 4 ? 'text-green-700' : monthlyScore >= 2.5 ? 'text-amber-700' : 'text-red-700'}`}>
                                 {monthlyScore.toFixed(1)}
                               </span>
                            </td>
                            {Array.from({ length: getDaysInMonth(reportMonth, reportYear) }).map((_, i) => {
                              const dateStr = `${reportYear}-${String(reportMonth + 1).padStart(2, '0')}-${String(i + 1).padStart(2, '0')}`;
                              const att = attendance.find(a => a.studentId === s.id && a.date === dateStr && a.type === 'MORNING');
                              return (
                                <td key={i} className="p-1 border-l border-slate-50 text-center">
                                  <div className={`w-8 h-8 flex items-center justify-center rounded-lg text-xs font-black mx-auto transition-transform ${getStatusColorClass(att?.status || '')}`}>
                                    {getStatusInitial(att?.status || '')}
                                  </div>
                                </td>
                              );
                            })}
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                )}
              </div>

              {/* Legend for Monthly View */}
              {roomViewMode === 'monthly' && (
                <div className="p-8 bg-slate-50 border-t border-slate-100">
                   <div className="flex flex-wrap gap-8">
                     {Object.entries(STATUS_LABELS).map(([key, val]) => (
                       <div key={key} className="flex items-center gap-3">
                         <div className={`w-8 h-8 flex items-center justify-center rounded-lg text-xs font-black ${getStatusColorClass(key)}`}>
                            {getStatusInitial(key)}
                         </div>
                         <span className="text-xs font-black text-slate-700 uppercase tracking-widest">{val.label}</span>
                       </div>
                     ))}
                   </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

