import React from 'react';
import { StudyBlock } from '../types';
import { Calendar, Save, CheckCircle2, Clock } from 'lucide-react';

interface SystemSettingsProps {
  studyBlocks: StudyBlock[];
  setStudyBlocks: React.Dispatch<React.SetStateAction<StudyBlock[]>>;
}

const SystemSettings: React.FC<SystemSettingsProps> = ({ studyBlocks, setStudyBlocks }) => {
  const handleUpdateBlock = (id: number, field: keyof StudyBlock, value: any) => {
    setStudyBlocks(prev => prev.map(block => 
      block.id === id ? { ...block, [field]: value } : block
    ));
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
        <div className="flex items-center gap-4 mb-8">
          <div className="p-4 bg-blue-600 rounded-2xl text-white shadow-lg shadow-blue-100">
            <Calendar size={28} />
          </div>
          <div>
            <h2 className="text-2xl font-black text-slate-900 tracking-tight">ตั้งค่าบล็อกเวลาเรียน (Block Course)</h2>
            <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">กำหนด 5 บล็อกเวลาเพื่อใช้คำนวณคะแนนการเข้าแถว (18 วันเรียน/บล็อก)</p>
          </div>
        </div>

        <div className="grid grid-cols-1 gap-6">
          {studyBlocks.map((block) => (
            <div key={block.id} className={`p-8 rounded-[32px] border-2 transition-all ${block.isActive ? 'bg-white border-blue-100 shadow-md' : 'bg-slate-50 border-slate-100 opacity-60'}`}>
              <div className="flex flex-col lg:flex-row items-center gap-8">
                <div className="flex items-center gap-5 shrink-0">
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl shadow-sm ${block.isActive ? 'bg-blue-600 text-white' : 'bg-slate-300 text-slate-500'}`}>
                    {block.id}
                  </div>
                  <div>
                    <input 
                      type="text" 
                      value={block.name} 
                      onChange={(e) => handleUpdateBlock(block.id, 'name', e.target.value)}
                      className="bg-transparent border-none font-black text-slate-900 text-xl outline-none focus:ring-0 p-0"
                    />
                    <div className="flex items-center gap-2 mt-1">
                      <input 
                        type="checkbox" 
                        checked={block.isActive} 
                        onChange={(e) => handleUpdateBlock(block.id, 'isActive', e.target.checked)}
                        className="rounded border-slate-300 text-blue-600 focus:ring-blue-500"
                        id={`active-${block.id}`}
                      />
                      <label htmlFor={`active-${block.id}`} className="text-[10px] font-black text-slate-400 uppercase tracking-widest cursor-pointer">เปิดใช้งานการคำนวณ</label>
                    </div>
                  </div>
                </div>

                <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-6 w-full">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">วันที่เริ่มต้นบล็อก</label>
                    <div className="relative">
                      <Clock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                      <input 
                        type="date" 
                        value={block.startDate} 
                        onChange={(e) => handleUpdateBlock(block.id, 'startDate', e.target.value)}
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl pl-12 pr-4 py-3.5 font-bold text-slate-900 outline-none transition-all"
                      />
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">วันที่สิ้นสุดบล็อก</label>
                    <div className="relative">
                      <Clock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                      <input 
                        type="date" 
                        value={block.endDate} 
                        onChange={(e) => handleUpdateBlock(block.id, 'endDate', e.target.value)}
                        className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl pl-12 pr-4 py-3.5 font-bold text-slate-900 outline-none transition-all"
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="mt-12 flex items-center justify-between p-8 bg-blue-50 rounded-[32px] border border-blue-100">
           <div className="flex items-center gap-4 text-blue-700">
             <CheckCircle2 size={24} />
             <p className="text-sm font-black uppercase tracking-wider">ระบบจะบันทึกการตั้งค่าอัตโนมัติลงในหน่วยความจำเครื่อง</p>
           </div>
           <div className="text-right">
             <p className="text-[10px] font-black text-blue-400 uppercase tracking-[0.2em] mb-1">เกณฑ์การคำนวณปัจจุบัน</p>
             <p className="text-lg font-black text-blue-900">(มาเรียนจริง * 5) / 18</p>
           </div>
        </div>
      </div>
    </div>
  );
};

export default SystemSettings;

