import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import MorningAttendance from './components/MorningAttendance';
import ClassAttendance from './components/ClassAttendance';
import BehaviorSystem from './components/BehaviorSystem';
import StudentManagement from './components/StudentManagement';
import Reports from './components/Reports';
import UserManagement from './components/UserManagement';
import SystemSettings from './components/SystemSettings';
import MorningScoreSummary from './components/MorningScoreSummary';
import Login from './components/Login';
import { MOCK_STUDENTS, MOCK_ATTENDANCE, MOCK_BEHAVIOR, MOCK_SUBJECTS } from './data/mockData';
import { Student, AttendanceRecord, BehaviorRecord, Subject, User, StudyBlock } from './types';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeMenu, setActiveMenu] = useState('dashboard');

  // Central States
  const [students, setStudents] = useState<Student[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [behaviorRecords, setBehaviorRecords] = useState<BehaviorRecord[]>([]);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);
  const [systemUsers, setSystemUsers] = useState<User[]>([]);
  const [studyBlocks, setStudyBlocks] = useState<StudyBlock[]>([
    { id: 1, name: 'บล็อกที่ 1', startDate: '2024-03-01', endDate: '2024-03-25', isActive: true },
    { id: 2, name: 'บล็อกที่ 2', startDate: '', endDate: '', isActive: false },
    { id: 3, name: 'บล็อกที่ 3', startDate: '', endDate: '', isActive: false },
    { id: 4, name: 'บล็อกที่ 4', startDate: '', endDate: '', isActive: false },
    { id: 5, name: 'บล็อกที่ 5', startDate: '', endDate: '', isActive: false },
  ]);

  // Initialize data
  useEffect(() => {
    const savedStudents = localStorage.getItem('cms_students');
    const savedAttendance = localStorage.getItem('cms_attendance');
    const savedBehavior = localStorage.getItem('cms_behavior');
    const savedSubjects = localStorage.getItem('cms_subjects');
    const savedRooms = localStorage.getItem('cms_rooms');
    const savedUsers = localStorage.getItem('cms_system_users');
    const savedBlocks = localStorage.getItem('cms_study_blocks');

    if (savedStudents) setStudents(JSON.parse(savedStudents));
    else setStudents(MOCK_STUDENTS);

    if (savedAttendance) setAttendance(JSON.parse(savedAttendance));
    else setAttendance(MOCK_ATTENDANCE);

    if (savedBehavior) setBehaviorRecords(JSON.parse(savedBehavior));
    else setBehaviorRecords(MOCK_BEHAVIOR);

    if (savedSubjects) setSubjects(JSON.parse(savedSubjects));
    else setSubjects(MOCK_SUBJECTS);

    if (savedRooms) setRooms(JSON.parse(savedRooms));

    if (savedUsers) setSystemUsers(JSON.parse(savedUsers));
    else setSystemUsers([
      { id: 'T1', name: 'อ.สมพงษ์ ใจสว่าง', role: 'TEACHER', username: 'teacher', password: '1234', department: 'เทคโนโลยีสารสนเทศ' },
      { id: 'A1', name: 'แอดมิน ระบบ', role: 'ADMIN', username: 'admin', password: '1234', department: 'ส่วนกลาง' },
      { id: 'P1', name: 'คุณแม่ มณี', role: 'PARENT', username: 'parent', password: '1234', studentId: '661001' }
    ]);

    if (savedBlocks) setStudyBlocks(JSON.parse(savedBlocks));
  }, []);

  // Save to LocalStorage
  useEffect(() => {
    if (students.length > 0) localStorage.setItem('cms_students', JSON.stringify(students));
    localStorage.setItem('cms_attendance', JSON.stringify(attendance));
    localStorage.setItem('cms_behavior', JSON.stringify(behaviorRecords));
    localStorage.setItem('cms_subjects', JSON.stringify(subjects));
    localStorage.setItem('cms_rooms', JSON.stringify(rooms));
    localStorage.setItem('cms_system_users', JSON.stringify(systemUsers));
    localStorage.setItem('cms_study_blocks', JSON.stringify(studyBlocks));
  }, [students, attendance, behaviorRecords, subjects, rooms, systemUsers, studyBlocks]);

  if (!user) {
    return <Login onLogin={setUser} systemUsers={systemUsers} />;
  }

  const renderContent = () => {
    if ((activeMenu === 'users' || activeMenu === 'settings') && user.role !== 'ADMIN') {
      setActiveMenu('dashboard');
      return null;
    }

    switch (activeMenu) {
      case 'dashboard':
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
      case 'students':
        return <StudentManagement students={students} setStudents={setStudents} />;
      case 'morning':
        return (
          <MorningAttendance 
            students={students} 
            setStudents={setStudents}
            attendanceRecords={attendance}
            setAttendanceRecords={setAttendance}
            rooms={rooms}
            setRooms={setRooms}
          />
        );
      case 'subject':
        return (
          <ClassAttendance 
            students={students} 
            setStudents={setStudents}
            subjects={subjects}
            setSubjects={setSubjects}
            rooms={rooms}
            setRooms={setRooms}
            attendanceRecords={attendance}
            setAttendanceRecords={setAttendance}
            currentUser={user}
          />
        );
      case 'behavior':
        return (
          <BehaviorSystem 
            students={students} 
            setStudents={setStudents}
            behaviorRecords={behaviorRecords}
            setBehaviorRecords={setBehaviorRecords}
          />
        );
      case 'report':
        return <Reports students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
      case 'morning_scores':
        return <MorningScoreSummary students={students} attendance={attendance} studyBlocks={studyBlocks} />;
      case 'users':
        return <UserManagement users={systemUsers} setUsers={setSystemUsers} />;
      case 'settings':
        return <SystemSettings studyBlocks={studyBlocks} setStudyBlocks={setStudyBlocks} />;
      default:
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
    }
  };

  return (
    <Layout 
      activeMenu={activeMenu} 
      setActiveMenu={setActiveMenu} 
      user={user}
      onLogout={() => setUser(null)}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useMemo } from 'react';
import { StudyBlock } from '../types';
import { Calendar as CalendarIcon, Save, CheckCircle2, Clock, AlertCircle, Info, CalendarDays } from 'lucide-react';

interface SystemSettingsProps {
  studyBlocks: StudyBlock[];
  setStudyBlocks: React.Dispatch<React.SetStateAction<StudyBlock[]>>;
}

const BLOCK_COLORS = [
  'bg-blue-500',
  'bg-indigo-500',
  'bg-purple-500',
  'bg-pink-500',
  'bg-emerald-500'
];

const BLOCK_TEXT_COLORS = [
  'text-blue-600',
  'text-indigo-600',
  'text-purple-600',
  'text-pink-600',
  'text-emerald-600'
];

const SystemSettings: React.FC<SystemSettingsProps> = ({ studyBlocks, setStudyBlocks }) => {

  // Helper to count weekdays (Mon-Fri) between two dates
  const countWeekdays = (startStr: string, endStr: string) => {
    if (!startStr || !endStr) return 0;
    const start = new Date(startStr);
    const end = new Date(endStr);
    let count = 0;
    const curDate = new Date(start.getTime());
    while (curDate <= end) {
      const dayOfWeek = curDate.getDay();
      if (dayOfWeek !== 0 && dayOfWeek !== 6) count++;
      curDate.setDate(curDate.getDate() + 1);
    }
    return count;
  };

  const handleUpdateBlock = (id: number, field: keyof StudyBlock, value: any) => {
    setStudyBlocks(prev => prev.map(block => 
      block.id === id ? { ...block, [field]: value } : block
    ));
  };

  // Generate simple visual timeline data
  const timelineData = useMemo(() => {
    const activeBlocks = studyBlocks.filter(b => b.isActive && b.startDate && b.endDate);
    if (activeBlocks.length === 0) return null;

    // Find min and max dates to show a range
    const dates = activeBlocks.flatMap(b => [new Date(b.startDate), new Date(b.endDate)]);
    const minDate = new Date(Math.min(...dates.map(d => d.getTime())));
    const maxDate = new Date(Math.max(...dates.map(d => d.getTime())));

    // Add 1 week buffer
    minDate.setDate(minDate.getDate() - 7);
    maxDate.setDate(maxDate.getDate() + 7);

    return { minDate, maxDate };
  }, [studyBlocks]);

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20 max-w-6xl mx-auto">
      <div className="bg-white p-8 md:p-12 rounded-[48px] border border-slate-200 shadow-sm relative overflow-hidden">
        {/* Background Decor */}
        <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-blue-50 rounded-full blur-3xl opacity-50" />

        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-6 mb-12 relative z-10">
          <div className="flex items-center gap-6">
            <div className="p-5 bg-slate-900 rounded-[24px] text-white shadow-2xl">
              <CalendarIcon size={32} />
            </div>
            <div>
              <h2 className="text-3xl font-black text-slate-900 tracking-tight">ตั้งค่าบล็อกเวลาเรียน</h2>
              <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">Block Course Management System</p>
            </div>
          </div>
          <div className="flex items-center gap-3 px-6 py-3 bg-amber-50 text-amber-700 rounded-2xl border border-amber-100">
            <Info size={18} />
            <span className="text-xs font-black uppercase tracking-wider">เกณฑ์ 18 วันเรียน (จันทร์-ศุกร์)</span>
          </div>
        </div>

        {/* Visual Calendar Preview Section */}
        <div className="mb-12 p-8 bg-slate-50 rounded-[32px] border border-slate-100 relative">
          <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
            <CalendarDays size={14} /> แผนผังช่วงเวลาเรียนภาพรวม
          </h3>

          <div className="space-y-4">
            {studyBlocks.map((block, idx) => {
              const weekdays = countWeekdays(block.startDate, block.endDate);
              const isActive = block.isActive && block.startDate && block.endDate;

              return (
                <div key={block.id} className="flex items-center gap-4">
                  <div className="w-24 shrink-0">
                    <span className={`text-[10px] font-black uppercase tracking-widest ${isActive ? BLOCK_TEXT_COLORS[idx] : 'text-slate-400'}`}>
                      {block.name}
                    </span>
                  </div>
                  <div className="flex-1 h-3 bg-slate-200 rounded-full overflow-hidden relative">
                    {isActive && (
                      <div 
                        className={`absolute h-full ${BLOCK_COLORS[idx]} opacity-80 rounded-full shadow-sm`}
                        style={{ 
                          left: '10%', // Simulation of relative position
                          width: `${Math.min(90, (weekdays / 25) * 100)}%` 
                        }}
                      />
                    )}
                  </div>
                  <div className="w-32 text-right">
                    {isActive ? (
                      <span className={`text-[10px] font-black ${weekdays === 18 ? 'text-green-600' : 'text-amber-600'}`}>
                        {weekdays} วันเรียน {weekdays === 18 ? '✓' : ''}
                      </span>
                    ) : (
                      <span className="text-[10px] font-black text-slate-300 italic">ไม่ได้เปิดใช้งาน</span>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
