                             <span className="text-slate-400 font-bold text-xs">จริง</span>
                           </div>
                           <span className="text-slate-300">+</span>
                           <div className="flex items-baseline gap-1">
                             <span className="text-xl font-black text-amber-500">{result.holidayDays}</span>
