                             <div className={`${bgColor} h-full rounded-full transition-all duration-1000`} style={{ width: `${(result.totalDays / 18) * 100}%` }} />
                           </div>
                           <span className="text-xs font-black text-slate-900">{result.totalDays}/18</span>
                         </div>
                      </td>
                      <td className="px-10 py-7 text-center">
                         <div className={`text-3xl font-black ${scoreColor}`}>
                           {result.score.toFixed(2)}
                         </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          ) : (
            <div className="py-32 flex flex-col items-center justify-center text-slate-300">
               <AlertCircle size={48} className="mb-4 opacity-20" />
               <p className="text-xl font-black text-slate-900">ไม่พบคลาสเรียนหรือรายชื่อที่ต้องการ</p>
               <p className="text-sm font-bold mt-1">กรุณาตรวจสอบการตั้งค่าฟิลเตอร์</p>
