import React, { useState, useMemo } from 'react';
import { StudyBlock } from '../types';
import { Calendar as CalendarIcon, Save, CheckCircle2, Clock, AlertCircle, Info, CalendarDays, Plus, Trash2, Sun } from 'lucide-react';

interface SystemSettingsProps {
  studyBlocks: StudyBlock[];
  setStudyBlocks: React.Dispatch<React.SetStateAction<StudyBlock[]>>;
}

const BLOCK_COLORS = [
  'bg-blue-500',
  'bg-indigo-500',
  'bg-purple-500',
  'bg-pink-500',
  'bg-emerald-500'
];

const BLOCK_TEXT_COLORS = [
  'text-blue-600',
  'text-indigo-600',
  'text-purple-600',
  'text-pink-600',
  'text-emerald-600'
];

const SystemSettings: React.FC<SystemSettingsProps> = ({ studyBlocks, setStudyBlocks }) => {
  const [newHolidayDate, setNewHolidayDate] = useState<Record<number, string>>({});

  // Helper to count weekdays (Mon-Fri) between two dates
  const countWeekdays = (startStr: string, endStr: string) => {
    if (!startStr || !endStr) return 0;
    const start = new Date(startStr);
    const end = new Date(endStr);
    let count = 0;
    const curDate = new Date(start.getTime());
    while (curDate <= end) {
      const dayOfWeek = curDate.getDay();
      if (dayOfWeek !== 0 && dayOfWeek !== 6) count++;
      curDate.setDate(curDate.getDate() + 1);
    }
    return count;
  };

  const handleUpdateBlock = (id: number, field: keyof StudyBlock, value: any) => {
    setStudyBlocks(prev => prev.map(block => 
      block.id === id ? { ...block, [field]: value } : block
    ));
  };

  const handleAddHoliday = (blockId: number) => {
    const date = newHolidayDate[blockId];
    if (!date) return;

    setStudyBlocks(prev => prev.map(block => {
      if (block.id === blockId) {
        if (block.holidays.includes(date)) return block;
        return { ...block, holidays: [...block.holidays, date].sort() };
      }
      return block;
    }));
    setNewHolidayDate(prev => ({ ...prev, [blockId]: '' }));
  };

  const handleRemoveHoliday = (blockId: number, date: string) => {
    const formattedDate = new Date(date).toLocaleDateString('th-TH', { dateStyle: 'long' });
    if (window.confirm(`คุณต้องการลบวันหยุดพิเศษวันที่ ${formattedDate} ใช่หรือไม่?`)) {
      setStudyBlocks(prev => prev.map(block => {
        if (block.id === blockId) {
          return { ...block, holidays: block.holidays.filter(d => d !== date) };
        }
        return block;
      }));
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20 max-w-6xl mx-auto">
      <div className="bg-white p-8 md:p-12 rounded-[48px] border border-slate-200 shadow-sm relative overflow-hidden">
