import React, { useState } from 'react';
import { Student, BehaviorRecord } from '../types';
import { Award, PlusCircle, MinusCircle, FileText, Download, Search, AlertCircle, Trash2 } from 'lucide-react';

interface BehaviorSystemProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  behaviorRecords: BehaviorRecord[];
  setBehaviorRecords: React.Dispatch<React.SetStateAction<BehaviorRecord[]>>;
}

const BehaviorSystem: React.FC<BehaviorSystemProps> = ({ students, setStudents, behaviorRecords, setBehaviorRecords }) => {
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(null);
  const [scoreChange, setScoreChange] = useState<number>(5);
  const [reason, setReason] = useState('');
  const [searchTerm, setSearchTerm] = useState('');

  const selectedStudent = students.find(s => s.id === selectedStudentId);
  const filteredStudents = students.filter(s => s.name.includes(searchTerm) || s.studentId.includes(searchTerm));

  const handleScoreUpdate = (type: 'ADD' | 'DEDUCT') => {
    if (!selectedStudent || !reason.trim()) return;

    const change = type === 'ADD' ? scoreChange : -scoreChange;
    const newScore = Math.min(100, Math.max(0, selectedStudent.behaviorScore + change));

    // Update Student Score
    setStudents(prev => prev.map(s => 
      s.id === selectedStudentId ? { ...s, behaviorScore: newScore } : s
    ));

    // Add History Record
    const newRecord: BehaviorRecord = {
      id: `BEH_${Date.now()}`,
      studentId: selectedStudent.id,
      type,
      score: scoreChange,
      reason,
      date: new Date().toLocaleDateString('th-TH'),
      recordedBy: 'อาจารย์ผู้สอน'
    };

    setBehaviorRecords(prev => [newRecord, ...prev]);
    setReason('');
  };

  const handleDeleteBehavior = (id: string) => {
    const record = behaviorRecords.find(b => b.id === id);
    if (!record) return;

    const confirmMsg = `ยืนยันการลบบันทึกพฤติกรรม: "${record.reason}"?\nคะแนนนักเรียนจะถูกปรับคืนโดยอัตโนมัติ`;
    if (window.confirm(confirmMsg)) {
      // Revert the score on the student
      setStudents(prev => prev.map(s => {
        if (s.id === record.studentId) {
          // If we added score, we now subtract it. If we deducted, we now add it back.
          const adjustment = record.type === 'ADD' ? -record.score : record.score;
          return { ...s, behaviorScore: Math.min(100, Math.max(0, s.behaviorScore + adjustment)) };
        }
        return s;
      }));

      // Remove the record
      setBehaviorRecords(prev => prev.filter(b => b.id !== id));
    }
  };

  const getScoreStatus = (score: number) => {
    if (score >= 90) return { label: 'ดีมาก', color: 'bg-green-100 text-green-800' };
    if (score >= 70) return { label: 'ดี', color: 'bg-blue-100 text-blue-800' };
    return { label: 'เฝ้าระวัง', color: 'bg-red-100 text-red-800' };
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm flex flex-col h-[calc(100vh-200px)]">
        <div className="p-4 border-b bg-slate-50">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-black" size={18} />
            <input type="text" placeholder="ค้นหานักเรียน..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white border border-slate-300 rounded-xl pl-10 pr-3 py-2.5 font-bold text-black" />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto p-2 space-y-1">
          {filteredStudents.map(student => (
            <button key={student.id} onClick={() => setSelectedStudentId(student.id)} className={`w-full text-left p-4 rounded-xl border transition-all ${selectedStudentId === student.id ? 'bg-blue-600 border-blue-700 text-white' : 'bg-white hover:bg-slate-50 text-black'}`}>
              <div className="flex justify-between items-start">
                <div><p className="font-black text-sm">{student.name}</p></div>
                <div className={`px-2 py-0.5 rounded-lg text-xs font-black ${selectedStudentId === student.id ? 'bg-white text-blue-600' : getScoreStatus(student.behaviorScore).color}`}>
                  {student.behaviorScore}
                </div>
              </div>
            </button>
          ))}
        </div>
      </div>

      <div className="lg:col-span-2 space-y-6">
        {selectedStudent ? (
          <>
            <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
              <div className="flex items-center justify-between mb-6">
                <div className="flex items-center gap-4">
                  <div className="w-16 h-16 bg-blue-100 rounded-2xl flex items-center justify-center text-blue-600"><Award size={32} /></div>
                  <div>
                    <h3 className="text-2xl font-black text-black">{selectedStudent.name}</h3>
                    <p className="text-slate-600 font-bold">{selectedStudent.level} {selectedStudent.department}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-xs font-black uppercase">คะแนนปัจจุบัน</p>
                  <p className="text-5xl font-black text-blue-600">{selectedStudent.behaviorScore}</p>
                </div>
              </div>
              <div className="p-5 bg-slate-50 rounded-2xl border space-y-4">
                <h4 className="font-black text-black flex items-center gap-2"><PlusCircle size={20} className="text-green-600" /> ปรับคะแนน</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <input type="text" placeholder="เหตุผล..." value={reason} onChange={(e) => setReason(e.target.value)} className="border rounded-xl px-4 py-2.5 font-bold text-black" />
                  <div className="flex gap-2">
                    <input type="number" value={scoreChange} onChange={(e) => setScoreChange(parseInt(e.target.value))} className="w-20 border rounded-xl px-4 py-2.5 font-black text-black" />
                    <button onClick={() => handleScoreUpdate('ADD')} className="flex-1 bg-green-600 text-white font-black rounded-xl hover:bg-green-700">เพิ่ม</button>
                    <button onClick={() => handleScoreUpdate('DEDUCT')} className="flex-1 bg-red-600 text-white font-black rounded-xl hover:bg-red-700">หัก</button>
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
              <h3 className="font-black text-black flex items-center gap-2 text-xl mb-6"><FileText size={22} className="text-blue-600" /> ประวัติการปรับคะแนน</h3>
              <div className="space-y-4">
                {behaviorRecords.filter(b => b.studentId === selectedStudent.id).map(record => (
                  <div key={record.id} className="flex items-center justify-between p-5 border rounded-2xl bg-white group">
                    <div className="flex gap-4 items-center">
                      <div className={`p-2 rounded-xl ${record.type === 'ADD' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                        {record.type === 'ADD' ? <PlusCircle size={20} /> : <MinusCircle size={20} />}
                      </div>
                      <div>
                        <p className="font-black text-black">{record.reason}</p>
                        <p className="text-xs text-slate-500">{record.date} • {record.recordedBy}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-5">
                      <div className={`font-black text-xl ${record.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                        {record.type === 'ADD' ? '+' : '-'}{record.score}
                      </div>
                      <button 
                        onClick={() => handleDeleteBehavior(record.id)}
                        className="p-3 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all opacity-0 group-hover:opacity-100"
                        title="ลบบันทึกพฤติกรรม"
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </>
        ) : (
          <div className="h-full bg-white rounded-2xl border border-slate-200 flex flex-col items-center justify-center p-20 text-slate-300">
            <AlertCircle size={96} className="mb-6 opacity-5" />
            <p className="text-2xl font-black text-black">กรุณาเลือกรายชื่อนักเรียน</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default BehaviorSystem;

import React, { useState, useEffect, useMemo } from 'react';
import { Student, AttendanceRecord, BehaviorRecord, ThaiLevel, Department, StudyBlock } from '../types';
import { 
  FileText, 
  Search, 
  Download, 
  User, 
  Calendar, 
  Award, 
  TrendingUp,
  BarChart3,
  ShieldAlert,
  Users,
  Grid3X3,
  ChevronLeft,
  ChevronRight,
  Filter,
  Star,
  Layers,
  CalendarDays
} from 'lucide-react';
import { STATUS_LABELS } from '../constants';

interface ReportsProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: BehaviorRecord[];
  user: any;
  studyBlocks: StudyBlock[];
}

const Reports: React.FC<ReportsProps> = ({ students, attendance, behavior, user, studyBlocks }) => {
  const [activeTab, setActiveTab] = useState<'individual' | 'room'>('individual');

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

  const [reportLevel, setReportLevel] = useState<string>(Object.values(ThaiLevel)[0]);
  const [reportDept, setReportDept] = useState<string>(Object.values(Department)[0]);
  const [reportRoom, setReportRoom] = useState<string>('1');

  const [reportViewMode, setReportViewMode] = useState<'monthly' | 'block'>('block');
  const [selectedBlockId, setSelectedBlockId] = useState<number | 'ALL'>(
    studyBlocks.find(b => b.isActive)?.id || 'ALL'
  );

  const [reportMonth, setReportMonth] = useState<number>(new Date().getMonth());
  const [reportYear, setReportYear] = useState<number>(new Date().getFullYear());

  useEffect(() => {
    if (user.role === 'PARENT') {
      const child = students.find(s => s.studentId === user.studentId);
      if (child) setSelectedStudent(child);
      setActiveTab('individual');
    }
  }, [user, students]);

  const filteredStudentsForSidebar = students.filter(s => 
    s.name.includes(searchTerm) || s.studentId.includes(searchTerm)
  );

  const roomStudents = students.filter(s => 
    s.level === reportLevel && s.department === reportDept && s.room === reportRoom
  );

  const getDaysInMonth = (month: number, year: number) => {
    return new Date(year, month + 1, 0).getDate();
  };

  // Helper to generate dates between two strings
  const getDatesInRange = (startDate: string, endDate: string) => {
    const dates = [];
    let curr = new Date(startDate);
    const last = new Date(endDate);
    while (curr <= last) {
      dates.push(new Date(curr).toISOString().split('T')[0]);
      curr.setDate(curr.getDate() + 1);
    }
    return dates;
  };

  const reportDates = useMemo(() => {
    if (reportViewMode === 'block' && selectedBlockId !== 'ALL') {
      const block = studyBlocks.find(b => b.id === selectedBlockId);
      if (block?.startDate && block?.endDate) {
        return getDatesInRange(block.startDate, block.endDate);
      }
    }

    // Monthly view fallback
    const days = getDaysInMonth(reportMonth, reportYear);
    return Array.from({ length: days }).map((_, i) => 
      `${reportYear}-${String(reportMonth + 1).padStart(2, '0')}-${String(i + 1).padStart(2, '0')}`
    );
  }, [reportViewMode, selectedBlockId, reportMonth, reportYear, studyBlocks]);

  const getStatusInitial = (status: string) => {
    switch(status) {
      case 'PRESENT': return 'ม';
      case 'LATE': return 'ส';
      case 'ABSENT': return 'ข';
      case 'BUSINESS_LEAVE': return 'ก';
      case 'SICK_LEAVE': return 'ป';
      default: return '-';
    }
  };

  const getStatusColorClass = (status: string) => {
    switch(status) {
      case 'PRESENT': return 'text-green-600 bg-green-50';
      case 'LATE': return 'text-amber-600 bg-amber-50';
      case 'ABSENT': return 'text-red-600 bg-red-50';
      case 'BUSINESS_LEAVE': return 'text-blue-600 bg-blue-50';
      case 'SICK_LEAVE': return 'text-purple-600 bg-purple-50';
      default: return 'text-slate-300';
    }
  };

  const calculateStudentMorningScore = (studentId: string, specificBlockId?: number | 'ALL') => {
    let targetBlocks = studyBlocks.filter(b => b.isActive && b.startDate && b.endDate);

    if (specificBlockId && specificBlockId !== 'ALL') {
      targetBlocks = studyBlocks.filter(b => b.id === specificBlockId);
    }

    if (targetBlocks.length === 0) return 0;

    const presentInBlocks = attendance.filter(a => 
      a.studentId === studentId && 
      a.type === 'MORNING' && 
      a.status === 'PRESENT' &&
      targetBlocks.some(block => a.date >= block.startDate && a.date <= block.endDate)
    ).length;

    const holidayDays = targetBlocks.reduce((acc, block) => acc + (block.holidays?.length || 0), 0);
    const totalPresentCredits = presentInBlocks + holidayDays;

    return Math.min(5, (totalPresentCredits * 5) / 18);
  };

  const months = [
    "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
    "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
  ];

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      {user.role !== 'PARENT' && (
        <div className="flex bg-white p-2 rounded-[24px] border border-slate-200 shadow-sm w-fit mx-auto md:mx-0">
          <button 
            onClick={() => setActiveTab('individual')} 
            className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${activeTab === 'individual' ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <User size={18} /> รายบุคคล
          </button>
          <button 
            onClick={() => setActiveTab('room')} 
            className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${activeTab === 'room' ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <Users size={18} /> รายห้อง
          </button>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {activeTab === 'individual' ? (
          <>
            {user.role !== 'PARENT' && (
              <div className="lg:col-span-1 space-y-6">
                <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm h-[calc(100vh-220px)] flex flex-col">
                  <h3 className="font-black text-slate-900 uppercase tracking-[0.2em] text-xs mb-6 px-1">รายชื่อนักเรียน</h3>
                  <div className="relative mb-6">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input 
                      type="text" 
                      placeholder="รหัส หรือ ชื่อ..." 
                      value={searchTerm} 
                      onChange={(e) => setSearchTerm(e.target.value)} 
                      className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl pl-11 pr-4 py-3.5 font-bold text-slate-900 text-sm outline-none transition-all" 
                    />
                  </div>
                  <div className="flex-1 overflow-y-auto space-y-2 pr-2 scrollbar-hide">
                    {filteredStudentsForSidebar.map(s => (
                      <button 
                        key={s.id} 
                        onClick={() => setSelectedStudent(s)} 
                        className={`w-full text-left p-4 rounded-2xl border-2 transition-all ${selectedStudent?.id === s.id ? 'bg-slate-900 border-slate-900 text-white shadow-xl' : 'bg-white border-transparent hover:bg-slate-50 text-slate-900'}`}
                      >
                        <p className="font-black text-sm truncate">{s.name}</p>
                        <p className={`text-[10px] font-extrabold uppercase mt-1 tracking-widest ${selectedStudent?.id === s.id ? 'text-slate-400' : 'text-slate-500'}`}>{s.studentId}</p>
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}

            <div className={`${user.role === 'PARENT' ? 'lg:col-span-4' : 'lg:col-span-3'} space-y-8`}>
              {selectedStudent ? (
                <div className="animate-in slide-in-from-right-4 duration-500">
                  <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6 mb-8">
                    <div className="flex items-center gap-6">
                      <div className="w-20 h-20 bg-slate-900 rounded-[28px] flex items-center justify-center text-white shadow-xl"><User size={40} /></div>
                      <div>
                        <h2 className="text-3xl font-black text-slate-900 leading-tight">{selectedStudent.name}</h2>
                        <p className="text-slate-500 font-extrabold uppercase text-xs tracking-[0.2em] mt-2">{selectedStudent.level} • {selectedStudent.department} (ห้อง {selectedStudent.room})</p>
                      </div>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                    <div className="bg-white p-8 rounded-[32px] border shadow-sm flex items-center gap-5">
                      <div className="p-5 bg-blue-50 text-blue-600 rounded-2xl"><BarChart3 size={28} /></div>
                      <div>
                        <p className="text-[11px] font-black text-slate-500 uppercase tracking-widest">การมาเรียน</p>
                        <p className="text-4xl font-black text-slate-900">
