                <select value={reportRoom} onChange={(e) => setReportRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none transition-all appearance-none">
