                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {filteredStudents.map((student, idx) => (
                  <tr key={student.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 lg:px-10 py-5 text-sm font-black text-slate-900 align-top">{idx + 1}</td>
                    <td className="px-6 lg:px-10 py-5 align-top">
                      <p className="font-black text-slate-900 text-base leading-tight">{student.name}</p>
                      <p className="text-[10px] text-slate-500 font-extrabold uppercase mt-1 tracking-widest">รหัส: {student.studentId}</p>
