                              className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all border-2 flex items-center gap-1.5 ${sessionAttendance[student.id] === status ? STATUS_LABELS[status].color + ' border-current shadow-md' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}
                            >
                              {STATUS_LABELS[status].icon}
                              {STATUS_LABELS[status].label}
                            </button>
                          ))}
                        </div>
                        {sessionAttendance[student.id] && sessionAttendance[student.id] !== 'PRESENT' && (
                          <div className="relative animate-in slide-in-from-top-2 max-w-md">
                            <MessageSquare className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                            <input type="text" value={remarks[student.id] || ''} onChange={(e) => handleRemarkChange(student.id, e.target.value)} placeholder="ระบุหมายเหตุเพิ่มเติม..." className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-400 rounded-xl pl-9 pr-3 py-2 text-xs font-bold text-slate-900 outline-none" />
                          </div>
                        )}
                      </div>
                    </td>
                    <td className="px-6 lg:px-10 py-5 align-top text-center">
                      <span className="text-[10px] font-black text-slate-900">95%</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-[24px] md:rounded-[32px] border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-300">
          <div className="p-5 md:p-7 bg-slate-50/50 border-b flex items-center justify-between">
            <h3 className="font-black text-slate-900 text-lg md:text-2xl flex items-center gap-3 md:gap-4"><Calendar size={22} className="text-blue-600" /> สมุดบันทึกรายวิชา</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left min-w-[600px]">
              <thead>
                <tr className="bg-white border-b border-slate-100">
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">วันที่</th>
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">นักเรียน</th>
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">สถานะ</th>
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">หมายเหตุ</th>
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-center">จัดการ</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {historyRecords.map((record) => {
                  const student = allStudents.find(s => s.id === record.studentId);
                  return (
                    <tr key={record.id} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-6 md:px-10 py-5 font-black text-slate-900">{record.date}</td>
                      <td className="px-6 md:px-10 py-5">
                        <p className="font-black text-slate-900">{student?.name}</p>
                        <p className="text-[10px] text-slate-500">{student?.studentId}</p>
                      </td>
                      <td className="px-6 md:px-10 py-5"><span className={`px-4 py-1.5 rounded-lg text-[10px] font-black border-2 ${STATUS_LABELS[record.status].color}`}>{STATUS_LABELS[record.status].label}</span></td>
                      <td className="px-6 md:px-10 py-5 text-xs font-bold">{record.remark || '-'}</td>
                      <td className="px-6 md:px-10 py-5 text-center">
                         <div className="flex items-center justify-center gap-2">
                           <button 
                             onClick={() => handleDeleteRecord(record.id)} 
                             className="p-4 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all" 
                             title="ลบประวัติการเช็คชื่อ"
                           >
                             <Trash2 size={22} />
                           </button>
                         </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-[32px] p-8 shadow-2xl animate-in zoom-in-95">
