            <form onSubmit={showAddModal === 'STUDENT' ? handleAddStudent : showAddModal === 'SUBJECT' ? handleAddSubject : handleAddRoom} className="space-y-4">
              <input type="text" required value={showAddModal === 'STUDENT' ? newStudent.name : showAddModal === 'SUBJECT' ? newSubject.name : newRoomValue} onChange={(e) => showAddModal === 'STUDENT' ? setNewStudent({...newStudent, name: e.target.value}) : showAddModal === 'SUBJECT' ? setNewSubject({...newSubject, name: e.target.value}) : setNewRoomValue(e.target.value)} className="w-full bg-slate-50 border-2 rounded-2xl px-6 py-4 font-black" placeholder="ชื่อ..." />
              <div className="flex gap-4"><button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-4 bg-slate-100 rounded-2xl">ยกเลิก</button><button type="submit" className="flex-1 py-4 bg-blue-600 text-white rounded-2xl shadow-lg">บันทึก</button></div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

