                   <div className="bg-white/5 p-4 rounded-2xl border border-white/10">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ปวส.</p>
                      <p className="text-2xl font-black text-white">{students.filter(s => s.level.includes('ปวส')).length}</p>
                   </div>
                </div>
              </div>
           </div>
           <div className="mt-8 relative z-10">
              <div className="flex items-center gap-2 text-green-400">
                <CheckCircle2 size={16} />
                <span className="text-[10px] font-black uppercase tracking-widest">Database Synced</span>
              </div>
           </div>
        </div>
      </div>

      <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-8 bg-slate-50/50 flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <h2 className="font-black text-slate-900 text-2xl tracking-tight leading-none">รายชื่อนักเรียนในระบบ</h2>
            <span className="bg-white px-3 py-1 rounded-full border border-slate-200 text-[10px] font-black text-slate-500">{filteredStudents.length} รายการ</span>
          </div>
          <div className="relative w-full md:w-96">
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input 
              type="text" 
              placeholder="ค้นหาด้วยชื่อ หรือ รหัสประจำตัว..." 
              value={searchTerm} 
              onChange={(e) => setSearchTerm(e.target.value)} 
              className="w-full bg-white border-2 border-slate-100 rounded-[20px] pl-14 pr-6 py-4 font-bold text-slate-900 outline-none focus:border-blue-500 transition-all shadow-inner" 
            />
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white border-b border-slate-100">
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ข้อมูลนักเรียน</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ระดับชั้น และ แผนก</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ห้อง</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] text-center">จัดการ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredStudents.length > 0 ? filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-5">
                       <div className="w-12 h-12 bg-slate-100 rounded-[18px] flex items-center justify-center text-slate-400 font-black group-hover:bg-blue-600 group-hover:text-white transition-all">
                         {student.name.charAt(0)}
                       </div>
                       <div>
                         <p className="font-black text-slate-900 text-lg leading-tight">{student.name}</p>
                         <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">รหัส: {student.studentId}</p>
                       </div>
                    </div>
                  </td>
                  <td className="px-10 py-6">
                    <div className="flex flex-col gap-1.5">
                       <span className="w-fit px-3 py-1 bg-slate-100 rounded-lg text-[10px] font-black text-slate-600 uppercase">{student.level}</span>
                       <span className="text-xs font-bold text-slate-500">{student.department}</span>
                    </div>
                  </td>
                  <td className="px-10 py-6 text-sm font-black text-slate-900">ห้อง {student.room}</td>
                  <td className="px-10 py-6 text-center">
                    <div className="flex items-center justify-center gap-2">
                       <button 
                         onClick={() => deleteStudent(student)} 
                         className="p-4 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all"
                         title="ลบรายชื่อนักเรียน"
                       >
                         <Trash2 size={22} />
                       </button>
                    </div>
                  </td>
                </tr>
              )) : (
                <tr>
                  <td colSpan={4} className="py-32 text-center text-slate-300">
                    <UserX size={64} className="mx-auto mb-6 opacity-5" />
                    <p className="text-2xl font-black text-slate-900">ไม่พบรายชื่อนักเรียนที่ค้นหา</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default StudentManagement;

import React, { useState, useRef } from 'react';
import { User, UserRole, Department } from '../types';
import { 
  UserPlus, 
  Shield, 
  Trash2, 
  Edit3, 
  X, 
  Search, 
  Link2, 
  FileSpreadsheet, 
  Upload, 
  Download,
  CheckCircle2,
  AlertCircle,
  Key,
  UserX
} from 'lucide-react';

interface UserManagementProps {
  users: User[];
  setUsers: React.Dispatch<React.SetStateAction<User[]>>;
  currentUser?: User;
}

const UserManagement: React.FC<UserManagementProps> = ({ users, setUsers, currentUser }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState<'ADD' | 'EDIT' | null>(null);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [importStatus, setImportStatus] = useState<{ type: 'success' | 'error'; message: string } | null>(null);

  const teacherFileInputRef = useRef<HTMLInputElement>(null);
  const parentFileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<User>>({
    name: '',
    role: 'TEACHER' as UserRole,
    department: Object.values(Department)[0],
    studentId: '',
    username: '',
    password: ''
  });

  const filteredUsers = users.filter(u => 
    u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    u.role.toLowerCase().includes(searchTerm.toLowerCase()) ||
    u.username.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const resetForm = () => {
    setFormData({
      name: '',
      role: 'TEACHER',
      department: Object.values(Department)[0],
      studentId: '',
      username: '',
      password: ''
    });
    setEditingUserId(null);
  };

  const handleOpenEdit = (user: User) => {
    setFormData({ ...user });
    setEditingUserId(user.id);
    setShowModal('EDIT');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (showModal === 'ADD') {
      const user = {
        id: `USR_${Date.now()}`,
        ...formData
      } as User;
      setUsers(prev => [...prev, user]);
    } else if (showModal === 'EDIT' && editingUserId) {
      setUsers(prev => prev.map(u => u.id === editingUserId ? { ...u, ...formData } as User : u));
    }
    setShowModal(null);
    resetForm();
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, targetRole: UserRole) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const lines = text.split('\n');
        const newUsers: User[] = [];

        for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;

          const columns = line.split(',');
          if (targetRole === 'TEACHER') {
            const [name, department, username, password] = columns;
            if (name) {
              newUsers.push({
                id: `USR_T_${Date.now()}_${i}`,
                name: name.trim(),
                department: department?.trim() || 'เทคโนโลยีสารสนเทศ',
                role: 'TEACHER',
                username: username?.trim() || `t_${Date.now()}_${i}`,
                password: password?.trim() || '1234'
              });
            }
          } else if (targetRole === 'PARENT') {
            const [name, studentId, username, password] = columns;
            if (name && studentId) {
              newUsers.push({
                id: `USR_P_${Date.now()}_${i}`,
                name: name.trim(),
                studentId: studentId.trim(),
                role: 'PARENT',
                username: username?.trim() || studentId.trim(),
                password: password?.trim() || '1234'
              });
            }
          }
        }

        if (newUsers.length > 0) {
          setUsers(prev => [...prev, ...newUsers]);
          setImportStatus({ type: 'success', message: `นำเข้าข้อมูล ${newUsers.length} รายการสำเร็จ` });
        } else {
          setImportStatus({ type: 'error', message: 'ไม่พบข้อมูลที่ถูกต้องในไฟล์' });
        }
      } catch (err) {
        setImportStatus({ type: 'error', message: 'เกิดข้อผิดพลาดในการอ่านไฟล์' });
      } finally {
        if (e.target) e.target.value = '';
        setTimeout(() => setImportStatus(null), 4000);
      }
    };
    reader.readAsText(file);
  };

  const downloadTemplate = (role: UserRole) => {
    let headers = "";
    let example = "";
    if (role === 'TEACHER') {
      headers = "name,department,username,password\n";
      example = "อ.สมหมาย สายเสมอ,เทคโนโลยีสารสนเทศ,sommai,1234";
    } else {
      headers = "name,studentId,username,password\n";
      example = "คุณแม่ มณี,661001,manee661001,1234";
    }
    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" + headers + example;
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `template_${role.toLowerCase()}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const deleteUser = (user: User) => {
    // Prevent deleting self
    if (currentUser && user.id === currentUser.id) {
      alert('คุณไม่สามารถลบบัญชีที่กำลังใช้งานอยู่ได้');
      return;
    }

    const confirmMsg = `ยืนยันการลบผู้ใช้ออกจากระบบ?\n\nชื่อ: ${user.name}\nสิทธิ์: ${user.role}\nUsername: ${user.username}`;

    if (window.confirm(confirmMsg)) {
      setUsers(prev => prev.filter(u => u.id !== user.id));
    }
  };

  const getRoleBadge = (role: UserRole) => {
    switch (role) {
      case 'ADMIN': return 'bg-indigo-100 text-indigo-700 border-indigo-200';
      case 'TEACHER': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'PARENT': return 'bg-pink-100 text-pink-700 border-pink-200';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex items-center gap-4 mb-6">
            <div className="p-4 bg-blue-600 rounded-[24px] text-white shadow-lg shadow-blue-100"><FileSpreadsheet size={24} /></div>
            <div>
              <h3 className="font-black text-slate-900 text-xl tracking-tight">นำเข้าอาจารย์</h3>
              <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-0.5">Bulk Teacher Import</p>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <button onClick={() => teacherFileInputRef.current?.click()} className="flex items-center justify-center gap-3 py-4 bg-slate-50 text-slate-900 rounded-2xl font-black border-2 border-dashed border-slate-200 hover:border-blue-500 hover:bg-blue-50 transition-all text-sm">
              <Upload size={18} /> อัปโหลด CSV
              <input type="file" ref={teacherFileInputRef} className="hidden" accept=".csv" onChange={(e) => handleFileUpload(e, 'TEACHER')} />
            </button>
            <button onClick={() => downloadTemplate('TEACHER')} className="flex items-center justify-center gap-3 py-4 bg-slate-900 text-white rounded-2xl font-black hover:bg-black transition-all text-sm shadow-xl shadow-slate-200">
              <Download size={18} /> เทมเพลต
            </button>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex items-center gap-4 mb-6">
            <div className="p-4 bg-pink-600 rounded-[24px] text-white shadow-lg shadow-pink-100"><UserPlus size={24} /></div>
            <div>
              <h3 className="font-black text-slate-900 text-xl tracking-tight">นำเข้าผู้ปกครอง</h3>
              <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-0.5">Bulk Parent Import</p>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <button onClick={() => parentFileInputRef.current?.click()} className="flex items-center justify-center gap-3 py-4 bg-slate-50 text-slate-900 rounded-2xl font-black border-2 border-dashed border-slate-200 hover:border-pink-500 hover:bg-pink-50 transition-all text-sm">
              <Upload size={18} /> อัปโหลด CSV
              <input type="file" ref={parentFileInputRef} className="hidden" accept=".csv" onChange={(e) => handleFileUpload(e, 'PARENT')} />
            </button>
            <button onClick={() => downloadTemplate('PARENT')} className="flex items-center justify-center gap-3 py-4 bg-slate-900 text-white rounded-2xl font-black hover:bg-black transition-all text-sm shadow-xl shadow-slate-200">
              <Download size={18} /> เทมเพลต
            </button>
          </div>
        </div>
      </div>

      {importStatus && (
        <div className={`p-4 rounded-[24px] flex items-center gap-3 border animate-in slide-in-from-top-4 ${importStatus.type === 'success' ? 'bg-green-50 border-green-200 text-green-800' : 'bg-red-50 border-red-200 text-red-800'}`}>
          {importStatus.type === 'success' ? <CheckCircle2 size={24} /> : <AlertCircle size={24} />}
          <p className="font-black text-sm">{importStatus.message}</p>
        </div>
      )}

      <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden mt-8">
        <div className="p-6 md:p-10 bg-slate-50/50 border-b flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <Shield size={28} className="text-indigo-600" />
            <div>
              <h2 className="font-black text-slate-900 text-2xl tracking-tight">จัดการข้อมูลผู้ใช้ ({users.length})</h2>
              <p className="text-sm font-bold text-slate-500">ควบคุมสิทธิ์และข้อมูลการเข้าสู่ระบบ</p>
            </div>
          </div>
          <div className="flex items-center gap-4 w-full md:w-auto">
            <div className="relative flex-1 md:w-80">
              <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
              <input type="text" placeholder="ค้นหาชื่อ หรือ Username..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white border-2 border-slate-100 rounded-[20px] pl-14 pr-6 py-4 text-sm font-bold text-slate-900 outline-none focus:border-indigo-500 transition-all shadow-inner" />
            </div>
            <button onClick={() => { resetForm(); setShowModal('ADD'); }} className="px-8 py-4 bg-indigo-600 text-white rounded-[20px] text-sm font-black flex items-center gap-3 shadow-xl shadow-indigo-100 hover:bg-indigo-700 transition-all active:scale-95 uppercase tracking-widest text-xs">
              <UserPlus size={20} /> เพิ่มรายคน
            </button>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white border-b border-slate-100">
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ข้อมูลเบื้องต้น</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ชื่อผู้ใช้ (Username)</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">รหัสผ่าน (Password)</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">สิทธิ์ / สังกัด</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">จัดการ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredUsers.length > 0 ? filteredUsers.map((u) => (
                <tr key={u.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-10 py-7">
                    <div className="flex items-center gap-5">
                      <div className={`w-14 h-14 rounded-[20px] flex items-center justify-center font-black text-xl text-white shadow-sm ${u.role === 'ADMIN' ? 'bg-indigo-600' : u.role === 'PARENT' ? 'bg-pink-600' : 'bg-slate-800'}`}>
                        {u.name.charAt(0)}
                      </div>
                      <div>
                        <p className="font-black text-slate-900 text-lg leading-tight">{u.name}</p>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">ID: {u.id.substring(0,8)}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-10 py-7">
                    <div className="flex items-center gap-2 text-slate-900 font-black">
                      <Key size={14} className="text-blue-500" />
                      <span>{u.username}</span>
                    </div>
                  </td>
                  <td className="px-10 py-7">
                    <span className="text-xs font-bold font-mono bg-slate-100 px-3 py-1 rounded-lg text-slate-600 select-all cursor-copy">
                      {u.password}
                    </span>
                  </td>
                  <td className="px-10 py-7">
                    <div className="flex flex-col gap-2">
                      <span className={`w-fit px-4 py-1 rounded-lg text-[9px] font-black border-2 uppercase tracking-widest ${getRoleBadge(u.role)}`}>{u.role}</span>
                      <span className="text-xs font-bold text-slate-500">{u.role === 'PARENT' ? `ลูก: ${u.studentId}` : u.department}</span>
                    </div>
                  </td>
                  <td className="px-10 py-7 text-right">
                    <div className="flex items-center justify-end gap-3">
                      <button onClick={() => handleOpenEdit(u)} className="p-3 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-2xl transition-all"><Edit3 size={20} /></button>
                      <button 
                        onClick={() => deleteUser(u)} 
                        className={`p-3 rounded-2xl transition-all ${currentUser?.id === u.id ? 'text-slate-200 cursor-not-allowed' : 'text-slate-400 hover:text-red-600 hover:bg-red-50'}`}
                        disabled={currentUser?.id === u.id}
                        title={currentUser?.id === u.id ? "ไม่สามารถลบตัวเองได้" : "ลบผู้ใช้"}
                      >
                        <Trash2 size={20} />
                      </button>
                    </div>
                  </td>
                </tr>
              )) : (
                <tr>
                  <td colSpan={5} className="py-32 text-center text-slate-300">
                    <UserX size={64} className="mx-auto mb-6 opacity-5" />
                    <p className="text-2xl font-black text-slate-900">ไม่พบข้อมูลผู้ใช้ที่ค้นหา</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md overflow-y-auto">
          <div className="bg-white w-full max-w-lg rounded-[48px] p-10 md:p-14 shadow-2xl animate-in zoom-in-95 relative my-8">
            <button onClick={() => setShowModal(null)} className="absolute top-10 right-10 text-slate-400 hover:text-slate-900 transition-colors"><X size={28} /></button>
            <h3 className="text-3xl font-black text-slate-900 mb-10 text-center uppercase tracking-tight">
              {showModal === 'ADD' ? 'ลงทะเบียนใหม่' : 'แก้ไขข้อมูล'}
            </h3>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ-นามสกุล</label>
                  <input type="text" required value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} className="w-full bg-slate-50 border-2 border-slate-100 focus:border-indigo-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none transition-all" placeholder="ชื่อ นามสกุล" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">สิทธิ์การใช้งาน</label>
                  <select value={formData.role} onChange={(e) => setFormData({...formData, role: e.target.value as UserRole})} className="w-full bg-slate-50 border-2 border-slate-100 focus:border-indigo-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none cursor-pointer">
                    <option value="TEACHER">TEACHER (อาจารย์)</option>
                    <option value="ADMIN">ADMIN (ผู้ดูแลระบบ)</option>
                    <option value="PARENT">PARENT (ผู้ปกครอง)</option>
                  </select>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-indigo-600 uppercase tracking-widest ml-1">Username</label>
                  <input type="text" required value={formData.username} onChange={(e) => setFormData({...formData, username: e.target.value})} className="w-full bg-indigo-50/50 border-2 border-indigo-100 focus:border-indigo-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none" placeholder="Username" />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-indigo-600 uppercase tracking-widest ml-1">Password</label>
                  <input type="text" required value={formData.password} onChange={(e) => setFormData({...formData, password: e.target.value})} className="w-full bg-indigo-50/50 border-2 border-indigo-100 focus:border-indigo-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none" placeholder="Password" />
                </div>
              </div>

              {formData.role === 'PARENT' ? (
                <div className="space-y-1.5 animate-in slide-in-from-top-2">
                  <label className="text-[10px] font-black text-pink-600 uppercase tracking-widest ml-1">รหัสประจำตัวนักเรียน (ลูก)</label>
                  <div className="relative">
                    <Link2 className="absolute left-5 top-1/2 -translate-y-1/2 text-pink-400" size={18} />
                    <input type="text" required value={formData.studentId} onChange={(e) => setFormData({...formData, studentId: e.target.value})} className="w-full bg-pink-50 border-2 border-pink-100 focus:pink-500 rounded-2xl pl-12 pr-5 py-4 font-black text-slate-900 outline-none" placeholder="เช่น 661001" />
                  </div>
                </div>
              ) : (
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา/สังกัด</label>
                  <select value={formData.department} onChange={(e) => setFormData({...formData, department: e.target.value})} className="w-full bg-slate-50 border-2 border-slate-100 focus:border-indigo-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none cursor-pointer">
                    {Object.values(Department).map(d => <option key={d} value={d}>{d}</option>)}
                  </select>
                </div>
              )}

              <div className="flex gap-6 pt-6">
                <button type="button" onClick={() => setShowModal(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-widest hover:bg-slate-200 transition-all">ยกเลิก</button>
                <button type="submit" className="flex-1 py-5 font-black text-white bg-indigo-600 rounded-[24px] shadow-2xl shadow-indigo-200 uppercase text-xs tracking-widest hover:bg-indigo-700 transition-all">บันทึกข้อมูล</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

