import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import MorningAttendance from './components/MorningAttendance';
import ClassAttendance from './components/ClassAttendance';
import BehaviorSystem from './components/BehaviorSystem';
import StudentManagement from './components/StudentManagement';
import Reports from './components/Reports';
import UserManagement from './components/UserManagement';
import SystemSettings from './components/SystemSettings';
import MorningScoreSummary from './components/MorningScoreSummary';
import Login from './components/Login';
import { MOCK_STUDENTS, MOCK_ATTENDANCE, MOCK_BEHAVIOR, MOCK_SUBJECTS } from './data/mockData';
import { Student, AttendanceRecord, BehaviorRecord, Subject, User, StudyBlock } from './types';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeMenu, setActiveMenu] = useState('dashboard');

  // Central States
  const [students, setStudents] = useState<Student[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [behaviorRecords, setBehaviorRecords] = useState<BehaviorRecord[]>([]);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);
  const [systemUsers, setSystemUsers] = useState<User[]>([]);
  const [studyBlocks, setStudyBlocks] = useState<StudyBlock[]>([
    { id: 1, name: 'บล็อกที่ 1', startDate: '2024-03-01', endDate: '2024-03-25', isActive: true, holidays: [] },
    { id: 2, name: 'บล็อกที่ 2', startDate: '', endDate: '', isActive: false, holidays: [] },
    { id: 3, name: 'บล็อกที่ 3', startDate: '', endDate: '', isActive: false, holidays: [] },
    { id: 4, name: 'บล็อกที่ 4', startDate: '', endDate: '', isActive: false, holidays: [] },
    { id: 5, name: 'บล็อกที่ 5', startDate: '', endDate: '', isActive: false, holidays: [] },
  ]);

  // Initialize data
  useEffect(() => {
    const savedStudents = localStorage.getItem('cms_students');
    const savedAttendance = localStorage.getItem('cms_attendance');
    const savedBehavior = localStorage.getItem('cms_behavior');
    const savedSubjects = localStorage.getItem('cms_subjects');
    const savedRooms = localStorage.getItem('cms_rooms');
    const savedUsers = localStorage.getItem('cms_system_users');
    const savedBlocks = localStorage.getItem('cms_study_blocks');

    if (savedStudents) setStudents(JSON.parse(savedStudents));
    else setStudents(MOCK_STUDENTS);

    if (savedAttendance) setAttendance(JSON.parse(savedAttendance));
    else setAttendance(MOCK_ATTENDANCE);

    if (savedBehavior) setBehaviorRecords(JSON.parse(savedBehavior));
    else setBehaviorRecords(MOCK_BEHAVIOR);

    if (savedSubjects) setSubjects(JSON.parse(savedSubjects));
    else setSubjects(MOCK_SUBJECTS);

    if (savedRooms) setRooms(JSON.parse(savedRooms));

    if (savedUsers) setSystemUsers(JSON.parse(savedUsers));
    else setSystemUsers([
      { id: 'T1', name: 'อ.สมพงษ์ ใจสว่าง', role: 'TEACHER', username: 'teacher', password: '1234', department: 'เทคโนโลยีสารสนเทศ' },
      { id: 'A1', name: 'แอดมิน ระบบ', role: 'ADMIN', username: 'admin', password: '1234', department: 'ส่วนกลาง' },
      { id: 'P1', name: 'คุณแม่ มณี', role: 'PARENT', username: 'parent', password: '1234', studentId: '661001' }
    ]);

    if (savedBlocks) setStudyBlocks(JSON.parse(savedBlocks));
  }, []);

  // Save to LocalStorage
  useEffect(() => {
    if (students.length > 0) localStorage.setItem('cms_students', JSON.stringify(students));
    localStorage.setItem('cms_attendance', JSON.stringify(attendance));
    localStorage.setItem('cms_behavior', JSON.stringify(behaviorRecords));
    localStorage.setItem('cms_subjects', JSON.stringify(subjects));
    localStorage.setItem('cms_rooms', JSON.stringify(rooms));
    localStorage.setItem('cms_system_users', JSON.stringify(systemUsers));
    localStorage.setItem('cms_study_blocks', JSON.stringify(studyBlocks));
  }, [students, attendance, behaviorRecords, subjects, rooms, systemUsers, studyBlocks]);

  if (!user) {
    return <Login onLogin={setUser} systemUsers={systemUsers} />;
  }

  const renderContent = () => {
    if ((activeMenu === 'users' || activeMenu === 'settings') && user.role !== 'ADMIN') {
      setActiveMenu('dashboard');
      return null;
    }

    switch (activeMenu) {
      case 'dashboard':
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
      case 'students':
        return <StudentManagement students={students} setStudents={setStudents} />;
      case 'morning':
        return (
          <MorningAttendance 
            students={students} 
            setStudents={setStudents}
            attendanceRecords={attendance}
            setAttendanceRecords={setAttendance}
            rooms={rooms}
            setRooms={setRooms}
          />
        );
      case 'subject':
        return (
          <ClassAttendance 
            students={students} 
            setStudents={setStudents}
            subjects={subjects}
            setSubjects={setSubjects}
            rooms={rooms}
            setRooms={setRooms}
            attendanceRecords={attendance}
            setAttendanceRecords={setAttendance}
            currentUser={user}
          />
        );
      case 'behavior':
        return (
          <BehaviorSystem 
            students={students} 
            setStudents={setStudents}
            behaviorRecords={behaviorRecords}
            setBehaviorRecords={setBehaviorRecords}
          />
        );
      case 'report':
        return <Reports students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
      case 'morning_scores':
        return <MorningScoreSummary students={students} attendance={attendance} studyBlocks={studyBlocks} />;
      case 'users':
        return <UserManagement users={systemUsers} setUsers={setSystemUsers} currentUser={user} />;
      case 'settings':
        return <SystemSettings studyBlocks={studyBlocks} setStudyBlocks={setStudyBlocks} />;
      default:
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
    }
  };

  return (
    <Layout 
      activeMenu={activeMenu} 
      setActiveMenu={setActiveMenu} 
      user={user}
      onLogout={() => setUser(null)}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Student } from '../types';
import { 
  FileSpreadsheet, 
  Download, 
  Upload, 
  CheckCircle2, 
  AlertCircle, 
  Search, 
  Trash2, 
  UserPlus,
  Info,
  UserX,
  // Fix: Added missing 'Users' icon import
  Users
} from 'lucide-react';

interface StudentManagementProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
}

const StudentManagement: React.FC<StudentManagementProps> = ({ students, setStudents }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const [importStatus, setImportStatus] = useState<null | 'success' | 'error'>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const filteredStudents = students.filter(s => 
    s.name.includes(searchTerm) || s.studentId.includes(searchTerm)
  );

  const downloadTemplate = () => {
    const headers = "studentId,name,level,department,room\n";
    const example = "661007,นายมานะ อดทน,ปวช. 1,เทคโนโลยีสารสนเทศ,1\n661008,นางสาวชูใจ ใจดี,ปวช. 1,เทคโนโลยีสารสนเทศ,1";
    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" + headers + example;
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "student_template.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const lines = text.split('\n');
        const newStudents: Student[] = [];

        for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;
          const [studentId, name, level, department, room] = line.split(',');

          if (studentId && name) {
            newStudents.push({
              id: `ID_${Date.now()}_${i}`,
              studentId,
              name,
              level: level || 'ปวช. 1',
              department: department || 'เทคโนโลยีสารสนเทศ',
              room: room || '1',
              behaviorScore: 100
            });
          }
        }

        if (newStudents.length > 0) {
          setStudents(prev => [...newStudents, ...prev]);
          setImportStatus('success');
        } else setImportStatus('error');
      } catch (err) { setImportStatus('error'); }
      finally { setIsImporting(false); if (fileInputRef.current) fileInputRef.current.value = ''; }
    };
    reader.readAsText(file);
  };

  const deleteStudent = (student: Student) => {
    const confirmMsg = `ยืนยันการลบรายชื่อนักเรียน?\n\nชื่อ: ${student.name}\nรหัส: ${student.studentId}\n\n*ประวัติการเช็คชื่อและคะแนนจะถูกลบออกด้วย*`;

    if (window.confirm(confirmMsg)) {
      setStudents(prev => prev.filter(s => s.id !== student.id));
    }
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex items-center gap-4 mb-8">
            <div className="p-4 bg-blue-600 rounded-[24px] text-white shadow-xl shadow-blue-100"><FileSpreadsheet size={28} /></div>
            <div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight">นำเข้าข้อมูลนักเรียน</h3>
              <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">อัปโหลดผ่านไฟล์ CSV มาตรฐาน</p>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div onClick={() => fileInputRef.current?.click()} className="p-8 bg-slate-50 rounded-[32px] border-4 border-dashed border-slate-100 flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50 transition-all group">
              <input type="file" ref={fileInputRef} className="hidden" accept=".csv" onChange={handleFileUpload} />
              <div className="p-5 bg-white rounded-2xl shadow-sm mb-4 group-hover:scale-110 transition-transform">
                <Upload size={32} className="text-blue-600" />
              </div>
              <p className="font-black text-slate-900">คลิกเพื่ออัปโหลดไฟล์ CSV</p>
              <p className="text-[10px] text-slate-400 font-bold uppercase mt-2">Maximum file size: 5MB</p>
            </div>
            <div className="flex flex-col justify-center gap-4">
              <button onClick={downloadTemplate} className="flex items-center justify-center gap-3 py-5 bg-slate-900 text-white rounded-[24px] font-black hover:bg-black transition-all shadow-xl shadow-slate-200">
                <Download size={20} /> ดาวน์โหลดเทมเพลต
              </button>
              <div className="p-5 bg-blue-50 rounded-[24px] border border-blue-100">
                <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1 flex items-center gap-2">
                  <Info size={12} /> คำแนะนำ
                </p>
                <p className="text-[11px] text-blue-800 font-bold leading-relaxed">กรุณาเรียงลำดับคอลัมน์ในไฟล์ CSV ให้ถูกต้องตามตัวอย่างเทมเพลตเพื่อให้ระบบนำเข้าข้อมูลได้อย่างแม่นยำ</p>
              </div>
            </div>
          </div>
          {importStatus && (
            <div className={`mt-8 p-5 rounded-[24px] flex items-center gap-4 border-2 animate-in slide-in-from-top-4 ${importStatus === 'success' ? 'bg-green-50 border-green-100 text-green-700' : 'bg-red-50 border-red-100 text-red-700'}`}>
              <CheckCircle2 size={24} />
              <p className="font-black text-sm">{importStatus === 'success' ? 'นำเข้าข้อมูลนักเรียนสำเร็จ!' : 'เกิดข้อผิดพลาดในการอ่านไฟล์ กรุณาตรวจสอบรูปแบบข้อมูล'}</p>
            </div>
          )}
        </div>

        <div className="bg-slate-900 p-10 rounded-[40px] shadow-2xl relative overflow-hidden flex flex-col justify-between">
           <div className="absolute top-0 right-0 p-12 opacity-10 pointer-events-none text-white">
              <Users size={180} />
           </div>
           <div className="relative z-10">
              <h4 className="text-xs font-black text-blue-400 uppercase tracking-[0.3em] mb-6">สรุปข้อมูลทะเบียน</h4>
              <div className="space-y-8">
                <div>
                  <span className="text-slate-400 font-bold text-sm">จำนวนนักเรียนทั้งหมด</span>
                  <p className="text-6xl font-black text-white mt-1">{students.length}</p>
                </div>
                <div className="grid grid-cols-2 gap-4">
                   <div className="bg-white/5 p-4 rounded-2xl border border-white/10">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ปวช.</p>
                      <p className="text-2xl font-black text-white">{students.filter(s => s.level.includes('ปวช')).length}</p>
                   </div>
                   <div className="bg-white/5 p-4 rounded-2xl border border-white/10">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ปวส.</p>
                      <p className="text-2xl font-black text-white">{students.filter(s => s.level.includes('ปวส')).length}</p>
                   </div>
                </div>
              </div>
           </div>
           <div className="mt-8 relative z-10">
              <div className="flex items-center gap-2 text-green-400">
                <CheckCircle2 size={16} />
                <span className="text-[10px] font-black uppercase tracking-widest">Database Synced</span>
              </div>
           </div>
        </div>
      </div>

      <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-8 bg-slate-50/50 flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <h2 className="font-black text-slate-900 text-2xl tracking-tight leading-none">รายชื่อนักเรียนในระบบ</h2>
            <span className="bg-white px-3 py-1 rounded-full border border-slate-200 text-[10px] font-black text-slate-500">{filteredStudents.length} รายการ</span>
          </div>
          <div className="relative w-full md:w-96">
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
            <input 
              type="text" 
              placeholder="ค้นหาด้วยชื่อ หรือ รหัสประจำตัว..." 
              value={searchTerm} 
              onChange={(e) => setSearchTerm(e.target.value)} 
              className="w-full bg-white border-2 border-slate-100 rounded-[20px] pl-14 pr-6 py-4 font-bold text-slate-900 outline-none focus:border-blue-500 transition-all shadow-inner" 
            />
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white border-b border-slate-100">
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ข้อมูลนักเรียน</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ระดับชั้น และ แผนก</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ห้อง</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] text-center">จัดการ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredStudents.length > 0 ? filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-5">
                       <div className="w-12 h-12 bg-slate-100 rounded-[18px] flex items-center justify-center text-slate-400 font-black group-hover:bg-blue-600 group-hover:text-white transition-all">
                         {student.name.charAt(0)}
                       </div>
                       <div>
                         <p className="font-black text-slate-900 text-lg leading-tight">{student.name}</p>
                         <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">รหัส: {student.studentId}</p>
                       </div>
                    </div>
                  </td>
                  <td className="px-10 py-6">
                    <div className="flex flex-col gap-1.5">
                       <span className="w-fit px-3 py-1 bg-slate-100 rounded-lg text-[10px] font-black text-slate-600 uppercase">{student.level}</span>
