                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ระดับชั้น และ แผนก</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ห้อง</th>
