              {showModal === 'ADD' ? 'ลงทะเบียนนักเรียนใหม่' : 'แก้ไขข้อมูลนักเรียน'}
            </h3>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">รหัสประจำตัวนักเรียน</label>
