                  type="text" 
                  required 
                  value={formData.studentId} 
                  onChange={(e) => setFormData({...formData, studentId: e.target.value})} 
                  className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none transition-all" 
                  placeholder="เช่น 661001" 
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ-นามสกุล</label>
                <input 
                  type="text" 
                  required 
                  value={formData.name} 
                  onChange={(e) => setFormData({...formData, name: e.target.value})} 
                  className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none transition-all" 
                  placeholder="ชื่อ นามสกุล" 
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
