  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);
  const [systemUsers, setSystemUsers] = useState<User[]>([]);
  const [studyBlocks, setStudyBlocks] = useState<StudyBlock[]>([
    { id: 1, name: 'บล็อกที่ 1', startDate: '2024-03-01', endDate: '2024-03-25', isActive: true, holidays: [] },
    { id: 2, name: 'บล็อกที่ 2', startDate: '', endDate: '', isActive: false, holidays: [] },
    { id: 3, name: 'บล็อกที่ 3', startDate: '', endDate: '', isActive: false, holidays: [] },
    { id: 4, name: 'บล็อกที่ 4', startDate: '', endDate: '', isActive: false, holidays: [] },
    { id: 5, name: 'บล็อกที่ 5', startDate: '', endDate: '', isActive: false, holidays: [] },
  ]);

  // Initialize data
  useEffect(() => {
    const savedStudents = localStorage.getItem('cms_students');
    const savedAttendance = localStorage.getItem('cms_attendance');
    const savedBehavior = localStorage.getItem('cms_behavior');
    const savedSubjects = localStorage.getItem('cms_subjects');
    const savedRooms = localStorage.getItem('cms_rooms');
    const savedUsers = localStorage.getItem('cms_system_users');
    const savedBlocks = localStorage.getItem('cms_study_blocks');

    setStudents(savedStudents ? JSON.parse(savedStudents) : MOCK_STUDENTS);
    setAttendance(savedAttendance ? JSON.parse(savedAttendance) : MOCK_ATTENDANCE);
    setBehaviorRecords(savedBehavior ? JSON.parse(savedBehavior) : MOCK_BEHAVIOR);
    setSubjects(savedSubjects ? JSON.parse(savedSubjects) : MOCK_SUBJECTS);
    setRooms(savedRooms ? JSON.parse(savedRooms) : ['1', '2', '3']);

    if (savedUsers) {
      setSystemUsers(JSON.parse(savedUsers));
    } else {
      setSystemUsers([
        { id: 'T1', name: 'อ.สมพงษ์ ใจสว่าง', role: 'TEACHER', username: 'teacher', password: '1234', department: 'เทคโนโลยีสารสนเทศ' },
        { id: 'A1', name: 'แอดมิน ระบบ', role: 'ADMIN', username: 'admin', password: '1234', department: 'ส่วนกลาง' },
        { id: 'P1', name: 'คุณแม่ มณี', role: 'PARENT', username: 'parent', password: '1234', studentId: '661001' }
      ]);
    }

    if (savedBlocks) setStudyBlocks(JSON.parse(savedBlocks));
    setIsInitialLoaded(true);
  }, []);

  // Save to LocalStorage - Trigger only after initial load is done
  useEffect(() => {
    if (isInitialLoaded) {
      localStorage.setItem('cms_students', JSON.stringify(students));
      localStorage.setItem('cms_attendance', JSON.stringify(attendance));
      localStorage.setItem('cms_behavior', JSON.stringify(behaviorRecords));
      localStorage.setItem('cms_subjects', JSON.stringify(subjects));
      localStorage.setItem('cms_rooms', JSON.stringify(rooms));
      localStorage.setItem('cms_system_users', JSON.stringify(systemUsers));
      localStorage.setItem('cms_study_blocks', JSON.stringify(studyBlocks));
    }
  }, [students, attendance, behaviorRecords, subjects, rooms, systemUsers, studyBlocks, isInitialLoaded]);

  if (!user) {
    return <Login onLogin={setUser} systemUsers={systemUsers} />;
  }

  const renderContent = () => {
    if ((activeMenu === 'users' || activeMenu === 'settings') && user.role !== 'ADMIN') {
      setActiveMenu('dashboard');
      return null;
    }

    switch (activeMenu) {
      case 'dashboard':
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
      case 'students':
        return <StudentManagement students={students} setStudents={setStudents} />;
      case 'morning':
        return (
          <MorningAttendance 
            students={students} 
            setStudents={setStudents}
            attendanceRecords={attendance}
            setAttendanceRecords={setAttendance}
            rooms={rooms}
            setRooms={setRooms}
          />
        );
      case 'subject':
        return (
          <ClassAttendance 
            students={students} 
            setStudents={setStudents}
            subjects={subjects}
            setSubjects={setSubjects}
            rooms={rooms}
            setRooms={setRooms}
            attendanceRecords={attendance}
            setAttendanceRecords={setAttendance}
            currentUser={user}
          />
        );
      case 'behavior':
        return (
          <BehaviorSystem 
            students={students} 
            setStudents={setStudents}
            behaviorRecords={behaviorRecords}
            setBehaviorRecords={setBehaviorRecords}
          />
        );
      case 'report':
        return <Reports students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
      case 'morning_scores':
        return <MorningScoreSummary students={students} attendance={attendance} studyBlocks={studyBlocks} />;
      case 'users':
        return <UserManagement users={systemUsers} setUsers={setSystemUsers} currentUser={user} />;
      case 'settings':
        return <SystemSettings studyBlocks={studyBlocks} setStudyBlocks={setStudyBlocks} />;
      default:
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
    }
  };

  return (
    <Layout 
      activeMenu={activeMenu} 
      setActiveMenu={setActiveMenu} 
      user={user}
      onLogout={() => setUser(null)}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Student, ThaiLevel, Department } from '../types';
import { 
  FileSpreadsheet, 
  Download, 
  Upload, 
  CheckCircle2, 
  Search, 
  UserPlus,
  Info,
  UserX,
  Users,
  Edit3,
  Trash2,
  X,
  Plus,
  AlertCircle
} from 'lucide-react';

interface StudentManagementProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
}

const StudentManagement: React.FC<StudentManagementProps> = ({ students, setStudents }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const [importStatus, setImportStatus] = useState<null | 'success' | 'error'>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Modal States
  const [showModal, setShowModal] = useState<'ADD' | 'EDIT' | null>(null);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);
  const [editingStudentId, setEditingStudentId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<Student>>({
    studentId: '',
    name: '',
    level: Object.values(ThaiLevel)[0],
    department: Object.values(Department)[0],
    room: '1'
  });

  const filteredStudents = students.filter(s => 
    s.name.includes(searchTerm) || s.studentId.includes(searchTerm)
  );

  const resetForm = () => {
    setFormData({
      studentId: '',
      name: '',
      level: Object.values(ThaiLevel)[0],
      department: Object.values(Department)[0],
      room: '1'
    });
    setEditingStudentId(null);
  };

  const handleOpenEdit = (student: Student) => {
    setFormData({ ...student });
    setEditingStudentId(student.id);
    setShowModal('EDIT');
  };

  const handleOpenAdd = () => {
    resetForm();
    setShowModal('ADD');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (showModal === 'ADD') {
      const newStudent: Student = {
        id: `STU_${Date.now()}`,
        studentId: formData.studentId || '',
        name: formData.name || '',
        level: formData.level || '',
        department: formData.department || '',
        room: formData.room || '1',
        behaviorScore: 100
      };
      setStudents(prev => [newStudent, ...prev]);
    } else if (showModal === 'EDIT' && editingStudentId) {
      setStudents(prev => prev.map(s => 
        s.id === editingStudentId ? { ...s, ...formData } as Student : s
      ));
    }
    setShowModal(null);
    resetForm();
  };

  const confirmDelete = () => {
    if (studentToDelete) {
      setStudents(prev => prev.filter(s => s.id !== studentToDelete.id));
      setStudentToDelete(null);
    }
  };

  const downloadTemplate = () => {
    const headers = "studentId,name,level,department,room\n";
    const example = "661007,นายมานะ อดทน,ปวช. 1,เทคโนโลยีสารสนเทศ,1\n661008,นางสาวชูใจ ใจดี,ปวช. 1,เทคโนโลยีสารสนเทศ,1";
    const csvContent = "data:text/csv;charset=utf-8,\uFEFF" + headers + example;
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "student_template.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;
        const lines = text.split('\n');
        const newStudents: Student[] = [];

        for (let i = 1; i < lines.length; i++) {
          const line = lines[i].trim();
          if (!line) continue;
          const [studentId, name, level, department, room] = line.split(',');

          if (studentId && name) {
            newStudents.push({
              id: `ID_${Date.now()}_${i}`,
              studentId: studentId.trim(),
              name: name.trim(),
              level: level?.trim() || 'ปวช. 1',
              department: department?.trim() || 'เทคโนโลยีสารสนเทศ',
              room: room?.trim() || '1',
              behaviorScore: 100
            });
          }
        }

        if (newStudents.length > 0) {
          setStudents(prev => [...newStudents, ...prev]);
          setImportStatus('success');
        } else setImportStatus('error');
      } catch (err) { setImportStatus('error'); }
      finally { setIsImporting(false); if (fileInputRef.current) fileInputRef.current.value = ''; }
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex items-center gap-4 mb-8">
            <div className="p-4 bg-blue-600 rounded-[24px] text-white shadow-xl shadow-blue-100"><FileSpreadsheet size={28} /></div>
            <div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight">นำเข้าข้อมูลนักเรียน</h3>
              <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">อัปโหลดผ่านไฟล์ CSV มาตรฐาน</p>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div onClick={() => fileInputRef.current?.click()} className="p-8 bg-slate-50 rounded-[32px] border-4 border-dashed border-slate-100 flex flex-col items-center justify-center cursor-pointer hover:border-blue-400 hover:bg-blue-50 transition-all group">
              <input type="file" ref={fileInputRef} className="hidden" accept=".csv" onChange={handleFileUpload} />
              <div className="p-5 bg-white rounded-2xl shadow-sm mb-4 group-hover:scale-110 transition-transform">
                <Upload size={32} className="text-blue-600" />
              </div>
              <p className="font-black text-slate-900">คลิกเพื่ออัปโหลดไฟล์ CSV</p>
              <p className="text-[10px] text-slate-400 font-bold uppercase mt-2">Maximum file size: 5MB</p>
            </div>
            <div className="flex flex-col justify-center gap-4">
              <button type="button" onClick={downloadTemplate} className="flex items-center justify-center gap-3 py-5 bg-slate-900 text-white rounded-[24px] font-black hover:bg-black transition-all shadow-xl shadow-slate-200">
                <Download size={20} /> ดาวน์โหลดเทมเพลต
              </button>
              <div className="p-5 bg-blue-50 rounded-[24px] border border-blue-100">
                <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1 flex items-center gap-2">
                  <Info size={12} /> คำแนะนำ
                </p>
                <p className="text-[11px] text-blue-800 font-bold leading-relaxed">กรุณาเรียงลำดับคอลัมน์ในไฟล์ CSV ให้ถูกต้องตามตัวอย่างเทมเพลตเพื่อให้ระบบนำเข้าข้อมูลได้อย่างแม่นยำ</p>
              </div>
            </div>
          </div>
          {importStatus && (
            <div className={`mt-8 p-5 rounded-[24px] flex items-center gap-4 border-2 animate-in slide-in-from-top-4 ${importStatus === 'success' ? 'bg-green-50 border-green-100 text-green-700' : 'bg-red-50 border-red-100 text-red-700'}`}>
              <CheckCircle2 size={24} />
              <p className="font-black text-sm">{importStatus === 'success' ? 'นำเข้าข้อมูลนักเรียนสำเร็จ!' : 'เกิดข้อผิดพลาดในการอ่านไฟล์ กรุณาตรวจสอบรูปแบบข้อมูล'}</p>
            </div>
          )}
        </div>

        <div className="bg-slate-900 p-10 rounded-[40px] shadow-2xl relative overflow-hidden flex flex-col justify-between">
           <div className="absolute top-0 right-0 p-12 opacity-10 pointer-events-none text-white">
              <Users size={180} />
           </div>
           <div className="relative z-10">
              <h4 className="text-xs font-black text-blue-400 uppercase tracking-[0.3em] mb-6">สรุปข้อมูลทะเบียน</h4>
              <div className="space-y-8">
                <div>
                  <span className="text-slate-400 font-bold text-sm">จำนวนนักเรียนทั้งหมด</span>
                  <p className="text-6xl font-black text-white mt-1">{students.length}</p>
                </div>
                <div className="grid grid-cols-2 gap-4">
                   <div className="bg-white/5 p-4 rounded-2xl border border-white/10">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ปวช.</p>
                      <p className="text-2xl font-black text-white">{students.filter(s => s.level.includes('ปวช')).length}</p>
                   </div>
                   <div className="bg-white/5 p-4 rounded-2xl border border-white/10">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ปวส.</p>
                      <p className="text-2xl font-black text-white">{students.filter(s => s.level.includes('ปวส')).length}</p>
                   </div>
                </div>
              </div>
           </div>
           <div className="mt-8 relative z-10">
              <div className="flex items-center gap-2 text-green-400">
                <CheckCircle2 size={16} />
                <span className="text-[10px] font-black uppercase tracking-widest">Database Synced</span>
              </div>
           </div>
        </div>
      </div>

      <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-8 bg-slate-50/50 flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <h2 className="font-black text-slate-900 text-2xl tracking-tight leading-none">รายชื่อนักเรียนในระบบ</h2>
            <span className="bg-white px-3 py-1 rounded-full border border-slate-200 text-[10px] font-black text-slate-500">{filteredStudents.length} รายการ</span>
          </div>
          <div className="flex flex-col sm:flex-row gap-4 w-full md:w-auto">
            <div className="relative flex-1 sm:w-80">
              <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
              <input 
                type="text" 
                placeholder="ค้นหาชื่อ หรือ รหัส..." 
                value={searchTerm} 
                onChange={(e) => setSearchTerm(e.target.value)} 
                className="w-full bg-white border-2 border-slate-100 rounded-[20px] pl-14 pr-6 py-4 font-bold text-slate-900 outline-none focus:border-blue-500 transition-all shadow-inner" 
              />
            </div>
            <button 
              onClick={handleOpenAdd}
              className="px-8 py-4 bg-blue-600 text-white rounded-[20px] font-black flex items-center justify-center gap-3 shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95"
            >
              <Plus size={20} /> เพิ่มนักเรียน
            </button>
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white border-b border-slate-100">
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ข้อมูลนักเรียน</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ระดับชั้น และ แผนก</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ห้อง</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">จัดการ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredStudents.length > 0 ? filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-5">
                       <div className="w-12 h-12 bg-slate-100 rounded-[18px] flex items-center justify-center text-slate-400 font-black group-hover:bg-blue-600 group-hover:text-white transition-all">
                         {student.name.charAt(0)}
                       </div>
                       <div>
                         <p className="font-black text-slate-900 text-lg leading-tight">{student.name}</p>
                         <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">รหัส: {student.studentId}</p>
                       </div>
                    </div>
                  </td>
                  <td className="px-10 py-6">
                    <div className="flex flex-col gap-1.5">
                       <span className="w-fit px-3 py-1 bg-slate-100 rounded-lg text-[10px] font-black text-slate-600 uppercase">{student.level}</span>
                       <span className="text-xs font-bold text-slate-500">{student.department}</span>
                    </div>
                  </td>
                  <td className="px-10 py-6 text-sm font-black text-slate-900">ห้อง {student.room}</td>
                  <td className="px-10 py-6 text-right">
                    <div className="flex items-center justify-end gap-3">
                      <button 
                        type="button"
                        onClick={() => handleOpenEdit(student)}
                        className="p-3 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-2xl transition-all active:scale-90"
                        title="แก้ไขข้อมูลนักเรียน"
                      >
                        <Edit3 size={20} />
                      </button>
                      <button 
                        type="button"
                        onClick={() => setStudentToDelete(student)}
                        className="p-3 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all active:scale-90"
                        title="ลบรายชื่อนักเรียน"
                      >
                        <Trash2 size={20} />
                      </button>
                    </div>
                  </td>
                </tr>
              )) : (
                <tr>
                  <td colSpan={4} className="py-32 text-center text-slate-300">
                    <UserX size={64} className="mx-auto mb-6 opacity-5" />
                    <p className="text-2xl font-black text-slate-900">ไม่พบรายชื่อนักเรียนที่ค้นหา</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Custom Confirmation Modal for Deletion */}
      {studentToDelete && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-[48px] p-12 shadow-2xl animate-in zoom-in-95 duration-300 text-center">
            <div className="w-24 h-24 bg-red-50 rounded-[32px] flex items-center justify-center text-red-600 mx-auto mb-8 shadow-inner">
               <AlertCircle size={48} />
            </div>
            <h3 className="text-3xl font-black text-slate-900 mb-2 uppercase tracking-tight leading-none">ยืนยันการลบ?</h3>
            <p className="text-slate-500 font-bold mb-8">คุณต้องการลบรายชื่อนักเรียนคนนี้:</p>

            <div className="bg-slate-50 rounded-3xl p-6 mb-10 text-left border border-slate-100">
              <div className="flex items-center gap-3 mb-2">
                 <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">นักเรียน:</span>
                 <span className="text-sm font-black text-slate-900">{studentToDelete.name}</span>
              </div>
              <div className="flex items-center gap-3">
                 <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">รหัส:</span>
                 <span className="text-sm font-black text-slate-900">{studentToDelete.studentId}</span>
              </div>
            </div>

            <p className="text-red-600 text-xs font-black uppercase tracking-widest mb-10">* ข้อมูลจะหายไปจากระบบทันที *</p>

            <div className="flex gap-6">
              <button 
                type="button"
                onClick={() => setStudentToDelete(null)} 
                className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-widest hover:bg-slate-200 transition-colors"
              >
                ยกเลิก
              </button>
              <button 
                type="button"
                onClick={confirmDelete} 
                className="flex-1 py-5 font-black text-white bg-red-600 rounded-[24px] shadow-xl shadow-red-200 uppercase text-xs tracking-widest hover:bg-red-700 transition-colors"
              >
                ยืนยันการลบ
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Add/Edit Student Modal */}
      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md overflow-y-auto">
          <div className="bg-white w-full max-w-lg rounded-[48px] p-10 md:p-14 shadow-2xl animate-in zoom-in-95 relative my-8">
            <button onClick={() => setShowModal(null)} className="absolute top-10 right-10 text-slate-400 hover:text-slate-900 transition-colors">
              <X size={28} />
            </button>
            <h3 className="text-3xl font-black text-slate-900 mb-10 text-center uppercase tracking-tight">
              {showModal === 'ADD' ? 'ลงทะเบียนนักเรียนใหม่' : 'แก้ไขข้อมูลนักเรียน'}
            </h3>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">รหัสประจำตัวนักเรียน</label>
                <input 
                  type="text" 
                  required 
                  value={formData.studentId} 
                  onChange={(e) => setFormData({...formData, studentId: e.target.value})} 
                  className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none transition-all" 
                  placeholder="เช่น 661001" 
                />
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ-นามสกุล</label>
                <input 
                  type="text" 
                  required 
                  value={formData.name} 
                  onChange={(e) => setFormData({...formData, name: e.target.value})} 
                  className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none transition-all" 
                  placeholder="ชื่อ นามสกุล" 
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
                  <select 
                    value={formData.level} 
                    onChange={(e) => setFormData({...formData, level: e.target.value})} 
                    className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none cursor-pointer"
                  >
                    {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ห้องเรียน</label>
                  <select 
                    value={formData.room} 
                    onChange={(e) => setFormData({...formData, room: e.target.value})} 
                    className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none cursor-pointer"
                  >
                    {['1', '2', '3', '4', '5'].map(v => <option key={v} value={v}>ห้อง {v}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
                <select 
                  value={formData.department} 
                  onChange={(e) => setFormData({...formData, department: e.target.value})} 
                  className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none cursor-pointer"
                >
                  {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>

              <div className="flex gap-6 pt-6">
                <button 
                  type="button" 
                  onClick={() => setShowModal(null)} 
                  className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-widest hover:bg-slate-200 transition-all"
                >
                  ยกเลิก
                </button>
                <button 
                  type="submit" 
                  className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-2xl shadow-blue-200 uppercase text-xs tracking-widest hover:bg-blue-700 transition-all"
                >
                  บันทึกข้อมูล
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentManagement;

import React, { useState, useEffect } from 'react';
import { Student, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { Search, Save, CheckCircle2, Filter, Plus, X, History, ClipboardCheck, Calendar, MessageSquare, Clock, UserPlus, Edit3, Trash2, AlertCircle } from 'lucide-react';

interface MorningAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
}

const MorningAttendance: React.FC<MorningAttendanceProps> = ({ 
  students, 
  setStudents, 
  attendanceRecords, 
  setAttendanceRecords,
  rooms,
  setRooms
}) => {
  const [levels, setLevels] = useState<string[]>(Object.values(ThaiLevel));
  const [depts, setDepts] = useState<string[]>(Object.values(Department));

  const [level, setLevel] = useState<string>(levels[0]);
  const [dept, setDept] = useState<string>(depts[0]);
  const [room, setRoom] = useState<string>(rooms[0]);

  const [searchTerm, setSearchTerm] = useState('');
  const [currentSession, setCurrentSession] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');
  const [currentTime, setCurrentTime] = useState(new Date());
  const [isEditingExisting, setIsEditingExisting] = useState(false);

  const [showAddModal, setShowAddModal] = useState<{ type: 'LEVEL' | 'DEPT' | 'ROOM' | 'STUDENT' | null }>({ type: null });
  const [recordToDelete, setRecordToDelete] = useState<AttendanceRecord | null>(null);
  const [editingHistoryRecord, setEditingHistoryRecord] = useState<AttendanceRecord | null>(null);
  const [newValue, setNewValue] = useState('');
  const [newStudent, setNewStudent] = useState({ studentId: '', name: '' });

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    const existingToday = attendanceRecords.filter(r => r.date === today && r.type === 'MORNING');

    if (existingToday.length > 0) {
      const sessionMap: Record<string, AttendanceStatus> = {};
      const remarkMap: Record<string, string> = {};
      let hasDataForCurrentGroup = false;

      existingToday.forEach(r => {
        sessionMap[r.studentId] = r.status;
        if (r.remark) remarkMap[r.studentId] = r.remark;

        if (!hasDataForCurrentGroup) {
          const student = students.find(s => s.id === r.studentId);
          if (student && student.level === level && student.department === dept && student.room === room) {
            hasDataForCurrentGroup = true;
          }
        }
      });

      setCurrentSession(sessionMap);
      setRemarks(remarkMap);
      setIsEditingExisting(hasDataForCurrentGroup);
    } else {
      setCurrentSession({});
      setRemarks({});
      setIsEditingExisting(false);
    }
  }, [level, dept, room, attendanceRecords, students]);

  const filteredStudents = students.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room &&
    (s.name.includes(searchTerm) || s.studentId.includes(searchTerm))
  );

  const historyRecords = attendanceRecords.filter(record => {
    const student = students.find(s => s.id === record.studentId);
    return record.type === 'MORNING' && 
           student?.level === level && 
           student?.department === dept && 
           student?.room === room;
  }).sort((a, b) => b.date.localeCompare(a.date) || b.timestamp.localeCompare(a.timestamp));

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setCurrentSession(prev => ({ ...prev, [studentId]: status }));
    setIsSaved(false);
    if (status === 'PRESENT') {
      setRemarks(prev => {
        const next = { ...prev };
        delete next[studentId];
        return next;
      });
    }
  };

  const handleRemarkChange = (studentId: string, text: string) => {
    setRemarks(prev => ({ ...prev, [studentId]: text }));
  };

  const confirmDelete = () => {
    if (recordToDelete) {
      setAttendanceRecords(prev => prev.filter(r => r.id !== recordToDelete.id));
      setRecordToDelete(null);
    }
  };

  const saveHistoryEdit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHistoryRecord) return;
    setAttendanceRecords(prev => prev.map(r => 
      r.id === editingHistoryRecord.id ? editingHistoryRecord : r
    ));
    setEditingHistoryRecord(null);
  };

  const handleSave = () => {
    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    setAttendanceRecords(prev => {
      const updated = [...prev];
      Object.entries(currentSession).forEach(([studentId, status]) => {
        const existingIdx = updated.findIndex(r => r.studentId === studentId && r.date === today && r.type === 'MORNING');

        if (existingIdx >= 0) {
          updated[existingIdx] = {
            ...updated[existingIdx],
            status,
            remark: remarks[studentId] || '',
            timestamp
          };
        } else {
          updated.push({
            id: `MORNING_${Date.now()}_${studentId}`,
            studentId,
            date: today,
            type: 'MORNING',
            status,
            remark: remarks[studentId] || '',
            timestamp
          });
        }
      });
      return updated;
    });

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 3000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setCurrentSession(prev => ({ ...prev, ...newBatch }));
    if (status === 'PRESENT') setRemarks({});
  };

  const handleAddNew = () => {
    if (showAddModal.type === 'STUDENT') {
      if (!newStudent.studentId || !newStudent.name) return;
      const student: Student = {
        id: `STU_${Date.now()}`,
        studentId: newStudent.studentId,
        name: newStudent.name,
        level: level,
        department: dept,
        room: room,
        behaviorScore: 100
      };
      setStudents(prev => [...prev, student]);
      setNewStudent({ studentId: '', name: '' });
      setShowAddModal({ type: null });
      return;
    }

    if (!newValue.trim()) return;
    if (showAddModal.type === 'LEVEL') setLevels([...levels, newValue]);
    else if (showAddModal.type === 'DEPT') setDepts([...depts, newValue]);
    else if (showAddModal.type === 'ROOM') setRooms([...rooms, newValue]);
    setNewValue('');
    setShowAddModal({ type: null });
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex bg-white p-2 rounded-[24px] border border-slate-200 shadow-sm w-fit">
        <button 
          onClick={() => setViewMode('checkin')} 
          className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <ClipboardCheck size={20} /> เช็คชื่อวันนี้
        </button>
        <button 
          onClick={() => setViewMode('history')} 
          className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <History size={20} /> ประวัติย้อนหลัง
        </button>
      </div>

      <div className="bg-white p-6 md:p-8 rounded-[40px] border border-slate-200 shadow-sm">
        <div className="flex flex-col md:flex-row gap-8">
          <div className="flex-1 grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">ระดับชั้น</label>
                <button onClick={() => setShowAddModal({ type: 'LEVEL' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {levels.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">แผนกวิชา</label>
                <button onClick={() => setShowAddModal({ type: 'DEPT' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {depts.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">ห้องเรียน</label>
                <button onClick={() => setShowAddModal({ type: 'ROOM' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {rooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest ml-1">ค้นหารายชื่อ</label>
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อ-รหัส..." className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl pl-12 pr-4 py-3 font-bold text-slate-900 outline-none" />
              </div>
            </div>
          </div>

          <div className="w-full md:w-64 bg-slate-900 p-6 rounded-[32px] border border-slate-800 flex flex-col justify-center shadow-xl">
            <div className="flex items-center gap-2 text-blue-400 mb-2">
              <Clock size={18} />
              <span className="text-[10px] font-black uppercase tracking-[0.2em]">เวลาปัจจุบัน</span>
            </div>
            <p className="text-4xl font-black text-white tabular-nums tracking-tighter">
              {currentTime.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
            </p>
            <p className="text-sm text-slate-400 font-bold mt-1">
              {currentTime.toLocaleDateString('th-TH', { dateStyle: 'long' })}
            </p>
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <>
          <div className="flex flex-wrap items-center justify-between gap-6 px-2">
            <div className="flex items-center gap-3">
              <span className="text-sm text-slate-500 font-black uppercase tracking-wider">เช็คชื่อด่วน:</span>
              <button onClick={() => markAll('PRESENT')} className="px-5 py-2 bg-green-50 text-green-700 rounded-full text-xs font-black border-2 border-green-200 hover:bg-green-100 transition-all">มาทุกคน</button>
              <button onClick={() => markAll('ABSENT')} className="px-5 py-2 bg-red-50 text-red-700 rounded-full text-xs font-black border-2 border-red-200 hover:bg-red-100 transition-all">ขาดทุกคน</button>
              <button 
                onClick={() => setShowAddModal({ type: 'STUDENT' })}
                className="flex items-center gap-2 px-5 py-2 bg-blue-50 text-blue-700 rounded-full text-xs font-black border-2 border-blue-200 hover:bg-blue-100 transition-all"
              >
                <UserPlus size={14} /> เพิ่มนักเรียนรายคน
              </button>
            </div>
            <button 
              onClick={handleSave} 
              disabled={filteredStudents.length === 0} 
              className={`flex items-center gap-3 px-10 py-4 rounded-2xl text-white font-black transition-all shadow-xl hover:-translate-y-1 active:translate-y-0 ${isSaved ? 'bg-green-600 shadow-green-200' : isEditingExisting ? 'bg-amber-600 shadow-amber-200' : 'bg-slate-900 shadow-slate-200'}`}
            >
              {isSaved ? <CheckCircle2 size={24} /> : isEditingExisting ? <Edit3 size={24} /> : <Save size={24} />} 
              <span className="text-lg">{isSaved ? 'อัปเดตเรียบร้อย' : isEditingExisting ? 'อัปเดตข้อมูลวันนี้' : 'บันทึกข้อมูลวันนี้'}</span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-2 gap-6">
            {filteredStudents.length > 0 ? (
              filteredStudents.map((student, index) => (
                <div key={student.id} className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm hover:border-blue-300 transition-all group flex flex-col justify-between">
                  <div className="flex flex-col md:flex-row md:items-start justify-between gap-5 mb-6">
                    <div className="flex items-start gap-4">
                      <div className="w-14 h-14 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-lg group-hover:bg-blue-600 transition-colors shrink-0">
                        {index + 1}
                      </div>
                      <div>
                        <h4 className="font-black text-slate-900 text-xl leading-tight">{student.name}</h4>
                        <p className="text-xs text-slate-500 font-extrabold uppercase mt-1.5 tracking-widest">รหัส: {student.studentId}</p>
                      </div>
                    </div>
                    <div className="grid grid-cols-5 gap-2 w-full md:w-auto">
                      {Object.entries(STATUS_LABELS).map(([key, value]) => (
                        <button 
                          key={key} 
                          onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} 
                          className={`flex flex-col items-center gap-1.5 p-2 rounded-xl transition-all border-2 ${currentSession[student.id] === key ? value.color + ' border-current scale-105 shadow-md ring-4 ring-blue-500/10' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-300'}`}
                          title={value.label}
                        >
                          <div className="scale-125">{value.icon}</div>
                          <span className="text-[10px] font-black uppercase text-center">{value.label}</span>
                        </button>
                      ))}
                    </div>
                  </div>

                  {currentSession[student.id] && currentSession[student.id] !== 'PRESENT' && (
                    <div className="mt-2 animate-in slide-in-from-top-2">
                      <div className="relative">
                        <MessageSquare className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                        <input 
                          type="text"
                          value={remarks[student.id] || ''}
                          onChange={(e) => handleRemarkChange(student.id, e.target.value)}
                          placeholder={`ระบุสาเหตุที่${STATUS_LABELS[currentSession[student.id]].label}...`}
                          className="w-full bg-slate-50 border-2 border-slate-200 focus:border-blue-400 rounded-xl pl-11 pr-4 py-3 font-bold text-slate-900 outline-none text-sm"
                        />
                      </div>
                    </div>
                  )}
                </div>
              ))
            ) : (
              <div className="col-span-full py-32 text-center text-slate-400 bg-white rounded-[40px] border border-slate-200 border-dashed">
                <Filter size={64} className="mx-auto mb-6 opacity-5" />
                <p className="text-2xl font-black text-slate-900">ไม่พบคลาสเรียนที่ต้องการ</p>
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-300">
          <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/30">
            <h3 className="font-black text-slate-900 text-2xl flex items-center gap-4">
              <Calendar size={28} className="text-blue-600" /> 
              สมุดบันทึกย้อนหลัง
            </h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-100">
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">วันที่</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">นักเรียน</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">สถานะ</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em]">หมายเหตุ</th>
                  <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase tracking-[0.2em] text-center">จัดการ</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {historyRecords.length > 0 ? (
                  historyRecords.map((record) => {
                    const student = students.find(s => s.id === record.studentId);
                    return (
                      <tr key={record.id} className="hover:bg-slate-50/80 transition-colors group">
                        <td className="px-10 py-6 font-extrabold text-slate-900 text-lg">{record.date}</td>
                        <td className="px-10 py-6">
                          <p className="font-black text-slate-900 text-lg">{student?.name}</p>
                          <p className="text-xs text-slate-500 font-bold uppercase">{student?.studentId}</p>
                        </td>
                        <td className="px-10 py-6">
                          <span className={`px-6 py-2 rounded-full text-xs font-black border flex items-center gap-2 w-fit ${STATUS_LABELS[record.status].color}`}>
                            {STATUS_LABELS[record.status].label}
                          </span>
                        </td>
                        <td className="px-10 py-6">
                          <p className="text-sm font-bold text-slate-900">{record.remark || '-'}</p>
                        </td>
                        <td className="px-10 py-6 text-center">
                           <div className="flex items-center justify-center gap-2">
                             <button 
                               type="button"
                               onClick={() => setEditingHistoryRecord(record)}
                               className="p-3 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-2xl transition-all active:scale-90"
                               title="แก้ไขบันทึก"
                             >
                               <Edit3 size={20} />
                             </button>
                             <button 
                               type="button"
                               onClick={() => setRecordToDelete(record)}
                               className="p-3 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all active:scale-90"
                               title="ลบประวัติการเช็คชื่อ"
                             >
                               <Trash2 size={20} />
                             </button>
                           </div>
                        </td>
                      </tr>
                    );
                  })
                ) : (
                  <tr>
                    <td colSpan={5} className="py-32 text-center text-slate-400">
                      <History size={64} className="mx-auto mb-6 opacity-5" />
                      <p className="text-2xl font-black text-slate-900">ยังไม่มีข้อมูลในระบบ</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Edit History Modal */}
      {editingHistoryRecord && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-sm">
          <div className="bg-white w-full max-w-lg rounded-[48px] p-10 md:p-14 shadow-2xl animate-in zoom-in-95 duration-300">
            <h3 className="text-3xl font-black text-slate-900 mb-2 text-center uppercase tracking-tight">แก้ไขบันทึกย้อนหลัง</h3>
            <p className="text-center text-slate-500 font-bold mb-8">
              {students.find(s => s.id === editingHistoryRecord.studentId)?.name} • {editingHistoryRecord.date}
            </p>

            <form onSubmit={saveHistoryEdit} className="space-y-8">
              <div className="grid grid-cols-2 xs:grid-cols-3 sm:grid-cols-5 gap-3">
                {Object.entries(STATUS_LABELS).map(([key, value]) => (
                  <button 
                    key={key} 
                    type="button"
                    onClick={() => setEditingHistoryRecord({...editingHistoryRecord, status: key as AttendanceStatus})} 
                    className={`flex flex-col items-center gap-2 p-3 rounded-2xl transition-all border-2 ${editingHistoryRecord.status === key ? value.color + ' border-current' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-300'}`}
                  >
                    {value.icon}
                    <span className="text-[10px] font-black uppercase text-center">{value.label}</span>
                  </button>
                ))}
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">หมายเหตุ</label>
                <div className="relative">
                  <MessageSquare className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="text" 
                    value={editingHistoryRecord.remark || ''} 
                    onChange={(e) => setEditingHistoryRecord({...editingHistoryRecord, remark: e.target.value})} 
                    className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl pl-14 pr-5 py-4 font-black text-slate-900 outline-none transition-all" 
                    placeholder="ระบุหมายเหตุ..."
                  />
                </div>
              </div>

              <div className="flex gap-6">
                <button type="button" onClick={() => setEditingHistoryRecord(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-widest hover:bg-slate-200 transition-colors">ยกเลิก</button>
                <button type="submit" className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-xs tracking-widest hover:bg-blue-700 transition-colors">บันทึกแก้ไข</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Confirmation Modal for Deletion */}
      {recordToDelete && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-[48px] p-12 shadow-2xl animate-in zoom-in-95 duration-300 text-center">
            <div className="w-24 h-24 bg-red-50 rounded-[32px] flex items-center justify-center text-red-600 mx-auto mb-8 shadow-inner">
               <AlertCircle size={48} />
            </div>
            <h3 className="text-3xl font-black text-slate-900 mb-2 uppercase tracking-tight leading-none">ยืนยันการลบ?</h3>
            <p className="text-slate-500 font-bold mb-8">คุณต้องการลบประวัติการเช็คชื่อของ:</p>

            <div className="bg-slate-50 rounded-3xl p-6 mb-10 text-left border border-slate-100">
              <div className="flex items-center gap-3 mb-2">
                 <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">นักเรียน:</span>
                 <span className="text-sm font-black text-slate-900">{students.find(s => s.id === recordToDelete.studentId)?.name || 'นักเรียน'}</span>
              </div>
              <div className="flex items-center gap-3">
                 <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">วันที่:</span>
                 <span className="text-sm font-black text-slate-900">{recordToDelete.date}</span>
              </div>
            </div>

            <p className="text-red-600 text-xs font-black uppercase tracking-widest mb-10">* การดำเนินการนี้ไม่สามารถย้อนกลับได้ *</p>

            <div className="flex gap-6">
              <button 
                onClick={() => setRecordToDelete(null)} 
                className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-widest hover:bg-slate-200 transition-colors"
              >
                ยกเลิก
              </button>
              <button 
                onClick={confirmDelete} 
                className="flex-1 py-5 font-black text-white bg-red-600 rounded-[24px] shadow-xl shadow-red-200 uppercase text-xs tracking-widest hover:bg-red-700 transition-colors"
              >
                ยืนยันการลบ
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Add New Item Modal */}
      {showAddModal.type && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-md">
          <div className="bg-white w-full max-w-md rounded-[48px] p-12 shadow-2xl animate-in zoom-in-95 duration-300">
            {showAddModal.type === 'STUDENT' ? (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-2 text-center uppercase tracking-tight">เพิ่มนักเรียนใหม่</h3>
                <p className="text-center text-slate-500 font-bold mb-8">{level} {dept} ห้อง {room}</p>
                <div className="space-y-4 mb-10">
                  <div className="space-y-1">
                    <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">รหัสประจำตัว</label>
                    <input 
                      type="text" 
                      value={newStudent.studentId} 
                      onChange={(e) => setNewStudent({...newStudent, studentId: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[24px] px-6 py-4 font-black text-slate-900 text-xl outline-none"
                      placeholder="เช่น 661001"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อ-นามสกุล</label>
                    <input 
                      type="text" 
                      value={newStudent.name} 
                      onChange={(e) => setNewStudent({...newStudent, name: e.target.value})} 
                      className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[24px] px-6 py-4 font-black text-slate-900 text-xl outline-none"
                      placeholder="นายสมมติ นามสกุล"
                    />
                  </div>
                </div>
              </>
            ) : (
              <>
                <h3 className="text-3xl font-black text-slate-900 mb-10 text-center uppercase tracking-tight">เพิ่มรายการใหม่</h3>
                <input 
                  type="text" 
                  autoFocus 
                  value={newValue} 
                  onChange={(e) => setNewValue(e.target.value)} 
                  className="w-full bg-slate-50 border-4 border-slate-100 focus:border-blue-600 rounded-[28px] px-8 py-6 font-black text-slate-900 text-2xl mb-10 outline-none transition-all placeholder:text-slate-300"
                  placeholder="ระบุข้อความที่นี่..."
                />
              </>
            )}
            <div className="flex gap-6">
              <button onClick={() => setShowAddModal({ type: null })} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-sm tracking-widest hover:bg-slate-200 transition-colors">ยกเลิก</button>
              <button onClick={handleAddNew} className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-sm tracking-widest hover:bg-blue-700 transition-colors">ตกลง</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default MorningAttendance;

import React, { useState, useEffect } from 'react';
import { Student, Subject, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { Save, BookOpen, Clock, Users, MessageSquare, UserPlus, X, Plus, Filter, History, ClipboardCheck, Calendar, Edit3, CheckCircle2, Trash2, AlertCircle } from 'lucide-react';

interface ClassAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  subjects: Subject[];
  setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  currentUser: any;
}

const ClassAttendance: React.FC<ClassAttendanceProps> = ({ 
  students: allStudents, 
  setStudents,
  subjects, 
  setSubjects,
  rooms,
  setRooms,
  attendanceRecords, 
  setAttendanceRecords,
  currentUser
}) => {
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');
  const [level, setLevel] = useState<string>(Object.values(ThaiLevel)[0]);
  const [dept, setDept] = useState<string>(Object.values(Department)[0]);
  const [room, setRoom] = useState(rooms.length > 0 ? rooms[0] : '1');
  const [subjectId, setSubjectId] = useState(subjects.length > 0 ? subjects[0].id : '');
  const [sessionAttendance, setSessionAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [isEditingExisting, setIsEditingExisting] = useState(false);

  const [showAddModal, setShowAddModal] = useState<'STUDENT' | 'SUBJECT' | 'ROOM' | null>(null);
  const [recordToDelete, setRecordToDelete] = useState<AttendanceRecord | null>(null);
  const [editingHistoryRecord, setEditingHistoryRecord] = useState<AttendanceRecord | null>(null);
  const [newStudent, setNewStudent] = useState({ studentId: '', name: '' });
  const [newSubject, setNewSubject] = useState({ code: '', name: '' });
  const [newRoomValue, setNewRoomValue] = useState('');

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    const existing = attendanceRecords.filter(r => r.date === today && r.type === 'SUBJECT' && r.subjectId === subjectId);

    if (existing.length > 0) {
      const attMap: Record<string, AttendanceStatus> = {};
      const remMap: Record<string, string> = {};
      let hasDataInGroup = false;

      existing.forEach(r => {
        attMap[r.studentId] = r.status;
        if (r.remark) remMap[r.studentId] = r.remark;

        if (!hasDataInGroup) {
          const s = allStudents.find(stu => stu.id === r.studentId);
          if (s && s.level === level && s.department === dept && s.room === room) hasDataInGroup = true;
        }
      });

      setSessionAttendance(attMap);
      setRemarks(remMap);
      setIsEditingExisting(hasDataInGroup);
    } else {
      setSessionAttendance({});
      setRemarks({});
      setIsEditingExisting(false);
    }
  }, [level, dept, room, subjectId, attendanceRecords, allStudents]);

  const filteredStudents = allStudents.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room
  );

  const historyRecords = attendanceRecords.filter(record => {
    const student = allStudents.find(s => s.id === record.studentId);
    return record.type === 'SUBJECT' && 
           record.subjectId === subjectId &&
           student?.level === level && 
           student?.department === dept && 
           student?.room === room;
  }).sort((a, b) => b.date.localeCompare(a.date) || b.timestamp.localeCompare(a.timestamp));

  const handleStatusChange = (id: string, status: AttendanceStatus) => {
    setSessionAttendance(prev => ({ ...prev, [id]: status }));
    setIsSaved(false);
    if (status === 'PRESENT') {
      setRemarks(prev => {
        const next = { ...prev };
        delete next[id];
        return next;
      });
    }
  };

  const handleRemarkChange = (id: string, text: string) => {
    setRemarks(prev => ({ ...prev, [id]: text }));
  };

  const confirmDelete = () => {
    if (recordToDelete) {
      setAttendanceRecords(prev => prev.filter(r => r.id !== recordToDelete.id));
      setRecordToDelete(null);
    }
  };

  const saveHistoryEdit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHistoryRecord) return;
    setAttendanceRecords(prev => prev.map(r => 
      r.id === editingHistoryRecord.id ? editingHistoryRecord : r
    ));
    setEditingHistoryRecord(null);
  };

  const handleSave = () => {
    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    setAttendanceRecords(prev => {
      const updated = [...prev];
      Object.entries(sessionAttendance).forEach(([studentId, status]) => {
        const existingIdx = updated.findIndex(r => r.studentId === studentId && r.date === today && r.type === 'SUBJECT' && r.subjectId === subjectId);

        if (existingIdx >= 0) {
          updated[existingIdx] = {
            ...updated[existingIdx],
            status,
            remark: remarks[studentId] || '',
            timestamp
          };
        } else {
          updated.push({
            id: `SUBJECT_${Date.now()}_${studentId}_${subjectId}`,
            studentId,
            date: today,
            type: 'SUBJECT',
            subjectId: subjectId,
            status: status as AttendanceStatus,
            remark: remarks[studentId] || '',
            timestamp
          });
        }
      });
      return updated;
    });

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const handleAddStudent = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newStudent.studentId || !newStudent.name) return;
    const student: Student = {
      id: `STU_${Date.now()}`,
      studentId: newStudent.studentId,
      name: newStudent.name,
      level: level,
      department: dept,
      room: room,
      behaviorScore: 100
    };
    setStudents(prev => [...prev, student]);
    setNewStudent({ studentId: '', name: '' });
    setShowAddModal(null);
  };

  const handleAddSubject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newSubject.code || !newSubject.name) return;
    const subject: Subject = {
      id: `SUB_${Date.now()}`,
      code: newSubject.code,
      name: newSubject.name,
      teacherId: currentUser.id
    };
    setSubjects(prev => [...prev, subject]);
    setSubjectId(subject.id);
    setNewSubject({ code: '', name: '' });
    setShowAddModal(null);
  };

  const handleAddRoom = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newRoomValue.trim()) return;
    if (!rooms.includes(newRoomValue)) {
      setRooms(prev => [...prev, newRoomValue]);
      setRoom(newRoomValue);
    }
    setNewRoomValue('');
    setShowAddModal(null);
  };

  return (
    <div className="space-y-4 md:space-y-6 animate-in slide-in-from-bottom-4 duration-500 max-w-[1600px] mx-auto pb-20">
      <div className="flex bg-white p-1 md:p-2 rounded-2xl md:rounded-[24px] border border-slate-200 shadow-sm w-full md:w-fit overflow-hidden">
        <button 
          onClick={() => setViewMode('checkin')} 
          className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-4 md:px-8 py-3 rounded-xl md:rounded-[18px] text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <ClipboardCheck size={18} /> <span className="hidden xs:inline">เช็คชื่อ</span>
        </button>
        <button 
          onClick={() => setViewMode('history')} 
          className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-4 md:px-8 py-3 rounded-xl md:rounded-[18px] text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <History size={18} /> <span className="hidden xs:inline">ประวัติ</span>
        </button>
      </div>

      <div className="bg-white p-4 md:p-6 rounded-[24px] md:rounded-[32px] border border-slate-200 shadow-sm">
        <div className="flex flex-col lg:flex-row gap-6 md:gap-8">
          <div className="flex-1">
            <div className="flex items-center gap-2 text-blue-600 font-black mb-4 md:mb-6 text-base md:text-lg">
              <Filter size={18} />
              <span>ตัวกรองข้อมูล</span>
            </div>
            <div className="grid grid-cols-1 xs:grid-cols-2 md:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
                <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl md:rounded-2xl px-3 py-2.5 md:px-4 md:py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 text-sm appearance-none">
                  {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
                <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl md:rounded-2xl px-3 py-2.5 md:px-4 md:py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 text-sm appearance-none">
                  {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>
              <div className="space-y-1.5">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ห้องเรียน</label>
                  <button onClick={() => setShowAddModal('ROOM')} className="text-blue-600 hover:bg-blue-50 p-1 rounded transition-colors"><Plus size={14} /></button>
                </div>
                <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl md:rounded-2xl px-3 py-2.5 md:px-4 md:py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 text-sm appearance-none">
                  {rooms.map(r => <option key={r} value={r}>ห้อง {r}</option>)}
                </select>
              </div>
              <div className="space-y-1.5">
                <div className="flex justify-between items-center px-1">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">รายวิชา</label>
                  <button onClick={() => setShowAddModal('SUBJECT')} className="text-blue-600 hover:bg-blue-50 p-1 rounded transition-colors"><Plus size={14} /></button>
                </div>
                <select value={subjectId} onChange={(e) => setSubjectId(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl md:rounded-2xl px-3 py-2.5 md:px-4 md:py-3 outline-none focus:ring-2 focus:ring-blue-500 font-bold text-slate-900 text-sm appearance-none">
                  {subjects.map(s => <option key={s.id} value={s.id}>{s.code} - {s.name}</option>)}
                </select>
              </div>
            </div>
          </div>
          <div className="w-full lg:w-64 xl:w-72 bg-slate-900 p-4 md:p-6 rounded-[24px] md:rounded-[32px] border border-slate-800 flex flex-row lg:flex-col items-center lg:items-start justify-between lg:justify-center shadow-xl shrink-0">
            <div className="flex items-center gap-2 text-blue-400">
              <Clock size={16} />
              <span className="text-[9px] md:text-[10px] font-black uppercase tracking-[0.2em] hidden xs:inline">เวลาปัจจุบัน</span>
            </div>
            <div className="lg:mt-2 text-right lg:text-left">
              <p className="text-2xl md:text-4xl font-black text-white tabular-nums tracking-tighter leading-none">
                {currentTime.toLocaleTimeString('th-TH', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
              </p>
              <p className="text-[10px] md:text-xs text-slate-400 font-bold mt-1 uppercase tracking-wider hidden lg:block">
                {currentTime.toLocaleDateString('th-TH', { dateStyle: 'medium' })}
              </p>
            </div>
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <div className="bg-white rounded-[24px] md:rounded-[32px] border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-300">
          <div className="p-4 md:p-6 bg-slate-50/50 border-b border-slate-200 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <Users size={20} className="text-slate-900" />
              <span className="font-black text-slate-900 text-lg md:text-xl tracking-tight">นักเรียน ({filteredStudents.length})</span>
              {isEditingExisting && <span className="px-3 py-1 bg-amber-100 text-amber-700 text-[10px] font-black rounded-lg uppercase tracking-widest animate-pulse">โหมดแก้ไข</span>}
            </div>
            <div className="flex items-center gap-3 w-full sm:w-auto">
              <button onClick={() => setShowAddModal('STUDENT')} className="flex-1 sm:flex-none flex items-center justify-center gap-2 px-4 py-2.5 bg-blue-50 text-blue-600 rounded-xl text-xs font-black border border-blue-200 hover:bg-blue-100 transition-all"><UserPlus size={14} /> เพิ่มรายคน</button>
              <button 
                onClick={handleSave}
                disabled={filteredStudents.length === 0}
                className={`flex-1 sm:flex-none px-6 py-2.5 rounded-xl text-white font-black transition-all shadow-lg flex items-center justify-center gap-2 uppercase tracking-widest text-[10px] md:text-xs ${isSaved ? 'bg-green-600' : isEditingExisting ? 'bg-amber-600 shadow-amber-200' : 'bg-slate-900 shadow-slate-200'}`}
              >
                {isSaved ? <CheckCircle2 size={16} /> : isEditingExisting ? <Edit3 size={16} /> : <Save size={16} />}
                {isSaved ? 'อัปเดตสำเร็จ' : isEditingExisting ? 'อัปเดตข้อมูล' : 'ยืนยันการเช็คชื่อ'}
              </button>
            </div>
          </div>

          <div className="hidden md:block overflow-x-auto">
            <table className="w-full text-left">
              <thead>
                <tr className="bg-white border-b border-slate-100">
                  <th className="px-6 lg:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">ลำดับ</th>
                  <th className="px-6 lg:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">นักเรียน</th>
                  <th className="px-6 lg:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">สถานะ และ หมายเหตุ</th>
                  <th className="px-6 lg:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-center">สถิติ</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {filteredStudents.map((student, idx) => (
                  <tr key={student.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 lg:px-10 py-5 text-sm font-black text-slate-900 align-top">{idx + 1}</td>
                    <td className="px-6 lg:px-10 py-5 align-top">
                      <p className="font-black text-slate-900 text-base leading-tight">{student.name}</p>
                      <p className="text-[10px] text-slate-500 font-extrabold uppercase mt-1 tracking-widest">รหัส: {student.studentId}</p>
                    </td>
                    <td className="px-6 lg:px-10 py-5 align-top">
                      <div className="flex flex-col gap-3">
                        <div className="flex flex-wrap gap-2">
                          {(['PRESENT', 'LATE', 'ABSENT', 'BUSINESS_LEAVE', 'SICK_LEAVE'] as AttendanceStatus[]).map((status) => (
                            <button
                              key={status}
                              onClick={() => handleStatusChange(student.id, status)}
                              className={`px-4 py-2 rounded-xl text-[10px] font-black transition-all border-2 flex items-center gap-1.5 ${sessionAttendance[student.id] === status ? STATUS_LABELS[status].color + ' border-current shadow-md' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}
                            >
                              {STATUS_LABELS[status].icon}
                              {STATUS_LABELS[status].label}
                            </button>
                          ))}
                        </div>
                        {sessionAttendance[student.id] && sessionAttendance[student.id] !== 'PRESENT' && (
                          <div className="relative animate-in slide-in-from-top-2 max-w-md">
                            <MessageSquare className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                            <input type="text" value={remarks[student.id] || ''} onChange={(e) => handleRemarkChange(student.id, e.target.value)} placeholder="ระบุหมายเหตุเพิ่มเติม..." className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-400 rounded-xl pl-9 pr-3 py-2 text-xs font-bold text-slate-900 outline-none" />
                          </div>
                        )}
                      </div>
                    </td>
                    <td className="px-6 lg:px-10 py-5 align-top text-center">
                      <span className="text-[10px] font-black text-slate-900">95%</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      ) : (
        <div className="bg-white rounded-[24px] md:rounded-[32px] border border-slate-200 shadow-sm overflow-hidden animate-in fade-in duration-300">
          <div className="p-5 md:p-7 bg-slate-50/50 border-b flex items-center justify-between">
            <h3 className="font-black text-slate-900 text-lg md:text-2xl flex items-center gap-3 md:gap-4"><Calendar size={22} className="text-blue-600" /> สมุดบันทึกรายวิชา</h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left min-w-[600px]">
              <thead>
                <tr className="bg-white border-b border-slate-100">
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">วันที่</th>
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">นักเรียน</th>
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">สถานะ</th>
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">หมายเหตุ</th>
                  <th className="px-6 md:px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] text-center">จัดการ</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {historyRecords.map((record) => {
                  const student = allStudents.find(s => s.id === record.studentId);
                  return (
                    <tr key={record.id} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-6 md:px-10 py-5 font-black text-slate-900">{record.date}</td>
                      <td className="px-6 md:px-10 py-5">
                        <p className="font-black text-slate-900">{student?.name}</p>
                        <p className="text-[10px] text-slate-500">{student?.studentId}</p>
                      </td>
                      <td className="px-6 md:px-10 py-5"><span className={`px-4 py-1.5 rounded-lg text-[10px] font-black border-2 ${STATUS_LABELS[record.status].color}`}>{STATUS_LABELS[record.status].label}</span></td>
                      <td className="px-6 md:px-10 py-5 text-xs font-bold">{record.remark || '-'}</td>
                      <td className="px-6 md:px-10 py-5 text-center">
                         <div className="flex items-center justify-center gap-2">
                           <button 
                             type="button"
                             onClick={() => setEditingHistoryRecord(record)}
                             className="p-3 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-2xl transition-all active:scale-90"
                             title="แก้ไขบันทึก"
                           >
                             <Edit3 size={20} />
                           </button>
                           <button 
                             type="button"
                             onClick={() => setRecordToDelete(record)} 
                             className="p-3 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all active:scale-90" 
                             title="ลบประวัติการเช็คชื่อ"
                           >
                             <Trash2 size={20} />
                           </button>
                         </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Edit History Modal */}
      {editingHistoryRecord && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-sm">
          <div className="bg-white w-full max-w-lg rounded-[48px] p-10 md:p-14 shadow-2xl animate-in zoom-in-95 duration-300">
            <h3 className="text-3xl font-black text-slate-900 mb-2 text-center uppercase tracking-tight">แก้ไขบันทึกรายวิชา</h3>
            <p className="text-center text-slate-500 font-bold mb-8">
              {allStudents.find(s => s.id === editingHistoryRecord.studentId)?.name} • {editingHistoryRecord.date}
            </p>

            <form onSubmit={saveHistoryEdit} className="space-y-8">
              <div className="grid grid-cols-2 xs:grid-cols-3 sm:grid-cols-5 gap-3">
                {Object.entries(STATUS_LABELS).map(([key, value]) => (
                  <button 
                    key={key} 
                    type="button"
                    onClick={() => setEditingHistoryRecord({...editingHistoryRecord, status: key as AttendanceStatus})} 
                    className={`flex flex-col items-center gap-2 p-3 rounded-2xl transition-all border-2 ${editingHistoryRecord.status === key ? value.color + ' border-current' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-300'}`}
                  >
                    {value.icon}
                    <span className="text-[10px] font-black uppercase text-center">{value.label}</span>
                  </button>
                ))}
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">หมายเหตุ</label>
                <div className="relative">
                  <MessageSquare className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="text" 
                    value={editingHistoryRecord.remark || ''} 
                    onChange={(e) => setEditingHistoryRecord({...editingHistoryRecord, remark: e.target.value})} 
                    className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl pl-14 pr-5 py-4 font-black text-slate-900 outline-none transition-all" 
                    placeholder="ระบุหมายเหตุ..."
                  />
                </div>
              </div>

              <div className="flex gap-6">
                <button type="button" onClick={() => setEditingHistoryRecord(null)} className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-widest hover:bg-slate-200 transition-colors">ยกเลิก</button>
                <button type="submit" className="flex-1 py-5 font-black text-white bg-blue-600 rounded-[24px] shadow-xl shadow-blue-200 uppercase text-xs tracking-widest hover:bg-blue-700 transition-colors">บันทึกแก้ไข</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Confirmation Modal for Deletion */}
      {recordToDelete && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-[48px] p-12 shadow-2xl animate-in zoom-in-95 duration-300 text-center">
            <div className="w-24 h-24 bg-red-50 rounded-[32px] flex items-center justify-center text-red-600 mx-auto mb-8 shadow-inner">
               <AlertCircle size={48} />
            </div>
            <h3 className="text-3xl font-black text-slate-900 mb-2 uppercase tracking-tight leading-none">ยืนยันการลบ?</h3>
            <p className="text-slate-500 font-bold mb-8">คุณต้องการลบประวัติการเช็คชื่อของ:</p>

            <div className="bg-slate-50 rounded-3xl p-6 mb-10 text-left border border-slate-100">
              <div className="flex items-center gap-3 mb-2">
                 <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">นักเรียน:</span>
                 <span className="text-sm font-black text-slate-900">{allStudents.find(s => s.id === recordToDelete.studentId)?.name || 'นักเรียน'}</span>
              </div>
              <div className="flex items-center gap-3">
                 <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">วันที่:</span>
                 <span className="text-sm font-black text-slate-900">{recordToDelete.date}</span>
              </div>
            </div>

            <p className="text-red-600 text-xs font-black uppercase tracking-widest mb-10">* การดำเนินการนี้ไม่สามารถย้อนกลับได้ *</p>

            <div className="flex gap-6">
              <button 
                onClick={() => setRecordToDelete(null)} 
                className="flex-1 py-5 font-black text-slate-600 bg-slate-100 rounded-[24px] uppercase text-xs tracking-widest hover:bg-slate-200 transition-colors"
              >
                ยกเลิก
              </button>
              <button 
                onClick={confirmDelete} 
                className="flex-1 py-5 font-black text-white bg-red-600 rounded-[24px] shadow-xl shadow-red-200 uppercase text-xs tracking-widest hover:bg-red-700 transition-colors"
              >
                ยืนยันการลบ
              </button>
            </div>
          </div>
        </div>
      )}

      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm">
          <div className="bg-white w-full max-w-md rounded-[32px] p-8 shadow-2xl animate-in zoom-in-95">
            <button onClick={() => setShowAddModal(null)} className="absolute top-6 right-6 text-slate-400"><X size={24} /></button>
            <h3 className="text-2xl font-black text-slate-900 mb-6 text-center uppercase">เพิ่มข้อมูล</h3>
            <form onSubmit={showAddModal === 'STUDENT' ? handleAddStudent : showAddModal === 'SUBJECT' ? handleAddSubject : handleAddRoom} className="space-y-4">
              <input type="text" required value={showAddModal === 'STUDENT' ? newStudent.name : showAddModal === 'SUBJECT' ? newSubject.name : newRoomValue} onChange={(e) => showAddModal === 'STUDENT' ? setNewStudent({...newStudent, name: e.target.value}) : showAddModal === 'SUBJECT' ? setNewSubject({...newSubject, name: e.target.value}) : setNewRoomValue(e.target.value)} className="w-full bg-slate-50 border-2 rounded-2xl px-6 py-4 font-black" placeholder="ชื่อ..." />
              <div className="flex gap-4"><button type="button" onClick={() => setShowAddModal(null)} className="flex-1 py-4 bg-slate-100 rounded-2xl">ยกเลิก</button><button type="submit" className="flex-1 py-4 bg-blue-600 text-white rounded-2xl shadow-lg">บันทึก</button></div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ClassAttendance;

import React, { useState, useEffect } from 'react';
import { Student, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { Search, Save, CheckCircle2, Filter, Plus, X, History, ClipboardCheck, Calendar, MessageSquare, Clock, UserPlus, Edit3, Trash2, AlertCircle, Lock } from 'lucide-react';

interface MorningAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
}

const MorningAttendance: React.FC<MorningAttendanceProps> = ({ 
  students, 
  setStudents, 
  attendanceRecords, 
  setAttendanceRecords,
  rooms,
  setRooms
}) => {
  const [levels, setLevels] = useState<string[]>(Object.values(ThaiLevel));
  const [depts, setDepts] = useState<string[]>(Object.values(Department));

  const [level, setLevel] = useState<string>(levels[0]);
  const [dept, setDept] = useState<string>(depts[0]);
  const [room, setRoom] = useState<string>(rooms[0]);

  const [searchTerm, setSearchTerm] = useState('');
  const [currentSession, setCurrentSession] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');
  const [currentTime, setCurrentTime] = useState(new Date());
  const [isEditingExisting, setIsEditingExisting] = useState(false);

  const [showAddModal, setShowAddModal] = useState<{ type: 'LEVEL' | 'DEPT' | 'ROOM' | 'STUDENT' | null }>({ type: null });
  const [recordToDelete, setRecordToDelete] = useState<AttendanceRecord | null>(null);
  const [editingHistoryRecord, setEditingHistoryRecord] = useState<AttendanceRecord | null>(null);
  const [newValue, setNewValue] = useState('');
  const [newStudent, setNewStudent] = useState({ studentId: '', name: '' });

  const todayStr = new Date().toISOString().split('T')[0];

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    const existingToday = attendanceRecords.filter(r => r.date === today && r.type === 'MORNING');

    if (existingToday.length > 0) {
      const sessionMap: Record<string, AttendanceStatus> = {};
      const remarkMap: Record<string, string> = {};
      let hasDataForCurrentGroup = false;

      existingToday.forEach(r => {
        sessionMap[r.studentId] = r.status;
        if (r.remark) remarkMap[r.studentId] = r.remark;

        if (!hasDataForCurrentGroup) {
          const student = students.find(s => s.id === r.studentId);
          if (student && student.level === level && student.department === dept && student.room === room) {
            hasDataForCurrentGroup = true;
          }
        }
      });

      setCurrentSession(sessionMap);
      setRemarks(remarkMap);
      setIsEditingExisting(hasDataForCurrentGroup);
    } else {
      setCurrentSession({});
      setRemarks({});
      setIsEditingExisting(false);
    }
  }, [level, dept, room, attendanceRecords, students]);

  const filteredStudents = students.filter(s => 
    s.level === level && 
    s.department === dept && 
    s.room === room &&
    (s.name.includes(searchTerm) || s.studentId.includes(searchTerm))
  );

  const historyRecords = attendanceRecords.filter(record => {
    const student = students.find(s => s.id === record.studentId);
    return record.type === 'MORNING' && 
           student?.level === level && 
           student?.department === dept && 
           student?.room === room;
  }).sort((a, b) => b.date.localeCompare(a.date) || b.timestamp.localeCompare(a.timestamp));

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setCurrentSession(prev => ({ ...prev, [studentId]: status }));
    setIsSaved(false);
    if (status === 'PRESENT') {
      setRemarks(prev => {
        const next = { ...prev };
        delete next[studentId];
        return next;
      });
    }
  };

  const handleRemarkChange = (studentId: string, text: string) => {
    setRemarks(prev => ({ ...prev, [studentId]: text }));
  };

  const confirmDelete = () => {
    if (recordToDelete) {
      if (recordToDelete.date !== todayStr) {
        alert('ไม่สามารถลบข้อมูลย้อนหลังได้');
        return;
      }
      setAttendanceRecords(prev => prev.filter(r => r.id !== recordToDelete.id));
      setRecordToDelete(null);
    }
  };

  const saveHistoryEdit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingHistoryRecord) return;
    if (editingHistoryRecord.date !== todayStr) {
      alert('ไม่สามารถแก้ไขข้อมูลย้อนหลังได้');
      setEditingHistoryRecord(null);
      return;
    }
    setAttendanceRecords(prev => prev.map(r => 
      r.id === editingHistoryRecord.id ? editingHistoryRecord : r
    ));
    setEditingHistoryRecord(null);
  };

  const handleSave = () => {
    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    setAttendanceRecords(prev => {
      const updated = [...prev];
      Object.entries(currentSession).forEach(([studentId, status]) => {
        const existingIdx = updated.findIndex(r => r.studentId === studentId && r.date === today && r.type === 'MORNING');

        if (existingIdx >= 0) {
          updated[existingIdx] = {
            ...updated[existingIdx],
            status,
            remark: remarks[studentId] || '',
            timestamp
          };
        } else {
          updated.push({
            id: `MORNING_${Date.now()}_${studentId}`,
            studentId,
            date: today,
            type: 'MORNING',
            status,
            remark: remarks[studentId] || '',
            timestamp
          });
        }
      });
      return updated;
    });

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 3000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setCurrentSession(prev => ({ ...prev, ...newBatch }));
    if (status === 'PRESENT') setRemarks({});
  };

  const handleAddNew = () => {
    if (showAddModal.type === 'STUDENT') {
      if (!newStudent.studentId || !newStudent.name) return;
      const student: Student = {
        id: `STU_${Date.now()}`,
        studentId: newStudent.studentId,
        name: newStudent.name,
        level: level,
        department: dept,
        room: room,
        behaviorScore: 100
      };
      setStudents(prev => [...prev, student]);
      setNewStudent({ studentId: '', name: '' });
      setShowAddModal({ type: null });
      return;
    }

    if (!newValue.trim()) return;
    if (showAddModal.type === 'LEVEL') setLevels([...levels, newValue]);
    else if (showAddModal.type === 'DEPT') setDepts([...depts, newValue]);
    else if (showAddModal.type === 'ROOM') setRooms([...rooms, newValue]);
    setNewValue('');
    setShowAddModal({ type: null });
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex bg-white p-2 rounded-[24px] border border-slate-200 shadow-sm w-fit">
        <button 
          onClick={() => setViewMode('checkin')} 
          className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <ClipboardCheck size={20} /> เช็คชื่อวันนี้
        </button>
        <button 
          onClick={() => setViewMode('history')} 
          className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <History size={20} /> ประวัติย้อนหลัง
        </button>
      </div>

      <div className="bg-white p-6 md:p-8 rounded-[40px] border border-slate-200 shadow-sm">
        <div className="flex flex-col md:flex-row gap-8">
          <div className="flex-1 grid grid-cols-1 md:grid-cols-4 gap-6">
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">ระดับชั้น</label>
                <button onClick={() => setShowAddModal({ type: 'LEVEL' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {levels.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">แผนกวิชา</label>
                <button onClick={() => setShowAddModal({ type: 'DEPT' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {depts.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <div className="flex justify-between items-center px-1">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest">ห้องเรียน</label>
                <button onClick={() => setShowAddModal({ type: 'ROOM' })} className="text-blue-600 hover:bg-blue-50 p-1 rounded-md transition-colors"><Plus size={14} /></button>
              </div>
              <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-4 py-3 font-bold text-slate-900 appearance-none cursor-pointer outline-none">
                {rooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest ml-1">ค้นหารายชื่อ</label>
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อ-รหัส..." className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl pl-12 pr-4 py-3 font-bold text-slate-900 outline-none" />
              </div>
            </div>
          </div>

          <div className="w-full md:w-64 bg-slate-900 p-6 rounded-[32px] border border-slate-800 flex flex-col justify-center shadow-xl">
            <div className="flex items-center gap-2 text-blue-400 mb-2">
