import React, { useState, useEffect, useRef } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import MorningAttendance from './components/MorningAttendance';
import ClassAttendance from './components/ClassAttendance';
import BehaviorSystem from './components/BehaviorSystem';
import StudentManagement from './components/StudentManagement';
import Reports from './components/Reports';
import UserManagement from './components/UserManagement';
import SystemSettings from './components/SystemSettings';
import MorningScoreSummary from './components/MorningScoreSummary';
import Login from './components/Login';
import { MOCK_STUDENTS, MOCK_ATTENDANCE, MOCK_BEHAVIOR, MOCK_SUBJECTS } from './data/mockData';
import { Student, AttendanceRecord, BehaviorRecord, Subject, User, StudyBlock } from './types';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeMenu, setActiveMenu] = useState('dashboard');
  const [isInitialLoaded, setIsInitialLoaded] = useState(false);

  // Central States
  const [students, setStudents] = useState<Student[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [behaviorRecords, setBehaviorRecords] = useState<BehaviorRecord[]>([]);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);
  const [systemUsers, setSystemUsers] = useState<User[]>([]);
  const [studyBlocks, setStudyBlocks] = useState<StudyBlock[]>([
    { id: 1, name: 'บล็อกที่ 1', startDate: '2024-03-01', endDate: '2024-03-25', isActive: true, holidays: [] },
    { id: 2, name: 'บล็อกที่ 2', startDate: '', endDate: '', isActive: false, holidays: [] },
    { id: 3, name: 'บล็อกที่ 3', startDate: '', endDate: '', isActive: false, holidays: [] },
    { id: 4, name: 'บล็อกที่ 4', startDate: '', endDate: '', isActive: false, holidays: [] },
    { id: 5, name: 'บล็อกที่ 5', startDate: '', endDate: '', isActive: false, holidays: [] },
  ]);

  // Initialize data with sanitization
  useEffect(() => {
    try {
      const savedStudents = localStorage.getItem('cms_students');
      const savedAttendance = localStorage.getItem('cms_attendance');
      const savedBehavior = localStorage.getItem('cms_behavior');
      const savedSubjects = localStorage.getItem('cms_subjects');
      const savedRooms = localStorage.getItem('cms_rooms');
      const savedUsers = localStorage.getItem('cms_system_users');
      const savedBlocks = localStorage.getItem('cms_study_blocks');

      if (savedStudents) setStudents(JSON.parse(savedStudents));
      else setStudents(MOCK_STUDENTS);

      if (savedAttendance) setAttendance(JSON.parse(savedAttendance));
      else setAttendance(MOCK_ATTENDANCE);

      if (savedBehavior) setBehaviorRecords(JSON.parse(savedBehavior));
      else setBehaviorRecords(MOCK_BEHAVIOR);

      if (savedSubjects) setSubjects(JSON.parse(savedSubjects));
      else setSubjects(MOCK_SUBJECTS);

      if (savedRooms) setRooms(JSON.parse(savedRooms));
      else setRooms(['1', '2', '3']);

      if (savedUsers) {
        setSystemUsers(JSON.parse(savedUsers));
      } else {
        setSystemUsers([
          { id: 'T1', name: 'อ.สมพงษ์ ใจสว่าง', role: 'TEACHER', username: 'teacher', password: '1234', department: 'เทคโนโลยีสารสนเทศ' },
          { id: 'A1', name: 'แอดมิน ระบบ', role: 'ADMIN', username: 'admin', password: '1234', department: 'ส่วนกลาง' },
          { id: 'P1', name: 'คุณแม่ มณี', role: 'PARENT', username: 'parent', password: '1234', studentId: '661001' }
        ]);
      }

      if (savedBlocks) {
        const parsedBlocks = JSON.parse(savedBlocks);
        // Sanitize: Ensure holidays array exists for each block to prevent crashes
        const sanitizedBlocks = parsedBlocks.map((b: any) => ({
          ...b,
          holidays: Array.isArray(b.holidays) ? b.holidays : []
        }));
        setStudyBlocks(sanitizedBlocks);
      }
    } catch (error) {
      console.error("Failed to load data from localStorage:", error);
      // Fallback to mock data on error
      setStudents(MOCK_STUDENTS);
      setAttendance(MOCK_ATTENDANCE);
      setBehaviorRecords(MOCK_BEHAVIOR);
      setSubjects(MOCK_SUBJECTS);
    } finally {
      setIsInitialLoaded(true);
    }
  }, []);

  // Save to LocalStorage
  useEffect(() => {
    if (isInitialLoaded) {
      localStorage.setItem('cms_students', JSON.stringify(students));
      localStorage.setItem('cms_attendance', JSON.stringify(attendance));
      localStorage.setItem('cms_behavior', JSON.stringify(behaviorRecords));
      localStorage.setItem('cms_subjects', JSON.stringify(subjects));
      localStorage.setItem('cms_rooms', JSON.stringify(rooms));
      localStorage.setItem('cms_system_users', JSON.stringify(systemUsers));
      localStorage.setItem('cms_study_blocks', JSON.stringify(studyBlocks));
    }
  }, [students, attendance, behaviorRecords, subjects, rooms, systemUsers, studyBlocks, isInitialLoaded]);

  if (!user) {
    return <Login onLogin={setUser} systemUsers={systemUsers} />;
  }

  const renderContent = () => {
    if ((activeMenu === 'users' || activeMenu === 'settings') && user.role !== 'ADMIN') {
      setActiveMenu('dashboard');
      return null;
    }

    switch (activeMenu) {
      case 'dashboard':
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
      case 'students':
        return <StudentManagement students={students} setStudents={setStudents} />;
      case 'morning':
        return (
          <MorningAttendance 
            students={students} 
            setStudents={setStudents}
            attendanceRecords={attendance}
            setAttendanceRecords={setAttendance}
            rooms={rooms}
            setRooms={setRooms}
          />
        );
      case 'subject':
        return (
          <ClassAttendance 
            students={students} 
            setStudents={setStudents}
            subjects={subjects}
            setSubjects={setSubjects}
            rooms={rooms}
            setRooms={setRooms}
            attendanceRecords={attendance}
            setAttendanceRecords={setAttendance}
            currentUser={user}
          />
        );
      case 'behavior':
        return (
          <BehaviorSystem 
            students={students} 
            setStudents={setStudents}
            behaviorRecords={behaviorRecords}
            setBehaviorRecords={setBehaviorRecords}
          />
        );
      case 'report':
        return <Reports students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
      case 'morning_scores':
        return <MorningScoreSummary students={students} attendance={attendance} studyBlocks={studyBlocks} />;
      case 'users':
        return <UserManagement users={systemUsers} setUsers={setSystemUsers} currentUser={user} />;
      case 'settings':
        return <SystemSettings studyBlocks={studyBlocks} setStudyBlocks={setStudyBlocks} />;
      default:
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
    }
  };

  return (
    <Layout 
      activeMenu={activeMenu} 
      setActiveMenu={setActiveMenu} 
      user={user}
      onLogout={() => setUser(null)}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { 
  Users, 
  CheckCircle, 
  AlertTriangle, 
  TrendingUp,
  Award,
  Heart,
  CalendarDays,
  Search,
  ArrowLeft,
  User,
  Activity,
  Filter,
  Calendar,
  Layers,
  ChevronLeft,
  ChevronRight,
  BookOpen,
  Sun,
  ChevronRight as ArrowRight,
  UserX,
  Star
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { Student, AttendanceRecord, ThaiLevel, Department, AttendanceStatus, StudyBlock } from '../types';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  user: any;
  studyBlocks: StudyBlock[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex items-start justify-between hover:shadow-md transition-shadow group">
    <div className="space-y-2">
      <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em]">{title}</p>
      <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'}`}>{value}</h3>
      <p className="text-xs text-slate-400 font-bold">{sub}</p>
    </div>
    <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
      {icon}
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ students, attendance, behavior, user, studyBlocks }) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [selectedLevel, setSelectedLevel] = useState<string>('ALL');
  const [selectedDept, setSelectedDept] = useState<string>('ALL');
  const [selectedRoom, setSelectedRoom] = useState<string>('ALL');
  const [timeframe, setTimeframe] = useState<'daily' | 'weekly' | 'monthly'>('weekly');
  const [attendanceType, setAttendanceType] = useState<'MORNING' | 'SUBJECT'>('MORNING');

  const [targetDate, setTargetDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [targetMonth, setTargetMonth] = useState<number>(new Date().getMonth());
  const [targetYear, setTargetYear] = useState<number>(new Date().getFullYear());

  const months = [
    "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
    "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
  ];

  const daysOfWeek = ["อา.", "จ.", "อ.", "พ.", "พฤ.", "ศ.", "ส."];

  const filteredStudentsByRoom = useMemo(() => {
    return students.filter(s => {
      const levelMatch = selectedLevel === 'ALL' || s.level === selectedLevel;
      const deptMatch = selectedDept === 'ALL' || s.department === selectedDept;
      const roomMatch = selectedRoom === 'ALL' || s.room === selectedRoom;
      return levelMatch && deptMatch && roomMatch;
    });
  }, [students, selectedLevel, selectedDept, selectedRoom]);

  const atRiskStudents = useMemo(() => {
    return filteredStudentsByRoom.filter(s => s.behaviorScore < 70).sort((a, b) => a.behaviorScore - b.behaviorScore);
  }, [filteredStudentsByRoom]);

  const studentIdsInRoom = useMemo(() => filteredStudentsByRoom.map(s => s.id), [filteredStudentsByRoom]);

  const roomAttendance = useMemo(() => 
    attendance.filter(a => studentIdsInRoom.includes(a.studentId) && a.type === attendanceType), 
    [attendance, studentIdsInRoom, attendanceType]
  );

  const calculateRate = (records: AttendanceRecord[]) => {
    if (records.length === 0) return 0;
    const present = records.filter(r => r.status === 'PRESENT').length;
    return Math.round((present / records.length) * 100);
  };

  const statsRate = useMemo(() => {
    if (timeframe === 'daily') {
      const records = roomAttendance.filter(a => a.date === targetDate);
      return calculateRate(records);
    } else if (timeframe === 'monthly') {
      const records = roomAttendance.filter(a => {
        const d = new Date(a.date);
        return d.getMonth() === targetMonth && d.getFullYear() === targetYear;
      });
      return calculateRate(records);
    } else {
      const base = new Date(targetDate);
      const day = base.getDay();
      const diff = base.getDate() - day + (day === 0 ? -6 : 1);
      const monday = new Date(new Date(targetDate).setDate(diff));
      const friday = new Date(new Date(monday).setDate(monday.getDate() + 4));

      const records = roomAttendance.filter(a => {
        const d = new Date(a.date);
        return d >= monday && d <= friday;
      });
      return calculateRate(records);
    }
  }, [roomAttendance, targetDate, targetMonth, targetYear, timeframe]);

  // Updated Room Assembly Score with Holiday Logic
  const roomAssemblyScore = useMemo(() => {
    const activeBlocks = studyBlocks.filter(b => b.isActive && b.startDate && b.endDate);
    if (activeBlocks.length === 0 || studentIdsInRoom.length === 0) return "0.0";

    const morningRecords = attendance.filter(a => 
      studentIdsInRoom.includes(a.studentId) && 
      a.type === 'MORNING' &&
      a.status === 'PRESENT' &&
      activeBlocks.some(block => a.date >= block.startDate && a.date <= block.endDate)
    );

    const holidayDays = activeBlocks.reduce((acc, block) => acc + (Array.isArray(block.holidays) ? block.holidays.length : 0), 0);

    // Formula: (ActualPresentSum + (Holidays * StudentCount)) * 5 / (Students * 18 Days)
    const totalPresentCredits = morningRecords.length + (holidayDays * studentIdsInRoom.length);
    const maxPossiblePresentCredits = studentIdsInRoom.length * 18;
    const score = (totalPresentCredits * 5) / maxPossiblePresentCredits;

    return Math.min(5, score).toFixed(1);
  }, [attendance, studentIdsInRoom, studyBlocks]);

  const chartData = useMemo(() => {
    if (timeframe === 'monthly') {
      const monthRanges = [
        { label: 'สัปดาห์ 1', start: 1, end: 7 },
        { label: 'สัปดาห์ 2', start: 8, end: 14 },
        { label: 'สัปดาห์ 3', start: 15, end: 21 },
        { label: 'สัปดาห์ 4', start: 22, end: 31 },
      ];

      return monthRanges.map(range => {
        const weekRecords = roomAttendance.filter(a => {
          const d = new Date(a.date);
          const dayNum = d.getDate();
          return d.getMonth() === targetMonth && 
                 d.getFullYear() === targetYear && 
                 dayNum >= range.start && 
                 dayNum <= range.end;
        });
        return { name: range.label, count: calculateRate(weekRecords) };
      });
    }

    if (timeframe === 'daily') {
      const data = [];
      const baseDate = new Date(targetDate);
      for (let i = 6; i >= 0; i--) {
        const d = new Date(baseDate);
        d.setDate(baseDate.getDate() - i);
        const dStr = d.toISOString().split('T')[0];
        const dayRecords = roomAttendance.filter(a => a.date === dStr);
        data.push({
          name: `${d.getDate()} ${months[d.getMonth()].substring(0, 3)}.`,
          count: calculateRate(dayRecords),
          fullDate: dStr
        });
      }
      return data;
    }

    const data = [];
    const base = new Date(targetDate);
    const day = base.getDay();
    const diff = base.getDate() - day + (day === 0 ? -6 : 1);
    const monday = new Date(new Date(targetDate).setDate(diff));

    for (let i = 0; i < 5; i++) {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      const dStr = d.toISOString().split('T')[0];
      const dayRecords = roomAttendance.filter(a => a.date === dStr);
      data.push({
        name: daysOfWeek[d.getDay()],
        count: calculateRate(dayRecords),
        fullDate: dStr
      });
    }
    return data;
  }, [roomAttendance, timeframe, targetDate, targetMonth, targetYear]);

  const renderIndividualView = (studentId: string) => {
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return null;

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;

    // Individual Block Score with Holiday Logic
    const activeBlocks = studyBlocks.filter(b => b.isActive && b.startDate && b.endDate);
    const actualPresent = attendance.filter(a => 
      a.studentId === student.id && 
      a.type === 'MORNING' && 
      a.status === 'PRESENT' &&
      activeBlocks.some(block => a.date >= block.startDate && a.date <= block.endDate)
    ).length;

    const holidayDays = activeBlocks.reduce((acc, block) => acc + (Array.isArray(block.holidays) ? block.holidays.length : 0), 0);
    const blockPresentWithHolidays = actualPresent + holidayDays;

    const blockScore = ((blockPresentWithHolidays * 5) / 18).toFixed(1);

    const latestBehavior = behavior.filter(b => b.studentId === student.id).slice(0, 5);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between gap-4">
          <button 
            onClick={() => setViewingStudentId(null)}
            className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-black text-sm hover:bg-slate-50 transition-all shadow-sm"
          >
            <ArrowLeft size={18} /> กลับสู่ภาพรวม
          </button>
          <div className="flex items-center gap-3 text-right">
            <div>
              <p className="text-xs font-black text-slate-400 uppercase tracking-widest">มุมมองรายบุคคล</p>
              <p className="text-lg font-black text-slate-900">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-100">
              <User size={24} />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard 
            title="เปอร์เซ็นต์การมาเรียนรวม" 
            value={`${attRate}%`} 
            sub={`จากทั้งหมด ${studentAttendance.length} รายการ`} 
            icon={<TrendingUp size={28} />} 
            color="bg-blue-600"
            textColor="text-blue-600"
          />
          <StatCard 
            title="คะแนนเข้าแถว (บล็อกคอร์ส)" 
            value={`${blockScore} / 5.0`} 
            sub={`รวมวันหยุดพิเศษ ${holidayDays} วัน`} 
            icon={<Star size={28} />} 
            color="bg-amber-500"
            textColor="text-amber-600"
          />
          <StatCard 
            title="ระดับชั้น" 
            value={student.level} 
            sub={student.department} 
            icon={<Activity size={28} />} 
            color="bg-indigo-600"
            textColor="text-indigo-600"
          />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-black text-slate-900 text-xl mb-8 flex items-center gap-3">
              <TrendingUp size={24} className="text-blue-600" />
              กราฟการมาเรียนรายวัน (7 รายการล่าสุด)
            </h3>
            <div className="h-[300px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={studentAttendance.slice(-7).map(a => ({ name: a.date, val: a.status === 'PRESENT' ? 100 : 0 }))}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 700}} />
                  <YAxis hide />
                  <Tooltip 
                    cursor={{fill: '#f8fafc'}}
                    contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                  />
                  <Bar dataKey="val" fill="#2563eb" radius={[10, 10, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-black text-slate-900 text-xl mb-6 flex items-center gap-3">
              <Award size={24} className="text-indigo-600" />
              บันทึกพฤติกรรมล่าสุด
            </h3>
            <div className="space-y-4">
              {latestBehavior.length > 0 ? latestBehavior.map(b => (
                <div key={b.id} className="p-4 bg-slate-50 rounded-2xl flex items-center justify-between border border-slate-100">
                   <div>
                     <p className="font-black text-slate-900 text-sm">{b.reason}</p>
                     <p className="text-[10px] font-bold text-slate-500 uppercase mt-1 tracking-widest">{b.date}</p>
                   </div>
                   <span className={`font-black text-lg ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                     {b.type === 'ADD' ? '+' : '-'}{b.score}
                   </span>
                </div>
              )) : (
                <div className="py-20 text-center flex flex-col items-center opacity-30">
                  <Heart size={48} className="mb-2" />
                  <p className="font-bold">ยังไม่มีบันทึกพฤติกรรม</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  };

  if (user.role === 'PARENT') {
    return renderIndividualView(user.studentId);
  }

  if (viewingStudentId) {
    return renderIndividualView(viewingStudentId);
  }

  const behaviorDist = [
    { name: 'ดีมาก (90+)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 90).length, color: '#16a34a' },
    { name: 'ปกติ (70-89)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 70 && s.behaviorScore < 90).length, color: '#2563eb' },
    { name: 'เฝ้าระวัง (<70)', value: filteredStudentsByRoom.filter(s => s.behaviorScore < 70).length, color: '#dc2626' },
  ];

  const avgBehavior = filteredStudentsByRoom.length > 0 
    ? Math.round(filteredStudentsByRoom.reduce((acc, s) => acc + s.behaviorScore, 0) / filteredStudentsByRoom.length)
    : 0;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col xl:flex-row gap-6">
        <div className="relative flex-1 group">
          <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600 transition-colors">
            <Search size={22} />
          </div>
          <input 
            type="text" 
            placeholder="ค้นหานักเรียนรายบุคคลเพื่อดูข้อมูลเชิงลึก..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border-2 border-slate-100 rounded-[28px] pl-16 pr-6 py-5 text-lg font-black text-slate-900 outline-none focus:border-blue-500 shadow-xl shadow-slate-100/50"
          />
        </div>

        <div className="flex bg-white p-2 rounded-[28px] border-2 border-slate-100 shadow-sm self-start">
          <button onClick={() => setTimeframe('daily')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'daily' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายวัน</button>
          <button onClick={() => setTimeframe('weekly')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'weekly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายสัปดาห์</button>
          <button onClick={() => setTimeframe('monthly')} className={`px-6 py-3 rounded-[20px] text-xs font-black uppercase tracking-widest transition-all ${timeframe === 'monthly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายเดือน</button>
        </div>
      </div>

      <div className="bg-white p-8 rounded-[40px] border-2 border-slate-100 shadow-sm">
        <div className="flex flex-col lg:flex-row items-end gap-8 mb-8 border-b border-slate-50 pb-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-1 w-full">
            <div className="space-y-1.5">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
