                        <input type="date" value={block.startDate} onChange={(e) => handleUpdateBlock(block.id, 'startDate', e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-2xl px-6 py-4 font-black text-slate-900 outline-none transition-all shadow-inner text-base" />
