                    <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-4 flex items-center gap-2">
                      <Sun size={14} className="text-amber-500" /> วันหยุดพิเศษ / วันปิดเรียน (นับเป็นวันมาเรียนให้อัตโนมัติ)
                    </h4>

                    <div className="flex flex-wrap gap-3 mb-5">
                      {Array.isArray(block.holidays) && block.holidays.map(date => {
                        const isConfirming = deletingDate?.blockId === block.id && deletingDate?.date === date;
                        return (
                          <div key={date} className={`flex items-center gap-3 pl-4 pr-1.5 py-2 rounded-xl border-2 font-bold text-sm transition-all duration-300 ${isConfirming ? 'bg-red-600 border-red-700 text-white scale-105 shadow-lg' : 'bg-amber-50 border-amber-100 text-amber-700 hover:border-amber-300'}`}>
                            <span className="flex items-center gap-2">
                              {isConfirming && <AlertTriangle size={14} className="animate-pulse" />}
                              {new Date(date).toLocaleDateString('th-TH', { dateStyle: 'long' })}
                            </span>

                            <button 
                              type="button"
                              onClick={(e) => {
                                e.preventDefault();
                                e.stopPropagation();
                                if (isConfirming) {
                                  processRemoveHoliday(block.id, date);
                                } else {
                                  setDeletingDate({ blockId: block.id, date });
                                  // Reset after 4 seconds if not confirmed
                                  setTimeout(() => setDeletingDate(prev => 
                                    (prev?.blockId === block.id && prev?.date === date) ? null : prev
                                  ), 4000);
                                }
                              }}
                              className={`flex items-center justify-center min-w-[40px] h-[36px] rounded-lg font-black text-[10px] uppercase tracking-wider transition-all ${isConfirming ? 'bg-white text-red-600 px-3' : 'text-amber-400 hover:text-red-500 hover:bg-white/50'}`}
                            >
                              {isConfirming ? (
                                "ยืนยันลบ?"
                              ) : (
                                <Trash2 size={18} />
                              )}
                            </button>

                            {isConfirming && (
                              <button 
                                type="button" 
                                onClick={(e) => { e.stopPropagation(); setDeletingDate(null); }}
                                className="bg-red-700/50 hover:bg-red-800 text-white p-1.5 rounded-lg transition-colors"
                              >
                                <X size={16} />
                              </button>
                            )}
                          </div>
                        );
                      })}
                      {(!Array.isArray(block.holidays) || block.holidays.length === 0) && (
                        <p className="text-xs text-slate-400 italic py-2">ยังไม่มีการกำหนดวันหยุดพิเศษสำหรับบล็อกนี้</p>
                      )}
                    </div>

                    <div className="flex items-center gap-3 max-w-sm">
                      <input type="date" value={newHolidayDate[block.id] || ''} onChange={(e) => setNewHolidayDate(prev => ({ ...prev, [block.id]: e.target.value }))} className="flex-1 bg-slate-50 border-2 border-slate-100 focus:border-amber-400 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none text-sm transition-all" />
                      <button type="button" onClick={() => handleAddHoliday(block.id)} className="bg-amber-500 text-white px-5 py-3.5 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg shadow-amber-100 hover:bg-amber-600 transition-all active:scale-95">
                        <Plus size={16} /> เพิ่มวันหยุด
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        <div className="mt-16 p-8 bg-slate-900 rounded-[40px] text-white flex flex-col md:flex-row items-center justify-between gap-8 shadow-2xl shadow-blue-200 border border-slate-800">
          <div className="flex items-center gap-6">
            <div className="w-16 h-16 bg-blue-600 rounded-3xl flex items-center justify-center shadow-lg shadow-blue-500/20">
              <CheckCircle2 size={32} className="text-white" />
            </div>
            <div>
              <p className="text-xl font-black tracking-tight">สูตรคำนวณคะแนนตามระเบียบใหม่</p>
              <p className="text-blue-400 text-sm font-bold">ระบบจะคำนวณเป็นเกรดเฉลี่ย (0-5.0) จากฐาน 18 วัน</p>
            </div>
          </div>
          <div className="text-center md:text-right shrink-0">
             <p className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-2">Morning Score Formula</p>
             <p className="text-3xl font-black text-amber-500">
               Σ ((มาเรียนจริง + วันหยุดพิเศษ) * 5) / 18
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

