        <div className="p-5 border-b bg-slate-50/50">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="ค้นหานักเรียน..." 
              value={searchTerm} 
              onChange={(e) => setSearchTerm(e.target.value)} 
              className="w-full bg-white border-2 border-slate-100 rounded-2xl pl-11 pr-4 py-3 font-black text-slate-900 outline-none focus:border-blue-500 transition-all text-sm" 
            />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto p-3 space-y-2 scrollbar-hide">
          {filteredStudents.map(student => (
            <button 
              key={student.id} 
              onClick={() => setSelectedStudentId(student.id)} 
              className={`w-full text-left p-5 rounded-[24px] border-2 transition-all ${selectedStudentId === student.id ? 'bg-slate-900 border-slate-900 text-white shadow-xl scale-[1.02]' : 'bg-white border-transparent hover:bg-slate-50 text-slate-900'}`}
            >
              <div className="flex justify-between items-center">
                <div>
                  <p className="font-black text-sm">{student.name}</p>
                  <p className={`text-[10px] font-bold uppercase mt-1 tracking-widest ${selectedStudentId === student.id ? 'text-slate-400' : 'text-slate-500'}`}>รหัส: {student.studentId}</p>
                </div>
                <div className={`px-3 py-1 rounded-xl text-xs font-black shadow-sm ${selectedStudentId === student.id ? 'bg-white text-slate-900' : getScoreStatus(student.behaviorScore).color}`}>
                  {student.behaviorScore}
                </div>
              </div>
            </button>
          ))}
        </div>
      </div>

      <div className="lg:col-span-2 space-y-6">
        {selectedStudent ? (
          <>
            <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm relative overflow-hidden">
              <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none text-blue-600">
                <Award size={150} />
              </div>
              <div className="flex items-center justify-between mb-8 relative z-10">
                <div className="flex items-center gap-6">
                  <div className="w-20 h-20 bg-blue-600 rounded-[28px] flex items-center justify-center text-white shadow-2xl shadow-blue-100">
                    <Award size={40} />
                  </div>
                  <div>
                    <h3 className="text-3xl font-black text-slate-900 tracking-tight">{selectedStudent.name}</h3>
                    <p className="text-slate-500 font-bold uppercase text-xs tracking-widest mt-1">{selectedStudent.level} • {selectedStudent.department}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">คะแนนปัจจุบัน</p>
                  <p className={`text-6xl font-black ${selectedStudent.behaviorScore >= 70 ? 'text-blue-600' : 'text-red-600'}`}>{selectedStudent.behaviorScore}</p>
                </div>
              </div>

              <div className="p-6 bg-slate-50 rounded-[32px] border-2 border-slate-100 space-y-5">
                <h4 className="font-black text-slate-900 flex items-center gap-2 text-sm uppercase tracking-widest">
                  <PlusCircle size={18} className="text-green-600" /> ปรับปรุงคะแนนพฤติกรรม
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
                  <div className="md:col-span-6">
                    <input 
                      type="text" 
                      placeholder="ระบุเหตุผลในการปรับคะแนน..." 
                      value={reason} 
                      onChange={(e) => setReason(e.target.value)} 
                      className="w-full bg-white border-2 border-transparent focus:border-blue-500 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none transition-all shadow-inner" 
                    />
                  </div>
                  <div className="md:col-span-2">
                    <input 
                      type="number" 
                      value={scoreChange} 
                      onChange={(e) => setScoreChange(parseInt(e.target.value) || 0)} 
                      className="w-full bg-white border-2 border-transparent focus:border-blue-500 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none text-center shadow-inner" 
                    />
                  </div>
                  <div className="md:col-span-4 flex gap-3">
                    <button onClick={() => handleScoreUpdate('ADD')} className="flex-1 bg-green-600 text-white font-black rounded-2xl hover:bg-green-700 transition-all shadow-lg shadow-green-100 active:scale-95 text-xs uppercase tracking-widest">บวกคะแนน</button>
                    <button onClick={() => handleScoreUpdate('DEDUCT')} className="flex-1 bg-red-600 text-white font-black rounded-2xl hover:bg-red-700 transition-all shadow-lg shadow-red-100 active:scale-95 text-xs uppercase tracking-widest">หักคะแนน</button>
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
              <h3 className="font-black text-slate-900 flex items-center gap-3 text-xl mb-8">
                <FileText size={24} className="text-blue-600" /> ประวัติการปรับปรุงคะแนน
              </h3>
              <div className="space-y-4">
                {behaviorRecords.filter(b => b.studentId === selectedStudent.id).map(record => {
                  const isConfirming = confirmingDeleteId === record.id;
                  return (
                    <div key={record.id} className={`flex items-center justify-between p-6 rounded-[28px] border-2 transition-all relative overflow-hidden ${isConfirming ? 'bg-red-50 border-red-500 ring-2 ring-red-200' : 'bg-white border-slate-50 hover:border-slate-200'}`}>
                      <div className="flex gap-5 items-center relative z-10">
                        <div className={`w-12 h-12 rounded-[18px] flex items-center justify-center shadow-inner shrink-0 ${record.type === 'ADD' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                          {record.type === 'ADD' ? <PlusCircle size={22} /> : <MinusCircle size={22} />}
                        </div>
                        <div>
                          <p className="font-black text-slate-900 leading-tight">{record.reason}</p>
                          <div className="flex items-center gap-3 mt-1.5">
                             <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{record.date}</span>
                             <span className="text-slate-200">•</span>
                             <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">โดย: {record.recordedBy}</span>
                          </div>
                        </div>
                      </div>

                      <div className="flex items-center gap-6 relative z-10">
                        <div className={`text-2xl font-black ${record.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                          {record.type === 'ADD' ? '+' : '-'}{record.score}
                        </div>

                        <div className="flex items-center gap-2">
                          {isConfirming ? (
                            <div className="flex items-center gap-2 animate-in slide-in-from-right-2 duration-300">
                               <button 
                                onClick={(e) => { e.preventDefault(); e.stopPropagation(); setConfirmingDeleteId(null); }}
                                className="flex items-center gap-2 px-4 py-2.5 bg-slate-200 text-slate-700 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-300 transition-all"
                              >
                                <X size={14} /> ยกเลิก
                              </button>
                              <button 
                                onClick={(e) => { e.preventDefault(); e.stopPropagation(); processDeleteBehavior(record.id); }}
                                className="flex items-center gap-2 px-5 py-2.5 bg-red-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-red-700 transition-all shadow-lg animate-pulse"
                              >
                                <Check size={14} /> ยืนยันการลบ
                              </button>
                            </div>
                          ) : (
                            <button 
                              type="button"
                              onClick={(e) => {
                                e.preventDefault();
                                e.stopPropagation();
                                setConfirmingDeleteId(record.id);
                                // Auto-reset confirmation after 5 seconds
                                setTimeout(() => setConfirmingDeleteId(prev => prev === record.id ? null : prev), 5000);
                              }}
                              className="p-3 text-slate-300 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all"
                              title="ลบรายการนี้"
                            >
                              <Trash2 size={22} />
                            </button>
                          )}
                        </div>
                      </div>
                    </div>
                  );
                })}
                {behaviorRecords.filter(b => b.studentId === selectedStudent.id).length === 0 && (
                  <div className="py-20 text-center flex flex-col items-center justify-center text-slate-300 border-2 border-dashed border-slate-100 rounded-[32px]">
                     <Award size={64} className="mb-4 opacity-5" />
                     <p className="text-sm font-black uppercase tracking-widest">ยังไม่มีประวัติพฤติกรรม</p>
                  </div>
                )}
              </div>
            </div>
          </>
        ) : (
          <div className="h-full bg-white rounded-[40px] border-4 border-dashed border-slate-100 flex flex-col items-center justify-center p-20 text-center">
            <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center text-slate-200 mb-8">
               <AlertCircle size={48} />
            </div>
            <h3 className="text-3xl font-black text-slate-900 mb-2 uppercase tracking-tight">เลือกรายชื่อนักเรียน</h3>
            <p className="text-slate-400 font-bold max-w-xs mx-auto">กรุณาเลือกนักเรียนจากรายการด้านซ้ายเพื่อจัดการคะแนนพฤติกรรมและดูประวัติย้อนหลัง</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default BehaviorSystem;

import React, { useState, useRef } from 'react';
import { Student, ThaiLevel, Department } from '../types';
import * as XLSX from 'https://esm.sh/xlsx';
import { 
  FileSpreadsheet, 
  Download, 
  Upload, 
  CheckCircle2, 
  Search, 
  UserPlus,
  Info,
  UserX,
  Users,
  Edit3,
  Trash2,
  X,
  Plus,
  AlertCircle,
  FileText
} from 'lucide-react';

interface StudentManagementProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
}

const StudentManagement: React.FC<StudentManagementProps> = ({ students, setStudents }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isImporting, setIsImporting] = useState(false);
  const [importStatus, setImportStatus] = useState<null | { type: 'success' | 'error', message: string }>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Modal States
  const [showModal, setShowModal] = useState<'ADD' | 'EDIT' | null>(null);
  const [studentToDelete, setStudentToDelete] = useState<Student | null>(null);
  const [editingStudentId, setEditingStudentId] = useState<string | null>(null);
  const [formData, setFormData] = useState<Partial<Student>>({
    studentId: '',
    name: '',
    level: Object.values(ThaiLevel)[0],
    department: Object.values(Department)[0],
    room: '1'
  });

  const filteredStudents = students.filter(s => 
    s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm)
  );

  const resetForm = () => {
    setFormData({
      studentId: '',
      name: '',
      level: Object.values(ThaiLevel)[0],
      department: Object.values(Department)[0],
      room: '1'
    });
    setEditingStudentId(null);
  };

  const handleOpenEdit = (student: Student) => {
    setFormData({ ...student });
    setEditingStudentId(student.id);
    setShowModal('EDIT');
  };

  const handleOpenAdd = () => {
    resetForm();
    setShowModal('ADD');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (showModal === 'ADD') {
      const newStudent: Student = {
        id: `STU_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
        studentId: formData.studentId || '',
        name: formData.name || '',
        level: formData.level || '',
        department: formData.department || '',
        room: formData.room || '1',
        behaviorScore: 100
      };
      setStudents(prev => [newStudent, ...prev]);
    } else if (showModal === 'EDIT' && editingStudentId) {
      setStudents(prev => prev.map(s => 
        s.id === editingStudentId ? { ...s, ...formData } as Student : s
      ));
    }
    setShowModal(null);
    resetForm();
  };

  const confirmDelete = () => {
    if (studentToDelete) {
      setStudents(prev => prev.filter(s => s.id !== studentToDelete.id));
      setStudentToDelete(null);
    }
  };

  const downloadTemplate = () => {
    const ws = XLSX.utils.json_to_sheet([
      { studentId: "661007", name: "นายมานะ อดทน", level: "ปวช. 1", department: "เทคโนโลยีสารสนเทศ", room: "1" },
      { studentId: "661008", name: "นางสาวชูใจ ใจดี", level: "ปวช. 1", department: "เทคโนโลยีสารสนเทศ", room: "1" }
    ]);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Students");
    XLSX.writeFile(wb, "student_template.xlsx");
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    setImportStatus(null);

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const data = event.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        const json: any[] = XLSX.utils.sheet_to_json(worksheet);

        const newStudents: Student[] = json.map((row, i) => ({
          id: `ID_${Date.now()}_${i}`,
          studentId: String(row.studentId || row['รหัสนักเรียน'] || '').trim(),
          name: String(row.name || row['ชื่อ-นามสกุล'] || '').trim(),
          level: String(row.level || row['ระดับชั้น'] || 'ปวช. 1').trim(),
          department: String(row.department || row['แผนกวิชา'] || 'เทคโนโลยีสารสนเทศ').trim(),
          room: String(row.room || row['ห้อง'] || '1').trim(),
          behaviorScore: 100
        })).filter(s => s.studentId && s.name);

        if (newStudents.length > 0) {
          setStudents(prev => [...newStudents, ...prev]);
          setImportStatus({ type: 'success', message: `นำเข้าข้อมูลสำเร็จ ${newStudents.length} รายการ` });
        } else {
          setImportStatus({ type: 'error', message: 'ไม่พบข้อมูลที่ถูกต้องในไฟล์ กรุณาตรวจสอบหัวตาราง' });
        }
      } catch (err) {
        console.error(err);
        setImportStatus({ type: 'error', message: 'เกิดข้อผิดพลาดในการอ่านไฟล์ Excel/CSV' });
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex items-center gap-4 mb-8">
            <div className="p-4 bg-green-600 rounded-[24px] text-white shadow-xl shadow-green-100"><FileSpreadsheet size={28} /></div>
            <div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight">นำเข้าข้อมูลนักเรียน</h3>
              <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">รองรับไฟล์ Excel (.xlsx) และ CSV</p>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div 
              onClick={() => fileInputRef.current?.click()} 
              className={`p-8 rounded-[32px] border-4 border-dashed flex flex-col items-center justify-center cursor-pointer transition-all group ${isImporting ? 'bg-slate-50 border-slate-200 opacity-50' : 'bg-slate-50 border-slate-100 hover:border-green-400 hover:bg-green-50'}`}
            >
              <input type="file" ref={fileInputRef} className="hidden" accept=".csv, .xlsx, .xls" onChange={handleFileUpload} disabled={isImporting} />
              <div className="p-5 bg-white rounded-2xl shadow-sm mb-4 group-hover:scale-110 transition-transform">
                {isImporting ? (
                  <div className="w-8 h-8 border-4 border-green-600 border-t-transparent rounded-full animate-spin" />
                ) : (
                  <Upload size={32} className="text-green-600" />
                )}
              </div>
              <p className="font-black text-slate-900 text-center">{isImporting ? 'กำลังประมวลผลไฟล์...' : 'คลิกเพื่อเลือกไฟล์ Excel หรือ CSV'}</p>
              <p className="text-[10px] text-slate-400 font-bold uppercase mt-2">Maximum file size: 10MB</p>
            </div>
            <div className="flex flex-col justify-center gap-4">
              <button type="button" onClick={downloadTemplate} className="flex items-center justify-center gap-3 py-5 bg-slate-900 text-white rounded-[24px] font-black hover:bg-black transition-all shadow-xl shadow-slate-200">
                <Download size={20} /> ดาวน์โหลดเทมเพลต Excel
              </button>
              <div className="p-5 bg-blue-50 rounded-[24px] border border-blue-100">
                <p className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1 flex items-center gap-2">
                  <Info size={12} /> ชื่อคอลัมน์ที่ต้องมี
                </p>
                <p className="text-[10px] text-blue-800 font-bold leading-relaxed">
                  studentId, name, level, department, room
                </p>
              </div>
            </div>
          </div>
          {importStatus && (
            <div className={`mt-8 p-5 rounded-[24px] flex items-center gap-4 border-2 animate-in slide-in-from-top-4 ${importStatus.type === 'success' ? 'bg-green-50 border-green-100 text-green-700' : 'bg-red-50 border-red-100 text-red-700'}`}>
              {importStatus.type === 'success' ? <CheckCircle2 size={24} /> : <AlertCircle size={24} />}
              <p className="font-black text-sm">{importStatus.message}</p>
            </div>
          )}
        </div>

        <div className="bg-slate-900 p-10 rounded-[40px] shadow-2xl relative overflow-hidden flex flex-col justify-between">
           <div className="absolute top-0 right-0 p-12 opacity-10 pointer-events-none text-white">
              <Users size={180} />
           </div>
           <div className="relative z-10">
              <h4 className="text-xs font-black text-blue-400 uppercase tracking-[0.3em] mb-6">สรุปข้อมูลทะเบียน</h4>
              <div className="space-y-8">
                <div>
                  <span className="text-slate-400 font-bold text-sm">จำนวนนักเรียนทั้งหมด</span>
                  <p className="text-6xl font-black text-white mt-1">{students.length}</p>
                </div>
                <div className="grid grid-cols-2 gap-4">
                   <div className="bg-white/5 p-4 rounded-2xl border border-white/10">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ปวช.</p>
                      <p className="text-2xl font-black text-white">{students.filter(s => s.level.includes('ปวช')).length}</p>
                   </div>
                   <div className="bg-white/5 p-4 rounded-2xl border border-white/10">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ปวส.</p>
                      <p className="text-2xl font-black text-white">{students.filter(s => s.level.includes('ปวส')).length}</p>
                   </div>
                </div>
              </div>
           </div>
           <div className="mt-8 relative z-10">
              <div className="flex items-center gap-2 text-green-400">
                <CheckCircle2 size={16} />
                <span className="text-[10px] font-black uppercase tracking-widest">Database Synced</span>
              </div>
           </div>
        </div>
      </div>

      <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-8 bg-slate-50/50 flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <h2 className="font-black text-slate-900 text-2xl tracking-tight leading-none">รายชื่อนักเรียนในระบบ</h2>
            <span className="bg-white px-3 py-1 rounded-full border border-slate-200 text-[10px] font-black text-slate-500">{filteredStudents.length} รายการ</span>
          </div>
          <div className="flex flex-col sm:flex-row gap-4 w-full md:w-auto">
            <div className="relative flex-1 sm:w-80">
              <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
              <input 
                type="text" 
                placeholder="ค้นหาชื่อ หรือ รหัส..." 
                value={searchTerm} 
                onChange={(e) => setSearchTerm(e.target.value)} 
                className="w-full bg-white border-2 border-slate-100 rounded-[20px] pl-14 pr-6 py-4 font-bold text-slate-900 outline-none focus:border-blue-500 transition-all shadow-inner" 
              />
            </div>
            <button 
              onClick={handleOpenAdd}
              className="px-8 py-4 bg-blue-600 text-white rounded-[20px] font-black flex items-center justify-center gap-3 shadow-xl shadow-blue-100 hover:bg-blue-700 transition-all active:scale-95"
            >
              <Plus size={20} /> เพิ่มนักเรียน
            </button>
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white border-b border-slate-100">
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ข้อมูลนักเรียน</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ระดับชั้น และ แผนก</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">ห้อง</th>
                <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] text-right">จัดการ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredStudents.length > 0 ? filteredStudents.map((student) => (
                <tr key={student.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-5">
                       <div className="w-12 h-12 bg-slate-100 rounded-[18px] flex items-center justify-center text-slate-400 font-black group-hover:bg-blue-600 group-hover:text-white transition-all">
                         {student.name.charAt(0)}
                       </div>
                       <div>
                         <p className="font-black text-slate-900 text-lg leading-tight">{student.name}</p>
