export default StudentManagement;

import React, { useState, useEffect, useMemo } from 'react';
import { Student, AttendanceRecord, BehaviorRecord, ThaiLevel, Department, StudyBlock } from '../types';
import { 
  FileText, 
  Search, 
  Download, 
  User, 
  Calendar, 
  Award, 
  TrendingUp,
  BarChart3,
  ShieldAlert,
  Users,
  Grid3X3,
  Filter,
  Star,
  Layers,
  CalendarDays,
  Clock,
  ArrowRight,
  ClipboardList,
  History,
  Activity,
  CheckCircle2,
  XCircle,
  AlertCircle
} from 'lucide-react';
import { STATUS_LABELS } from '../constants';

interface ReportsProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: BehaviorRecord[];
  user: any;
  studyBlocks: StudyBlock[];
}

const Reports: React.FC<ReportsProps> = ({ students, attendance, behavior, user, studyBlocks }) => {
  const [activeTab, setActiveTab] = useState<'individual' | 'room'>('individual');

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudent, setSelectedStudent] = useState<Student | null>(null);

  // Dynamically get departments from current students
  const availableDepts = useMemo(() => {
    const depts = new Set(students.map(s => s.department));
    if (depts.size === 0) Object.values(Department).forEach(d => depts.add(d));
    return Array.from(depts).sort();
  }, [students]);

  const [reportLevel, setReportLevel] = useState<string>(Object.values(ThaiLevel)[0]);
  const [reportDept, setReportDept] = useState<string>(availableDepts[0] || '');
  const [reportRoom, setReportRoom] = useState<string>('1');

  const [reportViewMode, setReportViewMode] = useState<'monthly' | 'block'>('block');
  const [selectedBlockId, setSelectedBlockId] = useState<number | 'ALL'>(
    studyBlocks.find(b => b.isActive)?.id || 'ALL'
  );

  const [reportMonth, setReportMonth] = useState<number>(new Date().getMonth());
  const [reportYear, setReportYear] = useState<number>(new Date().getFullYear());

  useEffect(() => {
    if (user.role === 'PARENT') {
      const child = students.find(s => s.studentId === user.studentId);
      if (child) setSelectedStudent(child);
      setActiveTab('individual');
    }
  }, [user, students]);

  useEffect(() => {
    if (reportDept && !availableDepts.includes(reportDept)) {
      setReportDept(availableDepts[0] || '');
    }
  }, [availableDepts, reportDept]);

  const filteredStudentsForSidebar = students.filter(s => 
    s.name.includes(searchTerm) || s.studentId.includes(searchTerm)
  );

  const roomStudents = students.filter(s => 
    s.level === reportLevel && s.department === reportDept && s.room === reportRoom
  );

  const getDaysInMonth = (month: number, year: number) => {
    return new Date(year, month + 1, 0).getDate();
  };

  const getDatesInRange = (startDate: string, endDate: string) => {
    const dates = [];
    if (!startDate || !endDate) return [];
    let curr = new Date(startDate);
    const last = new Date(endDate);
    while (curr <= last) {
      dates.push(new Date(curr).toISOString().split('T')[0]);
      curr.setDate(curr.getDate() + 1);
    }
    return dates;
  };

  const reportDates = useMemo(() => {
    if (reportViewMode === 'block' && selectedBlockId !== 'ALL') {
      const block = studyBlocks.find(b => b.id === selectedBlockId);
      if (block?.startDate && block?.endDate) {
        return getDatesInRange(block.startDate, block.endDate);
      }
    }

    const days = getDaysInMonth(reportMonth, reportYear);
    return Array.from({ length: days }).map((_, i) => 
      `${reportYear}-${String(reportMonth + 1).padStart(2, '0')}-${String(i + 1).padStart(2, '0')}`
    );
  }, [reportViewMode, selectedBlockId, reportMonth, reportYear, studyBlocks]);

  const getStatusInitial = (status: string) => {
    switch(status) {
      case 'PRESENT': return 'ม';
      case 'LATE': return 'ส';
      case 'ABSENT': return 'ข';
      case 'BUSINESS_LEAVE': return 'ก';
      case 'SICK_LEAVE': return 'ป';
      default: return '-';
    }
  };

  const getStatusColorClass = (status: string) => {
    switch(status) {
      case 'PRESENT': return 'text-green-600 bg-green-50';
      case 'LATE': return 'text-amber-600 bg-amber-50';
      case 'ABSENT': return 'text-red-600 bg-red-50';
      case 'BUSINESS_LEAVE': return 'text-blue-600 bg-blue-50';
      case 'SICK_LEAVE': return 'text-purple-600 bg-purple-50';
      default: return 'text-slate-200';
    }
  };

