      a.studentId === studentId && a.type === 'MORNING' && a.status === 'PRESENT' &&
      targetBlocks.some(block => a.date >= block.startDate && a.date <= block.endDate)
    ).length;
    const holidayDays = targetBlocks.reduce((acc, block) => acc + (block.holidays?.length || 0), 0);
    const totalPresentCredits = presentInBlocks + holidayDays;
    return Math.min(5, (totalPresentCredits * 5) / 18);
