                        <tr><td colSpan={reportDates.length + 2} className="py-32 text-center text-slate-400 font-bold italic bg-white">ไม่พบข้อมูลนักเรียนในห้องนี้</td></tr>
                      )}
                    </tbody>
                  </table>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

