import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, 
  CheckCircle, 
  AlertTriangle, 
  TrendingUp,
  Award,
  Heart,
  CalendarDays,
  Search,
  ArrowLeft,
  User,
