          { id: 'A1', name: 'แอดมิน ระบบ', role: 'ADMIN', username: 'admin', password: '1234', department: 'ส่วนกลาง' },
          { id: 'F1', name: 'การเงิน สถานศึกษา', role: 'FINANCE', username: 'finance', password: '1234', department: 'ฝ่ายการเงิน' },
          { id: 'P1', name: 'คุณแม่ มณี', role: 'PARENT', username: 'parent', password: '1234', studentId: '661001' }
        ]);
      }

      if (savedBlocks) {
        setStudyBlocks(JSON.parse(savedBlocks).map((b: any) => ({
          ...b, holidays: Array.isArray(b.holidays) ? b.holidays : []
        })));
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsInitialLoaded(true);
    }
  }, []);

  // Save to LocalStorage
  useEffect(() => {
    if (isInitialLoaded) {
      localStorage.setItem('cms_students', JSON.stringify(students));
      localStorage.setItem('cms_attendance', JSON.stringify(attendance));
      localStorage.setItem('cms_behavior', JSON.stringify(behaviorRecords));
      localStorage.setItem('cms_subjects', JSON.stringify(subjects));
      localStorage.setItem('cms_rooms', JSON.stringify(rooms));
      localStorage.setItem('cms_system_users', JSON.stringify(systemUsers));
      localStorage.setItem('cms_study_blocks', JSON.stringify(studyBlocks));
      localStorage.setItem('cms_tuition_configs', JSON.stringify(tuitionConfigs));
      localStorage.setItem('cms_payment_records', JSON.stringify(paymentRecords));
    }
  }, [students, attendance, behaviorRecords, subjects, rooms, systemUsers, studyBlocks, tuitionConfigs, paymentRecords, isInitialLoaded]);

  if (!user) {
    return <Login onLogin={setUser} systemUsers={systemUsers} />;
  }

  const renderContent = () => {
    switch (activeMenu) {
      case 'dashboard':
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
      case 'students':
        return <StudentManagement students={students} setStudents={setStudents} />;
      case 'morning':
        return <MorningAttendance students={students} setStudents={setStudents} attendanceRecords={attendance} setAttendanceRecords={setAttendance} rooms={rooms} setRooms={setRooms} />;
      case 'subject':
        return <ClassAttendance students={students} setStudents={setStudents} subjects={subjects} setSubjects={setSubjects} rooms={rooms} setRooms={setRooms} attendanceRecords={attendance} setAttendanceRecords={setAttendance} currentUser={user} />;
      case 'behavior':
        return <BehaviorSystem students={students} setStudents={setStudents} behaviorRecords={behaviorRecords} setBehaviorRecords={setBehaviorRecords} />;
      case 'tuition':
      case 'finance_report':
        return <TuitionSystem students={students} tuitionConfigs={tuitionConfigs} setTuitionConfigs={setTuitionConfigs} paymentRecords={paymentRecords} setPaymentRecords={setPaymentRecords} user={user} />;
      case 'report':
        return <Reports students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
      case 'morning_scores':
        return <MorningScoreSummary students={students} attendance={attendance} studyBlocks={studyBlocks} />;
      case 'users':
        return <UserManagement users={systemUsers} setUsers={setSystemUsers} currentUser={user} students={students} />;
      case 'settings':
        return <SystemSettings studyBlocks={studyBlocks} setStudyBlocks={setStudyBlocks} />;
      default:
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
    }
  };

  return (
    <Layout activeMenu={activeMenu} setActiveMenu={setActiveMenu} user={user} onLogout={() => setUser(null)}>
      {renderContent()}
    </Layout>
  );
};

export default App;

