import React, { useState, useMemo } from 'react';
import { Student, TuitionConfig, PaymentRecord, ThaiLevel, Department } from '../types';
import { CreditCard, Plus, Save, Trash2, Banknote, History, Search, Filter, CheckCircle2, AlertCircle, User, Wallet, ArrowRight } from 'lucide-react';

interface TuitionSystemProps {
  students: Student[];
  tuitionConfigs: TuitionConfig[];
  setTuitionConfigs: React.Dispatch<React.SetStateAction<TuitionConfig[]>>;
  paymentRecords: PaymentRecord[];
  setPaymentRecords: React.Dispatch<React.SetStateAction<PaymentRecord[]>>;
  user: any;
}

const TuitionSystem: React.FC<TuitionSystemProps> = ({ 
  students, tuitionConfigs, setTuitionConfigs, paymentRecords, setPaymentRecords, user 
}) => {
  const [activeTab, setActiveTab] = useState<'config' | 'payment' | 'history'>(
    user.role === 'PARENT' ? 'history' : 'payment'
  );

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(
    user.role === 'PARENT' ? students.find(s => s.studentId === user.studentId)?.id || null : null
  );

  // Configuration States
  const [newConfig, setNewConfig] = useState<Partial<TuitionConfig>>({
    level: Object.values(ThaiLevel)[0],
    department: Object.values(Department)[0],
    amount: 0,
    term: '1/2567'
  });

  // Payment States
  const [paymentAmount, setPaymentAmount] = useState<number>(0);
  const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'TRANSFER'>('TRANSFER');

  const filteredStudents = useMemo(() => {
    return students.filter(s => 
      s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm)
    );
  }, [students, searchTerm]);

  const handleAddConfig = () => {
    if (!newConfig.amount || newConfig.amount <= 0) {
      alert('กรุณาระบุจำนวนเงินที่ถูกต้อง');
      return;
    }
    const config: TuitionConfig = {
      id: `CONF_${Date.now()}`,
      level: newConfig.level!,
      department: newConfig.department!,
      amount: newConfig.amount!,
      term: newConfig.term!
    };
    setTuitionConfigs(prev => [...prev, config]);
    setNewConfig({ ...newConfig, amount: 0 });
  };

  const deleteConfig = (id: string) => {
    if (confirm('ยืนยันการลบการตั้งค่าค่าเทอมนี้?')) {
      setTuitionConfigs(prev => prev.filter(c => c.id !== id));
    }
  };

  const handlePayment = (student: Student, config: TuitionConfig) => {
    if (paymentAmount <= 0) {
      alert('กรุณาระบุจำนวนเงินที่ถูกต้อง');
      return;
    }

    const newPayment: PaymentRecord = {
      id: `PAY_${Date.now()}`,
      studentId: student.id,
      configId: config.id,
      amount: paymentAmount,
      method: paymentMethod,
      date: new Date().toLocaleDateString('th-TH'),
      recordedBy: user.name,
      status: 'PAID'
    };

    setPaymentRecords(prev => [...prev, newPayment]);
    setPaymentAmount(0);
    alert('บันทึกการชำระเงินสำเร็จ');
  };

  const getStudentTuitionStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return null;

    const paidAmount = paymentRecords
      .filter(p => p.studentId === student.id && p.configId === config.id)
      .reduce((sum, p) => sum + p.amount, 0);

    return {
      config,
      paidAmount,
      remaining: config.amount - paidAmount,
      isFullyPaid: paidAmount >= config.amount
    };
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20 max-w-7xl mx-auto">
      {user.role !== 'PARENT' && (
        <div className="flex bg-white p-2 rounded-[30px] border border-slate-200 shadow-sm w-fit mx-auto md:mx-0">
          <button onClick={() => setActiveTab('payment')} className={`px-10 py-4 rounded-[24px] text-sm font-black transition-all ${activeTab === 'payment' ? 'bg-slate-900 text-white shadow-xl scale-105' : 'text-slate-500 hover:bg-slate-50'}`}>รับชำระเงิน</button>
          <button onClick={() => setActiveTab('config')} className={`px-10 py-4 rounded-[24px] text-sm font-black transition-all ${activeTab === 'config' ? 'bg-slate-900 text-white shadow-xl scale-105' : 'text-slate-500 hover:bg-slate-50'}`}>ตั้งค่าค่าเทอม</button>
          <button onClick={() => setActiveTab('history')} className={`px-10 py-4 rounded-[24px] text-sm font-black transition-all ${activeTab === 'history' ? 'bg-slate-900 text-white shadow-xl scale-105' : 'text-slate-500 hover:bg-slate-50'}`}>ประวัติรายรับ</button>
        </div>
      )}

      {activeTab === 'config' && (user.role === 'ADMIN' || user.role === 'FINANCE') && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
