                        <span className="px-4 py-1.5 bg-indigo-50 text-indigo-700 rounded-full text-[11px] font-black">{config.term}</span>
                      </td>
                      <td className="px-10 py-7">
                        <p className="font-black text-slate-900">{config.level}</p>
                        <p className="text-[11px] font-bold text-slate-500 uppercase tracking-tight">{config.department}</p>
                      </td>
                      <td className="px-10 py-7 font-black text-slate-900 text-lg">{config.amount.toLocaleString()} <span className="text-[11px] text-slate-400 ml-1">฿</span></td>
