                                <input type="number" value={paymentAmount} onChange={(e) => setPaymentAmount(Number(e.target.value))} max={status.remaining} className="w-full bg-slate-50 border-2 border-slate-100 focus:border-indigo-500 rounded-[24px] pl-16 pr-8 py-5 font-black text-2xl text-slate-900 outline-none transition-all shadow-inner" placeholder="0.00" />
