                              <button onClick={() => setPaymentMethod('CASH')} className={`h-16 rounded-[20px] text-xs font-black border-2 transition-all flex items-center justify-center gap-2 ${paymentMethod === 'CASH' ? 'bg-emerald-50 border-emerald-600 text-emerald-700 shadow-md' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-300'}`}>
