                            <button onClick={() => handlePayment(student, status.config)} disabled={status.isFullyPaid} className={`w-full h-20 rounded-[28px] font-black flex items-center justify-center gap-4 transition-all shadow-2xl ${status.isFullyPaid ? 'bg-slate-100 text-slate-400 cursor-not-allowed shadow-none' : 'bg-indigo-600 text-white hover:bg-indigo-700 hover:-translate-y-1 active:scale-95 shadow-indigo-200'}`}>
