                        </h3>
                        <div className="space-y-4">
                          {paymentRecords.filter(p => p.studentId === student.id && p.configId === status.config.id).map(p => (
                            <div key={p.id} className="p-6 bg-slate-50 border-2 border-slate-100 rounded-[30px] flex items-center justify-between hover:border-blue-200 transition-all">
