                                  <p className="font-black text-slate-900 text-lg">{p.amount.toLocaleString()} ฿</p>
                                  <div className="flex items-center gap-3 mt-1 opacity-60">
                                     <span className="text-[10px] font-black uppercase tracking-widest">{p.method === 'TRANSFER' ? 'โอนเงินเข้าบัญชี' : 'ชำระด้วยเงินสด'}</span>
                                     <span className="text-slate-300">•</span>
                                     <span className="text-[10px] font-black uppercase tracking-widest">{p.date}</span>
