                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">เจ้าหน้าที่</p>
                                <p className="text-xs font-black text-slate-900">{p.recordedBy}</p>
                              </div>
                            </div>
                          ))}
                          {paymentRecords.filter(p => p.studentId === student.id).length === 0 && (
                            <div className="py-20 text-center opacity-30 italic font-bold text-slate-400 border-2 border-dashed border-slate-100 rounded-[30px]">
                              ไม่พบประวัติการทำรายการ
                            </div>
                          )}
                        </div>
                      </div>
                    </>
                  );
                })()}
              </div>
            ) : (
              <div className="h-full bg-white rounded-[60px] border-4 border-dashed border-slate-100 flex flex-col items-center justify-center p-20 text-center">
                <div className="w-32 h-32 bg-slate-50 rounded-full flex items-center justify-center text-slate-100 mb-10">
                   <Wallet size={80} />
                </div>
                <h3 className="text-4xl font-black text-slate-900 tracking-tight">เลือกนักเรียนเพื่อดำเนินการ</h3>
                <p className="text-slate-400 font-bold mt-4 max-w-sm mx-auto text-lg leading-relaxed">ค้นหารายชื่อนักเรียนจากรายการด้านซ้าย <br/> เพื่อตรวจสอบยอดค้างชำระและรับเงินเข้าสู่ระบบ</p>
              </div>
            )}
          </div>
        </div>
      )}

      {activeTab === 'history' && (
        <div className="bg-white rounded-[50px] border border-slate-200 shadow-sm overflow-hidden flex flex-col animate-in fade-in duration-700">
          <div className="p-10 md:p-14 border-b bg-slate-50/50 flex flex-col md:flex-row justify-between items-start md:items-center gap-8">
            <div className="flex items-center gap-5">
              <div className="w-16 h-16 bg-green-600 rounded-[24px] flex items-center justify-center text-white shadow-2xl shadow-green-100">
                <Banknote size={32} />
              </div>
              <div>
                <h3 className="text-3xl font-black text-slate-900 tracking-tight">สรุปรายรับและประวัติธุรกรรม</h3>
                <p className="text-slate-500 font-bold mt-1">แสดงรายการรับชำระเงินทั้งหมดที่เกิดขึ้นในระบบ</p>
              </div>
            </div>
            <div className="bg-slate-900 p-8 rounded-[35px] text-white shadow-2xl min-w-[280px]">
               <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] mb-2">ยอดรายรับรวมสะสม</p>
               <p className="text-5xl font-black">{paymentRecords.reduce((sum, p) => sum + p.amount, 0).toLocaleString()} <span className="text-xl font-black text-green-400">฿</span></p>
            </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50">
                <tr>
                  <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">วันที่ทำรายการ</th>
                  <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">รหัสนักเรียน / ชื่อ</th>
                  <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">ช่องทาง</th>
                  <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">จำนวนเงิน</th>
                  <th className="px-10 py-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">ผู้ออกใบรับ</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {paymentRecords.sort((a,b) => b.id.localeCompare(a.id)).map(p => {
                  const student = students.find(s => s.id === p.studentId);
                  return (
                    <tr key={p.id} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-10 py-8 text-sm font-bold text-slate-600">{p.date}</td>
                      <td className="px-10 py-8">
                        <p className="font-black text-slate-900 text-lg leading-tight">{student?.name}</p>
                        <p className="text-[11px] font-bold text-slate-400 uppercase tracking-widest mt-1">{student?.studentId}</p>
                      </td>
                      <td className="px-10 py-8">
                        <span className={`px-5 py-2 rounded-full text-[10px] font-black border uppercase tracking-widest ${p.method === 'TRANSFER' ? 'bg-indigo-50 text-indigo-700 border-indigo-100' : 'bg-emerald-50 text-emerald-700 border-emerald-100'}`}>
                           {p.method === 'TRANSFER' ? 'BANK TRANSFER' : 'CASH PAYMENT'}
                        </span>
                      </td>
                      <td className="px-10 py-8">
                        <span className="text-2xl font-black text-slate-900">{p.amount.toLocaleString()}</span>
                        <span className="text-xs font-bold text-slate-400 ml-1.5 uppercase">บาท</span>
                      </td>
                      <td className="px-10 py-8">
                        <div className="flex items-center gap-2">
                          <div className="w-8 h-8 rounded-lg bg-slate-100 flex items-center justify-center text-slate-500 font-black text-[10px]">
                            {p.recordedBy.charAt(0)}
                          </div>
                          <span className="text-xs font-black text-slate-700">{p.recordedBy}</span>
                        </div>
                      </td>
                    </tr>
                  );
                })}
                {paymentRecords.length === 0 && (
                  <tr>
                    <td colSpan={5} className="py-32 text-center text-slate-300">
                       <History size={64} className="mx-auto mb-6 opacity-5" />
                       <p className="text-2xl font-black text-slate-900">ยังไม่มีข้อมูลการชำระเงินในระบบ</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

export default TuitionSystem;

import React, { useState, useMemo } from 'react';
import { Student, TuitionConfig, PaymentRecord, ThaiLevel, Department } from '../types';
import { CreditCard, Plus, Save, Trash2, Banknote, History, Search, Filter, CheckCircle2, AlertCircle, User, Wallet, ArrowRight } from 'lucide-react';

interface TuitionSystemProps {
  students: Student[];
  tuitionConfigs: TuitionConfig[];
  setTuitionConfigs: React.Dispatch<React.SetStateAction<TuitionConfig[]>>;
  paymentRecords: PaymentRecord[];
  setPaymentRecords: React.Dispatch<React.SetStateAction<PaymentRecord[]>>;
  user: any;
}

const TuitionSystem: React.FC<TuitionSystemProps> = ({ 
  students, tuitionConfigs, setTuitionConfigs, paymentRecords, setPaymentRecords, user 
}) => {
  const [activeTab, setActiveTab] = useState<'config' | 'payment' | 'history'>(
    user.role === 'PARENT' ? 'history' : 'payment'
  );

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(
    user.role === 'PARENT' ? students.find(s => s.studentId === user.studentId)?.id || null : null
  );

  // Configuration States
  const [newConfig, setNewConfig] = useState<Partial<TuitionConfig>>({
    level: Object.values(ThaiLevel)[0],
    department: Object.values(Department)[0],
    amount: 0,
    term: '1/2567'
  });

  // Payment States
  const [paymentAmount, setPaymentAmount] = useState<number | "">("");
  const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'TRANSFER'>('TRANSFER');

  const filteredStudents = useMemo(() => {
    return students.filter(s => 
      s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm)
    );
  }, [students, searchTerm]);

  const handleAddConfig = () => {
    if (!newConfig.amount || newConfig.amount <= 0) {
      alert('กรุณาระบุจำนวนเงินที่ถูกต้อง');
      return;
    }
    const config: TuitionConfig = {
      id: `CONF_${Date.now()}`,
      level: newConfig.level!,
      department: newConfig.department!,
      amount: newConfig.amount!,
      term: newConfig.term!
    };
    setTuitionConfigs(prev => [...prev, config]);
    setNewConfig({ ...newConfig, amount: 0 });
  };

  const deleteConfig = (id: string) => {
    if (confirm('ยืนยันการลบการตั้งค่าค่าเทอมนี้?')) {
      setTuitionConfigs(prev => prev.filter(c => c.id !== id));
    }
  };

  const handlePayment = (student: Student, config: TuitionConfig) => {
    const amount = Number(paymentAmount);
    if (!paymentAmount || amount <= 0) {
      alert('กรุณาระบุจำนวนเงินที่ถูกต้อง');
      return;
    }

    const newPayment: PaymentRecord = {
      id: `PAY_${Date.now()}`,
      studentId: student.id,
      configId: config.id,
      amount: amount,
      method: paymentMethod,
      date: new Date().toLocaleDateString('th-TH'),
      recordedBy: user.name,
      status: 'PAID'
    };

    setPaymentRecords(prev => [...prev, newPayment]);
    setPaymentAmount("");
    alert('บันทึกการชำระเงินสำเร็จ');
  };

  const getStudentTuitionStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return null;

    const paidAmount = paymentRecords
      .filter(p => p.studentId === student.id && p.configId === config.id)
      .reduce((sum, p) => sum + p.amount, 0);

    return {
      config,
      paidAmount,
      remaining: config.amount - paidAmount,
      isFullyPaid: paidAmount >= config.amount
    };
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20 max-w-7xl mx-auto">
      {user.role !== 'PARENT' && (
        <div className="flex bg-white p-2 rounded-[30px] border border-slate-200 shadow-sm w-fit mx-auto md:mx-0">
          <button onClick={() => setActiveTab('payment')} className={`px-10 py-4 rounded-[24px] text-sm font-black transition-all ${activeTab === 'payment' ? 'bg-slate-900 text-white shadow-xl scale-105' : 'text-slate-500 hover:bg-slate-50'}`}>รับชำระเงิน</button>
          <button onClick={() => setActiveTab('config')} className={`px-10 py-4 rounded-[24px] text-sm font-black transition-all ${activeTab === 'config' ? 'bg-slate-900 text-white shadow-xl scale-105' : 'text-slate-500 hover:bg-slate-50'}`}>ตั้งค่าค่าเทอม</button>
          <button onClick={() => setActiveTab('history')} className={`px-10 py-4 rounded-[24px] text-sm font-black transition-all ${activeTab === 'history' ? 'bg-slate-900 text-white shadow-xl scale-105' : 'text-slate-500 hover:bg-slate-50'}`}>ประวัติรายรับ</button>
        </div>
      )}

      {activeTab === 'config' && (user.role === 'ADMIN' || user.role === 'FINANCE') && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1 bg-white p-10 rounded-[48px] border border-slate-200 shadow-sm h-fit">
            <h3 className="text-2xl font-black text-slate-900 mb-8 flex items-center gap-3">
              <div className="p-3 bg-blue-50 rounded-2xl text-blue-600"><Plus size={24} /></div>
              ตั้งค่าโครงสร้างค่าเทอม
            </h3>
            <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับการศึกษา</label>
                <select value={newConfig.level} onChange={(e) => setNewConfig({...newConfig, level: e.target.value})} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-[22px] px-6 py-4 font-bold text-slate-900 outline-none appearance-none cursor-pointer">
                  {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
                <select value={newConfig.department} onChange={(e) => setNewConfig({...newConfig, department: e.target.value})} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-[22px] px-6 py-4 font-bold text-slate-900 outline-none appearance-none cursor-pointer">
                  {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest ml-1">ยอดชำระ (บาท)</label>
                <div className="relative">
                  <Banknote className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                  <input 
                    type="number" 
                    value={newConfig.amount === 0 ? "" : newConfig.amount} 
                    onChange={(e) => setNewConfig({...newConfig, amount: e.target.value === "" ? 0 : Number(e.target.value)})} 
                    className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-[22px] pl-16 pr-6 py-4 font-black text-slate-900 outline-none" 
                    placeholder="0.00" 
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[11px] font-black text-slate-500 uppercase tracking-widest ml-1">ปีการศึกษา</label>
                <input type="text" value={newConfig.term} onChange={(e) => setNewConfig({...newConfig, term: e.target.value})} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-[22px] px-6 py-4 font-bold text-slate-900 outline-none" placeholder="เช่น 1/2567" />
