            </div>

            <button 
              type="submit"
              onMouseEnter={() => setIsHovered(true)}
              onMouseLeave={() => setIsHovered(false)}
              className="w-full h-16 relative group overflow-hidden bg-slate-900 rounded-2xl transition-all duration-300 shadow-xl active:scale-[0.98] mt-4"
            >
              <div className={`absolute inset-0 bg-blue-600 transition-transform duration-500 ease-in-out ${isHovered ? 'translate-x-0' : '-translate-x-full'}`}></div>
              <div className="flex items-center justify-center gap-3 relative z-10">
                <span className="text-base font-bold text-white font-heading tracking-tight">ยืนยันและเข้าสู่ระบบ</span>
                <ArrowRight size={20} className={`text-white transition-transform duration-300 ${isHovered ? 'translate-x-1' : ''}`} />
              </div>
            </button>
          </form>

          {/* Quick Access Section */}
          <div className="mt-12">
            <div className="flex items-center gap-4 mb-6 opacity-40">
              <div className="h-px flex-1 bg-slate-200"></div>
              <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest font-heading">บัญชีสำหรับทดสอบ</p>
              <div className="h-px flex-1 bg-slate-200"></div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              {[
                { label: 'แอดมิน', id: 'admin', icon: <ShieldCheck size={14} className="text-blue-500" /> },
                { label: 'อาจารย์', id: 'teacher', icon: <Sparkles size={14} className="text-amber-500" /> },
                { label: 'การเงิน', id: 'finance', icon: <Banknote size={14} className="text-green-500" /> },
                { label: 'ผู้ปกครอง', id: 'parent', icon: <UserIcon size={14} className="text-slate-400" /> }
              ].map((btn) => (
                <button 
                  key={btn.id}
                  type="button"
                  onClick={() => quickLogin(btn.id, '1234')}
                  className="flex items-center justify-center gap-2 py-3 bg-white border border-slate-100 hover:border-blue-500 hover:bg-blue-50/50 rounded-xl transition-all duration-200 group"
                >
                  {btn.icon}
                  <span className="text-xs font-bold text-slate-600 group-hover:text-blue-600 font-heading">{btn.label}</span>
                </button>
              ))}
            </div>
          </div>
        </div>

        <div className="mt-10 flex flex-col items-center gap-1 opacity-30">
          <p className="text-center text-slate-900 font-bold text-[9px] uppercase tracking-widest font-heading">
            Secured Institutional Network
          </p>
        </div>
      </div>
    </div>
  );
};

