import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, 
  CheckCircle, 
  AlertTriangle, 
  TrendingUp,
  Award,
  Heart,
  CalendarDays,
  Search,
  ArrowLeft,
  User,
  Activity,
  Filter,
  Calendar,
  Layers,
  ChevronLeft,
  ChevronRight,
  BookOpen,
  Sun,
  ChevronRight as ArrowRight,
