interface ReportsProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: BehaviorRecord[];
  user: any;
  studyBlocks: StudyBlock[];
}

const Reports: React.FC<ReportsProps> = ({ students, attendance, behavior, user, studyBlocks }) => {
  const [activeTab, setActiveTab] = useState<'individual' | 'room'>(user.role === 'PARENT' ? 'individual' : 'room');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(
    user.role === 'PARENT' ? students.find(s => s.studentId === user.studentId)?.id || null : null
  );

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);
  const availableRooms = useMemo(() => Array.from(new Set(students.map(s => s.room))).sort(), [students]);

  const [reportLevel, setReportLevel] = useState<string>(availableLevels[0] || '');
  const [reportDept, setReportDept] = useState<string>(availableDepts[0] || '');
  const [reportRoom, setReportRoom] = useState<string>(availableRooms[0] || '');

  const selectedStudent = useMemo(() => students.find(s => s.id === selectedStudentId), [students, selectedStudentId]);

  const roomStudents = useMemo(() => {
    return students.filter(s => 
      s.level === reportLevel && s.department === reportDept && s.room === reportRoom
    );
  }, [students, reportLevel, reportDept, reportRoom]);

  const getAttendanceStats = (studentId: string) => {
    const studentRecords = attendance.filter(a => a.studentId === studentId);
    const total = studentRecords.length;
    const present = studentRecords.filter(r => r.status === 'PRESENT').length;
    const late = studentRecords.filter(r => r.status === 'LATE').length;
    const absent = studentRecords.filter(r => r.status === 'ABSENT').length;
    const rate = total > 0 ? Math.round((present / total) * 100) : 0;
    return { total, present, late, absent, rate };
  };

  const exportRoomReport = () => {
    let csv = "data:text/csv;charset=utf-8,\uFEFF";
    csv += "รหัสนักเรียน,ชื่อ-นามสกุล,ระดับชั้น,แผนกวิชา,คะแนนพฤติกรรม,อัตราการเข้าเรียน(%),มาเรียน,สาย,ขาด\n";
    roomStudents.forEach(s => {
      const stats = getAttendanceStats(s.id);
      csv += `${s.studentId},${s.name},${s.level},${s.department},${s.behaviorScore},${stats.rate}%,${stats.present},${stats.late},${stats.absent}\n`;
    });
    const encodedUri = encodeURI(csv);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `รายงานรายห้อง_${reportLevel}_${reportDept}_ห้อง${reportRoom}.csv`);
    link.click();
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex bg-white p-2 rounded-2xl border border-slate-200 shadow-sm w-fit">
        {user.role !== 'PARENT' && (
          <button 
            onClick={() => setActiveTab('room')} 
            className={`flex items-center gap-2 px-8 py-3.5 rounded-xl text-sm font-bold transition-all font-heading ${activeTab === 'room' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
          >
            <Users size={18} /> สรุปรายห้อง
          </button>
        )}
        <button 
          onClick={() => setActiveTab('individual')} 
          className={`flex items-center gap-2 px-8 py-3.5 rounded-xl text-sm font-bold transition-all font-heading ${activeTab === 'individual' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
        >
          <User size={18} /> รายบุคคล
        </button>
      </div>

      {activeTab === 'room' && user.role !== 'PARENT' && (
        <div className="space-y-8">
          <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm grid grid-cols-1 md:grid-cols-4 gap-6 items-end">
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">ระดับชั้น</label>
              <select value={reportLevel} onChange={(e) => setReportLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-3.5 font-bold text-slate-900 outline-none transition-all">
                {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">แผนกวิชา</label>
              <select value={reportDept} onChange={(e) => setReportDept(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-3.5 font-bold text-slate-900 outline-none transition-all">
                {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">ห้อง</label>
              <select value={reportRoom} onChange={(e) => setReportRoom(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-3.5 font-bold text-slate-900 outline-none transition-all">
                {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
            <button 
              onClick={exportRoomReport}
              className="bg-blue-600 text-white px-8 py-4 rounded-xl font-bold flex items-center justify-center gap-3 shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all font-heading"
            >
