                    <th className="px-8 py-4 text-xs font-bold text-slate-500 uppercase">เข้าเรียน</th>
                    <th className="px-8 py-4 text-xs font-bold text-slate-500 uppercase">มา/สาย/ขาด</th>
                    <th className="px-8 py-4 text-xs font-bold text-slate-500 uppercase">สถานะภาพรวม</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {roomStudents.map((s, idx) => {
                    const stats = getAttendanceStats(s.id);
                    return (
                      <tr key={s.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-8 py-5 text-sm font-bold text-slate-400">{idx + 1}</td>
                        <td className="px-8 py-5">
                          <p className="font-bold text-slate-900">{s.name}</p>
                          <p className="text-[10px] text-slate-500 font-medium">{s.studentId}</p>
                        </td>
                        <td className="px-8 py-5">
                          <span className={`font-bold ${s.behaviorScore < 70 ? 'text-red-600' : 'text-slate-900'}`}>
                            {s.behaviorScore}
                          </span>
                        </td>
                        <td className="px-8 py-5">
                          <div className="flex items-center gap-3">
                            <div className="flex-1 h-2 bg-slate-100 rounded-full w-20 overflow-hidden">
                              <div className="h-full bg-blue-600 rounded-full" style={{ width: `${stats.rate}%` }} />
                            </div>
                            <span className="text-xs font-bold text-slate-600">{stats.rate}%</span>
                          </div>
                        </td>
                        <td className="px-8 py-5">
                          <div className="flex gap-2 text-[10px] font-bold">
                            <span className="text-green-600">ม:{stats.present}</span>
                            <span className="text-amber-600">ส:{stats.late}</span>
                            <span className="text-red-600">ข:{stats.absent}</span>
                          </div>
                        </td>
                        <td className="px-8 py-5">
                          {s.behaviorScore < 70 || stats.rate < 80 ? (
                            <span className="px-3 py-1 bg-red-50 text-red-600 rounded-lg text-[10px] font-bold border border-red-100 uppercase">เฝ้าระวัง</span>
                          ) : (
                            <span className="px-3 py-1 bg-green-50 text-green-600 rounded-lg text-[10px] font-bold border border-green-100 uppercase">ปกติ</span>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                  {roomStudents.length === 0 && (
                    <tr>
                      <td colSpan={6} className="py-20 text-center text-slate-400 font-bold">ไม่พบข้อมูลนักเรียนในห้องที่เลือก</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'individual' && (
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          {user.role !== 'PARENT' && (
            <div className="lg:col-span-1">
              <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm h-[600px] flex flex-col">
                <div className="relative mb-4">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input 
                    type="text" 
                    placeholder="ค้นหาชื่อ/รหัส..." 
                    value={searchTerm} 
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-12 pr-4 py-3 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500" 
                  />
                </div>
                <div className="flex-1 overflow-y-auto space-y-2 pr-2">
                  {students.filter(s => s.name.includes(searchTerm) || s.studentId.includes(searchTerm)).map(s => (
                    <button 
                      key={s.id} 
                      onClick={() => setSelectedStudentId(s.id)}
                      className={`w-full text-left p-4 rounded-xl border transition-all ${selectedStudentId === s.id ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white border-transparent hover:bg-slate-50'}`}
                    >
                      <p className="font-bold text-sm truncate">{s.name}</p>
                      <p className={`text-[10px] font-medium mt-1 ${selectedStudentId === s.id ? 'text-slate-400' : 'text-slate-500'}`}>{s.studentId}</p>
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}

          <div className={`${user.role === 'PARENT' ? 'lg:col-span-4' : 'lg:col-span-3'} space-y-6`}>
            {selectedStudent ? (
              <div className="space-y-6 animate-in slide-in-from-right-4 duration-500">
                <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-8">
                  <div className="flex items-center gap-6">
                    <div className="w-20 h-20 bg-blue-600 rounded-[24px] flex items-center justify-center text-white shadow-xl">
                      <User size={40} />
                    </div>
                    <div>
                      <h2 className="text-3xl font-bold text-slate-900 font-heading">{selectedStudent.name}</h2>
                      <p className="text-slate-500 font-bold uppercase text-xs tracking-widest mt-1">
                        {selectedStudent.studentId} • {selectedStudent.level} {selectedStudent.department}
                      </p>
                    </div>
                  </div>
                  <div className="flex gap-4">
                    <div className="text-center px-6 py-4 bg-slate-50 rounded-2xl border border-slate-100">
                      <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">พฤติกรรม</p>
                      <p className={`text-2xl font-black ${selectedStudent.behaviorScore < 70 ? 'text-red-600' : 'text-slate-900'}`}>{selectedStudent.behaviorScore}</p>
                    </div>
                    <div className="text-center px-6 py-4 bg-slate-50 rounded-2xl border border-slate-100">
                      <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">มาเรียน</p>
                      <p className="text-2xl font-black text-blue-600">{getAttendanceStats(selectedStudent.id).rate}%</p>
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm">
                    <h3 className="text-lg font-bold text-slate-900 mb-6 flex items-center gap-3 font-heading">
                      <TrendingUp className="text-blue-600" size={20} /> สถิติการเข้าเรียน (ล่าสุด)
                    </h3>
                    <div className="space-y-3">
                      {attendance.filter(a => a.studentId === selectedStudent.id).slice(-5).reverse().map(a => (
                        <div key={a.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-xl border border-slate-100">
                          <div>
                            <p className="font-bold text-sm text-slate-900">{a.type === 'MORNING' ? 'เข้าแถวหน้าเสาธง' : 'รายวิชา'}</p>
                            <p className="text-[10px] font-medium text-slate-400">{a.date} • {a.timestamp.split(' ')[1]}</p>
                          </div>
                          <span className={`px-3 py-1 rounded-lg text-[10px] font-bold uppercase border ${STATUS_LABELS[a.status].color}`}>
                            {STATUS_LABELS[a.status].label}
                          </span>
                        </div>
                      ))}
                      {attendance.filter(a => a.studentId === selectedStudent.id).length === 0 && (
                         <div className="py-10 text-center text-slate-400 font-bold">ไม่พบประวัติการเข้าเรียน</div>
                      )}
                    </div>
                  </div>

                  <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm">
                    <h3 className="text-lg font-bold text-slate-900 mb-6 flex items-center gap-3 font-heading">
                      <Award className="text-amber-600" size={20} /> บันทึกพฤติกรรม (ล่าสุด)
                    </h3>
                    <div className="space-y-3">
                      {behavior.filter(b => b.studentId === selectedStudent.id).slice(-5).reverse().map(b => (
                        <div key={b.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-xl border border-slate-100">
                          <div>
                            <p className="font-bold text-sm text-slate-900 truncate max-w-[150px]">{b.reason}</p>
                            <p className="text-[10px] font-medium text-slate-400">{b.date}</p>
                          </div>
                          <span className={`font-black text-lg ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                            {b.type === 'ADD' ? '+' : '-'}{b.score}
                          </span>
                        </div>
                      ))}
                      {behavior.filter(b => b.studentId === selectedStudent.id).length === 0 && (
                        <div className="py-10 text-center text-slate-400 font-bold">ไม่พบประวัติพฤติกรรม</div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            ) : (
              <div className="h-[600px] bg-white rounded-[32px] border-2 border-dashed border-slate-100 flex flex-col items-center justify-center p-20 text-center">
                <FileText size={64} className="text-slate-100 mb-6" />
                <h3 className="text-2xl font-bold text-slate-900 font-heading">กรุณาเลือกนักเรียน</h3>
                <p className="text-slate-400 text-sm mt-2 max-w-xs mx-auto">เลือกรายชื่อนักเรียนจากด้านซ้ายเพื่อดูสรุปรายงานผลรายบุคคลแบบละเอียด</p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default Reports;

import React, { useState, useMemo, useEffect } from 'react';
import { Student, AttendanceRecord, StudyBlock } from '../types';
import { Star, Search, Download, TrendingUp, AlertCircle, Sun, CheckCircle2, User } from 'lucide-react';

interface MorningScoreSummaryProps {
  students: Student[];
  attendance: AttendanceRecord[];
  studyBlocks: StudyBlock[];
}

const MorningScoreSummary: React.FC<MorningScoreSummaryProps> = ({ students, attendance, studyBlocks }) => {
  const availableLevels = useMemo<string[]>(() => {
    return Array.from(new Set(students.map(s => s.level))).sort();
  }, [students]);

  const availableDepts = useMemo<string[]>(() => {
    return Array.from(new Set(students.map(s => s.department))).sort();
  }, [students]);

  const availableRooms = useMemo<string[]>(() => {
    return Array.from(new Set(students.map(s => s.room))).sort((a, b) => parseInt(a) - parseInt(b));
  }, [students]);

  const [selectedLevel, setSelectedLevel] = useState<string>(availableLevels[0] || '');
  const [selectedDept, setSelectedDept] = useState<string>(availableDepts[0] || '');
  const [selectedRoom, setSelectedRoom] = useState<string>(availableRooms[0] || '');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    if (!availableLevels.includes(selectedLevel)) setSelectedLevel(availableLevels[0] || '');
    if (!availableDepts.includes(selectedDept)) setSelectedDept(availableDepts[0] || '');
    if (!availableRooms.includes(selectedRoom)) setSelectedRoom(availableRooms[0] || '');
  }, [availableLevels, availableDepts, availableRooms, selectedLevel, selectedDept, selectedRoom]);

  const activeBlocks = useMemo(() => studyBlocks.filter(b => b.isActive && b.startDate && b.endDate), [studyBlocks]);

  const calculateScore = (studentId: string) => {
    if (activeBlocks.length === 0) return { score: 0, actualDays: 0, holidayDays: 0, totalDays: 0 };

    const actualPresentDays = attendance.filter(a => 
      a.studentId === studentId && 
      a.type === 'MORNING' && 
      a.status === 'PRESENT' &&
      activeBlocks.some(block => a.date >= block.startDate && a.date <= block.endDate)
    ).length;

    const holidayDays = activeBlocks.reduce((acc, block) => acc + (Array.isArray(block.holidays) ? block.holidays.length : 0), 0);
    const totalDays = actualPresentDays + holidayDays;
    const rawScore = (totalDays * 5) / 18;
    const finalScore = Math.min(5, rawScore);

    return { 
      score: finalScore, 
      actualDays: actualPresentDays,
      holidayDays: holidayDays,
      totalDays: totalDays
    };
  };

  const filteredStudents = useMemo(() => {
    return students.filter(s => 
      s.level === selectedLevel && 
      s.department === selectedDept && 
      s.room === selectedRoom &&
      (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm))
    );
  }, [students, selectedLevel, selectedDept, selectedRoom, searchTerm]);

  const roomAverage = useMemo(() => {
    if (filteredStudents.length === 0) return "0.00";
    const totalScore = filteredStudents.reduce((acc, s) => acc + calculateScore(s.id).score, 0);
    return (totalScore / filteredStudents.length).toFixed(2);
  }, [filteredStudents, activeBlocks, attendance]);

  const exportCSV = () => {
    let csv = "data:text/csv;charset=utf-8,\uFEFF";
    csv += "รหัสนักเรียน,ชื่อ-นามสกุล,ระดับชั้น,แผนกวิชา,ห้อง,มาเรียนจริง,วันหยุดพิเศษ,รวมวันมาเรียน,คะแนนเข้าแถว(5.0)\n";
    filteredStudents.forEach(s => {
      const result = calculateScore(s.id);
      csv += `${s.studentId},${s.name},${s.level},${s.department},${s.room},${result.actualDays},${result.holidayDays},${result.totalDays},${result.score.toFixed(2)}\n`;
    });
    const encodedUri = encodeURI(csv);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `สรุปคะแนนเข้าแถว_${selectedLevel}_${selectedDept}_ห้อง${selectedRoom}.csv`);
    link.click();
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
      {/* Header Stat Section */}
      <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-8 mb-10">
          <div className="flex items-center gap-6">
            <div className="p-5 bg-amber-500 rounded-[24px] text-white shadow-xl shadow-amber-100">
              <Star size={32} />
            </div>
            <div>
              <h2 className="text-3xl font-black text-slate-900 tracking-tight font-heading">สรุปคะแนนเข้าแถวรายห้อง</h2>
              <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">เกณฑ์การคำนวณ: ((มาเรียนจริง + วันหยุดพิเศษ) * 5) / 18 วัน</p>
            </div>
          </div>
          <div className="flex items-center gap-4 w-full xl:w-auto">
            <div className="bg-slate-900 p-6 rounded-[32px] text-white shadow-2xl flex-1 xl:flex-none flex items-center gap-6">
               <div className="text-right border-r border-slate-700 pr-6">
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">คะแนนเฉลี่ยห้อง</p>
                 <p className="text-4xl font-black font-heading text-amber-400">{roomAverage}</p>
               </div>
               <div className="text-left">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">สถานะบล็อกเรียน</p>
                  <p className="text-sm font-bold">{activeBlocks.length > 0 ? activeBlocks.map(b => b.name).join(', ') : 'ไม่มีบล็อกที่เปิดใช้งาน'}</p>
               </div>
            </div>
            <button 
              onClick={exportCSV}
              className="p-6 bg-white border border-slate-200 rounded-[32px] text-slate-900 hover:bg-slate-50 transition-all shadow-sm flex flex-col items-center justify-center gap-1 group"
            >
              <Download size={24} className="group-hover:scale-110 transition-transform" />
              <span className="text-[10px] font-black uppercase tracking-widest">CSV</span>
            </button>
          </div>
        </div>

        {/* Filter Section */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 pt-8 border-t border-slate-50">
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ระดับชั้น</label>
            <select value={selectedLevel} onChange={(e) => setSelectedLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none transition-all appearance-none">
              {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">แผนกวิชา</label>
            <select value={selectedDept} onChange={(e) => setSelectedDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none transition-all appearance-none">
              {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ห้องเรียน</label>
            <select value={selectedRoom} onChange={(e) => setSelectedRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none transition-all appearance-none">
              {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ค้นหารายชื่อ</label>
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="ชื่อ หรือ รหัส..." className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl pl-12 pr-4 py-3.5 font-bold text-slate-900 outline-none transition-all shadow-inner" />
            </div>
          </div>
        </div>
      </div>

      {/* Main Table Section */}
      <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-8 border-b bg-slate-50/50 flex items-center justify-between">
          <h3 className="text-xl font-bold text-slate-900 flex items-center gap-3 font-heading">
            <TrendingUp size={24} className="text-blue-600" />
            ตารางสรุปคะแนนนักเรียน ({filteredStudents.length} คน)
          </h3>
          <div className="flex items-center gap-3">
             <div className="flex items-center gap-2 px-4 py-2 bg-green-50 text-green-700 rounded-xl text-[10px] font-black uppercase border border-green-100">
                <CheckCircle2 size={14} /> ผ่านเกณฑ์ (4.0+)
             </div>
             <div className="flex items-center gap-2 px-4 py-2 bg-amber-50 text-amber-700 rounded-xl text-[10px] font-black uppercase border border-amber-100">
                <AlertCircle size={14} /> เฝ้าระวัง
             </div>
          </div>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50/50">
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">นักเรียน</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">มาเรียนจริง</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">วันหยุดพิเศษ</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">รวมวันมาเรียน</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">คะแนน (5.0)</th>
                <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">รายละเอียด</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStudents.length > 0 ? filteredStudents.map((s) => {
                const result = calculateScore(s.id);
                const scoreColor = result.score >= 4 ? 'text-green-600' : result.score >= 3 ? 'text-amber-600' : 'text-red-600';
                return (
                  <tr key={s.id} className="hover:bg-slate-50 transition-colors group">
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-4">
                         <div className="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-400 font-bold group-hover:bg-blue-600 group-hover:text-white transition-all">
                           <User size={18} />
                         </div>
                         <div>
                           <p className="font-bold text-slate-900 text-sm leading-tight">{s.name}</p>
                           <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-0.5">{s.studentId}</p>
                         </div>
                      </div>
                    </td>
                    <td className="px-8 py-6 font-bold text-slate-900">{result.actualDays} วัน</td>
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-1.5 text-amber-600 font-bold text-sm">
                        <Sun size={14} /> {result.holidayDays} วัน
                      </div>
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-3">
                         <div className="flex-1 h-1.5 bg-slate-100 rounded-full w-20 overflow-hidden">
                           <div 
                            className="h-full bg-blue-600 rounded-full transition-all duration-500" 
                            style={{ width: `${Math.min(100, (result.totalDays / 18) * 100)}%` }} 
                           />
                         </div>
                         <span className="text-sm font-black text-slate-900">{result.totalDays}</span>
                      </div>
