              <Star size={32} />
            </div>
            <div>
              <h2 className="text-3xl font-black text-slate-900 tracking-tight font-heading">สรุปคะแนนเข้าแถวรายห้อง</h2>
              <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">เกณฑ์การคำนวณ: ((มาเรียนจริง + วันหยุดพิเศษ) * 5) / 18 วัน</p>
            </div>
          </div>
          <div className="flex items-center gap-4 w-full xl:w-auto">
            <div className="bg-slate-900 p-6 rounded-[32px] text-white shadow-2xl flex-1 xl:flex-none flex items-center gap-6">
               <div className="text-right border-r border-slate-700 pr-6">
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">คะแนนเฉลี่ยห้อง</p>
                 <p className="text-4xl font-black font-heading text-amber-400">{roomAverage}</p>
               </div>
               <div className="text-left">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">สถานะบล็อกเรียน</p>
                  <p className="text-sm font-bold">{activeBlocks.length > 0 ? activeBlocks.map(b => b.name).join(', ') : 'ไม่มีบล็อกที่เปิดใช้งาน'}</p>
               </div>
            </div>
            <button 
              onClick={exportCSV}
