  const shareToLine = () => {
    if (filteredStudents.length === 0) return;
    const emojiMap: Record<string, string> = { PRESENT: '✅', LATE: '⏰', ABSENT: '❌', BUSINESS_LEAVE: '📝', SICK_LEAVE: '🤒' };
