          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {filteredStudents.map((student, index) => (
              <div key={student.id} className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm hover:border-blue-300 transition-all group">
                <div className="flex items-start justify-between gap-5">
                  <div className="flex items-start gap-4">
                    <div className="w-14 h-14 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-lg group-hover:bg-blue-600 transition-colors shrink-0">{index + 1}</div>
                    <div>
                      <h4 className="font-black text-slate-900 text-xl leading-tight">{student.name}</h4>
                      <p className="text-xs text-slate-500 font-extrabold uppercase mt-1.5 tracking-widest">รหัส: {student.studentId}</p>
                    </div>
                  </div>
                  <div className="grid grid-cols-5 gap-2">
                    {Object.entries(STATUS_LABELS).map(([key, value]) => (
                      <button key={key} onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} className={`flex flex-col items-center gap-1.5 p-2 rounded-xl border-2 transition-all ${currentSession[student.id] === key ? value.color + ' border-current scale-105' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-300'}`}>
                        <div className="scale-125">{value.icon}</div>
                        <span className="text-[10px] font-black uppercase text-center">{value.label}</span>
                      </button>
                    ))}
