                </div>
                {currentSession[student.id] && currentSession[student.id] !== 'PRESENT' && (
                  <div className="mt-4 relative">
                    <MessageSquare className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <input type="text" value={remarks[student.id] || ''} onChange={(e) => setRemarks(prev => ({ ...prev, [student.id]: e.target.value }))} placeholder="ระบุหมายเหตุ..." className="w-full bg-slate-50 border-2 border-slate-200 rounded-xl pl-11 pr-4 py-3 font-bold text-slate-900 outline-none text-sm" />
