    return Array.from(new Set(students.map(s => s.level))).sort();
  }, [students]);

  const availableDepts = useMemo<string[]>(() => {
    return Array.from(new Set(students.map(s => s.department))).sort();
  }, [students]);

  const availableRooms = useMemo<string[]>(() => {
    return Array.from(new Set(students.map(s => s.room))).sort((a, b) => parseInt(a as string) - parseInt(b as string));
  }, [students]);

  const [selectedLevel, setSelectedLevel] = useState<string>(availableLevels[0] || '');
  const [selectedDept, setSelectedDept] = useState<string>(availableDepts[0] || '');
  const [selectedRoom, setSelectedRoom] = useState<string>(availableRooms[0] || '');
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    if (availableLevels.length > 0 && !selectedLevel) setSelectedLevel(availableLevels[0]);
    if (availableDepts.length > 0 && !selectedDept) setSelectedDept(availableDepts[0]);
    if (availableRooms.length > 0 && !selectedRoom) setSelectedRoom(availableRooms[0]);
  }, [availableLevels, availableDepts, availableRooms]);

  const activeBlocks = useMemo(() => studyBlocks.filter(b => b.isActive && b.startDate && b.endDate), [studyBlocks]);

  // ฟังก์ชันคำนวณคะแนนโดยดึงข้อมูลจาก attendance records จริง
  const calculateScore = (studentId: string) => {
    if (activeBlocks.length === 0) return { score: 0, actualDays: 0, holidayDays: 0, totalDays: 0 };

    // ดึงข้อมูลการเช็คชื่อเข้าแถว (MORNING) ของนักเรียนคนนี้ เฉพาะวันที่อยู่ในช่วงของ Active Blocks
    const studentMorningRecords = attendance.filter(a => 
      a.studentId === studentId && 
      a.type === 'MORNING' && 
      a.status === 'PRESENT' &&
      activeBlocks.some(block => {
        const recordDate = a.date; // รูปแบบ YYYY-MM-DD
        return recordDate >= block.startDate && recordDate <= block.endDate;
      })
    );

    // นับจำนวนวันที่เช็คชื่อว่า "มาเรียน (PRESENT)"
    const actualPresentDays = studentMorningRecords.length;

    // นับจำนวนวันหยุดพิเศษที่ครูตั้งค่าไว้ในบล็อกนั้นๆ
    const holidayDays = activeBlocks.reduce((acc, block) => acc + (Array.isArray(block.holidays) ? block.holidays.length : 0), 0);

    // รวมวันมาเรียนจริง + วันหยุดพิเศษ
    const totalDays = actualPresentDays + holidayDays;

    // คำนวณตามเกณฑ์: (วันรวม * 5 คะแนนเต็ม) / ฐาน 18 วัน
    const rawScore = (totalDays * 5) / 18;
    const finalScore = Math.min(5, rawScore); // คะแนนสูงสุดไม่เกิน 5.0

    return { 
      score: finalScore, 
      actualDays: actualPresentDays,
      holidayDays: holidayDays,
      totalDays: totalDays
    };
  };

  const filteredStudents = useMemo(() => {
    return students.filter(s => 
      s.level === selectedLevel && 
      s.department === selectedDept && 
      s.room === selectedRoom &&
      (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm))
    );
  }, [students, selectedLevel, selectedDept, selectedRoom, searchTerm]);

  const roomAverage = useMemo(() => {
    if (filteredStudents.length === 0) return "0.00";
    const totalScore = filteredStudents.reduce((acc, s) => acc + calculateScore(s.id).score, 0);
    return (totalScore / filteredStudents.length).toFixed(2);
  }, [filteredStudents, activeBlocks, attendance]);

  const exportCSV = () => {
    let csv = "data:text/csv;charset=utf-8,\uFEFF";
    csv += "รหัสนักเรียน,ชื่อ-นามสกุล,ระดับชั้น,แผนกวิชา,ห้อง,มาเรียนจริง,วันหยุดพิเศษ,รวมวันมาเรียน,คะแนนเข้าแถว(5.0)\n";
    filteredStudents.forEach(s => {
      const result = calculateScore(s.id);
      csv += `${s.studentId},${s.name},${s.level},${s.department},${s.room},${result.actualDays},${result.holidayDays},${result.totalDays},${result.score.toFixed(2)}\n`;
    });
    const encodedUri = encodeURI(csv);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `สรุปคะแนนเข้าแถว_${selectedLevel}_${selectedDept}_ห้อง${selectedRoom}.csv`);
    link.click();
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-8 mb-10">
          <div className="flex items-center gap-6">
            <div className="p-5 bg-amber-500 rounded-[24px] text-white shadow-xl shadow-amber-100">
              <Star size={32} />
            </div>
            <div>
              <h2 className="text-3xl font-black text-slate-900 tracking-tight font-heading">สรุปคะแนนเข้าแถวรายห้อง</h2>
              <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">เกณฑ์: ((มาเรียนจริง + วันหยุดพิเศษ) * 5) / 18 วัน</p>
            </div>
          </div>
          <div className="flex items-center gap-4 w-full xl:w-auto">
            <div className="bg-slate-900 p-6 rounded-[32px] text-white shadow-2xl flex-1 xl:flex-none flex items-center gap-6">
               <div className="text-right border-r border-slate-700 pr-6">
                 <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">เฉลี่ยรายห้อง</p>
                 <p className="text-4xl font-black font-heading text-amber-400">{roomAverage}</p>
               </div>
               <div className="text-left">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">บล็อกที่ใช้คำนวณ</p>
                  <p className="text-sm font-bold">{activeBlocks.length > 0 ? activeBlocks.map(b => b.name).join(', ') : 'ไม่ได้ตั้งค่าบล็อก'}</p>
               </div>
            </div>
            <button 
              onClick={exportCSV}
              className="p-6 bg-white border border-slate-200 rounded-[32px] text-slate-900 hover:bg-slate-50 transition-all shadow-sm flex flex-col items-center justify-center gap-1 group"
            >
              <Download size={24} className="group-hover:scale-110 transition-transform" />
              <span className="text-[10px] font-black uppercase tracking-widest">Excel</span>
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 pt-8 border-t border-slate-50">
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ระดับชั้น</label>
            <select value={selectedLevel} onChange={(e) => setSelectedLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none appearance-none">
              {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">แผนกวิชา</label>
            <select value={selectedDept} onChange={(e) => setSelectedDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none appearance-none">
              {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ห้องเรียน</label>
            <select value={selectedRoom} onChange={(e) => setSelectedRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none appearance-none">
              {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ค้นหารายชื่อ</label>
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="ชื่อ หรือ รหัส..." className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl pl-12 pr-4 py-3.5 font-bold text-slate-900 outline-none shadow-inner" />
            </div>
          </div>
        </div>
