                         </div>
                      </div>
                    </td>
                    <td className="px-8 py-6 font-bold text-slate-900">{result.actualDays} วัน</td>
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-1.5 text-amber-600 font-bold text-sm">
                        <Sun size={14} /> {result.holidayDays} วัน
                      </div>
                    </td>
                    <td className="px-8 py-6">
                      <div className="flex items-center gap-3">
                         <div className="flex-1 h-1.5 bg-slate-100 rounded-full w-20 overflow-hidden">
                           <div 
                            className="h-full bg-blue-600 rounded-full transition-all duration-500" 
                            style={{ width: `${Math.min(100, (result.totalDays / 18) * 100)}%` }} 
                           />
                         </div>
                         <span className="text-sm font-black text-slate-900">{result.totalDays}</span>
                      </div>
                    </td>
                    <td className="px-8 py-6">
                      <span className={`text-2xl font-black font-heading ${scoreColor}`}>
                        {result.score.toFixed(2)}
                      </span>
                    </td>
                  </tr>
                );
              }) : (
                <tr>
                  <td colSpan={5} className="py-24 text-center">
                    <div className="flex flex-col items-center opacity-20">
                      <Search size={64} className="mb-4" />
                      <p className="text-xl font-black text-slate-900">ไม่พบข้อมูลนักเรียน</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

