                    <input type="text" required value={formData.studentId} onChange={(e) => setFormData({...formData, studentId: e.target.value})} className="w-full bg-pink-50 border-2 border-pink-100 focus:ring-pink-500 rounded-2xl pl-12 pr-5 py-4 font-black text-slate-900 outline-none" placeholder="เช่น 661001" />
