import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import MorningAttendance from './components/MorningAttendance';
import ClassAttendance from './components/ClassAttendance';
import BehaviorSystem from './components/BehaviorSystem';
import StudentManagement from './components/StudentManagement';
import Reports from './components/Reports';
import UserManagement from './components/UserManagement';
import SystemSettings from './components/SystemSettings';
import MorningScoreSummary from './components/MorningScoreSummary';
import TuitionSystem from './components/TuitionSystem';
import Login from './components/Login';
import { MOCK_STUDENTS, MOCK_ATTENDANCE, MOCK_BEHAVIOR, MOCK_SUBJECTS } from './data/mockData';
import { Student, AttendanceRecord, BehaviorRecord, Subject, User, StudyBlock, TuitionConfig, PaymentRecord } from './types';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeMenu, setActiveMenu] = useState('dashboard');
  const [isInitialLoaded, setIsInitialLoaded] = useState(false);

  // Central States
  const [students, setStudents] = useState<Student[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [behaviorRecords, setBehaviorRecords] = useState<BehaviorRecord[]>([]);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);
  const [systemUsers, setSystemUsers] = useState<User[]>([]);
  const [tuitionConfigs, setTuitionConfigs] = useState<TuitionConfig[]>([]);
  const [paymentRecords, setPaymentRecords] = useState<PaymentRecord[]>([]);

  const [studyBlocks, setStudyBlocks] = useState<StudyBlock[]>([
    { id: 1, name: 'บล็อกที่ 1', startDate: '2024-03-01', endDate: '2024-03-25', isActive: true, holidays: [] },
    { id: 2, name: 'บล็อกที่ 2', startDate: '', endDate: '', isActive: false, holidays: [] },
    { id: 3, name: 'บล็อกที่ 3', startDate: '', endDate: '', isActive: false, holidays: [] },
    { id: 4, name: 'บล็อกที่ 4', startDate: '', endDate: '', isActive: false, holidays: [] },
    { id: 5, name: 'บล็อกที่ 5', startDate: '', endDate: '', isActive: false, holidays: [] },
  ]);

  // Initial Data Load from LocalStorage
  useEffect(() => {
    try {
      const load = (key: string) => localStorage.getItem(key);

      const savedStudents = load('cms_students');
      const savedAttendance = load('cms_attendance');
      const savedBehavior = load('cms_behavior');
      const savedSubjects = load('cms_subjects');
      const savedRooms = load('cms_rooms');
      const savedUsers = load('cms_system_users');
      const savedBlocks = load('cms_study_blocks');
      const savedTuition = load('cms_tuition_configs');
      const savedPayments = load('cms_payment_records');

      if (savedStudents) setStudents(JSON.parse(savedStudents));
      else setStudents(MOCK_STUDENTS);

      if (savedAttendance) setAttendance(JSON.parse(savedAttendance));
      else setAttendance(MOCK_ATTENDANCE);

      if (savedBehavior) setBehaviorRecords(JSON.parse(savedBehavior));
      else setBehaviorRecords(MOCK_BEHAVIOR);

      if (savedSubjects) setSubjects(JSON.parse(savedSubjects));
      else setSubjects(MOCK_SUBJECTS);

      if (savedRooms) setRooms(JSON.parse(savedRooms));
      if (savedTuition) setTuitionConfigs(JSON.parse(savedTuition));
      if (savedPayments) setPaymentRecords(JSON.parse(savedPayments));

      if (savedUsers) {
        setSystemUsers(JSON.parse(savedUsers));
      } else {
        setSystemUsers([
          { id: 'T1', name: 'อ.สมพงษ์ ใจสว่าง', role: 'TEACHER', username: 'teacher', password: '1234', department: 'เทคโนโลยีสารสนเทศ' },
          { id: 'A1', name: 'แอดมิน ระบบ', role: 'ADMIN', username: 'admin', password: '1234', department: 'ส่วนกลาง' },
          { id: 'F1', name: 'การเงิน สถานศึกษา', role: 'FINANCE', username: 'finance', password: '1234', department: 'ฝ่ายการเงิน' },
          { id: 'P1', name: 'คุณแม่ มณี', role: 'PARENT', username: 'parent', password: '1234', studentId: '661001' }
        ]);
      }

      if (savedBlocks) setStudyBlocks(JSON.parse(savedBlocks));

    } catch (error) {
      console.error("Critical error during data initialization:", error);
    } finally {
      setIsInitialLoaded(true);
    }
  }, []);

  // Persist State to LocalStorage on every change
  useEffect(() => {
    if (isInitialLoaded) {
      const save = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));
      save('cms_students', students);
      save('cms_attendance', attendance);
      save('cms_behavior', behaviorRecords);
      save('cms_subjects', subjects);
      save('cms_rooms', rooms);
      save('cms_system_users', systemUsers);
      save('cms_study_blocks', studyBlocks);
      save('cms_tuition_configs', tuitionConfigs);
      save('cms_payment_records', paymentRecords);
    }
  }, [students, attendance, behaviorRecords, subjects, rooms, systemUsers, studyBlocks, tuitionConfigs, paymentRecords, isInitialLoaded]);

  if (!user) {
    return <Login onLogin={setUser} systemUsers={systemUsers} />;
  }

  const renderContent = () => {
    switch (activeMenu) {
      case 'dashboard':
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} tuitionConfigs={tuitionConfigs} paymentRecords={paymentRecords} />;
      case 'students':
        return <StudentManagement students={students} setStudents={setStudents} />;
      case 'morning':
        return <MorningAttendance students={students} setStudents={setStudents} attendanceRecords={attendance} setAttendanceRecords={setAttendance} rooms={rooms} setRooms={setRooms} />;
      case 'subject':
        return <ClassAttendance students={students} setStudents={setStudents} subjects={subjects} setSubjects={setSubjects} rooms={rooms} setRooms={setRooms} attendanceRecords={attendance} setAttendanceRecords={setAttendance} currentUser={user} />;
      case 'behavior':
        return <BehaviorSystem students={students} setStudents={setStudents} behaviorRecords={behaviorRecords} setBehaviorRecords={setBehaviorRecords} />;
      case 'tuition':
      case 'finance_report':
        return <TuitionSystem students={students} tuitionConfigs={tuitionConfigs} setTuitionConfigs={setTuitionConfigs} paymentRecords={paymentRecords} setPaymentRecords={setPaymentRecords} user={user} />;
      case 'report':
        return <Reports students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
      case 'morning_scores':
        return <MorningScoreSummary students={students} attendance={attendance} studyBlocks={studyBlocks} />;
      case 'users':
        return <UserManagement users={systemUsers} setUsers={setSystemUsers} currentUser={user} students={students} />;
      case 'settings':
        return <SystemSettings studyBlocks={studyBlocks} setStudyBlocks={setStudyBlocks} />;
      default:
        return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} tuitionConfigs={tuitionConfigs} paymentRecords={paymentRecords} />;
    }
  };

  return (
    <Layout activeMenu={activeMenu} setActiveMenu={setActiveMenu} user={user} onLogout={() => setUser(null)}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { Student, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { 
  Search, Save, CheckCircle2, History, ClipboardCheck, 
  MessageSquare, Share2
} from 'lucide-react';

interface MorningAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
}

const MorningAttendance: React.FC<MorningAttendanceProps> = ({ 
  students, 
  attendanceRecords, 
  setAttendanceRecords
}) => {
  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);
  const availableRooms = useMemo(() => Array.from(new Set(students.map(s => s.room))).sort((a, b) => parseInt(a) - parseInt(b)), [students]);

  const [level, setLevel] = useState<string>(availableLevels[0] || '');
  const [dept, setDept] = useState<string>(availableDepts[0] || '');
  const [room, setRoom] = useState<string>(availableRooms[0] || '');

  const [searchTerm, setSearchTerm] = useState('');
  const [currentSession, setCurrentSession] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');

  const todayStr = new Date().toISOString().split('T')[0];

  // Load existing data for the day when filters change
  useEffect(() => {
    const todayRecords = attendanceRecords.filter(r => r.date === todayStr && r.type === 'MORNING');
    const sessionMap: Record<string, AttendanceStatus> = {};
    const remarkMap: Record<string, string> = {};

    todayRecords.forEach(r => {
      sessionMap[r.studentId] = r.status;
      if (r.remark) remarkMap[r.studentId] = r.remark;
    });

    setCurrentSession(sessionMap);
    setRemarks(remarkMap);
  }, [level, dept, room, attendanceRecords, todayStr]);

  const filteredStudents = students.filter(s => 
    s.level === level && s.department === dept && s.room === room &&
    (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm))
  );

  const historyRecords = useMemo(() => {
    return attendanceRecords.filter(record => {
      const student = students.find(s => s.id === record.studentId);
      return record.type === 'MORNING' && student?.level === level && student?.department === dept && student?.room === room;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [attendanceRecords, students, level, dept, room]);

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setCurrentSession(prev => ({ ...prev, [studentId]: status }));
    setIsSaved(false);
  };

  const handleSave = () => {
    const timestamp = new Date().toLocaleString('th-TH');

    const newRecordsBatch: AttendanceRecord[] = filteredStudents.map(s => ({
      id: `MORNING_${todayStr}_${s.id}`,
      studentId: s.id,
      date: todayStr,
      type: 'MORNING',
      status: currentSession[s.id] || 'ABSENT',
      remark: remarks[s.id] || '',
      timestamp: timestamp
    }));

    setAttendanceRecords(prev => {
      const studentIds = filteredStudents.map(s => s.id);
      const otherRecords = prev.filter(r => !(r.date === todayStr && r.type === 'MORNING' && studentIds.includes(r.studentId)));
      return [...otherRecords, ...newRecordsBatch];
    });

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setCurrentSession(prev => ({ ...prev, ...newBatch }));
  };

  const shareToLine = () => {
    if (filteredStudents.length === 0) return;
    const emojiMap: Record<string, string> = { PRESENT: '✅', LATE: '⏰', ABSENT: '❌', BUSINESS_LEAVE: '📝', SICK_LEAVE: '🤒' };
    const studentRows = filteredStudents.map((s, idx) => `${idx + 1}. ${s.name} [${emojiMap[currentSession[s.id] || 'ABSENT']}]`);
    let message = `📊 เช็คชื่อเข้าแถว (${todayStr})\n🏫 ห้อง: ${level} ${dept}/${room}\n` + studentRows.join('\n');
    window.open(`https://line.me/R/msg/text/?${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex bg-white p-2 rounded-2xl border border-slate-200 shadow-sm w-fit">
        <button onClick={() => setViewMode('checkin')} className={`flex items-center gap-2 px-8 py-3.5 rounded-xl text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><ClipboardCheck size={20} /> เช็คชื่อวันนี้</button>
        <button onClick={() => setViewMode('history')} className={`flex items-center gap-2 px-8 py-3.5 rounded-xl text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><History size={20} /> ประวัติย้อนหลัง</button>
      </div>

      <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ระดับชั้น</label>
            <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none transition-all">
              {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">แผนกวิชา</label>
            <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none transition-all">
              {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ห้องเรียน</label>
            <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none transition-all">
              {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ค้นหารายชื่อ</label>
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อ-รหัส..." className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl pl-12 pr-4 py-3 font-bold text-slate-900 outline-none" />
            </div>
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <>
          <div className="flex flex-wrap items-center justify-between gap-6 px-2">
            <div className="flex gap-3">
              <button onClick={() => markAll('PRESENT')} className="px-5 py-2 bg-green-50 text-green-700 rounded-full text-xs font-black border-2 border-green-100 transition-all">มาทุกคน</button>
              <button onClick={() => markAll('ABSENT')} className="px-5 py-2 bg-red-50 text-red-700 rounded-full text-xs font-black border-2 border-red-200 transition-all">ขาดทุกคน</button>
            </div>
            <div className="flex items-center gap-4">
              <button onClick={shareToLine} className="flex items-center gap-2 px-6 py-4 bg-[#06C755] hover:bg-[#05b14c] text-white rounded-2xl font-black transition-all shadow-lg"><Share2 size={20} /> แชร์ LINE</button>
              <button onClick={handleSave} className={`flex items-center gap-3 px-10 py-4 rounded-2xl text-white font-black transition-all shadow-xl ${isSaved ? 'bg-green-600' : 'bg-slate-900'}`}>
                {isSaved ? <CheckCircle2 size={24} /> : <Save size={24} />} 
                <span className="text-lg">{isSaved ? 'บันทึกแล้ว' : 'บันทึกข้อมูลวันนี้'}</span>
              </button>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {filteredStudents.map((student, index) => (
              <div key={student.id} className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm hover:border-blue-300 transition-all group">
                <div className="flex items-start justify-between gap-5">
                  <div className="flex items-start gap-4">
                    <div className="w-14 h-14 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-lg shrink-0">{index + 1}</div>
                    <div>
                      <h4 className="font-black text-slate-900 text-xl leading-tight">{student.name}</h4>
                      <p className="text-[10px] text-slate-500 font-bold uppercase mt-1">รหัส: {student.studentId}</p>
                    </div>
                  </div>
                  <div className="grid grid-cols-5 gap-1.5">
                    {Object.entries(STATUS_LABELS).map(([key, value]) => (
                      <button key={key} onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} className={`flex flex-col items-center gap-1.5 p-2 rounded-xl border-2 transition-all ${currentSession[student.id] === key ? value.color + ' border-current' : 'bg-white border-slate-100 text-slate-400'}`}>
                        <div className="scale-110">{value.icon}</div>
                        <span className="text-[8px] font-black uppercase">{value.label}</span>
                      </button>
                    ))}
                  </div>
                </div>
                {currentSession[student.id] && currentSession[student.id] !== 'PRESENT' && (
                  <div className="mt-4 relative">
                    <MessageSquare className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <input type="text" value={remarks[student.id] || ''} onChange={(e) => setRemarks(prev => ({ ...prev, [student.id]: e.target.value }))} placeholder="ระบุหมายเหตุ..." className="w-full bg-slate-50 border-2 border-slate-100 rounded-xl pl-11 pr-4 py-3 font-bold text-slate-900 outline-none text-sm" />
                  </div>
                )}
              </div>
            ))}
          </div>
        </>
      ) : (
        <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 border-b">
                <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase">วันที่</th>
                <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase">นักเรียน</th>
                <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase">สถานะ</th>
                <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase text-right">หมายเหตุ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {historyRecords.map((record) => {
                const student = students.find(s => s.id === record.studentId);
                return (
                  <tr key={record.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-10 py-6 font-bold text-slate-900">{record.date}</td>
                    <td className="px-10 py-6">
                      <p className="font-bold text-slate-900">{student?.name}</p>
                      <p className="text-xs text-slate-500">{student?.studentId}</p>
                    </td>
                    <td className="px-10 py-6">
                      <span className={`px-4 py-1.5 rounded-full text-xs font-bold border ${STATUS_LABELS[record.status].color}`}>
                        {STATUS_LABELS[record.status].label}
                      </span>
                    </td>
                    <td className="px-10 py-6 text-sm font-bold text-slate-900 text-right">{record.remark || '-'}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default MorningAttendance;

import React, { useState, useRef, useMemo } from 'react';
