  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState<'ADD' | 'EDIT' | null>(null);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);

  const availableDepts = useMemo(() => {
    const depts = new Set(students.map(s => s.department));
    Object.values(Department).forEach(d => depts.add(d));
    return Array.from(depts).sort();
  }, [students]);

  const [formData, setFormData] = useState<Partial<User>>({
    name: '',
    role: 'TEACHER',
    department: availableDepts[0] || '',
    studentId: '',
    username: '',
    password: ''
  });

  const filteredUsers = users.filter(u => 
    u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    u.username.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const resetForm = () => {
    setFormData({ name: '', role: 'TEACHER', department: availableDepts[0] || '', studentId: '', username: '', password: '' });
    setEditingUserId(null);
  };

