    e.preventDefault();
    if (showModal === 'ADD') {
      const newUser = { id: `USR_${Date.now()}`, ...formData } as User;
      setUsers(prev => [...prev, newUser]);
    } else if (showModal === 'EDIT' && editingUserId) {
      setUsers(prev => prev.map(u => u.id === editingUserId ? { ...u, ...formData } as User : u));
    }
    setShowModal(null);
    resetForm();
  };

  const deleteUser = (e: React.MouseEvent, user: User) => {
    e.preventDefault();
    e.stopPropagation();

    if (currentUser && user.id === currentUser.id) {
      alert('ไม่สามารถลบบัญชีที่คุณกำลังใช้งานได้');
      return;
    }

    if (window.confirm(`คุณต้องการลบผู้ใช้ ${user.name} หรือไม่?`)) {
