              <p className="text-sm font-bold text-slate-500">ควบคุมสิทธิ์และข้อมูลการเข้าใช้งาน</p>
            </div>
          </div>
          <div className="flex items-center gap-4 w-full md:w-auto">
            <div className="relative flex-1 md:w-80">
              <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
              <input type="text" placeholder="ค้นหาชื่อ หรือ Username..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white border-2 border-slate-100 rounded-2xl pl-14 pr-6 py-4 text-sm font-bold text-slate-900 outline-none focus:border-indigo-500 transition-all" />
            </div>
            <button onClick={() => { resetForm(); setShowModal('ADD'); }} className="px-8 py-4 bg-indigo-600 text-white rounded-2xl text-sm font-black flex items-center gap-3 shadow-lg hover:bg-indigo-700 transition-all">
              <UserPlus size={20} /> เพิ่มผู้ใช้
            </button>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white border-b">
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">ข้อมูลพื้นฐาน</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">ชื่อผู้ใช้ / รหัสผ่าน</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">สิทธิ์ / สังกัด</th>
