                  <td className="px-10 py-7">
                    <div className="flex items-center gap-4">
                      <div className={`w-12 h-12 rounded-xl flex items-center justify-center font-black text-white ${u.role === 'ADMIN' ? 'bg-indigo-600' : 'bg-slate-800'}`}>{u.name.charAt(0)}</div>
                      <div>
