                        <p className="text-[10px] text-slate-400 uppercase tracking-widest">{u.id}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-10 py-7">
                    <p className="text-sm font-black text-slate-900 flex items-center gap-2"><Key size={14} className="text-blue-500" /> {u.username}</p>
                    <p className="text-xs font-mono text-slate-400 mt-1">••••••••</p>
                  </td>
                  <td className="px-10 py-7">
                    <span className={`px-3 py-1 rounded-lg text-[9px] font-black border uppercase tracking-widest ${u.role === 'ADMIN' ? 'bg-indigo-50 text-indigo-700 border-indigo-100' : 'bg-slate-50 text-slate-700 border-slate-100'}`}>{u.role}</span>
