import React, { useState, useEffect, useCallback } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import MorningAttendance from './components/MorningAttendance';
import ClassAttendance from './components/ClassAttendance';
import BehaviorSystem from './components/BehaviorSystem';
import StudentManagement from './components/StudentManagement';
import Reports from './components/Reports';
import UserManagement from './components/UserManagement';
import SystemSettings from './components/SystemSettings';
import MorningScoreSummary from './components/MorningScoreSummary';
import TuitionSystem from './components/TuitionSystem';
import Login from './components/Login';
import { MOCK_STUDENTS, MOCK_ATTENDANCE, MOCK_BEHAVIOR, MOCK_SUBJECTS } from './data/mockData';
import { Student, AttendanceRecord, BehaviorRecord, Subject, User, StudyBlock, TuitionConfig, PaymentRecord } from './types';

// ใส่ URL จาก Google Apps Script ที่ Deploy ไว้
const GOOGLE_SHEET_API_URL = "YOUR_APPS_SCRIPT_WEB_APP_URL";

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeMenu, setActiveMenu] = useState('dashboard');
  const [isInitialLoaded, setIsInitialLoaded] = useState(false);

  // States
  const [students, setStudents] = useState<Student[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [behaviorRecords, setBehaviorRecords] = useState<BehaviorRecord[]>([]);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);
  const [systemUsers, setSystemUsers] = useState<User[]>([]);
  const [tuitionConfigs, setTuitionConfigs] = useState<TuitionConfig[]>([]);
  const [paymentRecords, setPaymentRecords] = useState<PaymentRecord[]>([]);
  const [studyBlocks, setStudyBlocks] = useState<StudyBlock[]>([]);

  // ฟังก์ชัน Sync ข้อมูลไป Google Sheets
  const syncToSheets = useCallback(async (payload: any) => {
    if (!GOOGLE_SHEET_API_URL || GOOGLE_SHEET_API_URL === "YOUR_APPS_SCRIPT_WEB_APP_URL") {
      console.warn("Google Sheet API URL is not set.");
      return;
    }
    try {
      // ใช้ no-cors เพราะ Apps Script ไม่รองรับ CORS สำหรับ POST ตรงๆ ในบางกรณี
      await fetch(GOOGLE_SHEET_API_URL, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      console.log(`Synced ${payload.type} to Google Sheets`);
    } catch (err) {
      console.error("Sheet Sync Error:", err);
    }
  }, []);

  // -- Wrapper Functions เพื่อดักจับเหตุการณ์และส่งข้อมูล --

  const handleSetStudents = (updater: any) => {
    setStudents(prev => {
      const next = typeof updater === 'function' ? updater(prev) : updater;
      if (next.length > prev.length) {
        // กรณีเพิ่มนักเรียนใหม่ (มักจะอยู่ตัวแรกหรือตัวสุดท้าย)
        const newStu = next.find((n: any) => !prev.some((p: any) => p.id === n.id));
        if (newStu) syncToSheets({ type: 'STUDENT', ...newStu });
      }
      return next;
    });
  };

  const handleSetAttendance = (updater: any) => {
    setAttendance(prev => {
      const next = typeof updater === 'function' ? updater(prev) : updater;
      const latestAdded = next.filter((n: any) => !prev.some((p: any) => p.id === n.id));
      latestAdded.forEach((rec: AttendanceRecord) => {
        const stu = students.find(s => s.id === rec.studentId);
        syncToSheets({
          type: rec.type === 'MORNING' ? 'ATTENDANCE_MORNING' : 'ATTENDANCE_SUBJECT',
          studentId: stu?.studentId,
          name: stu?.name,
          subjectId: rec.subjectId || '-',
          status: rec.status,
          remark: rec.remark || '-',
          recordedBy: user?.name || 'System'
        });
      });
      return next;
    });
  };

  const handleSetBehavior = (updater: any) => {
    setBehaviorRecords(prev => {
      const next = typeof updater === 'function' ? updater(prev) : updater;
      if (next.length > prev.length) {
        const rec = next[0]; // บันทึกใหม่มักถูก unshift เข้ามา
        const stu = students.find(s => s.id === rec.studentId);
        syncToSheets({
          type: 'BEHAVIOR',
          studentId: stu?.studentId,
          name: stu?.name,
          actionType: rec.type,
          score: rec.score,
          reason: rec.reason,
          recordedBy: rec.recordedBy
        });
      }
      return next;
    });
  };

  const handleSetPayments = (updater: any) => {
    setPaymentRecords(prev => {
      const next = typeof updater === 'function' ? updater(prev) : updater;
      if (next.length > prev.length) {
        const rec = next[next.length - 1]; // การเงินใหม่มักต่อท้าย
        const stu = students.find(s => s.id === rec.studentId);
        syncToSheets({
          type: 'PAYMENT',
          studentId: stu?.studentId,
          name: stu?.name,
          amount: rec.amount,
          method: rec.method,
          recordedBy: rec.recordedBy
        });
      }
      return next;
    });
  };

  const handleSetUsers = (updater: any) => {
    setSystemUsers(prev => {
      const next = typeof updater === 'function' ? updater(prev) : updater;
      if (next.length > prev.length) {
        const u = next[next.length - 1];
        syncToSheets({
          type: 'USER',
          username: u.username,
          name: u.name,
          role: u.role,
          department: u.department || '-'
        });
      }
      return next;
    });
  };

  // Initial Data Loading
  useEffect(() => {
    const load = (key: string) => localStorage.getItem(key);
    const savedStudents = load('cms_students');
    const savedAttendance = load('cms_attendance');
    const savedBehavior = load('cms_behavior');
    const savedSubjects = load('cms_subjects');
    const savedUsers = load('cms_system_users');
    const savedTuition = load('cms_tuition_configs');
    const savedPayments = load('cms_payment_records');
    const savedBlocks = load('cms_study_blocks');

    if (savedStudents) setStudents(JSON.parse(savedStudents)); else setStudents(MOCK_STUDENTS);
    if (savedAttendance) setAttendance(JSON.parse(savedAttendance)); else setAttendance(MOCK_ATTENDANCE);
    if (savedBehavior) setBehaviorRecords(JSON.parse(savedBehavior)); else setBehaviorRecords(MOCK_BEHAVIOR);
    if (savedSubjects) setSubjects(JSON.parse(savedSubjects)); else setSubjects(MOCK_SUBJECTS);
    if (savedTuition) setTuitionConfigs(JSON.parse(savedTuition));
    if (savedPayments) setPaymentRecords(JSON.parse(savedPayments));
    if (savedBlocks) setStudyBlocks(JSON.parse(savedBlocks)); else setStudyBlocks([
      { id: 1, name: 'บล็อกที่ 1', startDate: '2024-03-01', endDate: '2024-03-25', isActive: true, holidays: [] },
      { id: 2, name: 'บล็อกที่ 2', startDate: '', endDate: '', isActive: false, holidays: [] },
    ]);

    if (savedUsers) setSystemUsers(JSON.parse(savedUsers));
    else setSystemUsers([
      { id: 'A1', name: 'แอดมิน ระบบ', role: 'ADMIN', username: 'admin', password: '1234', department: 'ส่วนกลาง' },
      { id: 'T1', name: 'อ.สมพงษ์ ใจสว่าง', role: 'TEACHER', username: 'teacher', password: '1234', department: 'เทคโนโลยีสารสนเทศ' },
      { id: 'F1', name: 'ฝ่ายการเงิน', role: 'FINANCE', username: 'finance', password: '1234', department: 'ฝ่ายการเงิน' }
    ]);
    setIsInitialLoaded(true);
  }, []);

  // Save to LocalStorage
  useEffect(() => {
    if (isInitialLoaded) {
      const save = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));
      save('cms_students', students);
      save('cms_attendance', attendance);
      save('cms_behavior', behaviorRecords);
      save('cms_subjects', subjects);
      save('cms_system_users', systemUsers);
      save('cms_tuition_configs', tuitionConfigs);
      save('cms_payment_records', paymentRecords);
      save('cms_study_blocks', studyBlocks);
    }
  }, [students, attendance, behaviorRecords, subjects, systemUsers, tuitionConfigs, paymentRecords, studyBlocks, isInitialLoaded]);

  if (!user) return <Login onLogin={setUser} systemUsers={systemUsers} />;

  const renderContent = () => {
    switch (activeMenu) {
      case 'dashboard': return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} tuitionConfigs={tuitionConfigs} paymentRecords={paymentRecords} />;
      case 'students': return <StudentManagement students={students} setStudents={handleSetStudents} />;
      case 'morning': return <MorningAttendance students={students} setStudents={handleSetStudents} attendanceRecords={attendance} setAttendanceRecords={handleSetAttendance} rooms={rooms} setRooms={setRooms} />;
      case 'subject': return <ClassAttendance students={students} setStudents={handleSetStudents} subjects={subjects} setSubjects={setSubjects} rooms={rooms} setRooms={setRooms} attendanceRecords={attendance} setAttendanceRecords={handleSetAttendance} currentUser={user} />;
      case 'behavior': return <BehaviorSystem students={students} setStudents={handleSetStudents} behaviorRecords={behaviorRecords} setBehaviorRecords={handleSetBehavior} />;
      case 'tuition':
      case 'finance_report': return <TuitionSystem students={students} tuitionConfigs={tuitionConfigs} setTuitionConfigs={setTuitionConfigs} paymentRecords={paymentRecords} setPaymentRecords={handleSetPayments} user={user} />;
      case 'report': return <Reports students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
      case 'morning_scores': return <MorningScoreSummary students={students} attendance={attendance} studyBlocks={studyBlocks} />;
      case 'users': return <UserManagement users={systemUsers} setUsers={handleSetUsers} currentUser={user} students={students} />;
      case 'settings': return <SystemSettings studyBlocks={studyBlocks} setStudyBlocks={setStudyBlocks} />;
      default: return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
    }
  };

  return (
    <Layout activeMenu={activeMenu} setActiveMenu={setActiveMenu} user={user} onLogout={() => setUser(null)}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Student, AttendanceRecord, StudyBlock } from '../types';
import { Star, Search, Download, TrendingUp, Sun, User, Calendar, Layers, CheckCircle2, AlertCircle } from 'lucide-react';

interface MorningScoreSummaryProps {
  students: Student[];
  attendance: AttendanceRecord[];
  studyBlocks: StudyBlock[];
}

const MorningScoreSummary: React.FC<MorningScoreSummaryProps> = ({ students, attendance, studyBlocks }) => {
  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);
  const availableRooms = useMemo(() => Array.from(new Set(students.map(s => s.room))).sort((a, b) => parseInt(a as string) - parseInt(b as string)), [students]);

  const [selectedBlockId, setSelectedBlockId] = useState<number | 'ALL'>(
    studyBlocks.find(b => b.isActive)?.id || (studyBlocks.length > 0 ? studyBlocks[0].id : 'ALL')
  );
  const [selectedLevel, setSelectedLevel] = useState<string>(availableLevels[0] || '');
  const [selectedDept, setSelectedDept] = useState<string>(availableDepts[0] || '');
  const [selectedRoom, setSelectedRoom] = useState<string>(availableRooms[0] || '');
  const [searchTerm, setSearchTerm] = useState('');

  const currentBlock = useMemo(() => 
    selectedBlockId === 'ALL' ? null : studyBlocks.find(b => b.id === selectedBlockId)
  , [selectedBlockId, studyBlocks]);

  // ฟังก์ชันคำนวณคะแนนสำหรับนักเรียน 1 คน
  const calculateScore = (studentId: string) => {
    const blocksToProcess = currentBlock ? [currentBlock] : studyBlocks.filter(b => b.startDate && b.endDate);

    if (blocksToProcess.length === 0) return { score: 0, actualDays: 0, holidayDays: 0, totalDays: 0 };

    // 1. หาประวัติการเช็คชื่อ 'มาเรียน' (PRESENT) ในช่วงวันที่ของบล็อก
    const actualPresentDays = attendance.filter(a => 
      a.studentId === studentId && 
      a.type === 'MORNING' && 
      a.status === 'PRESENT' &&
      blocksToProcess.some(b => a.date >= b.startDate && a.date <= b.endDate)
    ).length;

    // 2. รวมวันหยุดพิเศษในบล็อก (นับเป็นมาเรียน)
    const holidayDays = blocksToProcess.reduce((acc, b) => acc + (Array.isArray(b.holidays) ? b.holidays.length : 0), 0);

    // 3. รวมทั้งหมด
    const totalDays = actualPresentDays + holidayDays;

    // 4. คำนวณคะแนนเต็ม 5.0 (ฐาน 18 วัน)
    const baseDays = 18;
    const finalScore = Math.min(5, (totalDays * 5) / baseDays);

    return { 
      score: finalScore, 
      actualDays: actualPresentDays, 
      holidayDays: holidayDays, 
      totalDays: totalDays 
    };
  };

  const filteredStudents = useMemo(() => {
    return students.filter(s => 
      s.level === selectedLevel && 
      s.department === selectedDept && 
      s.room === selectedRoom &&
      (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm))
    );
  }, [students, selectedLevel, selectedDept, selectedRoom, searchTerm]);

  const roomAverage = useMemo(() => {
    if (filteredStudents.length === 0) return "0.00";
    const total = filteredStudents.reduce((acc, s) => acc + calculateScore(s.id).score, 0);
    return (total / filteredStudents.length).toFixed(2);
  }, [filteredStudents, attendance, selectedBlockId]);

  const exportCSV = () => {
    let csv = "data:text/csv;charset=utf-8,\uFEFF";
    csv += "รหัสนักเรียน,ชื่อ-นามสกุล,มาเรียนจริง,วันหยุดพิเศษ,รวมวันมาเรียน,คะแนนเข้าแถว(5.0)\n";
    filteredStudents.forEach(s => {
      const res = calculateScore(s.id);
      csv += `${s.studentId},${s.name},${res.actualDays},${res.holidayDays},${res.totalDays},${res.score.toFixed(2)}\n`;
    });
    const encodedUri = encodeURI(csv);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `คะแนนเข้าแถว_${currentBlock?.name || 'ทุกบล็อก'}_ห้อง${selectedRoom}.csv`);
    link.click();
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
      {/* Header & Stats */}
      <div className="bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm">
        <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-8 mb-10">
          <div className="flex items-center gap-6">
            <div className="p-5 bg-amber-500 rounded-[24px] text-white shadow-xl shadow-amber-100">
              <Star size={32} />
            </div>
            <div>
              <h2 className="text-3xl font-black text-slate-900 tracking-tight font-heading">สรุปคะแนนเข้าแถว</h2>
              <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1 flex items-center gap-2">
                <Layers size={14} className="text-blue-500" /> 
                {currentBlock ? `กำลังดูข้อมูล: ${currentBlock.name}` : 'กำลังดูข้อมูล: ทุกบล็อกเรียน'}
              </p>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-4 w-full xl:w-auto">
            <div className="bg-slate-900 px-8 py-6 rounded-[32px] text-white flex items-center gap-8 shadow-2xl">
              <div className="border-r border-slate-700 pr-8">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">เฉลี่ยรายห้อง</p>
                <p className="text-4xl font-black text-amber-400 font-heading">{roomAverage}</p>
              </div>
              <div className="hidden sm:block">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1">เกณฑ์คำนวณ</p>
                <p className="text-sm font-bold text-blue-400">ฐาน 18 วันเรียน</p>
              </div>
            </div>
            <button onClick={exportCSV} className="p-6 bg-white border border-slate-200 rounded-[32px] hover:bg-slate-50 transition-all shadow-sm flex flex-col items-center justify-center gap-1 group">
              <Download size={24} className="text-slate-900 group-hover:scale-110 transition-transform" />
              <span className="text-[9px] font-black uppercase text-slate-500">Export</span>
            </button>
          </div>
        </div>

        {/* Filters */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-6 pt-8 border-t border-slate-50">
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">เลือกบล็อกเรียน</label>
            <select value={selectedBlockId} onChange={(e) => setSelectedBlockId(e.target.value === 'ALL' ? 'ALL' : Number(e.target.value))} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none appearance-none cursor-pointer">
              <option value="ALL">ทุกบล็อกรวมกัน</option>
              {studyBlocks.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ระดับชั้น</label>
            <select value={selectedLevel} onChange={(e) => setSelectedLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none appearance-none cursor-pointer">
              {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">แผนกวิชา</label>
            <select value={selectedDept} onChange={(e) => setSelectedDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none appearance-none cursor-pointer">
              {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ห้องเรียน</label>
            <select value={selectedRoom} onChange={(e) => setSelectedRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none appearance-none cursor-pointer">
              {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ค้นหารายชื่อ</label>
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="ชื่อ หรือ รหัส..." className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl pl-12 pr-4 py-3.5 font-bold text-slate-900 outline-none" />
            </div>
          </div>
        </div>
      </div>

      {/* Main Table */}
      <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-8 border-b bg-slate-50/50 flex items-center justify-between">
          <h3 className="text-xl font-bold text-slate-900 flex items-center gap-3 font-heading">
            <TrendingUp size={24} className="text-blue-600" />
            ตารางคะแนนพฤติกรรมบล็อกเรียน
          </h3>
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 bg-blue-600 rounded-full" />
              <span className="text-[10px] font-black uppercase text-slate-400">มาเรียนจริง</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 bg-amber-400 rounded-full" />
              <span className="text-[10px] font-black uppercase text-slate-400">วันหยุดพิเศษ</span>
            </div>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50/50">
                <th className="px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">นักเรียน</th>
                <th className="px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">ความก้าวหน้า (ฐาน 18 วัน)</th>
                <th className="px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">มาจริง / หยุดพิเศษ</th>
                <th className="px-10 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">คะแนน (5.0)</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStudents.map((s) => {
                const res = calculateScore(s.id);
                const isTargetMet = res.totalDays >= 18;
                return (
                  <tr key={s.id} className="hover:bg-slate-50 transition-all duration-300 group">
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-400 group-hover:bg-blue-600 group-hover:text-white transition-all">
                          <User size={20} />
                        </div>
                        <div>
                          <p className="font-bold text-slate-900 text-base leading-tight">{s.name}</p>
                          <p className="text-[10px] text-slate-500 font-black uppercase tracking-widest mt-1">{s.studentId}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <div className="max-w-[200px] space-y-2">
                        <div className="h-2 bg-slate-100 rounded-full overflow-hidden flex shadow-inner">
                          <div className="h-full bg-blue-600 transition-all duration-700" style={{ width: `${Math.min(100, (res.actualDays / 18) * 100)}%` }} />
                          <div className="h-full bg-amber-400 transition-all duration-700" style={{ width: `${Math.min(100, (res.holidayDays / 18) * 100)}%` }} />
                        </div>
                        <div className="flex justify-between items-center">
                          <span className={`text-[10px] font-black uppercase ${isTargetMet ? 'text-green-600' : 'text-slate-400'}`}>
                            {isTargetMet ? 'ครบเกณฑ์ ✓' : `${res.totalDays} / 18 วัน`}
                          </span>
                          <span className="text-[10px] font-bold text-slate-300">{Math.round((res.totalDays / 18) * 100)}%</span>
                        </div>
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-3">
                        <div className="text-center px-4 py-2 bg-blue-50 text-blue-700 rounded-xl border border-blue-100">
                           <p className="text-[9px] font-black uppercase tracking-tighter opacity-60">มาจริง</p>
                           <p className="text-sm font-black">{res.actualDays}</p>
                        </div>
                        <div className="text-center px-4 py-2 bg-amber-50 text-amber-700 rounded-xl border border-amber-100">
                           <p className="text-[9px] font-black uppercase tracking-tighter opacity-60">พิเศษ</p>
                           <p className="text-sm font-black">{res.holidayDays}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-2">
                         <span className={`text-3xl font-black font-heading ${res.score >= 4 ? 'text-green-600' : res.score >= 3 ? 'text-blue-600' : 'text-red-600'}`}>
                           {res.score.toFixed(2)}
                         </span>
                         {res.score === 5 && <CheckCircle2 className="text-green-500" size={18} />}
                      </div>
                    </td>
                  </tr>
                );
              })}
              {filteredStudents.length === 0 && (
                <tr>
                  <td colSpan={4} className="py-32 text-center">
                    <AlertCircle size={48} className="mx-auto text-slate-100 mb-4" />
                    <p className="text-slate-400 font-bold">ไม่พบข้อมูลนักเรียนที่ค้นหา</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default MorningScoreSummary;

payload.text:
เพื่อให้ระบบเชื่อมต่อกับ Google Sheets ทำงานได้อย่างสมบูรณ์แบบ (รองรับทั้งการบันทึกข้อมูลแบบ Log และการจัดการข้อมูลหลัก) นี่คือโค้ด **Google Apps Script** ที่ปรับปรุงใหม่ให้รองรับ Payload จากแอปพลิเคชัน EduSmart ของคุณครับ

### ขั้นตอนการใช้งาน:
1. เปิด [Google Sheets](https://sheets.new)
2. ไปที่เมนู **Extensions (ส่วนขยาย)** > **Apps Script**
3. ลบโค้ดเก่าออกแล้ววางโค้ดด้านล่างนี้ลงไป
4. กด **Save (บันทึก)**
5. กด **Deploy (ทำให้ใช้งานได้)** > **New Deployment (การทำให้ใช้งานได้ใหม่)**
6. เลือกประเภทเป็น **Web App (เว็บแอป)**
7. ตั้งค่า **Who has access (ใครที่มีสิทธิ์เข้าถึง)** เป็น **Anyone (ทุกคน)**
8. คัดลอก **Web App URL** ไปใส่ในไฟล์ `App.tsx` ในโปรเจกต์ของคุณ

---

### โค้ด Google Apps Script

```javascript
/**
 * EduSmart Backend API for Google Sheets
 * รองรับการบันทึกข้อมูล เช็คชื่อ, พฤติกรรม, การเงิน และข้อมูลนักเรียน
 */

function doPost(e) {
  try {
    // รับข้อมูลจากแอปพลิเคชัน
    var contents = e.postData.contents;
    var data = JSON.parse(contents);
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var timestamp = new Date();

    var sheetName = "";
    var rowData = [];
    var headers = [];

    // เลือกชีตตามประเภทของข้อมูล (type)
    switch(data.type) {

      case 'ATTENDANCE_MORNING':
        sheetName = "attendance_morning";
        headers = ["วันเวลาที่บันทึก", "รหัสนักเรียน", "ชื่อ-นามสกุล", "สถานะ", "หมายเหตุ", "ผู้บันทึก"];
        rowData = [timestamp, data.studentId, data.name, data.status, data.remark, data.recordedBy];
        break;

      case 'ATTENDANCE_SUBJECT':
        sheetName = "attendance_subject";
        headers = ["วันเวลาที่บันทึก", "รหัสนักเรียน", "ชื่อ-นามสกุล", "รหัสวิชา", "สถานะ", "หมายเหตุ", "ผู้บันทึก"];
        rowData = [timestamp, data.studentId, data.name, data.subjectId, data.status, data.remark, data.recordedBy];
        break;

      case 'BEHAVIOR':
        sheetName = "behavior_logs";
        headers = ["วันเวลาที่บันทึก", "รหัสนักเรียน", "ชื่อ-นามสกุล", "ประเภท", "คะแนน", "เหตุผล", "ผู้บันทึก"];
        rowData = [timestamp, data.studentId, data.name, data.actionType, data.score, data.reason, data.recordedBy];
        break;

      case 'PAYMENT':
        sheetName = "payments";
        headers = ["วันเวลาที่บันทึก", "รหัสนักเรียน", "ชื่อ-นามสกุล", "จำนวนเงิน", "ช่องทางชำระ", "ผู้บันทึก"];
        rowData = [timestamp, data.studentId, data.name, data.amount, data.method, data.recordedBy];
        break;

      case 'STUDENT':
        sheetName = "student_master";
        headers = ["วันที่ลงทะเบียน", "รหัสนักเรียน", "ชื่อ-นามสกุล", "ระดับชั้น", "แผนกวิชา", "ห้อง", "คะแนนพฤติกรรมเริ่มต้น"];
        rowData = [timestamp, data.studentId, data.name, data.level, data.department, data.room, data.behaviorScore];
        break;

      case 'USER':
        sheetName = "system_users";
        headers = ["วันที่สร้าง", "Username", "ชื่อผู้ใช้งาน", "สิทธิ์การใช้งาน", "แผนก/สังกัด"];
        rowData = [timestamp, data.username, data.name, data.role, data.department];
        break;

      default:
        return createResponse({"status": "error", "message": "Invalid data type"});
    }

    // เรียกฟังก์ชันจัดการชีต
    var sheet = getOrCreateSheet(ss, sheetName, headers);
    sheet.appendRow(rowData);

    return createResponse({"status": "success", "sheet": sheetName});

  } catch (err) {
    return createResponse({"status": "error", "message": err.toString()});
  }
}

/**
 * ฟังก์ชันสร้างชีตหากยังไม่มี และใส่ Header
 */
function getOrCreateSheet(ss, name, headers) {
  var sheet = ss.getSheetByName(name);
  if (!sheet) {
    sheet = ss.insertSheet(name);
    sheet.appendRow(headers);
    // ตกแต่ง Header เล็กน้อย
    sheet.getRange(1, 1, 1, headers.length)
         .setBackground("#0f172a")
         .setFontColor("#ffffff")
         .setFontWeight("bold");
    sheet.setFrozenRows(1); // ตรึงแถวบนสุด
  }
  return sheet;
}

/**
 * ฟังก์ชันสร้าง JSON Response สำหรับ API
 */
function createResponse(content) {
  return ContentService.createTextOutput(JSON.stringify(content))
    .setMimeType(ContentService.MimeType.JSON);
}

/**
 * ฟังก์ชันทดสอบสิทธิ์ (GET)
 */
function doGet() {
  return ContentService.createTextOutput("EduSmart API is active. Please use POST to send data.")
    .setMimeType(ContentService.MimeType.TEXT);
}
```

### การตั้งค่าในแอปพลิเคชัน (App.tsx):
เมื่อคุณได้ URL จากการ Deploy แล้ว ให้นำไปวางที่บรรทัดนี้ใน `App.tsx`:

```typescript
// ในไฟล์ App.tsx
const GOOGLE_SHEET_API_URL = "https://script.google.com/macros/s/XXXXX-YOUR-ID-XXXXX/exec";
```

### ทำไมต้องใช้โค้ดนี้?
1. **Auto-Sheet Generation**: ถ้าใน Google Sheets ของคุณยังไม่มีแท็บที่ต้องการ (เช่น `attendance_morning`) สคริปต์จะสร้างให้เองพร้อมใส่หัวตารางและใส่สีให้สวยงามโดยอัตโนมัติ
2. **Error Handling**: มีระบบตรวจสอบข้อผิดพลาด หากส่งข้อมูลมาผิดประเภท สคริปต์จะไม่ค้าง แต่จะส่งข้อความแจ้งเตือนกลับไปยังแอป
3. **Data Integrity**: รองรับการบันทึกข้อมูลที่ซับซ้อน เช่น การแยกประเภทเช็คชื่อเข้าแถวออกจากเช็คชื่อรายวิชา
4. **Security**: รองรับการบันทึก "ผู้บันทึก" (Recorded By) เพื่อให้คุณรู้ว่าใครเป็นคนทำรายการนั้นๆ ในชีตครับ

