import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, 
  CheckCircle, 
  AlertTriangle, 
  TrendingUp,
  Award,
  Heart,
  CalendarDays,
  Search,
  ArrowLeft,
  User,
  Activity,
  Filter,
  Calendar,
  Layers,
  ChevronLeft,
  ChevronRight,
  BookOpen,
  Sun,
  ChevronRight as ArrowRight,
  UserX,
  Star,
  Wallet,
  Copy,
  ExternalLink,
  CreditCard,
  Check
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { Student, AttendanceRecord, ThaiLevel, Department, AttendanceStatus, StudyBlock, TuitionConfig, PaymentRecord } from '../types';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor, children }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-shadow group relative overflow-hidden">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
    {children}
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  behavior, 
  user, 
  studyBlocks,
  tuitionConfigs = [],
  paymentRecords = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [copySuccess, setCopySuccess] = useState(false);
  const [showPaymentInfo, setShowPaymentInfo] = useState(false);

  const handleCopyAccount = () => {
    navigator.clipboard.writeText("8070863714");
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const availableLevels = useMemo<string[]>(() => {
    return Array.from(new Set(students.map(s => s.level))).sort();
  }, [students]);

  const availableDepts = useMemo<string[]>(() => {
    return Array.from(new Set(students.map(s => s.department))).sort();
  }, [students]);

  const availableRooms = useMemo<string[]>(() => {
    return Array.from(new Set(students.map(s => s.room))).sort((a, b) => parseInt(a as string) - parseInt(b as string));
  }, [students]);

  const [selectedLevel, setSelectedLevel] = useState<string>('ALL');
  const [selectedDept, setSelectedDept] = useState<string>('ALL');
  const [selectedRoom, setSelectedRoom] = useState<string>('ALL');
  const [timeframe, setTimeframe] = useState<'daily' | 'weekly' | 'monthly'>('weekly');
  const [attendanceType, setAttendanceType] = useState<'MORNING' | 'SUBJECT'>('MORNING');
  const [targetDate, setTargetDate] = useState<string>((new Date().toISOString().split('T')[0]));
  const [targetMonth, setTargetMonth] = useState<number>(new Date().getMonth());
  const [targetYear, setTargetYear] = useState<number>(new Date().getFullYear());

  const months = [
    "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
    "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
  ];

  const daysOfWeek = ["อา.", "จ.", "อ.", "พ.", "พฤ.", "ศ.", "ส."];

  const filteredStudentsByRoom = useMemo(() => {
    return students.filter(s => {
      const levelMatch = selectedLevel === 'ALL' || s.level === selectedLevel;
      const deptMatch = selectedDept === 'ALL' || s.department === selectedDept;
      const roomMatch = selectedRoom === 'ALL' || s.room === selectedRoom;
      return levelMatch && deptMatch && roomMatch;
    });
  }, [students, selectedLevel, selectedDept, selectedRoom]);

  const atRiskStudents = useMemo(() => {
    return filteredStudentsByRoom.filter(s => s.behaviorScore < 70).sort((a, b) => a.behaviorScore - b.behaviorScore);
  }, [filteredStudentsByRoom]);

  const studentIdsInRoom = useMemo(() => filteredStudentsByRoom.map(s => s.id), [filteredStudentsByRoom]);

  const roomAttendance = useMemo(() => 
    attendance.filter(a => studentIdsInRoom.includes(a.studentId) && a.type === attendanceType), 
    [attendance, studentIdsInRoom, attendanceType]
  );

  const calculateRate = (records: AttendanceRecord[]) => {
    if (records.length === 0) return 0;
    const present = records.filter(r => r.status === 'PRESENT').length;
    return Math.round((present / records.length) * 100);
  };

  const roomAssemblyScore = useMemo(() => {
    const activeBlocks = studyBlocks.filter(b => b.isActive && b.startDate && b.endDate);
    if (activeBlocks.length === 0 || studentIdsInRoom.length === 0) return "0.0";

    const morningRecords = attendance.filter(a => 
      studentIdsInRoom.includes(a.studentId) && 
      a.type === 'MORNING' &&
      a.status === 'PRESENT' &&
      activeBlocks.some(block => a.date >= block.startDate && a.date <= block.endDate)
    );

    const holidayDays = activeBlocks.reduce((acc, block) => acc + (Array.isArray(block.holidays) ? block.holidays.length : 0), 0);
    const totalPresentCredits = morningRecords.length + (holidayDays * studentIdsInRoom.length);
    const maxPossiblePresentCredits = studentIdsInRoom.length * 18;
    const score = (totalPresentCredits * 5) / maxPossiblePresentCredits;

    return Math.min(5, score).toFixed(1);
  }, [attendance, studentIdsInRoom, studyBlocks]);

  const chartData = useMemo(() => {
    if (timeframe === 'monthly') {
      const monthRanges = [
        { label: 'สัปดาห์ 1', start: 1, end: 7 },
        { label: 'สัปดาห์ 2', start: 8, end: 14 },
        { label: 'สัปดาห์ 3', start: 15, end: 21 },
        { label: 'สัปดาห์ 4', start: 22, end: 31 },
      ];

      return monthRanges.map(range => {
        const weekRecords = roomAttendance.filter(a => {
          const d = new Date(a.date);
          const dayNum = d.getDate();
          return d.getMonth() === targetMonth && 
                 d.getFullYear() === targetYear && 
                 dayNum >= range.start && 
                 dayNum <= range.end;
        });
        return { name: range.label, count: calculateRate(weekRecords) };
      });
    }

    if (timeframe === 'daily') {
      const data = [];
      const baseDate = new Date(targetDate);
      for (let i = 6; i >= 0; i--) {
        const d = new Date(baseDate);
        d.setDate(baseDate.getDate() - i);
        const dStr = d.toISOString().split('T')[0];
        const dayRecords = roomAttendance.filter(a => a.date === dStr);
        data.push({
          name: `${d.getDate()} ${months[d.getMonth()].substring(0, 3)}.`,
          count: calculateRate(dayRecords),
          fullDate: dStr
        });
      }
      return data;
    }

    const data = [];
    const base = new Date(targetDate);
    const day = base.getDay();
    const diff = base.getDate() - day + (day === 0 ? -6 : 1);
    const monday = new Date(new Date(targetDate).setDate(diff));

    for (let i = 0; i < 5; i++) {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      const dStr = d.toISOString().split('T')[0];
      const dayRecords = roomAttendance.filter(a => a.date === dStr);
      data.push({
        name: daysOfWeek[d.getDay()],
        count: calculateRate(dayRecords),
        fullDate: dStr
      });
    }
    return data;
  }, [roomAttendance, timeframe, targetDate, targetMonth, targetYear]);

  const renderIndividualView = (studentId: string) => {
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return null;

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;

    const activeBlocks = studyBlocks.filter(b => b.isActive && b.startDate && b.endDate);
    const actualPresent = attendance.filter(a => 
      a.studentId === student.id && 
      a.type === 'MORNING' && 
      a.status === 'PRESENT' &&
      activeBlocks.some(block => a.date >= block.startDate && a.date <= block.endDate)
    ).length;

    const holidayDays = activeBlocks.reduce((acc, block) => acc + (Array.isArray(block.holidays) ? block.holidays.length : 0), 0);
    const blockPresentWithHolidays = actualPresent + holidayDays;
    const blockScore = ((blockPresentWithHolidays * 5) / 18).toFixed(1);

    const latestBehavior = behavior.filter(b => b.studentId === student.id).slice(0, 5);

    // Calculate remaining tuition
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    const totalPaid = paymentRecords
      .filter(p => p.studentId === student.id && p.configId === config?.id)
      .reduce((sum, p) => sum + p.amount, 0);
    const remainingTuition = config ? config.amount - totalPaid : 0;

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button 
              onClick={() => setViewingStudentId(null)}
              className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-bold text-sm hover:bg-slate-50 transition-all shadow-sm font-heading"
            >
              <ArrowLeft size={18} /> กลับสู่ภาพรวม
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">
                {user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}
              </p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-100">
              <User size={24} />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatCard 
            title="เปอร์เซ็นต์การมาเรียนรวม" 
            value={`${attRate}%`} 
            sub={`จากทั้งหมด ${studentAttendance.length} รายการ`} 
            icon={<TrendingUp size={28} />} 
            color="bg-blue-600"
            textColor="text-blue-600"
          />
          <StatCard 
            title="คะแนนเข้าแถว (บล็อกคอร์ส)" 
            value={`${blockScore} / 5.0`} 
            sub={`รวมวันหยุดพิเศษ ${holidayDays} วัน`} 
            icon={<Star size={28} />} 
            color="bg-amber-500"
            textColor="text-amber-600"
          />
          <StatCard 
            title="ยอดค่าเทอมค้างชำระ" 
            value={`${remainingTuition.toLocaleString()} ฿`} 
            sub={config ? `จากทั้งหมด ${config.amount.toLocaleString()} ฿` : "ยังไม่กำหนดค่าเทอม"} 
            icon={<Wallet size={28} />} 
            color={remainingTuition > 0 ? "bg-red-500" : "bg-green-500"}
            textColor={remainingTuition > 0 ? "text-red-600" : "text-green-600"}
          >
            {user.role === 'PARENT' && remainingTuition > 0 && (
              <div className="mt-4 pt-4 border-t border-slate-100 w-full animate-in slide-in-from-top-2">
                {!showPaymentInfo ? (
                  <button 
                    onClick={() => setShowPaymentInfo(true)}
                    className="w-full py-3 bg-red-600 text-white rounded-xl font-black text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 shadow-lg shadow-red-100 hover:bg-red-700 transition-all"
                  >
                    <CreditCard size={14} /> ชำระเงินทันที
                  </button>
                ) : (
                  <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 space-y-3">
                    <div className="flex items-center justify-between">
                       <div className="flex items-center gap-2">
                          <img src="https://www.krungthai.com/Resource/Common/Images/Logo/logo_krungthai.png" alt="KTB" className="h-4 object-contain" />
                          <span className="text-[10px] font-black text-slate-500 uppercase">กรุงไทย (KTB)</span>
                       </div>
                       <button onClick={() => setShowPaymentInfo(false)} className="text-slate-400 hover:text-slate-600">
                          <XCircle size={14} />
                       </button>
                    </div>
                    <div className="text-center bg-white p-3 rounded-xl border border-slate-200">
                       <p className="text-xl font-black text-slate-900 tracking-wider font-heading">807-0-86371-4</p>
                       <p className="text-[9px] font-bold text-slate-400 mt-1 uppercase">วิทยาลัยเทคโนโลยี ดอนบอสโกสุราษฎร์</p>
                    </div>
                    <button 
                      onClick={handleCopyAccount}
                      className={`w-full py-3 rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all ${copySuccess ? 'bg-green-600 text-white shadow-green-100' : 'bg-slate-900 text-white shadow-slate-200'}`}
                    >
                      {copySuccess ? <Check size={14} /> : <Copy size={14} />}
                      {copySuccess ? "คัดลอกสำเร็จ" : "คัดลอกเลขบัญชี"}
                    </button>
                  </div>
                )}
              </div>
            )}
          </StatCard>
          <StatCard 
            title="พฤติกรรมสะสม" 
            value={student.behaviorScore} 
            sub="คะแนนความประพฤติ" 
            icon={<Activity size={28} />} 
            color="bg-indigo-600"
            textColor="text-indigo-600"
          />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-bold text-slate-900 text-xl mb-8 flex items-center gap-3 font-heading">
              <TrendingUp size={24} className="text-blue-600" />
              กราฟการมาเรียนรายวัน (7 รายการล่าสุด)
            </h3>
            <div className="h-[300px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={studentAttendance.slice(-7).map(a => ({ name: a.date, val: a.status === 'PRESENT' ? 100 : 0 }))}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 700}} />
                  <YAxis hide />
                  <Tooltip 
                    cursor={{fill: '#f8fafc'}}
                    contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                  />
                  <Bar dataKey="val" fill="#2563eb" radius={[10, 10, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-bold text-slate-900 text-xl mb-6 flex items-center gap-3 font-heading">
              <Award size={24} className="text-indigo-600" />
              บันทึกพฤติกรรมล่าสุด
            </h3>
            <div className="space-y-4">
              {latestBehavior.length > 0 ? latestBehavior.map(b => (
                <div key={b.id} className="p-4 bg-slate-50 rounded-2xl flex items-center justify-between border border-slate-100">
                   <div>
                     <p className="font-bold text-slate-900 text-sm">{b.reason}</p>
                     <p className="text-[10px] font-bold text-slate-500 uppercase mt-1 tracking-widest">{b.date}</p>
                   </div>
                   <span className={`font-bold text-lg ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                     {b.type === 'ADD' ? '+' : '-'}{b.score}
                   </span>
                </div>
              )) : (
                <div className="py-20 text-center flex flex-col items-center opacity-30">
                  <Heart size={48} className="mb-2" />
                  <p className="font-bold">ยังไม่มีบันทึกพฤติกรรม</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  };

  if (user.role === 'PARENT') {
    return renderIndividualView(user.studentId);
  }

  if (viewingStudentId) {
    return renderIndividualView(viewingStudentId);
  }

  const behaviorDist = [
    { name: 'ดีมาก (90+)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 90).length, color: '#16a34a' },
    { name: 'ปกติ (70-89)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 70 && s.behaviorScore < 90).length, color: '#2563eb' },
    { name: 'เฝ้าระวัง (<70)', value: filteredStudentsByRoom.filter(s => s.behaviorScore < 70).length, color: '#dc2626' },
  ];

  const avgBehavior = filteredStudentsByRoom.length > 0 
    ? Math.round(filteredStudentsByRoom.reduce((acc, s) => acc + s.behaviorScore, 0) / filteredStudentsByRoom.length)
    : 0;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col xl:flex-row gap-6">
        <div className="relative flex-1 group">
          <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600 transition-colors">
            <Search size={22} />
          </div>
          <input 
            type="text" 
            placeholder="ค้นหานักเรียนรายบุคคลเพื่อดูข้อมูลเชิงลึก..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border-2 border-slate-100 rounded-[28px] pl-16 pr-6 py-5 text-lg font-bold text-slate-900 outline-none focus:border-blue-500 shadow-xl shadow-slate-100/50"
          />
        </div>

        <div className="flex bg-white p-2 rounded-[28px] border-2 border-slate-100 shadow-sm self-start">
          <button onClick={() => setTimeframe('daily')} className={`px-6 py-3 rounded-[20px] text-xs font-bold uppercase tracking-widest transition-all font-heading ${timeframe === 'daily' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายวัน</button>
          <button onClick={() => setTimeframe('weekly')} className={`px-6 py-3 rounded-[20px] text-xs font-bold uppercase tracking-widest transition-all font-heading ${timeframe === 'weekly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายสัปดาห์</button>
          <button onClick={() => setTimeframe('monthly')} className={`px-6 py-3 rounded-[20px] text-xs font-bold uppercase tracking-widest transition-all font-heading ${timeframe === 'monthly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายเดือน</button>
        </div>
      </div>

      <div className="bg-white p-8 rounded-[40px] border-2 border-slate-100 shadow-sm">
        <div className="flex flex-col lg:flex-row items-end gap-8 mb-8 border-b border-slate-50 pb-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-1 w-full">
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">ระดับชั้น</label>
              <select value={selectedLevel} onChange={(e) => setSelectedLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none transition-all appearance-none">
                <option value="ALL">ทุกระดับชั้น</option>
                {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">แผนกวิชา</label>
              <select value={selectedDept} onChange={(e) => setSelectedDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none transition-all appearance-none">
                <option value="ALL">ทุกแผนกวิชา</option>
                {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">ห้อง</label>
              <select value={selectedRoom} onChange={(e) => setSelectedRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none transition-all appearance-none">
                <option value="ALL">ทุกห้อง</option>
                {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="นักเรียนในกลุ่ม" 
          value={filteredStudentsByRoom.length} 
          sub="จำนวนที่ลงทะเบียน" 
          icon={<Users size={28} />} 
          color="bg-slate-900"
        />
        <StatCard 
          title={`คะแนนเข้าแถว (บล็อกคอร์ส)`} 
          value={`${roomAssemblyScore} / 5.0`} 
          sub="เฉลี่ยรวมวันหยุดพิเศษ" 
          icon={<Star size={28} />} 
          color="bg-amber-500"
          textColor="text-amber-600"
        />
        <StatCard 
          title="เฝ้าระวังพฤติกรรม" 
          value={atRiskStudents.length} 
          sub="คะแนนต่ำกว่าเกณฑ์" 
          icon={<AlertTriangle size={28} />} 
          color="bg-orange-600"
          textColor="text-orange-600"
        />
        <StatCard 
          title="คะแนนเฉลี่ยกลุ่ม" 
          value={avgBehavior} 
          sub="ความประพฤติภาพรวม" 
          icon={<Award size={28} />} 
          color="bg-indigo-600"
          textColor="text-indigo-600"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h3 className="font-bold text-slate-900 text-xl flex items-center gap-3 mb-8 font-heading">
            <TrendingUp size={24} className="text-blue-600" />
            แนวโน้มการเข้าแถว ({attendanceType === 'MORNING' ? 'รายแถว' : 'รายวิชา'})
          </h3>
          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="4 4" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} domain={[0, 100]} dx={-10} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                />
                <Bar dataKey="count" fill="#2563eb" radius={[12, 12, 0, 0]} barSize={50} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h3 className="font-bold text-slate-900 text-xl mb-8 flex items-center gap-3 font-heading">
            <Award size={24} className="text-indigo-600" />
            ระดับพฤติกรรมในกลุ่ม
          </h3>
          <div className="h-[280px] w-full relative">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={behaviorDist} innerRadius={75} outerRadius={105} paddingAngle={10} dataKey="value">
                  {behaviorDist.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
              <span className="text-4xl font-black text-slate-900 font-heading">{filteredStudentsByRoom.length}</span>
              <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest font-heading">นักเรียน</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, 
  CheckCircle, 
  AlertTriangle, 
  TrendingUp,
  Award,
  Heart,
  CalendarDays,
  Search,
  ArrowLeft,
  User,
  Activity,
  Filter,
  Calendar,
  Layers,
  ChevronLeft,
  ChevronRight,
  BookOpen,
  Sun,
  ChevronRight as ArrowRight,
  UserX,
  Star,
  Wallet,
  Copy,
  ExternalLink,
  CreditCard,
  Check,
  /* Added XCircle to imports */
  XCircle
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { Student, AttendanceRecord, ThaiLevel, Department, AttendanceStatus, StudyBlock, TuitionConfig, PaymentRecord } from '../types';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor, children }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-shadow group relative overflow-hidden">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
    {children}
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  behavior, 
  user, 
  studyBlocks,
  tuitionConfigs = [],
  paymentRecords = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [copySuccess, setCopySuccess] = useState(false);
  const [showPaymentInfo, setShowPaymentInfo] = useState(false);

  const handleCopyAccount = () => {
    navigator.clipboard.writeText("8070863714");
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const availableLevels = useMemo<string[]>(() => {
    return Array.from(new Set(students.map(s => s.level))).sort();
  }, [students]);

  const availableDepts = useMemo<string[]>(() => {
    return Array.from(new Set(students.map(s => s.department))).sort();
  }, [students]);

  const availableRooms = useMemo<string[]>(() => {
    return Array.from(new Set(students.map(s => s.room))).sort((a, b) => parseInt(a as string) - parseInt(b as string));
  }, [students]);

  const [selectedLevel, setSelectedLevel] = useState<string>('ALL');
  const [selectedDept, setSelectedDept] = useState<string>('ALL');
  const [selectedRoom, setSelectedRoom] = useState<string>('ALL');
  const [timeframe, setTimeframe] = useState<'daily' | 'weekly' | 'monthly'>('weekly');
  const [attendanceType, setAttendanceType] = useState<'MORNING' | 'SUBJECT'>('MORNING');
  const [targetDate, setTargetDate] = useState<string>((new Date().toISOString().split('T')[0]));
  const [targetMonth, setTargetMonth] = useState<number>(new Date().getMonth());
  const [targetYear, setTargetYear] = useState<number>(new Date().getFullYear());

  const months = [
    "มกราคม", "กุมภาพันธ์", "มีนาคม", "เมษายน", "พฤษภาคม", "มิถุนายน",
    "กรกฎาคม", "สิงหาคม", "กันยายน", "ตุลาคม", "พฤศจิกายน", "ธันวาคม"
  ];

  const daysOfWeek = ["อา.", "จ.", "อ.", "พ.", "พฤ.", "ศ.", "ส."];

  const filteredStudentsByRoom = useMemo(() => {
    return students.filter(s => {
      const levelMatch = selectedLevel === 'ALL' || s.level === selectedLevel;
      const deptMatch = selectedDept === 'ALL' || s.department === selectedDept;
      const roomMatch = selectedRoom === 'ALL' || s.room === selectedRoom;
      return levelMatch && deptMatch && roomMatch;
    });
  }, [students, selectedLevel, selectedDept, selectedRoom]);

  const atRiskStudents = useMemo(() => {
    return filteredStudentsByRoom.filter(s => s.behaviorScore < 70).sort((a, b) => a.behaviorScore - b.behaviorScore);
  }, [filteredStudentsByRoom]);

  const studentIdsInRoom = useMemo(() => filteredStudentsByRoom.map(s => s.id), [filteredStudentsByRoom]);

  const roomAttendance = useMemo(() => 
    attendance.filter(a => studentIdsInRoom.includes(a.studentId) && a.type === attendanceType), 
    [attendance, studentIdsInRoom, attendanceType]
  );

  const calculateRate = (records: AttendanceRecord[]) => {
    if (records.length === 0) return 0;
    const present = records.filter(r => r.status === 'PRESENT').length;
    return Math.round((present / records.length) * 100);
  };

  const roomAssemblyScore = useMemo(() => {
    const activeBlocks = studyBlocks.filter(b => b.isActive && b.startDate && b.endDate);
    if (activeBlocks.length === 0 || studentIdsInRoom.length === 0) return "0.0";

    const morningRecords = attendance.filter(a => 
      studentIdsInRoom.includes(a.studentId) && 
      a.type === 'MORNING' &&
      a.status === 'PRESENT' &&
      activeBlocks.some(block => a.date >= block.startDate && a.date <= block.endDate)
    );

    const holidayDays = activeBlocks.reduce((acc, block) => acc + (Array.isArray(block.holidays) ? block.holidays.length : 0), 0);
    const totalPresentCredits = morningRecords.length + (holidayDays * studentIdsInRoom.length);
    const maxPossiblePresentCredits = studentIdsInRoom.length * 18;
    const score = (totalPresentCredits * 5) / maxPossiblePresentCredits;

    return Math.min(5, score).toFixed(1);
  }, [attendance, studentIdsInRoom, studyBlocks]);

  const chartData = useMemo(() => {
    if (timeframe === 'monthly') {
      const monthRanges = [
        { label: 'สัปดาห์ 1', start: 1, end: 7 },
        { label: 'สัปดาห์ 2', start: 8, end: 14 },
        { label: 'สัปดาห์ 3', start: 15, end: 21 },
        { label: 'สัปดาห์ 4', start: 22, end: 31 },
      ];

      return monthRanges.map(range => {
        const weekRecords = roomAttendance.filter(a => {
          const d = new Date(a.date);
          const dayNum = d.getDate();
          return d.getMonth() === targetMonth && 
                 d.getFullYear() === targetYear && 
                 dayNum >= range.start && 
                 dayNum <= range.end;
        });
        return { name: range.label, count: calculateRate(weekRecords) };
      });
    }

    if (timeframe === 'daily') {
      const data = [];
      const baseDate = new Date(targetDate);
      for (let i = 6; i >= 0; i--) {
        const d = new Date(baseDate);
        d.setDate(baseDate.getDate() - i);
        const dStr = d.toISOString().split('T')[0];
        const dayRecords = roomAttendance.filter(a => a.date === dStr);
        data.push({
          name: `${d.getDate()} ${months[d.getMonth()].substring(0, 3)}.`,
          count: calculateRate(dayRecords),
          fullDate: dStr
        });
      }
      return data;
    }

    const data = [];
    const base = new Date(targetDate);
    const day = base.getDay();
    const diff = base.getDate() - day + (day === 0 ? -6 : 1);
    const monday = new Date(new Date(targetDate).setDate(diff));

    for (let i = 0; i < 5; i++) {
      const d = new Date(monday);
      d.setDate(monday.getDate() + i);
      const dStr = d.toISOString().split('T')[0];
      const dayRecords = roomAttendance.filter(a => a.date === dStr);
      data.push({
        name: daysOfWeek[d.getDay()],
        count: calculateRate(dayRecords),
        fullDate: dStr
      });
    }
    return data;
  }, [roomAttendance, timeframe, targetDate, targetMonth, targetYear]);

  const renderIndividualView = (studentId: string) => {
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return null;

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;

    const activeBlocks = studyBlocks.filter(b => b.isActive && b.startDate && b.endDate);
    const actualPresent = attendance.filter(a => 
      a.studentId === student.id && 
      a.type === 'MORNING' && 
      a.status === 'PRESENT' &&
      activeBlocks.some(block => a.date >= block.startDate && a.date <= block.endDate)
    ).length;

    const holidayDays = activeBlocks.reduce((acc, block) => acc + (Array.isArray(block.holidays) ? block.holidays.length : 0), 0);
    const blockPresentWithHolidays = actualPresent + holidayDays;
    const blockScore = ((blockPresentWithHolidays * 5) / 18).toFixed(1);

    const latestBehavior = behavior.filter(b => b.studentId === student.id).slice(0, 5);

    // Calculate remaining tuition
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    const totalPaid = paymentRecords
      .filter(p => p.studentId === student.id && p.configId === config?.id)
      .reduce((sum, p) => sum + p.amount, 0);
    const remainingTuition = config ? config.amount - totalPaid : 0;

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button 
              onClick={() => setViewingStudentId(null)}
              className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-bold text-sm hover:bg-slate-50 transition-all shadow-sm font-heading"
            >
              <ArrowLeft size={18} /> กลับสู่ภาพรวม
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">
                {user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}
              </p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-100">
              <User size={24} />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatCard 
            title="เปอร์เซ็นต์การมาเรียนรวม" 
            value={`${attRate}%`} 
            sub={`จากทั้งหมด ${studentAttendance.length} รายการ`} 
            icon={<TrendingUp size={28} />} 
            color="bg-blue-600"
            textColor="text-blue-600"
          />
          <StatCard 
            title="คะแนนเข้าแถว (บล็อกคอร์ส)" 
            value={`${blockScore} / 5.0`} 
            sub={`รวมวันหยุดพิเศษ ${holidayDays} วัน`} 
            icon={<Star size={28} />} 
            color="bg-amber-500"
            textColor="text-amber-600"
          />
          <StatCard 
            title="ยอดค่าเทอมค้างชำระ" 
            value={`${remainingTuition.toLocaleString()} ฿`} 
            sub={config ? `จากทั้งหมด ${config.amount.toLocaleString()} ฿` : "ยังไม่กำหนดค่าเทอม"} 
            icon={<Wallet size={28} />} 
            color={remainingTuition > 0 ? "bg-red-500" : "bg-green-500"}
            textColor={remainingTuition > 0 ? "text-red-600" : "text-green-600"}
          >
            {user.role === 'PARENT' && remainingTuition > 0 && (
              <div className="mt-4 pt-4 border-t border-slate-100 w-full animate-in slide-in-from-top-2">
                {!showPaymentInfo ? (
                  <button 
                    onClick={() => setShowPaymentInfo(true)}
                    className="w-full py-3 bg-red-600 text-white rounded-xl font-black text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 shadow-lg shadow-red-100 hover:bg-red-700 transition-all"
                  >
                    <CreditCard size={14} /> ชำระเงินทันที
                  </button>
                ) : (
                  <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 space-y-3">
                    <div className="flex items-center justify-between">
                       <div className="flex items-center gap-2">
                          <img src="https://www.krungthai.com/Resource/Common/Images/Logo/logo_krungthai.png" alt="KTB" className="h-4 object-contain" />
                          <span className="text-[10px] font-black text-slate-500 uppercase">กรุงไทย (KTB)</span>
                       </div>
                       <button onClick={() => setShowPaymentInfo(false)} className="text-slate-400 hover:text-slate-600">
                          <XCircle size={14} />
                       </button>
                    </div>
                    <div className="text-center bg-white p-3 rounded-xl border border-slate-200">
                       <p className="text-xl font-black text-slate-900 tracking-wider font-heading">807-0-86371-4</p>
                       <p className="text-[9px] font-bold text-slate-400 mt-1 uppercase">วิทยาลัยเทคโนโลยี ดอนบอสโกสุราษฎร์</p>
                    </div>
                    <button 
                      onClick={handleCopyAccount}
                      className={`w-full py-3 rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all ${copySuccess ? 'bg-green-600 text-white shadow-green-100' : 'bg-slate-900 text-white shadow-slate-200'}`}
                    >
                      {copySuccess ? <Check size={14} /> : <Copy size={14} />}
                      {copySuccess ? "คัดลอกสำเร็จ" : "คัดลอกเลขบัญชี"}
                    </button>
                  </div>
                )}
              </div>
            )}
          </StatCard>
          <StatCard 
            title="พฤติกรรมสะสม" 
            value={student.behaviorScore} 
            sub="คะแนนความประพฤติ" 
            icon={<Activity size={28} />} 
            color="bg-indigo-600"
            textColor="text-indigo-600"
          />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-bold text-slate-900 text-xl mb-8 flex items-center gap-3 font-heading">
              <TrendingUp size={24} className="text-blue-600" />
              กราฟการมาเรียนรายวัน (7 รายการล่าสุด)
            </h3>
            <div className="h-[300px] w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={studentAttendance.slice(-7).map(a => ({ name: a.date, val: a.status === 'PRESENT' ? 100 : 0 }))}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 700}} />
                  <YAxis hide />
                  <Tooltip 
                    cursor={{fill: '#f8fafc'}}
                    contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                  />
                  <Bar dataKey="val" fill="#2563eb" radius={[10, 10, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-bold text-slate-900 text-xl mb-6 flex items-center gap-3 font-heading">
              <Award size={24} className="text-indigo-600" />
              บันทึกพฤติกรรมล่าสุด
            </h3>
            <div className="space-y-4">
              {latestBehavior.length > 0 ? latestBehavior.map(b => (
                <div key={b.id} className="p-4 bg-slate-50 rounded-2xl flex items-center justify-between border border-slate-100">
                   <div>
                     <p className="font-bold text-slate-900 text-sm">{b.reason}</p>
                     <p className="text-[10px] font-bold text-slate-500 uppercase mt-1 tracking-widest">{b.date}</p>
                   </div>
                   <span className={`font-bold text-lg ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                     {b.type === 'ADD' ? '+' : '-'}{b.score}
                   </span>
                </div>
              )) : (
                <div className="py-20 text-center flex flex-col items-center opacity-30">
                  <Heart size={48} className="mb-2" />
                  <p className="font-bold">ยังไม่มีบันทึกพฤติกรรม</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  };

  if (user.role === 'PARENT') {
    return renderIndividualView(user.studentId);
  }

  if (viewingStudentId) {
    return renderIndividualView(viewingStudentId);
  }

  const behaviorDist = [
    { name: 'ดีมาก (90+)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 90).length, color: '#16a34a' },
    { name: 'ปกติ (70-89)', value: filteredStudentsByRoom.filter(s => s.behaviorScore >= 70 && s.behaviorScore < 90).length, color: '#2563eb' },
    { name: 'เฝ้าระวัง (<70)', value: filteredStudentsByRoom.filter(s => s.behaviorScore < 70).length, color: '#dc2626' },
  ];

  const avgBehavior = filteredStudentsByRoom.length > 0 
    ? Math.round(filteredStudentsByRoom.reduce((acc, s) => acc + s.behaviorScore, 0) / filteredStudentsByRoom.length)
    : 0;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col xl:flex-row gap-6">
        <div className="relative flex-1 group">
          <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600 transition-colors">
            <Search size={22} />
          </div>
          <input 
            type="text" 
            placeholder="ค้นหานักเรียนรายบุคคลเพื่อดูข้อมูลเชิงลึก..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-white border-2 border-slate-100 rounded-[28px] pl-16 pr-6 py-5 text-lg font-bold text-slate-900 outline-none focus:border-blue-500 shadow-xl shadow-slate-100/50"
          />
        </div>

        <div className="flex bg-white p-2 rounded-[28px] border-2 border-slate-100 shadow-sm self-start">
          <button onClick={() => setTimeframe('daily')} className={`px-6 py-3 rounded-[20px] text-xs font-bold uppercase tracking-widest transition-all font-heading ${timeframe === 'daily' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายวัน</button>
          <button onClick={() => setTimeframe('weekly')} className={`px-6 py-3 rounded-[20px] text-xs font-bold uppercase tracking-widest transition-all font-heading ${timeframe === 'weekly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายสัปดาห์</button>
          <button onClick={() => setTimeframe('monthly')} className={`px-6 py-3 rounded-[20px] text-xs font-bold uppercase tracking-widest transition-all font-heading ${timeframe === 'monthly' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>รายเดือน</button>
        </div>
      </div>

      <div className="bg-white p-8 rounded-[40px] border-2 border-slate-100 shadow-sm">
        <div className="flex flex-col lg:flex-row items-end gap-8 mb-8 border-b border-slate-50 pb-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-1 w-full">
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">ระดับชั้น</label>
              <select value={selectedLevel} onChange={(e) => setSelectedLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none transition-all appearance-none">
                <option value="ALL">ทุกระดับชั้น</option>
                {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">แผนกวิชา</label>
              <select value={selectedDept} onChange={(e) => setSelectedDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none transition-all appearance-none">
                <option value="ALL">ทุกแผนกวิชา</option>
                {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">ห้อง</label>
              <select value={selectedRoom} onChange={(e) => setSelectedRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none transition-all appearance-none">
                <option value="ALL">ทุกห้อง</option>
                {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="นักเรียนในกลุ่ม" 
          value={filteredStudentsByRoom.length} 
          sub="จำนวนที่ลงทะเบียน" 
          icon={<Users size={28} />} 
          color="bg-slate-900"
        />
        <StatCard 
          title={`คะแนนเข้าแถว (บล็อกคอร์ส)`} 
          value={`${roomAssemblyScore} / 5.0`} 
          sub="เฉลี่ยรวมวันหยุดพิเศษ" 
          icon={<Star size={28} />} 
          color="bg-amber-500"
          textColor="text-amber-600"
        />
        <StatCard 
          title="เฝ้าระวังพฤติกรรม" 
          value={atRiskStudents.length} 
          sub="คะแนนต่ำกว่าเกณฑ์" 
          icon={<AlertTriangle size={28} />} 
          color="bg-orange-600"
          textColor="text-orange-600"
        />
        <StatCard 
          title="คะแนนเฉลี่ยกลุ่ม" 
          value={avgBehavior} 
          sub="ความประพฤติภาพรวม" 
          icon={<Award size={28} />} 
          color="bg-indigo-600"
          textColor="text-indigo-600"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h3 className="font-bold text-slate-900 text-xl flex items-center gap-3 mb-8 font-heading">
            <TrendingUp size={24} className="text-blue-600" />
            แนวโน้มการเข้าแถว ({attendanceType === 'MORNING' ? 'รายแถว' : 'รายวิชา'})
          </h3>
          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="4 4" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 13, fontWeight: 700}} domain={[0, 100]} dx={-10} />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                />
                <Bar dataKey="count" fill="#2563eb" radius={[12, 12, 0, 0]} barSize={50} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h3 className="font-bold text-slate-900 text-xl mb-8 flex items-center gap-3 font-heading">
            <Award size={24} className="text-indigo-600" />
            ระดับพฤติกรรมในกลุ่ม
          </h3>
          <div className="h-[280px] w-full relative">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={behaviorDist} innerRadius={75} outerRadius={105} paddingAngle={10} dataKey="value">
                  {behaviorDist.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
              <span className="text-4xl font-black text-slate-900 font-heading">{filteredStudentsByRoom.length}</span>
              <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest font-heading">นักเรียน</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

export type UserRole = 'ADMIN' | 'TEACHER' | 'PARENT' | 'FINANCE';

export interface User {
  id: string;
  name: string;
  role: UserRole;
  username: string;
  password: string;
  department?: string;
  studentId?: string; // สำหรับ PARENT เพื่อระบุลูก
  email?: string;
}

export type AttendanceStatus = 'PRESENT' | 'LATE' | 'ABSENT' | 'BUSINESS_LEAVE' | 'SICK_LEAVE';

export interface Student {
  id: string;
  studentId: string;
  name: string;
  level: string; 
  department: string; 
  room: string;
  behaviorScore: number;
}

export interface AttendanceRecord {
  id: string;
  studentId: string;
  date: string;
  type: 'MORNING' | 'SUBJECT';
  subjectId?: string;
  status: AttendanceStatus;
  remark?: string;
  timestamp: string;
}

export interface Subject {
  id: string;
  name: string;
  code: string;
  teacherId: string;
}

export interface BehaviorRecord {
  id: string;
  studentId: string;
  type: 'ADD' | 'DEDUCT';
  score: number;
  reason: string;
  date: string;
  recordedBy: string;
}

export interface TuitionConfig {
  id: string;
  level: string;
  department: string;
  amount: number;
  term: string; 
  blockId?: number; // ระบุว่ายอดนี้สำหรับบล็อกเรียนไหน
  dueDate?: string;  // วันที่ต้องชำระเงิน
}

export interface PaymentRecord {
  id: string;
  studentId: string;
  configId: string;
  amount: number;
  method: 'CASH' | 'TRANSFER';
  date: string;
  recordedBy: string;
  status: 'PAID' | 'PARTIAL' | 'PENDING';
}

export interface StudyBlock {
  id: number;
  name: string;
  startDate: string;
  endDate: string;
  isActive: boolean;
  holidays: string[];
}

export enum ThaiLevel {
  VCC1 = 'ปวช. 1',
  VCC2 = 'ปวช. 2',
  VCC3 = 'ปวช. 3',
  DIP1 = 'ปวส. 1',
  DIP2 = 'ปวส. 2',
}

export enum Department {
  IT = 'เทคโนโลยีสารสนเทศ',
  MECH = 'ช่างยนต์',
  ACC = 'การบัญชี',
  ELEC = 'ช่างไฟฟ้า',
}

import React, { useState, useMemo } from 'react';
import { 
  Users, 
  CheckCircle, 
  AlertTriangle, 
  TrendingUp,
  Award,
  Heart,
  Search,
  ArrowLeft,
  User,
  Activity,
  Star,
  Wallet,
  Copy,
  CreditCard,
  Check,
  XCircle,
  Calendar,
  Info
} from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord } from '../types';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor, children }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-shadow group relative overflow-hidden">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-3xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
    {children}
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  behavior, 
  user, 
  studyBlocks,
  tuitionConfigs = [],
  paymentRecords = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [copySuccess, setCopySuccess] = useState(false);
  const [showPaymentInfo, setShowPaymentInfo] = useState(false);

  const handleCopyAccount = () => {
    navigator.clipboard.writeText("8070863714");
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const currentActiveBlock = useMemo(() => studyBlocks.find(b => b.isActive), [studyBlocks]);

  const renderIndividualView = (studentId: string) => {
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return null;

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;

    // Calculate Score for Block
    const activeBlocks = studyBlocks.filter(b => b.isActive && b.startDate && b.endDate);
    const actualPresent = attendance.filter(a => 
      a.studentId === student.id && 
      a.type === 'MORNING' && 
      a.status === 'PRESENT' &&
      activeBlocks.some(block => a.date >= block.startDate && a.date <= block.endDate)
    ).length;

    const holidayDays = activeBlocks.reduce((acc, block) => acc + (Array.isArray(block.holidays) ? block.holidays.length : 0), 0);
    const blockScore = (((actualPresent + holidayDays) * 5) / 18).toFixed(1);

    // Tuition Summary
    const configs = tuitionConfigs.filter(c => c.level === student.level && c.department === student.department);
    const totalTuitionAmount = configs.reduce((sum, c) => sum + c.amount, 0);
    const totalPaid = paymentRecords
      .filter(p => p.studentId === student.id && configs.some(c => c.id === p.configId))
      .reduce((sum, p) => sum + p.amount, 0);

    const remainingTotal = Math.max(0, totalTuitionAmount - totalPaid);

    // Current Block Tuition
    const currentBlockConfig = configs.find(c => c.blockId === currentActiveBlock?.id);
    let blockRemaining = 0;
    if (currentBlockConfig) {
      const blockPaid = paymentRecords
        .filter(p => p.studentId === student.id && p.configId === currentBlockConfig.id)
        .reduce((sum, p) => sum + p.amount, 0);
      blockRemaining = Math.max(0, currentBlockConfig.amount - blockPaid);
    }

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-bold text-sm hover:bg-slate-50 transition-all shadow-sm font-heading">
              <ArrowLeft size={18} /> กลับสู่ภาพรวม
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">{user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}</p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><User size={24} /></div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าเรียน" value={`${attRate}%`} sub={`จากทั้งหมด ${studentAttendance.length} ครั้ง`} icon={<TrendingUp size={28} />} color="bg-blue-600" textColor="text-blue-600" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore} / 5.0`} sub={`บล็อกคอร์สปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />

          {/* Tuition Card */}
          <StatCard 
            title="ยอดค้างชำระรวม" 
            value={`${remainingTotal.toLocaleString()} ฿`} 
            sub={`ยอดรวมทุกบล็อกเรียน`} 
            icon={<Wallet size={28} />} 
            color={remainingTotal > 0 ? "bg-red-500" : "bg-green-500"} 
            textColor={remainingTotal > 0 ? "text-red-600" : "text-green-600"}
          >
            {user.role === 'PARENT' && remainingTotal > 0 && (
              <div className="mt-4 pt-4 border-t border-slate-100 w-full space-y-3">
                {currentBlockConfig && blockRemaining > 0 && (
                  <div className="p-3 bg-red-50 rounded-xl border border-red-100">
                    <div className="flex justify-between items-center mb-1">
                      <span className="text-[10px] font-black text-red-600 uppercase tracking-tighter">เฉพาะบล็อกปัจจุบัน</span>
                      <span className="text-xs font-black text-red-600">{blockRemaining.toLocaleString()} ฿</span>
                    </div>
                    <div className="flex items-center gap-2 text-[9px] font-bold text-red-400">
                      <Calendar size={10} /> ภายในวันที่: {currentBlockConfig.dueDate || '-'}
                    </div>
                  </div>
                )}

                {!showPaymentInfo ? (
                  <button onClick={() => setShowPaymentInfo(true)} className="w-full py-3 bg-slate-900 text-white rounded-xl font-black text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 shadow-lg hover:bg-black transition-all">
                    <CreditCard size={14} /> ดูเลขบัญชีชำระเงิน
                  </button>
                ) : (
                  <div className="bg-blue-50 p-4 rounded-2xl border border-blue-200 space-y-3 animate-in slide-in-from-top-2">
                    <div className="flex items-center justify-between">
                       <div className="flex items-center gap-2">
                          <img src="https://www.krungthai.com/Resource/Common/Images/Logo/logo_krungthai.png" alt="KTB" className="h-4 object-contain" />
                          <span className="text-[10px] font-black text-blue-700 uppercase">ธนาคารกรุงไทย</span>
                       </div>
                       <button onClick={() => setShowPaymentInfo(false)} className="text-slate-400 hover:text-slate-600"><XCircle size={16} /></button>
                    </div>
                    <div className="text-center bg-white p-4 rounded-2xl border border-blue-100 shadow-sm">
                       <p className="text-xs font-bold text-slate-400 uppercase mb-1">เลขที่บัญชี</p>
                       <p className="text-2xl font-black text-blue-600 tracking-wider font-heading">807-0-86371-4</p>
                       <p className="text-[9px] font-bold text-slate-500 mt-2 uppercase">วิทยาลัยเทคโนโลยี ดอนบอสโกสุราษฎร์</p>
                    </div>
                    <button 
                      onClick={handleCopyAccount}
                      className={`w-full py-3 rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all ${copySuccess ? 'bg-green-600 text-white' : 'bg-blue-600 text-white shadow-blue-100 hover:bg-blue-700'}`}
                    >
                      {copySuccess ? <Check size={14} /> : <Copy size={14} />}
                      {copySuccess ? "คัดลอกสำเร็จ!" : "คัดลอกเลขบัญชี"}
                    </button>
                  </div>
                )}
              </div>
            )}
          </StatCard>

          <StatCard title="พฤติกรรม" value={student.behaviorScore} sub="คะแนนปัจจุบัน" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        {/* Behavior Log for Parent */}
        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h3 className="font-bold text-slate-900 text-xl mb-6 flex items-center gap-3 font-heading">
            <Award size={24} className="text-indigo-600" /> บันทึกพฤติกรรมล่าสุด
          </h3>
          <div className="space-y-4">
            {behavior.filter(b => b.studentId === student.id).slice(0, 5).map(b => (
              <div key={b.id} className="p-4 bg-slate-50 rounded-2xl flex items-center justify-between border border-slate-100">
                 <div>
                   <p className="font-bold text-slate-900 text-sm">{b.reason}</p>
                   <p className="text-[10px] font-bold text-slate-500 uppercase mt-1">{b.date}</p>
                 </div>
                 <span className={`font-black text-lg ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                   {b.type === 'ADD' ? '+' : '-'}{b.score}
                 </span>
              </div>
            ))}
          </div>
        </div>
      </div>
    );
  };

  if (user.role === 'PARENT') return renderIndividualView(user.studentId);
  if (viewingStudentId) return renderIndividualView(viewingStudentId);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col xl:flex-row gap-6">
        <div className="relative flex-1 group">
          <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600" size={22} />
          <input type="text" placeholder="ค้นหานักเรียนเพื่อดูข้อมูลเชิงลึก..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white border-2 border-slate-100 rounded-[28px] pl-16 pr-6 py-5 text-lg font-bold text-slate-900 outline-none focus:border-blue-500 shadow-xl shadow-slate-100/50" />
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="นักเรียนทั้งหมด" value={students.length} sub="จำนวนลงทะเบียน" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เข้าแถว (ห้องเรียน)" value="95%" sub="ค่าเฉลี่ยรายวัน" icon={<CheckCircle size={28} />} color="bg-green-600" />
        <StatCard title="เฝ้าระวังพฤติกรรม" value={students.filter(s => s.behaviorScore < 70).length} sub="คะแนนต่ำกว่าเกณฑ์" icon={<AlertTriangle size={28} />} color="bg-red-600" />
        <StatCard title="คะแนนเฉลี่ยรวม" value="88" sub="ความประพฤติ" icon={<Award size={28} />} color="bg-indigo-600" />
      </div>

      <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
        <h3 className="text-xl font-bold text-slate-900 mb-8 font-heading">รายชื่อนักเรียน</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {students.filter(s => s.name.includes(searchTerm)).map(s => (
            <button key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center gap-4 p-4 rounded-2xl border border-slate-100 hover:border-blue-500 hover:bg-blue-50 transition-all text-left">
              <div className="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-400 font-bold">{s.name.charAt(0)}</div>
              <div>
                <p className="font-bold text-slate-900 text-sm">{s.name}</p>
                <p className="text-[10px] text-slate-500 uppercase">{s.studentId}</p>
              </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { Student, TuitionConfig, PaymentRecord, ThaiLevel, Department, StudyBlock } from '../types';
import { CreditCard, Plus, Save, Trash2, Banknote, History, Search, CheckCircle2, AlertCircle, User, Wallet, Calendar, Layers } from 'lucide-react';

interface TuitionSystemProps {
  students: Student[];
  tuitionConfigs: TuitionConfig[];
  setTuitionConfigs: React.Dispatch<React.SetStateAction<TuitionConfig[]>>;
  paymentRecords: PaymentRecord[];
  setPaymentRecords: React.Dispatch<React.SetStateAction<PaymentRecord[]>>;
  user: any;
  studyBlocks?: StudyBlock[];
}

const TuitionSystem: React.FC<TuitionSystemProps> = ({ 
  students, tuitionConfigs, setTuitionConfigs, paymentRecords, setPaymentRecords, user, studyBlocks = [] 
}) => {
  const [activeTab, setActiveTab] = useState<'config' | 'payment' | 'history'>(
    user.role === 'PARENT' ? 'history' : 'payment'
  );

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(null);

  const [newConfig, setNewConfig] = useState<Partial<TuitionConfig>>({
    level: Object.values(ThaiLevel)[0],
    department: Object.values(Department)[0],
    amount: 0,
    term: '1/2567',
    blockId: studyBlocks.find(b => b.isActive)?.id || 1,
    dueDate: new Date().toISOString().split('T')[0]
  });

  const [paymentAmount, setPaymentAmount] = useState<number | "">("");
  const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'TRANSFER'>('TRANSFER');

  const filteredStudents = useMemo(() => {
    return students.filter(s => 
      s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm)
    );
  }, [students, searchTerm]);

  const handleAddConfig = () => {
    if (!newConfig.amount || newConfig.amount <= 0) {
      alert('กรุณาระบุจำนวนเงินที่ถูกต้อง');
      return;
    }
    const config: TuitionConfig = {
      id: `CONF_${Date.now()}`,
      level: newConfig.level!,
      department: newConfig.department!,
      amount: newConfig.amount!,
      term: newConfig.term!,
      blockId: Number(newConfig.blockId),
      dueDate: newConfig.dueDate
    };
    setTuitionConfigs(prev => [...prev, config]);
  };

  const getStudentTuitionStatus = (student: Student) => {
    const studentConfigs = tuitionConfigs.filter(c => c.level === student.level && c.department === student.department);
    if (studentConfigs.length === 0) return null;

    const paidRecords = paymentRecords.filter(p => p.studentId === student.id);
    const totalPaid = paidRecords.reduce((sum, p) => sum + p.amount, 0);
    const totalAmount = studentConfigs.reduce((sum, c) => sum + c.amount, 0);

    return {
      configs: studentConfigs,
      paidAmount: totalPaid,
      remaining: Math.max(0, totalAmount - totalPaid),
      isFullyPaid: totalPaid >= totalAmount
    };
  };

  const handlePayment = (student: Student) => {
    const amount = Number(paymentAmount);
    if (!paymentAmount || amount <= 0) {
      alert('กรุณาระบุจำนวนเงินที่ถูกต้อง');
      return;
    }

    // Assigning to the oldest unpaid config first (Simplified logic)
    const status = getStudentTuitionStatus(student);
    if (!status) return;

    const newPayment: PaymentRecord = {
      id: `PAY_${Date.now()}`,
      studentId: student.id,
      configId: status.configs[0]?.id || 'GENERAL',
      amount: amount,
      method: paymentMethod,
      date: new Date().toLocaleDateString('th-TH'),
      recordedBy: user.name,
      status: 'PAID'
    };

    setPaymentRecords(prev => [...prev, newPayment]);
    setPaymentAmount("");
    alert('บันทึกการชำระเงินสำเร็จ');
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20 max-w-7xl mx-auto">
      <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit">
        <button onClick={() => setActiveTab('payment')} className={`px-8 py-3 rounded-xl text-sm font-bold transition-all font-heading ${activeTab === 'payment' ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>รับชำระเงิน</button>
        <button onClick={() => setActiveTab('config')} className={`px-8 py-3 rounded-xl text-sm font-bold transition-all font-heading ${activeTab === 'config' ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>ตั้งค่าค่าเทอมรายบล็อก</button>
        <button onClick={() => setActiveTab('history')} className={`px-8 py-3 rounded-xl text-sm font-bold transition-all font-heading ${activeTab === 'history' ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>ประวัติรายรับ</button>
      </div>

      {activeTab === 'config' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1 bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm space-y-6">
            <h3 className="text-xl font-bold text-slate-900 flex items-center gap-3 font-heading"><Plus className="text-blue-600" /> กำหนดค่าเทอมใหม่</h3>
            <div className="space-y-4">
              <div>
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">บล็อกเรียน</label>
                <select value={newConfig.blockId} onChange={(e) => setNewConfig({...newConfig, blockId: Number(e.target.value)})} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold">
                  {studyBlocks.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ระดับชั้น</label>
                  <select value={newConfig.level} onChange={(e) => setNewConfig({...newConfig, level: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold">
                    {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">แผนก</label>
                  <select value={newConfig.department} onChange={(e) => setNewConfig({...newConfig, department: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold">
                    {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
                  </select>
                </div>
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ยอดชำระ (บาท)</label>
                <input type="number" value={newConfig.amount === 0 ? "" : newConfig.amount} onChange={(e) => setNewConfig({...newConfig, amount: Number(e.target.value)})} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold" placeholder="0.00" />
              </div>
              <div>
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ชำระภายในวันที่</label>
                <input type="date" value={newConfig.dueDate} onChange={(e) => setNewConfig({...newConfig, dueDate: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold" />
              </div>
              <button onClick={handleAddConfig} className="w-full py-4 bg-blue-600 text-white rounded-xl font-black shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all font-heading">บันทึกโครงสร้าง</button>
            </div>
          </div>

          <div className="lg:col-span-2 bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
             <div className="p-6 border-b bg-slate-50/50 flex items-center gap-3">
                <Layers className="text-indigo-600" size={20} />
                <h3 className="text-lg font-bold font-heading">โครงสร้างค่าเทอมรายบล็อก</h3>
             </div>
             <div className="overflow-x-auto">
               <table className="w-full text-left">
                 <thead className="bg-slate-50">
                   <tr>
                     <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">บล็อก</th>
                     <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">ระดับ/แผนก</th>
                     <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">ยอดเงิน</th>
                     <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">เส้นตาย</th>
                     <th className="px-6 py-4 text-right"></th>
                   </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-100">
                   {tuitionConfigs.map(c => (
                     <tr key={c.id} className="hover:bg-slate-50">
                       <td className="px-6 py-4 font-bold text-slate-900">บล็อก {c.blockId}</td>
                       <td className="px-6 py-4">
                         <p className="text-xs font-bold text-slate-900">{c.level}</p>
                         <p className="text-[10px] text-slate-500">{c.department}</p>
                       </td>
                       <td className="px-6 py-4 font-black text-blue-600">{c.amount.toLocaleString()} ฿</td>
                       <td className="px-6 py-4 text-xs font-bold text-slate-600">{c.dueDate}</td>
                       <td className="px-6 py-4 text-right">
                         <button onClick={() => setTuitionConfigs(prev => prev.filter(item => item.id !== c.id))} className="text-slate-400 hover:text-red-600"><Trash2 size={16} /></button>
                       </td>
                     </tr>
                   ))}
                 </tbody>
               </table>
             </div>
          </div>
        </div>
      )}

      {activeTab === 'payment' && (
