        <button onClick={() => setActiveTab('history')} className={`px-8 py-3 rounded-xl text-sm font-bold transition-all font-heading ${activeTab === 'history' ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>ประวัติรายรับ</button>
