import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord } from '../types';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor, children }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-shadow group relative overflow-hidden">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
    {children}
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  behavior, 
  user, 
  studyBlocks,
  tuitionConfigs = [],
  paymentRecords = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [copySuccess, setCopySuccess] = useState(false);
  const [showBankInfo, setShowBankInfo] = useState(false);

  const handleCopyAccount = () => {
    navigator.clipboard.writeText("8070863714");
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const renderIndividualView = (studentId: string) => {
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return null;

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;

    const activeBlocks = studyBlocks.filter(b => b.isActive && b.startDate && b.endDate);
    const actualPresent = attendance.filter(a => 
      a.studentId === student.id && 
      a.type === 'MORNING' && 
      a.status === 'PRESENT' &&
      activeBlocks.some(block => a.date >= block.startDate && a.date <= block.endDate)
    ).length;

    const holidayDays = activeBlocks.reduce((acc, block) => acc + (Array.isArray(block.holidays) ? block.holidays.length : 0), 0);
    const blockScore = (((actualPresent + holidayDays) * 5) / 18).toFixed(1);

    // Calculate All Remaining Tuition
    const configs = tuitionConfigs.filter(c => c.level === student.level && c.department === student.department);
    const totalTuitionAmount = configs.reduce((sum, c) => sum + c.amount, 0);
    const totalPaid = paymentRecords
      .filter(p => p.studentId === student.id && configs.some(c => c.id === p.configId))
      .reduce((sum, p) => sum + p.amount, 0);

    const remainingTotal = Math.max(0, totalTuitionAmount - totalPaid);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-bold text-sm hover:bg-slate-50 transition-all shadow-sm font-heading">
              <ArrowLeft size={18} /> กลับสู่ภาพรวม
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">{user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}</p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-100">
              <User size={24} />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าเรียน" value={`${attRate}%`} sub={`จากทั้งหมด ${studentAttendance.length} รายการ`} icon={<TrendingUp size={28} />} color="bg-blue-600" textColor="text-blue-600" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore} / 5.0`} sub={`บล็อกคอร์สปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard 
            title="ยอดค้างชำระทั้งหมด" 
            value={`${remainingTotal.toLocaleString()} ฿`} 
            sub={`สรุปยอดคงเหลือรวมทุกเทอม`} 
            icon={<Wallet size={28} />} 
            color={remainingTotal > 0 ? "bg-red-500" : "bg-green-500"} 
            textColor={remainingTotal > 0 ? "text-red-600" : "text-green-600"}
          >
            {user.role === 'PARENT' && remainingTotal > 0 && (
              <button 
                onClick={() => setShowBankInfo(!showBankInfo)}
                className="mt-4 w-full py-3 bg-blue-600 text-white rounded-xl font-black text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all"
              >
                {showBankInfo ? <ChevronUp size={14} /> : <CreditCard size={14} />}
                {showBankInfo ? "ปิดข้อมูลการโอน" : "ชำระเงินตอนนี้"}
              </button>
            )}
          </StatCard>
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="ความประพฤติปัจจุบัน" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        {/* Bank Information Reveal Section */}
