const StatCard = ({ title, value, sub, icon, color, textColor, children, fullWidth }: any) => (
  <div className={`${fullWidth ? 'col-span-1 md:col-span-2 lg:col-span-2' : ''} bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-shadow group relative overflow-hidden h-fit`}>
