import React, { useState, useEffect } from 'react';
import { StudyBlock } from '../types';
import { 
  Calendar as CalendarIcon, 
  CheckCircle2, 
  Clock, 
  AlertCircle, 
  Info, 
  CalendarDays, 
  Plus, 
  Trash2, 
  Sun, 
  AlertTriangle, 
  Star, 
  Layers, 
  RefreshCw
} from 'lucide-react';

interface SystemSettingsProps {
  studyBlocks: StudyBlock[];
  setStudyBlocks: React.Dispatch<React.SetStateAction<StudyBlock[]>>;
}

const BLOCK_COLORS = [
  'bg-blue-600',
  'bg-indigo-600',
  'bg-purple-600',
  'bg-pink-600',
  'bg-emerald-600'
];

const BLOCK_TEXT_COLORS = [
  'text-blue-600',
  'text-indigo-600',
  'text-purple-600',
  'text-pink-600',
  'text-emerald-600'
];

const SystemSettings: React.FC<SystemSettingsProps> = ({ studyBlocks, setStudyBlocks }) => {
  const [newHolidayDate, setNewHolidayDate] = useState<Record<number, string>>({});
  const [deletingDate, setDeletingDate] = useState<{ blockId: number; date: string } | null>(null);

  const addBusinessDays = (startDate: Date, days: number): Date => {
    let result = new Date(startDate);
    let addedDays = 0;
    while (addedDays < days - 1) {
      result.setDate(result.getDate() + 1);
      if (result.getDay() !== 0 && result.getDay() !== 6) {
        addedDays++;
      }
    }
    return result;
  };

  const formatDate = (date: Date) => date.toISOString().split('T')[0];

  const handleAutoCalculateDates = () => {
    if (!confirm('คุณต้องการรีเซ็ตวันเริ่ม-สิ้นสุดของทุกบล็อกให้เป็น 18 วันทำการ (เริ่มวันนี้) ใช่หรือไม่?')) return;

    const newBlocks: StudyBlock[] = [];
    let currentStart = new Date();

    if (currentStart.getDay() === 0) currentStart.setDate(currentStart.getDate() + 1);
    else if (currentStart.getDay() === 6) currentStart.setDate(currentStart.getDate() + 2);

    studyBlocks.forEach((oldBlock, idx) => {
      const end = addBusinessDays(currentStart, 18);
      newBlocks.push({
        ...oldBlock,
        startDate: formatDate(currentStart),
        endDate: formatDate(end),
      });

      let nextStart = new Date(end);
      nextStart.setDate(nextStart.getDate() + 1);
      while (nextStart.getDay() === 0 || nextStart.getDay() === 6) {
        nextStart.setDate(nextStart.getDate() + 1);
      }
      currentStart = nextStart;
    });

    setStudyBlocks(newBlocks);
  };

  const countWeekdays = (startStr: string, endStr: string) => {
    if (!startStr || !endStr) return 0;
    const start = new Date(startStr);
    const end = new Date(endStr);
    let count = 0;
    const curDate = new Date(start.getTime());
    while (curDate <= end) {
      const dayOfWeek = curDate.getDay();
      if (dayOfWeek !== 0 && dayOfWeek !== 6) count++;
      curDate.setDate(curDate.getDate() + 1);
    }
    return count;
  };

  const handleUpdateBlock = (id: number, field: keyof StudyBlock, value: any) => {
    setStudyBlocks(prev => prev.map(block => 
      block.id === id ? { ...block, [field]: value } : block
    ));
  };

  const handleAddHoliday = (blockId: number) => {
    const date = newHolidayDate[blockId];
    if (!date) return;

    setStudyBlocks(prev => prev.map(block => {
      if (block.id === blockId) {
        const currentHolidays = Array.isArray(block.holidays) ? block.holidays : [];
        if (currentHolidays.includes(date)) return block;
        return { ...block, holidays: [...currentHolidays, date].sort() };
      }
      return block;
    }));
    setNewHolidayDate(prev => ({ ...prev, [blockId]: '' }));
  };

  const processRemoveHoliday = (blockId: number, date: string) => {
    setStudyBlocks(prev => prev.map(block => {
      if (block.id === blockId) {
        const currentHolidays = Array.isArray(block.holidays) ? block.holidays : [];
        return { 
          ...block, 
          holidays: currentHolidays.filter(d => d !== date) 
        };
      }
      return block;
    }));
    setDeletingDate(null);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20 max-w-7xl mx-auto">
      <div className="bg-white p-8 md:p-12 rounded-[48px] border border-slate-200 shadow-sm relative overflow-hidden">
        <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-blue-50 rounded-full blur-3xl opacity-50" />

        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-6 mb-12 relative z-10">
          <div className="flex items-center gap-6">
            <div className="p-5 bg-slate-900 rounded-[24px] text-white shadow-2xl">
              <Layers size={32} />
            </div>
            <div>
              <h2 className="text-3xl font-black text-slate-900 tracking-tight font-heading">ตั้งค่าบล็อกเรียน</h2>
              <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">กำหนดช่วงเวลาเรียนและวันหยุดพิเศษรายบล็อก</p>
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-4">
            <button 
              onClick={handleAutoCalculateDates}
              className="flex items-center gap-3 px-6 py-4 bg-amber-500 text-white rounded-2xl font-black text-xs uppercase tracking-wider shadow-lg shadow-amber-100 hover:bg-amber-600 transition-all font-heading"
            >
              <RefreshCw size={18} /> คำนวณ 18 วันใหม่อัตโนมัติ
            </button>
            <div className="flex items-center gap-3 px-6 py-3 bg-blue-50 text-blue-700 rounded-2xl border border-blue-100 shadow-sm">
              <Info size={18} />
              <span className="text-xs font-black uppercase tracking-wider">เกณฑ์ 18 วัน (ไม่รวมเสาร์-อาทิตย์)</span>
            </div>
          </div>
        </div>

        {/* Overview Timeline */}
        <div className="mb-12 p-8 bg-slate-50/50 rounded-[40px] border border-slate-100 relative">
          <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em] mb-8 flex items-center gap-2 font-heading">
            <CalendarDays size={14} /> แผนผังช่วงเวลา 5 บล็อกเรียน
          </h3>
          <div className="space-y-6">
            {studyBlocks.map((block, idx) => {
              const weekdays = countWeekdays(block.startDate, block.endDate);
              const holidaysCount = Array.isArray(block.holidays) ? block.holidays.length : 0;
              const totalDays = weekdays + holidaysCount;
              const isActive = block.isActive && block.startDate && block.endDate;
              return (
                <div key={block.id} className="flex items-center gap-6">
                  <div className="w-28 shrink-0">
                    <span className={`text-xs font-black uppercase tracking-widest font-heading ${isActive ? BLOCK_TEXT_COLORS[idx] : 'text-slate-400'}`}>
                      {block.name}
                    </span>
                  </div>
                  <div className="flex-1 h-3 bg-slate-200 rounded-full overflow-hidden relative shadow-inner">
                    {isActive && (
                      <div className={`absolute h-full ${BLOCK_COLORS[idx]} rounded-full shadow-lg transition-all duration-700`} style={{ left: '0%', width: `${Math.min(100, (totalDays / 20) * 100)}%` }} />
                    )}
                  </div>
                  <div className="w-56 text-right">
                    {isActive ? (
                      <span className={`text-[10px] font-black font-heading ${totalDays >= 18 ? 'text-green-600' : 'text-amber-600'}`}>
                        {weekdays} เรียน + {holidaysCount} หยุด = {totalDays} วัน
                      </span>
                    ) : (
                      <span className="text-[10px] font-black text-slate-300 italic">ปิดการใช้งาน</span>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Detailed Block List */}
        <div className="grid grid-cols-1 gap-12">
          {studyBlocks.map((block, idx) => {
            const weekdays = countWeekdays(block.startDate, block.endDate);
            const holidaysCount = Array.isArray(block.holidays) ? block.holidays.length : 0;
            const totalDays = weekdays + holidaysCount;
            const score = ((totalDays * 5) / 18).toFixed(1);
            const isTargetMet = totalDays >= 18;

            return (
              <div key={block.id} className={`p-8 md:p-10 rounded-[40px] border-2 transition-all duration-500 ${block.isActive ? 'bg-white border-slate-200 shadow-xl' : 'bg-slate-50/50 border-slate-100 opacity-50 grayscale'}`}>
                <div className="flex flex-col xl:flex-row items-start xl:items-center gap-10">
                  <div className="flex items-center gap-6 shrink-0 w-full xl:w-auto">
                    <div className={`w-20 h-20 rounded-3xl flex items-center justify-center font-black text-3xl shadow-2xl ${block.isActive ? BLOCK_COLORS[idx] + ' text-white' : 'bg-slate-300 text-slate-500'}`}>
                      {block.id}
                    </div>
                    <div className="flex-1">
                      <input type="text" value={block.name} onChange={(e) => handleUpdateBlock(block.id, 'name', e.target.value)} className="bg-transparent border-none font-black text-slate-900 text-2xl outline-none focus:ring-0 p-0 w-full font-heading" />
                      <div className="flex items-center gap-3 mt-2">
                        <label className="relative inline-flex items-center cursor-pointer">
                          <input type="checkbox" checked={block.isActive} onChange={(e) => handleUpdateBlock(block.id, 'isActive', e.target.checked)} className="sr-only peer" />
                          <div className="w-10 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
                        </label>
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest font-heading">เปิดใช้งานบล็อก</span>
                      </div>
                    </div>
                  </div>

                  <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-8 w-full">
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 flex items-center gap-2 font-heading"><Clock size={12} className="text-blue-500" /> วันเริ่มเรียน</label>
                      <input type="date" value={block.startDate} onChange={(e) => handleUpdateBlock(block.id, 'startDate', e.target.value)} className="w-full bg-slate-50 border-2 border-slate-100 focus:border-slate-900 rounded-[20px] px-6 py-4 font-bold text-slate-900 outline-none transition-all shadow-inner" />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 flex items-center gap-2 font-heading"><Clock size={12} className="text-pink-500" /> วันสิ้นสุดบล็อก</label>
                      <input type="date" value={block.endDate} onChange={(e) => handleUpdateBlock(block.id, 'endDate', e.target.value)} className="w-full bg-slate-50 border-2 border-slate-100 focus:border-slate-900 rounded-[20px] px-6 py-4 font-bold text-slate-900 outline-none transition-all shadow-inner" />
                    </div>
                  </div>

                  <div className="shrink-0 w-full xl:w-64 flex flex-col items-center justify-center p-6 bg-slate-900 rounded-[32px] text-white shadow-2xl">
                    <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2 flex items-center gap-1 font-heading"><Star size={10} className="text-amber-400" /> คำนวณคะแนน</p>
                    <div className="text-4xl font-black font-heading">
                      <span className={isTargetMet ? 'text-green-400' : 'text-amber-400'}>{score}</span>
                      <span className="text-sm text-slate-500 ml-1">/ 5.0</span>
                    </div>
                    <div className="flex items-center gap-1 mt-2">
                      {totalDays > 0 && (isTargetMet ? <span className="text-[10px] font-black text-green-400 uppercase">ครบเกณฑ์ ✓</span> : <span className="text-[10px] font-black text-amber-400 uppercase">{totalDays} / 18 วัน</span>)}
                    </div>
                  </div>
                </div>

                <div className="mt-8 pt-8 border-t border-slate-100">
                  <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2 font-heading">
                    <Sun size={14} className="text-amber-500" /> วันหยุดพิเศษรายบล็อก (นับเป็นวันมาเรียน)
                  </h4>

                  <div className="flex flex-wrap gap-3 mb-6">
                    {Array.isArray(block.holidays) && block.holidays.map(date => {
                      const isConfirming = deletingDate?.blockId === block.id && deletingDate?.date === date;
                      return (
                        <div key={date} className={`flex items-center gap-3 pl-5 pr-2 py-3 rounded-2xl border-2 font-bold text-sm transition-all duration-300 ${isConfirming ? 'bg-red-600 border-red-700 text-white shadow-xl' : 'bg-slate-50 border-slate-100 text-slate-700'}`}>
                          <span>{new Date(date).toLocaleDateString('th-TH', { dateStyle: 'long' })}</span>
                          <button 
                            type="button"
                            onClick={() => {
                              if (isConfirming) {
                                processRemoveHoliday(block.id, date);
                              } else {
                                setDeletingDate({ blockId: block.id, date });
                                setTimeout(() => setDeletingDate(null), 3000);
                              }
                            }}
                            className={`flex items-center justify-center h-9 px-3 rounded-xl font-black text-[10px] uppercase transition-all ${isConfirming ? 'bg-white text-red-600' : 'text-slate-300 hover:text-red-600'}`}
                          >
                            {isConfirming ? "ลบ?" : <Trash2 size={16} />}
                          </button>
                        </div>
                      );
                    })}
                  </div>

                  <div className="flex items-center gap-4 max-w-sm">
                    <input type="date" value={newHolidayDate[block.id] || ''} onChange={(e) => setNewHolidayDate(prev => ({ ...prev, [block.id]: e.target.value }))} className="flex-1 bg-slate-50 border-2 border-slate-100 rounded-xl px-5 py-3 font-bold text-slate-900 outline-none text-sm transition-all" />
                    <button type="button" onClick={() => handleAddHoliday(block.id)} className="bg-slate-900 text-white px-6 py-3 rounded-xl font-black text-xs flex items-center gap-2 shadow-lg hover:bg-black transition-all font-heading">
                      <Plus size={16} /> เพิ่มวันหยุด
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

