                            <li className="flex gap-2"><span>1.</span> โอนเงินเข้าบัญชีข้างต้น</li>
                            <li className="flex gap-2"><span>2.</span> แคปหน้าจอหลักฐานการโอน (Slip)</li>
                            <li className="flex gap-2"><span>3.</span> กดปุ่มแจ้งชำระเงินเพื่อไปที่ LINE</li>
                            <li className="flex gap-2 text-indigo-700 bg-indigo-50 p-1 rounded-md"><span>4.</span> แจ้งชื่อนักเรียน สาขา และระดับชั้นให้ชัดเจน</li>
                          </ul>
                        </div>
                        <a 
                          href={lineUrl}
                          target="_blank"
                          rel="noopener noreferrer"
