                   {b.type === 'ADD' ? '+' : '-'}{b.score}
                 </span>
              </div>
            ))}
            {behavior.filter(b => b.studentId === student.id).length === 0 && (
              <div className="py-20 text-center flex flex-col items-center opacity-30">
                <Heart size={48} className="mb-2" />
                <p className="font-bold text-sm">ยังไม่มีบันทึกพฤติกรรม</p>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  };

  if (user.role === 'PARENT') return renderIndividualView(user.studentId);
  if (viewingStudentId) return renderIndividualView(viewingStudentId);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col xl:flex-row gap-6">
        <div className="relative flex-1 group">
          <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600" size={22} />
          <input type="text" placeholder="ค้นหานักเรียนเพื่อดูข้อมูลเชิงลึก..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white border-2 border-slate-100 rounded-[28px] pl-16 pr-6 py-5 text-lg font-bold text-slate-900 outline-none focus:border-blue-500 shadow-xl shadow-slate-100/50" />
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="นักเรียนทั้งหมด" value={students.length} sub="จำนวนลงทะเบียน" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เข้าแถวเฉลี่ย" value="95%" sub="ค่าเฉลี่ยรายวัน" icon={<CheckCircle size={28} />} color="bg-green-600" />
        <StatCard title="เฝ้าระวังพฤติกรรม" value={students.filter(s => s.behaviorScore < 70).length} sub="คะแนนต่ำกว่าเกณฑ์" icon={<AlertTriangle size={28} />} color="bg-red-600" />
        <StatCard title="คะแนนเฉลี่ยรวม" value="88" sub="ความประพฤติ" icon={<Award size={28} />} color="bg-indigo-600" />
