const addBusinessDays = (startDate: Date, days: number): Date => {
  let result = new Date(startDate);
  let addedDays = 0;
  while (addedDays < days - 1) {
    result.setDate(result.getDate() + 1);
    if (result.getDay() !== 0 && result.getDay() !== 6) {
      addedDays++;
    }
  }
  return result;
};

const formatDate = (date: Date) => date.toISOString().split('T')[0];

const generateDefaultBlocks = (): StudyBlock[] => {
  const blocks: StudyBlock[] = [];
  let currentStart = new Date();
  if (currentStart.getDay() === 0) currentStart.setDate(currentStart.getDate() + 1);
  else if (currentStart.getDay() === 6) currentStart.setDate(currentStart.getDate() + 2);
  for (let i = 1; i <= 5; i++) {
    const end = addBusinessDays(currentStart, 18);
    blocks.push({
      id: i,
      name: `บล็อกที่ ${i}`,
      startDate: formatDate(currentStart),
      endDate: formatDate(end),
      isActive: i === 1,
      holidays: []
    });
    let nextStart = new Date(end);
    nextStart.setDate(nextStart.getDate() + 1);
    while (nextStart.getDay() === 0 || nextStart.getDay() === 6) {
      nextStart.setDate(nextStart.getDate() + 1);
    }
    currentStart = nextStart;
  }
  return blocks;
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeMenu, setActiveMenu] = useState('dashboard');
  const [isInitialLoaded, setIsInitialLoaded] = useState(false);

  const [students, setStudents] = useState<Student[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [behaviorRecords, setBehaviorRecords] = useState<BehaviorRecord[]>([]);
  const [notifications, setNotifications] = useState<NotificationRecord[]>([]);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);
  const [systemUsers, setSystemUsers] = useState<User[]>([]);
  const [tuitionConfigs, setTuitionConfigs] = useState<TuitionConfig[]>([]);
  const [paymentRecords, setPaymentRecords] = useState<PaymentRecord[]>([]);
  const [studyBlocks, setStudyBlocks] = useState<StudyBlock[]>([]);

  // Function to trigger parent notifications
  const triggerNotification = useCallback((studentId: string, status: string, type: 'MORNING' | 'SUBJECT', subjectId?: string) => {
    if (status === 'PRESENT') return;

    const student = students.find(s => s.id === studentId);
    if (!student) return;

    const subject = subjectId ? subjects.find(sub => sub.id === subjectId) : null;
    const typeLabel = type === 'MORNING' ? 'เข้าแถวหน้าเสาธง' : `วิชา ${subject?.name || 'รายวิชา'}`;

    let statusLabel = '';
    let notifType: any = 'INFO';

    switch(status) {
      case 'ABSENT': statusLabel = 'ขาดเรียน'; notifType = 'ABSENT'; break;
      case 'LATE': statusLabel = 'มาสาย'; notifType = 'LATE'; break;
      case 'BUSINESS_LEAVE': statusLabel = 'ลากิจ'; notifType = 'LEAVE'; break;
      case 'SICK_LEAVE': statusLabel = 'ลาป่วย'; notifType = 'LEAVE'; break;
    }

    const newNotif: NotificationRecord = {
      id: `NOTIF_${Date.now()}_${Math.random()}`,
      studentId: studentId,
      title: `แจ้งเตือนการ${statusLabel}`,
      message: `นักเรียน: ${student.name} มีสถานะ "${statusLabel}" ในการ${typeLabel} วันที่ ${new Date().toLocaleDateString('th-TH')}`,
      type: notifType,
      date: new Date().toISOString().split('T')[0],
      timestamp: new Date().toLocaleTimeString('th-TH'),
      isRead: false
    };

    setNotifications(prev => [newNotif, ...prev.slice(0, 49)]);
  }, [students, subjects]);

  const handleSetAttendance = (updater: any) => {
    setAttendance(prev => {
      const next = typeof updater === 'function' ? updater(prev) : updater;
      const latestAdded = next.filter((n: any) => !prev.some((p: any) => p.id === n.id));

      latestAdded.forEach((rec: AttendanceRecord) => {
        triggerNotification(rec.studentId, rec.status, rec.type, rec.subjectId);
      });

      return next;
    });
  };

  useEffect(() => {
    const load = (key: string) => localStorage.getItem(key);
    const savedStudents = load('cms_students');
    const savedAttendance = load('cms_attendance');
    const savedBehavior = load('cms_behavior');
    const savedNotifs = load('cms_notifications');
    const savedSubjects = load('cms_subjects');
    const savedUsers = load('cms_system_users');
    const savedTuition = load('cms_tuition_configs');
    const savedPayments = load('cms_payment_records');
    const savedBlocks = load('cms_study_blocks');

    if (savedStudents) setStudents(JSON.parse(savedStudents)); else setStudents(MOCK_STUDENTS);
    if (savedAttendance) setAttendance(JSON.parse(savedAttendance)); else setAttendance(MOCK_ATTENDANCE);
    if (savedBehavior) setBehaviorRecords(JSON.parse(savedBehavior)); else setBehaviorRecords(MOCK_BEHAVIOR);
    if (savedNotifs) setNotifications(JSON.parse(savedNotifs));
    if (savedSubjects) setSubjects(JSON.parse(savedSubjects)); else setSubjects(MOCK_SUBJECTS);
    if (savedTuition) setTuitionConfigs(JSON.parse(savedTuition));
    if (savedPayments) setPaymentRecords(JSON.parse(savedPayments));
    if (savedBlocks) setStudyBlocks(JSON.parse(savedBlocks)); else setStudyBlocks(generateDefaultBlocks());

    if (savedUsers) {
      setSystemUsers(JSON.parse(savedUsers));
    } else {
      setSystemUsers([
        { id: 'A1', name: 'แอดมิน ระบบ', role: 'ADMIN', username: 'admin', password: '1234', department: 'ส่วนกลาง' },
        { id: 'T1', name: 'อ.สมพงษ์ ใจสว่าง', role: 'TEACHER', username: 'teacher', password: '1234', department: 'เทคโนโลยีสารสนเทศ' },
        { id: 'F1', name: 'ฝ่ายการเงิน', role: 'FINANCE', username: 'finance', password: '1234', department: 'ฝ่ายการเงิน' },
        { id: 'P1', name: 'คุณแม่ของนายสมชาย', role: 'PARENT', username: 'parent', password: '1234', studentId: '1' }
      ]);
    }
    setIsInitialLoaded(true);
  }, []);

  useEffect(() => {
    if (isInitialLoaded) {
      const save = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));
      save('cms_students', students);
      save('cms_attendance', attendance);
      save('cms_behavior', behaviorRecords);
      save('cms_notifications', notifications);
      save('cms_subjects', subjects);
      save('cms_system_users', systemUsers);
      save('cms_tuition_configs', tuitionConfigs);
      save('cms_payment_records', paymentRecords);
      save('cms_study_blocks', studyBlocks);
    }
  }, [students, attendance, behaviorRecords, notifications, subjects, systemUsers, tuitionConfigs, paymentRecords, studyBlocks, isInitialLoaded]);

  if (!user) return <Login onLogin={setUser} systemUsers={systemUsers} />;

  const renderContent = () => {
    switch (activeMenu) {
      case 'dashboard': return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} notifications={notifications} user={user} studyBlocks={studyBlocks} tuitionConfigs={tuitionConfigs} paymentRecords={paymentRecords} />;
      case 'students': return <StudentManagement students={students} setStudents={setStudents} />;
      case 'morning': return <MorningAttendance students={students} setStudents={setStudents} attendanceRecords={attendance} setAttendanceRecords={handleSetAttendance} rooms={rooms} setRooms={setRooms} />;
      case 'subject': return <ClassAttendance students={students} setStudents={setStudents} subjects={subjects} setSubjects={setSubjects} rooms={rooms} setRooms={setRooms} attendanceRecords={attendance} setAttendanceRecords={handleSetAttendance} currentUser={user} />;
      case 'behavior': return <BehaviorSystem students={students} setStudents={setStudents} behaviorRecords={behaviorRecords} setBehaviorRecords={setBehaviorRecords} />;
      case 'tuition':
      case 'finance_report': return <TuitionSystem students={students} tuitionConfigs={tuitionConfigs} setTuitionConfigs={setTuitionConfigs} paymentRecords={paymentRecords} setPaymentRecords={setPaymentRecords} user={user} />;
      case 'line_config': return <LineConfig />;
      case 'report': return <Reports students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} />;
      case 'morning_scores': return <MorningScoreSummary students={students} attendance={attendance} studyBlocks={studyBlocks} />;
      case 'users': return <UserManagement users={systemUsers} setUsers={setSystemUsers} currentUser={user} students={students} />;
      case 'settings': return <SystemSettings studyBlocks={studyBlocks} setStudyBlocks={setStudyBlocks} />;
      default: return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} notifications={notifications} user={user} studyBlocks={studyBlocks} />;
    }
  };

  return (
    <Layout activeMenu={activeMenu} setActiveMenu={setActiveMenu} user={user} onLogout={() => setUser(null)}>
      {renderContent()}
    </Layout>
  );
};

