  Clock
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord } from '../types';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor, children, fullWidth }: any) => (
  <div className={`${fullWidth ? 'col-span-1 md:col-span-2 lg:col-span-2' : ''} bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-fit`}>
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
    {children}
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  behavior, 
  notifications = [],
  user, 
  studyBlocks,
  tuitionConfigs = [],
  paymentRecords = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [copySuccess, setCopySuccess] = useState(false);
  const [showBankInfo, setShowBankInfo] = useState(false);

  const lineUrl = localStorage.getItem('cms_line_notify_url') || "https://line.me/R/ti/p/@donbosco_surat";

  const handleCopyAccount = () => {
    navigator.clipboard.writeText("8070863714");
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const renderIndividualView = (studentId: string) => {
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return null;

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;

    const activeBlocks = studyBlocks.filter(b => b.isActive && b.startDate && b.endDate);
    const actualPresent = attendance.filter(a => 
      a.studentId === student.id && 
      a.type === 'MORNING' && 
      a.status === 'PRESENT' &&
      activeBlocks.some(block => a.date >= block.startDate && a.date <= block.endDate)
    ).length;

    const holidayDays = activeBlocks.reduce((acc, block) => acc + (Array.isArray(block.holidays) ? block.holidays.length : 0), 0);
    const blockScore = (((actualPresent + holidayDays) * 5) / 18).toFixed(1);

    const configs = tuitionConfigs.filter(c => c.level === student.level && c.department === student.department);
    const totalTuitionAmount = configs.reduce((sum, c) => sum + c.amount, 0);
    const totalPaid = paymentRecords
      .filter(p => p.studentId === student.id && configs.some(c => c.id === p.configId))
      .reduce((sum, p) => sum + p.amount, 0);

    const remainingTotal = Math.max(0, totalTuitionAmount - totalPaid);

    const studentNotifs = notifications.filter(n => n.studentId === student.id);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-bold text-sm hover:bg-slate-50 transition-all shadow-sm font-heading">
              <ArrowLeft size={18} /> กลับสู่ภาพรวม
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">{user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}</p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-100">
              <User size={24} />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 items-start">
          <StatCard title="เปอร์เซ็นต์เข้าเรียน" value={`${attRate}%`} sub={`จากทั้งหมด ${studentAttendance.length} รายการ`} icon={<TrendingUp size={28} />} color="bg-blue-600" textColor="text-blue-600" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore} / 5.0`} sub={`บล็อกคอร์สปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />

          <StatCard 
            title="ยอดค้างชำระทั้งหมด" 
            value={`${remainingTotal.toLocaleString()} ฿`} 
            sub={`สรุปยอดคงเหลือรวมทุกเทอม`} 
            icon={<Wallet size={28} />} 
            color={remainingTotal > 0 ? "bg-red-500" : "bg-green-500"} 
            textColor={remainingTotal > 0 ? "text-red-600" : "text-green-600"}
            fullWidth={showBankInfo}
          >
            {user.role === 'PARENT' && remainingTotal > 0 && (
              <div className="mt-4 space-y-4">
                <button 
                  onClick={() => setShowBankInfo(!showBankInfo)}
                  className={`w-full py-3 rounded-xl font-black text-[11px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all ${showBankInfo ? 'bg-slate-100 text-slate-600' : 'bg-blue-600 text-white shadow-lg shadow-blue-100 hover:bg-blue-700'}`}
                >
                  {showBankInfo ? <ChevronUp size={14} /> : <CreditCard size={14} />}
                  {showBankInfo ? "ย่อข้อมูล" : "ชำระเงินตอนนี้"}
                </button>

                {showBankInfo && (
                  <div className="pt-4 border-t border-slate-100 animate-in slide-in-from-top-4 duration-300">
                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                      <div className="space-y-4">
                        <div className="flex items-center gap-3 mb-2">
                           <img src="https://www.krungthai.com/Resource/Common/Images/Logo/logo_krungthai.png" alt="KTB" className="h-5 object-contain" />
                           <span className="text-[10px] font-black text-blue-800 uppercase tracking-widest">ธนาคารกรุงไทย (KTB)</span>
                        </div>
                        <div className="bg-slate-50 p-6 rounded-2xl border border-slate-100">
                           <p className="text-3xl font-black text-slate-900 tracking-widest font-heading mb-1 text-center lg:text-left">807-0-86371-4</p>
                           <p className="text-[10px] font-bold text-slate-500 uppercase text-center lg:text-left">ชื่อบัญชี: วิทยาลัยเทคโนโลยี ดอนบอสโกสุราษฎร์</p>
                           <button 
                              onClick={handleCopyAccount}
                              className={`w-full mt-4 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center justify-center gap-2 transition-all ${copySuccess ? 'bg-green-600 text-white' : 'bg-slate-900 text-white hover:bg-black'}`}
                            >
                              {copySuccess ? <Check size={14} /> : <Copy size={14} />}
                              {copySuccess ? "คัดลอกสำเร็จ" : "คัดลอกเลขบัญชี"}
                            </button>
                        </div>
                      </div>

                      <div className="space-y-4">
                        <div className="p-4 bg-blue-50 rounded-2xl border border-blue-100">
                          <h4 className="font-black text-blue-900 text-[10px] mb-3 uppercase tracking-widest flex items-center gap-2">
                            <Info size={14} /> ขั้นตอนสำคัญ
                          </h4>
                          <ul className="space-y-2 text-[10px] font-bold text-blue-800 leading-relaxed">
                            <li className="flex gap-2"><span>1.</span> โอนเงินเข้าบัญชีข้างต้น</li>
                            <li className="flex gap-2"><span>2.</span> แคปหน้าจอหลักฐานการโอน (Slip)</li>
                            <li className="flex gap-2"><span>3.</span> กดปุ่มแจ้งชำระเงินเพื่อไปที่ LINE</li>
                            <li className="flex gap-2 text-indigo-700 bg-indigo-50 p-1 rounded-md"><span>4.</span> แจ้งชื่อนักเรียน สาขา และระดับชั้นให้ชัดเจน</li>
                          </ul>
                        </div>
                        <a 
                          href={lineUrl}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="w-full h-14 bg-[#06C755] text-white rounded-xl font-black text-sm flex items-center justify-center gap-3 shadow-lg shadow-green-100 hover:scale-[1.02] transition-all"
                        >
                          แจ้งการชำระเงินทาง LINE <ExternalLink size={18} />
                        </a>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )}
          </StatCard>

          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="ความประพฤติปัจจุบัน" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* Notifications Panel */}
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm flex flex-col h-[500px]">
            <h3 className="font-bold text-slate-900 text-xl mb-6 flex items-center gap-3 font-heading">
              <Bell size={24} className="text-red-500" /> รายการแจ้งเตือนล่าสุด
            </h3>
            <div className="flex-1 overflow-y-auto space-y-4 pr-2">
              {studentNotifs.length > 0 ? studentNotifs.map(notif => (
                <div key={notif.id} className={`p-5 rounded-[24px] border-l-4 shadow-sm flex gap-4 ${
                  notif.type === 'ABSENT' ? 'bg-red-50 border-red-500' : 
                  notif.type === 'LATE' ? 'bg-amber-50 border-amber-500' : 
                  'bg-blue-50 border-blue-500'
                }`}>
                  <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 ${
                    notif.type === 'ABSENT' ? 'bg-red-500 text-white' : 
                    notif.type === 'LATE' ? 'bg-amber-500 text-white' : 
                    'bg-blue-500 text-white'
                  }`}>
                    {notif.type === 'ABSENT' ? <XCircle size={20} /> : <Clock size={20} />}
                  </div>
                  <div className="flex-1">
                    <div className="flex justify-between items-start">
                      <p className="font-black text-slate-900 text-sm">{notif.title}</p>
                      <span className="text-[9px] font-bold text-slate-400 uppercase">{notif.timestamp}</span>
                    </div>
                    <p className="text-xs text-slate-600 mt-1 font-medium leading-relaxed">{notif.message}</p>
                    <p className="text-[9px] text-slate-400 mt-2 font-bold uppercase">{notif.date}</p>
                  </div>
                </div>
              )) : (
                <div className="h-full flex flex-col items-center justify-center opacity-30 text-center">
                  <Bell size={48} className="mb-2" />
                  <p className="font-bold text-sm">ยังไม่มีรายการแจ้งเตือน</p>
                </div>
              )}
            </div>
          </div>

          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
            <h3 className="font-bold text-slate-900 text-xl mb-6 flex items-center gap-3 font-heading">
              <Award size={24} className="text-indigo-600" /> บันทึกพฤติกรรมล่าสุด
            </h3>
            <div className="space-y-4">
              {behavior.filter(b => b.studentId === student.id).slice(0, 5).map(b => (
                <div key={b.id} className="p-4 bg-slate-50 rounded-2xl flex items-center justify-between border border-slate-100">
                  <div>
                    <p className="font-bold text-slate-900 text-sm">{b.reason}</p>
                    <p className="text-[10px] font-bold text-slate-500 uppercase mt-1">{b.date}</p>
                  </div>
                  <span className={`font-black text-lg ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                    {b.type === 'ADD' ? '+' : '-'}{b.score}
                  </span>
                </div>
              ))}
              {behavior.filter(b => b.studentId === student.id).length === 0 && (
                <div className="py-20 text-center flex flex-col items-center opacity-30">
                  <Heart size={48} className="mb-2" />
                  <p className="font-bold text-sm">ยังไม่มีบันทึกพฤติกรรม</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  };

  if (user.role === 'PARENT') return renderIndividualView(user.studentId);
  if (viewingStudentId) return renderIndividualView(viewingStudentId);

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col xl:flex-row gap-6">
        <div className="relative flex-1 group">
          <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-600" size={22} />
          <input type="text" placeholder="ค้นหานักเรียนเพื่อดูข้อมูลเชิงลึก..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white border-2 border-slate-100 rounded-[28px] pl-16 pr-6 py-5 text-lg font-bold text-slate-900 outline-none focus:border-blue-500 shadow-xl shadow-slate-100/50" />
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="นักเรียนทั้งหมด" value={students.length} sub="จำนวนลงทะเบียน" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เข้าแถวเฉลี่ย" value="95%" sub="ค่าเฉลี่ยรายวัน" icon={<CheckCircle size={28} />} color="bg-green-600" />
        <StatCard title="เฝ้าระวังพฤติกรรม" value={students.filter(s => s.behaviorScore < 70).length} sub="คะแนนต่ำกว่าเกณฑ์" icon={<AlertTriangle size={28} />} color="bg-red-600" />
        <StatCard title="คะแนนเฉลี่ยรวม" value="88" sub="ความประพฤติ" icon={<Award size={28} />} color="bg-indigo-600" />
      </div>

      <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
        <h3 className="text-xl font-bold text-slate-900 mb-8 font-heading">รายชื่อนักเรียนในสังกัด</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {students.filter(s => s.name.includes(searchTerm)).map(s => (
            <button key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center gap-4 p-4 rounded-2xl border border-slate-100 hover:border-blue-500 hover:bg-blue-50 transition-all text-left group">
              <div className="w-12 h-12 bg-slate-100 rounded-xl flex items-center justify-center text-slate-400 font-bold group-hover:bg-blue-600 group-hover:text-white transition-all">{s.name.charAt(0)}</div>
              <div>
                <p className="font-bold text-slate-900 text-sm">{s.name}</p>
                <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{s.studentId}</p>
              </div>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

export type UserRole = 'ADMIN' | 'TEACHER' | 'PARENT' | 'FINANCE';

export interface User {
  id: string;
  name: string;
  role: UserRole;
  username: string;
  password: string;
  department?: string;
  studentId?: string; // สำหรับ PARENT เพื่อระบุลูก
  email?: string;
}

export type AttendanceStatus = 'PRESENT' | 'LATE' | 'ABSENT' | 'BUSINESS_LEAVE' | 'SICK_LEAVE';

/* Added missing ThaiLevel enum to fix component errors */
export enum ThaiLevel {
  VC1 = 'ปวช. 1',
  VC2 = 'ปวช. 2',
  VC3 = 'ปวช. 3',
  HVC1 = 'ปวส. 1',
  HVC2 = 'ปวส. 2'
}

/* Added missing Department enum to fix component errors */
export enum Department {
  IT = 'เทคโนโลยีสารสนเทศ',
  AUTO = 'ช่างยนต์',
  ELEC = 'ช่างไฟฟ้า',
  MECH = 'ช่างกลโรงงาน',
  ACCOUNT = 'การบัญชี'
}

export interface Student {
  id: string;
  studentId: string;
  name: string;
  level: string; 
  department: string; 
  room: string;
  behaviorScore: number;
}

export interface AttendanceRecord {
  id: string;
  studentId: string;
  date: string;
  type: 'MORNING' | 'SUBJECT';
  subjectId?: string;
  status: AttendanceStatus;
  remark?: string;
  timestamp: string;
}

export interface NotificationRecord {
  id: string;
  studentId: string;
  title: string;
  message: string;
  type: 'ABSENT' | 'LATE' | 'LEAVE' | 'INFO';
  date: string;
  timestamp: string;
  isRead: boolean;
}

export interface Subject {
  id: string;
  name: string;
  code: string;
  teacherId: string;
}

export interface BehaviorRecord {
  id: string;
  studentId: string;
  type: 'ADD' | 'DEDUCT';
  score: number;
  reason: string;
  date: string;
  recordedBy: string;
}

export interface TuitionConfig {
  id: string;
  level: string;
  department: string;
  amount: number;
  term: string; 
  blockId?: number;
  dueDate?: string;
}

export interface PaymentRecord {
  id: string;
  studentId: string;
  configId: string;
  amount: number;
  method: 'CASH' | 'TRANSFER';
  date: string;
  recordedBy: string;
  status: 'PAID' | 'PARTIAL' | 'PENDING';
}

export interface StudyBlock {
  id: number;
  name: string;
  startDate: string;
  endDate: string;
  isActive: boolean;
  holidays: string[];
}

import React, { useState } from 'react';
import { MENU_ITEMS, MENU_GROUPS } from '../constants';
import { LogOut, Menu, User, ChevronRight, Bell, Search, Settings, X, Clock, AlertCircle } from 'lucide-react';
import { NotificationRecord } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  activeMenu: string;
  setActiveMenu: (menu: string) => void;
  user: any;
  onLogout: () => void;
  notifications?: NotificationRecord[];
  setNotifications?: React.Dispatch<React.SetStateAction<NotificationRecord[]>>;
}

const Layout: React.FC<LayoutProps> = ({ 
  children, 
  activeMenu, 
  setActiveMenu, 
  user, 
  onLogout,
  notifications = [],
  setNotifications
}) => {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isNotifOpen, setIsNotifOpen] = useState(false);

  const filteredMenuItems = MENU_ITEMS.filter(item => 
    item.roles.includes(user.role)
  );

  const groups = Array.from(new Set(filteredMenuItems.map(item => item.group)));

  // กรองแจ้งเตือนเฉพาะของนักเรียนคนนั้น (ถ้าเป็นผู้ปกครอง)
  const userNotifications = user.role === 'PARENT' 
    ? notifications.filter(n => n.studentId === user.studentId)
    : notifications;

  const unreadCount = userNotifications.filter(n => !n.isRead).length;

  const handleMarkAsRead = () => {
    if (setNotifications && unreadCount > 0) {
      setNotifications(prev => prev.map(n => 
        (user.role === 'PARENT' ? n.studentId === user.studentId : true) 
          ? { ...n, isRead: true } 
          : n
      ));
    }
    setIsNotifOpen(!isNotifOpen);
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden">
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-40 md:hidden animate-in fade-in duration-300"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      <aside className={`
        fixed inset-y-0 left-0 z-50 w-[280px] bg-slate-900 text-white transform transition-all duration-500 ease-[cubic-bezier(0.4,0,0.2,1)]
        md:relative md:translate-x-0 border-r border-slate-800 shadow-2xl flex flex-col
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-8 pb-4 shrink-0">
          <div className="flex items-center gap-3 group">
            <div className="w-12 h-12 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-2xl flex items-center justify-center shadow-lg shadow-blue-500/20 group-hover:scale-110 transition-transform duration-300">
              <span className="text-xl font-bold italic tracking-tighter font-heading">ES</span>
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight leading-none font-heading">EduSmart</h1>
              <span className="text-[10px] font-semibold uppercase tracking-[0.2em] text-blue-400 opacity-90 font-heading">CMS Official</span>
            </div>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto px-4 py-6 scrollbar-hide space-y-8">
          {groups.map((groupKey) => (
            <div key={groupKey} className="space-y-2">
              <h3 className="px-4 text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3 font-heading">
                {(MENU_GROUPS as any)[groupKey]}
              </h3>
              <div className="space-y-1">
                {filteredMenuItems
                  .filter(item => item.group === groupKey)
                  .map((item) => {
                    const isActive = activeMenu === item.id;
                    return (
                      <button
                        key={item.id}
                        onClick={() => {
                          setActiveMenu(item.id);
                          setSidebarOpen(false);
                        }}
                        className={`
                          w-full group flex items-center justify-between px-4 py-3 rounded-xl transition-all duration-300 relative
                          ${isActive 
                            ? 'bg-blue-600/10 text-white' 
                            : 'text-slate-400 hover:text-white hover:bg-white/5'}
                        `}
                      >
                        <div className="flex items-center gap-4 relative z-10">
                          <div className={`
                            w-9 h-9 rounded-lg flex items-center justify-center transition-all duration-300
                            ${isActive ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-800 group-hover:bg-slate-700'}
                          `}>
                            {React.cloneElement(item.icon as React.ReactElement<any>, { size: 16 })}
                          </div>
