import React, { useState, useMemo } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Heart, Search, ArrowLeft, 
  User, Activity, Star, Wallet, CreditCard, Banknote, Bell, Clock, 
  BarChart3, Calendar, Filter, ChevronRight, LayoutGrid
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord } from '../types';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  LineChart, Line, AreaChart, Area, Cell 
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor, children }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-fit">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
    {children}
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  behavior, 
  notifications = [],
  user, 
  studyBlocks,
  tuitionConfigs = [],
  paymentRecords = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [chartMode, setChartMode] = useState<'daily' | 'weekly' | 'monthly'>('daily');
  const [filterType, setFilterType] = useState<'OVERALL' | 'ROOM' | 'INDIVIDUAL'>('OVERALL');
  const [filterRoom, setFilterRoom] = useState<string>(students[0]?.room || '1');
  const [filterStudentId, setFilterStudentId] = useState<string>('');

  // ฟังก์ชันคำนวณคะแนนสะสมบล็อกเรียน (Morning Score)
  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;

    const presentDays = attendance.filter(a => 
      a.studentId === studentId && 
      a.type === 'MORNING' && 
      a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && 
      a.date <= activeBlock.endDate
    ).length;

    const holidayDays = Array.isArray(activeBlock.holidays) ? activeBlock.holidays.length : 0;
    const total = presentDays + holidayDays;
    return Number(((total * 5) / 18).toFixed(2));
  };

  // นักเรียนเฝ้าระวัง (Watchlist)
  const behaviorWatchlist = useMemo(() => students.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 5), [students]);
  const attendanceWatchlist = useMemo(() => 
    students.map(s => ({ ...s, morningScore: getMorningScore(s.id) }))
            .filter(s => s.morningScore < 3.0)
            .sort((a,b) => a.morningScore - b.morningScore)
            .slice(0, 5)
  , [students, attendance, studyBlocks]);

  // เตรียมข้อมูลกราฟ
  const chartData = useMemo(() => {
    const today = new Date();
    const data: any[] = [];

    // กรองประวัติการเข้าเรียนตาม Filter
    const targetAttendance = attendance.filter(a => {
      if (a.type !== 'MORNING') return false;
      if (filterType === 'ROOM') {
        const student = students.find(s => s.id === a.studentId);
        return student?.room === filterRoom;
      }
      if (filterType === 'INDIVIDUAL') {
        return a.studentId === filterStudentId;
      }
      return true;
    });

    if (chartMode === 'daily') {
      for (let i = 6; i >= 0; i--) {
        const d = new Date();
        d.setDate(today.getDate() - i);
        const dateStr = d.toISOString().split('T')[0];
        const count = targetAttendance.filter(a => a.date === dateStr && a.status === 'PRESENT').length;
        data.push({ name: d.toLocaleDateString('th-TH', { weekday: 'short' }), value: count });
      }
    } else if (chartMode === 'monthly') {
      const months = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
      for (let i = 5; i >= 0; i--) {
        const m = new Date();
        m.setMonth(today.getMonth() - i);
        const monthLabel = months[m.getMonth()];
        const count = targetAttendance.filter(a => {
          const ad = new Date(a.date);
          return ad.getMonth() === m.getMonth() && ad.getFullYear() === m.getFullYear() && a.status === 'PRESENT';
        }).length;
        data.push({ name: monthLabel, value: count });
      }
    } else { // Weekly
      for (let i = 3; i >= 0; i--) {
        data.push({ name: `สัปดาห์ ${4-i}`, value: Math.floor(Math.random() * 50) + 20 }); // Mock weekly logic
      }
    }
    return data;
  }, [attendance, chartMode, filterType, filterRoom, filterStudentId, students]);

  if (user.role === 'PARENT' || viewingStudentId) {
    // โค้ดส่วน Individual View (เหมือนเดิมจากที่เคยส่งให้)
    const studentId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return null;

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-bold text-sm hover:bg-slate-50 transition-all shadow-sm font-heading">
              <ArrowLeft size={18} /> กลับสู่ภาพรวม
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">{user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}</p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-100">
              <User size={24} />
            </div>
          </div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าเรียน" value={`${attRate}%`} sub={`จากทั้งหมด ${studentAttendance.length} รายการ`} icon={<TrendingUp size={28} />} color="bg-blue-600" textColor="text-blue-600" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore} / 5.0`} sub={`บล็อกคอร์สปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="ความประพฤติปัจจุบัน" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
          <StatCard title="สถานะการเงิน" value="ปกติ" sub="ไม่มียอดค้างชำระ" icon={<Wallet size={28} />} color="bg-green-600" textColor="text-green-600" />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Upper Stats Row */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="นักเรียนทั้งหมด" value={students.length} sub="จำนวนลงทะเบียน" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เข้าแถววันนี้" value={attendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.type === 'MORNING' && a.status === 'PRESENT').length} sub="เช็คชื่อล่าสุด" icon={<CheckCircle size={28} />} color="bg-green-600" />
        <StatCard title="เฝ้าระวัง" value={behaviorWatchlist.length + attendanceWatchlist.length} sub="คะแนนต่ำกว่าเกณฑ์" icon={<AlertTriangle size={28} />} color="bg-red-600" />
        <StatCard title="คะแนนเฉลี่ย" value="88" sub="ความประพฤติวิทยาลัย" icon={<Award size={28} />} color="bg-indigo-600" />
      </div>

      {/* Main Analytics Section */}
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 mb-10">
            <div className="flex items-center gap-4">
              <div className="p-4 bg-blue-50 text-blue-600 rounded-2xl">
                <BarChart3 size={24} />
              </div>
              <div>
                <h3 className="text-xl font-black text-slate-900 font-heading">วิเคราะห์การเข้าแถว</h3>
                <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-0.5">Morning Attendance Analytics</p>
              </div>
            </div>

            <div className="flex flex-wrap items-center gap-3">
              <div className="flex bg-slate-100 p-1 rounded-xl">
                <button onClick={() => setChartMode('daily')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'daily' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>รายวัน</button>
                <button onClick={() => setChartMode('weekly')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'weekly' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>รายอาทิตย์</button>
                <button onClick={() => setChartMode('monthly')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'monthly' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>รายเดือน</button>
              </div>

              <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-xl">
                <Filter size={14} className="ml-2 text-slate-400" />
                <select value={filterType} onChange={(e) => setFilterType(e.target.value as any)} className="bg-transparent text-[10px] font-black uppercase outline-none border-none p-2 pr-6 cursor-pointer">
                  <option value="OVERALL">ภาพรวม</option>
                  <option value="ROOM">รายห้อง</option>
                  <option value="INDIVIDUAL">บุคคล</option>
                </select>
                {filterType === 'ROOM' && (
                  <select value={filterRoom} onChange={(e) => setFilterRoom(e.target.value)} className="bg-white rounded-lg px-3 py-1 text-[10px] font-black border-none shadow-sm">
                    {Array.from(new Set(students.map(s => s.room))).map(r => <option key={r} value={r}>ห้อง {r}</option>)}
                  </select>
                )}
                {filterType === 'INDIVIDUAL' && (
                  <input type="text" placeholder="รหัสนักเรียน..." value={filterStudentId} onChange={(e) => setFilterStudentId(e.target.value)} className="bg-white rounded-lg px-3 py-1 text-[10px] font-black w-24 border-none shadow-sm" />
                )}
              </div>
            </div>
          </div>

          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} />
                <Tooltip 
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', padding: '12px' }}
                  labelStyle={{ fontWeight: 900, fontSize: '12px', color: '#1e293b', marginBottom: '4px' }}
                />
                <Area type="monotone" dataKey="value" stroke="#2563eb" strokeWidth={4} fillOpacity={1} fill="url(#colorValue)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="space-y-6">
          {/* Behavior Watchlist */}
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest mb-6 flex items-center gap-2 font-heading">
              <AlertTriangle size={16} className="text-red-500" /> เฝ้าระวัง: พฤติกรรมต่ำ
            </h4>
            <div className="space-y-3">
              {behaviorWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-red-50/50 rounded-2xl border border-red-100/50 hover:bg-red-50 cursor-pointer transition-all group">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-red-100 rounded-xl flex items-center justify-center text-red-600 font-black text-xs">{s.name.charAt(0)}</div>
                    <div>
                      <p className="text-xs font-bold text-slate-900 group-hover:text-red-700 transition-colors">{s.name}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase">{s.studentId}</p>
                    </div>
                  </div>
                  <span className="text-sm font-black text-red-600">{s.behaviorScore}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Attendance Watchlist */}
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest mb-6 flex items-center gap-2 font-heading">
              <Clock size={16} className="text-amber-500" /> เฝ้าระวัง: เข้าแถวน้อย
            </h4>
            <div className="space-y-3">
              {attendanceWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-amber-50/50 rounded-2xl border border-amber-100/50 hover:bg-amber-50 cursor-pointer transition-all group">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-amber-100 rounded-xl flex items-center justify-center text-amber-600 font-black text-xs">{s.name.charAt(0)}</div>
                    <div>
                      <p className="text-xs font-bold text-slate-900 group-hover:text-amber-700 transition-colors">{s.name}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase">{s.studentId}</p>
                    </div>
                  </div>
                  <span className="text-sm font-black text-amber-600">{s.morningScore}</span>
                </div>
              ))}
              {attendanceWatchlist.length === 0 && (
                <div className="py-8 text-center opacity-30">
                  <CheckCircle size={32} className="mx-auto mb-2 text-green-500" />
                  <p className="text-[10px] font-black uppercase">ยังไม่มีนักเรียนกลุ่มเสี่ยง</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord, ThaiLevel, Department } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-fit">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks 
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [chartMode, setChartMode] = useState<'daily' | 'weekly' | 'monthly'>('daily');

  // Filters สำหรับทั้ง Dashboard
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  // กรองนักเรียนตามเงื่อนไขที่เลือก
  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  // ฟังก์ชันคำนวณคะแนนสะสมบล็อกเรียน (Morning Score)
  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;

    const presentDays = attendance.filter(a => 
      a.studentId === studentId && 
      a.type === 'MORNING' && 
      a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && 
      a.date <= activeBlock.endDate
    ).length;

    const holidayDays = Array.isArray(activeBlock.holidays) ? activeBlock.holidays.length : 0;
    const total = presentDays + holidayDays;
    return Number(((total * 5) / 18).toFixed(2));
  };

  // นักเรียนเฝ้าระวัง (Watchlist) กรองตามสาขาและระดับที่เลือก
  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase
      .filter(s => s.behaviorScore < 70)
      .sort((a,b) => a.behaviorScore - b.behaviorScore)
      .slice(0, 6)
  , [filteredStudentsBase]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudentsBase
      .map(s => ({ ...s, morningScore: getMorningScore(s.id) }))
      .filter(s => s.morningScore < 3.0)
      .sort((a,b) => a.morningScore - b.morningScore)
      .slice(0, 6)
  , [filteredStudentsBase, attendance, studyBlocks]);

  // ข้อมูลกราฟ กรองตามเงื่อนไข
  const chartData = useMemo(() => {
    const today = new Date();
    const data: any[] = [];
    const studentIds = new Set(filteredStudentsBase.map(s => s.id));

    const targetAttendance = attendance.filter(a => 
      a.type === 'MORNING' && studentIds.has(a.studentId)
    );

    if (chartMode === 'daily') {
      for (let i = 6; i >= 0; i--) {
        const d = new Date();
        d.setDate(today.getDate() - i);
        const dateStr = d.toISOString().split('T')[0];
        const count = targetAttendance.filter(a => a.date === dateStr && a.status === 'PRESENT').length;
        data.push({ name: d.toLocaleDateString('th-TH', { weekday: 'short' }), value: count });
      }
    } else if (chartMode === 'monthly') {
      const months = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
      for (let i = 5; i >= 0; i--) {
        const m = new Date();
        m.setMonth(today.getMonth() - i);
        const monthLabel = months[m.getMonth()];
        const count = targetAttendance.filter(a => {
          const ad = new Date(a.date);
          return ad.getMonth() === m.getMonth() && ad.getFullYear() === m.getFullYear() && a.status === 'PRESENT';
        }).length;
        data.push({ name: monthLabel, value: count });
      }
    } else {
      for (let i = 3; i >= 0; i--) {
        data.push({ name: `สัปดาห์ ${4-i}`, value: Math.floor(Math.random() * 50) + 10 });
      }
    }
    return data;
  }, [attendance, chartMode, filteredStudentsBase]);

  if (user.role === 'PARENT' || viewingStudentId) {
    const studentId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return null;

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-bold text-sm hover:bg-slate-50 transition-all shadow-sm font-heading">
              <ArrowLeft size={18} /> กลับสู่ภาพรวม
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">{user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}</p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <User size={24} />
            </div>
          </div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าเรียน" value={`${attRate}%`} sub={`จากทั้งหมด ${studentAttendance.length} รายการ`} icon={<TrendingUp size={28} />} color="bg-blue-600" textColor="text-blue-600" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore} / 5.0`} sub={`บล็อกปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="พฤติกรรมสะสม" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
          <StatCard title="สถานะการเงิน" value="ปกติ" sub="ไม่มีค้างชำระ" icon={<Wallet size={28} />} color="bg-green-600" textColor="text-green-600" />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Dashboard Filter Header */}
      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-slate-900 rounded-xl text-white">
            <Filter size={20} />
          </div>
          <div>
            <h4 className="font-black text-slate-900 text-sm font-heading">ตัวกรองวิเคราะห์ข้อมูล</h4>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">ข้อมูลเฝ้าระวังและกราฟจะปรับตามตัวกรองนี้</p>
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-4 w-full md:w-auto">
          <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-2xl border border-slate-100 flex-1 md:flex-none">
            <GraduationCap size={16} className="text-slate-400 ml-2" />
            <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="bg-transparent text-[10px] font-black uppercase outline-none border-none pr-6 cursor-pointer w-full">
              <option value="ALL">ทุกระดับชั้น</option>
              {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
            </select>
          </div>
          <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-2xl border border-slate-100 flex-1 md:flex-none">
            <Building2 size={16} className="text-slate-400 ml-2" />
            <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="bg-transparent text-[10px] font-black uppercase outline-none border-none pr-6 cursor-pointer w-full">
              <option value="ALL">ทุกแผนกวิชา</option>
              {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="นักเรียนในกลุ่ม" value={filteredStudentsBase.length} sub="ตามเงื่อนไขที่กรอง" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เข้าแถววันนี้" value={attendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.type === 'MORNING' && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="นักเรียนที่มาทัน" icon={<CheckCircle size={28} />} color="bg-green-600" />
        <StatCard title="กลุ่มเสี่ยง" value={behaviorWatchlist.length + attendanceWatchlist.length} sub="คะแนนต่ำกว่าเกณฑ์" icon={<ShieldAlert size={28} />} color="bg-red-600" />
        <StatCard title="คะแนนเฉลี่ย" value={filteredStudentsBase.length ? Math.round(filteredStudentsBase.reduce((a,b)=>a+b.behaviorScore,0)/filteredStudentsBase.length) : 0} sub="พฤติกรรมในกลุ่ม" icon={<Award size={28} />} color="bg-indigo-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 mb-10">
            <div className="flex items-center gap-4">
              <div className="p-4 bg-blue-50 text-blue-600 rounded-2xl">
                <BarChart3 size={24} />
              </div>
              <div>
                <h3 className="text-xl font-black text-slate-900 font-heading">วิเคราะห์การเข้าแถว</h3>
                <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-0.5">Morning Attendance Trend</p>
              </div>
            </div>
            <div className="flex bg-slate-100 p-1 rounded-xl">
              <button onClick={() => setChartMode('daily')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'daily' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>รายวัน</button>
              <button onClick={() => setChartMode('weekly')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'weekly' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>รายอาทิตย์</button>
              <button onClick={() => setChartMode('monthly')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'monthly' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>รายเดือน</button>
            </div>
          </div>

          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} />
                <Tooltip 
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', padding: '12px' }}
                  labelStyle={{ fontWeight: 900, fontSize: '12px', color: '#1e293b', marginBottom: '4px' }}
                />
                <Area type="monotone" dataKey="value" stroke="#2563eb" strokeWidth={4} fillOpacity={1} fill="url(#colorValue)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="space-y-6">
          {/* Behavior Watchlist */}
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <div className="flex items-center justify-between mb-6">
              <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest flex items-center gap-2 font-heading">
                <AlertTriangle size={16} className="text-red-500" /> คะแนนพฤติกรรมต่ำ
              </h4>
              <span className="text-[10px] font-black text-slate-400">ต่ำกว่า 70</span>
            </div>
            <div className="space-y-3">
              {behaviorWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border-l-4 border-l-red-500 hover:bg-slate-100 cursor-pointer transition-all group">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-slate-900 font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                    <div>
                      <p className="text-xs font-bold text-slate-900 truncate max-w-[120px]">{s.name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{s.department}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="text-sm font-black text-red-600">{s.behaviorScore}</span>
                    <ChevronRight size={14} className="text-slate-300 ml-2 inline" />
                  </div>
                </div>
              ))}
              {behaviorWatchlist.length === 0 && (
                <p className="text-center py-8 text-[10px] font-black text-slate-300 uppercase italic">ไม่มีข้อมูลกลุ่มเสี่ยง</p>
              )}
            </div>
          </div>

          {/* Attendance Watchlist */}
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <div className="flex items-center justify-between mb-6">
              <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest flex items-center gap-2 font-heading">
                <Clock size={16} className="text-amber-500" /> เข้าแถวน้อย (บล็อกนี้)
              </h4>
              <span className="text-[10px] font-black text-slate-400">ต่ำกว่า 3.0</span>
            </div>
            <div className="space-y-3">
              {attendanceWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border-l-4 border-l-amber-500 hover:bg-slate-100 cursor-pointer transition-all group">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-slate-900 font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                    <div>
                      <p className="text-xs font-bold text-slate-900 truncate max-w-[120px]">{s.name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{s.level}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="text-sm font-black text-amber-600">{s.morningScore}</span>
                    <ChevronRight size={14} className="text-slate-300 ml-2 inline" />
                  </div>
                </div>
              ))}
              {attendanceWatchlist.length === 0 && (
                <p className="text-center py-8 text-[10px] font-black text-slate-300 uppercase italic">ไม่มีข้อมูลกลุ่มเสี่ยง</p>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord, ThaiLevel, Department } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-fit">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [chartMode, setChartMode] = useState<'daily' | 'weekly' | 'monthly'>('daily');

  // Dashboard Global Filters
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  // ฟังก์ชันคำนวณคะแนนสะสมบล็อกเรียน (Morning Score)
  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = attendance.filter(a => 
      a.studentId === studentId && a.type === 'MORNING' && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    const holidayDays = Array.isArray(activeBlock.holidays) ? activeBlock.holidays.length : 0;
    return Number((( (presentDays + holidayDays) * 5) / 18).toFixed(2));
  };

  // ฟังก์ชันคำนวณสถานะการเงิน
  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A' };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, r) => sum + r.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: config.amount - paid,
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  // กรองนักเรียนสำหรับภาพรวมและรายการเฝ้าระวัง
  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudentsBase
      .map(s => ({ ...s, morningScore: getMorningScore(s.id) }))
      .filter(s => s.morningScore < 3.0)
      .sort((a,b) => a.morningScore - b.morningScore)
      .slice(0, 6)
  , [filteredStudentsBase, attendance, studyBlocks]);

  const chartData = useMemo(() => {
    const today = new Date();
    const data: any[] = [];
    const studentIdsInFilter = new Set(filteredStudentsBase.map(s => s.id));
    const targetAttendance = attendance.filter(a => a.type === 'MORNING' && studentIdsInFilter.has(a.studentId));

    if (chartMode === 'daily') {
      for (let i = 6; i >= 0; i--) {
        const d = new Date(); d.setDate(today.getDate() - i);
        const ds = d.toISOString().split('T')[0];
        const count = targetAttendance.filter(a => a.date === ds && a.status === 'PRESENT').length;
        data.push({ name: d.toLocaleDateString('th-TH', { weekday: 'short' }), value: count });
      }
    } else if (chartMode === 'monthly') {
      const months = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
      for (let i = 5; i >= 0; i--) {
        const m = new Date(); m.setMonth(today.getMonth() - i);
        const count = targetAttendance.filter(a => {
          const ad = new Date(a.date);
          return ad.getMonth() === m.getMonth() && ad.getFullYear() === m.getFullYear() && a.status === 'PRESENT';
        }).length;
        data.push({ name: months[m.getMonth()], value: count });
      }
    } else {
      for (let i = 3; i >= 0; i--) data.push({ name: `สัปดาห์ ${4-i}`, value: Math.floor(Math.random() * 50) + 10 });
    }
    return data;
  }, [attendance, chartMode, filteredStudentsBase]);

  // Individual View (For Parents or Clicking a student)
  if (user.role === 'PARENT' || viewingStudentId) {
    const studentId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return (
      <div className="p-20 text-center bg-white rounded-[40px] border-2 border-dashed border-slate-100">
        <AlertTriangle size={48} className="mx-auto text-amber-500 mb-4" />
        <p className="font-black text-slate-900">ไม่พบข้อมูลนักเรียน</p>
        <button onClick={() => setViewingStudentId(null)} className="mt-4 text-blue-600 font-bold underline">กลับสู่แดชบอร์ด</button>
      </div>
    );

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-bold text-sm hover:bg-slate-50 transition-all shadow-sm font-heading">
              <ArrowLeft size={18} /> กลับสู่ภาพรวม
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">{user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}</p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <User size={24} />
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าเรียน" value={`${attRate}%`} sub={`จากทั้งหมด ${studentAttendance.length} รายการ`} icon={<TrendingUp size={28} />} color="bg-blue-600" textColor="text-blue-600" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore} / 5.0`} sub={`บล็อกปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="พฤติกรรมสะสม" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
          <StatCard 
            title="สถานะการเงิน" 
            value={finance.status === 'PAID' ? 'ชำระแล้ว' : finance.status === 'PARTIAL' ? 'ค้างบางส่วน' : 'ยังไม่ชำระ'} 
            sub={finance.status === 'PAID' ? 'ไม่มีมียอดค้าง' : `คงเหลือ ${finance.remaining.toLocaleString()} ฿`} 
            icon={<Wallet size={28} />} 
            color={finance.status === 'PAID' ? 'bg-green-600' : 'bg-red-600'} 
            textColor={finance.status === 'PAID' ? 'text-green-600' : 'text-red-600'} 
          />
        </div>

        {/* Financial Section for Individual View */}
        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex items-center gap-4 mb-8">
            <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl"><CreditCard size={24} /></div>
            <div>
               <h3 className="text-xl font-black text-slate-900 font-heading">รายละเอียดค่าเทอม</h3>
               <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Tuition Fee Details</p>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
             <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
                <p className="text-[10px] font-black text-slate-400 uppercase mb-2">ยอดเต็มตามหลักสูตร</p>
                <p className="text-2xl font-black text-slate-900">{finance.amount.toLocaleString()} ฿</p>
             </div>
             <div className="p-6 bg-green-50 rounded-3xl border border-green-100">
                <p className="text-[10px] font-black text-green-600 uppercase mb-2">ชำระแล้วรวม</p>
                <p className="text-2xl font-black text-green-700">{finance.paid.toLocaleString()} ฿</p>
             </div>
             <div className="p-6 bg-red-50 rounded-3xl border border-red-100">
                <p className="text-[10px] font-black text-red-600 uppercase mb-2">ยอดคงเหลือที่ต้องชำระ</p>
                <p className="text-2xl font-black text-red-700">{finance.remaining.toLocaleString()} ฿</p>
             </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Dashboard Filter Header */}
      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-slate-900 rounded-xl text-white">
            <Filter size={20} />
          </div>
          <div>
            <h4 className="font-black text-slate-900 text-sm font-heading">ตัวกรองวิเคราะห์ข้อมูล</h4>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">ข้อมูลเฝ้าระวังและกราฟจะปรับตามตัวกรองนี้</p>
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-4 w-full md:w-auto">
          <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-2xl border border-slate-100 flex-1 md:flex-none">
            <GraduationCap size={16} className="text-slate-400 ml-2" />
            <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="bg-transparent text-[10px] font-black uppercase outline-none border-none pr-6 cursor-pointer w-full">
              <option value="ALL">ทุกระดับชั้น</option>
              {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
            </select>
          </div>
          <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-2xl border border-slate-100 flex-1 md:flex-none">
            <Building2 size={16} className="text-slate-400 ml-2" />
            <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="bg-transparent text-[10px] font-black uppercase outline-none border-none pr-6 cursor-pointer w-full">
              <option value="ALL">ทุกแผนกวิชา</option>
              {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="นักเรียนในกลุ่ม" value={filteredStudentsBase.length} sub="ตามเงื่อนไขที่กรอง" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เข้าแถววันนี้" value={attendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.type === 'MORNING' && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="นักเรียนที่มาทัน" icon={<CheckCircle size={28} />} color="bg-green-600" />
        <StatCard title="กลุ่มเสี่ยง" value={behaviorWatchlist.length + attendanceWatchlist.length} sub="คะแนนต่ำกว่าเกณฑ์" icon={<ShieldAlert size={28} />} color="bg-red-600" />
        <StatCard title="คะแนนเฉลี่ย" value={filteredStudentsBase.length ? Math.round(filteredStudentsBase.reduce((a,b)=>a+b.behaviorScore,0)/filteredStudentsBase.length) : 0} sub="พฤติกรรมในกลุ่ม" icon={<Award size={28} />} color="bg-indigo-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 mb-10">
            <div className="flex items-center gap-4">
              <div className="p-4 bg-blue-50 text-blue-600 rounded-2xl">
                <BarChart3 size={24} />
              </div>
              <div>
                <h3 className="text-xl font-black text-slate-900 font-heading">วิเคราะห์การเข้าแถว</h3>
                <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-0.5">Morning Attendance Trend</p>
              </div>
            </div>
            <div className="flex bg-slate-100 p-1 rounded-xl">
              <button onClick={() => setChartMode('daily')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'daily' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>รายวัน</button>
              <button onClick={() => setChartMode('weekly')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'weekly' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>รายอาทิตย์</button>
              <button onClick={() => setChartMode('monthly')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'monthly' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>รายเดือน</button>
            </div>
          </div>

          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} />
                <Tooltip 
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', padding: '12px' }}
                  labelStyle={{ fontWeight: 900, fontSize: '12px', color: '#1e293b', marginBottom: '4px' }}
                />
                <Area type="monotone" dataKey="value" stroke="#2563eb" strokeWidth={4} fillOpacity={1} fill="url(#colorValue)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="space-y-6">
          {/* Behavior Watchlist */}
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <div className="flex items-center justify-between mb-6">
              <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest flex items-center gap-2 font-heading">
                <AlertTriangle size={16} className="text-red-500" /> คะแนนพฤติกรรมต่ำ
              </h4>
              <span className="text-[10px] font-black text-slate-400">ต่ำกว่า 70</span>
            </div>
            <div className="space-y-3">
              {behaviorWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border-l-4 border-l-red-500 hover:bg-slate-100 cursor-pointer transition-all group">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-slate-900 font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                    <div>
                      <p className="text-xs font-bold text-slate-900 truncate max-w-[120px]">{s.name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{s.department}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="text-sm font-black text-red-600">{s.behaviorScore}</span>
                    <ChevronRight size={14} className="text-slate-300 ml-2 inline" />
                  </div>
                </div>
              ))}
              {behaviorWatchlist.length === 0 && (
                <p className="text-center py-8 text-[10px] font-black text-slate-300 uppercase italic">ไม่มีข้อมูลกลุ่มเสี่ยง</p>
              )}
            </div>
          </div>

          {/* Attendance Watchlist */}
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <div className="flex items-center justify-between mb-6">
              <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest flex items-center gap-2 font-heading">
                <Clock size={16} className="text-amber-500" /> เข้าแถวน้อย (บล็อกนี้)
              </h4>
              <span className="text-[10px] font-black text-slate-400">ต่ำกว่า 3.0</span>
            </div>
            <div className="space-y-3">
              {attendanceWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border-l-4 border-l-amber-500 hover:bg-slate-100 cursor-pointer transition-all group">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-slate-900 font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                    <div>
                      <p className="text-xs font-bold text-slate-900 truncate max-w-[120px]">{s.name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{s.level}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="text-sm font-black text-amber-600">{s.morningScore}</span>
                    <ChevronRight size={14} className="text-slate-300 ml-2 inline" />
                  </div>
                </div>
              ))}
              {attendanceWatchlist.length === 0 && (
                <p className="text-center py-8 text-[10px] font-black text-slate-300 uppercase italic">ไม่มีข้อมูลกลุ่มเสี่ยง</p>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard, MessageCircle, ExternalLink, Bell,
  Banknote, ChevronDown, ChevronUp
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord, ThaiLevel, Department } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-fit">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [chartMode, setChartMode] = useState<'daily' | 'weekly' | 'monthly'>('daily');
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);

  // Dashboard Global Filters (Affects both charts and watchlists)
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
  }, []);

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  // ฟังก์ชันคำนวณคะแนนสะสมบล็อกเรียน (Morning Score)
  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = attendance.filter(a => 
      a.studentId === studentId && a.type === 'MORNING' && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    const holidayDays = Array.isArray(activeBlock.holidays) ? activeBlock.holidays.length : 0;
    return Number((( (presentDays + holidayDays) * 5) / 18).toFixed(2));
  };

  // ฟังก์ชันคำนวณสถานะการเงิน
  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, r) => sum + r.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: config.amount - paid,
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  // กรองนักเรียนสำหรับภาพรวมและรายการเฝ้าระวัง
  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudentsBase
      .map(s => ({ ...s, morningScore: getMorningScore(s.id) }))
      .filter(s => s.morningScore < 3.0)
      .sort((a,b) => a.morningScore - b.morningScore)
      .slice(0, 6)
  , [filteredStudentsBase, attendance, studyBlocks]);

  const chartData = useMemo(() => {
    const today = new Date();
    const data: any[] = [];
    const studentIdsInFilter = new Set(filteredStudentsBase.map(s => s.id));
    const targetAttendance = attendance.filter(a => a.type === 'MORNING' && studentIdsInFilter.has(a.studentId));

    if (chartMode === 'daily') {
      for (let i = 6; i >= 0; i--) {
        const d = new Date(); d.setDate(today.getDate() - i);
        const ds = d.toISOString().split('T')[0];
        const count = targetAttendance.filter(a => a.date === ds && a.status === 'PRESENT').length;
        data.push({ name: d.toLocaleDateString('th-TH', { weekday: 'short' }), value: count });
      }
    } else if (chartMode === 'monthly') {
      const months = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
      for (let i = 5; i >= 0; i--) {
        const m = new Date(); m.setMonth(today.getMonth() - i);
        const count = targetAttendance.filter(a => {
          const ad = new Date(a.date);
          return ad.getMonth() === m.getMonth() && ad.getFullYear() === m.getFullYear() && a.status === 'PRESENT';
        }).length;
        data.push({ name: months[m.getMonth()], value: count });
      }
    } else {
      for (let i = 3; i >= 0; i--) data.push({ name: `สัปดาห์ ${4-i}`, value: Math.floor(Math.random() * 50) + 10 });
    }
    return data;
  }, [attendance, chartMode, filteredStudentsBase]);

  // --- Individual / Parent View ---
  if (user.role === 'PARENT' || viewingStudentId) {
    const studentId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return (
      <div className="p-20 text-center bg-white rounded-[40px] border-2 border-dashed border-slate-100">
        <AlertTriangle size={48} className="mx-auto text-amber-500 mb-4" />
        <p className="font-black text-slate-900">ไม่พบข้อมูลนักเรียน</p>
        <button onClick={() => setViewingStudentId(null)} className="mt-4 text-blue-600 font-bold underline">กลับสู่แดชบอร์ด</button>
      </div>
    );

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);
    const studentNotifications = notifications.filter(n => n.studentId === student.id).slice(0, 5);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        {/* Header */}
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-bold text-sm hover:bg-slate-50 transition-all shadow-sm font-heading">
              <ArrowLeft size={18} /> กลับสู่ภาพรวม
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">{user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}</p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <User size={24} />
            </div>
          </div>
        </div>

        {/* Highlighted Debt Section */}
        {finance.remaining > 0 && (
          <div className="bg-gradient-to-r from-red-600 to-orange-600 p-8 md:p-10 rounded-[40px] text-white shadow-2xl shadow-red-200 relative overflow-hidden animate-in zoom-in-95">
            <div className="absolute top-0 right-0 p-10 opacity-10 pointer-events-none">
              <Banknote size={180} />
            </div>
            <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
              <div className="text-center md:text-left">
                <p className="text-xs font-black text-red-100 uppercase tracking-[0.3em] mb-2 opacity-80">ยอดค้างชำระปัจจุบัน</p>
                <div className="flex items-baseline justify-center md:justify-start gap-3">
                  <h2 className="text-6xl md:text-7xl font-black font-heading tracking-tighter">
                    {finance.remaining.toLocaleString()}
                  </h2>
                  <span className="text-2xl font-bold opacity-80 uppercase font-heading">บาท</span>
                </div>
                <p className="mt-3 text-sm font-bold text-red-100 opacity-70">โปรดชำระค่าเทอมเพื่อรักษาสิทธิ์การเข้าสอบและสวัสดิการของนักเรียน</p>
              </div>
              <button 
                onClick={() => setShowPaymentDetails(!showPaymentDetails)}
                className="w-full md:w-auto px-10 py-6 bg-white text-red-600 rounded-[28px] font-black text-lg uppercase tracking-widest shadow-xl hover:bg-red-50 transition-all flex items-center justify-center gap-3 active:scale-95 shadow-red-900/20"
              >
                {showPaymentDetails ? <ChevronUp /> : <CreditCard />}
                {showPaymentDetails ? 'ซ่อนรายละเอียด' : 'ชำระเงินตอนนี้'}
              </button>
            </div>
          </div>
        )}

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าเรียน" value={`${attRate}%`} sub={`จากทั้งหมด ${studentAttendance.length} รายการ`} icon={<TrendingUp size={28} />} color="bg-blue-600" textColor="text-blue-600" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore} / 5.0`} sub={`บล็อกปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="พฤติกรรมสะสม" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
          <StatCard 
            title="สถานะการเงิน" 
            value={finance.status === 'PAID' ? 'ชำระแล้ว' : finance.status === 'PARTIAL' ? 'ค้างบางส่วน' : 'ยังไม่ชำระ'} 
            sub={finance.status === 'PAID' ? 'ไม่มีมียอดค้าง' : `คงเหลือ ${finance.remaining.toLocaleString()} ฿`} 
            icon={<Wallet size={28} />} 
            color={finance.status === 'PAID' ? 'bg-green-600' : 'bg-red-600'} 
            textColor={finance.status === 'PAID' ? 'text-green-600' : 'text-red-600'} 
          />
        </div>

        {/* Conditional Financial Details Section */}
        {(showPaymentDetails || finance.remaining === 0) && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 animate-in slide-in-from-top-4 duration-500">
            <div className="lg:col-span-2 space-y-8">
              <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm relative overflow-hidden">
                <div className="flex items-center justify-between mb-8">
                  <div className="flex items-center gap-4">
                    <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl"><CreditCard size={24} /></div>
                    <div>
                      <h3 className="text-xl font-black text-slate-900 font-heading">รายละเอียดค่าเทอม</h3>
                      <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Tuition Fee Details</p>
                    </div>
                  </div>
                  {finance.remaining > 0 && (
                    <span className="px-5 py-2 bg-red-50 text-red-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-red-100">มียอดค้าง</span>
                  )}
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                  <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 text-center">
                    <p className="text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">ยอดเต็ม</p>
                    <p className="text-2xl font-black text-slate-900">{finance.amount.toLocaleString()} ฿</p>
                  </div>
                  <div className="p-6 bg-green-50 rounded-3xl border border-green-100 text-center">
                    <p className="text-[10px] font-black text-green-600 uppercase mb-2 tracking-widest">ชำระแล้ว</p>
                    <p className="text-2xl font-black text-green-700">{finance.paid.toLocaleString()} ฿</p>
                  </div>
                  <div className="p-6 bg-red-50 rounded-3xl border border-red-100 text-center">
                    <p className="text-[10px] font-black text-red-600 uppercase mb-2 tracking-widest">คงเหลือ</p>
                    <p className="text-2xl font-black text-red-700">{finance.remaining.toLocaleString()} ฿</p>
                  </div>
                </div>

                {/* Bank Account Details */}
                {finance.remaining > 0 && (
                  <div className="p-8 bg-slate-900 rounded-[32px] text-white relative overflow-hidden shadow-2xl">
                    <div className="absolute top-0 right-0 p-8 opacity-10 pointer-events-none text-white">
                      <Banknote size={120} />
                    </div>
                    <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-6">
                      <div className="text-center md:text-left">
                        <p className="text-xs font-black text-blue-400 uppercase tracking-[0.2em] mb-4">ช่องทางการโอนเงิน</p>
                        <div className="space-y-1">
                          <p className="text-lg font-bold">ธนาคารกสิกรไทย (K-Bank)</p>
                          <p className="text-3xl font-black tracking-tighter text-blue-100">012-3-45678-9</p>
                          <p className="text-sm font-medium opacity-60">ชื่อบัญชี: วิทยาลัยเทคโนโลยีอาชีวศึกษา (ส่วนกลาง)</p>
                        </div>
                      </div>
                      {lineUrl && (
                        <a 
                          href={lineUrl} 
                          target="_blank" 
                          rel="noreferrer"
                          className="flex items-center gap-3 px-8 py-4 bg-[#06C755] hover:bg-[#05b14c] text-white rounded-2xl font-black text-sm uppercase tracking-widest transition-all shadow-xl hover:scale-105"
                        >
                          <MessageCircle size={20} /> แจ้งสลิปผ่าน LINE
                        </a>
                      )}
                    </div>
                  </div>
                )}
                {finance.remaining === 0 && (
                  <div className="p-8 bg-green-50 rounded-[32px] border border-green-100 flex items-center justify-center gap-4">
                    <CheckCircle size={32} className="text-green-600" />
                    <div>
                      <p className="text-lg font-black text-green-900">ชำระเรียบร้อยแล้ว</p>
                      <p className="text-sm font-bold text-green-700 opacity-80">ขอบคุณสำหรับการชำระค่าธรรมเนียมการศึกษา</p>
                    </div>
                  </div>
                )}
              </div>
            </div>

            {/* Sidebar info */}
            <div className="space-y-8">
              <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
                <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest mb-6 font-heading">กำหนดการบล็อกปัจจุบัน</h4>
                {studyBlocks.filter(b => b.isActive).map(b => (
                  <div key={b.id} className="space-y-4">
                    <div className="flex justify-between items-center text-sm">
                      <span className="text-slate-500 font-bold">วันเริ่ม:</span>
                      <span className="font-black text-slate-900">{new Date(b.startDate).toLocaleDateString('th-TH')}</span>
                    </div>
                    <div className="flex justify-between items-center text-sm">
                      <span className="text-slate-500 font-bold">วันสิ้นสุด:</span>
                      <span className="font-black text-slate-900">{new Date(b.endDate).toLocaleDateString('th-TH')}</span>
                    </div>
                    <div className="p-4 bg-amber-50 rounded-2xl border border-amber-100 mt-4">
                      <p className="text-[10px] font-black text-amber-700 uppercase tracking-widest mb-1 flex items-center gap-2">
                        <Clock size={12} /> หมายเหตุ
                      </p>
                      <p className="text-[10px] text-amber-800 font-bold leading-relaxed">คะแนนเข้าแถว 5.0 จะถูกคำนวณจากความสม่ำเสมอในบล็อกเรียนนี้</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Notifications for Parent/Student */}
        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center gap-4">
              <div className="p-4 bg-blue-50 text-blue-600 rounded-2xl"><Bell size={24} /></div>
              <div>
                <h3 className="text-xl font-black text-slate-900 font-heading">รายการแจ้งเตือนล่าสุด</h3>
                <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Recent Notifications</p>
              </div>
            </div>
          </div>
          <div className="space-y-4">
            {studentNotifications.length > 0 ? studentNotifications.map(n => (
              <div key={n.id} className="p-5 bg-slate-50 rounded-[28px] border border-slate-100 flex gap-5 items-start">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shrink-0 shadow-sm ${
                  n.type === 'ABSENT' ? 'bg-red-500 text-white' : 
                  n.type === 'LATE' ? 'bg-amber-500 text-white' : 'bg-blue-500 text-white'
                }`}>
                  <Bell size={20} />
                </div>
                <div>
                  <div className="flex items-center gap-3 mb-1">
                    <p className="font-black text-slate-900">{n.title}</p>
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{n.date}</span>
                  </div>
                  <p className="text-sm text-slate-600 leading-relaxed font-bold">{n.message}</p>
                </div>
              </div>
            )) : (
              <div className="py-10 text-center opacity-30">
                <CheckCircle size={48} className="mx-auto mb-4" />
                <p className="text-xs font-black uppercase tracking-widest">ไม่พบรายการแจ้งเตือนใหม่</p>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  // --- Admin / Staff View ---
  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Dashboard Global Filter Header */}
      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-slate-900 rounded-xl text-white">
            <Filter size={20} />
          </div>
          <div>
            <h4 className="font-black text-slate-900 text-sm font-heading">ตัวกรองวิเคราะห์ข้อมูล</h4>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">ข้อมูลเฝ้าระวังและกราฟจะปรับตามตัวกรองนี้</p>
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-4 w-full md:w-auto">
          <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-2xl border border-slate-100 flex-1 md:flex-none">
            <GraduationCap size={16} className="text-slate-400 ml-2" />
            <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="bg-transparent text-[10px] font-black uppercase outline-none border-none pr-6 cursor-pointer w-full">
              <option value="ALL">ทุกระดับชั้น</option>
              {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
            </select>
          </div>
          <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-2xl border border-slate-100 flex-1 md:flex-none">
            <Building2 size={16} className="text-slate-400 ml-2" />
            <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="bg-transparent text-[10px] font-black uppercase outline-none border-none pr-6 cursor-pointer w-full">
              <option value="ALL">ทุกแผนกวิชา</option>
              {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="นักเรียนในกลุ่ม" value={filteredStudentsBase.length} sub="ตามเงื่อนไขที่กรอง" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เข้าแถววันนี้" value={attendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.type === 'MORNING' && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="นักเรียนที่มาทัน" icon={<CheckCircle size={28} />} color="bg-green-600" />
        <StatCard title="กลุ่มเสี่ยง" value={behaviorWatchlist.length + attendanceWatchlist.length} sub="คะแนนต่ำกว่าเกณฑ์" icon={<ShieldAlert size={28} />} color="bg-red-600" />
        <StatCard title="คะแนนเฉลี่ย" value={filteredStudentsBase.length ? Math.round(filteredStudentsBase.reduce((a,b)=>a+b.behaviorScore,0)/filteredStudentsBase.length) : 0} sub="พฤติกรรมในกลุ่ม" icon={<Award size={28} />} color="bg-indigo-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-6 mb-10">
            <div className="flex items-center gap-4">
              <div className="p-4 bg-blue-50 text-blue-600 rounded-2xl">
                <BarChart3 size={24} />
              </div>
              <div>
                <h3 className="text-xl font-black text-slate-900 font-heading">วิเคราะห์การเข้าแถว</h3>
                <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-0.5">Morning Attendance Trend</p>
              </div>
            </div>
            <div className="flex bg-slate-100 p-1 rounded-xl">
              <button onClick={() => setChartMode('daily')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'daily' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>รายวัน</button>
              <button onClick={() => setChartMode('weekly')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'weekly' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>รายอาทิตย์</button>
              <button onClick={() => setChartMode('monthly')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'monthly' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>รายเดือน</button>
            </div>
          </div>

          <div className="h-[350px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#2563eb" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#2563eb" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} dy={10} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} />
                <Tooltip 
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', padding: '12px' }}
                  labelStyle={{ fontWeight: 900, fontSize: '12px', color: '#1e293b', marginBottom: '4px' }}
                />
                <Area type="monotone" dataKey="value" stroke="#2563eb" strokeWidth={4} fillOpacity={1} fill="url(#colorValue)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <div className="flex items-center justify-between mb-6">
              <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest flex items-center gap-2 font-heading">
                <AlertTriangle size={16} className="text-red-500" /> คะแนนพฤติกรรมต่ำ
              </h4>
              <span className="text-[10px] font-black text-slate-400">ต่ำกว่า 70</span>
            </div>
            <div className="space-y-3">
              {behaviorWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border-l-4 border-l-red-500 hover:bg-slate-100 cursor-pointer transition-all group">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-slate-900 font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                    <div>
                      <p className="text-xs font-bold text-slate-900 truncate max-w-[120px]">{s.name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{s.department}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="text-sm font-black text-red-600">{s.behaviorScore}</span>
                    <ChevronRight size={14} className="text-slate-300 ml-2 inline" />
                  </div>
                </div>
              ))}
              {behaviorWatchlist.length === 0 && (
                <p className="text-center py-8 text-[10px] font-black text-slate-300 uppercase italic">ไม่มีข้อมูลกลุ่มเสี่ยงในเงื่อนไขนี้</p>
              )}
            </div>
          </div>

          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <div className="flex items-center justify-between mb-6">
              <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest flex items-center gap-2 font-heading">
                <Clock size={16} className="text-amber-500" /> เข้าแถวน้อย (บล็อกนี้)
              </h4>
              <span className="text-[10px] font-black text-slate-400">ต่ำกว่า 3.0</span>
            </div>
            <div className="space-y-3">
              {attendanceWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border-l-4 border-l-amber-500 hover:bg-slate-100 cursor-pointer transition-all group">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-slate-900 font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                    <div>
                      <p className="text-xs font-bold text-slate-900 truncate max-w-[120px]">{s.name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{s.level}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <span className="text-sm font-black text-amber-600">{s.morningScore}</span>
                    <ChevronRight size={14} className="text-slate-300 ml-2 inline" />
                  </div>
                </div>
              ))}
              {attendanceWatchlist.length === 0 && (
                <p className="text-center py-8 text-[10px] font-black text-slate-300 uppercase italic">ไม่มีข้อมูลกลุ่มเสี่ยงในเงื่อนไขนี้</p>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard, MessageCircle, ExternalLink, Bell,
  Banknote, ChevronDown, ChevronUp
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord, ThaiLevel, Department } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-fit">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [chartMode, setChartMode] = useState<'daily' | 'weekly' | 'monthly'>('daily');
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);

  // Dashboard Global Filters
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
  }, []);

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = attendance.filter(a => 
      a.studentId === studentId && a.type === 'MORNING' && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    const holidayDays = Array.isArray(activeBlock.holidays) ? activeBlock.holidays.length : 0;
    return Number((( (presentDays + holidayDays) * 5) / 18).toFixed(2));
  };

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, r) => sum + r.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudentsBase
      .map(s => ({ ...s, morningScore: getMorningScore(s.id) }))
      .filter(s => s.morningScore < 3.0)
      .sort((a,b) => a.morningScore - b.morningScore)
      .slice(0, 6)
  , [filteredStudentsBase, attendance, studyBlocks]);

  const chartData = useMemo(() => {
    const today = new Date();
    const data: any[] = [];
    const studentIdsInFilter = new Set(filteredStudentsBase.map(s => s.id));
    const targetAttendance = attendance.filter(a => a.type === 'MORNING' && studentIdsInFilter.has(a.studentId));

    if (chartMode === 'daily') {
      for (let i = 6; i >= 0; i--) {
        const d = new Date(); d.setDate(today.getDate() - i);
        const ds = d.toISOString().split('T')[0];
        const count = targetAttendance.filter(a => a.date === ds && a.status === 'PRESENT').length;
        data.push({ name: d.toLocaleDateString('th-TH', { weekday: 'short' }), value: count });
      }
    } else if (chartMode === 'monthly') {
      const months = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
      for (let i = 5; i >= 0; i--) {
        const m = new Date(); m.setMonth(today.getMonth() - i);
        const count = targetAttendance.filter(a => {
          const ad = new Date(a.date);
          return ad.getMonth() === m.getMonth() && ad.getFullYear() === m.getFullYear() && a.status === 'PRESENT';
        }).length;
        data.push({ name: months[m.getMonth()], value: count });
      }
    } else {
      for (let i = 3; i >= 0; i--) data.push({ name: `สัปดาห์ ${4-i}`, value: Math.floor(Math.random() * 50) + 10 });
    }
    return data;
  }, [attendance, chartMode, filteredStudentsBase]);

  if (user.role === 'PARENT' || viewingStudentId) {
    const studentId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return (
      <div className="p-20 text-center bg-white rounded-[40px] border-2 border-dashed border-slate-100">
        <AlertTriangle size={48} className="mx-auto text-amber-500 mb-4" />
        <p className="font-black text-slate-900">ไม่พบข้อมูลนักเรียน</p>
        <button onClick={() => setViewingStudentId(null)} className="mt-4 text-blue-600 font-bold underline">กลับสู่แดชบอร์ด</button>
      </div>
    );

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);
    const studentNotifications = notifications.filter(n => n.studentId === student.id).slice(0, 3);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
        {/* Header */}
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-bold text-sm hover:bg-slate-50 transition-all shadow-sm font-heading">
              <ArrowLeft size={18} /> กลับสู่ภาพรวม
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">{user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}</p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <User size={24} />
            </div>
          </div>
        </div>

        {/* 1. Notifications at the TOP */}
        <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-black text-slate-900 font-heading uppercase tracking-widest flex items-center gap-2">
              <Bell size={18} className="text-blue-600" /> แจ้งเตือนล่าสุด
            </h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {studentNotifications.length > 0 ? studentNotifications.map(n => (
              <div key={n.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex gap-4 items-start relative overflow-hidden">
                <div className={`w-2 h-full absolute left-0 top-0 ${n.type === 'ABSENT' ? 'bg-red-500' : n.type === 'LATE' ? 'bg-amber-500' : 'bg-blue-500'}`} />
                <div className="ml-2">
                  <p className="font-black text-slate-900 text-xs truncate mb-1">{n.title}</p>
                  <p className="text-[10px] text-slate-600 line-clamp-2 font-bold leading-relaxed">{n.message}</p>
                </div>
              </div>
            )) : (
              <div className="col-span-3 py-4 text-center text-[10px] font-black text-slate-300 uppercase tracking-widest">ไม่มีการแจ้งเตือนใหม่</div>
            )}
          </div>
        </div>

        {/* 2. High Impact Debt Highlight (Keep if remaining > 0) */}
        {finance.remaining > 0 && (
          <div className="bg-gradient-to-r from-red-600 to-orange-600 p-8 rounded-[40px] text-white shadow-2xl relative overflow-hidden">
            <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
              <div className="text-center md:text-left">
                <p className="text-xs font-black text-red-100 uppercase tracking-[0.3em] mb-2 opacity-80">ยอดค้างชำระปัจจุบัน</p>
                <div className="flex items-baseline justify-center md:justify-start gap-3">
                  <h2 className="text-6xl font-black font-heading tracking-tighter">
                    {finance.remaining.toLocaleString()}
                  </h2>
                  <span className="text-2xl font-bold opacity-80 uppercase font-heading">บาท</span>
                </div>
              </div>
              <button 
                onClick={() => setShowPaymentDetails(!showPaymentDetails)}
                className="w-full md:w-auto px-10 py-6 bg-white text-red-600 rounded-[28px] font-black text-lg uppercase tracking-widest shadow-xl hover:bg-red-50 transition-all flex items-center justify-center gap-3"
              >
                {showPaymentDetails ? <ChevronUp /> : <CreditCard />}
                {showPaymentDetails ? 'ซ่อนรายละเอียด' : 'ชำระเงินตอนนี้'}
              </button>
            </div>
          </div>
        )}

        {/* 3. Stats Grid (Updated: Tuition replaces Financial Status) */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าเรียน" value={`${attRate}%`} sub={`จากทั้งหมด ${studentAttendance.length} รายการ`} icon={<TrendingUp size={28} />} color="bg-blue-600" textColor="text-blue-600" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore} / 5.0`} sub={`บล็อกปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="พฤติกรรมสะสม" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
          {/* แทนที่ Card สถานะการเงินเดิมด้วยยอดค้างชำระแบบชัดเจน */}
          <StatCard 
            title="ยอดค้างชำระ" 
            value={`${finance.remaining.toLocaleString()} ฿`} 
            sub={finance.status === 'PAID' ? 'ชำระครบถ้วนแล้ว' : 'รายการที่ต้องชำระ'} 
            icon={<Banknote size={28} />} 
            color={finance.remaining > 0 ? 'bg-red-600' : 'bg-green-600'} 
            textColor={finance.remaining > 0 ? 'text-red-600' : 'text-green-600'} 
          />
        </div>

        {/* Detailed Financial Panel */}
        {(showPaymentDetails || finance.remaining === 0) && (
          <div className="animate-in slide-in-from-top-4 duration-500">
            <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm relative overflow-hidden">
              <div className="flex items-center gap-4 mb-8">
                <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl"><CreditCard size={24} /></div>
                <div>
                  <h3 className="text-xl font-black text-slate-900 font-heading">รายละเอียดค่าเทอม</h3>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Financial Breakdown</p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 text-center">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-2">ยอดเต็ม</p>
                  <p className="text-2xl font-black text-slate-900">{finance.amount.toLocaleString()} ฿</p>
                </div>
                <div className="p-6 bg-green-50 rounded-3xl border border-green-100 text-center">
                  <p className="text-[10px] font-black text-green-600 uppercase mb-2">ชำระแล้ว</p>
                  <p className="text-2xl font-black text-green-700">{finance.paid.toLocaleString()} ฿</p>
                </div>
                <div className="p-6 bg-red-50 rounded-3xl border border-red-100 text-center">
                  <p className="text-[10px] font-black text-red-600 uppercase mb-2">คงเหลือ</p>
                  <p className="text-2xl font-black text-red-700">{finance.remaining.toLocaleString()} ฿</p>
                </div>
              </div>

              {finance.remaining > 0 && (
                <div className="p-8 bg-slate-900 rounded-[32px] text-white flex flex-col md:flex-row justify-between items-center gap-6">
                  <div>
                    <p className="text-xs font-black text-blue-400 uppercase tracking-widest mb-4">ช่องทางการโอนเงิน</p>
                    <p className="text-lg font-bold">ธนาคารกสิกรไทย (K-Bank)</p>
                    <p className="text-3xl font-black tracking-tighter text-blue-100">012-3-45678-9</p>
                    <p className="text-sm opacity-60">ชื่อบัญชี: วิทยาลัยเทคโนโลยีอาชีวศึกษา</p>
                  </div>
                  {lineUrl && (
                    <a href={lineUrl} target="_blank" rel="noreferrer" className="px-8 py-4 bg-[#06C755] text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:scale-105 transition-all">
                      <MessageCircle size={20} className="inline mr-2" /> แจ้งสลิปผ่าน LINE
                    </a>
                  )}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    );
  }

  // --- Admin View ---
  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-slate-900 rounded-xl text-white"><Filter size={20} /></div>
          <div>
            <h4 className="font-black text-slate-900 text-sm font-heading">ตัวกรองวิเคราะห์ข้อมูล</h4>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">สรุปภาพรวมแผนกและระดับชั้น</p>
          </div>
        </div>
        <div className="flex gap-4">
          <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="bg-slate-50 p-3 rounded-2xl text-[10px] font-black uppercase outline-none border border-slate-100">
            <option value="ALL">ทุกระดับชั้น</option>
            {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
          </select>
          <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="bg-slate-50 p-3 rounded-2xl text-[10px] font-black uppercase outline-none border border-slate-100">
            <option value="ALL">ทุกแผนกวิชา</option>
            {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="นักเรียนในกลุ่ม" value={filteredStudentsBase.length} sub="ตามเงื่อนไขที่กรอง" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เข้าแถววันนี้" value={attendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.type === 'MORNING' && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="มาทันเวลา" icon={<CheckCircle size={28} />} color="bg-green-600" />
        <StatCard title="กลุ่มเสี่ยง" value={behaviorWatchlist.length + attendanceWatchlist.length} sub="เฝ้าระวังพิเศษ" icon={<ShieldAlert size={28} />} color="bg-red-600" />
        <StatCard title="คะแนนเฉลี่ย" value={filteredStudentsBase.length ? Math.round(filteredStudentsBase.reduce((a,b)=>a+b.behaviorScore,0)/filteredStudentsBase.length) : 0} sub="พฤติกรรมเฉลี่ย" icon={<Award size={28} />} color="bg-indigo-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex justify-between items-center mb-10">
            <h3 className="text-xl font-black text-slate-900 font-heading">วิเคราะห์การเข้าเรียน</h3>
            <div className="flex bg-slate-100 p-1 rounded-xl">
              <button onClick={() => setChartMode('daily')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'daily' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>วัน</button>
              <button onClick={() => setChartMode('weekly')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'weekly' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>สัปดาห์</button>
              <button onClick={() => setChartMode('monthly')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'monthly' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>เดือน</button>
            </div>
          </div>
          <div className="h-[350px]">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs><linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#2563eb" stopOpacity={0.3}/><stop offset="95%" stopColor="#2563eb" stopOpacity={0}/></linearGradient></defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} />
                <Tooltip />
                <Area type="monotone" dataKey="value" stroke="#2563eb" strokeWidth={4} fill="url(#colorValue)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest mb-6 flex items-center gap-2 font-heading"><AlertTriangle size={16} className="text-red-500" /> พฤติกรรมต่ำ</h4>
            <div className="space-y-3">
              {behaviorWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border-l-4 border-l-red-500 cursor-pointer">
                  <p className="text-xs font-bold text-slate-900">{s.name}</p>
                  <span className="text-sm font-black text-red-600">{s.behaviorScore}</span>
                </div>
              ))}
            </div>
          </div>
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest mb-6 flex items-center gap-2 font-heading"><Clock size={16} className="text-amber-500" /> ขาดแถวบ่อย</h4>
            <div className="space-y-3">
              {attendanceWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border-l-4 border-l-amber-500 cursor-pointer">
                  <p className="text-xs font-bold text-slate-900">{s.name}</p>
                  <span className="text-sm font-black text-amber-600">{s.morningScore}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard, MessageCircle, ExternalLink, Bell,
  Banknote, ChevronDown, ChevronUp
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord, ThaiLevel, Department } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-fit">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [chartMode, setChartMode] = useState<'daily' | 'weekly' | 'monthly'>('daily');
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);

  // Dashboard Global Filters
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
  }, []);

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = attendance.filter(a => 
      a.studentId === studentId && a.type === 'MORNING' && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    const holidayDays = Array.isArray(activeBlock.holidays) ? activeBlock.holidays.length : 0;
    return Number((( (presentDays + holidayDays) * 5) / 18).toFixed(2));
  };

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, r) => sum + r.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudentsBase
      .map(s => ({ ...s, morningScore: getMorningScore(s.id) }))
      .filter(s => s.morningScore < 3.0)
      .sort((a,b) => a.morningScore - b.morningScore)
      .slice(0, 6)
  , [filteredStudentsBase, attendance, studyBlocks]);

  const chartData = useMemo(() => {
    const today = new Date();
    const data: any[] = [];
    const studentIdsInFilter = new Set(filteredStudentsBase.map(s => s.id));
    const targetAttendance = attendance.filter(a => a.type === 'MORNING' && studentIdsInFilter.has(a.studentId));

    if (chartMode === 'daily') {
      for (let i = 6; i >= 0; i--) {
        const d = new Date(); d.setDate(today.getDate() - i);
        const ds = d.toISOString().split('T')[0];
        const count = targetAttendance.filter(a => a.date === ds && a.status === 'PRESENT').length;
        data.push({ name: d.toLocaleDateString('th-TH', { weekday: 'short' }), value: count });
      }
    } else if (chartMode === 'monthly') {
      const months = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
      for (let i = 5; i >= 0; i--) {
        const m = new Date(); m.setMonth(today.getMonth() - i);
        const count = targetAttendance.filter(a => {
          const ad = new Date(a.date);
          return ad.getMonth() === m.getMonth() && ad.getFullYear() === m.getFullYear() && a.status === 'PRESENT';
        }).length;
        data.push({ name: months[m.getMonth()], value: count });
      }
    } else {
      for (let i = 3; i >= 0; i--) data.push({ name: `สัปดาห์ ${4-i}`, value: Math.floor(Math.random() * 50) + 10 });
    }
    return data;
  }, [attendance, chartMode, filteredStudentsBase]);

  // --- Individual / Parent View ---
  if (user.role === 'PARENT' || viewingStudentId) {
    const studentId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return (
      <div className="p-20 text-center bg-white rounded-[40px] border-2 border-dashed border-slate-100">
        <AlertTriangle size={48} className="mx-auto text-amber-500 mb-4" />
        <p className="font-black text-slate-900">ไม่พบข้อมูลนักเรียน</p>
        <button onClick={() => setViewingStudentId(null)} className="mt-4 text-blue-600 font-bold underline">กลับสู่แดชบอร์ด</button>
      </div>
    );

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);
    const studentNotifications = notifications.filter(n => n.studentId === student.id).slice(0, 3);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
        {/* Header */}
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-bold text-sm hover:bg-slate-50 transition-all shadow-sm font-heading">
              <ArrowLeft size={18} /> กลับสู่ภาพรวม
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">{user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}</p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <User size={24} />
            </div>
          </div>
        </div>

        {/* 1. Notifications at the TOP */}
        <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-black text-slate-900 font-heading uppercase tracking-widest flex items-center gap-2">
              <Bell size={18} className="text-blue-600" /> แจ้งเตือนล่าสุด
            </h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {studentNotifications.length > 0 ? studentNotifications.map(n => (
              <div key={n.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex gap-4 items-start relative overflow-hidden">
                <div className={`w-2 h-full absolute left-0 top-0 ${n.type === 'ABSENT' ? 'bg-red-500' : n.type === 'LATE' ? 'bg-amber-500' : 'bg-blue-500'}`} />
                <div className="ml-2">
                  <p className="font-black text-slate-900 text-xs truncate mb-1">{n.title}</p>
                  <p className="text-[10px] text-slate-600 line-clamp-2 font-bold leading-relaxed">{n.message}</p>
                </div>
              </div>
            )) : (
              <div className="col-span-3 py-4 text-center text-[10px] font-black text-slate-300 uppercase tracking-widest">ไม่มีการแจ้งเตือนใหม่</div>
            )}
          </div>
        </div>

        {/* 2. Stats Grid ( Tuition replaces Financial Status ) */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าเรียน" value={`${attRate}%`} sub={`จากทั้งหมด ${studentAttendance.length} รายการ`} icon={<TrendingUp size={28} />} color="bg-blue-600" textColor="text-blue-600" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore} / 5.0`} sub={`บล็อกปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="พฤติกรรมสะสม" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
          <StatCard 
            title="ยอดค้างชำระ" 
            value={`${finance.remaining.toLocaleString()} ฿`} 
            sub={finance.status === 'PAID' ? 'ชำระครบถ้วนแล้ว' : 'รายการที่ต้องชำระ'} 
            icon={<Banknote size={28} />} 
            color={finance.remaining > 0 ? 'bg-red-600' : 'bg-green-600'} 
            textColor={finance.remaining > 0 ? 'text-red-600' : 'text-green-600'} 
          />
        </div>

        {/* Detailed Financial Panel (Conditional) */}
        {showPaymentDetails && (
          <div className="animate-in slide-in-from-top-4 duration-500">
            <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm relative overflow-hidden">
              <div className="flex items-center gap-4 mb-8">
                <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl"><CreditCard size={24} /></div>
                <div>
                  <h3 className="text-xl font-black text-slate-900 font-heading">รายละเอียดค่าเทอม</h3>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Financial Breakdown</p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 text-center">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">ยอดเต็ม</p>
                  <p className="text-2xl font-black text-slate-900">{finance.amount.toLocaleString()} ฿</p>
                </div>
                <div className="p-6 bg-green-50 rounded-3xl border border-green-100 text-center">
                  <p className="text-[10px] font-black text-green-600 uppercase mb-2 tracking-widest">ชำระแล้ว</p>
                  <p className="text-2xl font-black text-green-700">{finance.paid.toLocaleString()} ฿</p>
                </div>
                <div className="p-6 bg-red-50 rounded-3xl border border-red-100 text-center">
                  <p className="text-[10px] font-black text-red-600 uppercase mb-2 tracking-widest">คงเหลือ</p>
                  <p className="text-2xl font-black text-red-700">{finance.remaining.toLocaleString()} ฿</p>
                </div>
              </div>

              {finance.remaining > 0 ? (
                <div className="p-8 bg-slate-900 rounded-[32px] text-white flex flex-col md:flex-row justify-between items-center gap-6">
                  <div>
                    <p className="text-xs font-black text-blue-400 uppercase tracking-widest mb-4">ช่องทางการโอนเงิน</p>
                    <p className="text-lg font-bold">ธนาคารกสิกรไทย (K-Bank)</p>
                    <p className="text-3xl font-black tracking-tighter text-blue-100">012-3-45678-9</p>
                    <p className="text-sm opacity-60">ชื่อบัญชี: วิทยาลัยเทคโนโลยีอาชีวศึกษา</p>
                  </div>
                  {lineUrl && (
                    <a href={lineUrl} target="_blank" rel="noreferrer" className="px-8 py-4 bg-[#06C755] text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:scale-105 transition-all">
                      <MessageCircle size={20} className="inline mr-2" /> แจ้งสลิปผ่าน LINE
                    </a>
                  )}
                </div>
              ) : (
                <div className="p-8 bg-green-50 rounded-[32px] border border-green-100 flex items-center justify-center gap-4">
                  <CheckCircle size={32} className="text-green-600" />
                  <p className="text-lg font-black text-green-900 font-heading">ชำระค่าเทอมครบถ้วนแล้ว</p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* 3. Debt Highlight ( At the BOTTOM ) */}
        {finance.remaining > 0 && (
          <div className="bg-gradient-to-r from-red-600 to-orange-600 p-8 md:p-10 rounded-[40px] text-white shadow-2xl relative overflow-hidden animate-in slide-in-from-bottom-6">
            <div className="absolute top-0 right-0 p-10 opacity-10 pointer-events-none">
              <Banknote size={150} />
            </div>
            <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
              <div className="text-center md:text-left">
                <p className="text-xs font-black text-red-100 uppercase tracking-[0.3em] mb-2 opacity-80">ยอดค้างชำระปัจจุบัน</p>
                <div className="flex items-baseline justify-center md:justify-start gap-3">
                  <h2 className="text-6xl md:text-7xl font-black font-heading tracking-tighter">
                    {finance.remaining.toLocaleString()}
                  </h2>
                  <span className="text-2xl font-bold opacity-80 uppercase font-heading">บาท</span>
                </div>
                <p className="mt-3 text-sm font-bold text-red-100 opacity-70">รักษาสิทธิ์การเข้าสอบและสวัสดิการของนักเรียน</p>
              </div>
              <button 
                onClick={() => setShowPaymentDetails(!showPaymentDetails)}
                className="w-full md:w-auto px-10 py-6 bg-white text-red-600 rounded-[28px] font-black text-lg uppercase tracking-widest shadow-xl hover:bg-red-50 transition-all flex items-center justify-center gap-3"
              >
                {showPaymentDetails ? <ChevronUp /> : <CreditCard />}
                {showPaymentDetails ? 'ซ่อนรายละเอียด' : 'ชำระเงินตอนนี้'}
              </button>
            </div>
          </div>
        )}
      </div>
    );
  }

  // --- Admin View ---
  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-slate-900 rounded-xl text-white"><Filter size={20} /></div>
          <div>
            <h4 className="font-black text-slate-900 text-sm font-heading">ตัวกรองวิเคราะห์ข้อมูล</h4>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">สรุปภาพรวมแผนกและระดับชั้น</p>
          </div>
        </div>
        <div className="flex gap-4">
          <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="bg-slate-50 p-3 rounded-2xl text-[10px] font-black uppercase outline-none border border-slate-100">
            <option value="ALL">ทุกระดับชั้น</option>
            {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
          </select>
          <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="bg-slate-50 p-3 rounded-2xl text-[10px] font-black uppercase outline-none border border-slate-100">
            <option value="ALL">ทุกแผนกวิชา</option>
            {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="นักเรียนในกลุ่ม" value={filteredStudentsBase.length} sub="ตามเงื่อนไขที่กรอง" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เข้าแถววันนี้" value={attendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.type === 'MORNING' && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="มาทันเวลา" icon={<CheckCircle2 size={28} />} color="bg-green-600" />
        <StatCard title="กลุ่มเสี่ยง" value={behaviorWatchlist.length + attendanceWatchlist.length} sub="เฝ้าระวังพิเศษ" icon={<ShieldAlert size={28} />} color="bg-red-600" />
        <StatCard title="คะแนนเฉลี่ย" value={filteredStudentsBase.length ? Math.round(filteredStudentsBase.reduce((a,b)=>a+b.behaviorScore,0)/filteredStudentsBase.length) : 0} sub="พฤติกรรมเฉลี่ย" icon={<Award size={28} />} color="bg-indigo-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex justify-between items-center mb-10">
            <h3 className="text-xl font-black text-slate-900 font-heading">วิเคราะห์การเข้าเรียน</h3>
            <div className="flex bg-slate-100 p-1 rounded-xl">
              <button onClick={() => setChartMode('daily')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'daily' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>วัน</button>
              <button onClick={() => setChartMode('weekly')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'weekly' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>สัปดาห์</button>
              <button onClick={() => setChartMode('monthly')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'monthly' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>เดือน</button>
            </div>
          </div>
          <div className="h-[350px]">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs><linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#2563eb" stopOpacity={0.3}/><stop offset="95%" stopColor="#2563eb" stopOpacity={0}/></linearGradient></defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} />
                <Tooltip />
                <Area type="monotone" dataKey="value" stroke="#2563eb" strokeWidth={4} fill="url(#colorValue)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest mb-6 flex items-center gap-2 font-heading"><AlertTriangle size={16} className="text-red-500" /> พฤติกรรมต่ำ</h4>
            <div className="space-y-3">
              {behaviorWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border-l-4 border-l-red-500 cursor-pointer">
                  <p className="text-xs font-bold text-slate-900">{s.name}</p>
                  <span className="text-sm font-black text-red-600">{s.behaviorScore}</span>
                </div>
              ))}
            </div>
          </div>
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest mb-6 flex items-center gap-2 font-heading"><Clock size={16} className="text-amber-500" /> ขาดแถวบ่อย</h4>
            <div className="space-y-3">
              {attendanceWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border-l-4 border-l-amber-500 cursor-pointer">
                  <p className="text-xs font-bold text-slate-900">{s.name}</p>
                  <span className="text-sm font-black text-amber-600">{s.morningScore}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard, MessageCircle, ExternalLink, Bell,
  Banknote, ChevronDown, ChevronUp, CheckCircle2
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord, ThaiLevel, Department } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-fit">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [chartMode, setChartMode] = useState<'daily' | 'weekly' | 'monthly'>('daily');
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);

  // Dashboard Global Filters
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
  }, []);

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = attendance.filter(a => 
      a.studentId === studentId && a.type === 'MORNING' && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    const holidayDays = Array.isArray(activeBlock.holidays) ? activeBlock.holidays.length : 0;
    return Number((( (presentDays + holidayDays) * 5) / 18).toFixed(2));
  };

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, r) => sum + r.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudentsBase
      .map(s => ({ ...s, morningScore: getMorningScore(s.id) }))
      .filter(s => s.morningScore < 3.0)
      .sort((a,b) => a.morningScore - b.morningScore)
      .slice(0, 6)
  , [filteredStudentsBase, attendance, studyBlocks]);

  const chartData = useMemo(() => {
    const today = new Date();
    const data: any[] = [];
    const studentIdsInFilter = new Set(filteredStudentsBase.map(s => s.id));
    const targetAttendance = attendance.filter(a => a.type === 'MORNING' && studentIdsInFilter.has(a.studentId));

    if (chartMode === 'daily') {
      for (let i = 6; i >= 0; i--) {
        const d = new Date(); d.setDate(today.getDate() - i);
        const ds = d.toISOString().split('T')[0];
        const count = targetAttendance.filter(a => a.date === ds && a.status === 'PRESENT').length;
        data.push({ name: d.toLocaleDateString('th-TH', { weekday: 'short' }), value: count });
      }
    } else if (chartMode === 'monthly') {
      const months = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
      for (let i = 5; i >= 0; i--) {
        const m = new Date(); m.setMonth(today.getMonth() - i);
        const count = targetAttendance.filter(a => {
          const ad = new Date(a.date);
          return ad.getMonth() === m.getMonth() && ad.getFullYear() === m.getFullYear() && a.status === 'PRESENT';
        }).length;
        data.push({ name: months[m.getMonth()], value: count });
      }
    } else {
      for (let i = 3; i >= 0; i--) data.push({ name: `สัปดาห์ ${4-i}`, value: Math.floor(Math.random() * 50) + 10 });
    }
    return data;
  }, [attendance, chartMode, filteredStudentsBase]);

  // --- Individual / Parent View ---
  if (user.role === 'PARENT' || viewingStudentId) {
    const studentId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return (
      <div className="p-20 text-center bg-white rounded-[40px] border-2 border-dashed border-slate-100">
        <AlertTriangle size={48} className="mx-auto text-amber-500 mb-4" />
        <p className="font-black text-slate-900">ไม่พบข้อมูลนักเรียน</p>
        <button onClick={() => setViewingStudentId(null)} className="mt-4 text-blue-600 font-bold underline">กลับสู่แดชบอร์ด</button>
      </div>
    );

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);
    const studentNotifications = notifications.filter(n => n.studentId === student.id).slice(0, 3);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
        {/* Header */}
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-bold text-sm hover:bg-slate-50 transition-all shadow-sm font-heading">
              <ArrowLeft size={18} /> กลับสู่ภาพรวม
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">{user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}</p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <User size={24} />
            </div>
          </div>
        </div>

        {/* 1. Notifications at the TOP */}
        <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-black text-slate-900 font-heading uppercase tracking-widest flex items-center gap-2">
              <Bell size={18} className="text-blue-600" /> แจ้งเตือนล่าสุด
            </h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {studentNotifications.length > 0 ? studentNotifications.map(n => (
              <div key={n.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex gap-4 items-start relative overflow-hidden">
                <div className={`w-2 h-full absolute left-0 top-0 ${n.type === 'ABSENT' ? 'bg-red-500' : n.type === 'LATE' ? 'bg-amber-500' : 'bg-blue-500'}`} />
                <div className="ml-2">
                  <p className="font-black text-slate-900 text-xs truncate mb-1">{n.title}</p>
                  <p className="text-[10px] text-slate-600 line-clamp-2 font-bold leading-relaxed">{n.message}</p>
                </div>
              </div>
            )) : (
              <div className="col-span-3 py-4 text-center text-[10px] font-black text-slate-300 uppercase tracking-widest">ไม่มีการแจ้งเตือนใหม่</div>
            )}
          </div>
        </div>

        {/* 2. Stats Grid ( Tuition replaces Financial Status ) */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าเรียน" value={`${attRate}%`} sub={`จากทั้งหมด ${studentAttendance.length} รายการ`} icon={<TrendingUp size={28} />} color="bg-blue-600" textColor="text-blue-600" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore} / 5.0`} sub={`บล็อกปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="พฤติกรรมสะสม" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
          <StatCard 
            title="ยอดค้างชำระ" 
            value={`${finance.remaining.toLocaleString()} ฿`} 
            sub={finance.status === 'PAID' ? 'ชำระครบถ้วนแล้ว' : 'รายการที่ต้องชำระ'} 
            icon={<Banknote size={28} />} 
            color={finance.remaining > 0 ? 'bg-red-600' : 'bg-green-600'} 
            textColor={finance.remaining > 0 ? 'text-red-600' : 'text-green-600'} 
          />
        </div>

        {/* Detailed Financial Panel (Conditional) */}
        {showPaymentDetails && (
          <div className="animate-in slide-in-from-top-4 duration-500">
            <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm relative overflow-hidden">
              <div className="flex items-center gap-4 mb-8">
                <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl"><CreditCard size={24} /></div>
                <div>
                  <h3 className="text-xl font-black text-slate-900 font-heading">รายละเอียดค่าเทอม</h3>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Financial Breakdown</p>
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 text-center">
                  <p className="text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">ยอดเต็ม</p>
                  <p className="text-2xl font-black text-slate-900">{finance.amount.toLocaleString()} ฿</p>
                </div>
                <div className="p-6 bg-green-50 rounded-3xl border border-green-100 text-center">
                  <p className="text-[10px] font-black text-green-600 uppercase mb-2 tracking-widest">ชำระแล้ว</p>
                  <p className="text-2xl font-black text-green-700">{finance.paid.toLocaleString()} ฿</p>
                </div>
                <div className="p-6 bg-red-50 rounded-3xl border border-red-100 text-center">
                  <p className="text-[10px] font-black text-red-600 uppercase mb-2 tracking-widest">คงเหลือ</p>
                  <p className="text-2xl font-black text-red-700">{finance.remaining.toLocaleString()} ฿</p>
                </div>
              </div>

              {finance.remaining > 0 ? (
                <div className="p-8 bg-slate-900 rounded-[32px] text-white flex flex-col md:flex-row justify-between items-center gap-6">
                  <div>
                    <p className="text-xs font-black text-blue-400 uppercase tracking-widest mb-4">ช่องทางการโอนเงิน</p>
                    <p className="text-lg font-bold">ธนาคารกสิกรไทย (K-Bank)</p>
                    <p className="text-3xl font-black tracking-tighter text-blue-100">012-3-45678-9</p>
                    <p className="text-sm opacity-60">ชื่อบัญชี: วิทยาลัยเทคโนโลยีอาชีวศึกษา</p>
                  </div>
                  {lineUrl && (
                    <a href={lineUrl} target="_blank" rel="noreferrer" className="px-8 py-4 bg-[#06C755] text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:scale-105 transition-all">
                      <MessageCircle size={20} className="inline mr-2" /> แจ้งสลิปผ่าน LINE
                    </a>
                  )}
                </div>
              ) : (
                <div className="p-8 bg-green-50 rounded-[32px] border border-green-100 flex items-center justify-center gap-4">
                  <CheckCircle size={32} className="text-green-600" />
                  <p className="text-lg font-black text-green-900 font-heading">ชำระค่าเทอมครบถ้วนแล้ว</p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* 3. Debt Highlight ( At the BOTTOM ) */}
        {finance.remaining > 0 && (
          <div className="bg-gradient-to-r from-red-600 to-orange-600 p-8 md:p-10 rounded-[40px] text-white shadow-2xl relative overflow-hidden animate-in slide-in-from-bottom-6">
            <div className="absolute top-0 right-0 p-10 opacity-10 pointer-events-none">
              <Banknote size={150} />
            </div>
            <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
              <div className="text-center md:text-left">
                <p className="text-xs font-black text-red-100 uppercase tracking-[0.3em] mb-2 opacity-80">ยอดค้างชำระปัจจุบัน</p>
                <div className="flex items-baseline justify-center md:justify-start gap-3">
                  <h2 className="text-6xl md:text-7xl font-black font-heading tracking-tighter">
                    {finance.remaining.toLocaleString()}
                  </h2>
                  <span className="text-2xl font-bold opacity-80 uppercase font-heading">บาท</span>
                </div>
                <p className="mt-3 text-sm font-bold text-red-100 opacity-70">รักษาสิทธิ์การเข้าสอบและสวัสดิการของนักเรียน</p>
              </div>
              <button 
                onClick={() => setShowPaymentDetails(!showPaymentDetails)}
                className="w-full md:w-auto px-10 py-6 bg-white text-red-600 rounded-[28px] font-black text-lg uppercase tracking-widest shadow-xl hover:bg-red-50 transition-all flex items-center justify-center gap-3"
              >
                {showPaymentDetails ? <ChevronUp /> : <CreditCard />}
                {showPaymentDetails ? 'ซ่อนรายละเอียด' : 'ชำระเงินตอนนี้'}
              </button>
            </div>
          </div>
        )}
      </div>
    );
  }

  // --- Admin View ---
  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-slate-900 rounded-xl text-white"><Filter size={20} /></div>
          <div>
            <h4 className="font-black text-slate-900 text-sm font-heading">ตัวกรองวิเคราะห์ข้อมูล</h4>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">สรุปภาพรวมแผนกและระดับชั้น</p>
          </div>
        </div>
        <div className="flex gap-4">
          <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="bg-slate-50 p-3 rounded-2xl text-[10px] font-black uppercase outline-none border border-slate-100">
            <option value="ALL">ทุกระดับชั้น</option>
            {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
          </select>
          <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="bg-slate-50 p-3 rounded-2xl text-[10px] font-black uppercase outline-none border border-slate-100">
            <option value="ALL">ทุกแผนกวิชา</option>
            {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="นักเรียนในกลุ่ม" value={filteredStudentsBase.length} sub="ตามเงื่อนไขที่กรอง" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เข้าแถววันนี้" value={attendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.type === 'MORNING' && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="มาทันเวลา" icon={<CheckCircle2 size={28} />} color="bg-green-600" />
        <StatCard title="กลุ่มเสี่ยง" value={behaviorWatchlist.length + attendanceWatchlist.length} sub="เฝ้าระวังพิเศษ" icon={<ShieldAlert size={28} />} color="bg-red-600" />
        <StatCard title="คะแนนเฉลี่ย" value={filteredStudentsBase.length ? Math.round(filteredStudentsBase.reduce((a,b)=>a+b.behaviorScore,0)/filteredStudentsBase.length) : 0} sub="พฤติกรรมเฉลี่ย" icon={<Award size={28} />} color="bg-indigo-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex justify-between items-center mb-10">
            <h3 className="text-xl font-black text-slate-900 font-heading">วิเคราะห์การเข้าเรียน</h3>
            <div className="flex bg-slate-100 p-1 rounded-xl">
              <button onClick={() => setChartMode('daily')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'daily' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>วัน</button>
              <button onClick={() => setChartMode('weekly')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'weekly' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>สัปดาห์</button>
              <button onClick={() => setChartMode('monthly')} className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-all ${chartMode === 'monthly' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500'}`}>เดือน</button>
            </div>
          </div>
          <div className="h-[350px]">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs><linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#2563eb" stopOpacity={0.3}/><stop offset="95%" stopColor="#2563eb" stopOpacity={0}/></linearGradient></defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} />
                <Tooltip />
                <Area type="monotone" dataKey="value" stroke="#2563eb" strokeWidth={4} fill="url(#colorValue)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="space-y-6">
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest mb-6 flex items-center gap-2 font-heading"><AlertTriangle size={16} className="text-red-500" /> พฤติกรรมต่ำ</h4>
            <div className="space-y-3">
              {behaviorWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border-l-4 border-l-red-500 cursor-pointer">
                  <p className="text-xs font-bold text-slate-900">{s.name}</p>
                  <span className="text-sm font-black text-red-600">{s.behaviorScore}</span>
                </div>
              ))}
            </div>
          </div>
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest mb-6 flex items-center gap-2 font-heading"><Clock size={16} className="text-amber-500" /> ขาดแถวบ่อย</h4>
            <div className="space-y-3">
              {attendanceWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border-l-4 border-l-amber-500 cursor-pointer">
                  <p className="text-xs font-bold text-slate-900">{s.name}</p>
                  <span className="text-sm font-black text-amber-600">{s.morningScore}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard, MessageCircle, ExternalLink, Bell,
  Banknote, ChevronDown, ChevronUp, CheckCircle2
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord, ThaiLevel, Department } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-fit">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [chartMode, setChartMode] = useState<'daily' | 'weekly' | 'monthly'>('daily');
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);

  // Dashboard Global Filters
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
  }, []);

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = attendance.filter(a => 
      a.studentId === studentId && a.type === 'MORNING' && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    const holidayDays = Array.isArray(activeBlock.holidays) ? activeBlock.holidays.length : 0;
    return Number((( (presentDays + holidayDays) * 5) / 18).toFixed(2));
  };

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, r) => sum + r.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudentsBase
      .map(s => ({ ...s, morningScore: getMorningScore(s.id) }))
      .filter(s => s.morningScore < 3.0)
      .sort((a,b) => a.morningScore - b.morningScore)
      .slice(0, 6)
  , [filteredStudentsBase, attendance, studyBlocks]);

  const chartData = useMemo(() => {
    const today = new Date();
    const data: any[] = [];
    const studentIdsInFilter = new Set(filteredStudentsBase.map(s => s.id));
    const targetAttendance = attendance.filter(a => a.type === 'MORNING' && studentIdsInFilter.has(a.studentId));

    if (chartMode === 'daily') {
      for (let i = 6; i >= 0; i--) {
        const d = new Date(); d.setDate(today.getDate() - i);
        const ds = d.toISOString().split('T')[0];
        const count = targetAttendance.filter(a => a.date === ds && a.status === 'PRESENT').length;
        data.push({ name: d.toLocaleDateString('th-TH', { weekday: 'short' }), value: count });
      }
    } else if (chartMode === 'monthly') {
      const months = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
      for (let i = 5; i >= 0; i--) {
        const m = new Date(); m.setMonth(today.getMonth() - i);
        const count = targetAttendance.filter(a => {
          const ad = new Date(a.date);
          return ad.getMonth() === m.getMonth() && ad.getFullYear() === m.getFullYear() && a.status === 'PRESENT';
        }).length;
        data.push({ name: months[m.getMonth()], value: count });
      }
    } else {
      for (let i = 3; i >= 0; i--) data.push({ name: `สัปดาห์ ${4-i}`, value: Math.floor(Math.random() * 50) + 10 });
    }
    return data;
  }, [attendance, chartMode, filteredStudentsBase]);

  // --- Individual / Parent View ---
  if (user.role === 'PARENT' || viewingStudentId) {
    const studentId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return (
      <div className="p-20 text-center bg-white rounded-[40px] border-2 border-dashed border-slate-100">
        <AlertTriangle size={48} className="mx-auto text-amber-500 mb-4" />
        <p className="font-black text-slate-900">ไม่พบข้อมูลนักเรียน</p>
        <button onClick={() => setViewingStudentId(null)} className="mt-4 text-blue-600 font-bold underline">กลับสู่แดชบอร์ด</button>
      </div>
    );

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);
    const studentNotifications = notifications.filter(n => n.studentId === student.id).slice(0, 3);

    return (
      <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
        {/* Header */}
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border-2 border-slate-100 rounded-2xl text-slate-600 font-bold text-sm hover:bg-slate-50 transition-all shadow-sm font-heading">
              <ArrowLeft size={18} /> กลับสู่ภาพรวม
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">{user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}</p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
              <User size={24} />
            </div>
          </div>
        </div>

        {/* 1. Notifications at the TOP */}
        <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-black text-slate-900 font-heading uppercase tracking-widest flex items-center gap-2">
              <Bell size={18} className="text-blue-600" /> แจ้งเตือนล่าสุด
            </h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {studentNotifications.length > 0 ? studentNotifications.map(n => (
              <div key={n.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex gap-4 items-start relative overflow-hidden">
                <div className={`w-2 h-full absolute left-0 top-0 ${n.type === 'ABSENT' ? 'bg-red-500' : n.type === 'LATE' ? 'bg-amber-500' : 'bg-blue-500'}`} />
                <div className="ml-2">
                  <p className="font-black text-slate-900 text-xs truncate mb-1">{n.title}</p>
                  <p className="text-[10px] text-slate-600 line-clamp-2 font-bold leading-relaxed">{n.message}</p>
                </div>
              </div>
            )) : (
              <div className="col-span-3 py-4 text-center text-[10px] font-black text-slate-300 uppercase tracking-widest">ไม่มีการแจ้งเตือนใหม่</div>
            )}
          </div>
        </div>

        {/* 2. Stats Grid (Now only 3 Cards, Debt Stat removed as requested) */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าเรียน" value={`${attRate}%`} sub={`จากทั้งหมด ${studentAttendance.length} รายการ`} icon={<TrendingUp size={28} />} color="bg-blue-600" textColor="text-blue-600" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore} / 5.0`} sub={`บล็อกปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="พฤติกรรมสะสม" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        {/* 3. Debt Highlight ( At the BOTTOM ) */}
        <div className="space-y-4">
          {finance.remaining > 0 && (
            <div className="bg-gradient-to-r from-red-600 to-orange-600 p-8 md:p-10 rounded-[40px] text-white shadow-2xl relative overflow-hidden animate-in slide-in-from-bottom-6">
              <div className="absolute top-0 right-0 p-10 opacity-10 pointer-events-none">
                <Banknote size={150} />
              </div>
              <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
                <div className="text-center md:text-left">
                  <p className="text-xs font-black text-red-100 uppercase tracking-[0.3em] mb-2 opacity-80">ยอดค้างชำระปัจจุบัน</p>
                  <div className="flex items-baseline justify-center md:justify-start gap-3">
                    <h2 className="text-6xl md:text-7xl font-black font-heading tracking-tighter">
                      {finance.remaining.toLocaleString()}
                    </h2>
                    <span className="text-2xl font-bold opacity-80 uppercase font-heading">บาท</span>
                  </div>
                  <p className="mt-3 text-sm font-bold text-red-100 opacity-70">โปรดชำระเงินเพื่อรักษาสิทธิ์การเรียนและการสอบ</p>
                </div>
                <button 
                  onClick={() => setShowPaymentDetails(!showPaymentDetails)}
                  className="w-full md:w-auto px-10 py-6 bg-white text-red-600 rounded-[28px] font-black text-lg uppercase tracking-widest shadow-xl hover:bg-red-50 transition-all flex items-center justify-center gap-3 active:scale-95"
                >
                  {showPaymentDetails ? <ChevronUp /> : <CreditCard />}
                  {showPaymentDetails ? 'ซ่อนรายละเอียด' : 'ชำระเงินตอนนี้'}
                </button>
              </div>
            </div>
          )}

          {/* Detailed Financial & Bank Info (Show below the red panel when toggled) */}
          {(showPaymentDetails || (finance.remaining === 0)) && (
            <div className="animate-in slide-in-from-top-4 duration-500 space-y-6">
              <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm relative overflow-hidden">
                <div className="flex items-center gap-4 mb-8">
                  <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl"><CreditCard size={24} /></div>
                  <div>
                    <h3 className="text-xl font-black text-slate-900 font-heading">ข้อมูลการชำระเงิน</h3>
                    <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Payment Information & Bank Details</p>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
                  <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 text-center">
                    <p className="text-[10px] font-black text-slate-400 uppercase mb-2">ยอดเต็ม</p>
                    <p className="text-2xl font-black text-slate-900">{finance.amount.toLocaleString()} ฿</p>
                  </div>
                  <div className="p-6 bg-green-50 rounded-3xl border border-green-100 text-center">
                    <p className="text-[10px] font-black text-green-600 uppercase mb-2">ชำระแล้ว</p>
                    <p className="text-2xl font-black text-green-700">{finance.paid.toLocaleString()} ฿</p>
                  </div>
                  <div className="p-6 bg-red-50 rounded-3xl border border-red-100 text-center">
                    <p className="text-[10px] font-black text-red-600 uppercase mb-2">คงเหลือ</p>
                    <p className="text-2xl font-black text-red-700">{finance.remaining.toLocaleString()} ฿</p>
                  </div>
                </div>

                {finance.remaining > 0 ? (
                  <div className="p-8 bg-slate-900 rounded-[32px] text-white flex flex-col md:flex-row justify-between items-center gap-6 relative overflow-hidden shadow-2xl">
                    <div className="absolute top-0 right-0 p-8 opacity-5 pointer-events-none"><Banknote size={100} /></div>
                    <div className="relative z-10">
                      <p className="text-xs font-black text-blue-400 uppercase tracking-[0.2em] mb-4">บัญชีธนาคารสำหรับโอนเงิน</p>
                      <div className="space-y-1">
                        <p className="text-lg font-bold">ธนาคารกสิกรไทย (K-Bank)</p>
                        <p className="text-4xl font-black tracking-tighter text-blue-100">012-3-45678-9</p>
                        <p className="text-sm font-medium opacity-60">ชื่อบัญชี: วิทยาลัยเทคโนโลยีอาชีวศึกษา (ส่วนกลาง)</p>
                      </div>
                    </div>
                    {lineUrl && (
                      <a href={lineUrl} target="_blank" rel="noreferrer" className="relative z-10 flex items-center gap-3 px-8 py-4 bg-[#06C755] text-white rounded-2xl font-black text-sm uppercase tracking-widest hover:scale-105 transition-all shadow-xl">
                        <MessageCircle size={20} /> แจ้งสลิปผ่าน LINE
                      </a>
                    )}
                  </div>
                ) : (
                  <div className="p-8 bg-green-50 rounded-[32px] border border-green-100 flex items-center justify-center gap-4">
                    <CheckCircle2 size={32} className="text-green-600" />
                    <div>
                      <p className="text-lg font-black text-green-900 font-heading">ชำระค่าเทอมครบถ้วนแล้ว</p>
                      <p className="text-sm font-bold text-green-700 opacity-70">ขอบคุณสำหรับการชำระค่าธรรมเนียมการศึกษา</p>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  // --- Admin View ---
  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-slate-900 rounded-xl text-white"><Filter size={20} /></div>
          <div>
            <h4 className="font-black text-slate-900 text-sm font-heading">ตัวกรองวิเคราะห์ข้อมูล</h4>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">สรุปภาพรวมแผนกและระดับชั้น</p>
          </div>
        </div>
        <div className="flex gap-4">
          <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="bg-slate-50 p-3 rounded-2xl text-[10px] font-black uppercase outline-none border border-slate-100">
            <option value="ALL">ทุกระดับชั้น</option>
            {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
          </select>
          <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="bg-slate-50 p-3 rounded-2xl text-[10px] font-black uppercase outline-none border border-slate-100">
            <option value="ALL">ทุกแผนกวิชา</option>
            {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
          </select>
        </div>
      </div>

