                  </div>
                </div>
                {lineUrl && (
                  <a href={lineUrl} target="_blank" rel="noreferrer" className="shrink-0 flex flex-col items-center justify-center gap-3 px-10 py-8 bg-[#06C755] text-white rounded-3xl font-black text-sm uppercase tracking-widest hover:scale-105 transition-all shadow-2xl">
                    <MessageCircle size={40} /> 
                    <span>แจ้งสลิปผ่าน LINE</span>
                  </a>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
