                <span className="font-black text-red-600">{s.behaviorScore}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { Student, TuitionConfig, PaymentRecord, ThaiLevel, Department } from '../types';
import { 
  CreditCard, Plus, Save, Trash2, Banknote, History, Search, CheckCircle2, 
  AlertCircle, User, Wallet, Layers, Bookmark, Settings, Building2, CreditCard as CardIcon, Check
} from 'lucide-react';

interface TuitionSystemProps {
  students: Student[];
  tuitionConfigs: TuitionConfig[];
  setTuitionConfigs: React.Dispatch<React.SetStateAction<TuitionConfig[]>>;
  paymentRecords: PaymentRecord[];
  setPaymentRecords: React.Dispatch<React.SetStateAction<PaymentRecord[]>>;
  user: any;
}

const TuitionSystem: React.FC<TuitionSystemProps> = ({ 
  students, tuitionConfigs, setTuitionConfigs, paymentRecords, setPaymentRecords, user 
}) => {
  const [activeTab, setActiveTab] = useState<'config' | 'payment' | 'bank'>(
    user.role === 'PARENT' ? 'bank' : 'payment'
  );

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(null);
  const [bankInfo, setBankInfo] = useState({
    bankName: 'ธนาคารกสิกรไทย (K-Bank)',
    accountNo: '012-3-45678-9',
    accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
  });

  useEffect(() => {
    const savedBank = localStorage.getItem('cms_bank_info');
    if (savedBank) setBankInfo(JSON.parse(savedBank));
  }, []);

  const saveBankInfo = () => {
    localStorage.setItem('cms_bank_info', JSON.stringify(bankInfo));
    alert('บันทึกข้อมูลบัญชีธนาคารเรียบร้อยแล้ว');
  };

  const [newConfig, setNewConfig] = useState<Partial<TuitionConfig>>({
    level: Object.values(ThaiLevel)[0],
    department: Object.values(Department)[0],
    amount: 0,
    term: '1/2567'
  });

  const [paymentAmount, setPaymentAmount] = useState<number | "">("");
  const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'TRANSFER'>('TRANSFER');

  const filteredStudents = useMemo(() => {
    return students.filter(s => 
      s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm)
    );
  }, [students, searchTerm]);

  const handleAddConfig = () => {
    if (!newConfig.amount || newConfig.amount <= 0) return alert('ระบุจำนวนเงิน');
    const config: TuitionConfig = {
      id: `CONF_${Date.now()}`,
      level: newConfig.level!,
      department: newConfig.department!,
      amount: newConfig.amount!,
      term: newConfig.term!
    };
    setTuitionConfigs(prev => [...prev, config]);
  };

  const handlePayment = (student: Student) => {
    const amount = Number(paymentAmount);
    if (amount <= 0) return alert('ระบุจำนวนเงิน');

    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    const newPayment: PaymentRecord = {
      id: `PAY_${Date.now()}`,
      studentId: student.id,
      configId: config?.id || 'GENERAL',
      amount: amount,
      method: paymentMethod,
      date: new Date().toLocaleDateString('th-TH'),
      recordedBy: user.name,
      status: 'PAID'
    };

    setPaymentRecords(prev => [...prev, newPayment]);
    setPaymentAmount("");
    alert('บันทึกสำเร็จ');
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20 max-w-7xl mx-auto">
      <div className="flex bg-white p-2 rounded-2xl border border-slate-200 shadow-sm w-fit">
        <button onClick={() => setActiveTab('payment')} className={`px-6 py-3 rounded-xl text-xs font-bold transition-all font-heading ${activeTab === 'payment' ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>รับชำระเงิน</button>
        <button onClick={() => setActiveTab('config')} className={`px-6 py-3 rounded-xl text-xs font-bold transition-all font-heading ${activeTab === 'config' ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>โครงสร้างค่าเทอม</button>
        <button onClick={() => setActiveTab('bank')} className={`px-6 py-3 rounded-xl text-xs font-bold transition-all font-heading ${activeTab === 'bank' ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>ตั้งค่าบัญชีรับเงิน</button>
      </div>

      {activeTab === 'bank' && (
        <div className="bg-white p-10 rounded-[40px] border border-slate-200 shadow-sm max-w-2xl mx-auto space-y-8 animate-in slide-in-from-bottom-4">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-indigo-600 rounded-2xl text-white shadow-xl shadow-indigo-100"><Settings size={24} /></div>
            <div>
              <h3 className="text-xl font-black text-slate-900 font-heading">ตั้งค่าบัญชีการเงิน</h3>
              <p className="text-xs text-slate-400 font-bold">ข้อมูลนี้จะไปแสดงในหน้าแจ้งชำระเงินของผู้ปกครอง</p>
            </div>
          </div>
          <div className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อธนาคาร</label>
              <div className="relative">
                <Building2 className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input type="text" value={bankInfo.bankName} onChange={(e) => setBankInfo({...bankInfo, bankName: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-2xl pl-12 pr-6 py-4 font-bold outline-none focus:border-indigo-600 transition-all" placeholder="เช่น ธนาคารกสิกรไทย" />
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">เลขที่บัญชี</label>
              <div className="relative">
                <CardIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input type="text" value={bankInfo.accountNo} onChange={(e) => setBankInfo({...bankInfo, accountNo: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-2xl pl-12 pr-6 py-4 font-black text-xl outline-none focus:border-indigo-600 transition-all" placeholder="000-0-00000-0" />
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ชื่อบัญชี</label>
              <div className="relative">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input type="text" value={bankInfo.accountName} onChange={(e) => setBankInfo({...bankInfo, accountName: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-2xl pl-12 pr-6 py-4 font-bold outline-none focus:border-indigo-600 transition-all" placeholder="ชื่อ นามสกุล หรือ ชื่อสถาบัน" />
              </div>
            </div>
            <button onClick={saveBankInfo} className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-black shadow-xl hover:bg-indigo-700 transition-all flex items-center justify-center gap-2 uppercase tracking-widest text-xs">
              <Save size={18} /> บันทึกข้อมูลบัญชี
            </button>
          </div>
        </div>
      )}

      {activeTab === 'config' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1 bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm space-y-6">
            <h3 className="text-xl font-bold font-heading">กำหนดค่าเทอม</h3>
            <div className="space-y-4">
              <input type="text" value={newConfig.term} onChange={(e) => setNewConfig({...newConfig, term: e.target.value})} className="w-full bg-slate-50 border rounded-xl px-4 py-3" placeholder="ภาคเรียน เช่น 1/2567" />
              <select value={newConfig.level} onChange={(e) => setNewConfig({...newConfig, level: e.target.value})} className="w-full bg-slate-50 border rounded-xl px-4 py-3">
                {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
              </select>
              <select value={newConfig.department} onChange={(e) => setNewConfig({...newConfig, department: e.target.value})} className="w-full bg-slate-50 border rounded-xl px-4 py-3">
                {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
              </select>
              <input type="number" value={newConfig.amount || ""} onChange={(e) => setNewConfig({...newConfig, amount: Number(e.target.value)})} className="w-full bg-slate-50 border rounded-xl px-4 py-3 font-black text-xl" placeholder="ยอดเงิน (บาท)" />
              <button onClick={handleAddConfig} className="w-full py-4 bg-blue-600 text-white rounded-xl font-black">บันทึกโครงสร้าง</button>
            </div>
          </div>
          <div className="lg:col-span-2 bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase">
                <tr>
                  <th className="px-6 py-4">ระดับ / แผนก</th>
                  <th className="px-6 py-4 text-right">ยอดเงิน</th>
                  <th className="px-6 py-4"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {tuitionConfigs.map(c => (
                  <tr key={c.id}>
                    <td className="px-6 py-5">
                      <p className="font-black text-sm">{c.level}</p>
                      <p className="text-[10px] font-bold text-slate-500">{c.department}</p>
                    </td>
                    <td className="px-6 py-5 text-right font-black text-blue-600">{c.amount.toLocaleString()} ฿</td>
                    <td className="px-6 py-5 text-right">
                      <button onClick={() => setTuitionConfigs(prev => prev.filter(i => i.id !== c.id))} className="text-slate-300 hover:text-red-600"><Trash2 size={18} /></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'payment' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
           <div className="lg:col-span-1 bg-white rounded-[32px] border border-slate-200 shadow-sm h-[600px] overflow-hidden flex flex-col">
              <div className="p-4 border-b flex items-center gap-2">
                <Search className="text-slate-400" size={18} />
                <input type="text" placeholder="ค้นหาชื่อ..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-transparent font-bold outline-none" />
              </div>
              <div className="flex-1 overflow-y-auto p-2">
                {filteredStudents.map(s => (
                  <button key={s.id} onClick={() => setSelectedStudentId(s.id)} className={`w-full text-left p-4 rounded-xl border-2 mb-2 transition-all ${selectedStudentId === s.id ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-white border-transparent hover:bg-slate-50'}`}>
                    <p className="font-bold text-sm">{s.name}</p>
                    <p className="text-[10px] opacity-60 uppercase tracking-widest">{s.studentId}</p>
                  </button>
                ))}
              </div>
           </div>
           <div className="lg:col-span-2">
             {selectedStudentId ? (
               <div className="bg-white p-10 rounded-[40px] border border-slate-200 shadow-sm space-y-8 animate-in slide-in-from-right-4">
                 {(() => {
                   const s = students.find(x => x.id === selectedStudentId)!;
                   const config = tuitionConfigs.find(c => c.level === s.level && c.department === s.department);
                   const paid = paymentRecords.filter(p => p.studentId === s.id).reduce((sum, p) => sum + p.amount, 0);
                   const remaining = config ? Math.max(0, config.amount - paid) : 0;
                   return (
                     <>
                       <div className="flex items-center gap-6">
                         <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl"><User size={32} /></div>
                         <div>
                            <h3 className="text-2xl font-bold font-heading">{s.name}</h3>
                            <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">{s.level} | {s.department}</p>
                         </div>
                       </div>
                       <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                         <div className="bg-slate-900 p-8 rounded-[32px] text-white flex flex-col justify-center">
                            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">ยอดค้างชำระปัจจุบัน</p>
                            <p className="text-5xl font-black text-blue-400 font-heading">{remaining.toLocaleString()} ฿</p>
                            <div className="mt-4 pt-4 border-t border-white/10 text-[10px] font-bold text-slate-400">ชำระแล้ว: {paid.toLocaleString()} ฿ / ยอดเต็ม: {config?.amount.toLocaleString() || 0} ฿</div>
