                            <input type="number" value={paymentAmount} onChange={(e) => setPaymentAmount(Number(e.target.value))} className="w-full bg-slate-50 border-2 border-slate-100 focus:border-slate-900 rounded-2xl px-5 py-4 font-black text-3xl outline-none" placeholder="0" />
                            <div className="grid grid-cols-2 gap-2">
                               <button onClick={() => setPaymentMethod('TRANSFER')} className={`py-3 rounded-xl text-xs font-black border-2 transition-all ${paymentMethod === 'TRANSFER' ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 hover:border-indigo-100'}`}>เงินโอน</button>
                               <button onClick={() => setPaymentMethod('CASH')} className={`py-3 rounded-xl text-xs font-black border-2 transition-all ${paymentMethod === 'CASH' ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 hover:border-indigo-100'}`}>เงินสด</button>
