      )}

      {activeTab === 'payment' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
           <div className="lg:col-span-1 bg-white rounded-[32px] border border-slate-200 shadow-sm h-[600px] overflow-hidden flex flex-col">
              <div className="p-4 border-b flex items-center gap-2">
                <Search className="text-slate-400" size={18} />
                <input type="text" placeholder="ค้นหาชื่อ..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-transparent font-bold outline-none" />
              </div>
              <div className="flex-1 overflow-y-auto p-2">
                {filteredStudents.map(s => (
                  <button key={s.id} onClick={() => setSelectedStudentId(s.id)} className={`w-full text-left p-4 rounded-xl border-2 mb-2 transition-all ${selectedStudentId === s.id ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-white border-transparent hover:bg-slate-50'}`}>
                    <p className="font-bold text-sm">{s.name}</p>
                    <p className="text-[10px] opacity-60 uppercase tracking-widest">{s.studentId}</p>
