  const [behaviorRecords, setBehaviorRecords] = useState<BehaviorRecord[]>([]);
  const [notifications, setNotifications] = useState<NotificationRecord[]>([]);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);
  const [systemUsers, setSystemUsers] = useState<User[]>([]);
  const [tuitionConfigs, setTuitionConfigs] = useState<TuitionConfig[]>([]);
  const [paymentRecords, setPaymentRecords] = useState<PaymentRecord[]>([]);
  const [studyBlocks, setStudyBlocks] = useState<StudyBlock[]>([]);

  const triggerNotification = useCallback((studentId: string, status: string, type: 'MORNING' | 'SUBJECT', subjectId?: string) => {
    if (status === 'PRESENT') return;

    const student = students.find(s => s.id === studentId);
    if (!student) return;

    const subject = subjectId ? subjects.find(sub => sub.id === subjectId) : null;
    const typeLabel = type === 'MORNING' ? 'เข้าแถวหน้าเสาธง' : `วิชา ${subject?.name || 'รายวิชา'}`;

    let statusLabel = '';
    let notifType: any = 'INFO';

    switch(status) {
      case 'ABSENT': statusLabel = 'ขาดเรียน'; notifType = 'ABSENT'; break;
      case 'LATE': statusLabel = 'มาสาย'; notifType = 'LATE'; break;
      case 'BUSINESS_LEAVE': statusLabel = 'ลากิจ'; notifType = 'LEAVE'; break;
      case 'SICK_LEAVE': statusLabel = 'ลาป่วย'; notifType = 'LEAVE'; break;
    }

    const newNotif: NotificationRecord = {
      id: `NOTIF_${Date.now()}_${Math.random()}`,
      studentId: studentId,
      title: `แจ้งเตือนการ${statusLabel}`,
      message: `นักเรียน: ${student.name} มีสถานะ "${statusLabel}" ในการ${typeLabel} วันที่ ${new Date().toLocaleDateString('th-TH')}`,
      type: notifType,
      date: new Date().toISOString().split('T')[0],
      timestamp: new Date().toLocaleTimeString('th-TH'),
      isRead: false
    };

    setNotifications(prev => [newNotif, ...prev.slice(0, 49)]);
  }, [students, subjects]);

  const handleSetAttendance = (updater: any) => {
    setAttendance(prev => {
      const next = typeof updater === 'function' ? updater(prev) : updater;
      const latestAdded = next.filter((n: any) => !prev.some((p: any) => p.id === n.id));

      latestAdded.forEach((rec: AttendanceRecord) => {
        triggerNotification(rec.studentId, rec.status, rec.type, rec.subjectId);
      });

      return next;
    });
  };

  useEffect(() => {
    const load = (key: string) => localStorage.getItem(key);
    const savedStudents = load('cms_students');
    const savedAttendance = load('cms_attendance');
    const savedBehavior = load('cms_behavior');
    const savedNotifs = load('cms_notifications');
    const savedSubjects = load('cms_subjects');
    const savedUsers = load('cms_system_users');
    const savedTuition = load('cms_tuition_configs');
    const savedPayments = load('cms_payment_records');
    const savedBlocks = load('cms_study_blocks');

    if (savedStudents) setStudents(JSON.parse(savedStudents)); else setStudents(MOCK_STUDENTS);
    if (savedAttendance) setAttendance(JSON.parse(savedAttendance)); else setAttendance(MOCK_ATTENDANCE);
    if (savedBehavior) setBehaviorRecords(JSON.parse(savedBehavior)); else setBehaviorRecords(MOCK_BEHAVIOR);
    if (savedNotifs) setNotifications(JSON.parse(savedNotifs));
    if (savedSubjects) setSubjects(JSON.parse(savedSubjects)); else setSubjects(MOCK_SUBJECTS);
    if (savedTuition) setTuitionConfigs(JSON.parse(savedTuition));
    if (savedPayments) setPaymentRecords(JSON.parse(savedPayments));
    if (savedBlocks) setStudyBlocks(JSON.parse(savedBlocks)); else setStudyBlocks(generateDefaultBlocks());

    if (savedUsers) {
      setSystemUsers(JSON.parse(savedUsers));
    } else {
      setSystemUsers([
        { id: 'A1', name: 'แอดมิน ระบบ', role: 'ADMIN', username: 'admin', password: '1234', department: 'ส่วนกลาง' },
        { id: 'T1', name: 'อ.สมพงษ์ ใจสว่าง', role: 'TEACHER', username: 'teacher', password: '1234', department: 'เทคโนโลยีสารสนเทศ' },
        { id: 'F1', name: 'ฝ่ายการเงิน', role: 'FINANCE', username: 'finance', password: '1234', department: 'ฝ่ายการเงิน' },
        { id: 'P1', name: 'คุณแม่ของนายสมชาย', role: 'PARENT', username: 'parent', password: '1234', studentId: '1' }
      ]);
    }
    setIsInitialLoaded(true);
  }, []);

  useEffect(() => {
    if (isInitialLoaded) {
      const save = (key: string, data: any) => localStorage.setItem(key, JSON.stringify(data));
      save('cms_students', students);
      save('cms_attendance', attendance);
      save('cms_behavior', behaviorRecords);
      save('cms_notifications', notifications);
      save('cms_subjects', subjects);
      save('cms_system_users', systemUsers);
      save('cms_tuition_configs', tuitionConfigs);
      save('cms_payment_records', paymentRecords);
      save('cms_study_blocks', studyBlocks);
    }
  }, [students, attendance, behaviorRecords, notifications, subjects, systemUsers, tuitionConfigs, paymentRecords, studyBlocks, isInitialLoaded]);

  if (!user) return <Login onLogin={setUser} systemUsers={systemUsers} />;

  const renderContent = () => {
    switch (activeMenu) {
      case 'dashboard': return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} notifications={notifications} user={user} studyBlocks={studyBlocks} tuitionConfigs={tuitionConfigs} paymentRecords={paymentRecords} />;
      case 'students': return <StudentManagement students={students} setStudents={setStudents} />;
      case 'morning': return <MorningAttendance students={students} setStudents={setStudents} attendanceRecords={attendance} setAttendanceRecords={handleSetAttendance} rooms={rooms} setRooms={setRooms} />;
      case 'subject': return <ClassAttendance students={students} setStudents={setStudents} subjects={subjects} setSubjects={setSubjects} rooms={rooms} setRooms={setRooms} attendanceRecords={attendance} setAttendanceRecords={handleSetAttendance} currentUser={user} />;
      case 'behavior': return <BehaviorSystem students={students} setStudents={setStudents} behaviorRecords={behaviorRecords} setBehaviorRecords={setBehaviorRecords} />;
      case 'tuition': return <TuitionSystem students={students} tuitionConfigs={tuitionConfigs} setTuitionConfigs={setTuitionConfigs} paymentRecords={paymentRecords} setPaymentRecords={setPaymentRecords} user={user} />;
      case 'finance_report': return <FinanceReport students={students} paymentRecords={paymentRecords} tuitionConfigs={tuitionConfigs} />;
      case 'report': return <Reports students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} paymentRecords={paymentRecords} />;
      case 'morning_scores': return <MorningScoreSummary students={students} attendance={attendance} studyBlocks={studyBlocks} />;
      case 'users': return <UserManagement users={systemUsers} setUsers={setSystemUsers} currentUser={user} students={students} />;
      case 'settings': return <SystemSettings studyBlocks={studyBlocks} setStudyBlocks={setStudyBlocks} />;
      case 'line_config': return <LineConfig />;
      default: return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} />;
    }
  };

  return (
    <Layout 
      activeMenu={activeMenu} 
      setActiveMenu={setActiveMenu} 
      user={user} 
      onLogout={() => setUser(null)}
      notifications={notifications}
      setNotifications={setNotifications}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Student, AttendanceRecord, BehaviorRecord, StudyBlock, PaymentRecord } from '../types';
import * as XLSX from 'https://esm.sh/xlsx';
import { 
  FileText, 
  Search, 
  Download, 
  User, 
  Award, 
  TrendingUp,
  Users,
  BarChart3,
  CheckCircle2,
  AlertCircle,
  FileSpreadsheet
} from 'lucide-react';
import { STATUS_LABELS } from '../constants';

interface ReportsProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: BehaviorRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  paymentRecords?: PaymentRecord[]; // เพิ่มเพื่อใช้ export รายบุคคล
}

const Reports: React.FC<ReportsProps> = ({ 
  students, attendance, behavior, user, studyBlocks, paymentRecords = []
}) => {
  const [activeTab, setActiveTab] = useState<'individual' | 'room'>(user.role === 'PARENT' ? 'individual' : 'room');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(
    user.role === 'PARENT' ? students.find(s => s.studentId === user.studentId)?.id || null : null
  );

  // Added explicit string casting to fix 'unknown' type comparison errors on line 40
  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level as string))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department as string))).sort(), [students]);
  const availableRooms = useMemo(() => Array.from(new Set(students.map(s => s.room as string))).sort((a, b) => parseInt(a) - parseInt(b)), [students]);

  const [reportLevel, setReportLevel] = useState<string>(availableLevels[0] || '');
  const [reportDept, setReportDept] = useState<string>(availableDepts[0] || '');
  const [reportRoom, setReportRoom] = useState<string>(availableRooms[0] || '');

  const selectedStudent = useMemo(() => students.find(s => s.id === selectedStudentId), [students, selectedStudentId]);

  const roomStudents = useMemo(() => {
    return students.filter(s => 
      s.level === reportLevel && s.department === reportDept && s.room === reportRoom
    );
  }, [students, reportLevel, reportDept, reportRoom]);

  const getAttendanceStats = (studentId: string) => {
    const studentRecords = attendance.filter(a => a.studentId === studentId);
    const total = studentRecords.length;
    const present = studentRecords.filter(r => r.status === 'PRESENT').length;
    const rate = total > 0 ? Math.round((present / total) * 100) : 0;
    return { total, present, rate };
  };

  const exportIndividualExcel = () => {
    if (!selectedStudent) return;

    const attData = attendance
      .filter(a => a.studentId === selectedStudent.id)
      .map(a => ({
        'วันที่': a.date,
        'ประเภท': a.type === 'MORNING' ? 'เข้าแถว' : 'รายวิชา',
        'สถานะ': STATUS_LABELS[a.status]?.label || a.status,
        'หมายเหตุ': a.remark || '-',
        'เวลาที่บันทึก': a.timestamp
      }));

    const behData = behavior
      .filter(b => b.studentId === selectedStudent.id)
      .map(b => ({
        'วันที่': b.date,
        'รายการ': b.reason,
        'ประเภท': b.type === 'ADD' ? 'เพิ่มคะแนน' : 'หักคะแนน',
        'คะแนน': b.score,
        'ผู้บันทึก': b.recordedBy
      }));

    const payData = paymentRecords
      .filter(p => p.studentId === selectedStudent.id)
      .map(p => ({
        'วันที่': p.date,
        'ยอดชำระ': p.amount,
        'วิธีชำระ': p.method === 'CASH' ? 'เงินสด' : 'เงินโอน',
        'ผู้รับเงิน': p.recordedBy
      }));

    const wb = XLSX.utils.book_new();

    const wsAtt = XLSX.utils.json_to_sheet(attData);
    XLSX.utils.book_append_sheet(wb, wsAtt, "ประวัติการเข้าเรียน");

    const wsBeh = XLSX.utils.json_to_sheet(behData);
    XLSX.utils.book_append_sheet(wb, wsBeh, "ประวัติพฤติกรรม");

    const wsPay = XLSX.utils.json_to_sheet(payData);
    XLSX.utils.book_append_sheet(wb, wsPay, "ประวัติการเงิน");

    XLSX.writeFile(wb, `ประวัติ_${selectedStudent.studentId}_${selectedStudent.name}.xlsx`);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex bg-white p-2 rounded-2xl border border-slate-200 shadow-sm w-fit">
        {user.role !== 'PARENT' && (
          <button onClick={() => setActiveTab('room')} className={`flex items-center gap-2 px-8 py-3.5 rounded-xl text-sm font-bold transition-all font-heading ${activeTab === 'room' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
            <Users size={18} /> สรุปรายห้อง
          </button>
        )}
        <button onClick={() => setActiveTab('individual')} className={`flex items-center gap-2 px-8 py-3.5 rounded-xl text-sm font-bold transition-all font-heading ${activeTab === 'individual' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
          <User size={18} /> สรุปรายบุคคล
        </button>
      </div>

      {activeTab === 'room' && user.role !== 'PARENT' && (
        <div className="space-y-8 animate-in slide-in-from-bottom-4">
          <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm grid grid-cols-1 md:grid-cols-4 gap-6 items-end">
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">ระดับชั้น</label>
              <select value={reportLevel} onChange={(e) => setReportLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-3.5 font-bold text-slate-900 outline-none">
                {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">แผนกวิชา</label>
              <select value={reportDept} onChange={(e) => setReportDept(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-3.5 font-bold text-slate-900 outline-none">
                {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">ห้อง</label>
              <select value={reportRoom} onChange={(e) => setReportRoom(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-3.5 font-bold text-slate-900 outline-none">
                {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
            <button className="bg-blue-600 text-white px-8 py-4 rounded-xl font-bold flex items-center justify-center gap-3 shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all font-heading">
              <Download size={20} /> ออกรายงานผลรวม
            </button>
          </div>

          <div className="bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-8 border-b bg-slate-50/50">
              <h3 className="text-xl font-bold text-slate-900 flex items-center gap-3 font-heading">
                <BarChart3 className="text-indigo-600" size={24} /> 
                สรุปสถิตินักเรียนรายห้อง ({roomStudents.length} คน)
              </h3>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase">
                  <tr>
                    <th className="px-8 py-4">ลำดับ</th>
                    <th className="px-8 py-4">นักเรียน</th>
                    <th className="px-8 py-4">คะแนนพฤติกรรม</th>
                    <th className="px-8 py-4">สถิติมาเรียน</th>
                    <th className="px-8 py-4">ภาพรวม</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {roomStudents.map((s, idx) => {
                    const stats = getAttendanceStats(s.id);
                    return (
                      <tr key={s.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-8 py-5 text-sm font-bold text-slate-400">{idx + 1}</td>
                        <td className="px-8 py-5">
                          <p className="font-bold text-slate-900">{s.name}</p>
                          <p className="text-[10px] text-slate-500 font-medium uppercase">{s.studentId}</p>
                        </td>
                        <td className="px-8 py-5">
                          <span className={`font-black ${s.behaviorScore < 70 ? 'text-red-600' : 'text-slate-900'}`}>{s.behaviorScore}</span>
                        </td>
                        <td className="px-8 py-5">
                          <div className="flex items-center gap-3">
                            <div className="flex-1 h-2 bg-slate-100 rounded-full w-24 overflow-hidden">
                              <div className="h-full bg-blue-600 rounded-full" style={{ width: `${stats.rate}%` }} />
                            </div>
                            <span className="text-xs font-bold text-slate-600">{stats.rate}%</span>
                          </div>
                        </td>
                        <td className="px-8 py-5">
                          {s.behaviorScore < 70 || stats.rate < 80 ? (
                            <span className="px-3 py-1 bg-red-50 text-red-600 rounded-lg text-[9px] font-bold border border-red-100 uppercase">ต้องปรับปรุง</span>
                          ) : (
                            <span className="px-3 py-1 bg-green-50 text-green-600 rounded-lg text-[9px] font-bold border border-green-100 uppercase">ดีมาก</span>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                  {roomStudents.length === 0 && (
                    <tr><td colSpan={5} className="py-20 text-center text-slate-300 font-bold">ไม่พบข้อมูลในห้องเรียนนี้</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'individual' && (
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 animate-in slide-in-from-right-4">
          {user.role !== 'PARENT' && (
            <div className="lg:col-span-1">
              <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm h-[600px] flex flex-col">
                <div className="relative mb-4">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input type="text" placeholder="ค้นหาชื่อ/รหัส..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-12 pr-4 py-3 text-sm font-bold outline-none" />
                </div>
                <div className="flex-1 overflow-y-auto space-y-2 pr-2">
                  {students.filter(s => s.name.includes(searchTerm) || s.studentId.includes(searchTerm)).map(s => (
                    <button key={s.id} onClick={() => setSelectedStudentId(s.id)} className={`w-full text-left p-4 rounded-xl border transition-all ${selectedStudentId === s.id ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-white border-transparent hover:bg-slate-50'}`}>
                      <p className="font-bold text-sm truncate">{s.name}</p>
                      <p className={`text-[10px] font-medium mt-1 ${selectedStudentId === s.id ? 'text-slate-400' : 'text-slate-500'}`}>{s.studentId}</p>
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}

          <div className={`${user.role === 'PARENT' ? 'lg:col-span-4' : 'lg:col-span-3'} space-y-6`}>
            {selectedStudent ? (
              <div className="space-y-6">
                <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-8">
                  <div className="flex items-center gap-6">
                    <div className="w-20 h-20 bg-blue-600 rounded-[24px] flex items-center justify-center text-white shadow-xl">
                      <User size={40} />
                    </div>
                    <div>
                      <h2 className="text-3xl font-bold text-slate-900 font-heading">{selectedStudent.name}</h2>
                      <p className="text-slate-500 font-bold uppercase text-xs tracking-widest mt-1">{selectedStudent.studentId} • {selectedStudent.level} {selectedStudent.department}</p>
                    </div>
                  </div>
                  <div className="flex gap-4">
                    <button 
                      onClick={exportIndividualExcel}
                      className="flex items-center gap-2 px-6 py-3 bg-green-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg shadow-green-100 hover:bg-green-700 transition-all active:scale-95"
                    >
                      <FileSpreadsheet size={18} /> Export Excel
                    </button>
                    <div className="text-center px-6 py-4 bg-slate-50 rounded-2xl border border-slate-100">
                      <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">คะแนนพฤติกรรม</p>
                      <p className={`text-2xl font-black ${selectedStudent.behaviorScore < 70 ? 'text-red-600' : 'text-slate-900'}`}>{selectedStudent.behaviorScore}</p>
                    </div>
                    <div className="text-center px-6 py-4 bg-slate-50 rounded-2xl border border-slate-100">
                      <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">มาเรียน</p>
                      <p className="text-2xl font-black text-blue-600">{getAttendanceStats(selectedStudent.id).rate}%</p>
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm">
                    <h3 className="text-lg font-bold text-slate-900 mb-6 flex items-center gap-3 font-heading">
                      <TrendingUp className="text-blue-600" size={20} /> รายการเช็คชื่อล่าสุด
                    </h3>
                    <div className="space-y-3">
                      {attendance.filter(a => a.studentId === selectedStudent.id).slice(-5).reverse().map(a => (
                        <div key={a.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-xl border border-slate-100">
                          <div>
                            <p className="font-bold text-sm text-slate-900">{a.type === 'MORNING' ? 'เข้าแถวหน้าเสาธง' : 'วิชาเรียน'}</p>
                            <p className="text-[10px] font-medium text-slate-400">{a.date}</p>
                          </div>
                          <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase border ${STATUS_LABELS[a.status].color}`}>
                            {STATUS_LABELS[a.status].label}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                  <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm">
                    <h3 className="text-lg font-bold text-slate-900 mb-6 flex items-center gap-3 font-heading">
                      <Award className="text-amber-600" size={20} /> บันทึกพฤติกรรมล่าสุด
                    </h3>
                    <div className="space-y-3">
                      {behavior.filter(b => b.studentId === selectedStudent.id).slice(-5).reverse().map(b => (
                        <div key={b.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-xl border border-slate-100">
                          <div>
                            <p className="font-bold text-sm text-slate-900 truncate max-w-[150px]">{b.reason}</p>
                            <p className="text-[10px] font-medium text-slate-400">{b.date}</p>
                          </div>
                          <span className={`font-black text-lg ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                            {b.type === 'ADD' ? '+' : '-'}{b.score}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            ) : (
              <div className="h-[600px] bg-white rounded-[32px] border-2 border-dashed border-slate-100 flex flex-col items-center justify-center p-20 text-center">
                <FileText size={64} className="text-slate-100 mb-6" />
                <h3 className="text-2xl font-bold text-slate-900 font-heading uppercase tracking-widest">โปรดเลือกนักเรียน</h3>
                <p className="text-slate-400 text-sm mt-2 font-bold opacity-50 uppercase">Select a student from the list to view report</p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default Reports;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard, MessageCircle, ExternalLink, Bell,
  Banknote, ChevronDown, ChevronUp, CheckCircle2, Copy, Check
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord, ThaiLevel, Department } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  AreaChart, Area
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-fit">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);
  const [copied, setCopied] = useState(false);
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  const [bankInfo, setBankInfo] = useState({
    bankName: 'ธนาคารกสิกรไทย (K-Bank)',
    accountNo: '012-3-45678-9',
    accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
  });

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
    const savedBank = localStorage.getItem('cms_bank_info');
    if (savedBank) setBankInfo(JSON.parse(savedBank));
  }, []);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = attendance.filter(a => 
      a.studentId === studentId && a.type === 'MORNING' && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    return Number((( (presentDays) * 5) / 18).toFixed(2));
  };

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, r) => sum + r.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  const chartData = useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => ({
      name: date,
      value: attendance.filter(a => a.date === date && a.status === 'PRESENT').length
    }));
  }, [attendance]);

  if (user.role === 'PARENT' || viewingStudentId) {
    const studentId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return <div className="p-20 text-center">ไม่พบข้อมูล</div>;

    const studentAttendance = attendance.filter(a => a.studentId === student.id);
    const presentCount = studentAttendance.filter(a => a.status === 'PRESENT').length;
    const attRate = studentAttendance.length > 0 ? Math.round((presentCount / studentAttendance.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);
    const studentNotifications = notifications.filter(n => n.studentId === student.id).slice(0, 3);

    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-20">
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border border-slate-100 rounded-2xl text-slate-600 font-bold hover:bg-slate-50 transition-all font-heading">
              <ArrowLeft size={18} /> กลับ
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">{user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}</p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><User size={24} /></div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-black text-slate-900 font-heading uppercase tracking-widest flex items-center gap-2">
              <Bell size={18} className="text-blue-600" /> แจ้งเตือนล่าสุด
            </h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {studentNotifications.length > 0 ? studentNotifications.map(n => (
              <div key={n.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex gap-4 items-start relative overflow-hidden">
                <div className={`w-1 h-full absolute left-0 top-0 ${n.type === 'ABSENT' ? 'bg-red-500' : 'bg-blue-500'}`} />
                <div className="ml-2">
                  <p className="font-black text-slate-900 text-xs truncate mb-1">{n.title}</p>
                  <p className="text-[10px] text-slate-600 line-clamp-2 font-bold">{n.message}</p>
                </div>
              </div>
            )) : <div className="col-span-3 text-center py-4 text-xs font-bold text-slate-400">ไม่มีการแจ้งเตือนใหม่</div>}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าเรียน" value={`${attRate}%`} sub={`จาก ${studentAttendance.length} รายการ`} icon={<TrendingUp size={28} />} color="bg-blue-600" textColor="text-blue-600" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore}`} sub={`บล็อกเรียนปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="พฤติกรรมสะสม" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        <div className="space-y-4">
          {finance.remaining > 0 ? (
            <div className="bg-gradient-to-br from-red-600 to-orange-600 p-8 md:p-10 rounded-[40px] text-white shadow-2xl relative overflow-hidden animate-in slide-in-from-bottom-6">
              <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
                <div className="text-center md:text-left">
                  <p className="text-xs font-black text-red-100 uppercase tracking-[0.3em] mb-2 opacity-80">ยอดค้างชำระปัจจุบัน</p>
                  <div className="flex items-baseline justify-center md:justify-start gap-3">
                    <h2 className="text-6xl font-black font-heading tracking-tighter">{finance.remaining.toLocaleString()}</h2>
                    <span className="text-2xl font-bold opacity-80 uppercase font-heading">บาท</span>
                  </div>
                </div>
                <button 
                  onClick={() => setShowPaymentDetails(!showPaymentDetails)}
                  className="w-full md:w-auto px-10 py-6 bg-white text-red-600 rounded-[28px] font-black text-lg uppercase tracking-widest shadow-xl hover:bg-red-50 transition-all flex items-center justify-center gap-3 active:scale-95"
                >
                  {showPaymentDetails ? <ChevronUp /> : <CreditCard />}
                  {showPaymentDetails ? 'ซ่อนรายละเอียด' : 'ชำระเงินตอนนี้'}
                </button>
              </div>
            </div>
          ) : (
            <div className="bg-green-50 p-8 rounded-[40px] border border-green-200 flex items-center justify-center gap-4">
              <CheckCircle2 className="text-green-600" size={32} />
              <p className="text-lg font-black text-green-900 font-heading">ชำระค่าเทอมครบถ้วนแล้ว</p>
            </div>
          )}

          {showPaymentDetails && finance.remaining > 0 && (
            <div className="bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-xl animate-in slide-in-from-top-4 space-y-8">
              <div className="flex items-center gap-4">
                <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl"><Banknote size={24} /></div>
                <div>
                  <h3 className="text-xl font-black text-slate-900 font-heading">ช่องทางการโอนเงิน</h3>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Bank Transfer Details</p>
                </div>
              </div>

              <div className="p-8 md:p-10 bg-slate-900 rounded-[32px] text-white flex flex-col md:flex-row justify-between items-center gap-10 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-8 opacity-5"><Banknote size={150} /></div>
                <div className="relative z-10 space-y-6 w-full">
                  <div className="grid grid-cols-1 gap-6">
                    <div className="bg-white/5 p-6 rounded-2xl border border-white/10 flex flex-wrap items-center justify-between gap-4">
                      <div className="space-y-4 flex-1 min-w-[240px]">
                        <div className="flex items-center gap-10">
                          <div>
                            <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">ธนาคาร</p>
                            <p className="text-lg font-bold">{bankInfo.bankName}</p>
                          </div>
                          <div>
                            <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">ชื่อบัญชี</p>
                            <p className="text-lg font-bold">{bankInfo.accountName}</p>
                          </div>
                        </div>
                        <div>
                          <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">เลขที่บัญชี</p>
                          <div className="flex items-center gap-4">
                            <p className="text-4xl font-black tracking-tighter text-blue-50">{bankInfo.accountNo}</p>
                            <button 
                              onClick={() => handleCopy(bankInfo.accountNo)}
                              className={`flex items-center justify-center gap-2 px-4 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${copied ? 'bg-green-600 text-white' : 'bg-white/10 text-white hover:bg-white/20 border border-white/20'}`}
                            >
                              {copied ? <Check size={14} /> : <Copy size={14} />}
                              {copied ? 'คัดลอกแล้ว' : 'คัดลอก'}
                            </button>
                          </div>
                        </div>
                      </div>

                      {lineUrl && (
                        <a href={lineUrl} target="_blank" rel="noreferrer" className="shrink-0 flex flex-col items-center justify-center gap-3 px-8 py-6 bg-[#06C755] text-white rounded-3xl font-black text-xs uppercase tracking-widest hover:scale-105 transition-all shadow-2xl">
                          <MessageCircle size={32} /> 
                          <span>แจ้งสลิปผ่าน LINE</span>
                        </a>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-slate-900 rounded-xl text-white"><Filter size={20} /></div>
          <h4 className="font-black text-slate-900 text-sm font-heading">ตัวกรองวิเคราะห์ข้อมูล</h4>
        </div>
        <div className="flex gap-4">
          <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="bg-slate-50 p-3 rounded-2xl text-[10px] font-black uppercase outline-none border border-slate-100">
            <option value="ALL">ทุกระดับชั้น</option>
            {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
          </select>
          <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="bg-slate-50 p-3 rounded-2xl text-[10px] font-black uppercase outline-none border border-slate-100">
            <option value="ALL">ทุกแผนกวิชา</option>
            {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="นักเรียนในกลุ่ม" value={filteredStudentsBase.length} sub="ตามเงื่อนไข" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="มาเรียนวันนี้" value={attendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="นักเรียนที่เข้าแถว" icon={<CheckCircle2 size={28} />} color="bg-green-600" />
        <StatCard title="กลุ่มเสี่ยง" value={behaviorWatchlist.length} sub="คะแนนต่ำกว่าเกณฑ์" icon={<ShieldAlert size={28} />} color="bg-red-600" />
        <StatCard title="คะแนนเฉลี่ย" value={filteredStudentsBase.length ? Math.round(filteredStudentsBase.reduce((a,b)=>a+b.behaviorScore,0)/filteredStudentsBase.length) : 0} sub="พฤติกรรมในกลุ่ม" icon={<Award size={28} />} color="bg-indigo-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm h-[480px]">
          <h3 className="text-xl font-black text-slate-900 font-heading mb-10">วิเคราะห์การเข้าเรียน</h3>
          <ResponsiveContainer width="100%" height="80%">
            <AreaChart data={chartData}>
              <defs><linearGradient id="colorValue" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#2563eb" stopOpacity={0.3}/><stop offset="95%" stopColor="#2563eb" stopOpacity={0}/></linearGradient></defs>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
              <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
              <Tooltip />
              <Area type="monotone" dataKey="value" stroke="#2563eb" strokeWidth={4} fill="url(#colorValue)" />
            </AreaChart>
          </ResponsiveContainer>
        </div>
        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
          <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest mb-6 font-heading">กลุ่มเฝ้าระวัง</h4>
          <div className="space-y-4">
            {behaviorWatchlist.map(s => (
              <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="flex items-center justify-between p-4 bg-red-50 rounded-2xl cursor-pointer">
                <span className="font-bold text-sm text-slate-900">{s.name}</span>
                <span className="font-black text-red-600">{s.behaviorScore}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { MENU_ITEMS, MENU_GROUPS } from '../constants';
import { LogOut, Menu, User, ChevronRight, Bell, Search, Settings, X, Clock, AlertCircle } from 'lucide-react';
import { NotificationRecord } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  activeMenu: string;
  setActiveMenu: (menu: string) => void;
  user: any;
  onLogout: () => void;
  notifications?: NotificationRecord[];
  setNotifications?: React.Dispatch<React.SetStateAction<NotificationRecord[]>>;
}

const Layout: React.FC<LayoutProps> = ({ 
  children, 
  activeMenu, 
  setActiveMenu, 
  user, 
  onLogout,
  notifications = [],
  setNotifications
}) => {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isNotifOpen, setIsNotifOpen] = useState(false);

  const filteredMenuItems = MENU_ITEMS.filter(item => 
    item.roles.includes(user.role)
  );

  const groups = Array.from(new Set(filteredMenuItems.map(item => item.group)));

  // กรองแจ้งเตือน: แสดงเฉพาะผู้ปกครองและเห็นเฉพาะของลูกตัวเองเท่านั้น
  const userNotifications = React.useMemo(() => {
    if (user.role === 'PARENT') {
      return notifications.filter(n => n.studentId === user.studentId);
    }
    // สำหรับบทบาทอื่น ไม่ต้องแสดงการแจ้งเตือนแบบ Pop-up (ให้ดูผ่าน Dashboard แทน)
    return [];
  }, [notifications, user]);

  const unreadCount = userNotifications.filter(n => !n.isRead).length;

  const handleToggleNotif = () => {
    setIsNotifOpen(!isNotifOpen);
    if (!isNotifOpen && setNotifications && unreadCount > 0) {
      setNotifications(prev => prev.map(n => {
        if (n.studentId === user.studentId) {
          return { ...n, isRead: true };
        }
        return n;
      }));
    }
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden">
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-40 md:hidden animate-in fade-in duration-300"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      <aside className={`
        fixed inset-y-0 left-0 z-50 w-[280px] bg-slate-900 text-white transform transition-all duration-500 ease-[cubic-bezier(0.4,0,0.2,1)]
        md:relative md:translate-x-0 border-r border-slate-800 shadow-2xl flex flex-col
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-8 pb-4 shrink-0">
          <div className="flex items-center gap-3 group">
            <div className="w-12 h-12 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-2xl flex items-center justify-center shadow-lg shadow-blue-500/20 group-hover:scale-110 transition-transform duration-300">
              <span className="text-xl font-bold italic tracking-tighter font-heading">ES</span>
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight leading-none font-heading">EduSmart</h1>
              <span className="text-[10px] font-semibold uppercase tracking-[0.2em] text-blue-400 opacity-90 font-heading">CMS Official</span>
            </div>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto px-4 py-6 scrollbar-hide space-y-8">
          {groups.map((groupKey) => (
            <div key={groupKey} className="space-y-2">
              <h3 className="px-4 text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3 font-heading">
                {(MENU_GROUPS as any)[groupKey]}
              </h3>
              <div className="space-y-1">
                {filteredMenuItems
                  .filter(item => item.group === groupKey)
                  .map((item) => {
                    const isActive = activeMenu === item.id;
                    return (
                      <button
                        key={item.id}
                        onClick={() => {
                          setActiveMenu(item.id);
                          setSidebarOpen(false);
                        }}
                        className={`
                          w-full group flex items-center justify-between px-4 py-3 rounded-xl transition-all duration-300 relative
                          ${isActive 
                            ? 'bg-blue-600/10 text-white' 
                            : 'text-slate-400 hover:text-white hover:bg-white/5'}
                        `}
                      >
                        <div className="flex items-center gap-4 relative z-10">
                          <div className={`
                            w-9 h-9 rounded-lg flex items-center justify-center transition-all duration-300
                            ${isActive ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-800 group-hover:bg-slate-700'}
                          `}>
                            {React.cloneElement(item.icon as React.ReactElement<any>, { size: 16 })}
                          </div>
                          <span className={`text-sm font-medium transition-all duration-300 font-heading ${isActive ? 'translate-x-1' : ''}`}>
                            {item.label}
                          </span>
                        </div>
                        {isActive && (
                          <div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse" />
                        )}
                      </button>
                    );
                  })}
              </div>
            </div>
          ))}
        </div>

        <div className="p-4 border-t border-slate-800/50 bg-slate-900/50 shrink-0">
          <div className="bg-slate-800/40 border border-white/5 rounded-2xl p-4">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-9 h-9 rounded-lg bg-slate-700 flex items-center justify-center text-white border border-white/10">
                <User size={16} />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-xs font-semibold text-white truncate font-heading">{user.name}</p>
                <p className="text-[10px] font-medium text-slate-500 truncate uppercase font-heading">{user.role}</p>
              </div>
