import React, { useState, useMemo } from 'react';
import { Student, AttendanceRecord, BehaviorRecord, StudyBlock, PaymentRecord } from '../types';
import * as XLSX from 'https://esm.sh/xlsx';
import { 
  FileText, 
  Search, 
  Download, 
  User, 
  Award, 
  TrendingUp,
  Users,
  BarChart3,
  CheckCircle2,
  AlertCircle,
  FileSpreadsheet
} from 'lucide-react';
import { STATUS_LABELS } from '../constants';

interface ReportsProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: BehaviorRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  paymentRecords?: PaymentRecord[]; // เพิ่มเพื่อใช้ export รายบุคคล
}

const Reports: React.FC<ReportsProps> = ({ 
  students, attendance, behavior, user, studyBlocks, paymentRecords = []
}) => {
  const [activeTab, setActiveTab] = useState<'individual' | 'room'>(user.role === 'PARENT' ? 'individual' : 'room');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(
    user.role === 'PARENT' ? students.find(s => s.studentId === user.studentId)?.id || null : null
  );

  // Fix: Added explicit string type assertions to resolve unknown type errors in localeCompare and parseInt
  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level as string))).sort((a, b) => (a as string).localeCompare(b as string)), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department as string))).sort((a, b) => (a as string).localeCompare(b as string)), [students]);
  const availableRooms = useMemo(() => Array.from(new Set(students.map(s => s.room as string))).sort((a, b) => parseInt(a as string) - parseInt(b as string)), [students]);

  const [reportLevel, setReportLevel] = useState<string>(availableLevels[0] || '');
  const [reportDept, setReportDept] = useState<string>(availableDepts[0] || '');
  const [reportRoom, setReportRoom] = useState<string>(availableRooms[0] || '');

  const selectedStudent = useMemo(() => students.find(s => s.id === selectedStudentId), [students, selectedStudentId]);

  const roomStudents = useMemo(() => {
    return students.filter(s => 
      s.level === reportLevel && s.department === reportDept && s.room === reportRoom
    );
  }, [students, reportLevel, reportDept, reportRoom]);

  const getAttendanceStats = (studentId: string) => {
    const studentRecords = attendance.filter(a => a.studentId === studentId);
    const total = studentRecords.length;
    const present = studentRecords.filter(r => r.status === 'PRESENT').length;
    const rate = total > 0 ? Math.round((present / total) * 100) : 0;
    return { total, present, rate };
  };

  const exportIndividualExcel = () => {
    if (!selectedStudent) return;

    const attData = attendance
      .filter(a => a.studentId === selectedStudent.id)
      .map(a => ({
        'วันที่': a.date,
        'ประเภท': a.type === 'MORNING' ? 'เข้าแถว' : 'รายวิชา',
        'สถานะ': STATUS_LABELS[a.status]?.label || a.status,
        'หมายเหตุ': a.remark || '-',
        'เวลาที่บันทึก': a.timestamp
      }));

    const behData = behavior
      .filter(b => b.studentId === selectedStudent.id)
      .map(b => ({
        'วันที่': b.date,
        'รายการ': b.reason,
        'ประเภท': b.type === 'ADD' ? 'เพิ่มคะแนน' : 'หักคะแนน',
        'คะแนน': b.score,
        'ผู้บันทึก': b.recordedBy
      }));

    const payData = paymentRecords
      .filter(p => p.studentId === selectedStudent.id)
      .map(p => ({
        'วันที่': p.date,
        'ยอดชำระ': p.amount,
        'วิธีชำระ': p.method === 'CASH' ? 'เงินสด' : 'เงินโอน',
        'ผู้รับเงิน': p.recordedBy
      }));

    const wb = XLSX.utils.book_new();

    const wsAtt = XLSX.utils.json_to_sheet(attData);
    XLSX.utils.book_append_sheet(wb, wsAtt, "ประวัติการเข้าเรียน");

    const wsBeh = XLSX.utils.json_to_sheet(behData);
    XLSX.utils.book_append_sheet(wb, wsBeh, "ประวัติพฤติกรรม");

    const wsPay = XLSX.utils.json_to_sheet(payData);
    XLSX.utils.book_append_sheet(wb, wsPay, "ประวัติการเงิน");

    XLSX.writeFile(wb, `ประวัติ_${selectedStudent.studentId}_${selectedStudent.name}.xlsx`);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex bg-white p-2 rounded-2xl border border-slate-200 shadow-sm w-fit">
        {user.role !== 'PARENT' && (
          <button onClick={() => setActiveTab('room')} className={`flex items-center gap-2 px-8 py-3.5 rounded-xl text-sm font-bold transition-all font-heading ${activeTab === 'room' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
            <Users size={18} /> สรุปรายห้อง
          </button>
        )}
        <button onClick={() => setActiveTab('individual')} className={`flex items-center gap-2 px-8 py-3.5 rounded-xl text-sm font-bold transition-all font-heading ${activeTab === 'individual' ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
          <User size={18} /> สรุปรายบุคคล
        </button>
      </div>

      {activeTab === 'room' && user.role !== 'PARENT' && (
        <div className="space-y-8 animate-in slide-in-from-bottom-4">
          <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm grid grid-cols-1 md:grid-cols-4 gap-6 items-end">
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">ระดับชั้น</label>
              <select value={reportLevel} onChange={(e) => setReportLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-3.5 font-bold text-slate-900 outline-none">
                {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">แผนกวิชา</label>
              <select value={reportDept} onChange={(e) => setReportDept(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-3.5 font-bold text-slate-900 outline-none">
                {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">ห้อง</label>
              <select value={reportRoom} onChange={(e) => setReportRoom(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-3.5 font-bold text-slate-900 outline-none">
                {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
            <button className="bg-blue-600 text-white px-8 py-4 rounded-xl font-bold flex items-center justify-center gap-3 shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all font-heading">
              <Download size={20} /> ออกรายงานผลรวม
            </button>
          </div>

          <div className="bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-8 border-b bg-slate-50/50">
              <h3 className="text-xl font-bold text-slate-900 flex items-center gap-3 font-heading">
                <BarChart3 className="text-indigo-600" size={24} /> 
                สรุปสถิตินักเรียนรายห้อง ({roomStudents.length} คน)
              </h3>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase">
                  <tr>
                    <th className="px-8 py-4">ลำดับ</th>
                    <th className="px-8 py-4">นักเรียน</th>
                    <th className="px-8 py-4">คะแนนพฤติกรรม</th>
                    <th className="px-8 py-4">สถิติมาเรียน</th>
                    <th className="px-8 py-4">ภาพรวม</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {roomStudents.map((s, idx) => {
                    const stats = getAttendanceStats(s.id);
                    return (
                      <tr key={s.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-8 py-5 text-sm font-bold text-slate-400">{idx + 1}</td>
                        <td className="px-8 py-5">
                          <p className="font-bold text-slate-900">{s.name}</p>
                          <p className="text-[10px] text-slate-500 font-medium uppercase">{s.studentId}</p>
                        </td>
                        <td className="px-8 py-5">
                          <span className={`font-black ${s.behaviorScore < 70 ? 'text-red-600' : 'text-slate-900'}`}>{s.behaviorScore}</span>
                        </td>
                        <td className="px-8 py-5">
                          <div className="flex items-center gap-3">
                            <div className="flex-1 h-2 bg-slate-100 rounded-full w-24 overflow-hidden">
                              <div className="h-full bg-blue-600 rounded-full" style={{ width: `${stats.rate}%` }} />
                            </div>
                            <span className="text-xs font-bold text-slate-600">{stats.rate}%</span>
                          </div>
                        </td>
                        <td className="px-8 py-5">
                          {s.behaviorScore < 70 || stats.rate < 80 ? (
                            <span className="px-3 py-1 bg-red-50 text-red-600 rounded-lg text-[9px] font-bold border border-red-100 uppercase">ต้องปรับปรุง</span>
                          ) : (
                            <span className="px-3 py-1 bg-green-50 text-green-600 rounded-lg text-[9px] font-bold border border-green-100 uppercase">ดีมาก</span>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                  {roomStudents.length === 0 && (
                    <tr><td colSpan={5} className="py-20 text-center text-slate-300 font-bold">ไม่พบข้อมูลในห้องเรียนนี้</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'individual' && (
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 animate-in slide-in-from-right-4">
          {user.role !== 'PARENT' && (
            <div className="lg:col-span-1">
              <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm h-[600px] flex flex-col">
                <div className="relative mb-4">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input type="text" placeholder="ค้นหาชื่อ/รหัส..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-12 pr-4 py-3 text-sm font-bold outline-none" />
                </div>
                <div className="flex-1 overflow-y-auto space-y-2 pr-2">
                  {students.filter(s => s.name.includes(searchTerm) || s.studentId.includes(searchTerm)).map(s => (
                    <button key={s.id} onClick={() => setSelectedStudentId(s.id)} className={`w-full text-left p-4 rounded-xl border transition-all ${selectedStudentId === s.id ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-white border-transparent hover:bg-slate-50'}`}>
                      <p className="font-bold text-sm truncate">{s.name}</p>
                      <p className={`text-[10px] font-medium mt-1 ${selectedStudentId === s.id ? 'text-slate-400' : 'text-slate-500'}`}>{s.studentId}</p>
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}

          <div className={`${user.role === 'PARENT' ? 'lg:col-span-4' : 'lg:col-span-3'} space-y-6`}>
            {selectedStudent ? (
              <div className="space-y-6">
                <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-8">
                  <div className="flex items-center gap-6">
                    <div className="w-20 h-20 bg-blue-600 rounded-[24px] flex items-center justify-center text-white shadow-xl">
                      <User size={40} />
                    </div>
                    <div>
                      <h2 className="text-3xl font-bold text-slate-900 font-heading">{selectedStudent.name}</h2>
                      <p className="text-slate-500 font-bold uppercase text-xs tracking-widest mt-1">{selectedStudent.studentId} • {selectedStudent.level} {selectedStudent.department}</p>
                    </div>
                  </div>
                  <div className="flex gap-4">
                    <button 
                      onClick={exportIndividualExcel}
                      className="flex items-center gap-2 px-6 py-3 bg-green-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-lg shadow-green-100 hover:bg-green-700 transition-all active:scale-95"
                    >
                      <FileSpreadsheet size={18} /> Export Excel
                    </button>
                    <div className="text-center px-6 py-4 bg-slate-50 rounded-2xl border border-slate-100">
                      <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">คะแนนพฤติกรรม</p>
                      <p className={`text-2xl font-black ${selectedStudent.behaviorScore < 70 ? 'text-red-600' : 'text-slate-900'}`}>{selectedStudent.behaviorScore}</p>
                    </div>
                    <div className="text-center px-6 py-4 bg-slate-50 rounded-2xl border border-slate-100">
                      <p className="text-[10px] font-bold text-slate-400 uppercase mb-1">มาเรียน</p>
                      <p className="text-2xl font-black text-blue-600">{getAttendanceStats(selectedStudent.id).rate}%</p>
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm">
                    <h3 className="text-lg font-bold text-slate-900 mb-6 flex items-center gap-3 font-heading">
                      <TrendingUp className="text-blue-600" size={20} /> รายการเช็คชื่อล่าสุด
                    </h3>
                    <div className="space-y-3">
                      {attendance.filter(a => a.studentId === selectedStudent.id).slice(-5).reverse().map(a => (
                        <div key={a.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-xl border border-slate-100">
                          <div>
                            <p className="font-bold text-sm text-slate-900">{a.type === 'MORNING' ? 'เข้าแถวหน้าเสาธง' : 'วิชาเรียน'}</p>
                            <p className="text-[10px] font-medium text-slate-400">{a.date}</p>
                          </div>
                          <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase border ${STATUS_LABELS[a.status].color}`}>
                            {STATUS_LABELS[a.status].label}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                  <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm">
                    <h3 className="text-lg font-bold text-slate-900 mb-6 flex items-center gap-3 font-heading">
                      <Award className="text-amber-600" size={20} /> บันทึกพฤติกรรมล่าสุด
                    </h3>
                    <div className="space-y-3">
                      {behavior.filter(b => b.studentId === selectedStudent.id).slice(-5).reverse().map(b => (
                        <div key={b.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-xl border border-slate-100">
                          <div>
                            <p className="font-bold text-sm text-slate-900 truncate max-w-[150px]">{b.reason}</p>
                            <p className="text-[10px] font-medium text-slate-400">{b.date}</p>
                          </div>
                          <span className={`font-black text-lg ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                            {b.type === 'ADD' ? '+' : '-'}{b.score}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            ) : (
              <div className="h-[600px] bg-white rounded-[32px] border-2 border-dashed border-slate-100 flex flex-col items-center justify-center p-20 text-center">
                <FileText size={64} className="text-slate-100 mb-6" />
                <h3 className="text-2xl font-bold text-slate-900 font-heading uppercase tracking-widest">โปรดเลือกนักเรียน</h3>
                <p className="text-slate-400 text-sm mt-2 font-bold opacity-50 uppercase">Select a student from the list to view report</p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

