import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard, MessageCircle, ExternalLink, Bell,
  Banknote, ChevronDown, ChevronUp, CheckCircle2, Copy, Check, Sun
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Cell
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-fit">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);
  const [copied, setCopied] = useState(false);
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  const [bankInfo, setBankInfo] = useState({
    bankName: 'ธนาคารกรุงไทย (Krungthai)',
    accountNo: '012-3-45678-9',
    accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
  });

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
    const savedBank = localStorage.getItem('cms_bank_info');
    if (savedBank) setBankInfo(JSON.parse(savedBank));
  }, []);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  // สถิติเฉพาะเข้าแถวหน้าเสาธง
  const morningAttendance = useMemo(() => attendance.filter(a => a.type === 'MORNING'), [attendance]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = morningAttendance.filter(a => 
      a.studentId === studentId && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    return Number((( (presentDays) * 5) / 18).toFixed(2));
  };

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, r) => sum + r.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  // กราฟสถิติการเข้าแถวหน้าเสาธงย้อนหลัง 7 วัน
  const chartData = useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => ({
      name: date,
      value: morningAttendance.filter(a => a.date === date && a.status === 'PRESENT').length
    }));
  }, [morningAttendance]);

  if (user.role === 'PARENT' || viewingStudentId) {
    const studentId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return <div className="p-20 text-center">ไม่พบข้อมูล</div>;

    const studentMorningAtt = morningAttendance.filter(a => a.studentId === student.id);
    const presentCount = studentMorningAtt.filter(a => a.status === 'PRESENT').length;
    const attRate = studentMorningAtt.length > 0 ? Math.round((presentCount / studentMorningAtt.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);
    const studentNotifications = notifications.filter(n => n.studentId === student.id).slice(0, 3);

    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-20">
        <div className="flex items-center justify-between gap-4">
          {user.role !== 'PARENT' && (
            <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border border-slate-100 rounded-2xl text-slate-600 font-bold hover:bg-slate-50 transition-all font-heading">
              <ArrowLeft size={18} /> กลับ
            </button>
          )}
          <div className="flex items-center gap-3 text-right ml-auto">
            <div>
              <p className="text-xs font-bold text-slate-400 uppercase tracking-widest font-heading">{user.role === 'PARENT' ? 'ข้อมูลบุตรหลาน' : 'มุมมองรายบุคคล'}</p>
              <p className="text-lg font-bold text-slate-900 font-heading">{student.name}</p>
            </div>
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><User size={24} /></div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-black text-slate-900 font-heading uppercase tracking-widest flex items-center gap-2">
              <Bell size={18} className="text-blue-600" /> แจ้งเตือนล่าสุด
            </h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {studentNotifications.length > 0 ? studentNotifications.map(n => (
              <div key={n.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex gap-4 items-start relative overflow-hidden">
                <div className={`w-1 h-full absolute left-0 top-0 ${n.type === 'ABSENT' ? 'bg-red-500' : 'bg-blue-500'}`} />
                <div className="ml-2">
                  <p className="font-black text-slate-900 text-xs truncate mb-1">{n.title}</p>
                  <p className="text-[10px] text-slate-600 line-clamp-2 font-bold">{n.message}</p>
                </div>
              </div>
            )) : <div className="col-span-3 text-center py-4 text-xs font-bold text-slate-400">ไม่มีการแจ้งเตือนใหม่</div>}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าแถว" value={`${attRate}%`} sub={`จากกิจกรรมหน้าเสาธง ${studentMorningAtt.length} ครั้ง`} icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore}`} sub={`บล็อกเรียนปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="คะแนนสะสมคงเหลือ" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        <div className="space-y-4">
          {finance.remaining > 0 ? (
            <div className="bg-gradient-to-br from-red-600 to-orange-600 p-8 md:p-10 rounded-[40px] text-white shadow-2xl relative overflow-hidden animate-in slide-in-from-bottom-6">
              <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
                <div className="text-center md:text-left">
                  <p className="text-xs font-black text-red-100 uppercase tracking-[0.3em] mb-2 opacity-80">ยอดค้างชำระปัจจุบัน</p>
                  <div className="flex items-baseline justify-center md:justify-start gap-3">
                    <h2 className="text-6xl font-black font-heading tracking-tighter">{finance.remaining.toLocaleString()}</h2>
                    <span className="text-2xl font-bold opacity-80 uppercase font-heading">บาท</span>
                  </div>
                </div>
                <button 
                  onClick={() => setShowPaymentDetails(!showPaymentDetails)}
                  className="w-full md:w-auto px-10 py-6 bg-white text-red-600 rounded-[28px] font-black text-lg uppercase tracking-widest shadow-xl hover:bg-red-50 transition-all flex items-center justify-center gap-3 active:scale-95"
                >
                  {showPaymentDetails ? <ChevronUp /> : <CreditCard />}
                  {showPaymentDetails ? 'ซ่อนรายละเอียด' : 'ชำระเงินตอนนี้'}
                </button>
              </div>
            </div>
          ) : (
            <div className="bg-green-50 p-8 rounded-[40px] border border-green-200 flex items-center justify-center gap-4">
              <CheckCircle2 className="text-green-600" size={32} />
              <p className="text-lg font-black text-green-900 font-heading">ชำระค่าเทอมครบถ้วนแล้ว</p>
            </div>
          )}

          {showPaymentDetails && finance.remaining > 0 && (
            <div className="bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-xl animate-in slide-in-from-top-4 space-y-8">
              <div className="flex items-center gap-4">
                <div className="p-4 bg-sky-50 text-[#00AEEF] rounded-2xl"><Banknote size={24} /></div>
                <div>
                  <h3 className="text-xl font-black text-slate-900 font-heading">ช่องทางการโอนเงิน</h3>
                  <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">Bank Transfer Details</p>
                </div>
              </div>

              <div className="p-8 md:p-10 bg-[#00AEEF] rounded-[32px] text-white relative overflow-hidden shadow-lg">
                <div className="absolute top-0 right-0 p-8 opacity-20 pointer-events-none transform translate-x-10 translate-y--10">
                   <Building2 size={240} />
                </div>
                <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-8">
                  <div className="flex-1 w-full">
                    <div className="flex flex-wrap items-center gap-x-12 gap-y-6 mb-6">
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">ธนาคาร</p>
                        <p className="text-xl font-bold font-heading">{bankInfo.bankName}</p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">ชื่อบัญชี</p>
                        <p className="text-xl font-bold font-heading">{bankInfo.accountName}</p>
                      </div>
                    </div>
                    <div className="space-y-1">
                      <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">เลขที่บัญชี</p>
                      <div className="flex items-center gap-6">
                        <p className="text-4xl md:text-5xl font-black tracking-tighter text-white font-heading">{bankInfo.accountNo}</p>
                        <button 
                          onClick={() => handleCopy(bankInfo.accountNo)}
                          className={`flex items-center justify-center gap-2 px-6 py-3 rounded-2xl font-black text-xs uppercase tracking-widest transition-all shadow-xl ${copied ? 'bg-green-500 text-white' : 'bg-white text-[#00AEEF] hover:bg-sky-50'}`}
                        >
                          {copied ? <Check size={16} /> : <Copy size={16} />}
                          {copied ? 'คัดลอกแล้ว' : 'คัดลอกเลขบัญชี'}
                        </button>
                      </div>
                    </div>
                  </div>

                  {lineUrl && (
                    <a href={lineUrl} target="_blank" rel="noreferrer" className="shrink-0 flex flex-col items-center justify-center gap-3 px-10 py-8 bg-[#06C755] text-white rounded-[32px] font-black text-xs uppercase tracking-widest hover:scale-105 transition-all shadow-2xl w-full md:w-auto">
                      <MessageCircle size={36} /> 
                      <span className="font-heading">แจ้งสลิปทาง LINE</span>
                    </a>
                  )}
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center justify-between gap-6">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-slate-900 rounded-xl text-white"><Filter size={20} /></div>
          <h4 className="font-black text-slate-900 text-sm font-heading">ตัวกรองวิเคราะห์ข้อมูลเข้าแถว</h4>
        </div>
        <div className="flex gap-4">
          <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="bg-slate-50 p-3 rounded-2xl text-[10px] font-black uppercase outline-none border border-slate-100">
            <option value="ALL">ทุกระดับชั้น</option>
            {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
          </select>
          <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="bg-slate-50 p-3 rounded-2xl text-[10px] font-black uppercase outline-none border border-slate-100">
            <option value="ALL">ทุกแผนกวิชา</option>
            {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="นักเรียนในกลุ่ม" value={filteredStudentsBase.length} sub="ตามเงื่อนไขที่เลือก" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เข้าแถววันนี้" value={morningAttendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="กิจกรรมหน้าเสาธง" icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
        <StatCard title="มาสายวันนี้" value={morningAttendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'LATE' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="หลังเวลา 08:00 น." icon={<Clock size={28} />} color="bg-amber-500" textColor="text-amber-600" />
        <StatCard title="ขาดแถววันนี้" value={morningAttendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'ABSENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="ไม่มีการเช็คชื่อ" icon={<ShieldAlert size={28} />} color="bg-red-600" textColor="text-red-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm h-[480px]">
          <div className="flex items-center justify-between mb-10">
            <h3 className="text-xl font-black text-slate-900 font-heading flex items-center gap-3">
               <BarChart3 className="text-[#00AEEF]" size={24} /> สถิติจำนวนคนเข้าแถว (ย้อนหลัง 7 วัน)
            </h3>
            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest bg-slate-50 px-4 py-1.5 rounded-full border">Assembly Statistics</span>
          </div>
          <ResponsiveContainer width="100%" height="80%">
            <BarChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis 
                dataKey="name" 
                axisLine={false} 
                tickLine={false} 
                tick={{fontSize: 10, fontWeight: 700, fill: '#94a3b8'}} 
              />
              <YAxis 
                axisLine={false} 
                tickLine={false} 
                tick={{fontSize: 10, fontWeight: 700, fill: '#94a3b8'}} 
              />
              <Tooltip 
                cursor={{fill: '#f8fafc'}}
                contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }}
              />
              <Bar dataKey="value" radius={[8, 8, 0, 0]} barSize={40}>
                {chartData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={index === chartData.length - 1 ? '#00AEEF' : '#cbd5e1'} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm overflow-hidden relative">
          <div className="absolute top-0 right-0 p-4 opacity-10 pointer-events-none">
             <AlertTriangle size={100} />
          </div>
          <h4 className="text-xs font-black text-slate-900 uppercase tracking-widest mb-6 font-heading">กลุ่มเฝ้าระวังพฤติกรรม</h4>
          <div className="space-y-4 relative z-10">
            {behaviorWatchlist.map(s => (
              <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="group flex items-center justify-between p-4 bg-red-50 hover:bg-red-100 rounded-2xl cursor-pointer transition-all">
                <div className="flex items-center gap-3">
                   <div className="w-8 h-8 bg-red-600 rounded-lg flex items-center justify-center text-white font-black text-[10px]">{s.name.charAt(0)}</div>
                   <span className="font-bold text-sm text-slate-900 truncate max-w-[120px]">{s.name}</span>
                </div>
                <div className="flex items-center gap-2">
                   <span className="font-black text-red-600">{s.behaviorScore}</span>
                   <ChevronRight size={16} className="text-red-300 group-hover:translate-x-1 transition-transform" />
                </div>
              </div>
            ))}
            {behaviorWatchlist.length === 0 && (
              <div className="py-20 text-center text-slate-300">
                 <CheckCircle2 size={40} className="mx-auto mb-2 opacity-20" />
                 <p className="text-xs font-bold">ไม่มีกลุ่มเฝ้าระวัง</p>
              </div>
            )}
          </div>
          <div className="mt-8 p-4 bg-slate-50 rounded-2xl border border-slate-100">
             <p className="text-[9px] font-bold text-slate-400 leading-relaxed">
               * กลุ่มเฝ้าระวังคำนวณจากนักเรียนที่มีคะแนนพฤติกรรมต่ำกว่า 70 คะแนน ซึ่งมีความเสี่ยงต่อการพ้นสภาพ
             </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard, MessageCircle, ExternalLink, Bell,
  Banknote, ChevronDown, ChevronUp, CheckCircle2, Copy, Check, Sun, PieChart
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Cell, Legend
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-full">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);
  const [copied, setCopied] = useState(false);
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  const [bankInfo, setBankInfo] = useState({
    bankName: 'ธนาคารกรุงไทย (Krungthai)',
    accountNo: '012-3-45678-9',
    accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
  });

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
    const savedBank = localStorage.getItem('cms_bank_info');
    if (savedBank) setBankInfo(JSON.parse(savedBank));
  }, []);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  // สถิติเฉพาะเข้าแถวหน้าเสาธง (Morning Assembly)
  const morningAttendance = useMemo(() => attendance.filter(a => a.type === 'MORNING'), [attendance]);

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  // กราฟสถิติการเข้าแถวหน้าเสาธงย้อนหลัง 7 วัน (Bar Chart)
  const chartData = useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const present = morningAttendance.filter(a => a.date === date && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length;
      return {
        name: new Date(date).toLocaleDateString('th-TH', { weekday: 'short' }),
        fullDate: date,
        value: present
      };
    });
  }, [morningAttendance, filteredStudentsBase]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = morningAttendance.filter(a => 
      a.studentId === studentId && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    return Number((( (presentDays) * 5) / 18).toFixed(2));
  };

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, r) => sum + r.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  // View สำหรับผู้ปกครอง หรือเมื่อเลือกดูรายบุคคล
  if (user.role === 'PARENT' || viewingStudentId) {
    const studentId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return <div className="p-20 text-center">ไม่พบข้อมูล</div>;

    const studentMorningAtt = morningAttendance.filter(a => a.studentId === student.id);
    const presentCount = studentMorningAtt.filter(a => a.status === 'PRESENT').length;
    const attRate = studentMorningAtt.length > 0 ? Math.round((presentCount / studentMorningAtt.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);
    const studentNotifications = notifications.filter(n => n.studentId === student.id).slice(0, 3);

    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-20">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            {user.role !== 'PARENT' && (
              <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border border-slate-100 rounded-2xl text-slate-600 font-bold hover:bg-slate-50 transition-all font-heading shadow-sm">
                <ArrowLeft size={18} /> กลับ
              </button>
            )}
            <div>
              <h2 className="text-3xl font-black text-slate-900 font-heading">ภาพรวมบุตรหลาน</h2>
              <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">{student.name}</p>
            </div>
          </div>
          <div className="flex items-center gap-3 bg-white p-2 pr-6 rounded-2xl border border-slate-100 shadow-sm">
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><User size={24} /></div>
            <div className="text-left">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">สถานะปัจจุบัน</p>
              <p className="text-sm font-bold text-slate-900 uppercase">ปวช. {student.level} | {student.department}</p>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าแถว" value={`${attRate}%`} sub={`จากกิจกรรมหน้าเสาธง ${studentMorningAtt.length} ครั้ง`} icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore}`} sub={`สะสมในบล็อกเรียนปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="คะแนนคงเหลือล่าสุด" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* แจ้งเตือน */}
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm h-full">
            <h3 className="text-xl font-black text-slate-900 font-heading mb-6 flex items-center gap-3 uppercase tracking-widest">
              <Bell size={24} className="text-blue-600" /> แจ้งเตือนล่าสุด
            </h3>
            <div className="space-y-4">
              {studentNotifications.length > 0 ? studentNotifications.map(n => (
                <div key={n.id} className="p-5 bg-slate-50 rounded-[24px] border border-slate-100 flex gap-4 items-start relative overflow-hidden transition-all hover:scale-[1.02]">
                  <div className={`w-1.5 h-full absolute left-0 top-0 ${n.type === 'ABSENT' ? 'bg-red-500' : 'bg-blue-500'}`} />
                  <div className="p-3 bg-white rounded-xl shadow-sm">
                    <Clock size={16} className="text-slate-400" />
                  </div>
                  <div>
                    <p className="font-black text-slate-900 text-sm mb-1">{n.title}</p>
                    <p className="text-xs text-slate-600 font-bold leading-relaxed">{n.message}</p>
                    <p className="text-[9px] text-slate-400 mt-2 font-black uppercase">{n.timestamp} • {n.date}</p>
                  </div>
                </div>
              )) : (
                <div className="text-center py-20 text-slate-300">
                  <Bell size={48} className="mx-auto mb-4 opacity-10" />
                  <p className="text-xs font-black uppercase tracking-widest">ไม่มีแจ้งเตือนใหม่</p>
                </div>
              )}
            </div>
          </div>

          {/* การเงิน */}
          <div className="space-y-6">
            {finance.remaining > 0 ? (
              <div className="bg-gradient-to-br from-red-600 to-orange-600 p-8 md:p-10 rounded-[40px] text-white shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                  <p className="text-[10px] font-black text-red-100 uppercase tracking-[0.3em] mb-4 opacity-80">ยอดค้างชำระค่าเทอม</p>
                  <div className="flex items-baseline gap-3 mb-8">
                    <h2 className="text-6xl font-black font-heading tracking-tighter">{finance.remaining.toLocaleString()}</h2>
                    <span className="text-2xl font-bold opacity-80 uppercase font-heading">บาท</span>
                  </div>
                  <button 
                    onClick={() => setShowPaymentDetails(!showPaymentDetails)}
                    className="w-full px-10 py-5 bg-white text-red-600 rounded-[24px] font-black text-sm uppercase tracking-widest shadow-xl hover:bg-red-50 transition-all flex items-center justify-center gap-3 active:scale-95"
                  >
                    {showPaymentDetails ? <ChevronUp /> : <CreditCard />}
                    {showPaymentDetails ? 'ซ่อนรายละเอียด' : 'ดูช่องทางชำระเงิน'}
                  </button>
                </div>
              </div>
            ) : (
              <div className="bg-green-50 p-10 rounded-[40px] border border-green-200 flex flex-col items-center justify-center text-center gap-4 h-full">
                <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center text-green-600">
                  <CheckCircle2 size={40} />
                </div>
                <h3 className="text-2xl font-black text-green-900 font-heading">ชำระครบถ้วนแล้ว</h3>
                <p className="text-sm text-green-700 font-bold">ขอบคุณที่ชำระค่าธรรมเนียมการศึกษาตามกำหนด</p>
              </div>
            )}

            {showPaymentDetails && finance.remaining > 0 && (
              <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-xl animate-in slide-in-from-top-4 space-y-6">
                <div className="p-8 bg-[#00AEEF] rounded-[32px] text-white relative overflow-hidden shadow-lg">
                  <div className="absolute top-0 right-0 p-8 opacity-20 pointer-events-none transform translate-x-10 translate-y--10">
                     <Building2 size={180} />
                  </div>
                  <div className="relative z-10 space-y-6">
                    <div className="flex flex-wrap gap-x-12 gap-y-4">
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">ธนาคาร</p>
                        <p className="text-lg font-bold font-heading">{bankInfo.bankName}</p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">ชื่อบัญชี</p>
                        <p className="text-lg font-bold font-heading">{bankInfo.accountName}</p>
                      </div>
                    </div>
                    <div className="space-y-1">
                      <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">เลขที่บัญชี</p>
                      <div className="flex items-center gap-6">
                        <p className="text-4xl md:text-5xl font-black tracking-tighter text-white font-heading">{bankInfo.accountNo}</p>
                        <button 
                          onClick={() => handleCopy(bankInfo.accountNo)}
                          className={`flex items-center justify-center gap-2 px-5 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all shadow-xl ${copied ? 'bg-green-500 text-white' : 'bg-white text-[#00AEEF] hover:bg-sky-50'}`}
                        >
                          {copied ? <Check size={14} /> : <Copy size={14} />}
                          {copied ? 'คัดลอกแล้ว' : 'คัดลอก'}
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
                {lineUrl && (
                  <a href={lineUrl} target="_blank" rel="noreferrer" className="flex items-center justify-center gap-3 py-5 bg-[#06C755] text-white rounded-[24px] font-black text-sm uppercase tracking-widest hover:scale-105 transition-all shadow-xl">
                    <MessageCircle size={24} /> 
                    <span>แจ้งสลิปผ่าน LINE Official</span>
                  </a>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  // View สำหรับ Admin / Teacher (ภาพรวมระบบ)
  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-center justify-between gap-6 bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
        <div className="flex items-center gap-5">
          <div className="p-4 bg-slate-900 rounded-[20px] text-white shadow-xl shadow-slate-100">
            <LayoutDashboard size={28} />
          </div>
          <div>
            <h2 className="text-2xl font-black text-slate-900 tracking-tight font-heading">แดชบอร์ดบริหารสถานศึกษา</h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Institutional Performance Metrics</p>
          </div>
        </div>

        <div className="flex gap-4 w-full lg:w-auto">
          <div className="flex-1 lg:w-48">
            <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3.5 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-400 transition-all">
              <option value="ALL">ทุกระดับชั้น</option>
              {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
            </select>
          </div>
          <div className="flex-1 lg:w-56">
            <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3.5 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-400 transition-all">
              <option value="ALL">ทุกแผนกวิชา</option>
              {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="จำนวนนักเรียน" value={filteredStudentsBase.length} sub="ในกลุ่มที่เลือก" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เข้าแถววันนี้" value={morningAttendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="กิจกรรมหน้าเสาธง" icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
        <StatCard title="มาสายวันนี้" value={morningAttendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'LATE' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="หลังเวลา 08:00 น." icon={<Clock size={28} />} color="bg-amber-500" textColor="text-amber-600" />
        <StatCard title="กลุ่มเฝ้าระวัง" value={behaviorWatchlist.length} sub="คะแนนพฤติกรรมต่ำ" icon={<ShieldAlert size={28} />} color="bg-red-600" textColor="text-red-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        {/* กราฟสถิติการเข้าแถว */}
        <div className="xl:col-span-2 bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm min-h-[500px] flex flex-col">
          <div className="flex items-center justify-between mb-10">
            <div>
              <h3 className="text-xl font-black text-slate-900 font-heading flex items-center gap-3">
                 <BarChart3 className="text-[#00AEEF]" size={24} /> สถิติจำนวนคนเข้าแถวรายวัน
              </h3>
              <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">7 Days Morning Assembly Attendance</p>
            </div>
            <div className="flex items-center gap-2 bg-sky-50 px-4 py-2 rounded-full border border-sky-100">
               <div className="w-2.5 h-2.5 bg-[#00AEEF] rounded-full animate-pulse" />
               <span className="text-[10px] font-black text-[#00AEEF] uppercase tracking-widest">Live Report</span>
            </div>
          </div>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="name" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fontSize: 10, fontWeight: 700, fill: '#94a3b8'}} 
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{fontSize: 10, fontWeight: 700, fill: '#94a3b8'}} 
                />
                <Tooltip 
                  cursor={{fill: '#f8fafc'}}
                  contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontFamily: 'Prompt' }}
                  labelStyle={{ fontWeight: 900, color: '#0f172a', marginBottom: '4px' }}
                />
                <Bar dataKey="value" name="จำนวนคนมาแถว" radius={[8, 8, 0, 0]} barSize={40}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index === chartData.length - 1 ? '#00AEEF' : '#cbd5e1'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* รายชื่อกลุ่มเฝ้าระวัง */}
        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm flex flex-col relative overflow-hidden">
          <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
             <AlertTriangle size={150} />
          </div>
          <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-8 font-heading flex items-center gap-2">
            <ShieldAlert size={20} className="text-red-600" /> รายชื่อกลุ่มเฝ้าระวังพฤติกรรม
          </h4>
          <div className="space-y-4 flex-1">
            {behaviorWatchlist.map(s => (
              <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="group flex items-center justify-between p-4 bg-red-50 hover:bg-red-100 rounded-2xl cursor-pointer transition-all border border-red-100/50">
                <div className="flex items-center gap-4">
                   <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-red-600 font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                   <div>
                     <p className="font-bold text-sm text-slate-900 truncate max-w-[140px] leading-tight">{s.name}</p>
                     <p className="text-[10px] text-slate-500 font-bold uppercase">{s.studentId}</p>
                   </div>
                </div>
                <div className="flex items-center gap-2">
                   <div className="text-right mr-2">
                      <p className="text-[9px] font-black text-red-400 uppercase tracking-tighter">คะแนน</p>
                      <p className="font-black text-red-600 leading-tight">{s.behaviorScore}</p>
                   </div>
                   <ChevronRight size={18} className="text-red-300 group-hover:translate-x-1 transition-transform" />
                </div>
              </div>
            ))}
            {behaviorWatchlist.length === 0 && (
              <div className="h-full flex flex-col items-center justify-center py-20 text-slate-300">
                 <CheckCircle2 size={48} className="mb-4 opacity-10" />
                 <p className="text-xs font-black uppercase tracking-widest">ไม่มีกลุ่มเฝ้าระวัง</p>
              </div>
            )}
          </div>
          <div className="mt-8 p-5 bg-slate-900 rounded-3xl text-white">
             <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest mb-1">สรุปสถานะพฤติกรรม</p>
             <p className="text-xs font-bold text-slate-400 leading-relaxed">
               พฤติกรรมเฉลี่ยของกลุ่มอยู่ที่ {filteredStudentsBase.length ? Math.round(filteredStudentsBase.reduce((a,b)=>a+b.behaviorScore,0)/filteredStudentsBase.length) : 0} คะแนน 
             </p>
          </div>
        </div>
      </div>

      {/* สถิติการเงินรายบล็อก (เฉพาะ Admin/Finance) */}
      {(user.role === 'ADMIN' || user.role === 'FINANCE') && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
           <div className="lg:col-span-1 bg-[#00AEEF] p-8 rounded-[40px] text-white shadow-xl relative overflow-hidden">
              <div className="absolute top-0 right-0 p-8 opacity-20 pointer-events-none transform translate-x-10 translate-y--10">
                 <PieChart size={180} />
              </div>
              <p className="text-[10px] font-black text-sky-100 uppercase tracking-[0.3em] mb-4 opacity-80 relative z-10">ภาพรวมการจัดเก็บค่าเทอม</p>
              <div className="flex items-baseline gap-2 relative z-10">
                <h2 className="text-5xl font-black font-heading tracking-tighter">
                  {Math.round((paymentRecords.reduce((sum, p) => sum + p.amount, 0) / (students.length * 10000)) * 100) || 0}
                </h2>
                <span className="text-xl font-bold opacity-80">%</span>
              </div>
              <div className="mt-10 pt-6 border-t border-white/20 relative z-10 flex justify-between items-center">
                 <div>
                    <p className="text-[9px] font-bold text-sky-100 uppercase opacity-60">ยอดจัดเก็บจริง</p>
                    <p className="text-lg font-black">{paymentRecords.reduce((sum, p) => sum + p.amount, 0).toLocaleString()} ฿</p>
                 </div>
                 <div className="text-right">
                    <p className="text-[9px] font-bold text-sky-100 uppercase opacity-60">เป้าหมายทั้งหมด</p>
                    <p className="text-lg font-black">{(students.length * 10000).toLocaleString()} ฿</p>
                 </div>
              </div>
           </div>

           <div className="lg:col-span-2 bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center gap-10">
              <div className="flex-1 w-full space-y-6">
                 <div>
                   <h3 className="text-xl font-black text-slate-900 font-heading">สถานะการชำระเงินรายบุคคล</h3>
                   <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">Tuition Payment Status</p>
                 </div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="p-5 bg-green-50 rounded-3xl border border-green-100">
                       <p className="text-[10px] font-black text-green-600 uppercase tracking-widest mb-1">ชำระแล้ว</p>
                       <p className="text-3xl font-black text-green-900">{students.filter(s => getFinancialStatus(s).remaining === 0).length} <span className="text-sm">คน</span></p>
                    </div>
                    <div className="p-5 bg-red-50 rounded-3xl border border-red-100">
                       <p className="text-[10px] font-black text-red-600 uppercase tracking-widest mb-1">ค้างชำระ</p>
                       <p className="text-3xl font-black text-red-900">{students.filter(s => getFinancialStatus(s).remaining > 0).length} <span className="text-sm">คน</span></p>
                    </div>
                 </div>
              </div>
              <div className="shrink-0">
                 <button onClick={() => window.location.hash = 'tuition'} className="p-8 bg-slate-100 hover:bg-slate-200 rounded-[32px] text-slate-900 transition-all flex flex-col items-center gap-3 group">
                    <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center shadow-md group-hover:scale-110 transition-transform">
                       <CreditCard size={28} className="text-blue-600" />
                    </div>
                    <span className="text-[10px] font-black uppercase tracking-widest">จัดการการเงิน</span>
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard, MessageCircle, ExternalLink, Bell,
  Banknote, ChevronDown, ChevronUp, CheckCircle2, Copy, Check, Sun, PieChart,
  LayoutDashboard
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Cell, Legend
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-full">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);
  const [copied, setCopied] = useState(false);
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  const [bankInfo, setBankInfo] = useState({
    bankName: 'ธนาคารกรุงไทย (Krungthai)',
    accountNo: '012-3-45678-9',
    accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
  });

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
    const savedBank = localStorage.getItem('cms_bank_info');
    if (savedBank) setBankInfo(JSON.parse(savedBank));
  }, []);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  // สถิติเฉพาะเข้าแถวหน้าเสาธง (Morning Assembly)
  const morningAttendance = useMemo(() => attendance.filter(a => a.type === 'MORNING'), [attendance]);

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  // กราฟสถิติการเข้าแถวหน้าเสาธงย้อนหลัง 7 วัน (Bar Chart)
  const chartData = useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const present = morningAttendance.filter(a => a.date === date && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length;
      return {
        name: new Date(date).toLocaleDateString('th-TH', { weekday: 'short' }),
        fullDate: date,
        value: present
      };
    });
  }, [morningAttendance, filteredStudentsBase]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = morningAttendance.filter(a => 
      a.studentId === studentId && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    return Number((( (presentDays) * 5) / 18).toFixed(2));
  };

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, r) => sum + r.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  // View สำหรับผู้ปกครอง หรือเมื่อเลือกดูรายบุคคล
  if (user.role === 'PARENT' || viewingStudentId) {
    const studentId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return <div className="p-20 text-center">ไม่พบข้อมูล</div>;

    const studentMorningAtt = morningAttendance.filter(a => a.studentId === student.id);
    const presentCount = studentMorningAtt.filter(a => a.status === 'PRESENT').length;
    const attRate = studentMorningAtt.length > 0 ? Math.round((presentCount / studentMorningAtt.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);
    const studentNotifications = notifications.filter(n => n.studentId === student.id).slice(0, 3);

    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-20">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            {user.role !== 'PARENT' && (
              <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border border-slate-100 rounded-2xl text-slate-600 font-bold hover:bg-slate-50 transition-all font-heading shadow-sm">
                <ArrowLeft size={18} /> กลับ
              </button>
            )}
            <div>
              <h2 className="text-3xl font-black text-slate-900 font-heading">ภาพรวมบุตรหลาน</h2>
              <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">{student.name}</p>
            </div>
          </div>
          <div className="flex items-center gap-3 bg-white p-2 pr-6 rounded-2xl border border-slate-100 shadow-sm">
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><User size={24} /></div>
            <div className="text-left">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">สถานะปัจจุบัน</p>
              <p className="text-sm font-bold text-slate-900 uppercase">ปวช. {student.level} | {student.department}</p>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าแถว" value={`${attRate}%`} sub={`จากกิจกรรมหน้าเสาธง ${studentMorningAtt.length} ครั้ง`} icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore}`} sub={`สะสมในบล็อกเรียนปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="คะแนนคงเหลือล่าสุด" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* แจ้งเตือน */}
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm h-full">
            <h3 className="text-xl font-black text-slate-900 font-heading mb-6 flex items-center gap-3 uppercase tracking-widest">
              <Bell size={24} className="text-blue-600" /> แจ้งเตือนล่าสุด
            </h3>
            <div className="space-y-4">
              {studentNotifications.length > 0 ? studentNotifications.map(n => (
                <div key={n.id} className="p-5 bg-slate-50 rounded-[24px] border border-slate-100 flex gap-4 items-start relative overflow-hidden transition-all hover:scale-[1.02]">
                  <div className={`w-1.5 h-full absolute left-0 top-0 ${n.type === 'ABSENT' ? 'bg-red-500' : 'bg-blue-500'}`} />
                  <div className="p-3 bg-white rounded-xl shadow-sm">
                    <Clock size={16} className="text-slate-400" />
                  </div>
                  <div>
                    <p className="font-black text-slate-900 text-sm mb-1">{n.title}</p>
                    <p className="text-xs text-slate-600 font-bold leading-relaxed">{n.message}</p>
