                            <span className="text-xs font-black text-slate-600">{stats.rate}%</span>
                          </div>
                        </td>
                        <td className="px-8 py-5">
                          {s.behaviorScore < 70 || stats.rate < 80 ? (
                            <span className="px-3 py-1 bg-red-50 text-red-600 rounded-lg text-[9px] font-black border border-red-100 uppercase">เฝ้าระวัง</span>
                          ) : (
                            <span className="px-3 py-1 bg-green-50 text-green-600 rounded-lg text-[9px] font-black border border-green-100 uppercase">ปกติ</span>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'individual' && (
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 animate-in slide-in-from-right-4">
          {!isParent && (
            <div className="lg:col-span-1">
              <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm h-[600px] flex flex-col">
                <div className="relative mb-4">
                  <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                  <input type="text" placeholder="ค้นหาชื่อ/รหัส..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-12 pr-4 py-3 text-sm font-bold outline-none" />
                </div>
                <div className="flex-1 overflow-y-auto space-y-2 pr-2 scrollbar-hide">
                  {students.filter(s => s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm)).map(s => (
                    <button key={s.id} onClick={() => setSelectedStudentId(s.id)} className={`w-full text-left p-4 rounded-xl border transition-all ${selectedStudentId === s.id ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-white border-transparent hover:bg-slate-50'}`}>
                      <p className="font-bold text-sm truncate">{s.name}</p>
                      <p className={`text-[10px] font-medium mt-1 ${selectedStudentId === s.id ? 'text-slate-400' : 'text-slate-500'}`}>{s.studentId}</p>
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}

          <div className={`${isParent ? 'lg:col-span-4' : 'lg:col-span-3'} space-y-6`}>
            {selectedStudent ? (
              <div className="space-y-6">
                <div className="bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none text-[#00AEEF]">
                    <User size={150} />
                  </div>
                  <div className="flex flex-col md:flex-row justify-between items-center gap-8 relative z-10">
                    <div className="flex items-center gap-6">
                      <div className="w-24 h-24 bg-[#00AEEF] rounded-[32px] flex items-center justify-center text-white shadow-2xl">
                        <User size={48} />
                      </div>
                      <div>
                        <h2 className="text-3xl font-black text-slate-900 font-heading leading-tight">{selectedStudent.name}</h2>
                        <div className="flex items-center gap-3 mt-2">
                           <span className="px-3 py-1 bg-slate-900 text-white rounded-lg text-[10px] font-black uppercase tracking-widest">{selectedStudent.studentId}</span>
                           <p className="text-slate-500 font-bold uppercase text-xs tracking-widest">{selectedStudent.level} | {selectedStudent.department}</p>
                        </div>
                      </div>
                    </div>
                    <div className="flex gap-4">
                      <button 
                        onClick={exportIndividualExcel}
                        className="flex items-center gap-3 px-8 py-4 bg-green-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-green-700 transition-all active:scale-95"
                      >
                        <FileSpreadsheet size={20} /> ส่งออกข้อมูล
                      </button>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mt-12">
                     <div className="bg-slate-50 p-6 rounded-[32px] border border-slate-100 text-center">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">คะแนนพฤติกรรม</p>
                        <p className={`text-3xl font-black ${selectedStudent.behaviorScore < 70 ? 'text-red-600' : 'text-slate-900'}`}>{selectedStudent.behaviorScore}</p>
                     </div>
                     <div className="bg-slate-50 p-6 rounded-[32px] border border-slate-100 text-center">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">อัตรามาเรียน</p>
                        <p className="text-3xl font-black text-[#00AEEF]">{getAttendanceStats(selectedStudent.id).rate}%</p>
                     </div>
                     <div className="bg-slate-50 p-6 rounded-[32px] border border-slate-100 text-center">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">มาเรียนจริง</p>
                        <p className="text-3xl font-black text-slate-900">{getAttendanceStats(selectedStudent.id).present} <span className="text-xs">วัน</span></p>
                     </div>
                     <div className="bg-slate-50 p-6 rounded-[32px] border border-slate-100 text-center">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">สถานะพฤติกรรม</p>
                        <p className={`text-xs font-black uppercase mt-2 ${selectedStudent.behaviorScore < 70 ? 'text-red-600' : 'text-green-600'}`}>
                           {selectedStudent.behaviorScore < 70 ? 'ควรปรับปรุง' : 'ดีมาก'}
                        </p>
                     </div>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm h-full flex flex-col">
                    <h3 className="text-lg font-black text-slate-900 mb-8 flex items-center gap-3 font-heading uppercase tracking-widest">
                      <Clock className="text-[#00AEEF]" size={24} /> สถิติการเช็คชื่อล่าสุด
                    </h3>
                    <div className="space-y-4 flex-1">
                      {attendance.filter(a => a.studentId === selectedStudent.id).slice(-10).reverse().map(a => (
                        <div key={a.id} className="flex items-center justify-between p-5 bg-slate-50 rounded-[24px] border border-slate-100 transition-all hover:scale-[1.02]">
                          <div className="flex items-center gap-4">
                             <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-white ${a.type === 'MORNING' ? 'bg-amber-500' : 'bg-blue-600'}`}>
                                {a.type === 'MORNING' ? <Sun size={20} /> : <FileText size={20} />}
                             </div>
                             <div>
                               <p className="font-black text-sm text-slate-900 leading-tight">{a.type === 'MORNING' ? 'กิจกรรมหน้าเสาธง' : 'รายวิชา'}</p>
                               <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase tracking-widest">{a.date} • {a.timestamp.split(' ')[1]}</p>
                             </div>
                          </div>
                          <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase border shadow-sm ${STATUS_LABELS[a.status].color}`}>
                            {STATUS_LABELS[a.status].label}
                          </span>
                        </div>
                      ))}
                      {attendance.filter(a => a.studentId === selectedStudent.id).length === 0 && (
                        <div className="py-20 text-center text-slate-300">
                           <Clock size={48} className="mx-auto mb-4 opacity-10" />
                           <p className="text-[10px] font-black uppercase tracking-widest">ไม่มีข้อมูลการเช็คชื่อ</p>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm h-full flex flex-col">
                    <h3 className="text-lg font-black text-slate-900 mb-8 flex items-center gap-3 font-heading uppercase tracking-widest">
                      <Award className="text-amber-600" size={24} /> บันทึกความประพฤติ
                    </h3>
                    <div className="space-y-4 flex-1">
                      {behavior.filter(b => b.studentId === selectedStudent.id).slice(-10).reverse().map(b => (
                        <div key={b.id} className="flex items-center justify-between p-5 bg-slate-50 rounded-[24px] border border-slate-100 transition-all hover:scale-[1.02]">
                          <div className="flex items-center gap-4">
                             <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-white ${b.type === 'ADD' ? 'bg-green-600' : 'bg-red-600'}`}>
                                {b.type === 'ADD' ? <Plus size={20} /> : <TrendingUp size={20} className="rotate-180" />}
                             </div>
                             <div>
                               <p className="font-black text-sm text-slate-900 truncate max-w-[150px] leading-tight">{b.reason}</p>
                               <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase tracking-widest">{b.date} • {b.recordedBy}</p>
                             </div>
                          </div>
                          <div className="text-right">
                             <p className={`text-xl font-black ${b.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                               {b.type === 'ADD' ? '+' : '-'}{b.score}
                             </p>
                             <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">แต้ม</p>
                          </div>
                        </div>
                      ))}
                      {behavior.filter(b => b.studentId === selectedStudent.id).length === 0 && (
                        <div className="py-20 text-center text-slate-300">
                           <Award size={48} className="mx-auto mb-4 opacity-10" />
                           <p className="text-[10px] font-black uppercase tracking-widest">ไม่มีประวัติพฤติกรรม</p>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            ) : (
              <div className="h-[600px] bg-white rounded-[48px] border-4 border-dashed border-slate-100 flex flex-col items-center justify-center p-20 text-center animate-pulse">
                <FileText size={64} className="text-slate-100 mb-6" />
                <h3 className="text-2xl font-black text-slate-900 font-heading uppercase tracking-widest">โปรดเลือกนักเรียน</h3>
                <p className="text-slate-400 text-sm mt-2 font-bold opacity-50 uppercase">Select a student from the list to view report</p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default Reports;

import React, { useState, useMemo, useEffect } from 'react';
import { Student, AttendanceRecord, BehaviorRecord, StudyBlock, PaymentRecord } from '../types';
import * as XLSX from 'https://esm.sh/xlsx';
import { 
  FileText, 
  Search, 
  Download, 
  User, 
  Award, 
  TrendingUp,
  Users,
  BarChart3,
  CheckCircle2,
  AlertCircle,
  FileSpreadsheet,
  Clock,
  Wallet,
  Calendar,
  ChevronRight,
  /* Added missing icons to fix line 291 and 321 */
  Sun,
  Plus
} from 'lucide-react';
import { STATUS_LABELS } from '../constants';

interface ReportsProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: BehaviorRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  paymentRecords?: PaymentRecord[];
}

const Reports: React.FC<ReportsProps> = ({ 
  students, attendance, behavior, user, studyBlocks, paymentRecords = []
}) => {
  const isParent = user.role === 'PARENT';

  // ค้นหาข้อมูลนักเรียนที่เป็นลูกของผู้ปกครองท่านนี้
  const parentChild = useMemo(() => {
    if (!isParent) return null;
    return students.find(s => s.studentId === user.studentId);
  }, [isParent, students, user.studentId]);

  const [activeTab, setActiveTab] = useState<'individual' | 'room'>(isParent ? 'individual' : 'room');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(
    isParent ? parentChild?.id || null : null
  );

  // อัปเดต selectedStudentId เมื่อข้อมูลลูกโหลดมา (กรณี Parent)
  useEffect(() => {
    if (isParent && parentChild) {
      setSelectedStudentId(parentChild.id);
    }
  }, [isParent, parentChild]);

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level as string))).sort((a, b) => (a as string).localeCompare(b as string)), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department as string))).sort((a, b) => (a as string).localeCompare(b as string)), [students]);
  const availableRooms = useMemo(() => Array.from(new Set(students.map(s => s.room as string))).sort((a, b) => parseInt(a as string) - parseInt(b as string)), [students]);

  const [reportLevel, setReportLevel] = useState<string>(availableLevels[0] || '');
  const [reportDept, setReportDept] = useState<string>(availableDepts[0] || '');
  const [reportRoom, setReportRoom] = useState<string>(availableRooms[0] || '');

  const selectedStudent = useMemo(() => students.find(s => s.id === selectedStudentId), [students, selectedStudentId]);

  const roomStudents = useMemo(() => {
    return students.filter(s => 
      s.level === reportLevel && s.department === reportDept && s.room === reportRoom
    );
  }, [students, reportLevel, reportDept, reportRoom]);

  const getAttendanceStats = (studentId: string) => {
    const studentRecords = attendance.filter(a => a.studentId === studentId);
    const total = studentRecords.length;
    const present = studentRecords.filter(r => r.status === 'PRESENT').length;
    const rate = total > 0 ? Math.round((present / total) * 100) : 0;
    return { total, present, rate };
  };

  const exportIndividualExcel = () => {
    if (!selectedStudent) return;

    const attData = attendance
      .filter(a => a.studentId === selectedStudent.id)
      .map(a => ({
        'วันที่': a.date,
        'ประเภท': a.type === 'MORNING' ? 'เข้าแถว' : 'รายวิชา',
        'สถานะ': STATUS_LABELS[a.status]?.label || a.status,
        'หมายเหตุ': a.remark || '-',
        'เวลาที่บันทึก': a.timestamp
      }));

    const behData = behavior
      .filter(b => b.studentId === selectedStudent.id)
      .map(b => ({
        'วันที่': b.date,
        'รายการ': b.reason,
        'ประเภท': b.type === 'ADD' ? 'เพิ่มคะแนน' : 'หักคะแนน',
        'คะแนน': b.score,
        'ผู้บันทึก': b.recordedBy
      }));

    const wb = XLSX.utils.book_new();
    const wsAtt = XLSX.utils.json_to_sheet(attData);
    XLSX.utils.book_append_sheet(wb, wsAtt, "สถิติการมาเรียน");
    const wsBeh = XLSX.utils.json_to_sheet(behData);
    XLSX.utils.book_append_sheet(wb, wsBeh, "บันทึกพฤติกรรม");

    XLSX.writeFile(wb, `รายงานผล_${selectedStudent.studentId}_${selectedStudent.name}.xlsx`);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex bg-white p-2 rounded-2xl border border-slate-200 shadow-sm w-fit">
        {!isParent && (
          <button onClick={() => setActiveTab('room')} className={`flex items-center gap-2 px-8 py-3.5 rounded-xl text-sm font-black transition-all font-heading ${activeTab === 'room' ? 'bg-[#00AEEF] text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
            <Users size={18} /> สรุปรายห้อง
          </button>
        )}
        <button onClick={() => setActiveTab('individual')} className={`flex items-center gap-2 px-8 py-3.5 rounded-xl text-sm font-black transition-all font-heading ${activeTab === 'individual' ? 'bg-[#00AEEF] text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
          <User size={18} /> {isParent ? 'รายงานผลบุตรหลาน' : 'รายงานผลรายบุคคล'}
        </button>
      </div>

      {activeTab === 'room' && !isParent && (
        <div className="space-y-8 animate-in slide-in-from-bottom-4">
          <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm grid grid-cols-1 md:grid-cols-4 gap-6 items-end">
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">ระดับชั้น</label>
              <select value={reportLevel} onChange={(e) => setReportLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-3.5 font-bold text-slate-900 outline-none">
                {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">แผนกวิชา</label>
              <select value={reportDept} onChange={(e) => setReportDept(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-3.5 font-bold text-slate-900 outline-none">
                {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest ml-1 font-heading">ห้อง</label>
              <select value={reportRoom} onChange={(e) => setReportRoom(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-5 py-3.5 font-bold text-slate-900 outline-none">
                {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>
            <button className="bg-[#00AEEF] text-white px-8 py-4 rounded-xl font-bold flex items-center justify-center gap-3 shadow-lg shadow-blue-100 hover:bg-sky-600 transition-all font-heading">
              <Download size={20} /> ออกรายงานรวม
            </button>
          </div>

          <div className="bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
            <div className="p-8 border-b bg-slate-50/50 flex items-center justify-between">
              <h3 className="text-xl font-bold text-slate-900 flex items-center gap-3 font-heading">
                <BarChart3 className="text-[#00AEEF]" size={24} /> 
                ภาพรวมนักเรียน {reportLevel} / {reportDept} ห้อง {reportRoom}
              </h3>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase">
                  <tr>
                    <th className="px-8 py-4">ลำดับ</th>
                    <th className="px-8 py-4">ชื่อ-นามสกุล</th>
                    <th className="px-8 py-4">คะแนนพฤติกรรม</th>
                    <th className="px-8 py-4">มาเรียน/เข้าแถว</th>
                    <th className="px-8 py-4">สถานะ</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {roomStudents.map((s, idx) => {
                    const stats = getAttendanceStats(s.id);
                    return (
                      <tr key={s.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-8 py-5 text-sm font-bold text-slate-400">{idx + 1}</td>
                        <td className="px-8 py-5">
                          <p className="font-bold text-slate-900">{s.name}</p>
                          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{s.studentId}</p>
                        </td>
                        <td className="px-8 py-5">
                          <span className={`font-black ${s.behaviorScore < 70 ? 'text-red-600' : 'text-slate-900'}`}>{s.behaviorScore}</span>
                        </td>
                        <td className="px-8 py-5">
                          <div className="flex items-center gap-3">
