import React, { useState } from 'react';
import { MENU_ITEMS, MENU_GROUPS } from '../constants';
import { LogOut, Menu, User, ChevronRight, Bell, Search, Settings, X, Clock, AlertCircle } from 'lucide-react';
import { NotificationRecord } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  activeMenu: string;
  setActiveMenu: (menu: string) => void;
  user: any;
  onLogout: () => void;
  notifications?: NotificationRecord[];
  setNotifications?: React.Dispatch<React.SetStateAction<NotificationRecord[]>>;
}

const Layout: React.FC<LayoutProps> = ({ 
  children, 
  activeMenu, 
  setActiveMenu, 
  user, 
  onLogout,
  notifications = [],
  setNotifications
}) => {
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isNotifOpen, setIsNotifOpen] = useState(false);

  const filteredMenuItems = MENU_ITEMS.filter(item => 
    item.roles.includes(user.role)
  );

  const groups = Array.from(new Set(filteredMenuItems.map(item => item.group)));

  // แก้ไขระบบแจ้งเตือน: แสดงเฉพาะผู้ปกครอง (PARENT) กรองเฉพาะลูก และเรียงลำดับล่าสุดไว้บนสุด
  const userNotifications = React.useMemo(() => {
    if (user.role !== 'PARENT') return [];

    return notifications
      .filter(n => n.studentId === user.studentId)
      .sort((a, b) => {
        // เรียงตาม ID หรือ Timestamp จริง (สมมติ ID มีส่วนประกอบของเวลา หรือใช้ Date เปรียบเทียบ)
        const dateA = new Date(`${a.date} ${a.timestamp}`).getTime();
        const dateB = new Date(`${b.date} ${b.timestamp}`).getTime();
        return dateB - dateA;
      });
  }, [notifications, user]);

  const unreadCount = userNotifications.filter(n => !n.isRead).length;

  const handleToggleNotif = () => {
    setIsNotifOpen(!isNotifOpen);
    if (!isNotifOpen && setNotifications && unreadCount > 0) {
      setNotifications(prev => prev.map(n => {
        if (n.studentId === user.studentId) {
          return { ...n, isRead: true };
        }
        return n;
      }));
    }
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] overflow-hidden">
      {isSidebarOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-40 md:hidden animate-in fade-in duration-300"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      <aside className={`
        fixed inset-y-0 left-0 z-50 w-[280px] bg-slate-900 text-white transform transition-all duration-500 ease-[cubic-bezier(0.4,0,0.2,1)]
        md:relative md:translate-x-0 border-r border-slate-800 shadow-2xl flex flex-col
        ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="p-8 pb-4 shrink-0">
          <div className="flex items-center gap-3 group">
            <div className="w-12 h-12 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-2xl flex items-center justify-center shadow-lg shadow-blue-500/20 group-hover:scale-110 transition-transform duration-300">
              <span className="text-xl font-bold italic tracking-tighter font-heading">ES</span>
            </div>
            <div>
              <h1 className="text-xl font-bold tracking-tight leading-none font-heading">EduSmart</h1>
              <span className="text-[10px] font-semibold uppercase tracking-[0.2em] text-blue-400 opacity-90 font-heading">CMS Official</span>
            </div>
          </div>
        </div>

        <div className="flex-1 overflow-y-auto px-4 py-6 scrollbar-hide space-y-8">
          {groups.map((groupKey) => (
            <div key={groupKey} className="space-y-2">
              <h3 className="px-4 text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3 font-heading">
                {(MENU_GROUPS as any)[groupKey]}
              </h3>
              <div className="space-y-1">
                {filteredMenuItems
                  .filter(item => item.group === groupKey)
                  .map((item) => {
                    const isActive = activeMenu === item.id;
                    return (
                      <button
                        key={item.id}
                        onClick={() => {
                          setActiveMenu(item.id);
                          setSidebarOpen(false);
                        }}
                        className={`
                          w-full group flex items-center justify-between px-4 py-3 rounded-xl transition-all duration-300 relative
                          ${isActive 
                            ? 'bg-blue-600/10 text-white' 
                            : 'text-slate-400 hover:text-white hover:bg-white/5'}
                        `}
                      >
                        <div className="flex items-center gap-4 relative z-10">
                          <div className={`
                            w-9 h-9 rounded-lg flex items-center justify-center transition-all duration-300
                            ${isActive ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-800 group-hover:bg-slate-700'}
                          `}>
                            {React.cloneElement(item.icon as React.ReactElement<any>, { size: 16 })}
                          </div>
                          <span className={`text-sm font-medium transition-all duration-300 font-heading ${isActive ? 'translate-x-1' : ''}`}>
                            {item.label}
                          </span>
                        </div>
                        {isActive && (
                          <div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse" />
                        )}
                      </button>
                    );
                  })}
              </div>
            </div>
          ))}
        </div>

        <div className="p-4 border-t border-slate-800/50 bg-slate-900/50 shrink-0">
          <div className="bg-slate-800/40 border border-white/5 rounded-2xl p-4">
            <div className="flex items-center gap-3 mb-4">
              <div className="w-9 h-9 rounded-lg bg-slate-700 flex items-center justify-center text-white border border-white/10">
                <User size={16} />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-xs font-semibold text-white truncate font-heading">{user.name}</p>
                <p className="text-[10px] font-medium text-slate-500 truncate uppercase font-heading">{user.role}</p>
              </div>
            </div>
            <button 
              onClick={onLogout}
              className="w-full flex items-center justify-center gap-2 py-2.5 bg-red-500/10 hover:bg-red-500 text-red-500 hover:text-white rounded-lg transition-all duration-300 font-bold text-[10px] uppercase tracking-wider font-heading border border-red-500/20"
            >
              <LogOut size={12} /> ออกจากระบบ
            </button>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-16 bg-white border-b border-slate-200 flex items-center justify-between px-8 shrink-0 z-30 sticky top-0">
          <div className="flex items-center gap-6">
            <button 
              className="md:hidden p-2.5 bg-slate-100 hover:bg-slate-200 text-slate-900 rounded-xl transition-all"
              onClick={() => setSidebarOpen(true)}
            >
              <Menu size={20} />
            </button>
            <div className="hidden sm:flex flex-col">
              <h2 className="text-lg font-bold text-slate-900 tracking-tight leading-none font-heading">
                {MENU_ITEMS.find(i => i.id === activeMenu)?.label}
              </h2>
            </div>
          </div>

          <div className="flex items-center gap-4">
            {user.role === 'PARENT' && (
              <div className="relative">
                <button 
                  onClick={handleToggleNotif}
                  className={`p-2.5 rounded-xl transition-all relative group ${isNotifOpen ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-50 text-slate-500 hover:bg-slate-100 border border-slate-200'}`}
                >
                  <Bell size={20} className={unreadCount > 0 ? "animate-[swing_2s_ease-in-out_infinite]" : ""} />
                  {unreadCount > 0 && (
                    <span className="absolute -top-1.5 -right-1.5 min-w-[20px] h-5 bg-red-600 text-white text-[10px] font-black rounded-full flex items-center justify-center border-2 border-white shadow-lg animate-bounce z-10 px-1">
                      {unreadCount > 99 ? '99+' : unreadCount}
                    </span>
                  )}
                </button>

                {isNotifOpen && (
                  <div className="absolute right-0 mt-4 w-80 md:w-96 bg-white rounded-[24px] shadow-2xl border border-slate-200 overflow-hidden animate-in slide-in-from-top-2 duration-300 z-50">
                    <div className="p-5 border-b bg-slate-50/50 flex items-center justify-between">
                      <h3 className="font-black text-slate-900 text-sm uppercase tracking-widest font-heading">แจ้งเตือนของคุณ</h3>
                      <button onClick={() => setIsNotifOpen(false)} className="text-slate-400 hover:text-slate-900"><X size={18} /></button>
                    </div>
                    <div className="max-h-[400px] overflow-y-auto scrollbar-hide">
                      {userNotifications.length > 0 ? userNotifications.map((n) => (
                        <div key={n.id} className={`p-4 border-b last:border-0 hover:bg-slate-50 transition-colors flex gap-4 ${!n.isRead ? 'bg-blue-50/40' : ''}`}>
                          <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 shadow-sm ${
                            n.type === 'ABSENT' ? 'bg-red-500 text-white' : 
                            n.type === 'LATE' ? 'bg-amber-500 text-white' : 'bg-blue-500 text-white'
                          }`}>
                            <AlertCircle size={18} />
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex justify-between items-start mb-0.5">
                              <p className="text-[11px] font-black text-slate-900 leading-tight">{n.title}</p>
                              {!n.isRead && <div className="w-2 h-2 bg-blue-600 rounded-full shrink-0 mt-1" />}
                            </div>
                            <p className="text-[10px] text-slate-600 line-clamp-2 leading-relaxed">{n.message}</p>
                            <div className="flex items-center gap-2 mt-2 opacity-50">
                              <Clock size={10} />
                              <span className="text-[9px] font-bold uppercase tracking-tighter">{n.timestamp} • {n.date}</span>
                            </div>
                          </div>
                        </div>
                      )) : (
                        <div className="p-12 text-center text-slate-300">
                          <Bell size={48} className="mx-auto mb-4 opacity-10" />
                          <p className="text-xs font-bold uppercase tracking-widest">ยังไม่มีการแจ้งเตือน</p>
                        </div>
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}

            <div className="h-8 w-px bg-slate-200 mx-1 hidden sm:block" />
            <div className="flex items-center gap-3">
              <div className="text-right hidden sm:block">
                <p className="text-xs font-bold text-slate-900 leading-none font-heading">{user.name}</p>
                <p className="text-[10px] font-medium text-slate-400 mt-1 uppercase font-heading">{user.department || 'Official'}</p>
              </div>
              <div className="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-900 border border-slate-200">
                <User size={18} />
              </div>
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto px-6 md:px-10 py-8 scroll-smooth">
          <div className="max-w-[1600px] mx-auto">
            {children}
          </div>
        </div>
      </main>

      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes swing {
          0%, 100% { transform: rotate(0deg); }
          20% { transform: rotate(15deg); }
          40% { transform: rotate(-10deg); }
          60% { transform: rotate(5deg); }
          80% { transform: rotate(-5deg); }
        }
      `}} />
    </div>
  );
};

export default Layout;

