                >
                  <Bell size={20} className={unreadCount > 0 ? "animate-[swing_2s_ease-in-out_infinite]" : ""} />
                  {unreadCount > 0 && (
                    <span className="absolute -top-1.5 -right-1.5 min-w-[20px] h-5 bg-red-600 text-white text-[10px] font-black rounded-full flex items-center justify-center border-2 border-white shadow-lg animate-bounce z-10 px-1">
                      {unreadCount > 99 ? '99+' : unreadCount}
