import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard, MessageCircle, ExternalLink, Bell,
  Banknote, ChevronDown, ChevronUp, CheckCircle2, Copy, Check, Sun, PieChart,
  LayoutDashboard
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Cell, Legend
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-full">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);
  const [copied, setCopied] = useState(false);
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  const [bankInfo, setBankInfo] = useState({
    bankName: 'ธนาคารกรุงไทย (Krungthai)',
    accountNo: '012-3-45678-9',
    accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
  });

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
    const savedBank = localStorage.getItem('cms_bank_info');
    if (savedBank) setBankInfo(JSON.parse(savedBank));
  }, []);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  // สถิติเฉพาะเข้าแถวหน้าเสาธง (Morning Assembly)
  const morningAttendance = useMemo(() => attendance.filter(a => a.type === 'MORNING'), [attendance]);

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  // กราฟสถิติการเข้าแถวหน้าเสาธงย้อนหลัง 7 วัน (Bar Chart)
  const chartData = useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const present = morningAttendance.filter(a => a.date === date && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length;
      return {
        name: new Date(date).toLocaleDateString('th-TH', { weekday: 'short' }),
        fullDate: date,
        value: present
      };
    });
  }, [morningAttendance, filteredStudentsBase]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = morningAttendance.filter(a => 
      a.studentId === studentId && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    return Number((( (presentDays) * 5) / 18).toFixed(2));
  };

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, r) => sum + r.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  // View สำหรับผู้ปกครอง หรือเมื่อเลือกดูรายบุคคล
  if (user.role === 'PARENT' || viewingStudentId) {
    const studentId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === studentId || s.studentId === studentId);
    if (!student) return <div className="p-20 text-center">ไม่พบข้อมูล</div>;

    const studentMorningAtt = morningAttendance.filter(a => a.studentId === student.id);
    const presentCount = studentMorningAtt.filter(a => a.status === 'PRESENT').length;
    const attRate = studentMorningAtt.length > 0 ? Math.round((presentCount / studentMorningAtt.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);

    // เรียงการแจ้งเตือนล่าสุดไว้บนสุดเสมอ
    const studentNotifications = useMemo(() => {
      return notifications
        .filter(n => n.studentId === student.id)
        .sort((a, b) => {
          const timeA = new Date(`${a.date} ${a.timestamp}`).getTime();
          const timeB = new Date(`${b.date} ${b.timestamp}`).getTime();
          return timeB - timeA;
        })
        .slice(0, 5); // แสดง 5 รายการล่าสุดในแดชบอร์ด
    }, [notifications, student.id]);

    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-20">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            {user.role !== 'PARENT' && (
              <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border border-slate-100 rounded-2xl text-slate-600 font-bold hover:bg-slate-50 transition-all font-heading shadow-sm">
                <ArrowLeft size={18} /> กลับ
              </button>
            )}
            <div>
              <h2 className="text-3xl font-black text-slate-900 font-heading">ภาพรวมบุตรหลาน</h2>
              <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">{student.name}</p>
            </div>
          </div>
          <div className="flex items-center gap-3 bg-white p-2 pr-6 rounded-2xl border border-slate-100 shadow-sm">
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><User size={24} /></div>
            <div className="text-left">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">สถานะปัจจุบัน</p>
              <p className="text-sm font-bold text-slate-900 uppercase">ปวช. {student.level} | {student.department}</p>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าแถว" value={`${attRate}%`} sub={`จากกิจกรรมหน้าเสาธง ${studentMorningAtt.length} ครั้ง`} icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore}`} sub={`สะสมในบล็อกเรียนปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="คะแนนคงเหลือล่าสุด" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {/* แจ้งเตือนล่าสุด */}
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm h-full">
