                </div>
              )) : (
                <div className="text-center py-20 text-slate-300">
                  <Bell size={48} className="mx-auto mb-4 opacity-10" />
                  <p className="text-xs font-black uppercase tracking-widest">ไม่มีแจ้งเตือนใหม่</p>
                </div>
              )}
            </div>
          </div>

          {/* การเงิน */}
          <div className="space-y-6">
