              <div className="bg-green-50 p-10 rounded-[40px] border border-green-200 flex flex-col items-center justify-center text-center gap-4 h-full">
                <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center text-green-600">
                  <CheckCircle2 size={40} />
