        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard, MessageCircle, ExternalLink, Bell,
  Banknote, ChevronDown, ChevronUp, CheckCircle2, Copy, Check, Sun, PieChart,
  LayoutDashboard
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Cell, Legend
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-full">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);
  const [copied, setCopied] = useState(false);
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  const [bankInfo, setBankInfo] = useState({
    bankName: 'ธนาคารกรุงไทย (Krungthai)',
    accountNo: '012-3-45678-9',
    accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
  });

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
    const savedBank = localStorage.getItem('cms_bank_info');
    if (savedBank) setBankInfo(JSON.parse(savedBank));
  }, []);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  const morningAttendance = useMemo(() => attendance.filter(a => a.type === 'MORNING'), [attendance]);

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = morningAttendance.filter(a => 
      a.studentId === studentId && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    return Number((( (presentDays) * 5) / 18).toFixed(2));
  };

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudentsBase
      .filter(s => getMorningScore(s.id) < 3.0)
      .sort((a,b) => getMorningScore(a.id) - getMorningScore(b.id))
      .slice(0, 6)
  , [filteredStudentsBase, morningAttendance, studyBlocks]);

  const chartData = useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const present = morningAttendance.filter(a => a.date === date && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length;
      return {
        name: new Date(date).toLocaleDateString('th-TH', { weekday: 'short' }),
        fullDate: date,
        value: present
      };
    });
  }, [morningAttendance, filteredStudentsBase]);

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, r) => sum + r.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  if (user.role === 'PARENT' || viewingStudentId) {
    const targetId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === targetId || s.studentId === targetId);

    if (!student) {
      return (
        <div className="p-20 text-center flex flex-col items-center justify-center space-y-4">
          <AlertTriangle size={64} className="text-amber-500" />
          <h2 className="text-2xl font-black text-slate-900 font-heading">ไม่พบข้อมูลนักเรียน</h2>
          <button onClick={() => setViewingStudentId(null)} className="px-6 py-2 bg-slate-900 text-white rounded-xl font-bold">กลับสู่แดชบอร์ด</button>
        </div>
      );
    }

    const studentMorningAtt = morningAttendance.filter(a => a.studentId === student.id);
    const presentCount = studentMorningAtt.filter(a => a.status === 'PRESENT').length;
    const attRate = studentMorningAtt.length > 0 ? Math.round((presentCount / studentMorningAtt.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);

    const studentNotifications = useMemo(() => {
      return notifications
        .filter(n => n.studentId === student.id)
        .sort((a, b) => {
          const timeA = new Date(`${a.date} ${a.timestamp}`).getTime();
          const timeB = new Date(`${b.date} ${b.timestamp}`).getTime();
          return timeB - timeA;
        })
        .slice(0, 5);
    }, [notifications, student.id]);

    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-20">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            {user.role !== 'PARENT' && (
              <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border border-slate-100 rounded-2xl text-slate-600 font-bold hover:bg-slate-50 transition-all font-heading shadow-sm">
                <ArrowLeft size={18} /> กลับ
              </button>
            )}
            <div>
              <h2 className="text-3xl font-black text-slate-900 font-heading">ภาพรวมนักเรียน</h2>
              <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">{student.name}</p>
            </div>
          </div>
          <div className="flex items-center gap-3 bg-white p-2 pr-6 rounded-2xl border border-slate-100 shadow-sm">
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><User size={24} /></div>
            <div className="text-left">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ข้อมูลพื้นฐาน</p>
              <p className="text-sm font-bold text-slate-900 uppercase">{student.level} | {student.department}</p>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าแถว" value={`${attRate}%`} sub={`จากกิจกรรมหน้าเสาธง ${studentMorningAtt.length} ครั้ง`} icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore}`} sub={`สะสมในบล็อกเรียนปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="คะแนนคงเหลือล่าสุด" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm h-full">
            <h3 className="text-xl font-black text-slate-900 font-heading mb-6 flex items-center gap-3 uppercase tracking-widest">
              <Bell size={24} className="text-blue-600" /> แจ้งเตือนล่าสุด
            </h3>
            <div className="space-y-4">
              {studentNotifications.length > 0 ? studentNotifications.map(n => (
                <div key={n.id} className="p-5 bg-slate-50 rounded-[24px] border border-slate-100 flex gap-4 items-start relative overflow-hidden transition-all hover:scale-[1.02] hover:shadow-md cursor-default">
                  <div className={`w-1.5 h-full absolute left-0 top-0 ${n.type === 'ABSENT' ? 'bg-red-500' : 'bg-blue-500'}`} />
                  <div className="p-3 bg-white rounded-xl shadow-sm">
                    <Clock size={16} className="text-slate-400" />
                  </div>
                  <div>
                    <div className="flex justify-between items-center mb-1">
                      <p className="font-black text-slate-900 text-sm leading-tight">{n.title}</p>
                      {!n.isRead && <div className="w-2 h-2 bg-blue-600 rounded-full" />}
                    </div>
                    <p className="text-xs text-slate-600 font-bold leading-relaxed">{n.message}</p>
                    <p className="text-[9px] text-slate-400 mt-2 font-black uppercase">{n.timestamp} • {n.date}</p>
                  </div>
                </div>
              )) : (
                <div className="text-center py-20 text-slate-300">
                  <Bell size={48} className="mx-auto mb-4 opacity-10" />
                  <p className="text-xs font-black uppercase tracking-widest">ไม่มีแจ้งเตือนใหม่</p>
                </div>
              )}
            </div>
          </div>

          <div className="space-y-6">
            {finance.remaining > 0 ? (
              <div className="bg-gradient-to-br from-red-600 to-orange-600 p-8 md:p-10 rounded-[40px] text-white shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                  <p className="text-[10px] font-black text-red-100 uppercase tracking-[0.3em] mb-4 opacity-80">ยอดค้างชำระค่าเทอม</p>
                  <div className="flex items-baseline gap-3 mb-8">
                    <h2 className="text-6xl font-black font-heading tracking-tighter">{finance.remaining.toLocaleString()}</h2>
                    <span className="text-2xl font-bold opacity-80 uppercase font-heading">บาท</span>
                  </div>
                  <button 
                    onClick={() => setShowPaymentDetails(!showPaymentDetails)}
                    className="w-full px-10 py-5 bg-white text-red-600 rounded-[24px] font-black text-sm uppercase tracking-widest shadow-xl hover:bg-red-50 transition-all flex items-center justify-center gap-3 active:scale-95"
                  >
                    {showPaymentDetails ? <ChevronUp /> : <CreditCard />}
                    {showPaymentDetails ? 'ซ่อนรายละเอียด' : 'ดูช่องทางชำระเงิน'}
                  </button>
                </div>
              </div>
            ) : (
              <div className="bg-green-50 p-10 rounded-[40px] border border-green-200 flex flex-col items-center justify-center text-center gap-4 h-full">
                <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center text-green-600">
                  <CheckCircle2 size={40} />
                </div>
                <h3 className="text-2xl font-black text-green-900 font-heading">ชำระครบถ้วนแล้ว</h3>
                <p className="text-sm text-green-700 font-bold">ขอบคุณที่ชำระค่าธรรมเนียมการศึกษาตามกำหนด</p>
              </div>
            )}

            {showPaymentDetails && finance.remaining > 0 && (
              <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-xl animate-in slide-in-from-top-4 space-y-6">
                <div className="p-8 bg-[#00AEEF] rounded-[32px] text-white relative overflow-hidden shadow-lg">
                  <div className="absolute top-0 right-0 p-8 opacity-20 pointer-events-none transform translate-x-10 translate-y--10">
                     <Building2 size={180} />
                  </div>
                  <div className="relative z-10 space-y-6">
                    <div className="flex flex-wrap gap-x-12 gap-y-4">
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">ธนาคาร</p>
                        <p className="text-lg font-bold font-heading">{bankInfo.bankName}</p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">ชื่อบัญชี</p>
                        <p className="text-lg font-bold font-heading">{bankInfo.accountName}</p>
                      </div>
                    </div>
                    <div className="space-y-1">
                      <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">เลขที่บัญชี</p>
                      <div className="flex items-center gap-6">
                        <p className="text-4xl md:text-5xl font-black tracking-tighter text-white font-heading">{bankInfo.accountNo}</p>
                        <button 
                          onClick={() => handleCopy(bankInfo.accountNo)}
                          className={`flex items-center justify-center gap-2 px-5 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all shadow-xl ${copied ? 'bg-green-500 text-white' : 'bg-white text-[#00AEEF] hover:bg-sky-50'}`}
                        >
                          {copied ? <Check size={14} /> : <Copy size={14} />}
                          {copied ? 'คัดลอกแล้ว' : 'คัดลอก'}
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-center justify-between gap-6 bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
        <div className="flex items-center gap-5">
          <div className="p-4 bg-slate-900 rounded-[20px] text-white shadow-xl shadow-slate-100">
            <LayoutDashboard size={28} />
          </div>
          <div>
            <h2 className="text-2xl font-black text-slate-900 tracking-tight font-heading">แดชบอร์ดบริหารสถานศึกษา</h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Institutional Performance Metrics</p>
          </div>
        </div>

        <div className="flex gap-4 w-full lg:w-auto">
          <div className="flex-1 lg:w-48">
            <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3.5 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-400 transition-all">
              <option value="ALL">ทุกระดับชั้น</option>
              {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
            </select>
          </div>
          <div className="flex-1 lg:w-56">
            <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3.5 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-400 transition-all">
              <option value="ALL">ทุกแผนกวิชา</option>
              {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="จำนวนนักเรียน" value={filteredStudentsBase.length} sub="ในกลุ่มที่เลือก" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เข้าแถววันนี้" value={morningAttendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="กิจกรรมหน้าเสาธง" icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
        <StatCard title="มาสายวันนี้" value={morningAttendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'LATE' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="หลังเวลา 08:00 น." icon={<Clock size={28} />} color="bg-amber-500" textColor="text-amber-600" />
        <StatCard title="กลุ่มเฝ้าระวัง" value={behaviorWatchlist.length} sub="คะแนนพฤติกรรมต่ำ" icon={<ShieldAlert size={28} />} color="bg-red-600" textColor="text-red-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm min-h-[500px] flex flex-col">
          <div className="flex items-center justify-between mb-10">
            <div>
              <h3 className="text-xl font-black text-slate-900 font-heading flex items-center gap-3">
                 <BarChart3 className="text-[#00AEEF]" size={24} /> สถิติจำนวนคนเข้าแถวรายวัน
              </h3>
              <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">7 Days Morning Assembly Attendance</p>
            </div>
            <div className="flex items-center gap-2 bg-sky-50 px-4 py-2 rounded-full border border-sky-100">
               <div className="w-2.5 h-2.5 bg-[#00AEEF] rounded-full animate-pulse" />
               <span className="text-[10px] font-black text-[#00AEEF] uppercase tracking-widest">Live Report</span>
            </div>
          </div>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#94a3b8'}} />
                <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontFamily: 'Prompt' }} labelStyle={{ fontWeight: 900, color: '#0f172a', marginBottom: '4px' }} />
                <Bar dataKey="value" name="จำนวนคนมาแถว" radius={[8, 8, 0, 0]} barSize={40}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index === chartData.length - 1 ? '#00AEEF' : '#cbd5e1'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="flex flex-col gap-8">
          {/* พฤติกรรมเฝ้าระวัง */}
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm flex flex-col relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
              <AlertTriangle size={150} />
            </div>
            <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-6 font-heading flex items-center gap-2">
              <ShieldAlert size={20} className="text-red-600" /> กลุ่มเฝ้าระวังพฤติกรรม
            </h4>
            <div className="space-y-4 flex-1">
              {behaviorWatchlist.map(s => (
                <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="group flex items-center justify-between p-4 bg-red-50 hover:bg-red-100 rounded-2xl cursor-pointer transition-all border border-red-100/50">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-red-600 font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                    <div>
                      <p className="font-bold text-sm text-slate-900 truncate max-w-[140px] leading-tight">{s.name}</p>
                      <p className="text-[10px] text-slate-500 font-bold uppercase">{s.studentId}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="text-right mr-2">
                      <p className="text-[9px] font-black text-red-400 uppercase tracking-tighter">คะแนน</p>
                      <p className="font-black text-red-600 leading-tight">{s.behaviorScore}</p>
                    </div>
                    <ChevronRight size={18} className="text-red-300 group-hover:translate-x-1 transition-transform" />
                  </div>
                </div>
              ))}
              {behaviorWatchlist.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center py-10 text-slate-300">
                  <CheckCircle2 size={32} className="mb-2 opacity-10" />
                  <p className="text-xs font-black uppercase tracking-widest text-center">ไม่มีกลุ่มเฝ้าระวังพฤติกรรม</p>
                </div>
              )}
            </div>
          </div>

          {/* เข้าแถวเฝ้าระวัง */}
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm flex flex-col relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
              <Sun size={150} />
            </div>
            <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-6 font-heading flex items-center gap-2">
              <Clock size={20} className="text-[#00AEEF]" /> กลุ่มเฝ้าระวังคะแนนเข้าแถว
            </h4>
            <div className="space-y-4 flex-1">
              {attendanceWatchlist.map(s => {
                const score = getMorningScore(s.id);
                return (
                  <div key={s.id} onClick={() => setViewingStudentId(s.id)} className="group flex items-center justify-between p-4 bg-sky-50 hover:bg-sky-100 rounded-2xl cursor-pointer transition-all border border-sky-100/50">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-[#00AEEF] font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                      <div>
                        <p className="font-bold text-sm text-slate-900 truncate max-w-[140px] leading-tight">{s.name}</p>
                        <p className="text-[10px] text-slate-500 font-bold uppercase">{s.studentId}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <div className="text-right mr-2">
                        <p className="text-[9px] font-black text-sky-400 uppercase tracking-tighter">คะแนน</p>
                        <p className="font-black text-[#00AEEF] leading-tight">{score}</p>
                      </div>
                      <ChevronRight size={18} className="text-sky-300 group-hover:translate-x-1 transition-transform" />
                    </div>
                  </div>
                );
              })}
              {attendanceWatchlist.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center py-10 text-slate-300">
                  <CheckCircle2 size={32} className="mb-2 opacity-10" />
                  <p className="text-xs font-black uppercase tracking-widest text-center">ไม่มีกลุ่มเฝ้าระวังคะแนนเข้าแถว</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard, MessageCircle, ExternalLink, Bell,
  Banknote, ChevronDown, ChevronUp, CheckCircle2, Copy, Check, Sun, PieChart,
  LayoutDashboard
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Cell, Legend
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-full">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);
  const [copied, setCopied] = useState(false);
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  const [bankInfo, setBankInfo] = useState({
    bankName: 'ธนาคารกรุงไทย (Krungthai)',
    accountNo: '012-3-45678-9',
    accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
  });

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
    const savedBank = localStorage.getItem('cms_bank_info');
    if (savedBank) setBankInfo(JSON.parse(savedBank));
  }, []);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  const morningAttendance = useMemo(() => attendance.filter(a => a.type === 'MORNING'), [attendance]);

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = morningAttendance.filter(a => 
      a.studentId === studentId && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    return Number((( (presentDays) * 5) / 18).toFixed(2));
  };

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudentsBase
      .filter(s => getMorningScore(s.id) < 3.0)
      .sort((a,b) => getMorningScore(a.id) - getMorningScore(b.id))
      .slice(0, 6)
  , [filteredStudentsBase, morningAttendance, studyBlocks]);

  const chartData = useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const present = morningAttendance.filter(a => a.date === date && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length;
      return {
        name: new Date(date).toLocaleDateString('th-TH', { weekday: 'short' }),
        fullDate: date,
        value: present
      };
    });
  }, [morningAttendance, filteredStudentsBase]);

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, r) => sum + r.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  // View สำหรับผู้ปกครอง หรือเมื่อเลือกดูรายบุคคล
  if (user.role === 'PARENT' || viewingStudentId) {
    const targetId = viewingStudentId || user.studentId;
    // ค้นหาโดยเช็คทั้ง ID และ StudentID เพื่อความแม่นยำ ป้องกันหน้าขาว
    const student = students.find(s => s.id === targetId || s.studentId === targetId);

    if (!student) {
      return (
        <div className="p-20 text-center flex flex-col items-center justify-center space-y-4">
          <AlertTriangle size={64} className="text-amber-500" />
          <h2 className="text-2xl font-black text-slate-900 font-heading">ไม่พบข้อมูลนักเรียน</h2>
          <button 
            onClick={() => setViewingStudentId(null)} 
            className="px-8 py-3 bg-slate-900 text-white rounded-2xl font-bold hover:bg-black transition-all"
          >
            กลับสู่แดชบอร์ดหลัก
          </button>
        </div>
      );
    }

    const studentMorningAtt = morningAttendance.filter(a => a.studentId === student.id);
    const presentCount = studentMorningAtt.filter(a => a.status === 'PRESENT').length;
    const attRate = studentMorningAtt.length > 0 ? Math.round((presentCount / studentMorningAtt.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);

    const studentNotifications = useMemo(() => {
      return notifications
        .filter(n => n.studentId === student.id)
        .sort((a, b) => {
          const timeA = new Date(`${a.date} ${a.timestamp}`).getTime();
          const timeB = new Date(`${b.date} ${b.timestamp}`).getTime();
          return timeB - timeA;
        })
        .slice(0, 5);
    }, [notifications, student.id]);

    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-20">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            {user.role !== 'PARENT' && (
              <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border border-slate-100 rounded-2xl text-slate-600 font-bold hover:bg-slate-50 transition-all font-heading shadow-sm">
                <ArrowLeft size={18} /> กลับ
              </button>
            )}
            <div>
              <h2 className="text-3xl font-black text-slate-900 font-heading">ภาพรวมนักเรียน</h2>
              <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">{student.name}</p>
            </div>
          </div>
          <div className="flex items-center gap-3 bg-white p-2 pr-6 rounded-2xl border border-slate-100 shadow-sm">
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><User size={24} /></div>
            <div className="text-left">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ชั้นเรียน</p>
              <p className="text-sm font-bold text-slate-900 uppercase">{student.level} | {student.department}</p>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าแถว" value={`${attRate}%`} sub={`จากกิจกรรมหน้าเสาธง ${studentMorningAtt.length} ครั้ง`} icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore}`} sub={`สะสมในบล็อกเรียนปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="คะแนนคงเหลือล่าสุด" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm h-full">
            <h3 className="text-xl font-black text-slate-900 font-heading mb-6 flex items-center gap-3 uppercase tracking-widest">
              <Bell size={24} className="text-blue-600" /> แจ้งเตือนล่าสุด
            </h3>
            <div className="space-y-4">
              {studentNotifications.length > 0 ? studentNotifications.map(n => (
                <div key={n.id} className="p-5 bg-slate-50 rounded-[24px] border border-slate-100 flex gap-4 items-start relative overflow-hidden transition-all hover:scale-[1.02] hover:shadow-md cursor-default">
                  <div className={`w-1.5 h-full absolute left-0 top-0 ${n.type === 'ABSENT' ? 'bg-red-500' : 'bg-blue-500'}`} />
                  <div className="p-3 bg-white rounded-xl shadow-sm">
                    <Clock size={16} className="text-slate-400" />
                  </div>
                  <div>
                    <div className="flex justify-between items-center mb-1">
                      <p className="font-black text-slate-900 text-sm leading-tight">{n.title}</p>
