        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);
  const [copied, setCopied] = useState(false);
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  const [bankInfo, setBankInfo] = useState({
    bankName: 'ธนาคารกรุงไทย (Krungthai)',
    accountNo: '012-3-45678-9',
    accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
  });

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
    const savedBank = localStorage.getItem('cms_bank_info');
    if (savedBank) setBankInfo(JSON.parse(savedBank));
  }, []);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  const morningAttendance = useMemo(() => attendance.filter(a => a.type === 'MORNING'), [attendance]);

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = morningAttendance.filter(a => 
      a.studentId === studentId && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    return Number((( (presentDays) * 5) / 18).toFixed(2));
  };

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudentsBase
      .filter(s => getMorningScore(s.id) < 3.0)
      .sort((a,b) => getMorningScore(a.id) - getMorningScore(b.id))
      .slice(0, 6)
  , [filteredStudentsBase, morningAttendance, studyBlocks]);

  const chartData = useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const present = morningAttendance.filter(a => a.date === date && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length;
      return {
        name: new Date(date).toLocaleDateString('th-TH', { weekday: 'short' }),
        fullDate: date,
        value: present
      };
    });
  }, [morningAttendance, filteredStudentsBase]);

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, r) => sum + r.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  // View สำหรับผู้ปกครอง หรือเมื่อเลือกดูรายบุคคล
  if (user.role === 'PARENT' || viewingStudentId) {
    const targetId = viewingStudentId || user.studentId;
    // ค้นหาโดยเช็คทั้ง ID และ StudentID เพื่อความแม่นยำ ป้องกันหน้าขาว
    // Priority 1: Check internal id (e.g. '1')
    // Priority 2: Check institutional studentId (e.g. '661001')
    const student = students.find(s => s.id === targetId) || students.find(s => s.studentId === targetId);

    if (!student) {
      return (
        <div className="p-20 text-center flex flex-col items-center justify-center space-y-4">
          <AlertTriangle size={64} className="text-amber-500 animate-bounce" />
          <h2 className="text-2xl font-black text-slate-900 font-heading">ไม่พบข้อมูลนักเรียน</h2>
          <p className="text-slate-500">รหัส {targetId} ไม่ตรงกับฐานข้อมูลปัจจุบัน</p>
          <button 
            onClick={() => setViewingStudentId(null)} 
            className="px-8 py-3 bg-slate-900 text-white rounded-2xl font-bold hover:bg-black transition-all mt-4"
          >
            กลับสู่แดชบอร์ดหลัก
          </button>
        </div>
      );
    }

    const studentMorningAtt = morningAttendance.filter(a => a.studentId === student.id);
    const presentCount = studentMorningAtt.filter(a => a.status === 'PRESENT').length;
    const attRate = studentMorningAtt.length > 0 ? Math.round((presentCount / studentMorningAtt.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);

    const studentNotifications = notifications
      .filter(n => n.studentId === student.id)
      .sort((a, b) => {
        const timeA = new Date(`${a.date} ${a.timestamp}`).getTime();
        const timeB = new Date(`${b.date} ${b.timestamp}`).getTime();
        return timeB - timeA;
      })
      .slice(0, 5);

    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-20">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            {user.role !== 'PARENT' && (
              <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border border-slate-100 rounded-2xl text-slate-600 font-bold hover:bg-slate-50 transition-all font-heading shadow-sm">
                <ArrowLeft size={18} /> กลับ
              </button>
            )}
            <div>
              <h2 className="text-3xl font-black text-slate-900 font-heading">ภาพรวมนักเรียน</h2>
              <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">{student.name}</p>
            </div>
          </div>
          <div className="flex items-center gap-3 bg-white p-2 pr-6 rounded-2xl border border-slate-100 shadow-sm">
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><User size={24} /></div>
            <div className="text-left">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ชั้นเรียน</p>
              <p className="text-sm font-bold text-slate-900 uppercase">{student.level} | {student.department}</p>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าแถว" value={`${attRate}%`} sub={`จากกิจกรรมหน้าเสาธง ${studentMorningAtt.length} ครั้ง`} icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore}`} sub={`สะสมในบล็อกเรียนปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="คะแนนคงเหลือล่าสุด" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm h-full">
            <h3 className="text-xl font-black text-slate-900 font-heading mb-6 flex items-center gap-3 uppercase tracking-widest">
              <Bell size={24} className="text-blue-600" /> แจ้งเตือนล่าสุด
            </h3>
            <div className="space-y-4">
              {studentNotifications.length > 0 ? studentNotifications.map(n => (
                <div key={n.id} className="p-5 bg-slate-50 rounded-[24px] border border-slate-100 flex gap-4 items-start relative overflow-hidden transition-all hover:scale-[1.02] hover:shadow-md cursor-default">
                  <div className={`w-1.5 h-full absolute left-0 top-0 ${n.type === 'ABSENT' ? 'bg-red-500' : 'bg-blue-500'}`} />
                  <div className="p-3 bg-white rounded-xl shadow-sm">
                    <Clock size={16} className="text-slate-400" />
                  </div>
                  <div>
                    <div className="flex justify-between items-center mb-1">
                      <p className="font-black text-slate-900 text-sm leading-tight">{n.title}</p>
                      {!n.isRead && <div className="w-2 h-2 bg-blue-600 rounded-full" />}
                    </div>
                    <p className="text-xs text-slate-600 font-bold leading-relaxed">{n.message}</p>
                    <p className="text-[9px] text-slate-400 mt-2 font-black uppercase">{n.timestamp} • {n.date}</p>
                  </div>
                </div>
              )) : (
                <div className="text-center py-20 text-slate-300">
                  <Bell size={48} className="mx-auto mb-4 opacity-10" />
                  <p className="text-xs font-black uppercase tracking-widest">ไม่มีแจ้งเตือนใหม่</p>
                </div>
              )}
            </div>
          </div>

          <div className="space-y-6">
            {finance.remaining > 0 ? (
              <div className="bg-gradient-to-br from-red-600 to-orange-600 p-8 md:p-10 rounded-[40px] text-white shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                  <p className="text-[10px] font-black text-red-100 uppercase tracking-[0.3em] mb-4 opacity-80">ยอดค้างชำระค่าเทอม</p>
                  <div className="flex items-baseline gap-3 mb-8">
                    <h2 className="text-6xl font-black font-heading tracking-tighter">{finance.remaining.toLocaleString()}</h2>
                    <span className="text-2xl font-bold opacity-80 uppercase font-heading">บาท</span>
                  </div>
                  <button 
                    onClick={() => setShowPaymentDetails(!showPaymentDetails)}
                    className="w-full px-10 py-5 bg-white text-red-600 rounded-[24px] font-black text-sm uppercase tracking-widest shadow-xl hover:bg-red-50 transition-all flex items-center justify-center gap-3 active:scale-95"
                  >
                    {showPaymentDetails ? <ChevronUp /> : <CreditCard />}
                    {showPaymentDetails ? 'ซ่อนรายละเอียด' : 'ดูช่องทางชำระเงิน'}
                  </button>
                </div>
              </div>
            ) : (
              <div className="bg-green-50 p-10 rounded-[40px] border border-green-200 flex flex-col items-center justify-center text-center gap-4 h-full">
                <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center text-green-600">
                  <CheckCircle2 size={40} />
                </div>
                <h3 className="text-2xl font-black text-green-900 font-heading">ชำระครบถ้วนแล้ว</h3>
                <p className="text-sm text-green-700 font-bold">ขอบคุณที่ชำระค่าธรรมเนียมการศึกษาตามกำหนด</p>
              </div>
            )}

            {showPaymentDetails && finance.remaining > 0 && (
              <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-xl animate-in slide-in-from-top-4 space-y-6">
                <div className="p-8 bg-[#00AEEF] rounded-[32px] text-white relative overflow-hidden shadow-lg">
                  <div className="absolute top-0 right-0 p-8 opacity-20 pointer-events-none transform translate-x-10 translate-y--10">
                     <Building2 size={180} />
                  </div>
                  <div className="relative z-10 space-y-6">
                    <div className="flex flex-wrap gap-x-12 gap-y-4">
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">ธนาคาร</p>
                        <p className="text-lg font-bold font-heading">{bankInfo.bankName}</p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">ชื่อบัญชี</p>
                        <p className="text-lg font-bold font-heading">{bankInfo.accountName}</p>
                      </div>
                    </div>
                    <div className="space-y-1">
                      <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">เลขที่บัญชี</p>
                      <div className="flex items-center gap-6">
                        <p className="text-4xl md:text-5xl font-black tracking-tighter text-white font-heading">{bankInfo.accountNo}</p>
                        <button 
                          onClick={() => handleCopy(bankInfo.accountNo)}
                          className={`flex items-center justify-center gap-2 px-5 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all shadow-xl ${copied ? 'bg-green-500 text-white' : 'bg-white text-[#00AEEF] hover:bg-sky-50'}`}
                        >
                          {copied ? <Check size={14} /> : <Copy size={14} />}
                          {copied ? 'คัดลอกแล้ว' : 'คัดลอก'}
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-center justify-between gap-6 bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
        <div className="flex items-center gap-5">
          <div className="p-4 bg-slate-900 rounded-[20px] text-white shadow-xl shadow-slate-100">
            <LayoutDashboard size={28} />
          </div>
          <div>
            <h2 className="text-2xl font-black text-slate-900 tracking-tight font-heading">แดชบอร์ดบริหารสถานศึกษา</h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">สรุปภาพรวมข้อมูลอาชีวศึกษา</p>
          </div>
        </div>

        <div className="flex gap-4 w-full lg:w-auto">
          <div className="flex-1 lg:w-48">
            <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3.5 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-400 transition-all">
              <option value="ALL">ทุกระดับชั้น</option>
              {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
            </select>
          </div>
          <div className="flex-1 lg:w-56">
            <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3.5 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-400 transition-all">
              <option value="ALL">ทุกแผนกวิชา</option>
              {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="จำนวนนักเรียน" value={filteredStudentsBase.length} sub="ในกลุ่มที่เลือก" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เข้าแถววันนี้" value={morningAttendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="กิจกรรมหน้าเสาธง" icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
        <StatCard title="มาสายวันนี้" value={morningAttendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'LATE' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="หลังเวลา 08:00 น." icon={<Clock size={28} />} color="bg-amber-500" textColor="text-amber-600" />
        <StatCard title="กลุ่มเฝ้าระวัง" value={behaviorWatchlist.length} sub="คะแนนพฤติกรรมต่ำ" icon={<ShieldAlert size={28} />} color="bg-red-600" textColor="text-red-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm min-h-[500px] flex flex-col">
          <div className="flex items-center justify-between mb-10">
            <div>
              <h3 className="text-xl font-black text-slate-900 font-heading flex items-center gap-3">
                 <BarChart3 className="text-[#00AEEF]" size={24} /> สถิติจำนวนคนเข้าแถวรายวัน
              </h3>
              <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">การเข้าแถวหน้าเสาธง 7 วันย้อนหลัง</p>
            </div>
            <div className="flex items-center gap-2 bg-sky-50 px-4 py-2 rounded-full border border-sky-100">
               <div className="w-2.5 h-2.5 bg-[#00AEEF] rounded-full animate-pulse" />
               <span className="text-[10px] font-black text-[#00AEEF] uppercase tracking-widest">Live Report</span>
            </div>
          </div>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#94a3b8'}} />
                <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontFamily: 'Prompt' }} labelStyle={{ fontWeight: 900, color: '#0f172a', marginBottom: '4px' }} />
                <Bar dataKey="value" name="จำนวนคนมาแถว" radius={[8, 8, 0, 0]} barSize={40}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index === chartData.length - 1 ? '#00AEEF' : '#cbd5e1'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="flex flex-col gap-6">
          {/* พฤติกรรมเฝ้าระวัง */}
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm flex flex-col relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
              <ShieldAlert size={150} />
            </div>
            <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-6 font-heading flex items-center gap-2">
              <ShieldAlert size={20} className="text-red-600" /> กลุ่มเฝ้าระวังพฤติกรรม
            </h4>
            <div className="space-y-4 flex-1">
              {behaviorWatchlist.map(s => (
                <button 
                  key={s.id} 
                  onClick={() => setViewingStudentId(s.id)} 
                  className="w-full group flex items-center justify-between p-4 bg-red-50 hover:bg-red-100 rounded-2xl cursor-pointer transition-all border border-red-100/50"
                >
                  <div className="flex items-center gap-4 text-left">
                    <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-red-600 font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                    <div className="min-w-0">
                      <p className="font-bold text-sm text-slate-900 truncate leading-tight">{s.name}</p>
                      <p className="text-[10px] text-slate-500 font-bold uppercase">{s.studentId}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="text-right mr-2">
                      <p className="text-[9px] font-black text-red-400 uppercase tracking-tighter">คะแนน</p>
                      <p className="font-black text-red-600 leading-tight">{s.behaviorScore}</p>
                    </div>
                    <ChevronRight size={18} className="text-red-300 group-hover:translate-x-1 transition-transform" />
                  </div>
                </button>
              ))}
              {behaviorWatchlist.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center py-10 text-slate-300">
                  <CheckCircle2 size={32} className="mb-2 opacity-10" />
                  <p className="text-xs font-black uppercase tracking-widest text-center">ไม่มีกลุ่มเฝ้าระวังพฤติกรรม</p>
                </div>
              )}
            </div>
          </div>

          {/* เข้าแถวเฝ้าระวัง */}
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm flex flex-col relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
              <Sun size={150} />
            </div>
            <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-6 font-heading flex items-center gap-2">
              <Clock size={20} className="text-[#00AEEF]" /> กลุ่มเฝ้าระวังคะแนนเข้าแถว
            </h4>
            <div className="space-y-4 flex-1">
              {attendanceWatchlist.map(s => {
                const score = getMorningScore(s.id);
                return (
                  <button 
                    key={s.id} 
                    onClick={() => setViewingStudentId(s.id)} 
                    className="w-full group flex items-center justify-between p-4 bg-sky-50 hover:bg-sky-100 rounded-2xl cursor-pointer transition-all border border-sky-100/50"
                  >
                    <div className="flex items-center gap-4 text-left">
                      <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-[#00AEEF] font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                      <div className="min-w-0">
                        <p className="font-bold text-sm text-slate-900 truncate leading-tight">{s.name}</p>
                        <p className="text-[10px] text-slate-500 font-bold uppercase">{s.studentId}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <div className="text-right mr-2">
                        <p className="text-[9px] font-black text-sky-400 uppercase tracking-tighter">คะแนน</p>
                        <p className="font-black text-[#00AEEF] leading-tight">{score}</p>
                      </div>
                      <ChevronRight size={18} className="text-sky-300 group-hover:translate-x-1 transition-transform" />
                    </div>
                  </button>
                );
              })}
              {attendanceWatchlist.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center py-10 text-slate-300">
                  <CheckCircle2 size={32} className="mb-2 opacity-10" />
                  <p className="text-xs font-black uppercase tracking-widest text-center">ไม่มีกลุ่มเฝ้าระวังคะแนนเข้าแถว</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard, MessageCircle, ExternalLink, Bell,
  Banknote, ChevronDown, ChevronUp, CheckCircle2, Copy, Check, Sun, PieChart,
  LayoutDashboard
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Cell, Legend
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-full">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);
  const [copied, setCopied] = useState(false);
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  const [bankInfo, setBankInfo] = useState({
    bankName: 'ธนาคารกรุงไทย (Krungthai)',
    accountNo: '012-3-45678-9',
    accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
  });

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
    const savedBank = localStorage.getItem('cms_bank_info');
    if (savedBank) setBankInfo(JSON.parse(savedBank));
  }, []);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  const morningAttendance = useMemo(() => attendance.filter(a => a.type === 'MORNING'), [attendance]);

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = morningAttendance.filter(a => 
      a.studentId === studentId && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    return Number((( (presentDays) * 5) / 18).toFixed(2));
  };

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudentsBase
      .filter(s => getMorningScore(s.id) < 3.0)
      .sort((a,b) => getMorningScore(a.id) - getMorningScore(b.id))
      .slice(0, 6)
  , [filteredStudentsBase, morningAttendance, studyBlocks]);

  const chartData = useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const present = morningAttendance.filter(a => a.date === date && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length;
      return {
        name: new Date(date).toLocaleDateString('th-TH', { weekday: 'short' }),
        fullDate: date,
        value: present
      };
    });
  }, [morningAttendance, filteredStudentsBase]);

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, p) => sum + p.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  // Student Detail View
  if (user.role === 'PARENT' || viewingStudentId) {
    const targetId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === targetId) || students.find(s => s.studentId === targetId);

    if (!student) {
      return (
        <div className="p-20 text-center flex flex-col items-center justify-center space-y-4">
          <AlertTriangle size={64} className="text-amber-500 animate-bounce" />
          <h2 className="text-2xl font-black text-slate-900 font-heading uppercase tracking-tighter">ไม่พบข้อมูลนักเรียน</h2>
          <p className="text-slate-400 font-bold">ไม่พบข้อมูลสำหรับรหัส: {targetId}</p>
          <button 
            onClick={() => setViewingStudentId(null)} 
            className="mt-6 px-10 py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-black transition-all shadow-xl"
          >
            กลับสู่หน้าหลัก
          </button>
        </div>
      );
    }

    const studentMorningAtt = morningAttendance.filter(a => a.studentId === student.id);
    const presentCount = studentMorningAtt.filter(a => a.status === 'PRESENT').length;
    const attRate = studentMorningAtt.length > 0 ? Math.round((presentCount / studentMorningAtt.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);

    const studentNotifications = notifications
      .filter(n => n.studentId === student.id)
      .sort((a, b) => {
        const timeA = new Date(`${a.date} ${a.timestamp}`).getTime();
        const timeB = new Date(`${b.date} ${b.timestamp}`).getTime();
        return timeB - timeA;
      })
      .slice(0, 5);

    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-20">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            {user.role !== 'PARENT' && (
              <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border border-slate-100 rounded-2xl text-slate-600 font-bold hover:bg-slate-50 transition-all font-heading shadow-sm">
                <ArrowLeft size={18} /> กลับ
              </button>
            )}
            <div>
              <h2 className="text-3xl font-black text-slate-900 font-heading">ภาพรวมนักเรียน</h2>
              <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">{student.name}</p>
            </div>
          </div>
          <div className="flex items-center gap-3 bg-white p-2 pr-6 rounded-2xl border border-slate-100 shadow-sm">
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><User size={24} /></div>
            <div className="text-left">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ชั้นเรียน</p>
              <p className="text-sm font-bold text-slate-900 uppercase">{student.level} | {student.department}</p>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าแถว" value={`${attRate}%`} sub={`จากกิจกรรมหน้าเสาธง ${studentMorningAtt.length} ครั้ง`} icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore}`} sub={`สะสมในบล็อกเรียนปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="คะแนนคงเหลือล่าสุด" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm h-full">
            <h3 className="text-xl font-black text-slate-900 font-heading mb-6 flex items-center gap-3 uppercase tracking-widest">
              <Bell size={24} className="text-blue-600" /> แจ้งเตือนล่าสุด
            </h3>
            <div className="space-y-4">
              {studentNotifications.length > 0 ? studentNotifications.map(n => (
                <div key={n.id} className="p-5 bg-slate-50 rounded-[24px] border border-slate-100 flex gap-4 items-start relative overflow-hidden transition-all hover:scale-[1.02] hover:shadow-md cursor-default">
                  <div className={`w-1.5 h-full absolute left-0 top-0 ${n.type === 'ABSENT' ? 'bg-red-500' : 'bg-blue-500'}`} />
                  <div className="p-3 bg-white rounded-xl shadow-sm">
                    <Clock size={16} className="text-slate-400" />
                  </div>
                  <div>
                    <div className="flex justify-between items-center mb-1">
                      <p className="font-black text-slate-900 text-sm leading-tight">{n.title}</p>
                      {!n.isRead && <div className="w-2 h-2 bg-blue-600 rounded-full" />}
                    </div>
                    <p className="text-xs text-slate-600 font-bold leading-relaxed">{n.message}</p>
                    <p className="text-[9px] text-slate-400 mt-2 font-black uppercase">{n.timestamp} • {n.date}</p>
                  </div>
                </div>
              )) : (
                <div className="text-center py-20 text-slate-300">
                  <Bell size={48} className="mx-auto mb-4 opacity-10" />
                  <p className="text-xs font-black uppercase tracking-widest">ไม่มีแจ้งเตือนใหม่</p>
                </div>
              )}
            </div>
          </div>

          <div className="space-y-6">
            {finance.remaining > 0 ? (
              <div className="bg-gradient-to-br from-red-600 to-orange-600 p-8 md:p-10 rounded-[40px] text-white shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                  <p className="text-[10px] font-black text-red-100 uppercase tracking-[0.3em] mb-4 opacity-80">ยอดค้างชำระค่าเทอม</p>
                  <div className="flex items-baseline gap-3 mb-8">
                    <h2 className="text-6xl font-black font-heading tracking-tighter">{finance.remaining.toLocaleString()}</h2>
                    <span className="text-2xl font-bold opacity-80 uppercase font-heading">บาท</span>
                  </div>
                  <button 
                    onClick={() => setShowPaymentDetails(!showPaymentDetails)}
                    className="w-full px-10 py-5 bg-white text-red-600 rounded-[24px] font-black text-sm uppercase tracking-widest shadow-xl hover:bg-red-50 transition-all flex items-center justify-center gap-3 active:scale-95"
                  >
                    {showPaymentDetails ? <ChevronUp /> : <CreditCard />}
                    {showPaymentDetails ? 'ซ่อนรายละเอียด' : 'ดูช่องทางชำระเงิน'}
                  </button>
                </div>
              </div>
            ) : (
              <div className="bg-green-50 p-10 rounded-[40px] border border-green-200 flex flex-col items-center justify-center text-center gap-4 h-full">
                <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center text-green-600">
                  <CheckCircle2 size={40} />
                </div>
                <h3 className="text-2xl font-black text-green-900 font-heading">ชำระครบถ้วนแล้ว</h3>
                <p className="text-sm text-green-700 font-bold">ขอบคุณที่ชำระค่าธรรมเนียมการศึกษาตามกำหนด</p>
              </div>
            )}

            {showPaymentDetails && finance.remaining > 0 && (
              <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-xl animate-in slide-in-from-top-4 space-y-6">
                <div className="p-8 bg-[#00AEEF] rounded-[32px] text-white relative overflow-hidden shadow-lg">
                  <div className="absolute top-0 right-0 p-8 opacity-20 pointer-events-none transform translate-x-10 translate-y--10">
                     <Building2 size={180} />
                  </div>
                  <div className="relative z-10 space-y-6">
                    <div className="flex flex-wrap gap-x-12 gap-y-4">
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">ธนาคาร</p>
                        <p className="text-lg font-bold font-heading">{bankInfo.bankName}</p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">ชื่อบัญชี</p>
                        <p className="text-lg font-bold font-heading">{bankInfo.accountName}</p>
                      </div>
                    </div>
                    <div className="space-y-1">
                      <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">เลขที่บัญชี</p>
                      <div className="flex items-center gap-6">
                        <p className="text-4xl md:text-5xl font-black tracking-tighter text-white font-heading">{bankInfo.accountNo}</p>
                        <button 
                          onClick={() => handleCopy(bankInfo.accountNo)}
                          className={`flex items-center justify-center gap-2 px-5 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all shadow-xl ${copied ? 'bg-green-500 text-white' : 'bg-white text-[#00AEEF] hover:bg-sky-50'}`}
                        >
                          {copied ? <Check size={14} /> : <Copy size={14} />}
                          {copied ? 'คัดลอกแล้ว' : 'คัดลอก'}
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  // Admin/Teacher Dashboard
  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-center justify-between gap-6 bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
        <div className="flex items-center gap-5">
          <div className="p-4 bg-slate-900 rounded-[20px] text-white shadow-xl shadow-slate-100">
            <LayoutDashboard size={28} />
          </div>
          <div>
            <h2 className="text-2xl font-black text-slate-900 tracking-tight font-heading">แดชบอร์ดบริหารสถานศึกษา</h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">สรุปภาพรวมข้อมูลอาชีวศึกษา</p>
          </div>
        </div>

        <div className="flex gap-4 w-full lg:w-auto">
          <div className="flex-1 lg:w-48">
            <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3.5 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-400 transition-all">
              <option value="ALL">ทุกระดับชั้น</option>
              {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
            </select>
          </div>
          <div className="flex-1 lg:w-56">
            <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3.5 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-400 transition-all">
              <option value="ALL">ทุกแผนกวิชา</option>
              {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="จำนวนนักเรียน" value={filteredStudentsBase.length} sub="ในกลุ่มที่เลือก" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เฝ้าระวังพฤติกรรม" value={behaviorWatchlist.length} sub="คะแนนพฤติกรรมต่ำกว่า 70" icon={<ShieldAlert size={28} />} color="bg-red-600" textColor="text-red-600" />
        <StatCard title="เฝ้าระวังเข้าแถว" value={attendanceWatchlist.length} sub="คะแนนเข้าแถวต่ำกว่า 3.0" icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
        <StatCard title="มาสายวันนี้" value={morningAttendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'LATE' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="หลังเวลา 08:00 น." icon={<Clock size={28} />} color="bg-amber-500" textColor="text-amber-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm min-h-[500px] flex flex-col">
          <div className="flex items-center justify-between mb-10">
            <div>
              <h3 className="text-xl font-black text-slate-900 font-heading flex items-center gap-3">
                 <BarChart3 className="text-[#00AEEF]" size={24} /> สถิติจำนวนคนเข้าแถวรายวัน
              </h3>
              <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">การเข้าแถวหน้าเสาธง 7 วันย้อนหลัง</p>
            </div>
            <div className="flex items-center gap-2 bg-sky-50 px-4 py-2 rounded-full border border-sky-100">
               <div className="w-2.5 h-2.5 bg-[#00AEEF] rounded-full animate-pulse" />
               <span className="text-[10px] font-black text-[#00AEEF] uppercase tracking-widest">Live Report</span>
            </div>
          </div>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#94a3b8'}} />
                <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontFamily: 'Prompt' }} labelStyle={{ fontWeight: 900, color: '#0f172a', marginBottom: '4px' }} />
                <Bar dataKey="value" name="จำนวนคนมาแถว" radius={[8, 8, 0, 0]} barSize={40}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index === chartData.length - 1 ? '#00AEEF' : '#cbd5e1'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="flex flex-col gap-6">
          {/* พฤติกรรมเฝ้าระวัง */}
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm flex flex-col relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
              <ShieldAlert size={150} />
            </div>
            <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-6 font-heading flex items-center gap-2">
              <ShieldAlert size={20} className="text-red-600" /> กลุ่มเฝ้าระวังพฤติกรรม
            </h4>
            <div className="space-y-4 flex-1">
              {behaviorWatchlist.map(s => (
                <button 
                  key={s.id} 
                  onClick={() => setViewingStudentId(s.id)} 
                  className="w-full group flex items-center justify-between p-4 bg-red-50 hover:bg-red-100 rounded-2xl cursor-pointer transition-all border border-red-100/50"
                >
                  <div className="flex items-center gap-4 text-left">
                    <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-red-600 font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                    <div className="min-w-0">
                      <p className="font-bold text-sm text-slate-900 truncate leading-tight">{s.name}</p>
                      <p className="text-[10px] text-slate-500 font-bold uppercase">{s.studentId}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="text-right mr-2">
                      <p className="text-[9px] font-black text-red-400 uppercase tracking-tighter">คะแนน</p>
                      <p className="font-black text-red-600 leading-tight">{s.behaviorScore}</p>
                    </div>
                    <ChevronRight size={18} className="text-red-300 group-hover:translate-x-1 transition-transform" />
                  </div>
                </button>
              ))}
              {behaviorWatchlist.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center py-10 text-slate-300">
                  <CheckCircle2 size={32} className="mb-2 opacity-10" />
                  <p className="text-xs font-black uppercase tracking-widest text-center">ไม่มีกลุ่มเฝ้าระวังพฤติกรรม</p>
                </div>
              )}
            </div>
          </div>

          {/* เข้าแถวเฝ้าระวัง */}
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm flex flex-col relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
              <Sun size={150} />
            </div>
            <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-6 font-heading flex items-center gap-2">
              <Clock size={20} className="text-[#00AEEF]" /> กลุ่มเฝ้าระวังคะแนนเข้าแถว
            </h4>
            <div className="space-y-4 flex-1">
              {attendanceWatchlist.map(s => {
                const score = getMorningScore(s.id);
                return (
                  <button 
                    key={s.id} 
                    onClick={() => setViewingStudentId(s.id)} 
                    className="w-full group flex items-center justify-between p-4 bg-sky-50 hover:bg-sky-100 rounded-2xl cursor-pointer transition-all border border-sky-100/50"
                  >
                    <div className="flex items-center gap-4 text-left">
                      <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-[#00AEEF] font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                      <div className="min-w-0">
                        <p className="font-bold text-sm text-slate-900 truncate leading-tight">{s.name}</p>
                        <p className="text-[10px] text-slate-500 font-bold uppercase">{s.studentId}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <div className="text-right mr-2">
                        <p className="text-[9px] font-black text-sky-400 uppercase tracking-tighter">คะแนน</p>
                        <p className="font-black text-[#00AEEF] leading-tight">{score}</p>
                      </div>
                      <ChevronRight size={18} className="text-sky-300 group-hover:translate-x-1 transition-transform" />
                    </div>
                  </button>
                );
              })}
              {attendanceWatchlist.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center py-10 text-slate-300">
                  <CheckCircle2 size={32} className="mb-2 opacity-10" />
                  <p className="text-xs font-black uppercase tracking-widest text-center">ไม่มีกลุ่มเฝ้าระวังคะแนนเข้าแถว</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, CheckCircle, AlertTriangle, TrendingUp, Award, Search, ArrowLeft, 
  User, Activity, Star, Wallet, Clock, BarChart3, Filter, ShieldAlert,
  ChevronRight, Building2, GraduationCap, CreditCard, MessageCircle, ExternalLink, Bell,
  Banknote, ChevronDown, ChevronUp, CheckCircle2, Copy, Check, Sun, PieChart,
  LayoutDashboard
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar, Cell, Legend
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-7 rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-full">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-2">
        <p className="text-slate-500 text-[10px] font-extrabold uppercase tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-xs text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-4 rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {icon}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);
  const [copied, setCopied] = useState(false);
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  const [bankInfo, setBankInfo] = useState({
    bankName: 'ธนาคารกรุงไทย (Krungthai)',
    accountNo: '012-3-45678-9',
    accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
  });

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
    const savedBank = localStorage.getItem('cms_bank_info');
    if (savedBank) setBankInfo(JSON.parse(savedBank));
  }, []);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  const morningAttendance = useMemo(() => attendance.filter(a => a.type === 'MORNING'), [attendance]);

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = morningAttendance.filter(a => 
      a.studentId === studentId && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    return Number((( (presentDays) * 5) / 18).toFixed(2));
  };

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudentsBase
      .filter(s => getMorningScore(s.id) < 3.0)
      .sort((a,b) => getMorningScore(a.id) - getMorningScore(b.id))
      .slice(0, 6)
  , [filteredStudentsBase, morningAttendance, studyBlocks]);

  const chartData = useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const present = morningAttendance.filter(a => a.date === date && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length;
      return {
        name: new Date(date).toLocaleDateString('th-TH', { weekday: 'short' }),
        fullDate: date,
        value: present
      };
    });
  }, [morningAttendance, filteredStudentsBase]);

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, p) => sum + p.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  // Student Detail View
  if (user.role === 'PARENT' || viewingStudentId) {
    const targetId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === targetId) || students.find(s => s.studentId === targetId);

    if (!student) {
      return (
        <div className="p-20 text-center flex flex-col items-center justify-center space-y-4">
          <AlertTriangle size={64} className="text-amber-500 animate-bounce" />
          <h2 className="text-2xl font-black text-slate-900 font-heading uppercase tracking-tighter">ไม่พบข้อมูลนักเรียน</h2>
          <p className="text-slate-400 font-bold">ไม่พบข้อมูลสำหรับรหัส: {targetId}</p>
          <button 
            onClick={() => setViewingStudentId(null)} 
            className="mt-6 px-10 py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-black transition-all shadow-xl"
          >
            กลับสู่หน้าหลัก
          </button>
        </div>
      );
    }

    const studentMorningAtt = morningAttendance.filter(a => a.studentId === student.id);
    const presentCount = studentMorningAtt.filter(a => a.status === 'PRESENT').length;
    const attRate = studentMorningAtt.length > 0 ? Math.round((presentCount / studentMorningAtt.length) * 100) : 0;
    const blockScore = getMorningScore(student.id);
    const finance = getFinancialStatus(student);

    const studentNotifications = notifications
      .filter(n => n.studentId === student.id)
      .sort((a, b) => {
        const timeA = new Date(`${a.date} ${a.timestamp}`).getTime();
        const timeB = new Date(`${b.date} ${b.timestamp}`).getTime();
        return timeB - timeA;
      })
      .slice(0, 5);

    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-20">
        <div className="flex flex-col md:flex-row items-center justify-between gap-4">
          <div className="flex items-center gap-4">
            {user.role !== 'PARENT' && (
              <button onClick={() => setViewingStudentId(null)} className="flex items-center gap-3 px-6 py-3 bg-white border border-slate-100 rounded-2xl text-slate-600 font-bold hover:bg-slate-50 transition-all font-heading shadow-sm">
                <ArrowLeft size={18} /> กลับ
              </button>
            )}
            <div>
              <h2 className="text-3xl font-black text-slate-900 font-heading">ภาพรวมนักเรียน</h2>
              <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">{student.name}</p>
            </div>
          </div>
          <div className="flex items-center gap-3 bg-white p-2 pr-6 rounded-2xl border border-slate-100 shadow-sm">
            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><User size={24} /></div>
            <div className="text-left">
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ชั้นเรียน</p>
              <p className="text-sm font-bold text-slate-900 uppercase">{student.level} | {student.department}</p>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าแถว" value={`${attRate}%`} sub={`จากกิจกรรมหน้าเสาธง ${studentMorningAtt.length} ครั้ง`} icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
          <StatCard title="คะแนนเข้าแถว" value={`${blockScore}`} sub={`สะสมในบล็อกเรียนปัจจุบัน`} icon={<Star size={28} />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="คะแนนคงเหลือล่าสุด" icon={<Activity size={28} />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm h-full">
            <h3 className="text-xl font-black text-slate-900 font-heading mb-6 flex items-center gap-3 uppercase tracking-widest">
              <Bell size={24} className="text-blue-600" /> แจ้งเตือนล่าสุด
            </h3>
            <div className="space-y-4">
              {studentNotifications.length > 0 ? studentNotifications.map(n => (
                <div key={n.id} className="p-5 bg-slate-50 rounded-[24px] border border-slate-100 flex gap-4 items-start relative overflow-hidden transition-all hover:scale-[1.02] hover:shadow-md cursor-default">
                  <div className={`w-1.5 h-full absolute left-0 top-0 ${n.type === 'ABSENT' ? 'bg-red-500' : 'bg-blue-500'}`} />
                  <div className="p-3 bg-white rounded-xl shadow-sm">
                    <Clock size={16} className="text-slate-400" />
                  </div>
                  <div>
                    <div className="flex justify-between items-center mb-1">
                      <p className="font-black text-slate-900 text-sm leading-tight">{n.title}</p>
                      {!n.isRead && <div className="w-2 h-2 bg-blue-600 rounded-full" />}
                    </div>
                    <p className="text-xs text-slate-600 font-bold leading-relaxed">{n.message}</p>
                    <p className="text-[9px] text-slate-400 mt-2 font-black uppercase">{n.timestamp} • {n.date}</p>
                  </div>
                </div>
              )) : (
                <div className="text-center py-20 text-slate-300">
                  <Bell size={48} className="mx-auto mb-4 opacity-10" />
                  <p className="text-xs font-black uppercase tracking-widest">ไม่มีแจ้งเตือนใหม่</p>
                </div>
              )}
            </div>
          </div>

          <div className="space-y-6">
            {finance.remaining > 0 ? (
              <div className="bg-gradient-to-br from-red-600 to-orange-600 p-8 md:p-10 rounded-[40px] text-white shadow-2xl relative overflow-hidden">
                <div className="relative z-10">
                  <p className="text-[10px] font-black text-red-100 uppercase tracking-[0.3em] mb-4 opacity-80">ยอดค้างชำระค่าเทอม</p>
                  <div className="flex items-baseline gap-3 mb-8">
                    <h2 className="text-6xl font-black font-heading tracking-tighter">{finance.remaining.toLocaleString()}</h2>
                    <span className="text-2xl font-bold opacity-80 uppercase font-heading">บาท</span>
                  </div>
                  <button 
                    onClick={() => setShowPaymentDetails(!showPaymentDetails)}
                    className="w-full px-10 py-5 bg-white text-red-600 rounded-[24px] font-black text-sm uppercase tracking-widest shadow-xl hover:bg-red-50 transition-all flex items-center justify-center gap-3 active:scale-95"
                  >
                    {showPaymentDetails ? <ChevronUp /> : <CreditCard />}
                    {showPaymentDetails ? 'ซ่อนรายละเอียด' : 'ดูช่องทางชำระเงิน'}
                  </button>
                </div>
              </div>
            ) : (
              <div className="bg-green-50 p-10 rounded-[40px] border border-green-200 flex flex-col items-center justify-center text-center gap-4 h-full">
                <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center text-green-600">
                  <CheckCircle2 size={40} />
                </div>
                <h3 className="text-2xl font-black text-green-900 font-heading">ชำระครบถ้วนแล้ว</h3>
                <p className="text-sm text-green-700 font-bold">ขอบคุณที่ชำระค่าธรรมเนียมการศึกษาตามกำหนด</p>
              </div>
            )}

            {showPaymentDetails && finance.remaining > 0 && (
              <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-xl animate-in slide-in-from-top-4 space-y-6">
                <div className="p-8 bg-[#00AEEF] rounded-[32px] text-white relative overflow-hidden shadow-lg">
                  <div className="absolute top-0 right-0 p-8 opacity-20 pointer-events-none transform translate-x-10 translate-y--10">
                     <Building2 size={180} />
                  </div>
                  <div className="relative z-10 space-y-6">
                    <div className="flex flex-wrap gap-x-12 gap-y-4">
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">ธนาคาร</p>
                        <p className="text-lg font-bold font-heading">{bankInfo.bankName}</p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">ชื่อบัญชี</p>
                        <p className="text-lg font-bold font-heading">{bankInfo.accountName}</p>
                      </div>
                    </div>
                    <div className="space-y-1">
                      <p className="text-[10px] font-black text-sky-100 uppercase tracking-widest opacity-80">เลขที่บัญชี</p>
                      <div className="flex items-center gap-6">
                        <p className="text-4xl md:text-5xl font-black tracking-tighter text-white font-heading">{bankInfo.accountNo}</p>
                        <button 
                          onClick={() => handleCopy(bankInfo.accountNo)}
                          className={`flex items-center justify-center gap-2 px-5 py-2.5 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all shadow-xl ${copied ? 'bg-green-500 text-white' : 'bg-white text-[#00AEEF] hover:bg-sky-50'}`}
                        >
                          {copied ? <Check size={14} /> : <Copy size={14} />}
                          {copied ? 'คัดลอกแล้ว' : 'คัดลอก'}
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }

  // Admin/Teacher Dashboard
  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-center justify-between gap-6 bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
        <div className="flex items-center gap-5">
          <div className="p-4 bg-slate-900 rounded-[20px] text-white shadow-xl shadow-slate-100">
            <LayoutDashboard size={28} />
          </div>
          <div>
            <h2 className="text-2xl font-black text-slate-900 tracking-tight font-heading">แดชบอร์ดบริหารสถานศึกษา</h2>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">สรุปภาพรวมข้อมูลอาชีวศึกษา</p>
          </div>
        </div>

        <div className="flex gap-4 w-full lg:w-auto">
          <div className="flex-1 lg:w-48">
            <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3.5 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-400 transition-all">
              <option value="ALL">ทุกระดับชั้น</option>
              {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
            </select>
          </div>
          <div className="flex-1 lg:w-56">
            <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3.5 rounded-2xl text-[10px] font-black uppercase outline-none focus:border-blue-400 transition-all">
              <option value="ALL">ทุกแผนกวิชา</option>
              {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard title="จำนวนนักเรียน" value={filteredStudentsBase.length} sub="ในกลุ่มที่เลือก" icon={<Users size={28} />} color="bg-slate-900" />
        <StatCard title="เฝ้าระวังพฤติกรรม" value={behaviorWatchlist.length} sub="คะแนนพฤติกรรมต่ำกว่า 70" icon={<ShieldAlert size={28} />} color="bg-red-600" textColor="text-red-600" />
        <StatCard title="เฝ้าระวังเข้าแถว" value={attendanceWatchlist.length} sub="คะแนนเข้าแถวต่ำกว่า 3.0" icon={<Sun size={28} />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
        <StatCard title="มาสายวันนี้" value={morningAttendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'LATE' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="หลังเวลา 07:50 น." icon={<Clock size={28} />} color="bg-amber-500" textColor="text-amber-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm min-h-[500px] flex flex-col">
          <div className="flex items-center justify-between mb-10">
            <div>
              <h3 className="text-xl font-black text-slate-900 font-heading flex items-center gap-3">
                 <BarChart3 className="text-[#00AEEF]" size={24} /> สถิติจำนวนคนเข้าแถวรายวัน
              </h3>
              <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">การเข้าแถวหน้าเสาธง 7 วันย้อนหลัง</p>
            </div>
            <div className="flex items-center gap-2 bg-sky-50 px-4 py-2 rounded-full border border-sky-100">
               <div className="w-2.5 h-2.5 bg-[#00AEEF] rounded-full animate-pulse" />
               <span className="text-[10px] font-black text-[#00AEEF] uppercase tracking-widest">Live Report</span>
            </div>
          </div>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#94a3b8'}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#94a3b8'}} />
                <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)', fontFamily: 'Prompt' }} labelStyle={{ fontWeight: 900, color: '#0f172a', marginBottom: '4px' }} />
                <Bar dataKey="value" name="จำนวนคนมาแถว" radius={[8, 8, 0, 0]} barSize={40}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={index === chartData.length - 1 ? '#00AEEF' : '#cbd5e1'} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="flex flex-col gap-6">
          {/* พฤติกรรมเฝ้าระวัง */}
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm flex flex-col relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
              <ShieldAlert size={150} />
            </div>
            <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-6 font-heading flex items-center gap-2">
              <ShieldAlert size={20} className="text-red-600" /> กลุ่มเฝ้าระวังพฤติกรรม
            </h4>
            <div className="space-y-4 flex-1">
              {behaviorWatchlist.map(s => (
                <button 
                  key={s.id} 
                  onClick={() => setViewingStudentId(s.id)} 
                  className="w-full group flex items-center justify-between p-4 bg-red-50 hover:bg-red-100 rounded-2xl cursor-pointer transition-all border border-red-100/50"
                >
                  <div className="flex items-center gap-4 text-left">
                    <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-red-600 font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                    <div className="min-w-0">
                      <p className="font-bold text-sm text-slate-900 truncate leading-tight">{s.name}</p>
                      <p className="text-[10px] text-slate-500 font-bold uppercase">{s.studentId}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <div className="text-right mr-2">
                      <p className="text-[9px] font-black text-red-400 uppercase tracking-tighter">คะแนน</p>
                      <p className="font-black text-red-600 leading-tight">{s.behaviorScore}</p>
                    </div>
                    <ChevronRight size={18} className="text-red-300 group-hover:translate-x-1 transition-transform" />
                  </div>
                </button>
              ))}
              {behaviorWatchlist.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center py-10 text-slate-300">
                  <CheckCircle2 size={32} className="mb-2 opacity-10" />
                  <p className="text-xs font-black uppercase tracking-widest text-center">ไม่มีกลุ่มเฝ้าระวังพฤติกรรม</p>
                </div>
              )}
            </div>
          </div>

          {/* เข้าแถวเฝ้าระวัง */}
          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm flex flex-col relative overflow-hidden">
            <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
              <Sun size={150} />
            </div>
            <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest mb-6 font-heading flex items-center gap-2">
              <Clock size={20} className="text-[#00AEEF]" /> กลุ่มเฝ้าระวังคะแนนเข้าแถว
            </h4>
            <div className="space-y-4 flex-1">
              {attendanceWatchlist.map(s => {
                const score = getMorningScore(s.id);
                return (
                  <button 
                    key={s.id} 
                    onClick={() => setViewingStudentId(s.id)} 
                    className="w-full group flex items-center justify-between p-4 bg-sky-50 hover:bg-sky-100 rounded-2xl cursor-pointer transition-all border border-sky-100/50"
                  >
                    <div className="flex items-center gap-4 text-left">
                      <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-[#00AEEF] font-black text-xs shadow-sm">{s.name.charAt(0)}</div>
                      <div className="min-w-0">
                        <p className="font-bold text-sm text-slate-900 truncate leading-tight">{s.name}</p>
                        <p className="text-[10px] text-slate-500 font-bold uppercase">{s.studentId}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      <div className="text-right mr-2">
                        <p className="text-[9px] font-black text-sky-400 uppercase tracking-tighter">คะแนน</p>
                        <p className="font-black text-[#00AEEF] leading-tight">{score}</p>
                      </div>
                      <ChevronRight size={18} className="text-sky-300 group-hover:translate-x-1 transition-transform" />
                    </div>
                  </button>
                );
              })}
              {attendanceWatchlist.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center py-10 text-slate-300">
                  <CheckCircle2 size={32} className="mb-2 opacity-10" />
                  <p className="text-xs font-black uppercase tracking-widest text-center">ไม่มีกลุ่มเฝ้าระวังคะแนนเข้าแถว</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Student, Subject, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { 
  Save, BookOpen, Clock, Users, MessageSquare, UserPlus, X, Plus, Filter, 
  History, ClipboardCheck, Calendar, Edit3, CheckCircle2, Trash2, AlertCircle, Lock,
  Share2, Search, ChevronRight, Settings2
} from 'lucide-react';

interface ClassAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  subjects: Subject[];
  setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  currentUser: any;
}

const ClassAttendance: React.FC<ClassAttendanceProps> = ({ 
  students: allStudents, 
  subjects, 
  setSubjects,
  attendanceRecords, 
  setAttendanceRecords,
  currentUser
}) => {
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');
  const [searchTerm, setSearchTerm] = useState('');
  const [showSubjectModal, setShowSubjectModal] = useState(false);
  const [editingSubject, setEditingSubject] = useState<Partial<Subject> | null>(null);

  const availableLevels = useMemo<string[]>(() => {
    const levels = Array.from(new Set(allStudents.map(s => s.level)));
    return (levels.length > 0 ? levels.sort() : Object.values(ThaiLevel)) as string[];
  }, [allStudents]);

  const availableDepts = useMemo<string[]>(() => {
    const depts = Array.from(new Set(allStudents.map(s => s.department)));
    return (depts.length > 0 ? depts.sort() : Object.values(Department)) as string[];
  }, [allStudents]);

  const availableRooms = useMemo<string[]>(() => {
    const rms = Array.from(new Set(allStudents.map(s => s.room)));
    return rms.length > 0 ? rms.sort((a, b) => parseInt(a as string) - parseInt(b as string)) : ['1', '2', '3'];
  }, [allStudents]);

  const [level, setLevel] = useState<string>(availableLevels[0] || '');
  const [dept, setDept] = useState<string>(availableDepts[0] || '');
  const [room, setRoom] = useState<string>(availableRooms[0] || '');
  const [subjectId, setSubjectId] = useState<string>(subjects[0]?.id || '');

  const [sessionAttendance, setSessionAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);

  // Sync state with attendanceRecords whenever filters change
  useEffect(() => {
    if (!subjectId) return;
    const today = new Date().toISOString().split('T')[0];
    const existing = attendanceRecords.filter(r => r.date === today && r.type === 'SUBJECT' && r.subjectId === subjectId);

    const attMap: Record<string, AttendanceStatus> = {};
    const remMap: Record<string, string> = {};

    existing.forEach(r => {
      attMap[r.studentId] = r.status;
      if (r.remark) remMap[r.studentId] = r.remark;
    });

    setSessionAttendance(attMap);
    setRemarks(remMap);
  }, [level, dept, room, subjectId, attendanceRecords]);

  const filteredStudents = useMemo(() => {
    return allStudents.filter(s => 
      s.level === level && 
      s.department === dept && 
      s.room === room &&
      (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm))
    );
  }, [allStudents, level, dept, room, searchTerm]);

  const historyRecords = useMemo(() => {
    return attendanceRecords.filter(record => {
      const student = allStudents.find(s => s.id === record.studentId);
      return record.type === 'SUBJECT' && 
             record.subjectId === subjectId &&
             student?.level === level && 
             student?.department === dept && 
             student?.room === room;
    }).sort((a, b) => b.date.localeCompare(a.date) || b.timestamp.localeCompare(a.timestamp));
  }, [attendanceRecords, subjectId, level, dept, room, allStudents]);

  const handleStatusChange = (id: string, status: AttendanceStatus) => {
    setSessionAttendance(prev => ({ ...prev, [id]: status }));
    setIsSaved(false);
  };

  const handleSave = () => {
    if (!subjectId) return alert('กรุณาเลือกรายวิชา');

    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    const newRecordsBatch: AttendanceRecord[] = filteredStudents.map(s => ({
      id: `SUBJECT_${today}_${subjectId}_${s.id}`,
      studentId: s.id,
      date: today,
      type: 'SUBJECT',
      subjectId: subjectId,
      status: sessionAttendance[s.id] || 'ABSENT',
      remark: remarks[s.id] || '',
      timestamp: timestamp
    }));

    setAttendanceRecords(prev => {
      const studentIds = filteredStudents.map(s => s.id);
      const otherRecords = prev.filter(r => !(r.date === today && r.type === 'SUBJECT' && r.subjectId === subjectId && studentIds.includes(r.studentId)));
      return [...otherRecords, ...newRecordsBatch];
    });

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setSessionAttendance(prev => ({ ...prev, ...newBatch }));
  };

  const handleSaveSubject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingSubject?.name || !editingSubject?.code) return;

    if (editingSubject.id) {
      setSubjects(prev => prev.map(s => s.id === editingSubject.id ? (editingSubject as Subject) : s));
    } else {
      const newSub: Subject = {
        ...(editingSubject as Subject),
        id: `SUB_${Date.now()}`,
        teacherId: currentUser.id
      };
      setSubjects(prev => [...prev, newSub]);
      if (!subjectId) setSubjectId(newSub.id);
    }
    setEditingSubject(null);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div className="flex bg-white p-2 rounded-[24px] border border-slate-200 shadow-sm w-fit">
          <button onClick={() => setViewMode('checkin')} className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><ClipboardCheck size={20} /> เช็คชื่อ</button>
          <button onClick={() => setViewMode('history')} className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><History size={20} /> ประวัติ</button>
        </div>

        <button 
          onClick={() => setShowSubjectModal(true)}
          className="flex items-center gap-2 px-6 py-3.5 bg-white border border-slate-200 rounded-2xl text-slate-600 text-sm font-black hover:bg-slate-50 transition-all shadow-sm font-heading"
        >
          <Settings2 size={18} className="text-blue-600" /> จัดการรายวิชา
        </button>
      </div>

      <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
        <div className="grid grid-cols-1 md:grid-cols-5 gap-6">
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
            <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none">
              {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
            <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none">
              {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ห้องเรียน</label>
            <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none">
              {availableRooms.map(r => <option key={r} value={r}>ห้อง {r}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">รายวิชา</label>
            <select value={subjectId} onChange={(e) => setSubjectId(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none">
              {subjects.length > 0 ? subjects.map(s => <option key={s.id} value={s.id}>{s.code} - {s.name}</option>) : <option value="">(ไม่มีรายวิชา)</option>}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ค้นหา</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อ..." className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-10 pr-4 py-3 font-bold text-slate-900 outline-none text-sm" />
            </div>
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <>
          <div className="flex justify-between items-center px-2">
            <div className="flex gap-3">
              <button onClick={() => markAll('PRESENT')} className="px-5 py-2 bg-green-50 text-green-700 rounded-full text-xs font-black border border-green-200 transition-all hover:bg-green-100">มาทุกคน</button>
              <button onClick={() => markAll('ABSENT')} className="px-5 py-2 bg-red-50 text-red-700 rounded-full text-xs font-black border border-red-200 transition-all hover:bg-red-100">ขาดทุกคน</button>
            </div>
            <button onClick={handleSave} className={`flex items-center gap-3 px-8 py-4 rounded-2xl text-white font-black transition-all shadow-xl ${isSaved ? 'bg-green-600' : 'bg-slate-900 hover:bg-black active:scale-95'}`}>
              {isSaved ? <CheckCircle2 size={22} /> : <Save size={22} />}
              <span>{isSaved ? 'บันทึกแล้ว' : 'บันทึกข้อมูลวันนี้'}</span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {filteredStudents.map((student, index) => (
              <div key={student.id} className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col justify-between hover:border-blue-300 transition-all group">
                <div className="flex justify-between items-start gap-4">
                  <div className="flex items-start gap-4">
                    <div className="w-12 h-12 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-white shrink-0 group-hover:bg-blue-600 transition-colors">{index + 1}</div>
                    <div>
                      <h4 className="font-black text-slate-900 text-lg leading-tight">{student.name}</h4>
                      <p className="text-[10px] text-slate-500 font-bold uppercase mt-1 tracking-widest">รหัส: {student.studentId}</p>
                    </div>
                  </div>
                  <div className="grid grid-cols-5 gap-1.5">
                    {Object.entries(STATUS_LABELS).map(([key, value]) => (
                      <button key={key} onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} className={`flex flex-col items-center gap-1 p-2 rounded-xl border-2 transition-all ${sessionAttendance[student.id] === key ? value.color + ' border-current shadow-sm' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-200'}`}>
                        <div className="scale-110">{value.icon}</div>
                        <span className="text-[8px] font-black uppercase text-center">{value.label}</span>
                      </button>
                    ))}
                  </div>
                </div>
                {sessionAttendance[student.id] && sessionAttendance[student.id] !== 'PRESENT' && (
                  <div className="mt-4 relative">
                    <MessageSquare className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                    <input type="text" value={remarks[student.id] || ''} onChange={(e) => setRemarks(prev => ({ ...prev, [student.id]: e.target.value }))} placeholder="ระบุหมายเหตุ..." className="w-full bg-slate-50 border border-slate-100 rounded-xl pl-9 pr-4 py-2 text-xs font-bold outline-none focus:border-blue-400 transition-all" />
                  </div>
                )}
              </div>
            ))}
            {filteredStudents.length === 0 && (
              <div className="col-span-full py-20 text-center bg-white rounded-[32px] border-2 border-dashed border-slate-100 text-slate-300">
                <Users size={48} className="mx-auto mb-4 opacity-10" />
                <p className="text-sm font-black uppercase tracking-widest">ไม่พบรายชื่อนักเรียนในกลุ่มนี้</p>
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 border-b">
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">วันที่</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">นักเรียน</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">สถานะ</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">วิชา</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {historyRecords.length > 0 ? historyRecords.map((record) => {
                const student = allStudents.find(s => s.id === record.studentId);
                const subj = subjects.find(s => s.id === record.subjectId);
                return (
                  <tr key={record.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4 font-bold text-slate-900 text-sm whitespace-nowrap">{record.date}</td>
                    <td className="px-6 py-4">
                      <p className="font-black text-slate-900 text-sm">{student?.name}</p>
                      <p className="text-[10px] text-slate-500 font-bold">{student?.studentId}</p>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-3 py-1 rounded-full text-[10px] font-black border flex items-center gap-2 w-fit ${STATUS_LABELS[record.status].color}`}>
                        {STATUS_LABELS[record.status].label}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-xs font-bold text-slate-500">{subj?.code}</td>
                  </tr>
                );
              }) : (
                <tr>
                  <td colSpan={4} className="py-20 text-center text-slate-300">
                    <History size={48} className="mx-auto mb-4 opacity-10" />
                    <p className="text-xs font-black uppercase tracking-widest">ยังไม่มีประวัติการเช็คชื่อในรายวิชานี้</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Subject Management Modal */}
      {showSubjectModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-md overflow-y-auto">
          <div className="bg-white w-full max-w-2xl rounded-[48px] p-8 md:p-12 shadow-2xl animate-in zoom-in-95 duration-300 relative my-8">
            <button onClick={() => { setShowSubjectModal(false); setEditingSubject(null); }} className="absolute top-10 right-10 text-slate-400 hover:text-slate-900 transition-colors">
              <X size={28} />
            </button>
            <h3 className="text-2xl font-black text-slate-900 mb-8 uppercase tracking-tight font-heading flex items-center gap-3">
              <BookOpen size={28} className="text-blue-600" /> จัดการรายวิชาเช็คชื่อ
            </h3>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-6">
                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">{editingSubject?.id ? 'แก้ไขรายวิชา' : 'เพิ่มรายวิชาใหม่'}</h4>
                <form onSubmit={handleSaveSubject} className="space-y-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-bold text-slate-400 ml-1">รหัสวิชา</label>
                    <input 
                      type="text" 
                      required 
                      value={editingSubject?.code || ''} 
                      onChange={(e) => setEditingSubject(prev => ({ ...prev, code: e.target.value }))}
                      className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-3 font-bold outline-none transition-all" 
                      placeholder="เช่น IT30201"
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-bold text-slate-400 ml-1">ชื่อวิชา</label>
                    <input 
                      type="text" 
                      required 
                      value={editingSubject?.name || ''} 
                      onChange={(e) => setEditingSubject(prev => ({ ...prev, name: e.target.value }))}
                      className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-3 font-bold outline-none transition-all" 
                      placeholder="เช่น ภาษาอังกฤษเพื่ออาชีพ"
                    />
                  </div>
                  <div className="flex gap-3 pt-2">
                    {editingSubject && (
                      <button type="button" onClick={() => setEditingSubject(null)} className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-black text-[10px] uppercase tracking-widest">ยกเลิก</button>
                    )}
                    <button type="submit" className="flex-1 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-blue-100">
                      {editingSubject?.id ? 'บันทึกการแก้ไข' : 'เพิ่มรายวิชา'}
                    </button>
                  </div>
                </form>
              </div>

              <div className="space-y-6">
                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">รายวิชาทั้งหมด ({subjects.length})</h4>
                <div className="space-y-3 max-h-[300px] overflow-y-auto pr-2 scrollbar-hide">
                  {subjects.map(s => (
                    <div key={s.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100 group">
                      <div className="min-w-0">
                        <p className="font-black text-sm text-slate-900 truncate">{s.name}</p>
                        <p className="text-[10px] font-bold text-slate-400 uppercase">{s.code}</p>
                      </div>
                      <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={() => setEditingSubject(s)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-white rounded-lg transition-all"><Edit3 size={16} /></button>
                        <button onClick={() => setSubjects(prev => prev.filter(i => i.id !== s.id))} className="p-2 text-slate-400 hover:text-red-600 hover:bg-white rounded-lg transition-all"><Trash2 size={16} /></button>
                      </div>
                    </div>
                  ))}
                  {subjects.length === 0 && (
                    <div className="py-10 text-center text-slate-300 italic text-xs">ยังไม่มีข้อมูลรายวิชา</div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ClassAttendance;

import React, { useState, useEffect, useMemo } from 'react';
import { Student, Subject, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { 
  Save, BookOpen, Clock, Users, MessageSquare, UserPlus, X, Plus, Filter, 
  History, ClipboardCheck, Calendar, Edit3, CheckCircle2, Trash2, AlertCircle, Lock,
  Share2, Search, ChevronRight, Settings2
} from 'lucide-react';

interface ClassAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  subjects: Subject[];
  setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  currentUser: any;
}

const ClassAttendance: React.FC<ClassAttendanceProps> = ({ 
  students: allStudents, 
  subjects, 
  setSubjects,
  attendanceRecords, 
  setAttendanceRecords,
  currentUser
}) => {
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');
  const [searchTerm, setSearchTerm] = useState('');
  const [showSubjectModal, setShowSubjectModal] = useState(false);
  const [editingSubject, setEditingSubject] = useState<Partial<Subject> | null>(null);

  const availableLevels = useMemo<string[]>(() => {
    const levels = Array.from(new Set(allStudents.map(s => s.level)));
    return (levels.length > 0 ? levels.sort() : Object.values(ThaiLevel)) as string[];
  }, [allStudents]);

  const availableDepts = useMemo<string[]>(() => {
    const depts = Array.from(new Set(allStudents.map(s => s.department)));
    return (depts.length > 0 ? depts.sort() : Object.values(Department)) as string[];
  }, [allStudents]);

  const availableRooms = useMemo<string[]>(() => {
    const rms = Array.from(new Set(allStudents.map(s => s.room)));
    return rms.length > 0 ? rms.sort((a, b) => parseInt(a as string) - parseInt(b as string)) : ['1', '2', '3'];
  }, [allStudents]);

  const [level, setLevel] = useState<string>(availableLevels[0] || '');
  const [dept, setDept] = useState<string>(availableDepts[0] || '');
  const [room, setRoom] = useState<string>(availableRooms[0] || '');

  // CRITICAL: Filter subjects based on selected level and department
  const filteredSubjects = useMemo(() => {
    return subjects.filter(s => s.level === level && s.department === dept);
  }, [subjects, level, dept]);

  const [subjectId, setSubjectId] = useState<string>('');

  // Auto-select first subject when filters change
  useEffect(() => {
    if (filteredSubjects.length > 0) {
      // If current selected subject is not in the filtered list, switch to first one
      if (!filteredSubjects.some(s => s.id === subjectId)) {
        setSubjectId(filteredSubjects[0].id);
      }
    } else {
      setSubjectId('');
    }
  }, [filteredSubjects, subjectId]);

  const [sessionAttendance, setSessionAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);

  // Sync state with attendanceRecords whenever filters change
  useEffect(() => {
    if (!subjectId) {
      setSessionAttendance({});
      setRemarks({});
      return;
    }
    const today = new Date().toISOString().split('T')[0];
    const existing = attendanceRecords.filter(r => r.date === today && r.type === 'SUBJECT' && r.subjectId === subjectId);

    const attMap: Record<string, AttendanceStatus> = {};
    const remMap: Record<string, string> = {};

    existing.forEach(r => {
      attMap[r.studentId] = r.status;
      if (r.remark) remMap[r.studentId] = r.remark;
    });

    setSessionAttendance(attMap);
    setRemarks(remMap);
  }, [level, dept, room, subjectId, attendanceRecords]);

  const filteredStudents = useMemo(() => {
    return allStudents.filter(s => 
      s.level === level && 
      s.department === dept && 
      s.room === room &&
      (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm))
    );
  }, [allStudents, level, dept, room, searchTerm]);

  const historyRecords = useMemo(() => {
    return attendanceRecords.filter(record => {
      const student = allStudents.find(s => s.id === record.studentId);
      return record.type === 'SUBJECT' && 
             record.subjectId === subjectId &&
             student?.level === level && 
             student?.department === dept && 
             student?.room === room;
    }).sort((a, b) => b.date.localeCompare(a.date) || b.timestamp.localeCompare(a.timestamp));
  }, [attendanceRecords, subjectId, level, dept, room, allStudents]);

  const handleStatusChange = (id: string, status: AttendanceStatus) => {
    setSessionAttendance(prev => ({ ...prev, [id]: status }));
    setIsSaved(false);
  };

  const handleSave = () => {
    if (!subjectId) return alert('กรุณาเลือกรายวิชา');

    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    const newRecordsBatch: AttendanceRecord[] = filteredStudents.map(s => ({
      id: `SUBJECT_${today}_${subjectId}_${s.id}`,
      studentId: s.id,
      date: today,
      type: 'SUBJECT',
      subjectId: subjectId,
      status: sessionAttendance[s.id] || 'ABSENT',
      remark: remarks[s.id] || '',
      timestamp: timestamp
    }));

    setAttendanceRecords(prev => {
      const studentIds = filteredStudents.map(s => s.id);
      const otherRecords = prev.filter(r => !(r.date === today && r.type === 'SUBJECT' && r.subjectId === subjectId && studentIds.includes(r.studentId)));
      return [...otherRecords, ...newRecordsBatch];
    });

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setSessionAttendance(prev => ({ ...prev, ...newBatch }));
  };

  const handleSaveSubject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingSubject?.name || !editingSubject?.code || !editingSubject?.level || !editingSubject?.department) return;

    if (editingSubject.id) {
      setSubjects(prev => prev.map(s => s.id === editingSubject.id ? (editingSubject as Subject) : s));
    } else {
      const newSub: Subject = {
        ...(editingSubject as Subject),
        id: `SUB_${Date.now()}`,
        teacherId: currentUser.id
      };
      setSubjects(prev => [...prev, newSub]);
    }
    setEditingSubject(null);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div className="flex bg-white p-2 rounded-[24px] border border-slate-200 shadow-sm w-fit">
          <button onClick={() => setViewMode('checkin')} className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><ClipboardCheck size={20} /> เช็คชื่อ</button>
          <button onClick={() => setViewMode('history')} className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><History size={20} /> ประวัติ</button>
        </div>

        <button 
          onClick={() => {
            // Default level and dept in modal based on current view
            setEditingSubject({ level: level, department: dept });
            setShowSubjectModal(true);
          }}
          className="flex items-center gap-2 px-6 py-3.5 bg-white border border-slate-200 rounded-2xl text-slate-600 text-sm font-black hover:bg-slate-50 transition-all shadow-sm font-heading"
        >
          <Settings2 size={18} className="text-blue-600" /> จัดการรายวิชา
        </button>
      </div>

      <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
        <div className="grid grid-cols-1 md:grid-cols-5 gap-6">
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
            <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none">
              {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
            <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none">
              {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ห้องเรียน</label>
            <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none">
              {availableRooms.map(r => <option key={r} value={r}>ห้อง {r}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 text-blue-600">วิชาที่เปิดสอน ({level})</label>
            <select value={subjectId} onChange={(e) => setSubjectId(e.target.value)} className="w-full bg-slate-50 border border-blue-100 rounded-xl px-4 py-3 font-black text-slate-900 outline-none focus:border-blue-400">
              {filteredSubjects.length > 0 ? filteredSubjects.map(s => <option key={s.id} value={s.id}>{s.code} - {s.name}</option>) : <option value="">(ไม่มีรายวิชาในกลุ่มนี้)</option>}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ค้นหานักเรียน</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อ..." className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-10 pr-4 py-3 font-bold text-slate-900 outline-none text-sm" />
            </div>
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <>
          <div className="flex justify-between items-center px-2">
            <div className="flex gap-3">
              <button onClick={() => markAll('PRESENT')} className="px-5 py-2 bg-green-50 text-green-700 rounded-full text-xs font-black border border-green-200 transition-all hover:bg-green-100">มาทุกคน</button>
              <button onClick={() => markAll('ABSENT')} className="px-5 py-2 bg-red-50 text-red-700 rounded-full text-xs font-black border border-red-200 transition-all hover:bg-red-100">ขาดทุกคน</button>
            </div>
            <button onClick={handleSave} className={`flex items-center gap-3 px-8 py-4 rounded-2xl text-white font-black transition-all shadow-xl ${isSaved ? 'bg-green-600' : 'bg-slate-900 hover:bg-black active:scale-95'}`}>
              {isSaved ? <CheckCircle2 size={22} /> : <Save size={22} />}
              <span>{isSaved ? 'บันทึกแล้ว' : 'บันทึกข้อมูลวันนี้'}</span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {filteredStudents.map((student, index) => (
              <div key={student.id} className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col justify-between hover:border-blue-300 transition-all group">
                <div className="flex justify-between items-start gap-4">
                  <div className="flex items-start gap-4">
                    <div className="w-12 h-12 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-white shrink-0 group-hover:bg-blue-600 transition-colors">{index + 1}</div>
                    <div>
                      <h4 className="font-black text-slate-900 text-lg leading-tight">{student.name}</h4>
                      <p className="text-[10px] text-slate-500 font-bold uppercase mt-1 tracking-widest">รหัส: {student.studentId}</p>
                    </div>
                  </div>
                  <div className="grid grid-cols-5 gap-1.5">
                    {Object.entries(STATUS_LABELS).map(([key, value]) => (
                      <button key={key} onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} className={`flex flex-col items-center gap-1 p-2 rounded-xl border-2 transition-all ${sessionAttendance[student.id] === key ? value.color + ' border-current shadow-sm' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-200'}`}>
                        <div className="scale-110">{value.icon}</div>
                        <span className="text-[8px] font-black uppercase text-center">{value.label}</span>
                      </button>
                    ))}
                  </div>
                </div>
                {sessionAttendance[student.id] && sessionAttendance[student.id] !== 'PRESENT' && (
                  <div className="mt-4 relative">
                    <MessageSquare className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                    <input type="text" value={remarks[student.id] || ''} onChange={(e) => setRemarks(prev => ({ ...prev, [student.id]: e.target.value }))} placeholder="ระบุหมายเหตุ..." className="w-full bg-slate-50 border border-slate-100 rounded-xl pl-9 pr-4 py-2 text-xs font-bold outline-none focus:border-blue-400 transition-all" />
                  </div>
                )}
              </div>
            ))}
            {filteredStudents.length === 0 && (
              <div className="col-span-full py-20 text-center bg-white rounded-[32px] border-2 border-dashed border-slate-100 text-slate-300">
                <Users size={48} className="mx-auto mb-4 opacity-10" />
                <p className="text-sm font-black uppercase tracking-widest">ไม่พบรายชื่อนักเรียนในกลุ่มนี้</p>
              </div>
            )}
            {filteredStudents.length > 0 && !subjectId && (
              <div className="col-span-full py-20 text-center bg-white rounded-[32px] border-2 border-dashed border-red-100 text-red-400">
                <AlertCircle size={48} className="mx-auto mb-4 opacity-10" />
                <p className="text-sm font-black uppercase tracking-widest">กรุณาเลือกรายวิชาหรือเพิ่มรายวิชาสำหรับระดับชั้น {level}</p>
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 border-b">
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">วันที่</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">นักเรียน</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">สถานะ</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">วิชา</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {historyRecords.length > 0 ? historyRecords.map((record) => {
                const student = allStudents.find(s => s.id === record.studentId);
                const subj = subjects.find(s => s.id === record.subjectId);
                return (
                  <tr key={record.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4 font-bold text-slate-900 text-sm whitespace-nowrap">{record.date}</td>
                    <td className="px-6 py-4">
                      <p className="font-black text-slate-900 text-sm">{student?.name}</p>
                      <p className="text-[10px] text-slate-500 font-bold">{student?.studentId}</p>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-3 py-1 rounded-full text-[10px] font-black border flex items-center gap-2 w-fit ${STATUS_LABELS[record.status].color}`}>
                        {STATUS_LABELS[record.status].label}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-xs font-bold text-slate-500">{subj?.code}</td>
                  </tr>
                );
              }) : (
                <tr>
                  <td colSpan={4} className="py-20 text-center text-slate-300">
                    <History size={48} className="mx-auto mb-4 opacity-10" />
                    <p className="text-xs font-black uppercase tracking-widest">ยังไม่มีประวัติการเช็คชื่อในรายวิชานี้</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Subject Management Modal */}
      {showSubjectModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-md overflow-y-auto">
          <div className="bg-white w-full max-w-4xl rounded-[48px] p-8 md:p-12 shadow-2xl animate-in zoom-in-95 duration-300 relative my-8">
            <button onClick={() => { setShowSubjectModal(false); setEditingSubject(null); }} className="absolute top-10 right-10 text-slate-400 hover:text-slate-900 transition-colors">
              <X size={28} />
            </button>
            <h3 className="text-2xl font-black text-slate-900 mb-8 uppercase tracking-tight font-heading flex items-center gap-3">
              <BookOpen size={28} className="text-blue-600" /> จัดการรายวิชาเช็คชื่อ
            </h3>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              <div className="space-y-6">
                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">{editingSubject?.id ? 'แก้ไขรายวิชา' : 'เพิ่มรายวิชาใหม่'}</h4>
                <form onSubmit={handleSaveSubject} className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-bold text-slate-400 ml-1">รหัสวิชา</label>
                      <input 
                        type="text" 
                        required 
                        value={editingSubject?.code || ''} 
                        onChange={(e) => setEditingSubject(prev => ({ ...prev, code: e.target.value }))}
                        className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-3 font-bold outline-none transition-all" 
                        placeholder="เช่น IT30201"
                      />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-bold text-slate-400 ml-1">ชื่อวิชา</label>
                      <input 
                        type="text" 
                        required 
                        value={editingSubject?.name || ''} 
                        onChange={(e) => setEditingSubject(prev => ({ ...prev, name: e.target.value }))}
                        className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-3 font-bold outline-none transition-all" 
                        placeholder="เช่น ภาษาอังกฤษเพื่ออาชีพ"
                      />
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-bold text-slate-400 ml-1">ระดับชั้น</label>
                      <select 
                        value={editingSubject?.level || ''} 
                        onChange={(e) => setEditingSubject(prev => ({ ...prev, level: e.target.value }))}
                        className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-3 font-bold outline-none cursor-pointer"
                      >
                        <option value="">เลือกสีมารถ...</option>
                        {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
                      </select>
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-bold text-slate-400 ml-1">แผนกวิชา</label>
                      <select 
                        value={editingSubject?.department || ''} 
                        onChange={(e) => setEditingSubject(prev => ({ ...prev, department: e.target.value }))}
                        className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-3 font-bold outline-none cursor-pointer"
                      >
                        <option value="">เลือกแผนก...</option>
                        {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
                      </select>
                    </div>
                  </div>

                  <div className="flex gap-3 pt-2">
                    {editingSubject?.id && (
                      <button type="button" onClick={() => setEditingSubject(null)} className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-black text-[10px] uppercase tracking-widest">ยกเลิก</button>
                    )}
                    <button type="submit" className="flex-1 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-blue-100">
                      {editingSubject?.id ? 'บันทึกการแก้ไข' : 'เพิ่มรายวิชา'}
                    </button>
                  </div>
                </form>
              </div>

              <div className="space-y-6">
                <div className="flex items-center justify-between ml-1">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">รายวิชาทั้งหมด ({subjects.length})</h4>
                  <div className="text-[9px] font-bold text-slate-400 bg-slate-50 px-2 py-1 rounded-md uppercase">กรองตามห้องเรียนที่เลือกอัตโนมัติ</div>
                </div>
                <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 scrollbar-hide">
                  {subjects.sort((a,b) => a.level.localeCompare(b.level)).map(s => {
                    const isMatched = s.level === level && s.department === dept;
                    return (
                      <div key={s.id} className={`flex items-center justify-between p-4 rounded-2xl border-2 transition-all group ${isMatched ? 'bg-blue-50 border-blue-100' : 'bg-slate-50 border-slate-100'}`}>
                        <div className="min-w-0">
                          <p className="font-black text-sm text-slate-900 truncate">{s.name}</p>
                          <div className="flex items-center gap-2 mt-1">
                            <span className="text-[9px] font-black text-slate-500 bg-white px-2 py-0.5 rounded border border-slate-100 uppercase">{s.code}</span>
                            <span className={`text-[9px] font-black px-2 py-0.5 rounded border uppercase ${isMatched ? 'bg-blue-600 text-white border-blue-600' : 'bg-slate-200 text-slate-600 border-slate-200'}`}>{s.level}</span>
                          </div>
                        </div>
                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => setEditingSubject(s)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-white rounded-lg transition-all"><Edit3 size={16} /></button>
                          <button onClick={() => setSubjects(prev => prev.filter(i => i.id !== s.id))} className="p-2 text-slate-400 hover:text-red-600 hover:bg-white rounded-lg transition-all"><Trash2 size={16} /></button>
                        </div>
                      </div>
                    );
                  })}
                  {subjects.length === 0 && (
                    <div className="py-20 text-center text-slate-300 italic text-xs">ยังไม่มีข้อมูลรายวิชา</div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ClassAttendance;

import React, { useState, useEffect, useMemo } from 'react';
import { Student, Subject, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { 
  Save, BookOpen, Clock, Users, MessageSquare, UserPlus, X, Plus, Filter, 
  History, ClipboardCheck, Calendar, Edit3, CheckCircle2, Trash2, AlertCircle, Lock,
  Share2, Search, ChevronRight, Settings2
} from 'lucide-react';

interface ClassAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  subjects: Subject[];
  setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  currentUser: any;
}

const ClassAttendance: React.FC<ClassAttendanceProps> = ({ 
  students: allStudents, 
  subjects, 
  setSubjects,
  attendanceRecords, 
  setAttendanceRecords,
  currentUser
}) => {
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');
  const [searchTerm, setSearchTerm] = useState('');
  const [showSubjectModal, setShowSubjectModal] = useState(false);
  const [editingSubject, setEditingSubject] = useState<Partial<Subject> | null>(null);

  const availableLevels = useMemo<string[]>(() => {
    const levels = Array.from(new Set(allStudents.map(s => s.level)));
    return (levels.length > 0 ? levels.sort() : Object.values(ThaiLevel)) as string[];
  }, [allStudents]);

  const availableDepts = useMemo<string[]>(() => {
    const depts = Array.from(new Set(allStudents.map(s => s.department)));
    return (depts.length > 0 ? depts.sort() : Object.values(Department)) as string[];
  }, [allStudents]);

  const availableRooms = useMemo<string[]>(() => {
    const rms = Array.from(new Set(allStudents.map(s => s.room)));
    return rms.length > 0 ? rms.sort((a, b) => parseInt(a as string) - parseInt(b as string)) : ['1', '2', '3'];
  }, [allStudents]);

  const [level, setLevel] = useState<string>(availableLevels[0] || '');
  const [dept, setDept] = useState<string>(availableDepts[0] || '');
  const [room, setRoom] = useState<string>(availableRooms[0] || '');

  // Filter subjects based on selected level AND department
  const filteredSubjects = useMemo(() => {
    return subjects.filter(s => s.level === level && s.department === dept);
  }, [subjects, level, dept]);

  const [subjectId, setSubjectId] = useState<string>('');

  // Auto-select subject when filters change to ensure dropdown stays synced
  useEffect(() => {
    if (filteredSubjects.length > 0) {
      if (!filteredSubjects.some(s => s.id === subjectId)) {
        setSubjectId(filteredSubjects[0].id);
      }
    } else {
      setSubjectId('');
    }
  }, [filteredSubjects, subjectId]);

  const [sessionAttendance, setSessionAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);

  useEffect(() => {
    if (!subjectId) {
      setSessionAttendance({});
      setRemarks({});
      return;
    }
    const today = new Date().toISOString().split('T')[0];
    const existing = attendanceRecords.filter(r => r.date === today && r.type === 'SUBJECT' && r.subjectId === subjectId);

    const attMap: Record<string, AttendanceStatus> = {};
    const remMap: Record<string, string> = {};

    existing.forEach(r => {
      attMap[r.studentId] = r.status;
      if (r.remark) remMap[r.studentId] = r.remark;
    });

    setSessionAttendance(attMap);
    setRemarks(remMap);
  }, [level, dept, room, subjectId, attendanceRecords]);

  const filteredStudents = useMemo(() => {
    return allStudents.filter(s => 
      s.level === level && 
      s.department === dept && 
      s.room === room &&
      (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm))
    );
  }, [allStudents, level, dept, room, searchTerm]);

  const historyRecords = useMemo(() => {
    return attendanceRecords.filter(record => {
      const student = allStudents.find(s => s.id === record.studentId);
      return record.type === 'SUBJECT' && 
             record.subjectId === subjectId &&
             student?.level === level && 
             student?.department === dept && 
             student?.room === room;
    }).sort((a, b) => b.date.localeCompare(a.date) || b.timestamp.localeCompare(a.timestamp));
  }, [attendanceRecords, subjectId, level, dept, room, allStudents]);

  const handleStatusChange = (id: string, status: AttendanceStatus) => {
    setSessionAttendance(prev => ({ ...prev, [id]: status }));
    setIsSaved(false);
  };

  const handleSave = () => {
    if (!subjectId) return alert('กรุณาเลือกรายวิชา');

    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    const newRecordsBatch: AttendanceRecord[] = filteredStudents.map(s => ({
      id: `SUBJECT_${today}_${subjectId}_${s.id}`,
      studentId: s.id,
      date: today,
      type: 'SUBJECT',
      subjectId: subjectId,
      status: sessionAttendance[s.id] || 'ABSENT',
      remark: remarks[s.id] || '',
      timestamp: timestamp
    }));

    setAttendanceRecords(prev => {
      const studentIds = filteredStudents.map(s => s.id);
      const otherRecords = prev.filter(r => !(r.date === today && r.type === 'SUBJECT' && r.subjectId === subjectId && studentIds.includes(r.studentId)));
      return [...otherRecords, ...newRecordsBatch];
    });

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setSessionAttendance(prev => ({ ...prev, ...newBatch }));
  };

  const handleSaveSubject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingSubject?.name || !editingSubject?.code || !editingSubject?.level || !editingSubject?.department) return;

    if (editingSubject.id) {
      setSubjects(prev => prev.map(s => s.id === editingSubject.id ? (editingSubject as Subject) : s));
    } else {
      const newSub: Subject = {
        ...(editingSubject as Subject),
        id: `SUB_${Date.now()}`,
        teacherId: currentUser.id
      };
      setSubjects(prev => [...prev, newSub]);
    }
    setEditingSubject(null);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div className="flex bg-white p-2 rounded-[24px] border border-slate-200 shadow-sm w-fit">
          <button onClick={() => setViewMode('checkin')} className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><ClipboardCheck size={20} /> เช็คชื่อ</button>
          <button onClick={() => setViewMode('history')} className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><History size={20} /> ประวัติ</button>
        </div>

        <button 
          onClick={() => {
            setEditingSubject({ level: level, department: dept });
            setShowSubjectModal(true);
          }}
          className="flex items-center gap-2 px-6 py-3.5 bg-white border border-slate-200 rounded-2xl text-slate-600 text-sm font-black hover:bg-slate-50 transition-all shadow-sm font-heading"
        >
          <Settings2 size={18} className="text-blue-600" /> จัดการรายวิชา
        </button>
      </div>

      <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
        <div className="grid grid-cols-1 md:grid-cols-5 gap-6">
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
            <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none">
              {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
            <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none">
              {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ห้องเรียน</label>
            <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none">
              {availableRooms.map(r => <option key={r} value={r}>ห้อง {r}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-blue-600 uppercase tracking-widest ml-1">รายวิชา ({dept})</label>
            <select value={subjectId} onChange={(e) => setSubjectId(e.target.value)} className="w-full bg-slate-50 border border-blue-100 rounded-xl px-4 py-3 font-black text-slate-900 outline-none focus:border-blue-400">
              {filteredSubjects.length > 0 ? filteredSubjects.map(s => <option key={s.id} value={s.id}>{s.code} - {s.name}</option>) : <option value="">(ไม่มีรายวิชาในกลุ่มนี้)</option>}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ค้นหานักเรียน</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อ..." className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-10 pr-4 py-3 font-bold text-slate-900 outline-none text-sm" />
            </div>
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <>
          <div className="flex justify-between items-center px-2">
            <div className="flex gap-3">
              <button onClick={() => markAll('PRESENT')} className="px-5 py-2 bg-green-50 text-green-700 rounded-full text-xs font-black border border-green-200 transition-all hover:bg-green-100">มาทุกคน</button>
              <button onClick={() => markAll('ABSENT')} className="px-5 py-2 bg-red-50 text-red-700 rounded-full text-xs font-black border border-red-200 transition-all hover:bg-red-100">ขาดทุกคน</button>
            </div>
            <button onClick={handleSave} className={`flex items-center gap-3 px-8 py-4 rounded-2xl text-white font-black transition-all shadow-xl ${isSaved ? 'bg-green-600' : 'bg-slate-900 hover:bg-black active:scale-95'}`}>
              {isSaved ? <CheckCircle2 size={22} /> : <Save size={22} />}
              <span>{isSaved ? 'บันทึกแล้ว' : 'บันทึกข้อมูลวันนี้'}</span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {filteredStudents.map((student, index) => (
              <div key={student.id} className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col justify-between hover:border-blue-300 transition-all group">
                <div className="flex justify-between items-start gap-4">
                  <div className="flex items-start gap-4">
                    <div className="w-12 h-12 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-white shrink-0 group-hover:bg-blue-600 transition-colors">{index + 1}</div>
                    <div>
                      <h4 className="font-black text-slate-900 text-lg leading-tight">{student.name}</h4>
                      <p className="text-[10px] text-slate-500 font-bold uppercase mt-1 tracking-widest">รหัส: {student.studentId}</p>
                    </div>
                  </div>
                  <div className="grid grid-cols-5 gap-1.5">
                    {Object.entries(STATUS_LABELS).map(([key, value]) => (
                      <button key={key} onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} className={`flex flex-col items-center gap-1 p-2 rounded-xl border-2 transition-all ${sessionAttendance[student.id] === key ? value.color + ' border-current shadow-sm' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-200'}`}>
                        <div className="scale-110">{value.icon}</div>
                        <span className="text-[8px] font-black uppercase text-center">{value.label}</span>
                      </button>
                    ))}
                  </div>
                </div>
                {sessionAttendance[student.id] && sessionAttendance[student.id] !== 'PRESENT' && (
                  <div className="mt-4 relative">
                    <MessageSquare className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                    <input type="text" value={remarks[student.id] || ''} onChange={(e) => setRemarks(prev => ({ ...prev, [student.id]: e.target.value }))} placeholder="ระบุหมายเหตุ..." className="w-full bg-slate-50 border border-slate-100 rounded-xl pl-9 pr-4 py-2 text-xs font-bold outline-none focus:border-blue-400 transition-all" />
                  </div>
                )}
              </div>
            ))}
            {filteredStudents.length === 0 && (
              <div className="col-span-full py-20 text-center bg-white rounded-[32px] border-2 border-dashed border-slate-100 text-slate-300">
                <Users size={48} className="mx-auto mb-4 opacity-10" />
                <p className="text-sm font-black uppercase tracking-widest">ไม่พบรายชื่อนักเรียนในกลุ่มนี้</p>
              </div>
            )}
            {filteredStudents.length > 0 && !subjectId && (
              <div className="col-span-full py-20 text-center bg-white rounded-[32px] border-2 border-dashed border-red-100 text-red-400">
                <AlertCircle size={48} className="mx-auto mb-4 opacity-10" />
                <p className="text-sm font-black uppercase tracking-widest">กรุณาเลือกหรือเพิ่มรายวิชาสำหรับ {level} แผนก {dept}</p>
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 border-b">
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">วันที่</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">นักเรียน</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">สถานะ</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-500 uppercase tracking-widest">วิชา</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {historyRecords.length > 0 ? historyRecords.map((record) => {
                const student = allStudents.find(s => s.id === record.studentId);
                const subj = subjects.find(s => s.id === record.subjectId);
                return (
                  <tr key={record.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4 font-bold text-slate-900 text-sm whitespace-nowrap">{record.date}</td>
                    <td className="px-6 py-4">
                      <p className="font-black text-slate-900 text-sm">{student?.name}</p>
                      <p className="text-[10px] text-slate-500 font-bold">{student?.studentId}</p>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-3 py-1 rounded-full text-[10px] font-black border flex items-center gap-2 w-fit ${STATUS_LABELS[record.status].color}`}>
                        {STATUS_LABELS[record.status].label}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-xs font-bold text-slate-500">{subj?.code}</td>
                  </tr>
                );
              }) : (
                <tr>
                  <td colSpan={4} className="py-20 text-center text-slate-300">
                    <History size={48} className="mx-auto mb-4 opacity-10" />
                    <p className="text-xs font-black uppercase tracking-widest">ยังไม่มีประวัติการเช็คชื่อในรายวิชานี้</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Subject Management Modal */}
      {showSubjectModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-md overflow-y-auto">
          <div className="bg-white w-full max-w-4xl rounded-[48px] p-8 md:p-12 shadow-2xl animate-in zoom-in-95 duration-300 relative my-8">
            <button onClick={() => { setShowSubjectModal(false); setEditingSubject(null); }} className="absolute top-10 right-10 text-slate-400 hover:text-slate-900 transition-colors">
              <X size={28} />
            </button>
            <h3 className="text-2xl font-black text-slate-900 mb-8 uppercase tracking-tight font-heading flex items-center gap-3">
              <BookOpen size={28} className="text-blue-600" /> จัดการรายวิชาเช็คชื่อ
            </h3>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              <div className="space-y-6">
                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">{editingSubject?.id ? 'แก้ไขรายวิชา' : 'เพิ่มรายวิชาใหม่'}</h4>
                <form onSubmit={handleSaveSubject} className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-bold text-slate-400 ml-1">รหัสวิชา</label>
                      <input 
                        type="text" 
                        required 
                        value={editingSubject?.code || ''} 
                        onChange={(e) => setEditingSubject(prev => ({ ...prev, code: e.target.value }))}
                        className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-3 font-bold outline-none transition-all" 
                        placeholder="เช่น IT30201"
                      />
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-bold text-slate-400 ml-1">ชื่อวิชา</label>
                      <input 
                        type="text" 
                        required 
                        value={editingSubject?.name || ''} 
                        onChange={(e) => setEditingSubject(prev => ({ ...prev, name: e.target.value }))}
                        className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-3 font-bold outline-none transition-all" 
                        placeholder="เช่น ภาษาอังกฤษ"
                      />
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-bold text-slate-400 ml-1">ระดับชั้น</label>
                      <select 
                        value={editingSubject?.level || ''} 
                        onChange={(e) => setEditingSubject(prev => ({ ...prev, level: e.target.value }))}
                        className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-3 font-bold outline-none cursor-pointer"
                      >
                        <option value="">เลือกสีมารถ...</option>
                        {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
                      </select>
                    </div>
                    <div className="space-y-1.5">
                      <label className="text-[10px] font-bold text-slate-400 ml-1">แผนกวิชา</label>
                      <select 
                        value={editingSubject?.department || ''} 
                        onChange={(e) => setEditingSubject(prev => ({ ...prev, department: e.target.value }))}
                        className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-3 font-bold outline-none cursor-pointer"
                      >
                        <option value="">เลือกแผนก...</option>
                        {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
                      </select>
                    </div>
                  </div>

                  <div className="flex gap-3 pt-2">
                    {editingSubject?.id && (
                      <button type="button" onClick={() => setEditingSubject(null)} className="flex-1 py-3 bg-slate-100 text-slate-600 rounded-xl font-black text-[10px] uppercase tracking-widest">ยกเลิก</button>
                    )}
                    <button type="submit" className="flex-1 py-3 bg-blue-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-blue-100">
                      {editingSubject?.id ? 'บันทึกการแก้ไข' : 'เพิ่มรายวิชา'}
                    </button>
                  </div>
                </form>
              </div>

              <div className="space-y-6">
                <div className="flex items-center justify-between ml-1">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">รายวิชาทั้งหมด ({subjects.length})</h4>
                </div>
                <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 scrollbar-hide">
                  {subjects.sort((a,b) => a.level.localeCompare(b.level)).map(s => {
                    const isMatched = s.level === level && s.department === dept;
                    return (
                      <div key={s.id} className={`flex items-center justify-between p-4 rounded-2xl border-2 transition-all group ${isMatched ? 'bg-blue-50 border-blue-100' : 'bg-slate-50 border-slate-100'}`}>
                        <div className="min-w-0 text-left">
                          <p className="font-black text-sm text-slate-900 truncate">{s.name}</p>
                          <div className="flex items-center gap-2 mt-1">
                            <span className="text-[9px] font-black text-slate-500 bg-white px-2 py-0.5 rounded border border-slate-100 uppercase">{s.code}</span>
                            <span className={`text-[9px] font-black px-2 py-0.5 rounded border uppercase ${isMatched ? 'bg-blue-600 text-white border-blue-600' : 'bg-slate-200 text-slate-600 border-slate-200'}`}>{s.level}</span>
                            <span className="text-[9px] font-bold text-slate-400 truncate">{s.department}</span>
                          </div>
                        </div>
                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => setEditingSubject(s)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-white rounded-lg transition-all"><Edit3 size={16} /></button>
                          <button onClick={() => setSubjects(prev => prev.filter(i => i.id !== s.id))} className="p-2 text-slate-400 hover:text-red-600 hover:bg-white rounded-lg transition-all"><Trash2 size={16} /></button>
                        </div>
                      </div>
                    );
                  })}
                  {subjects.length === 0 && (
                    <div className="py-20 text-center text-slate-300 italic text-xs">ยังไม่มีข้อมูลรายวิชา</div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ClassAttendance;

import React, { useState, useEffect, useMemo } from 'react';
import { Student, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { 
  Search, Save, CheckCircle2, History, ClipboardCheck, 
  MessageSquare, Share2, Calendar, X
} from 'lucide-react';

interface MorningAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
}

const MorningAttendance: React.FC<MorningAttendanceProps> = ({ 
  students, 
  attendanceRecords, 
  setAttendanceRecords
}) => {
  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level as string))).sort((a, b) => (a as string).localeCompare(b as string)), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department as string))).sort((a, b) => (a as string).localeCompare(b as string)), [students]);
  const availableRooms = useMemo(() => Array.from(new Set(students.map(s => s.room as string))).sort((a, b) => parseInt(a as string) - parseInt(b as string)), [students]);

  const [level, setLevel] = useState<string>(availableLevels[0] || '');
  const [dept, setDept] = useState<string>(availableDepts[0] || '');
  const [room, setRoom] = useState<string>(availableRooms[0] || '');

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedHistoryDate, setSelectedHistoryDate] = useState<string>('');
  const [currentSession, setCurrentSession] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaved, setIsSaved] = useState(false);
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');

  const todayStr = new Date().toLocaleDateString('th-TH', { 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
  });

  useEffect(() => {
    const rawDate = new Date().toISOString().split('T')[0];
    const todayRecords = attendanceRecords.filter(r => r.date === rawDate && r.type === 'MORNING');
    const sessionMap: Record<string, AttendanceStatus> = {};
    const remarkMap: Record<string, string> = {};

    todayRecords.forEach(r => {
      sessionMap[r.studentId] = r.status;
      if (r.remark) remarkMap[r.studentId] = r.remark;
    });

    setCurrentSession(sessionMap);
    setRemarks(remarkMap);
  }, [level, dept, room, attendanceRecords]);

  const filteredStudents = students.filter(s => 
    s.level === level && s.department === dept && s.room === room &&
    (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm))
  );

  const historyRecords = useMemo(() => {
    return attendanceRecords.filter(record => {
      const student = students.find(s => s.id === record.studentId);
      const matchesFilter = record.type === 'MORNING' && student?.level === level && student?.department === dept && student?.room === room;
      const matchesDate = selectedHistoryDate ? record.date === selectedHistoryDate : true;
      return matchesFilter && matchesDate;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [attendanceRecords, students, level, dept, room, selectedHistoryDate]);

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setCurrentSession(prev => ({ ...prev, [studentId]: status }));
    setIsSaved(false);
  };

  const handleSave = () => {
    const rawDate = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    const newRecordsBatch: AttendanceRecord[] = filteredStudents.map(s => ({
      id: `MORNING_${rawDate}_${s.id}`,
      studentId: s.id,
      date: rawDate,
      type: 'MORNING',
      status: currentSession[s.id] || 'ABSENT',
      remark: remarks[s.id] || '',
      timestamp: timestamp
    }));

    setAttendanceRecords(prev => {
      const studentIds = filteredStudents.map(s => s.id);
      const otherRecords = prev.filter(r => !(r.date === rawDate && r.type === 'MORNING' && studentIds.includes(r.studentId)));
      return [...otherRecords, ...newRecordsBatch];
    });

    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
