};

export default ClassAttendance;

import React, { useState } from 'react';
import { Student, BehaviorRecord } from '../types';
import { Award, PlusCircle, MinusCircle, FileText, Search, AlertCircle, Trash2, X, AlertTriangle, Check, RotateCcw } from 'lucide-react';

interface BehaviorSystemProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  behaviorRecords: BehaviorRecord[];
  setBehaviorRecords: React.Dispatch<React.SetStateAction<BehaviorRecord[]>>;
}

const BehaviorSystem: React.FC<BehaviorSystemProps> = ({ students, setStudents, behaviorRecords, setBehaviorRecords }) => {
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(null);
  const [scoreChange, setScoreChange] = useState<number>(5);
  const [reason, setReason] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [confirmingDeleteId, setConfirmingDeleteId] = useState<string | null>(null);

  const selectedStudent = students.find(s => s.id === selectedStudentId);
  const filteredStudents = students.filter(s => s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm));

  const handleScoreUpdate = (type: 'ADD' | 'DEDUCT') => {
    if (!selectedStudent || !reason.trim()) return;

    const change = type === 'ADD' ? scoreChange : -scoreChange;
    const newScore = Math.min(100, Math.max(0, selectedStudent.behaviorScore + change));

    // Update Student Score
    setStudents(prev => prev.map(s => 
      s.id === selectedStudentId ? { ...s, behaviorScore: newScore } : s
    ));

    // Add History Record
    const newRecord: BehaviorRecord = {
      id: `BEH_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      studentId: selectedStudent.id,
      type,
      score: scoreChange,
      reason,
      date: new Date().toLocaleDateString('th-TH'),
      recordedBy: 'อาจารย์ผู้สอน'
    };

    setBehaviorRecords(prev => [newRecord, ...prev]);
    setReason('');
  };

  const processDeleteBehavior = (id: string) => {
    const record = behaviorRecords.find(b => b.id === id);
    if (!record) return;

    // Revert the score on the student
    setStudents(prev => prev.map(s => {
      if (s.id === record.studentId) {
        const adjustment = record.type === 'ADD' ? -record.score : record.score;
        return { ...s, behaviorScore: Math.min(100, Math.max(0, s.behaviorScore + adjustment)) };
      }
      return s;
    }));

    // Remove the record
    setBehaviorRecords(prev => prev.filter(b => b.id !== id));
    setConfirmingDeleteId(null);
  };

  const getScoreStatus = (score: number) => {
    if (score >= 90) return { label: 'ดีมาก', color: 'bg-green-100 text-green-800' };
    if (score >= 70) return { label: 'ดี', color: 'bg-blue-100 text-blue-800' };
    return { label: 'เฝ้าระวัง', color: 'bg-red-100 text-red-800' };
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in duration-500">
      <div className="bg-white rounded-[32px] border border-slate-200 shadow-sm flex flex-col h-[calc(100vh-200px)] overflow-hidden">
        <div className="p-5 border-b bg-slate-50/50">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="ค้นหานักเรียน..." 
              value={searchTerm} 
              onChange={(e) => setSearchTerm(e.target.value)} 
              className="w-full bg-white border-2 border-slate-100 rounded-2xl pl-11 pr-4 py-3 font-black text-slate-900 outline-none focus:border-blue-500 transition-all text-sm" 
            />
          </div>
        </div>
        <div className="flex-1 overflow-y-auto p-3 space-y-2 scrollbar-hide">
          {filteredStudents.map(student => (
            <button 
              key={student.id} 
              onClick={() => setSelectedStudentId(student.id)} 
              className={`w-full text-left p-5 rounded-[24px] border-2 transition-all ${selectedStudentId === student.id ? 'bg-slate-900 border-slate-900 text-white shadow-xl scale-[1.02]' : 'bg-white border-transparent hover:bg-slate-50 text-slate-900'}`}
            >
              <div className="flex justify-between items-center">
                <div>
                  <p className="font-black text-sm">{student.name}</p>
                  <p className={`text-[10px] font-bold uppercase mt-1 tracking-widest ${selectedStudentId === student.id ? 'text-slate-400' : 'text-slate-500'}`}>รหัส: {student.studentId}</p>
                </div>
                <div className={`px-3 py-1 rounded-xl text-xs font-black shadow-sm ${selectedStudentId === student.id ? 'bg-white text-slate-900' : getScoreStatus(student.behaviorScore).color}`}>
                  {student.behaviorScore}
                </div>
              </div>
            </button>
          ))}
        </div>
      </div>

      <div className="lg:col-span-2 space-y-6">
        {selectedStudent ? (
          <>
            <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm relative overflow-hidden">
              <div className="absolute top-0 right-0 p-10 opacity-5 pointer-events-none text-blue-600">
                <Award size={150} />
              </div>
              <div className="flex items-center justify-between mb-8 relative z-10">
                <div className="flex items-center gap-6">
                  <div className="w-20 h-20 bg-blue-600 rounded-[28px] flex items-center justify-center text-white shadow-2xl shadow-blue-100">
                    <Award size={40} />
                  </div>
                  <div>
                    <h3 className="text-3xl font-black text-slate-900 tracking-tight">{selectedStudent.name}</h3>
                    <p className="text-slate-500 font-bold uppercase text-xs tracking-widest mt-1">{selectedStudent.level} • {selectedStudent.department}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">คะแนนปัจจุบัน</p>
                  <p className={`text-6xl font-black ${selectedStudent.behaviorScore >= 70 ? 'text-blue-600' : 'text-red-600'}`}>{selectedStudent.behaviorScore}</p>
                </div>
              </div>

              <div className="p-6 bg-slate-50 rounded-[32px] border-2 border-slate-100 space-y-5">
                <h4 className="font-black text-slate-900 flex items-center gap-2 text-sm uppercase tracking-widest">
                  <PlusCircle size={18} className="text-green-600" /> ปรับปรุงคะแนนพฤติกรรม
                </h4>
                <div className="grid grid-cols-1 md:grid-cols-12 gap-4">
                  <div className="md:col-span-6">
                    <input 
                      type="text" 
                      placeholder="ระบุเหตุผลในการปรับคะแนน..." 
                      value={reason} 
                      onChange={(e) => setReason(e.target.value)} 
                      className="w-full bg-white border-2 border-transparent focus:border-blue-500 rounded-2xl px-5 py-3.5 font-bold text-slate-900 outline-none transition-all shadow-inner" 
                    />
                  </div>
                  <div className="md:col-span-2">
                    <input 
                      type="number" 
                      value={scoreChange} 
                      onChange={(e) => setScoreChange(parseInt(e.target.value) || 0)} 
                      className="w-full bg-white border-2 border-transparent focus:border-blue-500 rounded-2xl px-5 py-3.5 font-black text-slate-900 outline-none text-center shadow-inner" 
                    />
                  </div>
                  <div className="md:col-span-4 flex gap-3">
                    <button onClick={() => handleScoreUpdate('ADD')} className="flex-1 bg-green-600 text-white font-black rounded-2xl hover:bg-green-700 transition-all shadow-lg shadow-green-100 active:scale-95 text-xs uppercase tracking-widest">บวกคะแนน</button>
                    <button onClick={() => handleScoreUpdate('DEDUCT')} className="flex-1 bg-red-600 text-white font-black rounded-2xl hover:bg-red-700 transition-all shadow-lg shadow-red-100 active:scale-95 text-xs uppercase tracking-widest">หักคะแนน</button>
                  </div>
                </div>
              </div>
            </div>

            <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
              <h3 className="font-black text-slate-900 flex items-center gap-3 text-xl mb-8">
                <FileText size={24} className="text-blue-600" /> ประวัติการปรับปรุงคะแนน
              </h3>
              <div className="space-y-4">
                {behaviorRecords.filter(b => b.studentId === selectedStudent.id).map(record => {
                  const isConfirming = confirmingDeleteId === record.id;
                  return (
                    <div key={record.id} className={`flex items-center justify-between p-6 rounded-[28px] border-2 transition-all relative overflow-hidden ${isConfirming ? 'bg-red-50 border-red-500 ring-2 ring-red-200' : 'bg-white border-slate-50 hover:border-slate-200'}`}>
                      <div className="flex gap-5 items-center relative z-10">
                        <div className={`w-12 h-12 rounded-[18px] flex items-center justify-center shadow-inner shrink-0 ${record.type === 'ADD' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                          {record.type === 'ADD' ? <PlusCircle size={22} /> : <MinusCircle size={22} />}
                        </div>
                        <div>
                          <p className={`font-black leading-tight ${isConfirming ? 'text-red-900' : 'text-slate-900'}`}>{record.reason}</p>
                          <div className="flex items-center gap-3 mt-1.5">
                             <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{record.date}</span>
                             <span className="text-slate-200">•</span>
                             <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">โดย: {record.recordedBy}</span>
                          </div>
                        </div>
                      </div>

                      <div className="flex items-center gap-6 relative z-10">
                        <div className={`text-2xl font-black ${record.type === 'ADD' ? 'text-green-600' : 'text-red-600'}`}>
                          {record.type === 'ADD' ? '+' : '-'}{record.score}
                        </div>

                        <div className="flex items-center gap-2">
                          {isConfirming ? (
                            <div className="flex items-center gap-2 animate-in slide-in-from-right-2 duration-300">
                               <button 
                                onClick={(e) => { e.preventDefault(); e.stopPropagation(); setConfirmingDeleteId(null); }}
                                className="flex items-center gap-2 px-4 py-2.5 bg-slate-200 text-slate-700 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-slate-300 transition-all"
                              >
                                <X size={14} /> ยกเลิก
                              </button>
                              <button 
                                onClick={(e) => { e.preventDefault(); e.stopPropagation(); processDeleteBehavior(record.id); }}
                                className="flex items-center gap-2 px-5 py-2.5 bg-red-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-red-700 transition-all shadow-lg"
                              >
                                <Check size={14} /> ยืนยันลบ
                              </button>
                            </div>
                          ) : (
                            <button 
                              type="button"
                              onClick={(e) => {
                                e.preventDefault();
                                e.stopPropagation();
                                setConfirmingDeleteId(record.id);
                                setTimeout(() => setConfirmingDeleteId(prev => prev === record.id ? null : prev), 5000);
                              }}
                              className="p-3 text-slate-300 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all"
                              title="ลบรายการนี้"
                            >
                              <Trash2 size={22} />
                            </button>
                          )}
                        </div>
                      </div>
                    </div>
                  );
                })}
                {behaviorRecords.filter(b => b.studentId === selectedStudent.id).length === 0 && (
                  <div className="py-20 text-center flex flex-col items-center justify-center text-slate-300 border-2 border-dashed border-slate-100 rounded-[32px]">
                     <Award size={64} className="mb-4 opacity-5" />
                     <p className="text-sm font-black uppercase tracking-widest">ยังไม่มีประวัติพฤติกรรม</p>
                  </div>
                )}
              </div>
            </div>
          </>
        ) : (
          <div className="h-full bg-white rounded-[40px] border-4 border-dashed border-slate-100 flex flex-col items-center justify-center p-20 text-center">
            <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center text-slate-200 mb-8">
               <AlertCircle size={48} />
            </div>
            <h3 className="text-3xl font-black text-slate-900 mb-2 uppercase tracking-tight">เลือกรายชื่อนักเรียน</h3>
            <p className="text-slate-400 font-bold max-w-xs mx-auto">กรุณาเลือกนักเรียนจากรายการด้านซ้ายเพื่อจัดการคะแนนพฤติกรรมและดูประวัติย้อนหลัง</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default BehaviorSystem;

import React, { useState, useRef, useMemo } from 'react';
import { User, UserRole, Department, Student } from '../types';
import * as XLSX from 'https://esm.sh/xlsx';
import { 
  UserPlus, Shield, Trash2, Edit3, X, Search, FileSpreadsheet, 
  Upload, Download, Key, UserX, Users, UserCircle, CheckCircle2, AlertCircle, Info, Check
} from 'lucide-react';

interface UserManagementProps {
  users: User[];
  setUsers: React.Dispatch<React.SetStateAction<User[]>>;
  currentUser?: User;
  students?: Student[]; 
}

const UserManagement: React.FC<UserManagementProps> = ({ users, setUsers, currentUser, students = [] }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [activeTab, setActiveTab] = useState<'TEACHER' | 'PARENT' | 'ADMIN'>('TEACHER');
  const [showModal, setShowModal] = useState<'ADD' | 'EDIT' | null>(null);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [isImporting, setIsImporting] = useState(false);
  const [importStatus, setImportStatus] = useState<null | { type: 'success' | 'error', message: string }>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const availableDepts = useMemo(() => {
    const depts = new Set(students.map(s => s.department));
    Object.values(Department).forEach(d => depts.add(d));
    return Array.from(depts).sort();
  }, [students]);

  const [formData, setFormData] = useState<Partial<User>>({
    name: '',
    role: 'TEACHER',
    department: availableDepts[0] || '',
    studentId: '',
    username: '',
    password: ''
  });

  const filteredUsers = users.filter(u => 
    u.role === activeTab &&
    (u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
     u.username.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const resetForm = () => {
    setFormData({ 
      name: '', 
      role: activeTab as UserRole, 
      department: availableDepts[0] || '', 
      studentId: '', 
      username: '', 
      password: '' 
    });
    setEditingUserId(null);
  };

  const handleOpenEdit = (user: User) => {
    setFormData({ ...user });
    setEditingUserId(user.id);
    setShowModal('EDIT');
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (showModal === 'ADD') {
      const newUser = { id: `USR_${Date.now()}`, ...formData } as User;
      setUsers(prev => [...prev, newUser]);
    } else if (showModal === 'EDIT' && editingUserId) {
      setUsers(prev => prev.map(u => u.id === editingUserId ? { ...u, ...formData } as User : u));
    }
    setShowModal(null);
    resetForm();
  };

  const processDeleteUser = (id: string) => {
    if (currentUser && id === currentUser.id) {
      alert('ไม่สามารถลบบัญชีที่คุณกำลังใช้งานได้');
      setConfirmDeleteId(null);
      return;
    }
    setUsers(prev => prev.filter(u => u.id !== id));
    setConfirmDeleteId(null);
  };

  const downloadTemplate = () => {
    const teacherData = [
      { name: "ชื่อ-นามสกุล ครู", username: "teacher_id", password: "password123", department: "แผนกวิชา" }
    ];
    const parentData = [
      { name: "ชื่อ-นามสกุล ผู้ปกครอง", username: "parent_id", password: "password123", studentId: "รหัสนักเรียน (รหัส 6 หลัก)" }
    ];

    const wb = XLSX.utils.book_new();
    const wsTeacher = XLSX.utils.json_to_sheet(teacherData);
    const wsParent = XLSX.utils.json_to_sheet(parentData);

    XLSX.utils.book_append_sheet(wb, wsTeacher, "Template_Teacher");
    XLSX.utils.book_append_sheet(wb, wsParent, "Template_Parent");
    XLSX.writeFile(wb, "user_import_template.xlsx");
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    setImportStatus(null);

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const data = event.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const sheetName = activeTab === 'TEACHER' ? 'Template_Teacher' : 'Template_Parent';
        const worksheet = workbook.Sheets[sheetName] || workbook.Sheets[workbook.SheetNames[0]];
        const json: any[] = XLSX.utils.sheet_to_json(worksheet);

        const newUsers: User[] = json.map((row, i) => ({
          id: `USR_IMP_${Date.now()}_${i}`,
          name: String(row.name || row['ชื่อ-นามสกุล'] || '').trim(),
          username: String(row.username || row['ชื่อผู้ใช้'] || '').trim(),
          password: String(row.password || row['รหัสผ่าน'] || '1234').trim(),
          role: activeTab as UserRole,
          department: activeTab === 'TEACHER' ? String(row.department || row['แผนกวิชา'] || '').trim() : undefined,
          studentId: activeTab === 'PARENT' ? String(row.studentId || row['รหัสนักเรียน'] || '').trim() : undefined,
        })).filter(u => u.name && u.username);

        if (newUsers.length > 0) {
          setUsers(prev => [...prev, ...newUsers]);
          setImportStatus({ type: 'success', message: `นำเข้าข้อมูลสำเร็จ ${newUsers.length} รายการ` });
        } else {
          setImportStatus({ type: 'error', message: 'ไม่พบข้อมูลที่ถูกต้อง กรุณาตรวจสอบหัวตารางในไฟล์' });
        }
      } catch (err) {
        setImportStatus({ type: 'error', message: 'เกิดข้อผิดพลาดในการอ่านไฟล์' });
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex items-center gap-5 mb-8">
            <div className="p-4 bg-indigo-600 rounded-[24px] text-white shadow-xl shadow-indigo-100">
              <FileSpreadsheet size={28} />
            </div>
            <div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight font-heading">นำเข้าผู้ใช้งานแบบกลุ่ม</h3>
              <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">เพิ่มข้อมูล{activeTab === 'TEACHER' ? 'ครู' : 'ผู้ปกครอง'}ผ่านไฟล์ Excel</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div 
              onClick={() => fileInputRef.current?.click()} 
              className={`p-10 rounded-[32px] border-4 border-dashed flex flex-col items-center justify-center cursor-pointer transition-all group ${isImporting ? 'bg-slate-50 border-slate-200 opacity-50' : 'bg-slate-50 border-slate-100 hover:border-indigo-400 hover:bg-indigo-50'}`}
            >
              <input type="file" ref={fileInputRef} className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} disabled={isImporting} />
              <div className="p-5 bg-white rounded-2xl shadow-sm mb-4 group-hover:scale-110 transition-transform">
                {isImporting ? <div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin" /> : <Upload size={32} className="text-indigo-600" />}
              </div>
              <p className="font-black text-slate-900 text-center text-sm">{isImporting ? 'กำลังประมวลผลไฟล์...' : `อัปโหลดไฟล์สำหรับ ${activeTab === 'TEACHER' ? 'ครู' : 'ผู้ปกครอง'}`}</p>
            </div>
            <div className="flex flex-col justify-center gap-4">
              <button onClick={downloadTemplate} className="flex items-center justify-center gap-3 py-5 bg-slate-900 text-white rounded-[24px] font-black hover:bg-black transition-all shadow-xl">
                <Download size={20} /> ดาวน์โหลดเทมเพลต (xlsx)
              </button>
              <div className="p-5 bg-indigo-50 rounded-[24px] border border-indigo-100">
                <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest mb-1 flex items-center gap-2">
                  <Info size={12} /> ข้อมูลที่ต้องระบุ
                </p>
                <p className="text-[10px] text-indigo-800 font-bold leading-relaxed">
                  {activeTab === 'TEACHER' ? 'name, username, password, department' : 'name, username, password, studentId'}
                </p>
              </div>
            </div>
          </div>
          {importStatus && (
            <div className={`mt-6 p-4 rounded-2xl flex items-center gap-4 border-2 animate-in slide-in-from-top-4 ${importStatus.type === 'success' ? 'bg-green-50 border-green-100 text-green-700' : 'bg-red-50 border-red-100 text-red-700'}`}>
              {importStatus.type === 'success' ? <CheckCircle2 size={20} /> : <AlertCircle size={20} />}
              <p className="font-black text-xs">{importStatus.message}</p>
            </div>
          )}
        </div>

        <div className="bg-indigo-900 p-10 rounded-[40px] shadow-2xl relative overflow-hidden flex flex-col justify-between">
           <div className="absolute top-0 right-0 p-12 opacity-10 pointer-events-none text-white">
              <Shield size={180} />
           </div>
           <div className="relative z-10">
              <h4 className="text-xs font-black text-indigo-300 uppercase tracking-[0.3em] mb-8 font-heading">สรุปสิทธิ์ผู้ใช้งาน</h4>
              <div className="grid grid-cols-2 gap-4">
                 <div className="bg-white/5 p-5 rounded-3xl border border-white/10">
                    <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">แอดมิน</p>
                    <p className="text-3xl font-black text-white">{users.filter(u => u.role === 'ADMIN').length}</p>
                 </div>
                 <div className="bg-white/5 p-5 rounded-3xl border border-white/10">
                    <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">ครู</p>
                    <p className="text-3xl font-black text-white">{users.filter(u => u.role === 'TEACHER').length}</p>
                 </div>
                 <div className="bg-white/5 p-5 rounded-3xl border border-white/10 col-span-2">
                    <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">ผู้ปกครอง</p>
                    <p className="text-3xl font-black text-white">{users.filter(u => u.role === 'PARENT').length}</p>
                 </div>
              </div>
           </div>
        </div>
      </div>

      <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-8 bg-slate-50/50 border-b flex flex-col lg:flex-row items-center justify-between gap-6">
          <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit shrink-0">
            <button onClick={() => { setActiveTab('TEACHER'); setConfirmDeleteId(null); }} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-xs font-black transition-all font-heading ${activeTab === 'TEACHER' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
              <Users size={16} /> อาจารย์
            </button>
            <button onClick={() => { setActiveTab('PARENT'); setConfirmDeleteId(null); }} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-xs font-black transition-all font-heading ${activeTab === 'PARENT' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
              <UserCircle size={16} /> ผู้ปกครอง
            </button>
            <button onClick={() => { setActiveTab('ADMIN'); setConfirmDeleteId(null); }} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-xs font-black transition-all font-heading ${activeTab === 'ADMIN' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}>
              <Shield size={16} /> แอดมิน
            </button>
          </div>
          <div className="flex items-center gap-4 w-full lg:w-auto">
            <div className="relative flex-1 lg:w-80">
              <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
              <input type="text" placeholder="ค้นหาชื่อ หรือ Username..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-white border-2 border-slate-100 rounded-2xl pl-14 pr-6 py-4 text-sm font-bold text-slate-900 outline-none focus:border-indigo-500 transition-all shadow-inner" />
            </div>
            <button onClick={() => { resetForm(); setShowModal('ADD'); }} className="px-8 py-4 bg-indigo-600 text-white rounded-2xl text-sm font-black flex items-center gap-3 shadow-xl hover:bg-indigo-700 transition-all font-heading uppercase tracking-widest">
              <UserPlus size={20} /> เพิ่มผู้ใช้
            </button>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-white border-b">
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">ข้อมูลพื้นฐาน</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">ชื่อผู้ใช้ / รหัสผ่าน</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest">{activeTab === 'PARENT' ? 'รหัสนักเรียน' : 'แผนกวิชา'}</th>
                <th className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">จัดการ</th>
              </tr>
            </thead>
