                  <td colSpan={4} className="py-32 text-center">
                    <UserX size={64} className="mx-auto text-slate-100 mb-6" />
                    <p className="font-black text-slate-900 text-xl font-heading">ไม่พบรายชื่อ{activeTab === 'TEACHER' ? 'ครู' : 'ผู้ปกครอง'}</p>
                    <p className="text-slate-400 text-sm mt-1">ลองเปลี่ยนคำค้นหา หรือนำเข้าข้อมูลใหม่</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {showModal && (
