            <h3 className="text-2xl font-black text-slate-900 mb-10 uppercase tracking-tight font-heading text-center">
              {showModal === 'ADD' ? `เพิ่ม ${activeTab === 'TEACHER' ? 'อาจารย์' : 'ผู้ปกครอง'}` : 'แก้ไขข้อมูลผู้ใช้'}
            </h3>
            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ชื่อ-นามสกุล</label>
                <input type="text" required value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})} className="w-full bg-slate-50 border-2 border-slate-100 focus:border-indigo-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none transition-all" />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">Username</label>
