          <div className="lg:col-span-2 bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase">
                <tr>
                  <th className="px-8 py-5">ระดับ / แผนก</th>
                  <th className="px-8 py-5 text-right">ยอดเงิน</th>
                  <th className="px-8 py-5 text-right">จัดการ</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {tuitionConfigs.map(c => {
                  const isConfirming = confirmDeleteId === c.id;
                  return (
                    <tr key={c.id} className={`hover:bg-slate-50/50 transition-colors ${isConfirming ? 'bg-red-50' : ''}`}>
                      <td className="px-8 py-5">
                        <p className={`font-black ${isConfirming ? 'text-red-900' : 'text-slate-900'}`}>{c.level}</p>
                        <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{c.department}</p>
                      </td>
                      <td className={`px-8 py-5 text-right font-black text-lg ${isConfirming ? 'text-red-600' : 'text-[#00AEEF]'}`}>
                        {c.amount.toLocaleString()} ฿
                      </td>
                      <td className="px-8 py-5 text-right">
                        {isConfirming ? (
                          <div className="flex justify-end gap-2 animate-in slide-in-from-right-2">
                            <button onClick={() => setConfirmDeleteId(null)} className="p-2 bg-slate-200 text-slate-600 rounded-lg hover:bg-slate-300 transition-all"><X size={16} /></button>
                            <button onClick={() => processDeleteConfig(c.id)} className="p-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-all text-[10px] font-black uppercase">ลบ</button>
                          </div>
                        ) : (
                          <button onClick={() => setConfirmDeleteId(c.id)} className="p-2 text-slate-300 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"><Trash2 size={18} /></button>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'payment' && (
