                <Search className="text-slate-400" size={18} />
                <input type="text" placeholder="ค้นหาชื่อ หรือ รหัสนักเรียน..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-transparent font-bold outline-none text-sm" />
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-2">
                {filteredStudents.map(s => (
                  <button key={s.id} onClick={() => setSelectedStudentId(s.id)} className={`w-full text-left p-4 rounded-[20px] border-2 transition-all ${selectedStudentId === s.id ? 'bg-[#00AEEF] border-[#00AEEF] text-white shadow-lg scale-[1.02]' : 'bg-white border-transparent hover:bg-slate-50 text-slate-900'}`}>
                    <p className="font-black text-sm">{s.name}</p>
                    <p className={`text-[10px] font-bold uppercase tracking-widest mt-0.5 ${selectedStudentId === s.id ? 'text-sky-100 opacity-80' : 'text-slate-400'}`}>{s.studentId}</p>
                  </button>
                ))}
              </div>
           </div>
           <div className="lg:col-span-2">
             {selectedStudentId ? (
               <div className="bg-white p-10 rounded-[40px] border border-slate-200 shadow-sm space-y-10 animate-in slide-in-from-right-4">
