import React, { useState, useEffect, useMemo } from 'react';
import { Student, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { 
  Search, Save, CheckCircle2, History, ClipboardCheck, 
  MessageSquare, Share2, Calendar, X, Loader2
} from 'lucide-react';

interface MorningAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
}

const MorningAttendance: React.FC<MorningAttendanceProps> = ({ 
  students, 
  attendanceRecords, 
  setAttendanceRecords
}) => {
  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level as string))).sort((a, b) => (a as string).localeCompare(b as string)), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department as string))).sort((a, b) => (a as string).localeCompare(b as string)), [students]);
  const availableRooms = useMemo(() => Array.from(new Set(students.map(s => s.room as string))).sort((a, b) => parseInt(a as string) - parseInt(b as string)), [students]);

  const [level, setLevel] = useState<string>(availableLevels[0] || '');
  const [dept, setDept] = useState<string>(availableDepts[0] || '');
  const [room, setRoom] = useState<string>(availableRooms[0] || '');

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedHistoryDate, setSelectedHistoryDate] = useState<string>('');
  const [currentSession, setCurrentSession] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaving, setIsSaving] = useState(false);
  const [isSaved, setIsSaved] = useState(false);
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');

  const todayStr = new Date().toLocaleDateString('th-TH', { 
    year: 'numeric', 
    month: 'long', 
    day: 'numeric' 
  });

  useEffect(() => {
    const rawDate = new Date().toISOString().split('T')[0];
    const todayRecords = attendanceRecords.filter(r => r.date === rawDate && r.type === 'MORNING');
    const sessionMap: Record<string, AttendanceStatus> = {};
    const remarkMap: Record<string, string> = {};

    todayRecords.forEach(r => {
      sessionMap[r.studentId] = r.status;
      if (r.remark) remarkMap[r.studentId] = r.remark;
    });

    setCurrentSession(sessionMap);
    setRemarks(remarkMap);
  }, [level, dept, room, attendanceRecords]);

  const filteredStudents = students.filter(s => 
    s.level === level && s.department === dept && s.room === room &&
    (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm))
  );

  const historyRecords = useMemo(() => {
    return attendanceRecords.filter(record => {
      const student = students.find(s => s.id === record.studentId);
      const matchesFilter = record.type === 'MORNING' && student?.level === level && student?.department === dept && student?.room === room;
      const matchesDate = selectedHistoryDate ? record.date === selectedHistoryDate : true;
      return matchesFilter && matchesDate;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [attendanceRecords, students, level, dept, room, selectedHistoryDate]);

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setCurrentSession(prev => ({ ...prev, [studentId]: status }));
    setIsSaved(false);
  };

  const handleSave = async () => {
    setIsSaving(true);

    // Simulate network delay for UX
    await new Promise(resolve => setTimeout(resolve, 600));

    const rawDate = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    const newRecordsBatch: AttendanceRecord[] = filteredStudents.map(s => ({
      id: `MORNING_${rawDate}_${s.id}`,
      studentId: s.id,
      date: rawDate,
      type: 'MORNING',
      status: currentSession[s.id] || 'ABSENT',
      remark: remarks[s.id] || '',
      timestamp: timestamp
    }));

    setAttendanceRecords(prev => {
      const studentIds = filteredStudents.map(s => s.id);
      const otherRecords = prev.filter(r => !(r.date === rawDate && r.type === 'MORNING' && studentIds.includes(r.studentId)));
      return [...otherRecords, ...newRecordsBatch];
    });

    setIsSaving(false);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setCurrentSession(prev => ({ ...prev, ...newBatch }));
    setIsSaved(false);
  };

  const shareToLine = () => {
    if (filteredStudents.length === 0) return;

    const emojiMap: Record<string, string> = { 
      PRESENT: '✅', 
      LATE: '⏰', 
      ABSENT: '❌', 
      BUSINESS_LEAVE: '📝', 
      SICK_LEAVE: '🤒' 
    };

    const stats = {
      PRESENT: 0,
      LATE: 0,
      ABSENT: 0,
      BUSINESS_LEAVE: 0,
      SICK_LEAVE: 0
    };

    const studentRows = filteredStudents.map((s, idx) => {
      const status = currentSession[s.id] || 'ABSENT';
      stats[status]++;
      const remarkText = remarks[s.id] ? ` [${remarks[s.id]}]` : '';
      return `${idx + 1}. ${s.name} ${emojiMap[status]}${remarkText}`;
    });

    const divider = "---------------------------";

    let message = `📋 รายงานเช็คชื่อเข้าแถว\n`;
    message += `🗓️ วันที่: ${todayStr}\n`;
    message += `🏫 ${level} / ${dept} (ห้อง ${room})\n`;
    message += `${divider}\n`;
    message += studentRows.join('\n');
    message += `\n${divider}\n`;
    message += `📊 สรุปยอดรวม\n`;
    message += `✅ มา: ${stats.PRESENT} | ⏰ สาย: ${stats.LATE}\n`;
    message += `❌ ขาด: ${stats.ABSENT} | 📝 ลา: ${stats.BUSINESS_LEAVE + stats.SICK_LEAVE}\n`;
    message += `👥 รวมทั้งหมด: ${filteredStudents.length} คน\n`;
    message += `${divider}\n`;
    message += `ระบบ EduSmart CMS`;

    window.open(`https://line.me/R/msg/text/?${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex bg-white p-2 rounded-2xl border border-slate-200 shadow-sm w-fit">
        <button onClick={() => setViewMode('checkin')} className={`flex items-center gap-2 px-8 py-3.5 rounded-xl text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><ClipboardCheck size={20} /> เช็คชื่อวันนี้</button>
        <button onClick={() => setViewMode('history')} className={`flex items-center gap-2 px-8 py-3.5 rounded-xl text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><History size={20} /> ประวัติย้อนหลัง</button>
      </div>

      <div className="bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm">
        <div className="grid grid-cols-1 md:grid-cols-4 lg:grid-cols-5 gap-6">
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ระดับชั้น</label>
            <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none transition-all">
              {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">แผนกวิชา</label>
            <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none transition-all">
              {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-2">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ห้องเรียน</label>
            <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none transition-all">
              {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
            </select>
          </div>
          {viewMode === 'checkin' ? (
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">ค้นหารายชื่อ</label>
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อ-รหัส..." className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl pl-12 pr-4 py-3 font-bold text-slate-900 outline-none" />
              </div>
            </div>
          ) : (
            <div className="space-y-2 lg:col-span-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">กรองตามวันที่</label>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={18} />
                  <input type="date" value={selectedHistoryDate} onChange={(e) => setSelectedHistoryDate(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl pl-12 pr-4 py-3 font-bold text-slate-900 outline-none transition-all" />
                </div>
                {selectedHistoryDate && (
                  <button onClick={() => setSelectedHistoryDate('')} className="p-3 bg-slate-100 text-slate-500 rounded-xl hover:bg-slate-200 transition-all"><X size={20} /></button>
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <>
          <div className="flex flex-wrap items-center justify-between gap-6 px-2">
            <div className="flex gap-3">
              <button onClick={() => markAll('PRESENT')} className="px-5 py-2 bg-green-50 text-green-700 rounded-full text-xs font-black border-2 border-green-100 transition-all">มาทุกคน</button>
              <button onClick={() => markAll('ABSENT')} className="px-5 py-2 bg-red-50 text-red-700 rounded-full text-xs font-black border-2 border-red-200 transition-all">ขาดทุกคน</button>
            </div>
            <div className="flex items-center gap-4">
              <button onClick={shareToLine} className="group relative flex items-center gap-2 px-7 py-4 bg-[#06C755] hover:bg-[#05b14c] text-white rounded-2xl font-black transition-all shadow-xl shadow-green-100/50 hover:scale-105 active:scale-95">
                <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 rounded-2xl transition-opacity" />
                <Share2 size={20} /> 
                <span>ส่งรายงานเข้า LINE</span>
              </button>
              <button 
                onClick={handleSave} 
                disabled={isSaving}
                className={`flex items-center gap-3 px-10 py-4 rounded-2xl text-white font-black transition-all shadow-xl ${
                  isSaved ? 'bg-green-600 scale-105 shadow-green-200' : 
                  isSaving ? 'bg-slate-400 cursor-not-allowed' : 'bg-slate-900 hover:bg-black'
                }`}
              >
                {isSaving ? <Loader2 size={24} className="animate-spin" /> : isSaved ? <CheckCircle2 size={24} className="animate-in zoom-in" /> : <Save size={24} />} 
                <span className="text-lg">
                  {isSaving ? 'กำลังบันทึก...' : isSaved ? 'บันทึกสำเร็จ' : 'บันทึกข้อมูลวันนี้'}
                </span>
              </button>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {filteredStudents.map((student, index) => (
              <div key={student.id} className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm hover:border-blue-300 transition-all group">
                <div className="flex items-start justify-between gap-5">
                  <div className="flex items-start gap-4">
                    <div className="w-14 h-14 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-xl text-white shadow-lg shrink-0 group-hover:bg-blue-600 transition-colors">{index + 1}</div>
                    <div>
                      <h4 className="font-black text-slate-900 text-xl leading-tight">{student.name}</h4>
                      <p className="text-[10px] text-slate-500 font-bold uppercase mt-1">รหัส: {student.studentId}</p>
                    </div>
                  </div>
                  <div className="grid grid-cols-5 gap-1.5">
                    {Object.entries(STATUS_LABELS).map(([key, value]) => (
                      <button key={key} onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} className={`flex flex-col items-center gap-1.5 p-2 rounded-xl border-2 transition-all ${currentSession[student.id] === key ? value.color + ' border-current' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-200'}`}>
                        <div className="scale-110">{value.icon}</div>
                        <span className="text-[8px] font-black uppercase text-center">{value.label}</span>
                      </button>
                    ))}
                  </div>
                </div>
                {currentSession[student.id] && currentSession[student.id] !== 'PRESENT' && (
                  <div className="mt-4 relative">
                    <MessageSquare className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                    <input type="text" value={remarks[student.id] || ''} onChange={(e) => setRemarks(prev => ({ ...prev, [student.id]: e.target.value }))} placeholder="ระบุหมายเหตุ เช่น ไปหาหมอ, รถเสีย..." className="w-full bg-slate-50 border-2 border-slate-100 rounded-xl pl-11 pr-4 py-3 font-bold text-slate-900 outline-none text-sm focus:border-blue-500 transition-all" />
                  </div>
                )}
              </div>
            ))}
          </div>
        </>
      ) : (
        <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 border-b">
                <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase">วันที่</th>
                <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase">นักเรียน</th>
                <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase">สถานะ</th>
                <th className="px-10 py-6 text-xs font-black text-slate-500 uppercase text-right">หมายเหตุ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {historyRecords.length > 0 ? historyRecords.map((record) => {
                const student = students.find(s => s.id === record.studentId);
                return (
                  <tr key={record.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-10 py-6 font-bold text-slate-900">{record.date}</td>
                    <td className="px-10 py-6">
                      <p className="font-bold text-slate-900">{student?.name}</p>
                      <p className="text-xs text-slate-500">{student?.studentId}</p>
                    </td>
                    <td className="px-10 py-6">
                      <span className={`px-4 py-1.5 rounded-full text-xs font-bold border ${STATUS_LABELS[record.status].color}`}>
                        {STATUS_LABELS[record.status].label}
                      </span>
                    </td>
                    <td className="px-10 py-6 text-sm font-bold text-slate-900 text-right">{record.remark || '-'}</td>
                  </tr>
                );
              }) : (
                <tr>
                  <td colSpan={4} className="py-20 text-center">
                    <History size={48} className="mx-auto text-slate-200 mb-4 opacity-10" />
                    <p className="text-sm font-bold text-slate-400 uppercase tracking-widest">ไม่พบประวัติการเช็คชื่อตามตัวกรอง</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default MorningAttendance;

import React, { useState, useEffect, useMemo } from 'react';
import { Student, Subject, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { 
  Save, BookOpen, Clock, Users, MessageSquare, UserPlus, X, Plus, Filter, 
  History, ClipboardCheck, Calendar, Edit3, CheckCircle2, Trash2, AlertCircle, Lock,
  Share2, Search, ChevronRight, Settings2, AlertTriangle, Loader2
} from 'lucide-react';

interface ClassAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  subjects: Subject[];
  setSubjects: React.Dispatch<React.SetStateAction<Subject[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  currentUser: any;
}

const ClassAttendance: React.FC<ClassAttendanceProps> = ({ 
  students: allStudents, 
  subjects, 
  setSubjects,
  attendanceRecords, 
  setAttendanceRecords,
  currentUser
}) => {
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedHistoryDate, setSelectedHistoryDate] = useState<string>('');
  const [showSubjectModal, setShowSubjectModal] = useState(false);
  const [editingSubject, setEditingSubject] = useState<Partial<Subject> | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  const availableLevels = useMemo<string[]>(() => {
    const levels = Array.from(new Set(allStudents.map(s => s.level)));
    return (levels.length > 0 ? levels.sort() : Object.values(ThaiLevel)) as string[];
  }, [allStudents]);

  const availableDepts = useMemo<string[]>(() => {
    const depts = Array.from(new Set(allStudents.map(s => s.department)));
    return (depts.length > 0 ? depts.sort() : Object.values(Department)) as string[];
  }, [allStudents]);

  const availableRooms = useMemo<string[]>(() => {
    const rms = Array.from(new Set(allStudents.map(s => s.room)));
    return rms.length > 0 ? rms.sort((a, b) => parseInt(a as string) - parseInt(b as string)) : ['1', '2', '3'];
  }, [allStudents]);

  const [level, setLevel] = useState<string>(availableLevels[0] || '');
  const [dept, setDept] = useState<string>(availableDepts[0] || '');
  const [room, setRoom] = useState<string>(availableRooms[0] || '');

  const filteredSubjects = useMemo(() => {
    return subjects.filter(s => s.level === level && s.department === dept);
  }, [subjects, level, dept]);

  const [subjectId, setSubjectId] = useState<string>('');

  useEffect(() => {
    if (filteredSubjects.length > 0) {
      if (!filteredSubjects.some(s => s.id === subjectId)) {
        setSubjectId(filteredSubjects[0].id);
      }
    } else {
      setSubjectId('');
    }
  }, [filteredSubjects, subjectId]);

  const [sessionAttendance, setSessionAttendance] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaving, setIsSaving] = useState(false);
  const [isSaved, setIsSaved] = useState(false);
  const [isSubjectSaving, setIsSubjectSaving] = useState(false);

  useEffect(() => {
    if (!subjectId) {
      setSessionAttendance({});
      setRemarks({});
      return;
    }
    const today = new Date().toISOString().split('T')[0];
    const existing = attendanceRecords.filter(r => r.date === today && r.type === 'SUBJECT' && r.subjectId === subjectId);

    const attMap: Record<string, AttendanceStatus> = {};
    const remMap: Record<string, string> = {};

    existing.forEach(r => {
      attMap[r.studentId] = r.status;
      if (r.remark) remMap[r.studentId] = r.remark;
    });

    setSessionAttendance(attMap);
    setRemarks(remMap);
  }, [level, dept, room, subjectId, attendanceRecords]);

  const filteredStudents = useMemo(() => {
    return allStudents.filter(s => 
      s.level === level && 
      s.department === dept && 
      s.room === room &&
      (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm))
    );
  }, [allStudents, level, dept, room, searchTerm]);

  const historyRecords = useMemo(() => {
    return attendanceRecords.filter(record => {
      const student = allStudents.find(s => s.id === record.studentId);
      const matchesFilter = record.type === 'SUBJECT' && 
             record.subjectId === subjectId &&
             student?.level === level && 
             student?.department === dept && 
             student?.room === room;
      const matchesDate = selectedHistoryDate ? record.date === selectedHistoryDate : true;
      return matchesFilter && matchesDate;
    }).sort((a, b) => b.date.localeCompare(a.date) || b.timestamp.localeCompare(a.timestamp));
  }, [attendanceRecords, subjectId, level, dept, room, allStudents, selectedHistoryDate]);

  const handleStatusChange = (id: string, status: AttendanceStatus) => {
    setSessionAttendance(prev => ({ ...prev, [id]: status }));
    setIsSaved(false);
  };

  const handleSave = async () => {
    if (!subjectId) return alert('กรุณาเลือกรายวิชา');

    setIsSaving(true);
    await new Promise(resolve => setTimeout(resolve, 600));

    const today = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');

    const newRecordsBatch: AttendanceRecord[] = filteredStudents.map(s => ({
      id: `SUBJECT_${today}_${subjectId}_${s.id}`,
      studentId: s.id,
      date: today,
      type: 'SUBJECT',
      subjectId: subjectId,
      status: sessionAttendance[s.id] || 'ABSENT',
      remark: remarks[s.id] || '',
      timestamp: timestamp
    }));

    setAttendanceRecords(prev => {
      const studentIds = filteredStudents.map(s => s.id);
      const otherRecords = prev.filter(r => !(r.date === today && r.type === 'SUBJECT' && r.subjectId === subjectId && studentIds.includes(r.studentId)));
      return [...otherRecords, ...newRecordsBatch];
    });

    setIsSaving(false);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setSessionAttendance(prev => ({ ...prev, ...newBatch }));
    setIsSaved(false);
  };

  const handleSaveSubject = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingSubject?.name || !editingSubject?.code || !editingSubject?.level || !editingSubject?.department) return;

    setIsSubjectSaving(true);
    await new Promise(resolve => setTimeout(resolve, 400));

    if (editingSubject.id) {
      setSubjects(prev => prev.map(s => s.id === editingSubject.id ? (editingSubject as Subject) : s));
    } else {
      const newSub: Subject = {
        ...(editingSubject as Subject),
        id: `SUB_${Date.now()}`,
        teacherId: currentUser.id
      };
      setSubjects(prev => [...prev, newSub]);
    }

    setIsSubjectSaving(false);
    setEditingSubject(null);
  };

  const handleDeleteSubject = (id: string) => {
    setSubjects(prev => prev.filter(s => s.id !== id));
    setConfirmDeleteId(null);
  };

  return (
    <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div className="flex bg-white p-2 rounded-[24px] border border-slate-200 shadow-sm w-fit">
          <button onClick={() => setViewMode('checkin')} className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><ClipboardCheck size={20} /> เช็คชื่อ</button>
          <button onClick={() => setViewMode('history')} className={`flex items-center gap-2 px-8 py-3.5 rounded-[18px] text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><History size={20} /> ประวัติ</button>
        </div>

        <button 
          onClick={() => {
            setEditingSubject({ level: level, department: dept });
            setShowSubjectModal(true);
          }}
          className="flex items-center gap-2 px-6 py-3.5 bg-white border border-slate-200 rounded-2xl text-slate-600 text-sm font-black hover:bg-slate-50 transition-all shadow-sm font-heading"
        >
          <Settings2 size={18} className="text-blue-600" /> จัดการรายวิชา
        </button>
      </div>

      <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
        <div className="grid grid-cols-1 md:grid-cols-5 gap-6">
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ระดับชั้น</label>
            <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none">
              {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">แผนกวิชา</label>
            <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none">
              {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ห้องเรียน</label>
            <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-slate-900 outline-none">
              {availableRooms.map(r => <option key={r} value={r}>ห้อง {r}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-blue-600 uppercase tracking-widest ml-1">รายวิชา ({dept})</label>
            <select value={subjectId} onChange={(e) => setSubjectId(e.target.value)} className="w-full bg-slate-50 border border-blue-100 rounded-xl px-4 py-3 font-black text-slate-900 outline-none focus:border-blue-400">
              {filteredSubjects.length > 0 ? filteredSubjects.map(s => <option key={s.id} value={s.id}>{s.code} - {s.name}</option>) : <option value="">(ไม่มีรายวิชาในกลุ่มนี้)</option>}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">
              {viewMode === 'checkin' ? 'ค้นหานักเรียน' : 'กรองตามวันที่'}
            </label>
            {viewMode === 'checkin' ? (
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อ..." className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-10 pr-4 py-3 font-bold text-slate-900 outline-none text-sm" />
              </div>
            ) : (
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" size={16} />
