                    const isMatched = s.level === level && s.department === dept;
                    const isConfirming = confirmDeleteId === s.id;
                    return (
                      <div key={s.id} className={`flex items-center justify-between p-4 rounded-2xl border-2 transition-all group ${isMatched ? 'bg-blue-50 border-blue-100' : 'bg-slate-50 border-slate-100'} ${isConfirming ? 'border-red-400 bg-red-50' : ''}`}>
                        <div className="min-w-0 text-left">
                          <p className={`font-black text-sm truncate ${isConfirming ? 'text-red-700' : 'text-slate-900'}`}>{s.name}</p>
                          <div className="flex items-center gap-2 mt-1">
                            <span className="text-[9px] font-black text-slate-500 bg-white px-2 py-0.5 rounded border border-slate-100 uppercase">{s.code}</span>
                            <span className={`text-[9px] font-black px-2 py-0.5 rounded border uppercase ${isMatched ? 'bg-blue-600 text-white border-blue-600' : 'bg-slate-200 text-slate-600 border-slate-200'}`}>{s.level}</span>
                          </div>
                        </div>
                        <div className="flex gap-1 transition-all">
                          {isConfirming ? (
                            <div className="flex gap-1 animate-in slide-in-from-right-2">
                              <button onClick={() => setConfirmDeleteId(null)} className="p-2 text-slate-500 hover:bg-white rounded-lg transition-all" title="ยกเลิก"><X size={16} /></button>
                              <button onClick={() => handleDeleteSubject(s.id)} className="p-2 text-red-600 hover:bg-white rounded-lg transition-all font-black text-[10px] uppercase" title="ยืนยันการลบ">ยืนยัน</button>
                            </div>
                          ) : (
                            <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                              <button onClick={() => setEditingSubject(s)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-white rounded-lg transition-all"><Edit3 size={16} /></button>
                              <button onClick={() => setConfirmDeleteId(s.id)} className="p-2 text-slate-400 hover:text-red-600 hover:bg-white rounded-lg transition-all"><Trash2 size={16} /></button>
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })}
                  {subjects.length === 0 && (
                    <div className="py-20 text-center text-slate-300 italic text-xs">ยังไม่มีข้อมูลรายวิชา</div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ClassAttendance;

import React, { useState, useMemo, useEffect } from 'react';
import { Student, TuitionConfig, PaymentRecord, ThaiLevel, Department } from '../types';
import { 
  CreditCard, Plus, Save, Trash2, Banknote, History, Search, CheckCircle2, 
  AlertCircle, User, Wallet, Layers, Bookmark, Settings, Building2, CreditCard as CardIcon, Check, X, Loader2
} from 'lucide-react';

interface TuitionSystemProps {
  students: Student[];
  tuitionConfigs: TuitionConfig[];
  setTuitionConfigs: React.Dispatch<React.SetStateAction<TuitionConfig[]>>;
  paymentRecords: PaymentRecord[];
  setPaymentRecords: React.Dispatch<React.SetStateAction<PaymentRecord[]>>;
  user: any;
}

const TuitionSystem: React.FC<TuitionSystemProps> = ({ 
  students, tuitionConfigs, setTuitionConfigs, paymentRecords, setPaymentRecords, user 
}) => {
  const [activeTab, setActiveTab] = useState<'config' | 'payment' | 'bank'>(
    user.role === 'PARENT' ? 'bank' : 'payment'
  );

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [isConfigSaving, setIsConfigSaving] = useState(false);
  const [isPaymentSaving, setIsPaymentSaving] = useState(false);
  const [isPaymentSuccess, setIsPaymentSuccess] = useState(false);

  const [bankInfo, setBankInfo] = useState({
    bankName: 'ธนาคารกรุงไทย (Krungthai)',
    accountNo: '012-3-45678-9',
    accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
  });

  useEffect(() => {
    const savedBank = localStorage.getItem('cms_bank_info');
    if (savedBank) setBankInfo(JSON.parse(savedBank));
  }, []);

  const saveBankInfo = () => {
    localStorage.setItem('cms_bank_info', JSON.stringify(bankInfo));
    alert('บันทึกข้อมูลบัญชีธนาคารเรียบร้อยแล้ว');
  };

  const [newConfig, setNewConfig] = useState<Partial<TuitionConfig>>({
    level: Object.values(ThaiLevel)[0],
    department: Object.values(Department)[0],
    amount: 0,
    term: '1/2567'
  });

  const [paymentAmount, setPaymentAmount] = useState<number | "">("");
  const [paymentMethod, setPaymentMethod] = useState<'CASH' | 'TRANSFER'>('TRANSFER');

  const filteredStudents = useMemo(() => {
    return students.filter(s => 
      s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm)
    );
  }, [students, searchTerm]);

  const handleAddConfig = async () => {
    if (!newConfig.amount || newConfig.amount <= 0) return alert('ระบุจำนวนเงิน');

    setIsConfigSaving(true);
    await new Promise(resolve => setTimeout(resolve, 500));

    const config: TuitionConfig = {
      id: `CONF_${Date.now()}`,
      level: newConfig.level!,
      department: newConfig.department!,
      amount: newConfig.amount!,
      term: newConfig.term!
    };
    setTuitionConfigs(prev => [...prev, config]);
    setIsConfigSaving(false);
  };

  const handlePayment = async (student: Student) => {
    const amount = Number(paymentAmount);
    if (amount <= 0) return alert('ระบุจำนวนเงิน');

    setIsPaymentSaving(true);
    await new Promise(resolve => setTimeout(resolve, 800));

    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    const newPayment: PaymentRecord = {
      id: `PAY_${Date.now()}`,
      studentId: student.id,
      configId: config?.id || 'GENERAL',
      amount: amount,
      method: paymentMethod,
      date: new Date().toLocaleDateString('th-TH'),
      recordedBy: user.name,
      status: 'PAID'
    };

    setPaymentRecords(prev => [...prev, newPayment]);
    setPaymentAmount("");
    setIsPaymentSaving(false);
    setIsPaymentSuccess(true);
    setTimeout(() => setIsPaymentSuccess(false), 3000);
  };

  const processDeleteConfig = (id: string) => {
    setTuitionConfigs(prev => prev.filter(c => c.id !== id));
    setConfirmDeleteId(null);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20 max-w-7xl mx-auto">
      <div className="flex bg-white p-2 rounded-2xl border border-slate-200 shadow-sm w-fit">
        <button onClick={() => { setActiveTab('payment'); setConfirmDeleteId(null); }} className={`px-6 py-3 rounded-xl text-xs font-bold transition-all font-heading ${activeTab === 'payment' ? 'bg-[#00AEEF] text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>รับชำระเงิน</button>
        <button onClick={() => { setActiveTab('config'); setConfirmDeleteId(null); }} className={`px-6 py-3 rounded-xl text-xs font-bold transition-all font-heading ${activeTab === 'config' ? 'bg-[#00AEEF] text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>โครงสร้างค่าเทอม</button>
        <button onClick={() => { setActiveTab('bank'); setConfirmDeleteId(null); }} className={`px-6 py-3 rounded-xl text-xs font-bold transition-all font-heading ${activeTab === 'bank' ? 'bg-[#00AEEF] text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}>ตั้งค่าบัญชีรับเงิน</button>
      </div>

      {activeTab === 'bank' && (
        <div className="bg-white p-10 rounded-[40px] border border-slate-200 shadow-sm max-w-2xl mx-auto space-y-8 animate-in slide-in-from-bottom-4">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-sky-50 text-[#00AEEF] rounded-2xl shadow-sm"><Settings size={24} /></div>
            <div>
              <h3 className="text-xl font-black text-slate-900 font-heading">ตั้งค่าบัญชีรับชำระเงิน</h3>
              <p className="text-xs text-slate-400 font-bold">บัญชีนี้จะแสดงให้ผู้ปกครองเห็นในหน้า Dashbord และการแจ้งเตือน</p>
            </div>
          </div>
          <div className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ชื่อธนาคาร</label>
              <div className="relative">
                <Building2 className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                <input type="text" value={bankInfo.bankName} onChange={(e) => setBankInfo({...bankInfo, bankName: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-2xl pl-12 pr-6 py-4 font-bold outline-none focus:border-[#00AEEF] transition-all" placeholder="เช่น ธนาคารกรุงไทย" />
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">เลขที่บัญชี</label>
              <div className="relative">
                <CardIcon className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                <input type="text" value={bankInfo.accountNo} onChange={(e) => setBankInfo({...bankInfo, accountNo: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-2xl pl-12 pr-6 py-4 font-black text-xl outline-none focus:border-[#00AEEF] transition-all" placeholder="000-0-00000-0" />
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ชื่อบัญชี</label>
              <div className="relative">
                <User className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                <input type="text" value={bankInfo.accountName} onChange={(e) => setBankInfo({...bankInfo, accountName: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-2xl pl-12 pr-6 py-4 font-bold outline-none focus:border-[#00AEEF] transition-all" placeholder="ชื่อ นามสกุล หรือ ชื่อสถาบัน" />
              </div>
            </div>
            <button onClick={saveBankInfo} className="w-full py-5 bg-[#00AEEF] text-white rounded-2xl font-black shadow-xl hover:bg-sky-600 transition-all flex items-center justify-center gap-2 uppercase tracking-widest text-xs font-heading">
              <Save size={18} /> บันทึกข้อมูลบัญชีรับชำระ
            </button>
          </div>
        </div>
      )}

      {activeTab === 'config' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1 bg-white p-8 rounded-[32px] border border-slate-200 shadow-sm space-y-6">
            <h3 className="text-xl font-bold font-heading">กำหนดค่าเทอม</h3>
            <div className="space-y-4">
              <input type="text" value={newConfig.term} onChange={(e) => setNewConfig({...newConfig, term: e.target.value})} className="w-full bg-slate-50 border rounded-xl px-4 py-3" placeholder="ภาคเรียน เช่น 1/2567" />
              <select value={newConfig.level} onChange={(e) => setNewConfig({...newConfig, level: e.target.value})} className="w-full bg-slate-50 border rounded-xl px-4 py-3 font-bold">
                {Object.values(ThaiLevel).map(v => <option key={v} value={v}>{v}</option>)}
              </select>
              <select value={newConfig.department} onChange={(e) => setNewConfig({...newConfig, department: e.target.value})} className="w-full bg-slate-50 border rounded-xl px-4 py-3 font-bold">
                {Object.values(Department).map(v => <option key={v} value={v}>{v}</option>)}
              </select>
              <input type="number" value={newConfig.amount || ""} onChange={(e) => setNewConfig({...newConfig, amount: Number(e.target.value)})} className="w-full bg-slate-50 border rounded-xl px-4 py-3 font-black text-xl" placeholder="ยอดเงิน (บาท)" />
              <button 
                onClick={handleAddConfig} 
                disabled={isConfigSaving}
                className={`w-full py-4 rounded-xl font-black uppercase tracking-widest text-xs font-heading shadow-lg transition-all flex items-center justify-center gap-2 ${
                  isConfigSaving ? 'bg-slate-400 cursor-not-allowed' : 'bg-[#00AEEF] text-white hover:bg-sky-600'
                }`}
              >
                {isConfigSaving ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                {isConfigSaving ? 'กำลังบันทึก...' : 'บันทึกโครงสร้าง'}
              </button>
            </div>
          </div>
          <div className="lg:col-span-2 bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase">
                <tr>
                  <th className="px-8 py-5">ระดับ / แผนก</th>
                  <th className="px-8 py-5 text-right">ยอดเงิน</th>
                  <th className="px-8 py-5 text-right">จัดการ</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {tuitionConfigs.map(c => {
                  const isConfirming = confirmDeleteId === c.id;
                  return (
                    <tr key={c.id} className={`hover:bg-slate-50/50 transition-colors ${isConfirming ? 'bg-red-50' : ''}`}>
                      <td className="px-8 py-5">
                        <p className={`font-black ${isConfirming ? 'text-red-900' : 'text-slate-900'}`}>{c.level}</p>
                        <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{c.department}</p>
                      </td>
                      <td className={`px-8 py-5 text-right font-black text-lg ${isConfirming ? 'text-red-600' : 'text-[#00AEEF]'}`}>
                        {c.amount.toLocaleString()} ฿
                      </td>
                      <td className="px-8 py-5 text-right">
                        {isConfirming ? (
                          <div className="flex justify-end gap-2 animate-in slide-in-from-right-2">
                            <button onClick={() => setConfirmDeleteId(null)} className="p-2 bg-slate-200 text-slate-600 rounded-lg hover:bg-slate-300 transition-all"><X size={16} /></button>
                            <button onClick={() => processDeleteConfig(c.id)} className="p-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-all text-[10px] font-black uppercase">ลบ</button>
                          </div>
                        ) : (
                          <button onClick={() => setConfirmDeleteId(c.id)} className="p-2 text-slate-300 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all"><Trash2 size={18} /></button>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {activeTab === 'payment' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
           <div className="lg:col-span-1 bg-white rounded-[32px] border border-slate-200 shadow-sm h-[600px] overflow-hidden flex flex-col">
              <div className="p-6 border-b flex items-center gap-3 bg-slate-50/50">
                <Search className="text-slate-400" size={18} />
                <input type="text" placeholder="ค้นหาชื่อ หรือ รหัสนักเรียน..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="w-full bg-transparent font-bold outline-none text-sm" />
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-2">
                {filteredStudents.map(s => (
                  <button key={s.id} onClick={() => { setSelectedStudentId(s.id); setIsPaymentSuccess(false); }} className={`w-full text-left p-4 rounded-[20px] border-2 transition-all ${selectedStudentId === s.id ? 'bg-[#00AEEF] border-[#00AEEF] text-white shadow-lg scale-[1.02]' : 'bg-white border-transparent hover:bg-slate-50 text-slate-900'}`}>
                    <p className="font-black text-sm">{s.name}</p>
                    <p className={`text-[10px] font-bold uppercase tracking-widest mt-0.5 ${selectedStudentId === s.id ? 'text-sky-100 opacity-80' : 'text-slate-400'}`}>{s.studentId}</p>
                  </button>
                ))}
              </div>
           </div>
           <div className="lg:col-span-2">
             {selectedStudentId ? (
               <div className="bg-white p-10 rounded-[40px] border border-slate-200 shadow-sm space-y-10 animate-in slide-in-from-right-4">
                 {(() => {
                   const s = students.find(x => x.id === selectedStudentId)!;
                   const config = tuitionConfigs.find(c => c.level === s.level && c.department === s.department);
                   const paid = paymentRecords.filter(p => p.studentId === s.id).reduce((sum, p) => sum + p.amount, 0);
                   const remaining = config ? Math.max(0, config.amount - paid) : 0;
                   return (
                     <>
                       <div className="flex items-center justify-between">
                          <div className="flex items-center gap-6">
                            <div className="w-20 h-20 bg-sky-50 text-[#00AEEF] rounded-[24px] flex items-center justify-center shadow-inner"><User size={40} /></div>
                            <div>
                                <h3 className="text-3xl font-black text-slate-900 font-heading leading-tight">{s.name}</h3>
                                <div className="flex items-center gap-3 mt-1.5">
                                   <span className="px-3 py-1 bg-slate-900 text-white rounded-lg text-[10px] font-black uppercase tracking-widest">{s.studentId}</span>
                                   <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">{s.level} | {s.department}</p>
                                </div>
                            </div>
                          </div>
                          {(remaining === 0 || isPaymentSuccess) && (
                            <div className="flex items-center gap-2 text-green-600 bg-green-50 px-6 py-3 rounded-2xl border border-green-100 animate-in zoom-in">
                               <CheckCircle2 size={24} />
                               <span className="font-black uppercase tracking-widest text-xs font-heading">
                                 {isPaymentSuccess ? 'รับชำระสำเร็จ' : 'ชำระครบแล้ว'}
                               </span>
                            </div>
                          )}
                       </div>

                       <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                         <div className="bg-slate-900 p-10 rounded-[40px] text-white flex flex-col justify-center relative overflow-hidden shadow-2xl">
                            <div className="absolute top-0 right-0 p-8 opacity-5 pointer-events-none transform translate-x-10 translate-y--10">
                               <Wallet size={180} />
                            </div>
                            <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-3 relative z-10 font-heading">ยอดค้างชำระปัจจุบัน</p>
                            <p className="text-6xl font-black text-[#00AEEF] font-heading relative z-10 tracking-tighter">{remaining.toLocaleString()}<span className="text-xl ml-2 text-slate-400">฿</span></p>
                            <div className="mt-8 pt-6 border-t border-white/10 flex items-center justify-between relative z-10">
                               <div>
                                  <p className="text-[9px] font-bold text-slate-500 uppercase mb-0.5">ชำระแล้ว</p>
                                  <p className="text-sm font-black text-white">{paid.toLocaleString()} ฿</p>
                               </div>
                               <div className="text-right">
                                  <p className="text-[9px] font-bold text-slate-500 uppercase mb-0.5">ยอดเต็ม</p>
                                  <p className="text-sm font-black text-slate-300">{config?.amount.toLocaleString() || 0} ฿</p>
                               </div>
                            </div>
                         </div>

                         <div className="space-y-8">
                            <div className="space-y-2">
                               <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ระบุยอดเงินที่รับชำระ</label>
                               <div className="relative">
                                  <input type="number" value={paymentAmount} onChange={(e) => setPaymentAmount(Number(e.target.value))} className="w-full bg-slate-50 border-2 border-slate-100 focus:border-[#00AEEF] rounded-[24px] px-8 py-6 font-black text-5xl outline-none transition-all shadow-inner text-[#00AEEF]" placeholder="0" />
                                  <span className="absolute right-8 top-1/2 -translate-y-1/2 font-black text-slate-300 text-2xl">฿</span>
                               </div>
                            </div>
                            <div className="grid grid-cols-2 gap-4">
                               <button onClick={() => setPaymentMethod('TRANSFER')} className={`py-4 rounded-2xl text-[10px] font-black border-2 transition-all uppercase tracking-widest font-heading ${paymentMethod === 'TRANSFER' ? 'bg-[#00AEEF] border-[#00AEEF] text-white shadow-lg' : 'bg-white border-slate-100 text-slate-400 hover:border-sky-100'}`}>เงินโอน (Transfer)</button>
                               <button onClick={() => setPaymentMethod('CASH')} className={`py-4 rounded-2xl text-[10px] font-black border-2 transition-all uppercase tracking-widest font-heading ${paymentMethod === 'CASH' ? 'bg-[#00AEEF] border-[#00AEEF] text-white shadow-lg' : 'bg-white border-slate-100 text-slate-400 hover:border-sky-100'}`}>เงินสด (Cash)</button>
                            </div>
                            <button 
                              onClick={() => handlePayment(s)} 
                              disabled={isPaymentSaving || remaining === 0}
                              className={`w-full py-6 rounded-[24px] font-black uppercase tracking-widest text-xs transition-all shadow-2xl active:scale-95 font-heading flex items-center justify-center gap-3 ${
                                isPaymentSaving ? 'bg-slate-400 cursor-not-allowed' : 
                                remaining === 0 ? 'bg-slate-100 text-slate-400 cursor-not-allowed' : 'bg-slate-900 text-white hover:bg-black'
                              }`}
                            >
                              {isPaymentSaving ? <Loader2 size={18} className="animate-spin" /> : <Banknote size={18} />}
                              {isPaymentSaving ? 'กำลังยืนยัน...' : 'ยืนยันการรับชำระเงิน'}
                            </button>
                         </div>
                       </div>
                     </>
                   )
                 })()}
               </div>
             ) : <div className="h-full flex flex-col items-center justify-center text-slate-300 border-4 border-dashed border-slate-100 rounded-[48px] p-20 text-center animate-pulse">
                  <Wallet size={80} className="mb-6 opacity-10" />
                  <h3 className="text-2xl font-black text-slate-400 uppercase tracking-widest font-heading">โปรดเลือกนักเรียน</h3>
                  <p className="text-sm font-bold opacity-60 mt-2">คลิกเลือกรายชื่อจากแถบด้านซ้ายเพื่อทำรายการการเงิน</p>
                </div>}
           </div>
        </div>
      )}
    </div>
  );
};

export default TuitionSystem;

import React, { useState, useRef, useMemo } from 'react';
import { User, UserRole, Department, Student } from '../types';
import * as XLSX from 'https://esm.sh/xlsx';
import { 
  UserPlus, Shield, Trash2, Edit3, X, Search, FileSpreadsheet, 
  Upload, Download, Key, UserX, Users, UserCircle, CheckCircle2, AlertCircle, Info, Check, Loader2
} from 'lucide-react';

interface UserManagementProps {
  users: User[];
  setUsers: React.Dispatch<React.SetStateAction<User[]>>;
  currentUser?: User;
  students?: Student[]; 
}

const UserManagement: React.FC<UserManagementProps> = ({ users, setUsers, currentUser, students = [] }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [activeTab, setActiveTab] = useState<'TEACHER' | 'PARENT' | 'ADMIN'>('TEACHER');
  const [showModal, setShowModal] = useState<'ADD' | 'EDIT' | null>(null);
  const [editingUserId, setEditingUserId] = useState<string | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [isImporting, setIsImporting] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [importStatus, setImportStatus] = useState<null | { type: 'success' | 'error', message: string }>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const availableDepts = useMemo(() => {
    const depts = new Set(students.map(s => s.department));
    Object.values(Department).forEach(d => depts.add(d));
    return Array.from(depts).sort();
  }, [students]);

  const [formData, setFormData] = useState<Partial<User>>({
    name: '',
    role: 'TEACHER',
    department: availableDepts[0] || '',
    studentId: '',
    username: '',
    password: ''
  });

  const filteredUsers = users.filter(u => 
    u.role === activeTab &&
    (u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
     u.username.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const resetForm = () => {
    setFormData({ 
      name: '', 
      role: activeTab as UserRole, 
      department: availableDepts[0] || '', 
      studentId: '', 
      username: '', 
      password: '' 
    });
    setEditingUserId(null);
  };

  const handleOpenEdit = (user: User) => {
    setFormData({ ...user });
    setEditingUserId(user.id);
    setShowModal('EDIT');
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    // Simulate API call delay
    await new Promise(resolve => setTimeout(resolve, 500));

    if (showModal === 'ADD') {
      const newUser = { id: `USR_${Date.now()}`, ...formData } as User;
      setUsers(prev => [...prev, newUser]);
    } else if (showModal === 'EDIT' && editingUserId) {
      setUsers(prev => prev.map(u => u.id === editingUserId ? { ...u, ...formData } as User : u));
    }

    setIsSaving(false);
    setShowModal(null);
    resetForm();
  };

  const processDeleteUser = (id: string) => {
    if (currentUser && id === currentUser.id) {
      alert('ไม่สามารถลบบัญชีที่คุณกำลังใช้งานได้');
      setConfirmDeleteId(null);
      return;
    }
    setUsers(prev => prev.filter(u => u.id !== id));
    setConfirmDeleteId(null);
  };

  const downloadTemplate = () => {
    const teacherData = [
      { name: "ชื่อ-นามสกุล ครู", username: "teacher_id", password: "password123", department: "แผนกวิชา" }
    ];
    const parentData = [
      { name: "ชื่อ-นามสกุล ผู้ปกครอง", username: "parent_id", password: "password123", studentId: "รหัสนักเรียน (รหัส 6 หลัก)" }
    ];

    const wb = XLSX.utils.book_new();
    const wsTeacher = XLSX.utils.json_to_sheet(teacherData);
    const wsParent = XLSX.utils.json_to_sheet(parentData);

    XLSX.utils.book_append_sheet(wb, wsTeacher, "Template_Teacher");
    XLSX.utils.book_append_sheet(wb, wsParent, "Template_Parent");
    XLSX.writeFile(wb, "user_import_template.xlsx");
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImporting(true);
    setImportStatus(null);

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const data = event.target?.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const sheetName = activeTab === 'TEACHER' ? 'Template_Teacher' : 'Template_Parent';
        const worksheet = workbook.Sheets[sheetName] || workbook.Sheets[workbook.SheetNames[0]];
        const json: any[] = XLSX.utils.sheet_to_json(worksheet);

        const newUsers: User[] = json.map((row, i) => ({
          id: `USR_IMP_${Date.now()}_${i}`,
          name: String(row.name || row['ชื่อ-นามสกุล'] || '').trim(),
          username: String(row.username || row['ชื่อผู้ใช้'] || '').trim(),
          password: String(row.password || row['รหัสผ่าน'] || '1234').trim(),
          role: activeTab as UserRole,
          department: activeTab === 'TEACHER' ? String(row.department || row['แผนกวิชา'] || '').trim() : undefined,
          studentId: activeTab === 'PARENT' ? String(row.studentId || row['รหัสนักเรียน'] || '').trim() : undefined,
        })).filter(u => u.name && u.username);

        if (newUsers.length > 0) {
          setUsers(prev => [...prev, ...newUsers]);
          setImportStatus({ type: 'success', message: `นำเข้าข้อมูลสำเร็จ ${newUsers.length} รายการ` });
        } else {
          setImportStatus({ type: 'error', message: 'ไม่พบข้อมูลที่ถูกต้อง กรุณาตรวจสอบหัวตารางในไฟล์' });
        }
      } catch (err) {
        setImportStatus({ type: 'error', message: 'เกิดข้อผิดพลาดในการอ่านไฟล์' });
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };
    reader.readAsBinaryString(file);
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        <div className="xl:col-span-2 bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm">
          <div className="flex items-center gap-5 mb-8">
            <div className="p-4 bg-indigo-600 rounded-[24px] text-white shadow-xl shadow-indigo-100">
              <FileSpreadsheet size={28} />
            </div>
            <div>
              <h3 className="text-2xl font-black text-slate-900 tracking-tight font-heading">นำเข้าผู้ใช้งานแบบกลุ่ม</h3>
              <p className="text-xs text-slate-500 font-bold uppercase tracking-widest mt-1">เพิ่มข้อมูล{activeTab === 'TEACHER' ? 'ครู' : 'ผู้ปกครอง'}ผ่านไฟล์ Excel</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div 
              onClick={() => fileInputRef.current?.click()} 
              className={`p-10 rounded-[32px] border-4 border-dashed flex flex-col items-center justify-center cursor-pointer transition-all group ${isImporting ? 'bg-slate-50 border-slate-200 opacity-50' : 'bg-slate-50 border-slate-100 hover:border-indigo-400 hover:bg-indigo-50'}`}
            >
              <input type="file" ref={fileInputRef} className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} disabled={isImporting} />
              <div className="p-5 bg-white rounded-2xl shadow-sm mb-4 group-hover:scale-110 transition-transform">
                {isImporting ? <div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin" /> : <Upload size={32} className="text-indigo-600" />}
              </div>
              <p className="font-black text-slate-900 text-center text-sm">{isImporting ? 'กำลังประมวลผลไฟล์...' : `อัปโหลดไฟล์สำหรับ ${activeTab === 'TEACHER' ? 'ครู' : 'ผู้ปกครอง'}`}</p>
            </div>
            <div className="flex flex-col justify-center gap-4">
              <button onClick={downloadTemplate} className="flex items-center justify-center gap-3 py-5 bg-slate-900 text-white rounded-[24px] font-black hover:bg-black transition-all shadow-xl">
                <Download size={20} /> ดาวน์โหลดเทมเพลต (xlsx)
              </button>
              <div className="p-5 bg-indigo-50 rounded-[24px] border border-indigo-100">
                <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest mb-1 flex items-center gap-2">
                  <Info size={12} /> ข้อมูลที่ต้องระบุ
                </p>
                <p className="text-[10px] text-indigo-800 font-bold leading-relaxed">
                  {activeTab === 'TEACHER' ? 'name, username, password, department' : 'name, username, password, studentId'}
                </p>
              </div>
            </div>
          </div>
          {importStatus && (
            <div className={`mt-6 p-4 rounded-2xl flex items-center gap-4 border-2 animate-in slide-in-from-top-4 ${importStatus.type === 'success' ? 'bg-green-50 border-green-100 text-green-700' : 'bg-red-50 border-red-100 text-red-700'}`}>
              {importStatus.type === 'success' ? <CheckCircle2 size={20} /> : <AlertCircle size={20} />}
              <p className="font-black text-xs">{importStatus.message}</p>
            </div>
          )}
        </div>

        <div className="bg-indigo-900 p-10 rounded-[40px] shadow-2xl relative overflow-hidden flex flex-col justify-between">
           <div className="absolute top-0 right-0 p-12 opacity-10 pointer-events-none text-white">
              <Shield size={180} />
           </div>
           <div className="relative z-10">
              <h4 className="text-xs font-black text-indigo-300 uppercase tracking-[0.3em] mb-8 font-heading">สรุปสิทธิ์ผู้ใช้งาน</h4>
              <div className="grid grid-cols-2 gap-4">
                 <div className="bg-white/5 p-5 rounded-3xl border border-white/10">
                    <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">แอดมิน</p>
                    <p className="text-3xl font-black text-white">{users.filter(u => u.role === 'ADMIN').length}</p>
                 </div>
                 <div className="bg-white/5 p-5 rounded-3xl border border-white/10">
                    <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">ครู</p>
                    <p className="text-3xl font-black text-white">{users.filter(u => u.role === 'TEACHER').length}</p>
                 </div>
                 <div className="bg-white/5 p-5 rounded-3xl border border-white/10 col-span-2">
                    <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">ผู้ปกครอง</p>
                    <p className="text-3xl font-black text-white">{users.filter(u => u.role === 'PARENT').length}</p>
                 </div>
              </div>
           </div>
        </div>
      </div>

      <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-8 bg-slate-50/50 border-b flex flex-col lg:flex-row items-center justify-between gap-6">
          <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-fit shrink-0">
