              )}

              {activeTab === 'PARENT' && (
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">รหัสนักเรียน (บุตรหลาน)</label>
                  <input type="text" required value={formData.studentId} onChange={(e) => setFormData({...formData, studentId: e.target.value})} className="w-full bg-slate-50 border-2 border-slate-100 focus:border-indigo-500 rounded-2xl px-5 py-4 font-black text-slate-900 outline-none transition-all" placeholder="ระบุรหัส 6 หลัก" />
                </div>
              )}

              <div className="flex gap-4 pt-6">
                <button type="button" onClick={() => setShowModal(null)} className="flex-1 py-5 bg-slate-100 text-slate-600 rounded-[24px] font-black uppercase text-xs tracking-widest hover:bg-slate-200 transition-all">ยกเลิก</button>
