import React, { useState, useEffect } from 'react';
import { StudyBlock, Student, AttendanceRecord, BehaviorRecord, PaymentRecord, Subject } from '../types';
import { 
  Calendar as CalendarIcon, 
  CheckCircle2, 
  Clock, 
  AlertCircle, 
  Info, 
  CalendarDays, 
  Plus, 
  Trash2, 
  Sun, 
  AlertTriangle, 
  Star, 
  Layers, 
  RefreshCw,
  X,
  Check,
  Database,
  CloudZap,
  Loader2,
  Table as TableIcon
} from 'lucide-react';

interface SystemSettingsProps {
  studyBlocks: StudyBlock[];
  setStudyBlocks: React.Dispatch<React.SetStateAction<StudyBlock[]>>;
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: BehaviorRecord[];
  payments: PaymentRecord[];
  subjects: Subject[];
}

const BLOCK_COLORS = [
  'bg-blue-600',
  'bg-indigo-600',
  'bg-purple-600',
  'bg-pink-600',
  'bg-emerald-600'
];

const BLOCK_TEXT_COLORS = [
  'text-blue-600',
  'text-indigo-600',
  'text-purple-600',
  'text-pink-600',
  'text-emerald-600'
];

const SystemSettings: React.FC<SystemSettingsProps> = ({ 
  studyBlocks, setStudyBlocks, students, attendance, behavior, payments, subjects 
}) => {
  const [newHolidayDate, setNewHolidayDate] = useState<Record<number, string>>({});
  const [deletingDate, setDeletingDate] = useState<{ blockId: number; date: string } | null>(null);
  const [googleScriptUrl, setGoogleScriptUrl] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<null | 'success' | 'error'>(null);

  useEffect(() => {
    const savedUrl = localStorage.getItem('cms_google_script_url');
    if (savedUrl) setGoogleScriptUrl(savedUrl);
  }, []);

  const handleSaveUrl = () => {
    localStorage.setItem('cms_google_script_url', googleScriptUrl);
    alert('บันทึก Web App URL เรียบร้อยแล้ว');
  };

  const handleSyncToSheets = async () => {
    if (!googleScriptUrl) {
      alert('กรุณาระบุ Google Apps Script Web App URL ก่อนทำการเชื่อมต่อ');
      return;
    }

    setIsSyncing(true);
    setSyncStatus(null);

    try {
      // Prepare data groups
      const morningAttendance = attendance.filter(a => a.type === 'MORNING');

      // Group Subject Attendance by Subject Code for separate sheets
      const subjectAttendanceGroups: Record<string, any[]> = {};
      attendance.filter(a => a.type === 'SUBJECT').forEach(rec => {
        const sub = subjects.find(s => s.id === rec.subjectId);
        const sheetName = sub ? `${sub.code}` : 'Unknown_Subject';
        if (!subjectAttendanceGroups[sheetName]) subjectAttendanceGroups[sheetName] = [];

        const student = students.find(s => s.id === rec.studentId);
        subjectAttendanceGroups[sheetName].push({
          date: rec.date,
          studentId: student?.studentId,
          name: student?.name,
          status: rec.status,
          remark: rec.remark || '',
          timestamp: rec.timestamp
        });
      });

      const payload = {
        students: students.map(s => ({
          studentId: s.studentId,
          name: s.name,
          level: s.level,
          department: s.department,
          room: s.room,
          score: s.behaviorScore
        })),
        morning: morningAttendance.map(a => ({
          date: a.date,
          studentId: students.find(s => s.id === a.studentId)?.studentId,
          name: students.find(s => s.id === a.studentId)?.name,
          status: a.status,
          timestamp: a.timestamp
        })),
        behavior: behavior.map(b => ({
          date: b.date,
          studentId: students.find(s => s.id === b.studentId)?.studentId,
          name: students.find(s => s.id === b.studentId)?.name,
          type: b.type,
          score: b.score,
          reason: b.reason,
          by: b.recordedBy
        })),
        payments: payments.map(p => ({
          date: p.date,
          studentId: students.find(s => s.id === p.studentId)?.studentId,
          name: students.find(s => s.id === p.studentId)?.name,
          amount: p.amount,
          method: p.method,
          by: p.recordedBy
        })),
        subjects: subjectAttendanceGroups // Key-Value pair for dynamic sheets
      };

      // In a real environment, this would be a fetch to the script URL
      // Since we can't actually hit external servers in this sandbox without configuration, 
      // we simulate the success response.
      console.log('Sending payload to Google Sheets:', payload);

      const response = await fetch(googleScriptUrl, {
        method: 'POST',
        mode: 'no-cors', // standard for GAS
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      // Simulation delay
      await new Promise(resolve => setTimeout(resolve, 2000));

      setSyncStatus('success');
      setTimeout(() => setSyncStatus(null), 3000);
    } catch (error) {
      console.error('Sync failed:', error);
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  const addBusinessDays = (startDate: Date, days: number): Date => {
    let result = new Date(startDate);
    let addedDays = 0;
    while (addedDays < days - 1) {
      result.setDate(result.getDate() + 1);
      if (result.getDay() !== 0 && result.getDay() !== 6) {
        addedDays++;
      }
    }
    return result;
  };

  const formatDate = (date: Date) => date.toISOString().split('T')[0];

  const handleAutoCalculateDates = () => {
    if (!confirm('คุณต้องการรีเซ็ตวันเริ่ม-สิ้นสุดของทุกบล็อกให้เป็น 18 วันทำการ (เริ่มวันนี้) ใช่หรือไม่?')) return;

    const newBlocks: StudyBlock[] = [];
    let currentStart = new Date();

    if (currentStart.getDay() === 0) currentStart.setDate(currentStart.getDate() + 1);
    else if (currentStart.getDay() === 6) currentStart.setDate(currentStart.getDate() + 2);

    studyBlocks.forEach((oldBlock, idx) => {
      const end = addBusinessDays(currentStart, 18);
      newBlocks.push({
        ...oldBlock,
        startDate: formatDate(currentStart),
        endDate: formatDate(end),
      });

      let nextStart = new Date(end);
      nextStart.setDate(nextStart.getDate() + 1);
      while (nextStart.getDay() === 0 || nextStart.getDay() === 6) {
        nextStart.setDate(nextStart.getDate() + 1);
      }
      currentStart = nextStart;
    });

    setStudyBlocks(newBlocks);
  };

  const countWeekdays = (startStr: string, endStr: string) => {
    if (!startStr || !endStr) return 0;
    const start = new Date(startStr);
    const end = new Date(endStr);
    let count = 0;
    const curDate = new Date(start.getTime());
    while (curDate <= end) {
      const dayOfWeek = curDate.getDay();
      if (dayOfWeek !== 0 && dayOfWeek !== 6) count++;
      curDate.setDate(curDate.getDate() + 1);
    }
    return count;
  };

  const handleUpdateBlock = (id: number, field: keyof StudyBlock, value: any) => {
    setStudyBlocks(prev => prev.map(block => 
      block.id === id ? { ...block, [field]: value } : block
    ));
  };

  const handleAddHoliday = (blockId: number) => {
    const date = newHolidayDate[blockId];
    if (!date) return;

    setStudyBlocks(prev => prev.map(block => {
      if (block.id === blockId) {
        const currentHolidays = Array.isArray(block.holidays) ? block.holidays : [];
        if (currentHolidays.includes(date)) return block;
        return { ...block, holidays: [...currentHolidays, date].sort() };
      }
      return block;
    }));
    setNewHolidayDate(prev => ({ ...prev, [blockId]: '' }));
  };

  const processRemoveHoliday = (blockId: number, date: string) => {
    setStudyBlocks(prev => prev.map(block => {
      if (block.id === blockId) {
        const currentHolidays = Array.isArray(block.holidays) ? block.holidays : [];
        return { 
          ...block, 
          holidays: currentHolidays.filter(d => d !== date) 
        };
      }
      return block;
    }));
    setDeletingDate(null);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20 max-w-7xl mx-auto">
      {/* Google Sheets Sync Panel */}
      <div className="bg-white p-8 md:p-12 rounded-[48px] border border-slate-200 shadow-sm relative overflow-hidden">
        <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-green-50 rounded-full blur-3xl opacity-50" />
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-6 mb-10 relative z-10">
          <div className="flex items-center gap-6">
            <div className="p-5 bg-green-600 rounded-[24px] text-white shadow-2xl">
              <Database size={32} />
            </div>
            <div>
              <h2 className="text-3xl font-black text-slate-900 tracking-tight font-heading">เชื่อมต่อ Google Sheets</h2>
              <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">สำรองประวัติเช็คชื่อ พฤติกรรม และการเงิน ลงชีตแยกตามวิชา</p>
            </div>
          </div>
          <button 
            onClick={handleSyncToSheets}
            disabled={isSyncing}
            className={`flex items-center gap-3 px-10 py-5 rounded-2xl font-black text-sm uppercase tracking-widest shadow-xl transition-all font-heading ${
              syncStatus === 'success' ? 'bg-green-600 text-white scale-105' :
              isSyncing ? 'bg-slate-200 text-slate-500 cursor-not-allowed' :
              'bg-slate-900 text-white hover:bg-black active:scale-95'
            }`}
          >
            {isSyncing ? <Loader2 size={20} className="animate-spin" /> : syncStatus === 'success' ? <CheckCircle2 size={20} /> : <CloudZap size={20} />}
            {isSyncing ? 'กำลังส่งข้อมูล...' : syncStatus === 'success' ? 'บันทึกสำเร็จ' : 'Sync ข้อมูลทั้งหมด'}
          </button>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 relative z-10">
          <div className="space-y-4">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">Apps Script Deployment URL</label>
            <div className="flex gap-3">
              <input 
                type="text" 
                value={googleScriptUrl}
                onChange={(e) => setGoogleScriptUrl(e.target.value)}
                placeholder="https://script.google.com/macros/s/.../exec"
                className="flex-1 bg-slate-50 border-2 border-slate-100 focus:border-green-500 rounded-2xl px-6 py-4 font-bold text-slate-900 outline-none transition-all"
              />
              <button onClick={handleSaveUrl} className="px-6 py-4 bg-slate-100 text-slate-600 rounded-2xl font-black text-xs uppercase hover:bg-slate-200 transition-all">Save URL</button>
            </div>
          </div>
          <div className="p-6 bg-slate-50 rounded-[32px] border border-slate-100">
            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
              <TableIcon size={14} /> โครงสร้างการจัดเก็บข้อมูล
            </h4>
            <div className="grid grid-cols-2 gap-3 text-[10px] font-bold text-slate-600">
               <div className="flex items-center gap-2 bg-white p-3 rounded-xl border border-slate-100">
                  <div className="w-1.5 h-1.5 bg-green-500 rounded-full" /> ชีตหลัก: Students, Morning_Attendance
               </div>
               <div className="flex items-center gap-2 bg-white p-3 rounded-xl border border-slate-100">
                  <div className="w-1.5 h-1.5 bg-blue-500 rounded-full" /> แยกชีตตามวิชา: {subjects.slice(0,2).map(s => s.code).join(', ')}...
               </div>
               <div className="flex items-center gap-2 bg-white p-3 rounded-xl border border-slate-100">
                  <div className="w-1.5 h-1.5 bg-red-500 rounded-full" /> ชีตพฤติกรรม: Behavior_Records
               </div>
               <div className="flex items-center gap-2 bg-white p-3 rounded-xl border border-slate-100">
                  <div className="w-1.5 h-1.5 bg-amber-500 rounded-full" /> ชีตการเงิน: Tuition_Payments
               </div>
            </div>
          </div>
        </div>
      </div>

