---

### Step 2: Google Apps Script Code

Copy the code below and paste it into your Google Sheet (Tools > Extensions > Apps Script).

**Behavior**:
1. It automatically creates sheets if they don't exist.
2. It **overwrites** the current data to keep the sheet as an exact backup of your system.
3. It creates separate sheets for every Subject Code provided in the `subjects` payload.

```javascript
/**
 * CMS Google Sheets Sync Backend
 * - บันทึกข้อมูลทะเบียนนักเรียน
 * - บันทึกประวัติการเช็คชื่อหน้าเสาธง
 * - บันทึกประวัติพฤติกรรม
 * - บันทึกประวัติการเงิน
 * - บันทึกประวัติการเข้าเรียน (แยกตามรหัสวิชา)
 */

function doPost(e) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var data = JSON.parse(e.postData.contents);

  // 1. Sync Students Sheet
  updateSheet(ss, "Students", ["รหัสประจำตัว", "ชื่อ-นามสกุล", "ระดับชั้น", "แผนกวิชา", "ห้อง", "คะแนนพฤติกรรม"], data.students);

  // 2. Sync Morning Attendance Sheet
  updateSheet(ss, "Morning_Attendance", ["วันที่", "รหัสนักเรียน", "ชื่อ-นามสกุล", "ระดับ", "แผนก", "สถานะ", "วันเวลาที่บันทึก"], data.morning);

  // 3. Sync Behavior Records Sheet
  updateSheet(ss, "Behavior_Records", ["วันที่", "รหัสนักเรียน", "ชื่อ-นามสกุล", "ประเภท", "คะแนน", "เหตุผล", "ผู้บันทึก"], data.behavior);

  // 4. Sync Tuition Payments Sheet
  updateSheet(ss, "Tuition_Payments", ["วันที่", "รหัสนักเรียน", "ชื่อ-นามสกุล", "ยอดเงิน", "วิธีชำระ", "ผู้บันทึก"], data.payments);

  // 5. Sync Subject Attendance (Dynamic Sheets)
  if (data.subjects) {
    for (var subjectCode in data.subjects) {
      var subjectData = data.subjects[subjectCode].map(function(item) {
        return [item.date, item.studentId, item.name, item.level, item.status, item.remark, item.timestamp];
      });
      updateSheet(ss, "Subject_" + subjectCode, ["วันที่", "รหัสนักเรียน", "ชื่อ-นามสกุล", "ระดับ", "สถานะ", "หมายเหตุ", "วันเวลาที่บันทึก"], subjectData);
    }
  }

  return ContentService.createTextOutput("Sync Completed Successfully")
    .setMimeType(ContentService.MimeType.TEXT);
}

function updateSheet(ss, sheetName, headers, rows) {
  var sheet = ss.getSheetByName(sheetName);
  if (!sheet) {
    sheet = ss.insertSheet(sheetName);
  }

  sheet.clear(); // Clear existing content for fresh backup
  sheet.getRange(1, 1, 1, headers.length).setValues([headers]).setFontWeight("bold").setBackground("#f3f4f6");

  if (rows && rows.length > 0) {
    sheet.getRange(2, 1, rows.length, headers.length).setValues(rows);
  }

  sheet.autoResizeColumns(1, headers.length);
}
```

### Installation Steps for the Sheet:
1.  Open a new Google Sheet.
2.  Go to **Extensions** -> **Apps Script**.
3.  Paste the code above and save (click the floppy disk icon).
4.  Click **Deploy** -> **New Deployment**.
5.  Select **Type: Web App**.
6.  Set **Execute as: Me**.
7.  Set **Who has access: Anyone** (This is required for the system to talk to the script without a complex Google Auth flow).
8.  Click **Deploy**, authorize permissions, and **copy the Web App URL**.
9.  Open your CMS, go to **ตั้งค่าบล็อกเรียน**, paste the URL into the **Google Apps Script Web App URL** box, and click **Save**.
10. Click **Sync ข้อมูลทั้งหมด** to test.

