### Google Apps Script ที่ต้องแก้ไข (แทนที่ของเดิมทั้งหมด):
ก๊อปปี้โค้ดนี้ไปวางใน Apps Script เพื่อรองรับทั้งการบันทึก (POST) และการดึงข้อมูล (GET)

```javascript
/**
 * CMS Google Sheets Cloud DB Engine
 * รองรับการดึงข้อมูลล่าสุด (GET) และการบันทึกแบบ Real-time (POST)
 */

function doGet(e) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var action = e.parameter.action;

  if (action === "getAllData") {
    var data = {
      students: getSheetData(ss, "Students"),
      attendance: getSheetData(ss, "Morning_Attendance"), // รวม Subject เข้าไปด้วยได้ หรือแยก
      behavior: getSheetData(ss, "Behavior_Records"),
      payments: getSheetData(ss, "Tuition_Payments"),
      subjects: getSheetData(ss, "Subjects_Config")
    };

    // ดึงข้อมูล Attendance จากชีตรายวิชาทั้งหมดด้วย
    var allSheets = ss.getSheets();
    allSheets.forEach(function(s) {
      if (s.getName().indexOf("Subject_") === 0) {
        var subData = getSheetData(ss, s.getName());
        data.attendance = data.attendance.concat(subData.map(function(r) {
          r.type = "SUBJECT";
          r.subjectId = s.getName().replace("Subject_", "");
          return r;
        }));
      }
    });

    return ContentService.createTextOutput(JSON.stringify(data))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

function doPost(e) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var payload = JSON.parse(e.postData.contents);
  var action = payload.action;

  if (action === "syncData") {
    var type = payload.type;
    var data = payload.data;

    if (type === "students") {
      updateSheet(ss, "Students", ["รหัสประจำตัว", "ชื่อ-นามสกุล", "ระดับชั้น", "แผนกวิชา", "ห้อง", "คะแนนพฤติกรรม"], data.map(s => [s.studentId, s.name, s.level, s.department, s.room, s.behaviorScore]));
    } else if (type === "attendance") {
      // แยกบันทึก Morning และ Subject
      var morning = data.filter(a => a.type === "MORNING").map(a => [a.date, a.studentId, "", "", "", a.status, a.timestamp]);
      updateSheet(ss, "Morning_Attendance", ["วันที่", "รหัสนักเรียน", "ชื่อ-นามสกุล", "ระดับ", "แผนก", "สถานะ", "เวลาบันทึก"], morning);

      // บันทึกแยกรายวิชา
      var subjects = {};
      data.filter(a => a.type === "SUBJECT").forEach(a => {
        if (!subjects[a.subjectId]) subjects[a.subjectId] = [];
        subjects[a.subjectId].push([a.date, a.studentId, "", "", a.status, a.remark, a.timestamp]);
      });
      for (var code in subjects) {
        updateSheet(ss, "Subject_" + code, ["วันที่", "รหัสนักเรียน", "ชื่อ-นามสกุล", "ระดับ", "สถานะ", "หมายเหตุ", "เวลาบันทึก"], subjects[code]);
      }
    } else if (type === "behavior") {
      updateSheet(ss, "Behavior_Records", ["วันที่", "รหัสนักเรียน", "ชื่อ-นามสกุล", "ประเภท", "คะแนน", "เหตุผล", "ผู้บันทึก"], data.map(b => [b.date, b.studentId, "", b.type, b.score, b.reason, b.recordedBy]));
    } else if (type === "payments") {
      updateSheet(ss, "Tuition_Payments", ["วันที่", "รหัสนักเรียน", "ชื่อ-นามสกุล", "ยอดเงิน", "วิธีชำระ", "ผู้บันทึก"], data.map(p => [p.date, p.studentId, "", p.amount, p.method, p.recordedBy]));
    }
  }

  return ContentService.createTextOutput("Success").setMimeType(ContentService.MimeType.TEXT);
}

function getSheetData(ss, name) {
  var sheet = ss.getSheetByName(name);
  if (!sheet) return [];
  var vals = sheet.getDataRange().getValues();
  if (vals.length < 2) return [];
  var headers = vals[0];
  var data = [];
  for (var i = 1; i < vals.length; i++) {
    var obj = {};
    for (var j = 0; j < headers.length; j++) {
      obj[headers[j]] = vals[i][j];
    }
    data.push(obj);
  }
  return data;
}

function updateSheet(ss, name, headers, rows) {
  var sheet = ss.getSheetByName(name) || ss.insertSheet(name);
  sheet.clear();
  sheet.getRange(1, 1, 1, headers.length).setValues([headers]).setFontWeight("bold");
  if (rows.length > 0) {
    sheet.getRange(2, 1, rows.length, headers.length).setValues(rows);
  }
}
```

**วิธีใช้งาน:**
1.  นำโค้ด Apps Script ใหม่ไปวางทับอันเดิม
2.  **Deploy** ใหม่เป็นเวอร์ชันล่าสุด (สำคัญมาก)
3.  นำ URL มาใส่ในแอปตรงหน้า **ตั้งค่าบล็อกเรียน**
4.  ตอนนี้ไม่ว่าคุณจะเปิดแอปจากมือถือ แท็บเล็ต หรือคอมพิวเตอร์ ข้อมูลจะถูกดึงมาจาก Google Sheets ทันทีที่เข้าสู่ระบบ และเมื่อมีการเปลี่ยนแปลง ข้อมูลจะอัปเดตกลับไปที่ Sheet ทันที ทำให้ทุกเครื่องซิงค์กันตลอดเวลาครับ!

