import React, { useState } from 'react';
import { StudyBlock } from '../types';
import { 
  Layers, 
  Sun, 
  Trash2, 
  X,
  CalendarDays
} from 'lucide-react';

interface SystemSettingsProps {
  studyBlocks: StudyBlock[];
  setStudyBlocks: (blocks: StudyBlock[]) => void;
}

const BLOCK_COLORS = ['bg-blue-600', 'bg-indigo-600', 'bg-purple-600', 'bg-pink-600', 'bg-emerald-600'];

const SystemSettings: React.FC<SystemSettingsProps> = ({ studyBlocks, setStudyBlocks }) => {
  const [deletingDate, setDeletingDate] = useState<{ blockId: number; date: string } | null>(null);

  const handleUpdateBlock = (id: number, field: keyof StudyBlock, value: any) => {
    const updated = studyBlocks.map(block => {
      if (block.id === id) {
        // หากตั้งค่า isActive เป็น true บล็อกอื่นต้องเป็น false
        if (field === 'isActive' && value === true) {
          return { ...block, [field]: value };
        }
        return { ...block, [field]: value };
      }
      if (field === 'isActive' && value === true) {
        return { ...block, isActive: false };
      }
      return block;
    });
    setStudyBlocks(updated);
  };

  const processRemoveHoliday = (blockId: number, date: string) => {
    const updated = studyBlocks.map(block => block.id === blockId ? { ...block, holidays: block.holidays.filter(d => d !== date) } : block);
    setStudyBlocks(updated);
    setDeletingDate(null);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20 max-w-7xl mx-auto">
      <div className="bg-white p-8 md:p-12 rounded-[48px] border border-slate-200 shadow-sm relative">
        <div className="flex items-center gap-6 mb-12">
          <div className="p-5 bg-slate-900 rounded-[24px] text-white shadow-2xl">
            <Layers size={32} />
          </div>
          <div>
            <h2 className="text-3xl font-black text-slate-900 tracking-tight font-heading">ตั้งค่าบล็อกเรียน (Study Blocks)</h2>
            <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">กำหนดช่วงเวลาเรียนและวันหยุดรายบล็อกสำหรับการคำนวณคะแนน</p>
          </div>
        </div>

        <div className="grid grid-cols-1 gap-12">
          {studyBlocks.map((block, idx) => (
            <div key={block.id} className={`p-8 md:p-10 rounded-[40px] border-2 transition-all ${block.isActive ? 'border-blue-500 bg-blue-50/20' : 'border-slate-200 bg-white'}`}>
              <div className="flex flex-col xl:flex-row items-start xl:items-center gap-10">
                <div className={`w-20 h-20 rounded-3xl flex items-center justify-center font-black text-3xl shadow-2xl text-white ${BLOCK_COLORS[idx]}`}>
                  {block.id}
                </div>
                <div className="flex-1 space-y-4">
                   <div className="flex items-center justify-between">
                     <input type="text" value={block.name} onChange={(e) => handleUpdateBlock(block.id, 'name', e.target.value)} className="font-black text-slate-900 text-2xl outline-none focus:ring-0 p-0 w-64 font-heading bg-transparent" />
                     <button 
                        onClick={() => handleUpdateBlock(block.id, 'isActive', !block.isActive)}
                        className={`px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${block.isActive ? 'bg-blue-600 text-white shadow-lg' : 'bg-slate-100 text-slate-400'}`}
                     >
                       {block.isActive ? 'กำลังใช้งาน' : 'คลิกเพื่อใช้งาน'}
                     </button>
                   </div>
                   <div className="flex flex-wrap gap-4">
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">วันที่เริ่มต้น</label>
                        <input type="date" value={block.startDate} onChange={(e) => handleUpdateBlock(block.id, 'startDate', e.target.value)} className="bg-white border-2 border-slate-100 rounded-xl px-4 py-2 font-bold text-sm outline-none" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">วันที่สิ้นสุด</label>
                        <input type="date" value={block.endDate} onChange={(e) => handleUpdateBlock(block.id, 'endDate', e.target.value)} className="bg-white border-2 border-slate-100 rounded-xl px-4 py-2 font-bold text-sm outline-none" />
                      </div>
                   </div>
                </div>
              </div>

              <div className="mt-8 pt-8 border-t border-slate-100">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2 font-heading">
                  <Sun size={14} className="text-amber-500" /> วันหยุดพิเศษในบล็อกนี้ (ถือเป็นวันมาเรียน)
                </h4>
                <div className="flex flex-wrap gap-3">
                  {block.holidays.map(date => {
                    const isConfirming = deletingDate?.blockId === block.id && deletingDate?.date === date;
                    return (
                      <div key={date} className={`flex items-center gap-3 pl-5 pr-2 py-3 rounded-2xl border-2 font-bold text-sm transition-all ${isConfirming ? 'bg-red-600 border-red-700 text-white shadow-xl' : 'bg-slate-50 border-slate-100 text-slate-700'}`}>
                        <span>{new Date(date).toLocaleDateString('th-TH', { dateStyle: 'long' })}</span>
                        {isConfirming ? (
                          <div className="flex gap-1 animate-in slide-in-from-right-2">
                             <button onClick={() => setDeletingDate(null)} className="p-2 hover:bg-white/10 rounded-lg transition-all"><X size={16} /></button>
                             <button onClick={() => processRemoveHoliday(block.id, date)} className="p-2 hover:bg-white/10 rounded-lg transition-all font-black text-[10px] uppercase">ยืนยัน</button>
                          </div>
                        ) : (
                          <button onClick={() => setDeletingDate({ blockId: block.id, date })} className="p-2 text-slate-300 hover:text-red-600 transition-all"><Trash2 size={16} /></button>
                        )}
                      </div>
                    );
                  })}
                  <div className="relative group">
                    <CalendarDays className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 pointer-events-none" size={16} />
                    <input 
                      type="date" 
                      onChange={(e) => {
                        if (!e.target.value) return;
                        handleUpdateBlock(block.id, 'holidays', [...block.holidays, e.target.value]);
                        e.target.value = '';
                      }}
                      className="bg-white border-2 border-dashed border-slate-200 rounded-2xl pl-12 pr-5 py-3 text-xs font-bold outline-none hover:border-blue-400 transition-all cursor-pointer" 
                    />
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default SystemSettings;

import React, { useState, useEffect } from 'react';
import { Student, AttendanceRecord, BehaviorRecord, PaymentRecord, Subject } from '../types';
import { 
  Database,
  Zap,
  Loader2,
  Table as TableIcon,
  CheckCircle2,
  CloudZap,
  Server
} from 'lucide-react';

interface CloudConfigProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: BehaviorRecord[];
  payments: PaymentRecord[];
  subjects: Subject[];
}

const CloudConfig: React.FC<CloudConfigProps> = ({ 
  students, attendance, behavior, payments, subjects 
}) => {
  const [googleScriptUrl, setGoogleScriptUrl] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncStatus, setSyncStatus] = useState<null | 'success' | 'error'>(null);

  useEffect(() => {
    const savedUrl = localStorage.getItem('cms_google_script_url');
    if (savedUrl) setGoogleScriptUrl(savedUrl);
  }, []);

  const handleSaveUrl = () => {
    localStorage.setItem('cms_google_script_url', googleScriptUrl);
    alert('บันทึก Web App URL เรียบร้อยแล้ว');
  };

  const handleSyncToSheets = async () => {
    if (!googleScriptUrl) {
      alert('กรุณาระบุ Google Apps Script Web App URL ก่อนทำการเชื่อมต่อ');
      return;
    }

    setIsSyncing(true);
    setSyncStatus(null);

    try {
      const morningAttendance = attendance.filter(a => a.type === 'MORNING');
      const subjectGroups: Record<string, any[]> = {};
      attendance.filter(a => a.type === 'SUBJECT').forEach(rec => {
        const sub = subjects.find(s => s.id === rec.subjectId);
        const sheetName = sub ? sub.code : 'Unknown';
        if (!subjectGroups[sheetName]) subjectGroups[sheetName] = [];
        const student = students.find(s => s.id === rec.studentId);
        subjectGroups[sheetName].push({
          date: rec.date,
          studentId: student?.studentId,
          name: student?.name,
          level: student?.level,
          status: rec.status,
          remark: rec.remark || '',
          timestamp: rec.timestamp
        });
      });

      const payload = {
        action: 'syncData',
        type: 'all',
        students: students.map(s => [s.studentId, s.name, s.level, s.department, s.room, s.behaviorScore]),
        morning: morningAttendance.map(a => {
          const s = students.find(x => x.id === a.studentId);
          return [a.date, s?.studentId, s?.name, s?.level, s?.department, a.status, a.timestamp];
        }),
        behavior: behavior.map(b => {
          const s = students.find(x => x.id === b.studentId);
          return [b.date, s?.studentId, s?.name, b.type, b.score, b.reason, b.recordedBy];
        }),
        payments: payments.map(p => {
          const s = students.find(x => x.id === p.studentId);
          return [p.date, s?.studentId, s?.name, p.amount, p.method, p.recordedBy];
        }),
        subjects: subjectGroups
      };

      await fetch(googleScriptUrl, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      await new Promise(resolve => setTimeout(resolve, 1500));
      setSyncStatus('success');
      setTimeout(() => setSyncStatus(null), 3000);
    } catch (error) {
      console.error('Sync failed:', error);
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20 max-w-4xl mx-auto">
      <div className="bg-white p-10 md:p-14 rounded-[48px] border border-slate-200 shadow-sm relative overflow-hidden">
        <div className="absolute top-0 right-0 -mr-16 -mt-16 w-64 h-64 bg-emerald-50 rounded-full blur-3xl opacity-50" />

        <div className="flex items-center gap-6 mb-12 relative z-10">
          <div className="p-5 bg-emerald-600 rounded-[24px] text-white shadow-2xl">
            <Server size={32} />
          </div>
          <div>
            <h2 className="text-3xl font-black text-slate-900 tracking-tight font-heading uppercase">Cloud Database Sync</h2>
            <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">ตั้งค่าการเชื่อมต่อ Google Sheets เพื่อซิงค์ข้อมูลระหว่างเครื่อง</p>
          </div>
        </div>

        <div className="space-y-10 relative z-10">
          <div className="p-8 bg-slate-50 rounded-[32px] border border-slate-100 space-y-6">
            <div className="space-y-4">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">Google Apps Script Web App URL</label>
              <div className="flex flex-col sm:flex-row gap-3">
                <input 
                  type="text" 
                  value={googleScriptUrl}
                  onChange={(e) => setGoogleScriptUrl(e.target.value)}
                  placeholder="https://script.google.com/macros/s/.../exec"
                  className="flex-1 bg-white border-2 border-slate-100 focus:border-emerald-500 rounded-2xl px-6 py-4 font-bold text-slate-900 outline-none transition-all"
                />
                <button onClick={handleSaveUrl} className="px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-xs uppercase hover:bg-black transition-all shadow-lg font-heading">Save URL</button>
              </div>
            </div>

            <div className="pt-4">
               <button 
                  onClick={handleSyncToSheets}
                  disabled={isSyncing}
                  className={`w-full flex items-center justify-center gap-4 py-6 rounded-3xl font-black text-sm uppercase tracking-widest shadow-2xl transition-all font-heading ${
                    syncStatus === 'success' ? 'bg-green-600 text-white' :
                    isSyncing ? 'bg-slate-200 text-slate-500 cursor-not-allowed' :
                    'bg-emerald-600 text-white hover:bg-emerald-700 active:scale-95'
                  }`}
                >
                  {isSyncing ? <Loader2 size={24} className="animate-spin" /> : syncStatus === 'success' ? <CheckCircle2 size={24} /> : <CloudZap size={24} />}
                  {isSyncing ? 'กำลังส่งข้อมูลไปคลาวด์...' : syncStatus === 'success' ? 'ซิงค์ข้อมูลสำเร็จ' : 'Sync All Data to Google Sheets Now'}
                </button>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="p-6 bg-white border border-slate-100 rounded-[32px] shadow-sm flex items-start gap-4">
               <div className="p-3 bg-blue-50 text-blue-600 rounded-xl"><TableIcon size={20} /></div>
               <div>
                  <h4 className="font-black text-slate-900 text-sm uppercase font-heading mb-1">Sheet แยกรายวิชา</h4>
                  <p className="text-[10px] font-bold text-slate-500">ระบบจะสร้างชีตแยกตามรหัสวิชาให้อัตโนมัติ (เช่น IT30201)</p>
               </div>
            </div>
            <div className="p-6 bg-white border border-slate-100 rounded-[32px] shadow-sm flex items-start gap-4">
               <div className="p-3 bg-green-50 text-green-600 rounded-xl"><Database size={20} /></div>
               <div>
                  <h4 className="font-black text-slate-900 text-sm uppercase font-heading mb-1">รองรับการเข้าถึงพร้อมกัน</h4>
                  <p className="text-[10px] font-bold text-slate-500">เมื่อตั้งค่า URL แล้ว ทุกเครื่องจะดึงข้อมูลจากชีตเดียวกันเสมอ</p>
               </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

