const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);
  const [copied, setCopied] = useState(false);
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  const [bankInfo, setBankInfo] = useState({
    bankName: 'ธนาคารกรุงไทย (Krungthai)',
    accountNo: '012-3-45678-9',
    accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
  });

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
    const savedBank = localStorage.getItem('cms_bank_info');
    if (savedBank) setBankInfo(JSON.parse(savedBank));
  }, []);

  const handleCopy = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  const morningAttendance = useMemo(() => attendance.filter(a => a.type === 'MORNING'), [attendance]);

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = morningAttendance.filter(a => 
      a.studentId === studentId && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    return Number((( (presentDays) * 5) / 18).toFixed(2));
  };

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudentsBase
      .map(s => ({ ...s, morningScore: getMorningScore(s.id) }))
      .filter(s => s.morningScore < 3.0)
      .sort((a,b) => a.morningScore - b.morningScore)
      .slice(0, 6)
  , [filteredStudentsBase, morningAttendance, studyBlocks]);

  const chartData = useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const present = morningAttendance.filter(a => a.date === date && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length;
      return {
        name: new Date(date).toLocaleDateString('th-TH', { weekday: 'short' }),
        fullDate: date,
        value: present
      };
    });
  }, [morningAttendance, filteredStudentsBase]);

  const getFinancialStatus = (student: Student) => {
    const config = tuitionConfigs.find(c => c.level === student.level && c.department === student.department);
    if (!config) return { amount: 0, paid: 0, status: 'N/A', remaining: 0 };
    const paid = paymentRecords.filter(p => p.studentId === student.id).reduce((sum, p) => sum + p.amount, 0);
    return {
      amount: config.amount,
      paid: paid,
      remaining: Math.max(0, config.amount - paid),
      status: paid >= config.amount ? 'PAID' : paid > 0 ? 'PARTIAL' : 'PENDING'
    };
  };

  if (user.role === 'PARENT' || viewingStudentId) {
