import React, { useState, useEffect, useMemo } from 'react';
import { Student, AttendanceRecord, AttendanceStatus, ThaiLevel, Department } from '../types';
import { STATUS_LABELS } from '../constants';
import { 
  Search, Save, CheckCircle2, History, ClipboardCheck, 
  MessageSquare, Share2, Calendar, X, Loader2, Sun
} from 'lucide-react';

interface MorningAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
}

const MorningAttendance: React.FC<MorningAttendanceProps> = ({ 
  students, 
  attendanceRecords, 
  setAttendanceRecords
}) => {
  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level as string))).sort((a, b) => (a as string).localeCompare(b as string)), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department as string))).sort((a, b) => (a as string).localeCompare(b as string)), [students]);
  const availableRooms = useMemo(() => Array.from(new Set(students.map(s => s.room as string))).sort((a, b) => parseInt(a as string) - parseInt(b as string)), [students]);

  const [level, setLevel] = useState<string>(availableLevels[0] || '');
  const [dept, setDept] = useState<string>(availableDepts[0] || '');
  const [room, setRoom] = useState<string>(availableRooms[0] || '');

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedHistoryDate, setSelectedHistoryDate] = useState<string>('');
  const [currentSession, setCurrentSession] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaving, setIsSaving] = useState(false);
  const [isSaved, setIsSaved] = useState(false);
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');

  useEffect(() => {
    const rawDate = new Date().toISOString().split('T')[0];
    const todayRecords = attendanceRecords.filter(r => r.date === rawDate && r.type === 'MORNING');
    const sessionMap: Record<string, AttendanceStatus> = {};
    const remarkMap: Record<string, string> = {};
    todayRecords.forEach(r => {
      sessionMap[r.studentId] = r.status;
      if (r.remark) remarkMap[r.studentId] = r.remark;
    });
    setCurrentSession(sessionMap);
    setRemarks(remarkMap);
  }, [level, dept, room, attendanceRecords]);

  const filteredStudents = students.filter(s => 
    s.level === level && s.department === dept && s.room === room &&
    (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm))
  );

  const historyRecords = useMemo(() => {
    return attendanceRecords.filter(record => {
      const student = students.find(s => s.id === record.studentId);
      const matchesFilter = record.type === 'MORNING' && student?.level === level && student?.department === dept && student?.room === room;
      const matchesDate = selectedHistoryDate ? record.date === selectedHistoryDate : true;
      return matchesFilter && matchesDate;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [attendanceRecords, students, level, dept, room, selectedHistoryDate]);

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setCurrentSession(prev => ({ ...prev, [studentId]: status }));
    setIsSaved(false);
  };

  const handleSave = async () => {
    setIsSaving(true);
    await new Promise(resolve => setTimeout(resolve, 600));
    const rawDate = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');
    const newRecordsBatch: AttendanceRecord[] = filteredStudents.map(s => ({
      id: `MORNING_${rawDate}_${s.id}`,
      studentId: s.id,
      date: rawDate,
      type: 'MORNING',
      status: currentSession[s.id] || 'ABSENT',
      remark: remarks[s.id] || '',
      timestamp: timestamp
    }));
    setAttendanceRecords(prev => {
      const studentIds = filteredStudents.map(s => s.id);
      const otherRecords = prev.filter(r => !(r.date === rawDate && r.type === 'MORNING' && studentIds.includes(r.studentId)));
      return [...otherRecords, ...newRecordsBatch];
    });
    setIsSaving(false);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setCurrentSession(prev => ({ ...prev, ...newBatch }));
    setIsSaved(false);
  };

  const shareToLine = () => {
    const rawDate = new Date().toLocaleDateString('th-TH', { dateStyle: 'long' });
    let text = `รายงานการเข้าแถวหน้าเสาธง\nประจำวันที่: ${rawDate}\nชั้น: ${level} แผนก: ${dept} ห้อง: ${room}\n\n`;

    const absents = filteredStudents.filter(s => currentSession[s.id] === 'ABSENT');
    const lates = filteredStudents.filter(s => currentSession[s.id] === 'LATE');
    const leaves = filteredStudents.filter(s => currentSession[s.id] === 'BUSINESS_LEAVE' || currentSession[s.id] === 'SICK_LEAVE');

    text += `✅ มาเรียน: ${filteredStudents.length - absents.length - leaves.length} คน\n`;
    text += `❌ ขาดเรียน: ${absents.length} คน\n`;
    text += `⏰ มาสาย: ${lates.length} คน\n`;
    text += `📝 ลา: ${leaves.length} คน\n\n`;

    if (absents.length > 0) {
      text += `รายชื่อนักเรียนที่ขาดเรียน:\n`;
      absents.forEach((s, idx) => {
        text += `${idx + 1}. ${s.name} (${s.studentId})\n`;
      });
    }

    const url = `https://line.me/R/msg/text/?${encodeURIComponent(text)}`;
    window.open(url, '_blank');
  };

  return (
    <div className="space-y-6 md:space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
        <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-full md:w-fit">
          <button onClick={() => setViewMode('checkin')} className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-6 md:px-8 py-3 rounded-xl text-[11px] md:text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><ClipboardCheck size={18} /> เช็คชื่อวันนี้</button>
          <button onClick={() => setViewMode('history')} className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-6 md:px-8 py-3 rounded-xl text-[11px] md:text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><History size={18} /> ประวัติ</button>
        </div>

        {viewMode === 'checkin' && (
          <button 
            onClick={shareToLine}
            className="w-full md:w-auto flex items-center justify-center gap-2 px-6 py-3 bg-[#06C755] text-white rounded-xl text-[11px] md:text-sm font-black shadow-lg hover:bg-green-600 transition-all font-heading uppercase"
          >
            <Share2 size={18} /> แชร์สรุปเข้า LINE
          </button>
        )}
      </div>

      <div className="bg-white p-5 md:p-8 rounded-[28px] md:rounded-[32px] border border-slate-200 shadow-sm">
        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4 md:gap-6">
          <div className="space-y-1.5">
            <label className="text-[9px] md:text-[10px] font-black text-slate-500 uppercase tracking-widest">ระดับชั้น</label>
            <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-3 py-2.5 md:px-4 md:py-3 font-bold text-xs md:text-sm text-slate-900 outline-none transition-all">
              {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[9px] md:text-[10px] font-black text-slate-500 uppercase tracking-widest">แผนก</label>
            <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-3 py-2.5 md:px-4 md:py-3 font-bold text-xs md:text-sm text-slate-900 outline-none transition-all">
              {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[9px] md:text-[10px] font-black text-slate-500 uppercase tracking-widest">ห้อง</label>
            <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-3 py-2.5 md:px-4 md:py-3 font-bold text-xs md:text-sm text-slate-900 outline-none transition-all">
              {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
            </select>
          </div>
          <div className="col-span-2 md:col-span-1 lg:col-span-2 space-y-1.5">
            <label className="text-[9px] md:text-[10px] font-black text-slate-500 uppercase tracking-widest">
              {viewMode === 'checkin' ? 'ค้นหารายชื่อ' : 'วันที่'}
            </label>
            {viewMode === 'checkin' ? (
              <div className="relative">
                <Search className="absolute left-3 md:left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อ-รหัส..." className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl pl-10 md:pl-12 pr-4 py-2.5 md:py-3 font-bold text-xs md:text-sm text-slate-900 outline-none" />
              </div>
            ) : (
              <input type="date" value={selectedHistoryDate} onChange={(e) => setSelectedHistoryDate(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-2.5 md:py-3 font-bold text-xs md:text-sm text-slate-900 outline-none" />
            )}
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <>
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 px-1">
            <div className="flex gap-2.5">
              <button onClick={() => markAll('PRESENT')} className="flex-1 md:flex-none px-4 py-2.5 bg-green-50 text-green-700 rounded-xl text-[10px] font-black border border-green-200 uppercase tracking-widest hover:bg-green-100 transition-all">มาทุกคน</button>
              <button onClick={() => markAll('ABSENT')} className="flex-1 md:flex-none px-4 py-2.5 bg-red-50 text-red-700 rounded-xl text-[10px] font-black border border-red-200 uppercase tracking-widest hover:bg-red-100 transition-all">ขาดทุกคน</button>
            </div>
            <button 
              onClick={handleSave} 
              disabled={isSaving}
              className={`flex items-center justify-center gap-3 px-8 py-4 md:py-4.5 rounded-2xl text-white font-black transition-all shadow-xl active:scale-95 ${
                isSaved ? 'bg-green-600 shadow-green-200' : 
                isSaving ? 'bg-slate-400 cursor-not-allowed' : 'bg-slate-900'
              }`}
            >
              {isSaving ? <Loader2 size={20} className="animate-spin" /> : isSaved ? <CheckCircle2 size={20} /> : <Save size={20} />} 
              <span className="text-sm md:text-base">
                {isSaving ? 'กำลังบันทึก...' : isSaved ? 'บันทึกสำเร็จ' : 'บันทึกข้อมูลวันนี้'}
              </span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {filteredStudents.map((student, index) => (
              <div key={student.id} className="bg-white p-5 rounded-[24px] border border-slate-200 shadow-sm flex flex-col gap-5 group hover:border-blue-400 transition-all">
                <div className="flex items-start justify-between gap-3">
                  <div className="flex items-start gap-3">
                    <div className="w-10 h-10 md:w-12 md:h-12 bg-slate-900 rounded-xl flex items-center justify-center font-black text-sm md:text-base text-white shadow-lg shrink-0 group-hover:bg-blue-600 transition-colors">{index + 1}</div>
                    <div className="min-w-0">
                      <h4 className="font-black text-slate-900 text-sm md:text-base leading-tight truncate">{student.name}</h4>
                      <p className="text-[9px] text-slate-400 font-bold uppercase mt-1 tracking-tighter">ID: {student.studentId}</p>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-1">
                     <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${currentSession[student.id] ? STATUS_LABELS[currentSession[student.id]].color : 'bg-slate-50 text-slate-300'}`}>
                       {currentSession[student.id] ? STATUS_LABELS[currentSession[student.id]].label : 'ยังไม่ได้เช็ค'}
                     </span>
                  </div>
                </div>

                <div className="grid grid-cols-5 gap-1 md:gap-2">
                  {Object.entries(STATUS_LABELS).map(([key, value]) => (
                    <button 
                      key={key} 
                      onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} 
                      className={`flex flex-col items-center justify-center gap-1.5 p-2 rounded-xl border-2 transition-all ${currentSession[student.id] === key ? value.color + ' border-current' : 'bg-white border-slate-50 text-slate-300 hover:border-slate-100'}`}
                    >
                      <div className="scale-90 md:scale-100">{value.icon}</div>
                      <span className="text-[7px] md:text-[8px] font-black uppercase text-center leading-none tracking-tighter">{value.label}</span>
                    </button>
                  ))}
                </div>

                {currentSession[student.id] && currentSession[student.id] !== 'PRESENT' && (
                  <div className="relative animate-in slide-in-from-top-2">
                    <MessageSquare className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                    <input type="text" value={remarks[student.id] || ''} onChange={(e) => setRemarks(prev => ({ ...prev, [student.id]: e.target.value }))} placeholder="ระบุเหตุผล..." className="w-full bg-slate-50 border border-slate-100 rounded-xl pl-9 pr-4 py-2.5 font-bold text-slate-900 outline-none text-[11px] focus:border-blue-500 transition-all" />
                  </div>
                )}
              </div>
            ))}
            {filteredStudents.length === 0 && (
              <div className="col-span-full py-20 text-center text-slate-300 flex flex-col items-center gap-4">
                 <Sun size={48} className="opacity-10" />
                 <p className="text-xs font-black uppercase tracking-widest">ไม่พบรายชื่อนักเรียนในกลุ่มนี้</p>
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {historyRecords.length > 0 ? historyRecords.map((record) => {
            const student = students.find(s => s.id === record.studentId);
            return (
              <div key={record.id} className="bg-white p-5 rounded-[24px] border border-slate-200 flex flex-col gap-3 hover:shadow-md transition-all">
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-blue-50 text-blue-600 rounded-lg flex items-center justify-center"><ClipboardCheck size={16} /></div>
                    <div>
                       <p className="text-xs font-black text-slate-900">{student?.name}</p>
                       <p className="text-[9px] text-slate-400 font-bold">{record.date} • {record.timestamp.split(' ')[1]}</p>
                    </div>
                  </div>
                  <span className={`px-3 py-1 rounded-full text-[9px] font-black border uppercase ${STATUS_LABELS[record.status].color}`}>
                    {STATUS_LABELS[record.status].label}
                  </span>
                </div>
                {record.remark && (
                  <div className="p-2.5 bg-slate-50 rounded-lg text-[10px] font-bold text-slate-600 flex items-center gap-2">
                    <MessageSquare size={12} className="text-slate-300" /> {record.remark}
                  </div>
                )}
              </div>
            );
          }) : (
            <div className="col-span-full py-10 md:py-20 text-center text-slate-300 italic text-xs uppercase font-black">ไม่พบข้อมูล</div>
          )}
        </div>
      )}
    </div>
  );
};

export default MorningAttendance;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, AlertTriangle, User, Activity, Star, Clock, BarChart3, ShieldAlert,
  ChevronRight, CreditCard, MessageCircle, Bell,
  CheckCircle2, Copy, Check, Sun, ChevronUp, ArrowLeft, LayoutDashboard
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  notifications?: NotificationRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor }: any) => (
  <div className="bg-white p-5 md:p-7 rounded-[28px] md:rounded-[32px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all duration-300 group relative overflow-hidden h-full">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-1.5 md:space-y-2">
        <p className="text-slate-500 text-[9px] md:text-[10px] font-extrabold uppercase tracking-[0.15em] md:tracking-[0.2em] font-heading">{title}</p>
        <h3 className={`text-3xl md:text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-[10px] md:text-xs text-slate-400 font-bold leading-tight">{sub}</p>
      </div>
      <div className={`p-3 md:p-4 rounded-xl md:rounded-2xl ${color} text-white shadow-lg group-hover:scale-110 transition-transform`}>
        {React.cloneElement(icon as React.ReactElement, { size: 20 })}
      </div>
    </div>
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students, 
  attendance, 
  user, 
  studyBlocks,
  notifications = [],
  paymentRecords = [],
  tuitionConfigs = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [lineUrl, setLineUrl] = useState('');
  const [showPaymentDetails, setShowPaymentDetails] = useState(false);
  const [copied, setCopied] = useState(false);
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');

  useEffect(() => {
    setLineUrl(localStorage.getItem('cms_line_notify_url') || '');
  }, []);

  const morningAttendance = useMemo(() => attendance.filter(a => a.type === 'MORNING'), [attendance]);

  const filteredStudentsBase = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const getMorningScore = (studentId: string) => {
    const activeBlock = studyBlocks.find(b => b.isActive) || studyBlocks[0];
    if (!activeBlock) return 0;
    const presentDays = morningAttendance.filter(a => 
      a.studentId === studentId && a.status === 'PRESENT' &&
      a.date >= activeBlock.startDate && a.date <= activeBlock.endDate
    ).length;
    return Number((( (presentDays) * 5) / 18).toFixed(2));
  };

  const behaviorWatchlist = useMemo(() => 
    filteredStudentsBase.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudentsBase]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudentsBase
      .map(s => ({ ...s, morningScore: getMorningScore(s.id) }))
      .filter(s => s.morningScore < 3.0)
      .sort((a,b) => a.morningScore - b.morningScore)
      .slice(0, 6)
  , [filteredStudentsBase, morningAttendance, studyBlocks]);

  const chartData = useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const present = morningAttendance.filter(a => a.date === date && a.status === 'PRESENT' && filteredStudentsBase.some(s => s.id === a.studentId)).length;
      return {
        name: new Date(date).toLocaleDateString('th-TH', { weekday: 'short' }),
        value: present
      };
    });
  }, [morningAttendance, filteredStudentsBase]);

  if (user.role === 'PARENT' || viewingStudentId) {
    const targetId = viewingStudentId || user.studentId;
    const student = students.find(s => s.id === targetId) || students.find(s => s.studentId === targetId);

    if (!student) return <div className="p-20 text-center"><AlertTriangle size={48} className="mx-auto text-amber-500 mb-4" /><h3 className="font-black">ไม่พบข้อมูล</h3></div>;

    const blockScore = getMorningScore(student.id);
    const studentMorningAtt = morningAttendance.filter(a => a.studentId === student.id);
    const presentCount = studentMorningAtt.filter(a => a.status === 'PRESENT').length;
    const attRate = studentMorningAtt.length > 0 ? Math.round((presentCount / studentMorningAtt.length) * 100) : 0;

    return (
      <div className="space-y-6 md:space-y-8 animate-in fade-in duration-500 pb-20">
        <div className="flex items-center gap-4">
          {user.role !== 'PARENT' && <button onClick={() => setViewingStudentId(null)} className="p-3 bg-white border border-slate-100 rounded-xl shadow-sm"><ArrowLeft size={18} /></button>}
          <h2 className="text-xl md:text-3xl font-black text-slate-900 font-heading">ภาพรวมนักเรียน: {student.name}</h2>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าแถว" value={`${attRate}%`} sub="รวมทุกบล็อก" icon={<Sun />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
          <StatCard title="คะแนนเข้าแถว" value={blockScore} sub="ในบล็อกปัจจุบัน" icon={<Star />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="พฤติกรรม" value={student.behaviorScore} sub="คะแนนคงเหลือ" icon={<Activity />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>
      </div>
    );
  }

  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);

  return (
    <div className="space-y-6 md:space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-stretch lg:items-center justify-between gap-4 md:gap-6 bg-white p-4 md:p-6 rounded-2xl md:rounded-[32px] border border-slate-200 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="p-3 md:p-4 bg-slate-900 rounded-xl md:rounded-[20px] text-white shadow-xl">
            <LayoutDashboard size={24} />
          </div>
          <div>
            <h2 className="text-lg md:text-2xl font-black text-slate-900 tracking-tight font-heading leading-none">แผงควบคุมหลัก</h2>
            <p className="text-[9px] md:text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">สรุปภาพรวมสถานศึกษา</p>
          </div>
        </div>
        <div className="flex flex-col sm:flex-row gap-3 w-full lg:w-auto">
          <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3 rounded-xl text-[10px] font-black uppercase outline-none">
            <option value="ALL">ทุกระดับชั้น</option>
            {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
          </select>
          <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3 rounded-xl text-[10px] font-black uppercase outline-none">
            <option value="ALL">ทุกแผนกวิชา</option>
            {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
        <StatCard title="จำนวนนักเรียน" value={filteredStudentsBase.length} sub="ในกลุ่มที่เลือก" icon={<Users />} color="bg-slate-900" />
        <StatCard title="เฝ้าระวังพฤติกรรม" value={behaviorWatchlist.length} sub="ต่ำกว่า 70 คะแนน" icon={<ShieldAlert />} color="bg-red-600" textColor="text-red-600" />
        <StatCard title="เฝ้าระวังเข้าแถว" value={attendanceWatchlist.length} sub="ต่ำกว่า 3.0 คะแนน" icon={<Sun />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
        <StatCard title="มาสายวันนี้" value={morningAttendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'LATE' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="หลัง 07:50 น." icon={<Clock />} color="bg-amber-500" textColor="text-amber-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 md:gap-8">
        <div className="xl:col-span-2 bg-white p-5 md:p-8 rounded-[32px] md:rounded-[40px] border border-slate-200 shadow-sm min-h-[400px]">
          <h3 className="text-lg font-black text-slate-900 font-heading mb-8 flex items-center gap-2">
             <BarChart3 className="text-[#00AEEF]" size={20} /> สถิติคนเข้าแถว (7 วันล่าสุด)
          </h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
                <Tooltip cursor={{fill: '#f8fafc'}} />
                <Bar dataKey="value" fill="#00AEEF" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="flex flex-col gap-6">
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col">
            <h4 className="text-[11px] font-black text-slate-900 uppercase tracking-widest mb-6 flex items-center gap-2">
              <ShieldAlert size={18} className="text-red-600" /> เฝ้าระวังพฤติกรรม
            </h4>
            <div className="space-y-3">
