        </div>

        {viewMode === 'checkin' && filteredStudents.length > 0 && (
          <button 
            onClick={shareToLine}
            className="w-full md:w-auto flex items-center justify-center gap-2 px-6 py-3 bg-[#06C755] text-white rounded-xl text-[11px] md:text-sm font-black shadow-lg hover:bg-green-600 transition-all uppercase tracking-widest"
          >
            <Share2 size={18} /> แชร์รายงานเข้า LINE
          </button>
        )}
      </div>

      <div className="bg-white p-5 md:p-8 rounded-[28px] md:rounded-[32px] border border-slate-200 shadow-sm">
        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4 md:gap-6">
