                       <p className="text-xs font-black text-slate-900">{student?.name}</p>
                       <p className="text-[9px] text-slate-400 font-bold">{record.date}</p>
                    </div>
                  </div>
                  <span className={`px-3 py-1 rounded-full text-[9px] font-black border uppercase ${STATUS_LABELS[record.status].color}`}>
                    {STATUS_LABELS[record.status].label}
                  </span>
                </div>
                {record.remark && <div className="p-2.5 bg-slate-50 rounded-lg text-[10px] font-bold text-slate-600 flex items-center gap-2"><MessageSquare size={12} /> {record.remark}</div>}
              </div>
            );
          }) : <div className="col-span-full py-20 text-center text-slate-300 font-black uppercase tracking-widest text-xs">ไม่พบข้อมูลประวัติ</div>}
        </div>
      )}
    </div>
  );
};

