            <button 
              onClick={handleSave} 
              disabled={isSaving}
              className={`flex items-center justify-center gap-3 px-8 py-4 rounded-2xl text-white font-black transition-all shadow-xl active:scale-95 ${
                isSaved ? 'bg-green-600 shadow-green-200' : 
                isSaving ? 'bg-slate-400 cursor-not-allowed' : 'bg-slate-900'
              }`}
            >
              {isSaving ? <Loader2 size={20} className="animate-spin" /> : isSaved ? <CheckCircle2 size={20} /> : <Save size={20} />} 
              <span className="text-sm md:text-base">{isSaving ? 'บันทึก...' : isSaved ? 'สำเร็จ' : 'บันทึกวันนี้'}</span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
