        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard title="เปอร์เซ็นต์เข้าแถว" value={`${attRate}%`} sub="จากรายการเช็คชื่อทั้งหมด" icon={<CheckCircle2 />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
          <StatCard title="คะแนนเข้าแถว (บล็อก)" value={blockScore} sub="คำนวณจากฐาน 18 วัน" icon={<Star />} color="bg-amber-500" textColor="text-amber-600" />
          <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="คะแนนคงเหลือปัจจุบัน" icon={<Activity />} color="bg-indigo-600" textColor="text-indigo-600" />
        </div>

        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm">
           <h3 className="text-sm font-black text-slate-900 uppercase tracking-[0.2em] mb-6 flex items-center gap-2">
             <User size={18} className="text-[#00AEEF]" /> ข้อมูลทั่วไป
           </h3>
           <div className="grid grid-cols-2 md:grid-cols-4 gap-8">
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">รหัสนักเรียน</p>
                <p className="text-lg font-black text-slate-900">{student.studentId}</p>
              </div>
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">ระดับชั้น</p>
                <p className="text-lg font-black text-slate-900">{student.level}</p>
              </div>
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">แผนกวิชา</p>
                <p className="text-lg font-black text-slate-900">{student.department}</p>
              </div>
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">ห้อง</p>
                <p className="text-lg font-black text-slate-900">{student.room}</p>
              </div>
           </div>
        </div>
      </div>
    );
  }

  const availableLevels = useMemo(() => Array.from(new Set((students || []).map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set((students || []).map(s => s.department))).sort(), [students]);

  return (
    <div className="space-y-6 md:space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-stretch lg:items-center justify-between gap-4 md:gap-6 bg-white p-4 md:p-6 rounded-2xl md:rounded-[32px] border border-slate-200 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="p-3 md:p-4 bg-slate-900 rounded-xl md:rounded-[20px] text-white shadow-xl">
            <LayoutDashboard size={24} />
          </div>
          <div>
            <h2 className="text-lg md:text-2xl font-black text-slate-900 tracking-tight font-heading leading-none">แผงควบคุมหลัก</h2>
            <p className="text-[9px] md:text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">สรุปภาพรวมสถานศึกษา</p>
          </div>
        </div>
        <div className="flex flex-col sm:flex-row gap-3 w-full lg:w-auto">
          <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3 rounded-xl text-[10px] font-black uppercase outline-none">
            <option value="ALL">ทุกระดับชั้น</option>
            {availableLevels.map(l => <option key={l} value={l}>{l}</option>)}
          </select>
          <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3 rounded-xl text-[10px] font-black uppercase outline-none">
            <option value="ALL">ทุกแผนกวิชา</option>
            {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
        <StatCard title="จำนวนนักเรียน" value={filteredStudentsBase.length} sub="ในกลุ่มที่เลือก" icon={<Users />} color="bg-slate-900" />
        <StatCard title="เฝ้าระวังพฤติกรรม" value={behaviorWatchlist.length} sub="ต่ำกว่า 70 คะแนน" icon={<ShieldAlert />} color="bg-red-600" textColor="text-red-600" />
        <StatCard title="เฝ้าระวังเข้าแถว" value={attendanceWatchlist.length} sub="ต่ำกว่า 3.0 คะแนน" icon={<Sun />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
        <StatCard title="มาสายวันนี้" value={morningAttendance.filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'LATE' && filteredStudentsBase.some(s => s.id === a.studentId)).length} sub="หลัง 07:50 น." icon={<Clock />} color="bg-amber-500" textColor="text-amber-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 md:gap-8">
        <div className="xl:col-span-2 bg-white p-5 md:p-8 rounded-[32px] md:rounded-[40px] border border-slate-200 shadow-sm min-h-[400px]">
          <h3 className="text-lg font-black text-slate-900 font-heading mb-8 flex items-center gap-2">
             <BarChart3 className="text-[#00AEEF]" size={20} /> สถิติคนเข้าแถว (7 วันล่าสุด)
          </h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
                <Tooltip cursor={{fill: '#f8fafc'}} />
                <Bar dataKey="value" fill="#00AEEF" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="flex flex-col gap-6">
          {/* Behavior Watchlist */}
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col">
            <h4 className="text-[11px] font-black text-slate-900 uppercase tracking-widest mb-6 flex items-center justify-between">
              <span className="flex items-center gap-2"><ShieldAlert size={18} className="text-red-600" /> เฝ้าระวังพฤติกรรม</span>
