              <input type="file" ref={fileInputRef} className="hidden" accept=".xlsx, .xls, .csv" onChange={() => {}} />
              <div className="p-3 bg-white rounded-xl shadow-sm mb-3"><Upload size={24} className="text-green-600" /></div>
              <p className="text-xs font-black text-slate-900 uppercase">เลือกไฟล์</p>
