                  <div className="flex items-center gap-3 text-left min-w-0">
                    <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-red-600 font-black text-xs shrink-0 shadow-sm border border-red-100">
                      {s.name.charAt(0)}
                    </div>
                    <div className="min-w-0">
                      <p className="font-black text-[13px] text-slate-900 truncate leading-none">{s.name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">คะแนน: {s.behaviorScore}</p>
