                      {s.name.charAt(0)}
                    </div>
                    <div className="min-w-0">
                      <p className="font-black text-[13px] text-slate-900 truncate leading-none">{s.name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase mt-1">คะแนน: {s.morningScore}</p>
                    </div>
