                  <button 
                    onClick={() => setViewingStudentId(String(s.id))}
                    className="p-3 bg-[#00AEEF] text-white rounded-xl shadow-lg shadow-sky-200 hover:bg-sky-600 hover:scale-105 transition-all active:scale-95"
