              <p className="text-[10px] font-bold text-[#00AEEF] uppercase tracking-widest mt-1">{student.name} ({student.studentId})</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <StatCard title="เปอร์เซ็นต์เข้าแถว" value={`${attRate}%`} sub="จากทุกวันที่มีการเช็คชื่อ" icon={<CheckCircle2 />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
            <StatCard title="คะแนนเข้าแถว (บล็อก)" value={blockScore} sub={`บล็อก: ${activeBlock?.name || '-'}`} icon={<Star />} color="bg-amber-500" textColor="text-amber-600" />
            <StatCard title="คะแนนพฤติกรรม" value={student.behaviorScore} sub="คะแนนคงเหลือปัจจุบัน" icon={<Activity />} color="bg-indigo-600" textColor="text-indigo-600" />
