                  </div>
                  <button 
                    onClick={() => setViewingStudentId(String(s.id))}
                    className="p-3 bg-[#00AEEF] text-white rounded-xl shadow-lg hover:bg-sky-600 transition-all active:scale-95 flex items-center justify-center group/btn"
                    title="ดูรายละเอียดข้อมูล"
                  >
                    <ChevronRight size={18} className="group-hover/btn:translate-x-0.5 transition-transform" />
                  </button>
                </div>
              ))}
              {attendanceWatchlist.length === 0 && <p className="text-center py-6 text-[10px] text-slate-300 font-black uppercase tracking-widest">ไม่มีรายการ</p>}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  Users, User, Activity, Star, Clock, BarChart3, ShieldAlert,
  CheckCircle2, Sun, ArrowLeft, LayoutDashboard, ChevronRight, 
  Wallet, Banknote, Info, Search, Bell, MessageSquare, Copy, Check, ExternalLink,
  X
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
  notifications?: NotificationRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor, extra }: any) => (
  <div className="bg-white p-5 md:p-7 rounded-[28px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all group overflow-hidden h-full">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-1.5 flex-1">
        <p className="text-slate-500 text-[9px] font-extrabold uppercase tracking-widest font-heading">{title}</p>
        <h3 className={`text-3xl md:text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-[10px] text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-3 rounded-2xl ${color} text-white shadow-lg shrink-0`}>
        {React.isValidElement(icon) ? React.cloneElement(icon as React.ReactElement, { size: 20 }) : null}
      </div>
    </div>
    {extra && <div className="mt-4 pt-4 border-t border-slate-50">{extra}</div>}
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students = [], 
  attendance = [], 
  user, 
  studyBlocks = [],
  tuitionConfigs = [],
  paymentRecords = [],
  notifications = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');
  const [showBankDetails, setShowBankDetails] = useState(false);
  const [copied, setCopied] = useState(false);

  const isParent = user?.role === 'PARENT';

  const bankInfo = useMemo(() => {
    const saved = localStorage.getItem('cms_bank_info');
    return saved ? JSON.parse(saved) : {
      bankName: 'ธนาคารกรุงไทย (Krungthai)',
      accountNo: '012-3-45678-9',
      accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
    };
  }, []);

  const handleCopyAccount = () => {
    navigator.clipboard.writeText(bankInfo.accountNo);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const attendanceMap = useMemo(() => {
    const map = new Map<string, AttendanceRecord[]>();
    (attendance || []).forEach(record => {
      const sId = String(record.studentId);
      if (!map.has(sId)) map.set(sId, []);
      map.get(sId)?.push(record);
    });
    return map;
  }, [attendance]);

  const activeBlock = useMemo(() => 
    (studyBlocks || []).find(b => b.isActive) || (studyBlocks?.[0] || null)
  , [studyBlocks]);

  const getStudentStats = (sId: string) => {
    const sIdStr = String(sId);
    const records = attendanceMap.get(sIdStr) || [];
    const morningRecords = records.filter(r => r.type === 'MORNING');

    let blockPresentDays = 0;
    if (activeBlock) {
      blockPresentDays = morningRecords.filter(r => 
        r.status === 'PRESENT' && r.date >= activeBlock.startDate && r.date <= activeBlock.endDate
      ).length;
    }
    const blockScore = Number(((blockPresentDays * 5) / 18).toFixed(2));
    const presentCount = morningRecords.filter(r => r.status === 'PRESENT').length;
    const attRate = morningRecords.length > 0 ? Math.round((presentCount / morningRecords.length) * 100) : 0;

    const student = students.find(x => String(x.id) === sIdStr || String(x.studentId) === sIdStr);
    const config = tuitionConfigs.find(c => c.level === student?.level && c.department === student?.department);
    const paid = paymentRecords.filter(p => String(p.studentId) === String(student?.id)).reduce((sum, p) => sum + p.amount, 0);
    const remaining = config ? Math.max(0, config.amount - paid) : 0;

    return { blockScore, attRate, remaining, totalExpected: config?.amount || 0, paid };
  };

  const filteredStudents = useMemo(() => {
    return students.filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const targetId = viewingStudentId || (isParent ? user?.studentId : null);

  if (targetId) {
    const student = students.find(s => String(s.id) === String(targetId) || String(s.studentId) === String(targetId));

    if (student) {
      const { blockScore, attRate, remaining, totalExpected, paid } = getStudentStats(student.id);
      const studentNotifications = notifications.filter(n => String(n.studentId) === String(student.id)).slice(0, 5);

      return (
        <div className="space-y-6 md:space-y-8 animate-in fade-in duration-500 pb-20">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              {!isParent && (
                <button onClick={() => setViewingStudentId(null)} className="p-4 bg-white border border-slate-200 rounded-2xl shadow-sm hover:bg-slate-50 transition-all flex items-center justify-center group">
                  <ArrowLeft size={20} className="group-hover:-translate-x-1 transition-transform" />
                </button>
              )}
              <div>
                <h2 className="text-xl md:text-3xl font-black text-slate-900 font-heading uppercase tracking-tight">
                  {isParent ? 'ข้อมูลบุตรหลาน' : 'สรุปข้อมูลรายบุคคล'}
                </h2>
                <p className="text-[10px] font-bold text-[#00AEEF] uppercase tracking-widest mt-1">{student.name} ({student.studentId})</p>
              </div>
            </div>
          </div>

          {/* แผงแจ้งเตือนล่าสุด */}
          <div className="bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
            <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest flex items-center gap-2 mb-6">
              <Bell className="text-red-500 animate-pulse" size={18} /> แจ้งเตือนล่าสุด
            </h4>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 flex-1">
              {studentNotifications.length > 0 ? studentNotifications.map(n => (
                <div key={n.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex items-start gap-3 hover:bg-white transition-all group/notif">
                  <div className={`p-2 rounded-xl shrink-0 ${n.type === 'ABSENT' ? 'bg-red-100 text-red-600' : 'bg-blue-100 text-blue-600'}`}>
                    <Info size={14} />
                  </div>
                  <div>
                    <p className="text-xs font-black text-slate-900 leading-tight group-hover/notif:text-[#00AEEF] transition-colors">{n.title}</p>
                    <p className="text-[10px] text-slate-500 font-bold mt-1 line-clamp-1">{n.message}</p>
                    <p className="text-[9px] text-slate-400 font-bold mt-1">{n.date}</p>
                  </div>
                </div>
              )) : (
                <div className="col-span-full flex flex-col items-center justify-center py-6 opacity-20">
                  <MessageSquare size={32} />
                  <p className="text-[9px] font-black uppercase tracking-widest mt-2">ไม่มีแจ้งเตือนใหม่</p>
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <StatCard 
              title="เปอร์เซ็นต์เข้าแถว" 
              value={`${attRate}%`} 
              sub="จากทุกวันที่มีการเช็คชื่อ" 
              icon={<CheckCircle2 />} 
              color="bg-[#00AEEF]" 
              textColor="text-[#00AEEF]" 
            />
            <StatCard 
              title="คะแนนพฤติกรรม" 
              value={student.behaviorScore} 
              sub="คะแนนคงเหลือปัจจุบัน" 
              icon={<Activity />} 
              color="bg-indigo-600" 
              textColor="text-indigo-600" 
            />
            {/* แผงยอดค้างชำระ - สีแดงเด่นชัด */}
            <div className="bg-red-600 p-6 md:p-8 rounded-[32px] shadow-xl text-white flex flex-col justify-between hover:bg-red-700 transition-all">
              <div className="flex items-start justify-between">
                <div>
                  <p className="text-red-100 text-[9px] font-extrabold uppercase tracking-widest font-heading mb-1">ยอดค้างชำระค่าธรรมเนียม</p>
                  <h3 className="text-4xl md:text-5xl font-black font-heading leading-none">
                    {remaining.toLocaleString()} <span className="text-xl">฿</span>
                  </h3>
                </div>
                <div className="p-3 bg-white/20 rounded-2xl text-white">
                  <Wallet size={24} />
                </div>
              </div>

              <div className="mt-6 space-y-4">
                <div className="bg-white/10 p-4 rounded-2xl border border-white/10 flex items-center justify-between">
                  <div className="text-center flex-1 border-r border-white/20">
                    <p className="text-[9px] font-black text-red-100 uppercase mb-0.5">ชำระแล้ว</p>
                    <p className="text-sm font-black">{paid.toLocaleString()} ฿</p>
                  </div>
                  <div className="text-center flex-1">
                    <p className="text-[9px] font-black text-red-100 uppercase mb-0.5">ยอดทั้งหมด</p>
                    <p className="text-sm font-black text-white/70">{totalExpected.toLocaleString()} ฿</p>
                  </div>
                </div>

                {remaining > 0 && (
                  <button 
                    onClick={() => setShowBankDetails(!showBankDetails)}
                    className="w-full flex items-center justify-center gap-2 py-3.5 bg-white text-red-600 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-slate-50 transition-all shadow-lg active:scale-95"
                  >
                    <Banknote size={16} /> {showBankDetails ? 'ซ่อนข้อมูลธนาคาร' : 'ชำระเงินตอนนี้'}
                  </button>
                )}
              </div>
            </div>
          </div>

          {/* แผงข้อมูลธนาคาร */}
          {showBankDetails && remaining > 0 && (
            <div className="bg-white p-8 md:p-12 rounded-[40px] border-4 border-red-500 shadow-2xl animate-in slide-in-from-top-6 duration-500 relative overflow-hidden">
               <div className="absolute top-0 right-0 p-8 opacity-5 text-red-600 pointer-events-none">
                 <Banknote size={180} />
               </div>

               <div className="flex flex-col lg:flex-row gap-12 items-center relative z-10">
                  <div className="lg:w-1/2 space-y-8 w-full">
                    <div className="space-y-2">
                      <h4 className="text-2xl font-black text-slate-900 flex items-center gap-3 font-heading uppercase tracking-tight">
                        <Banknote className="text-green-600" size={32} /> บัญชีสำหรับการโอนเงิน
                      </h4>
                      <p className="text-xs text-slate-500 font-bold">กรุณาตรวจสอบยอดเงินและโอนเข้าบัญชีสถาบันโดยตรง</p>
                    </div>

                    <div className="space-y-5 bg-slate-50 p-6 rounded-[32px] border border-slate-100">
                      <div className="flex items-center justify-between py-2 border-b border-slate-200">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ธนาคาร</span>
                        <span className="text-sm font-black text-slate-900">{bankInfo.bankName}</span>
                      </div>

                      <div className="flex flex-col gap-2">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">เลขที่บัญชี</span>
                        <div className="flex items-center justify-between bg-white p-4 rounded-2xl border-2 border-red-500 shadow-sm">
                          <span className="text-3xl font-black text-red-600 tracking-tighter">{bankInfo.accountNo}</span>
                          <button 
                            onClick={handleCopyAccount}
                            className={`p-3 rounded-xl flex items-center gap-2 transition-all active:scale-90 ${copied ? 'bg-green-600 text-white shadow-lg' : 'bg-slate-100 text-slate-600 hover:bg-slate-900 hover:text-white'}`}
                          >
                            {copied ? <Check size={18} /> : <Copy size={18} />}
                            <span className="text-[10px] font-black uppercase">{copied ? 'สำเร็จ' : 'คัดลอก'}</span>
                          </button>
                        </div>
                      </div>

                      <div className="flex items-center justify-between py-2">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">ชื่อบัญชี</span>
                        <span className="text-sm font-black text-slate-900">{bankInfo.accountName}</span>
                      </div>
                    </div>
                  </div>

                  <div className="lg:w-1/2 p-8 bg-red-50 rounded-[40px] border-2 border-red-100 flex flex-col gap-6 w-full">
                    <div className="flex items-start gap-4">
                      <div className="p-4 bg-white rounded-2xl text-red-600 shadow-sm shrink-0"><Info size={24} /></div>
                      <div>
                        <p className="text-base font-black text-slate-900 font-heading">ขั้นตอนการชำระเงิน</p>
                        <ul className="text-[11px] text-slate-700 font-bold mt-3 space-y-2 list-decimal list-inside leading-relaxed">
                          <li>โอนเงินเข้าเลขที่บัญชีที่ปรากฏให้ครบตามยอดค้างชำระ</li>
                          <li>บันทึกภาพหลักฐานการโอนเงิน (Slip) ทันที</li>
                          <li>ส่งหลักฐานให้เจ้าหน้าที่ผ่านช่องทาง LINE ของวิทยาลัย</li>
                          <li>รอเจ้าหน้าที่ตรวจสอบและอัปเดตยอดภายใน 1-2 วันทำการ</li>
                        </ul>
                      </div>
                    </div>

                    <button 
                      onClick={() => setShowBankDetails(false)} 
                      className="w-full py-4 bg-white border border-slate-200 text-slate-400 rounded-2xl text-[10px] font-black uppercase hover:text-red-500 hover:border-red-200 transition-all flex items-center justify-center gap-2"
                    >
                      <X size={14} /> ปิดหน้าต่างข้อมูลธนาคาร
                    </button>
                  </div>
               </div>
            </div>
          )}

          <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm relative overflow-hidden">
             <div className="absolute top-0 right-0 p-8 opacity-5 text-slate-900 pointer-events-none">
                <User size={100} />
             </div>
             <h3 className="text-xs font-black text-slate-900 uppercase tracking-[0.2em] mb-8 flex items-center gap-3 relative z-10">
               <span className="w-1 h-5 bg-[#00AEEF] rounded-full"></span> รายละเอียดนักเรียน
             </h3>
             <div className="grid grid-cols-2 md:grid-cols-4 gap-6 relative z-10">
                <div className="space-y-1">
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">ระดับชั้น</p>
                  <p className="text-base font-black text-slate-900">{student.level}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">แผนกวิชา</p>
                  <p className="text-base font-black text-slate-900">{student.department}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">ห้องเรียน</p>
                  <p className="text-base font-black text-slate-900">ห้อง {student.room}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">รหัสประจำตัว</p>
                  <p className="text-base font-black text-slate-900">{student.studentId}</p>
                </div>
             </div>
          </div>

          {!isParent && (
            <button 
              onClick={() => setViewingStudentId(null)}
              className="w-full md:w-auto px-10 py-5 bg-slate-900 text-white rounded-2xl font-black text-[11px] uppercase tracking-[0.2em] hover:bg-black transition-all shadow-xl flex items-center justify-center gap-3 active:scale-95"
            >
              <LayoutDashboard size={18} /> กลับสู่หน้าหลัก
            </button>
          )}
        </div>
      );
    } else {
      setViewingStudentId(null);
    }
  }

  // แดชบอร์ดสำหรับอาจารย์/แอดมิน
  const behaviorWatchlist = useMemo(() => 
    filteredStudents.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudents]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudents
      .map(s => ({ ...s, morningScore: getStudentStats(s.id).blockScore }))
      .filter(s => s.morningScore < 3.0)
      .sort((a,b) => a.morningScore - b.morningScore)
      .slice(0, 6)
  , [filteredStudents, attendanceMap, activeBlock]);

  const chartData = useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const presentCount = (attendance || []).filter(a => 
        a.date === date && a.status === 'PRESENT' && a.type === 'MORNING'
      ).length;
      return {
        name: new Date(date).toLocaleDateString('th-TH', { weekday: 'short' }),
        value: presentCount
      };
    });
  }, [attendance]);

  return (
    <div className="space-y-6 md:space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col lg:flex-row items-stretch lg:items-center justify-between gap-4 md:gap-6 bg-white p-4 md:p-6 rounded-[32px] border border-slate-200 shadow-sm">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-slate-900 rounded-2xl text-white shadow-xl">
            <LayoutDashboard size={24} />
          </div>
          <div>
            <h2 className="text-lg md:text-2xl font-black text-slate-900 tracking-tight font-heading leading-none">แผงควบคุมหลัก</h2>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">Institutional Overview</p>
          </div>
        </div>
        <div className="flex flex-col sm:flex-row gap-3 w-full lg:w-auto">
          <select value={filterLevel} onChange={(e) => setFilterLevel(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3 rounded-xl text-[10px] font-black uppercase outline-none">
            <option value="ALL">ทุกระดับชั้น</option>
            {Array.from(new Set(students.map(s => s.level))).map(l => <option key={l} value={l}>{l}</option>)}
          </select>
          <select value={filterDept} onChange={(e) => setFilterDept(e.target.value)} className="w-full bg-slate-50 border border-slate-100 p-3 rounded-xl text-[10px] font-black uppercase outline-none">
            <option value="ALL">ทุกแผนกวิชา</option>
            {Array.from(new Set(students.map(s => s.department))).map(d => <option key={d} value={d}>{d}</option>)}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6">
        <StatCard title="จำนวนนักเรียน" value={filteredStudents.length} sub="ในตัวกรองปัจจุบัน" icon={<Users />} color="bg-slate-900" />
        <StatCard title="เฝ้าระวังพฤติกรรม" value={behaviorWatchlist.length} sub="คะแนนต่ำกว่า 70" icon={<ShieldAlert />} color="bg-red-600" textColor="text-red-600" />
        <StatCard title="เฝ้าระวังเข้าแถว" value={attendanceWatchlist.length} sub="คะแนนต่ำกว่า 3.0" icon={<Sun />} color="bg-[#00AEEF]" textColor="text-[#00AEEF]" />
        <StatCard title="มาสายวันนี้" value={(attendance || []).filter(a => a.date === new Date().toISOString().split('T')[0] && a.status === 'LATE' && a.type === 'MORNING').length} sub="เข้าแถวหลัง 07:50 น." icon={<Clock />} color="bg-amber-500" textColor="text-amber-600" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-6 md:gap-8">
        <div className="xl:col-span-2 bg-white p-5 md:p-8 rounded-[40px] border border-slate-200 shadow-sm min-h-[400px]">
          <h3 className="text-lg font-black text-slate-900 font-heading mb-8 flex items-center gap-2">
             <BarChart3 className="text-[#00AEEF]" size={20} /> สถิติมาเข้าแถว (7 วันล่าสุด)
          </h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
                <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700}} />
                <Tooltip cursor={{fill: '#f8fafc'}} />
                <Bar dataKey="value" fill="#00AEEF" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="flex flex-col gap-6">
          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <h4 className="text-[11px] font-black text-slate-900 uppercase tracking-widest mb-6 flex items-center justify-between border-b pb-4 border-slate-50">
              <span className="flex items-center gap-2"><ShieldAlert size={18} className="text-red-600" /> เฝ้าระวังพฤติกรรม</span>
            </h4>
            <div className="space-y-2">
              {behaviorWatchlist.map(s => (
                <div key={s.id} className="flex items-center justify-between p-4 bg-red-50/50 rounded-2xl border border-red-100/50 group">
                  <div className="flex items-center gap-3 min-w-0">
                    <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-red-600 font-black text-xs border border-red-100 shrink-0 shadow-sm">
                      {s.name.charAt(0)}
                    </div>
                    <div className="min-w-0">
                      <p className="font-black text-[13px] text-slate-900 truncate leading-none">{s.name}</p>
                      <p className="text-[9px] text-slate-400 font-bold mt-1 uppercase">คะแนน: {s.behaviorScore}</p>
                    </div>
                  </div>
                  <button 
                    onClick={() => setViewingStudentId(String(s.id))}
                    className="p-3 bg-red-600 text-white rounded-xl shadow-lg hover:bg-red-700 transition-all active:scale-95 flex items-center justify-center group/btn"
                    title="ดูรายละเอียดข้อมูล"
                  >
                    <ChevronRight size={18} className="group-hover/btn:translate-x-0.5 transition-transform" />
                  </button>
                </div>
              ))}
              {behaviorWatchlist.length === 0 && <p className="text-center py-6 text-[10px] text-slate-300 font-black uppercase tracking-widest">ไม่มีรายการ</p>}
            </div>
          </div>

          <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm">
            <h4 className="text-[11px] font-black text-slate-900 uppercase tracking-widest mb-6 flex items-center justify-between border-b pb-4 border-slate-50">
              <span className="flex items-center gap-2"><Sun size={18} className="text-[#00AEEF]" /> เฝ้าระวังเข้าแถว</span>
            </h4>
            <div className="space-y-2">
              {attendanceWatchlist.map(s => (
                <div key={s.id} className="flex items-center justify-between p-4 bg-sky-50/50 rounded-2xl border border-sky-100/50 group">
                  <div className="flex items-center gap-3 min-w-0">
                    <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-[#00AEEF] font-black text-xs border border-sky-100 shrink-0 shadow-sm">
                      {s.name.charAt(0)}
                    </div>
                    <div className="min-w-0">
                      <p className="font-black text-[13px] text-slate-900 truncate leading-none">{s.name}</p>
                      <p className="text-[9px] text-slate-400 font-bold mt-1 uppercase">คะแนน: {s.morningScore}</p>
                    </div>
                  </div>
                  <button 
                    onClick={() => setViewingStudentId(String(s.id))}
                    className="p-3 bg-[#00AEEF] text-white rounded-xl shadow-lg hover:bg-sky-600 transition-all active:scale-95 flex items-center justify-center group/btn"
                    title="ดูรายละเอียดข้อมูล"
                  >
                    <ChevronRight size={18} className="group-hover/btn:translate-x-0.5 transition-transform" />
                  </button>
                </div>
              ))}
              {attendanceWatchlist.length === 0 && <p className="text-center py-6 text-[10px] text-slate-300 font-black uppercase tracking-widest">ไม่มีรายการ</p>}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

{
  "name": "EduSmart Vocational CMS",
  "description": "ระบบบริหารจัดการสถานศึกษาระดับอาชีวศึกษา (CMS) ครบวงจรสำหรับครูและผู้บริหาร รองรับการเช็คชื่อเข้าแถว เข้าเรียน และระบบคะแนนพฤติกรรม",
  "requestFramePermissions": [
    "camera"
  ]
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Student, AttendanceRecord, AttendanceStatus } from '../types';
import { STATUS_LABELS } from '../constants';
import { 
  Search, Save, CheckCircle2, History, ClipboardCheck, 
  MessageSquare, Share2, Sun, Loader2, X, Scan, Camera, CameraOff,
  UserCheck, AlertCircle
} from 'lucide-react';

interface MorningAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
}

const MorningAttendance: React.FC<MorningAttendanceProps> = ({ 
  students, 
  attendanceRecords, 
  setAttendanceRecords
}) => {
  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).map(String).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).map(String).sort(), [students]);
  const availableRooms = useMemo(() => Array.from(new Set(students.map(s => s.room))).map(String).sort((a,b) => parseInt(a)-parseInt(b)), [students]);

  const [level, setLevel] = useState<string>(availableLevels[0] || '');
  const [dept, setDept] = useState<string>(availableDepts[0] || '');
  const [room, setRoom] = useState<string>(availableRooms[0] || '');

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedHistoryDate, setSelectedHistoryDate] = useState<string>('');
  const [currentSession, setCurrentSession] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaving, setIsSaving] = useState(false);
  const [isSaved, setIsSaved] = useState(false);
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');

  // Barcode Scanner States
  const [isScannerEnabled, setIsScannerEnabled] = useState(false);
  const [barcodeInput, setBarcodeInput] = useState('');
  const [lastScannedStudent, setLastScannedStudent] = useState<Student | null>(null);
  const scanInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (availableLevels.length > 0 && !level) setLevel(availableLevels[0]);
    if (availableDepts.length > 0 && !dept) setDept(availableDepts[0]);
    if (availableRooms.length > 0 && !room) setRoom(availableRooms[0]);
  }, [availableLevels, availableDepts, availableRooms]);

  useEffect(() => {
    const rawDate = new Date().toISOString().split('T')[0];
    const todayRecords = attendanceRecords.filter(r => r.date === rawDate && r.type === 'MORNING');
    const sessionMap: Record<string, AttendanceStatus> = {};
    const remarkMap: Record<string, string> = {};
    todayRecords.forEach(r => {
      sessionMap[r.studentId] = r.status;
      if (r.remark) remarkMap[r.studentId] = r.remark;
    });
    setCurrentSession(sessionMap);
    setRemarks(remarkMap);
  }, [level, dept, room, attendanceRecords]);

  // Handle Scanner Focus
  useEffect(() => {
    if (isScannerEnabled && scanInputRef.current) {
      scanInputRef.current.focus();
    }
  }, [isScannerEnabled]);

  const filteredStudents = students.filter(s => 
    s.level === level && s.department === dept && s.room === room &&
    (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm))
  );

  const historyRecords = useMemo(() => {
    return attendanceRecords.filter(record => {
      const student = students.find(s => s.id === record.studentId);
      const matchesFilter = record.type === 'MORNING' && student?.level === level && student?.department === dept && student?.room === room;
      const matchesDate = selectedHistoryDate ? record.date === selectedHistoryDate : true;
      return matchesFilter && matchesDate;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [attendanceRecords, students, level, dept, room, selectedHistoryDate]);

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setCurrentSession(prev => ({ ...prev, [studentId]: status }));
    setIsSaved(false);
  };

  const handleBarcodeScan = (e: React.FormEvent) => {
    e.preventDefault();
    if (!barcodeInput) return;

    // ค้นหานักเรียนจาก รหัสนักเรียน (studentId)
    const scannedStudent = students.find(s => s.studentId === barcodeInput);

    if (scannedStudent) {
      handleStatusChange(scannedStudent.id, 'PRESENT');
      setLastScannedStudent(scannedStudent);
      // Optional: Play a "beep" sound if available
      try {
        const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2571/2571-preview.mp3');
        audio.play();
      } catch (e) {}

      // เคลียร์ค่าหลังจากสแกน 1.5 วินาทีเพื่อความสวยงาม
      setTimeout(() => setLastScannedStudent(null), 2000);
    } else {
      // ไม่พบนักเรียน
      setLastScannedStudent(null);
    }

    setBarcodeInput('');
    if (scanInputRef.current) scanInputRef.current.focus();
  };

  const handleSave = async () => {
    setIsSaving(true);
    await new Promise(resolve => setTimeout(resolve, 600));
    const rawDate = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');
    const newRecordsBatch: AttendanceRecord[] = filteredStudents.map(s => ({
      id: `MORNING_${rawDate}_${s.id}`,
      studentId: s.id,
      date: rawDate,
      type: 'MORNING',
      status: currentSession[s.id] || 'ABSENT',
      remark: remarks[s.id] || '',
      timestamp: timestamp
    }));
    setAttendanceRecords(prev => {
      const studentIds = filteredStudents.map(s => s.id);
      const otherRecords = prev.filter(r => !(r.date === rawDate && r.type === 'MORNING' && studentIds.includes(r.studentId)));
      return [...otherRecords, ...newRecordsBatch];
    });
    setIsSaving(false);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setCurrentSession(prev => ({ ...prev, ...newBatch }));
    setIsSaved(false);
  };

  const shareToLine = () => {
    const rawDate = new Date().toLocaleDateString('th-TH', { 
      day: 'numeric', 
      month: 'long', 
      year: 'numeric' 
    });
    let text = `📋 รายงานเช็คชื่อเข้าแถว\n`;
    text += `🗓️ วันที่: ${rawDate}\n`;
    text += `🏫 ${level} / ${dept}\n`;
    text += `สารสนเทศ (ห้อง ${room})\n`;
    text += `--------------------------\n`;
    filteredStudents.forEach((s, idx) => {
      const status = currentSession[s.id] || 'ABSENT';
      let icon = '❌'; 
      if (status === 'PRESENT') icon = '✅';
      else if (status === 'LATE') icon = '⏰';
      else if (status === 'SICK_LEAVE' || status === 'BUSINESS_LEAVE') icon = '📝';
      text += `${idx + 1}. ${s.name} ${icon}\n`;
    });
    text += `--------------------------\n`;
    const total = filteredStudents.length;
    const absents = filteredStudents.filter(s => (currentSession[s.id] || 'ABSENT') === 'ABSENT');
    const lates = filteredStudents.filter(s => currentSession[s.id] === 'LATE');
    const leaves = filteredStudents.filter(s => currentSession[s.id] === 'SICK_LEAVE' || currentSession[s.id] === 'BUSINESS_LEAVE');
    const presents = filteredStudents.filter(s => currentSession[s.id] === 'PRESENT');
    text += `📊 สรุปยอดรวม\n`;
    text += `✅ มา: ${presents.length} | ⏰ สาย: ${lates.length}\n`;
    text += `❌ ขาด: ${absents.length} | 📝 ลา: ${leaves.length}\n`;
    text += `👥 รวมทั้งหมด: ${total} คน\n`;
    text += `--------------------------\n`;
    text += `ระบบ EduSmart CMS`;
    const url = `https://line.me/R/msg/text/?${encodeURIComponent(text)}`;
    window.open(url, '_blank');
  };

  return (
    <div className="space-y-6 md:space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
        <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm w-full md:w-fit">
          <button onClick={() => setViewMode('checkin')} className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-6 md:px-8 py-3 rounded-xl text-[11px] md:text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><ClipboardCheck size={18} /> เช็คชื่อวันนี้</button>
          <button onClick={() => setViewMode('history')} className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-6 md:px-8 py-3 rounded-xl text-[11px] md:text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><History size={18} /> ประวัติ</button>
        </div>

        <div className="flex gap-3 w-full md:w-auto">
          {viewMode === 'checkin' && (
            <button 
              onClick={() => setIsScannerEnabled(!isScannerEnabled)}
              className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-4 rounded-2xl text-[11px] md:text-sm font-black shadow-xl transition-all uppercase tracking-widest font-heading active:scale-95 border-2 ${isScannerEnabled ? 'bg-amber-100 text-amber-700 border-amber-200' : 'bg-white text-slate-600 border-slate-200'}`}
            >
              {isScannerEnabled ? <CameraOff size={18} /> : <Scan size={18} />}
              {isScannerEnabled ? 'ปิดสแกนเนอร์' : 'เปิดสแกนบาร์โค้ด'}
            </button>
          )}

          {viewMode === 'checkin' && filteredStudents.length > 0 && (
            <button 
              onClick={shareToLine}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-4 bg-[#06C755] text-white rounded-2xl text-[11px] md:text-sm font-black shadow-xl hover:bg-green-600 transition-all uppercase tracking-widest font-heading active:scale-95"
            >
              <Share2 size={18} /> แชร์ LINE
            </button>
          )}
        </div>
      </div>

      {/* Barcode Scanner UI */}
      {viewMode === 'checkin' && isScannerEnabled && (
        <div className="bg-slate-900 p-8 rounded-[32px] shadow-2xl animate-in zoom-in duration-300 relative overflow-hidden border-4 border-amber-400">
           <div className="absolute top-0 right-0 p-8 opacity-5 text-white pointer-events-none">
              <Scan size={150} />
           </div>

           <div className="flex flex-col items-center text-center space-y-6 relative z-10">
              <div className="space-y-2">
                <h3 className="text-2xl font-black text-white font-heading uppercase tracking-tight">ระบบสแกนเช็คชื่ออัตโนมัติ</h3>
                <p className="text-amber-400 font-bold text-xs uppercase tracking-[0.2em]">โหมดเชื่อมต่อเครื่องสแกน หรือ กล้อง</p>
              </div>

              <form onSubmit={handleBarcodeScan} className="w-full max-w-md">
                <div className="relative group">
                   <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400">
                     <Search size={24} />
                   </div>
                   <input 
                    ref={scanInputRef}
                    type="text" 
                    value={barcodeInput}
                    onChange={(e) => setBarcodeInput(e.target.value)}
                    onBlur={() => isScannerEnabled && scanInputRef.current?.focus()}
                    autoFocus
                    placeholder="สแกนรหัส หรือ พิมพ์ที่นี่..."
                    className="w-full bg-white/10 border-2 border-white/20 focus:border-amber-400 rounded-3xl pl-16 pr-8 py-6 text-2xl font-black text-white outline-none transition-all placeholder:text-white/20"
                   />
                </div>
              </form>

              {lastScannedStudent ? (
                <div className="flex items-center gap-4 bg-green-500 text-white px-8 py-5 rounded-[24px] shadow-2xl animate-in slide-in-from-bottom-4 duration-300">
                  <div className="p-3 bg-white/20 rounded-xl">
                    <UserCheck size={28} />
                  </div>
                  <div className="text-left">
                    <p className="text-[10px] font-black uppercase tracking-widest opacity-80">เช็คชื่อสำเร็จ</p>
                    <p className="text-xl font-black leading-none">{lastScannedStudent.name}</p>
                  </div>
                </div>
              ) : (
                <div className="flex items-center gap-3 text-slate-400 text-sm font-bold animate-pulse">
                   <AlertCircle size={18} />
                   <span>พร้อมสแกน... กรุณาโฟกัสเคอร์เซอร์ที่ช่องด้านบน</span>
                </div>
              )}
           </div>
        </div>
      )}

      <div className="bg-white p-5 md:p-8 rounded-[28px] md:rounded-[32px] border border-slate-200 shadow-sm">
        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4 md:gap-6">
          <div className="space-y-1.5">
            <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest">ระดับชั้น</label>
            <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-3 py-2.5 md:py-3 font-bold text-xs text-slate-900 outline-none transition-all">
              {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest">แผนก</label>
            <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-3 py-2.5 md:py-3 font-bold text-xs text-slate-900 outline-none transition-all">
              {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest">ห้อง</label>
            <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-3 py-2.5 md:py-3 font-bold text-xs text-slate-900 outline-none transition-all">
              {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
            </select>
          </div>
          <div className="col-span-2 md:col-span-1 lg:col-span-2 space-y-1.5">
            <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest">{viewMode === 'checkin' ? 'ค้นหา' : 'เลือกวันที่'}</label>
            {viewMode === 'checkin' ? (
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="ชื่อ..." className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl pl-10 pr-4 py-2.5 md:py-3 font-bold text-xs text-slate-900 outline-none" />
              </div>
            ) : (
              <input type="date" value={selectedHistoryDate} onChange={(e) => setSelectedHistoryDate(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-2.5 md:py-3 font-bold text-xs text-slate-900 outline-none" />
            )}
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <>
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
            <div className="flex gap-2">
              <button onClick={() => markAll('PRESENT')} className="flex-1 md:flex-none px-4 py-2.5 bg-green-50 text-green-700 rounded-xl text-[10px] font-black border border-green-200 uppercase tracking-widest hover:bg-green-100 transition-all">มาทุกคน</button>
              <button onClick={() => markAll('ABSENT')} className="flex-1 md:flex-none px-4 py-2.5 bg-red-50 text-red-700 rounded-xl text-[10px] font-black border border-red-200 uppercase tracking-widest hover:bg-red-100 transition-all">ขาดทุกคน</button>
            </div>
            <button 
              onClick={handleSave} 
              disabled={isSaving}
              className={`flex items-center justify-center gap-3 px-8 py-4 rounded-2xl text-white font-black transition-all shadow-xl active:scale-95 ${
                isSaved ? 'bg-green-600 shadow-green-200' : 
                isSaving ? 'bg-slate-400 cursor-not-allowed' : 'bg-slate-900'
              }`}
            >
              {isSaving ? <Loader2 size={20} className="animate-spin" /> : isSaved ? <CheckCircle2 size={20} /> : <Save size={20} />} 
              <span className="text-sm md:text-base">{isSaving ? 'บันทึก...' : isSaved ? 'สำเร็จ' : 'บันทึกวันนี้'}</span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {filteredStudents.map((student, index) => (
              <div key={student.id} className={`bg-white p-5 rounded-[24px] border-2 flex flex-col gap-4 group transition-all ${currentSession[student.id] === 'PRESENT' ? 'border-green-400 bg-green-50/10' : 'border-slate-100 hover:border-blue-300'}`}>
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center font-black text-white text-sm shrink-0">{index + 1}</div>
                    <div className="min-w-0">
                      <h4 className="font-black text-slate-900 text-sm truncate">{student.name}</h4>
                      <p className="text-[9px] text-slate-400 font-bold uppercase tracking-tighter">ID: {student.studentId}</p>
                    </div>
                  </div>
                  <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${currentSession[student.id] ? STATUS_LABELS[currentSession[student.id]].color : 'bg-slate-50 text-slate-300'}`}>
                    {currentSession[student.id] ? STATUS_LABELS[currentSession[student.id]].label : 'ยังไม่ได้เช็ค'}
                  </span>
                </div>

                <div className="grid grid-cols-5 gap-1.5">
                  {Object.entries(STATUS_LABELS).map(([key, value]) => (
                    <button 
                      key={key} 
                      onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} 
                      className={`flex flex-col items-center gap-1.5 p-2 rounded-xl border-2 transition-all ${currentSession[student.id] === key ? value.color + ' border-current' : 'bg-white border-slate-50 text-slate-300 hover:border-slate-100'}`}
                    >
                      <div className="scale-75 md:scale-90">{value.icon}</div>
                      <span className="text-[7px] font-black uppercase text-center leading-tight">{value.label}</span>
                    </button>
                  ))}
                </div>

                {(currentSession[student.id] && currentSession[student.id] !== 'PRESENT') && (
                  <div className="relative">
                    <MessageSquare className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={12} />
                    <input type="text" value={remarks[student.id] || ''} onChange={(e) => setRemarks(prev => ({ ...prev, [student.id]: e.target.value }))} placeholder="ระบุเหตุผล..." className="w-full bg-slate-50 border border-slate-100 rounded-xl pl-9 pr-4 py-2 font-bold text-slate-900 outline-none text-[10px] focus:border-blue-500" />
                  </div>
                )}
              </div>
            ))}
            {filteredStudents.length === 0 && <div className="col-span-full py-20 text-center"><Sun size={48} className="mx-auto opacity-10 mb-4" /><p className="text-slate-300 font-black uppercase tracking-widest text-xs">ไม่พบรายชื่อ</p></div>}
          </div>
        </>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {historyRecords.length > 0 ? historyRecords.map((record) => {
            const student = students.find(s => s.id === record.studentId);
            return (
              <div key={record.id} className="bg-white p-5 rounded-[24px] border border-slate-200 flex flex-col gap-3">
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-blue-50 text-blue-600 rounded-lg flex items-center justify-center"><ClipboardCheck size={16} /></div>
                    <div>
                       <p className="text-xs font-black text-slate-900">{student?.name}</p>
                       <p className="text-[9px] text-slate-400 font-bold">{record.date}</p>
                    </div>
                  </div>
                  <span className={`px-3 py-1 rounded-full text-[9px] font-black border uppercase ${STATUS_LABELS[record.status].color}`}>
                    {STATUS_LABELS[record.status].label}
                  </span>
                </div>
                {record.remark && <div className="p-2.5 bg-slate-50 rounded-lg text-[10px] font-bold text-slate-600 flex items-center gap-2"><MessageSquare size={12} /> {record.remark}</div>}
              </div>
            );
          }) : <div className="col-span-full py-20 text-center text-slate-300 font-black uppercase tracking-widest text-xs">ไม่พบข้อมูลประวัติ</div>}
        </div>
      )}
    </div>
  );
};

export default MorningAttendance;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Student, AttendanceRecord, AttendanceStatus } from '../types';
import { STATUS_LABELS } from '../constants';
import { 
  Search, Save, CheckCircle2, History, ClipboardCheck, 
  MessageSquare, Share2, Sun, Loader2, X, Scan, Camera, CameraOff,
  UserCheck, AlertCircle, Sparkles
} from 'lucide-react';

interface MorningAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
}

const MorningAttendance: React.FC<MorningAttendanceProps> = ({ 
  students, 
  attendanceRecords, 
  setAttendanceRecords
}) => {
  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).map(String).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).map(String).sort(), [students]);
  const availableRooms = useMemo(() => Array.from(new Set(students.map(s => s.room))).map(String).sort((a,b) => parseInt(a)-parseInt(b)), [students]);

  const [level, setLevel] = useState<string>(availableLevels[0] || '');
  const [dept, setDept] = useState<string>(availableDepts[0] || '');
  const [room, setRoom] = useState<string>(availableRooms[0] || '');

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedHistoryDate, setSelectedHistoryDate] = useState<string>('');
  const [currentSession, setCurrentSession] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaving, setIsSaving] = useState(false);
  const [isSaved, setIsSaved] = useState(false);
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');

  // Barcode Scanner States
  const [isScannerEnabled, setIsScannerEnabled] = useState(false);
  const [barcodeInput, setBarcodeInput] = useState('');
  const [lastScannedStudent, setLastScannedStudent] = useState<Student | null>(null);
  const scanInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (availableLevels.length > 0 && !level) setLevel(availableLevels[0]);
    if (availableDepts.length > 0 && !dept) setDept(availableDepts[0]);
    if (availableRooms.length > 0 && !room) setRoom(availableRooms[0]);
  }, [availableLevels, availableDepts, availableRooms]);

  useEffect(() => {
    const rawDate = new Date().toISOString().split('T')[0];
    const todayRecords = attendanceRecords.filter(r => r.date === rawDate && r.type === 'MORNING');
    const sessionMap: Record<string, AttendanceStatus> = {};
    const remarkMap: Record<string, string> = {};
    todayRecords.forEach(r => {
      sessionMap[r.studentId] = r.status;
      if (r.remark) remarkMap[r.studentId] = r.remark;
    });
    setCurrentSession(sessionMap);
    setRemarks(remarkMap);
  }, [level, dept, room, attendanceRecords]);

  // Handle Scanner Focus Logic
  useEffect(() => {
    let focusInterval: number;
    if (isScannerEnabled && viewMode === 'checkin') {
      scanInputRef.current?.focus();
      // สร้าง interval เพื่อดึงโฟกัสกลับมาเสมอ ป้องกันครูเผลอไปกดที่อื่น
      focusInterval = window.setInterval(() => {
        if (document.activeElement !== scanInputRef.current) {
          scanInputRef.current?.focus();
        }
      }, 1000);
    }
    return () => clearInterval(focusInterval);
  }, [isScannerEnabled, viewMode]);

  const filteredStudents = students.filter(s => 
    s.level === level && s.department === dept && s.room === room &&
    (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm))
  );

  const historyRecords = useMemo(() => {
    return attendanceRecords.filter(record => {
      const student = students.find(s => s.id === record.studentId);
      const matchesFilter = record.type === 'MORNING' && student?.level === level && student?.department === dept && student?.room === room;
      const matchesDate = selectedHistoryDate ? record.date === selectedHistoryDate : true;
      return matchesFilter && matchesDate;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [attendanceRecords, students, level, dept, room, selectedHistoryDate]);

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setCurrentSession(prev => ({ ...prev, [studentId]: status }));
    setIsSaved(false);
  };

  const handleBarcodeScan = (e: React.FormEvent) => {
    e.preventDefault();
    if (!barcodeInput) return;

    // ค้นหานักเรียนจาก studentId
    const scannedStudent = students.find(s => s.studentId === barcodeInput.trim());

    if (scannedStudent) {
      handleStatusChange(scannedStudent.id, 'PRESENT');
      setLastScannedStudent(scannedStudent);

      // เสียง Beep สัญญาณสำเร็จ
      try {
        const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2571/2571-preview.mp3');
        audio.volume = 0.5;
        audio.play();
      } catch (err) {}

      // เคลียร์ feedback หลังจาก 2 วินาที
      setTimeout(() => setLastScannedStudent(null), 2500);
    } else {
      setLastScannedStudent(null);
    }

    setBarcodeInput('');
    scanInputRef.current?.focus();
  };

  const handleSave = async () => {
    setIsSaving(true);
    await new Promise(resolve => setTimeout(resolve, 600));
    const rawDate = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');
    const newRecordsBatch: AttendanceRecord[] = filteredStudents.map(s => ({
      id: `MORNING_${rawDate}_${s.id}`,
      studentId: s.id,
      date: rawDate,
      type: 'MORNING',
      status: currentSession[s.id] || 'ABSENT',
      remark: remarks[s.id] || '',
      timestamp: timestamp
    }));
    setAttendanceRecords(prev => {
      const studentIds = filteredStudents.map(s => s.id);
      const otherRecords = prev.filter(r => !(r.date === rawDate && r.type === 'MORNING' && studentIds.includes(r.studentId)));
      return [...otherRecords, ...newRecordsBatch];
    });
    setIsSaving(false);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setCurrentSession(prev => ({ ...prev, ...newBatch }));
    setIsSaved(false);
  };

  const shareToLine = () => {
    const rawDate = new Date().toLocaleDateString('th-TH', { 
      day: 'numeric', 
      month: 'long', 
      year: 'numeric' 
    });
    let text = `📋 รายงานเช็คชื่อเข้าแถว\n`;
    text += `🗓️ วันที่: ${rawDate}\n`;
    text += `🏫 ${level} / ${dept} (ห้อง ${room})\n`;
    text += `--------------------------\n`;
    filteredStudents.forEach((s, idx) => {
      const status = currentSession[s.id] || 'ABSENT';
      let icon = '❌'; 
      if (status === 'PRESENT') icon = '✅';
      else if (status === 'LATE') icon = '⏰';
      else if (status === 'SICK_LEAVE' || status === 'BUSINESS_LEAVE') icon = '📝';
      text += `${idx + 1}. ${s.name} ${icon}\n`;
    });
    text += `--------------------------\n`;
    const presents = filteredStudents.filter(s => currentSession[s.id] === 'PRESENT').length;
    text += `✅ มา: ${presents} | 👥 รวม: ${filteredStudents.length}\n`;
    text += `ระบบ EduSmart CMS`;
    window.open(`https://line.me/R/msg/text/?${encodeURIComponent(text)}`, '_blank');
  };

  return (
    <div className="space-y-6 md:space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
        <div className="flex bg-white p-2 rounded-[22px] border border-slate-200 shadow-sm w-full md:w-fit">
          <button onClick={() => setViewMode('checkin')} className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-8 py-3.5 rounded-xl text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><ClipboardCheck size={18} /> เช็คชื่อวันนี้</button>
          <button onClick={() => setViewMode('history')} className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-8 py-3.5 rounded-xl text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><History size={18} /> ประวัติ</button>
        </div>

        <div className="flex gap-3 w-full md:w-auto">
          {viewMode === 'checkin' && (
            <button 
              onClick={() => setIsScannerEnabled(!isScannerEnabled)}
              className={`flex-1 md:flex-none flex items-center justify-center gap-3 px-6 py-4 rounded-2xl text-[11px] md:text-sm font-black shadow-xl transition-all uppercase tracking-widest font-heading active:scale-95 border-2 ${isScannerEnabled ? 'bg-amber-500 border-amber-600 text-white' : 'bg-white border-slate-200 text-slate-600'}`}
            >
              {isScannerEnabled ? <CameraOff size={20} /> : <Scan size={20} />}
              {isScannerEnabled ? 'ปิดระบบสแกน' : 'เปิดโหมดสแกน'}
            </button>
          )}

          {viewMode === 'checkin' && filteredStudents.length > 0 && (
            <button 
              onClick={shareToLine}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-4 bg-[#06C755] text-white rounded-2xl text-[11px] md:text-sm font-black shadow-xl hover:bg-green-600 transition-all uppercase tracking-widest font-heading active:scale-95"
            >
              <Share2 size={18} /> แชร์ LINE
            </button>
          )}
        </div>
      </div>

      {/* Barcode Scanner UI Panel */}
      {viewMode === 'checkin' && isScannerEnabled && (
        <div className="bg-slate-950 p-8 md:p-12 rounded-[40px] shadow-2xl animate-in zoom-in duration-300 relative overflow-hidden border-4 border-amber-400">
           {/* Scan Line Animation */}
           <div className="absolute inset-0 pointer-events-none overflow-hidden opacity-10">
              <div className="w-full h-1 bg-amber-400 absolute animate-[scan-move_3s_linear_infinite]" />
           </div>

           <div className="flex flex-col items-center text-center space-y-8 relative z-10">
              <div className="space-y-3">
                <div className="flex items-center justify-center gap-3 text-amber-400">
                  <Scan size={32} className="animate-pulse" />
                  <h3 className="text-3xl font-black text-white font-heading uppercase tracking-tight">Scanner Terminal</h3>
                </div>
                <p className="text-slate-500 font-bold text-xs uppercase tracking-[0.3em]">พร้อมรับรหัสนักเรียนจากเครื่องสแกน หรือ กล้อง</p>
              </div>

              <form onSubmit={handleBarcodeScan} className="w-full max-w-lg">
                <div className="relative group">
                   <input 
                    ref={scanInputRef}
                    type="text" 
                    value={barcodeInput}
                    onChange={(e) => setBarcodeInput(e.target.value)}
                    placeholder="สแกนบาร์โค้ดที่นี่..."
                    className="w-full bg-white/5 border-2 border-white/20 focus:border-amber-400 rounded-[32px] px-10 py-8 text-4xl font-black text-white outline-none transition-all placeholder:text-white/10 text-center tracking-[0.2em]"
                   />
                   <div className="absolute right-6 top-1/2 -translate-y-1/2 text-white/20">
                      <Loader2 className="animate-spin" size={24} />
                   </div>
                </div>
              </form>

              {lastScannedStudent ? (
                <div className="flex items-center gap-6 bg-green-600 text-white px-10 py-6 rounded-[32px] shadow-2xl animate-in slide-in-from-bottom-6 duration-300 border-2 border-white/20">
                  <div className="p-4 bg-white/20 rounded-2xl">
                    <Check size={32} strokeWidth={4} />
                  </div>
                  <div className="text-left">
                    <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-80 mb-1">Check-in Success!</p>
                    <p className="text-2xl font-black leading-none font-heading">{lastScannedStudent.name}</p>
                    <p className="text-xs font-bold text-green-100 mt-1">{lastScannedStudent.studentId} • มาเรียน</p>
                  </div>
                </div>
              ) : (
                <div className="flex flex-col items-center gap-4 text-slate-500">
                   <div className="flex items-center gap-3 text-sm font-bold animate-pulse">
                      <Sparkles size={18} className="text-amber-500" />
                      <span>กรุณายิงบาร์โค้ด หรือ พิมพ์เลข 6 หลัก</span>
                   </div>
                </div>
              )}
           </div>

           <style dangerouslySetInnerHTML={{ __html: `
              @keyframes scan-move {
                0% { top: 0%; }
                100% { top: 100%; }
              }
           `}} />
        </div>
      )}

      <div className="bg-white p-5 md:p-8 rounded-[28px] md:rounded-[32px] border border-slate-200 shadow-sm">
        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4 md:gap-6">
          <div className="space-y-1.5">
            <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ระดับชั้น</label>
            <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 font-bold text-xs text-slate-900 outline-none transition-all">
              {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">แผนกวิชา</label>
            <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 font-bold text-xs text-slate-900 outline-none transition-all">
              {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ห้องเรียน</label>
            <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 font-bold text-xs text-slate-900 outline-none transition-all">
              {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
            </select>
          </div>
          <div className="col-span-2 md:col-span-1 lg:col-span-2 space-y-1.5">
            <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">{viewMode === 'checkin' ? 'ค้นหารายชื่อ' : 'เลือกวันที่'}</label>
            {viewMode === 'checkin' ? (
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อนักเรียน..." className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl pl-12 pr-4 py-3 font-bold text-xs text-slate-900 outline-none transition-all shadow-inner" />
              </div>
            ) : (
              <input type="date" value={selectedHistoryDate} onChange={(e) => setSelectedHistoryDate(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 font-bold text-xs text-slate-900 outline-none" />
            )}
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <>
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 px-1">
            <div className="flex gap-2">
              <button onClick={() => markAll('PRESENT')} className="flex-1 md:flex-none px-6 py-3 bg-green-50 text-green-700 rounded-xl text-[10px] font-black border border-green-200 uppercase tracking-widest hover:bg-green-100 transition-all">มาทุกคน</button>
              <button onClick={() => markAll('ABSENT')} className="flex-1 md:flex-none px-6 py-3 bg-red-50 text-red-700 rounded-xl text-[10px] font-black border border-red-200 uppercase tracking-widest hover:bg-red-100 transition-all">ขาดทุกคน</button>
            </div>
            <button 
              onClick={handleSave} 
              disabled={isSaving}
              className={`flex items-center justify-center gap-3 px-10 py-5 rounded-2xl text-white font-black transition-all shadow-xl active:scale-95 ${
                isSaved ? 'bg-green-600 shadow-green-200' : 
                isSaving ? 'bg-slate-400 cursor-not-allowed' : 'bg-slate-900 hover:bg-black'
              }`}
            >
              {isSaving ? <Loader2 size={22} className="animate-spin" /> : isSaved ? <CheckCircle2 size={22} /> : <Save size={22} />} 
              <span className="text-sm md:text-base font-heading">{isSaving ? 'กำลังบันทึก...' : isSaved ? 'บันทึกสำเร็จ' : 'บันทึกข้อมูลวันนี้'}</span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {filteredStudents.map((student, index) => (
              <div key={student.id} className={`bg-white p-6 rounded-[32px] border-2 flex flex-col gap-5 group transition-all relative overflow-hidden ${currentSession[student.id] === 'PRESENT' ? 'border-green-400 bg-green-50/10' : 'border-slate-100 hover:border-blue-300'}`}>
                {currentSession[student.id] === 'PRESENT' && (
                   <div className="absolute top-0 right-0 p-4 text-green-500/20">
                      <CheckCircle2 size={64} />
                   </div>
                )}

                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-white text-sm shrink-0 shadow-lg group-hover:scale-110 transition-transform">{index + 1}</div>
                    <div className="min-w-0">
                      <h4 className="font-black text-slate-900 text-base truncate font-heading">{student.name}</h4>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">ID: {student.studentId}</p>
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-5 gap-2">
                  {Object.entries(STATUS_LABELS).map(([key, value]) => (
                    <button 
                      key={key} 
                      onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} 
                      className={`flex flex-col items-center gap-2 p-2 rounded-xl border-2 transition-all ${currentSession[student.id] === key ? value.color + ' border-current shadow-sm' : 'bg-white border-slate-50 text-slate-300 hover:border-slate-200'}`}
                    >
                      <div className="scale-90 md:scale-100">{value.icon}</div>
                      <span className="text-[8px] font-black uppercase text-center leading-tight tracking-tighter">{value.label}</span>
                    </button>
                  ))}
                </div>

                {(currentSession[student.id] && currentSession[student.id] !== 'PRESENT') && (
                  <div className="relative animate-in slide-in-from-top-2">
                    <MessageSquare className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                    <input type="text" value={remarks[student.id] || ''} onChange={(e) => setRemarks(prev => ({ ...prev, [student.id]: e.target.value }))} placeholder="ระบุเหตุผลในการลา/ขาด..." className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-10 pr-4 py-2.5 font-bold text-slate-900 outline-none text-[10px] focus:border-blue-500 transition-all shadow-inner" />
                  </div>
                )}
              </div>
            ))}
            {filteredStudents.length === 0 && (
              <div className="col-span-full py-24 text-center bg-white rounded-[40px] border-4 border-dashed border-slate-50">
                <Sun size={64} className="mx-auto opacity-10 mb-6" />
                <p className="text-slate-300 font-black uppercase tracking-[0.3em] text-sm">ไม่พบรายชื่อในกลุ่มนี้</p>
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {historyRecords.length > 0 ? historyRecords.map((record) => {
            const student = students.find(s => s.id === record.studentId);
            return (
              <div key={record.id} className="bg-white p-6 rounded-[32px] border border-slate-200 flex flex-col gap-4 shadow-sm hover:shadow-md transition-all">
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center shadow-inner"><ClipboardCheck size={20} /></div>
                    <div>
                       <p className="text-sm font-black text-slate-900 font-heading leading-none">{student?.name}</p>
                       <p className="text-[10px] text-slate-400 font-bold mt-1 uppercase tracking-widest">{record.date}</p>
                    </div>
                  </div>
                  <span className={`px-4 py-1.5 rounded-full text-[9px] font-black border uppercase tracking-widest shadow-sm ${STATUS_LABELS[record.status].color}`}>
                    {STATUS_LABELS[record.status].label}
                  </span>
                </div>
                {record.remark && (
                  <div className="p-3 bg-slate-50 rounded-2xl text-[10px] font-bold text-slate-600 flex items-center gap-3 border border-slate-100">
                    <MessageSquare size={14} className="text-slate-400" /> {record.remark}
                  </div>
                )}
                <div className="text-[9px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5 mt-1 opacity-60">
                   <Clock size={12} /> บันทึกเมื่อ {record.timestamp}
                </div>
              </div>
            );
          }) : (
            <div className="col-span-full py-24 text-center bg-white rounded-[40px] border-4 border-dashed border-slate-50">
               <History size={64} className="mx-auto text-slate-100 mb-6" />
               <p className="text-slate-300 font-black uppercase tracking-[0.3em] text-sm">ไม่พบข้อมูลประวัติ</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default MorningAttendance;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Student, AttendanceRecord, AttendanceStatus } from '../types';
import { STATUS_LABELS } from '../constants';
import { 
  Search, Save, CheckCircle2, History, ClipboardCheck, 
  MessageSquare, Share2, Sun, Loader2, X, Scan, Camera, CameraOff,
  UserCheck, AlertCircle, Sparkles, Check, Clock
} from 'lucide-react';

interface MorningAttendanceProps {
  students: Student[];
  setStudents: React.Dispatch<React.SetStateAction<Student[]>>;
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
  rooms: string[];
  setRooms: React.Dispatch<React.SetStateAction<string[]>>;
}

const MorningAttendance: React.FC<MorningAttendanceProps> = ({ 
  students, 
  attendanceRecords, 
  setAttendanceRecords
}) => {
  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).map(String).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).map(String).sort(), [students]);
  const availableRooms = useMemo(() => Array.from(new Set(students.map(s => s.room))).map(String).sort((a,b) => parseInt(a)-parseInt(b)), [students]);

  const [level, setLevel] = useState<string>(availableLevels[0] || '');
  const [dept, setDept] = useState<string>(availableDepts[0] || '');
  const [room, setRoom] = useState<string>(availableRooms[0] || '');

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedHistoryDate, setSelectedHistoryDate] = useState<string>('');
  const [currentSession, setCurrentSession] = useState<Record<string, AttendanceStatus>>({});
  const [remarks, setRemarks] = useState<Record<string, string>>({});
  const [isSaving, setIsSaving] = useState(false);
  const [isSaved, setIsSaved] = useState(false);
  const [viewMode, setViewMode] = useState<'checkin' | 'history'>('checkin');

  // Barcode Scanner States
  const [isScannerEnabled, setIsScannerEnabled] = useState(false);
  const [barcodeInput, setBarcodeInput] = useState('');
  const [lastScannedStudent, setLastScannedStudent] = useState<Student | null>(null);
  const scanInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (availableLevels.length > 0 && !level) setLevel(availableLevels[0]);
    if (availableDepts.length > 0 && !dept) setDept(availableDepts[0]);
    if (availableRooms.length > 0 && !room) setRoom(availableRooms[0]);
  }, [availableLevels, availableDepts, availableRooms]);

  useEffect(() => {
    const rawDate = new Date().toISOString().split('T')[0];
    const todayRecords = attendanceRecords.filter(r => r.date === rawDate && r.type === 'MORNING');
    const sessionMap: Record<string, AttendanceStatus> = {};
    const remarkMap: Record<string, string> = {};
    todayRecords.forEach(r => {
      sessionMap[r.studentId] = r.status;
      if (r.remark) remarkMap[r.studentId] = r.remark;
    });
    setCurrentSession(sessionMap);
    setRemarks(remarkMap);
  }, [level, dept, room, attendanceRecords]);

  // Handle Scanner Focus Logic
  useEffect(() => {
    let focusInterval: number;
    if (isScannerEnabled && viewMode === 'checkin') {
      scanInputRef.current?.focus();
      // สร้าง interval เพื่อดึงโฟกัสกลับมาเสมอ ป้องกันครูเผลอไปกดที่อื่น
      focusInterval = window.setInterval(() => {
        if (document.activeElement !== scanInputRef.current) {
          scanInputRef.current?.focus();
        }
      }, 1000);
    }
    return () => clearInterval(focusInterval);
  }, [isScannerEnabled, viewMode]);

  const filteredStudents = students.filter(s => 
    s.level === level && s.department === dept && s.room === room &&
    (s.name.toLowerCase().includes(searchTerm.toLowerCase()) || s.studentId.includes(searchTerm))
  );

  const historyRecords = useMemo(() => {
    return attendanceRecords.filter(record => {
      const student = students.find(s => s.id === record.studentId);
      const matchesFilter = record.type === 'MORNING' && student?.level === level && student?.department === dept && student?.room === room;
      const matchesDate = selectedHistoryDate ? record.date === selectedHistoryDate : true;
      return matchesFilter && matchesDate;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [attendanceRecords, students, level, dept, room, selectedHistoryDate]);

  const handleStatusChange = (studentId: string, status: AttendanceStatus) => {
    setCurrentSession(prev => ({ ...prev, [studentId]: status }));
    setIsSaved(false);
  };

  const handleBarcodeScan = (e: React.FormEvent) => {
    e.preventDefault();
    if (!barcodeInput) return;

    // ค้นหานักเรียนจาก studentId
    const scannedStudent = students.find(s => s.studentId === barcodeInput.trim());

    if (scannedStudent) {
      handleStatusChange(scannedStudent.id, 'PRESENT');
      setLastScannedStudent(scannedStudent);

      // เสียง Beep สัญญาณสำเร็จ
      try {
        const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2571/2571-preview.mp3');
        audio.volume = 0.5;
        audio.play();
      } catch (err) {}

      // เคลียร์ feedback หลังจาก 2 วินาที
      setTimeout(() => setLastScannedStudent(null), 2500);
    } else {
      setLastScannedStudent(null);
    }

    setBarcodeInput('');
    scanInputRef.current?.focus();
  };

  const handleSave = async () => {
    setIsSaving(true);
    await new Promise(resolve => setTimeout(resolve, 600));
    const rawDate = new Date().toISOString().split('T')[0];
    const timestamp = new Date().toLocaleString('th-TH');
    const newRecordsBatch: AttendanceRecord[] = filteredStudents.map(s => ({
      id: `MORNING_${rawDate}_${s.id}`,
      studentId: s.id,
      date: rawDate,
      type: 'MORNING',
      status: currentSession[s.id] || 'ABSENT',
      remark: remarks[s.id] || '',
      timestamp: timestamp
    }));
    setAttendanceRecords(prev => {
      const studentIds = filteredStudents.map(s => s.id);
      const otherRecords = prev.filter(r => !(r.date === rawDate && r.type === 'MORNING' && studentIds.includes(r.studentId)));
      return [...otherRecords, ...newRecordsBatch];
    });
    setIsSaving(false);
    setIsSaved(true);
    setTimeout(() => setIsSaved(false), 2000);
  };

  const markAll = (status: AttendanceStatus) => {
    const newBatch: Record<string, AttendanceStatus> = {};
    filteredStudents.forEach(s => { newBatch[s.id] = status; });
    setCurrentSession(prev => ({ ...prev, ...newBatch }));
    setIsSaved(false);
  };

  const shareToLine = () => {
    const rawDate = new Date().toLocaleDateString('th-TH', { 
      day: 'numeric', 
      month: 'long', 
      year: 'numeric' 
    });
    let text = `📋 รายงานเช็คชื่อเข้าแถว\n`;
    text += `🗓️ วันที่: ${rawDate}\n`;
    text += `🏫 ${level} / ${dept} (ห้อง ${room})\n`;
    text += `--------------------------\n`;
    filteredStudents.forEach((s, idx) => {
      const status = currentSession[s.id] || 'ABSENT';
      let icon = '❌'; 
      if (status === 'PRESENT') icon = '✅';
      else if (status === 'LATE') icon = '⏰';
      else if (status === 'SICK_LEAVE' || status === 'BUSINESS_LEAVE') icon = '📝';
      text += `${idx + 1}. ${s.name} ${icon}\n`;
    });
    text += `--------------------------\n`;
    const presents = filteredStudents.filter(s => currentSession[s.id] === 'PRESENT').length;
    text += `✅ มา: ${presents} | 👥 รวม: ${filteredStudents.length}\n`;
    text += `ระบบ EduSmart CMS`;
    window.open(`https://line.me/R/msg/text/?${encodeURIComponent(text)}`, '_blank');
  };

  return (
    <div className="space-y-6 md:space-y-8 animate-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
        <div className="flex bg-white p-2 rounded-[22px] border border-slate-200 shadow-sm w-full md:w-fit">
          <button onClick={() => setViewMode('checkin')} className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-8 py-3.5 rounded-xl text-sm font-black transition-all ${viewMode === 'checkin' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><ClipboardCheck size={18} /> เช็คชื่อวันนี้</button>
          <button onClick={() => setViewMode('history')} className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-8 py-3.5 rounded-xl text-sm font-black transition-all ${viewMode === 'history' ? 'bg-blue-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}><History size={18} /> ประวัติ</button>
        </div>

        <div className="flex gap-3 w-full md:w-auto">
          {viewMode === 'checkin' && (
            <button 
              onClick={() => setIsScannerEnabled(!isScannerEnabled)}
              className={`flex-1 md:flex-none flex items-center justify-center gap-3 px-6 py-4 rounded-2xl text-[11px] md:text-sm font-black shadow-xl transition-all uppercase tracking-widest font-heading active:scale-95 border-2 ${isScannerEnabled ? 'bg-amber-500 border-amber-600 text-white' : 'bg-white border-slate-200 text-slate-600'}`}
            >
              {isScannerEnabled ? <CameraOff size={20} /> : <Scan size={20} />}
              {isScannerEnabled ? 'ปิดระบบสแกน' : 'เปิดโหมดสแกน'}
            </button>
          )}

          {viewMode === 'checkin' && filteredStudents.length > 0 && (
            <button 
              onClick={shareToLine}
              className="flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-4 bg-[#06C755] text-white rounded-2xl text-[11px] md:text-sm font-black shadow-xl hover:bg-green-600 transition-all uppercase tracking-widest font-heading active:scale-95"
            >
              <Share2 size={18} /> แชร์ LINE
            </button>
          )}
        </div>
      </div>

      {/* Barcode Scanner UI Panel */}
      {viewMode === 'checkin' && isScannerEnabled && (
        <div className="bg-slate-950 p-8 md:p-12 rounded-[40px] shadow-2xl animate-in zoom-in duration-300 relative overflow-hidden border-4 border-amber-400">
           {/* Scan Line Animation */}
           <div className="absolute inset-0 pointer-events-none overflow-hidden opacity-10">
              <div className="w-full h-1 bg-amber-400 absolute animate-[scan-move_3s_linear_infinite]" />
           </div>

           <div className="flex flex-col items-center text-center space-y-8 relative z-10">
              <div className="space-y-3">
                <div className="flex items-center justify-center gap-3 text-amber-400">
                  <Scan size={32} className="animate-pulse" />
                  <h3 className="text-3xl font-black text-white font-heading uppercase tracking-tight">Scanner Terminal</h3>
                </div>
                <p className="text-slate-500 font-bold text-xs uppercase tracking-[0.3em]">พร้อมรับรหัสนักเรียนจากเครื่องสแกน หรือ กล้อง</p>
              </div>

              <form onSubmit={handleBarcodeScan} className="w-full max-w-lg">
                <div className="relative group">
                   <input 
                    ref={scanInputRef}
                    type="text" 
                    value={barcodeInput}
                    onChange={(e) => setBarcodeInput(e.target.value)}
                    placeholder="สแกนบาร์โค้ดที่นี่..."
                    className="w-full bg-white/5 border-2 border-white/20 focus:border-amber-400 rounded-[32px] px-10 py-8 text-4xl font-black text-white outline-none transition-all placeholder:text-white/10 text-center tracking-[0.2em]"
                   />
                   <div className="absolute right-6 top-1/2 -translate-y-1/2 text-white/20">
                      <Loader2 className="animate-spin" size={24} />
                   </div>
                </div>
              </form>

              {lastScannedStudent ? (
                <div className="flex items-center gap-6 bg-green-600 text-white px-10 py-6 rounded-[32px] shadow-2xl animate-in slide-in-from-bottom-6 duration-300 border-2 border-white/20">
                  <div className="p-4 bg-white/20 rounded-2xl">
                    {/* Fixed: Used imported Check icon */}
                    <Check size={32} strokeWidth={4} />
                  </div>
                  <div className="text-left">
                    <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-80 mb-1">Check-in Success!</p>
                    <p className="text-2xl font-black leading-none font-heading">{lastScannedStudent.name}</p>
                    <p className="text-xs font-bold text-green-100 mt-1">{lastScannedStudent.studentId} • มาเรียน</p>
                  </div>
                </div>
              ) : (
                <div className="flex flex-col items-center gap-4 text-slate-500">
                   <div className="flex items-center gap-3 text-sm font-bold animate-pulse">
                      <Sparkles size={18} className="text-amber-500" />
                      <span>กรุณายิงบาร์โค้ด หรือ พิมพ์เลข 6 หลัก</span>
                   </div>
                </div>
              )}
           </div>

           <style dangerouslySetInnerHTML={{ __html: `
              @keyframes scan-move {
                0% { top: 0%; }
                100% { top: 100%; }
              }
           `}} />
        </div>
      )}

      <div className="bg-white p-5 md:p-8 rounded-[28px] md:rounded-[32px] border border-slate-200 shadow-sm">
        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4 md:gap-6">
          <div className="space-y-1.5">
            <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ระดับชั้น</label>
            <select value={level} onChange={(e) => setLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 font-bold text-xs text-slate-900 outline-none transition-all">
              {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">แผนกวิชา</label>
            <select value={dept} onChange={(e) => setDept(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 font-bold text-xs text-slate-900 outline-none transition-all">
              {availableDepts.map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
          <div className="space-y-1.5">
            <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">ห้องเรียน</label>
            <select value={room} onChange={(e) => setRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 font-bold text-xs text-slate-900 outline-none transition-all">
              {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
            </select>
          </div>
          <div className="col-span-2 md:col-span-1 lg:col-span-2 space-y-1.5">
            <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-1 font-heading">{viewMode === 'checkin' ? 'ค้นหารายชื่อ' : 'เลือกวันที่'}</label>
            {viewMode === 'checkin' ? (
              <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="พิมพ์ชื่อนักเรียน..." className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl pl-12 pr-4 py-3 font-bold text-xs text-slate-900 outline-none transition-all shadow-inner" />
              </div>
            ) : (
              <input type="date" value={selectedHistoryDate} onChange={(e) => setSelectedHistoryDate(e.target.value)} className="w-full bg-slate-50 border-2 border-transparent focus:border-blue-500 rounded-xl px-4 py-3 font-bold text-xs text-slate-900 outline-none" />
            )}
          </div>
        </div>
      </div>

      {viewMode === 'checkin' ? (
        <>
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 px-1">
            <div className="flex gap-2">
              <button onClick={() => markAll('PRESENT')} className="flex-1 md:flex-none px-6 py-3 bg-green-50 text-green-700 rounded-xl text-[10px] font-black border border-green-200 uppercase tracking-widest hover:bg-green-100 transition-all">มาทุกคน</button>
              <button onClick={() => markAll('ABSENT')} className="flex-1 md:flex-none px-6 py-3 bg-red-50 text-red-700 rounded-xl text-[10px] font-black border border-red-200 uppercase tracking-widest hover:bg-red-100 transition-all">ขาดทุกคน</button>
            </div>
            <button 
              onClick={handleSave} 
              disabled={isSaving}
              className={`flex items-center justify-center gap-3 px-10 py-5 rounded-2xl text-white font-black transition-all shadow-xl active:scale-95 ${
                isSaved ? 'bg-green-600 shadow-green-200' : 
                isSaving ? 'bg-slate-400 cursor-not-allowed' : 'bg-slate-900 hover:bg-black'
              }`}
            >
              {isSaving ? <Loader2 size={22} className="animate-spin" /> : isSaved ? <CheckCircle2 size={22} /> : <Save size={22} />} 
              <span className="text-sm md:text-base font-heading">{isSaving ? 'กำลังบันทึก...' : isSaved ? 'บันทึกสำเร็จ' : 'บันทึกข้อมูลวันนี้'}</span>
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {filteredStudents.map((student, index) => (
              <div key={student.id} className={`bg-white p-6 rounded-[32px] border-2 flex flex-col gap-5 group transition-all relative overflow-hidden ${currentSession[student.id] === 'PRESENT' ? 'border-green-400 bg-green-50/10' : 'border-slate-100 hover:border-blue-300'}`}>
                {currentSession[student.id] === 'PRESENT' && (
                   <div className="absolute top-0 right-0 p-4 text-green-500/20">
                      <CheckCircle2 size={64} />
                   </div>
                )}

                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-slate-900 rounded-2xl flex items-center justify-center font-black text-white text-sm shrink-0 shadow-lg group-hover:scale-110 transition-transform">{index + 1}</div>
                    <div className="min-w-0">
                      <h4 className="font-black text-slate-900 text-base truncate font-heading">{student.name}</h4>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">ID: {student.studentId}</p>
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-5 gap-2">
                  {Object.entries(STATUS_LABELS).map(([key, value]) => (
                    <button 
                      key={key} 
                      onClick={() => handleStatusChange(student.id, key as AttendanceStatus)} 
                      className={`flex flex-col items-center gap-2 p-2 rounded-xl border-2 transition-all ${currentSession[student.id] === key ? value.color + ' border-current shadow-sm' : 'bg-white border-slate-50 text-slate-300 hover:border-slate-200'}`}
                    >
                      <div className="scale-90 md:scale-100">{value.icon}</div>
                      <span className="text-[8px] font-black uppercase text-center leading-tight tracking-tighter">{value.label}</span>
                    </button>
                  ))}
                </div>

                {(currentSession[student.id] && currentSession[student.id] !== 'PRESENT') && (
                  <div className="relative animate-in slide-in-from-top-2">
                    <MessageSquare className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={14} />
                    <input type="text" value={remarks[student.id] || ''} onChange={(e) => setRemarks(prev => ({ ...prev, [student.id]: e.target.value }))} placeholder="ระบุเหตุผลในการลา/ขาด..." className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-10 pr-4 py-2.5 font-bold text-slate-900 outline-none text-[10px] focus:border-blue-500 transition-all shadow-inner" />
                  </div>
                )}
              </div>
            ))}
            {filteredStudents.length === 0 && (
              <div className="col-span-full py-24 text-center bg-white rounded-[40px] border-4 border-dashed border-slate-50">
                <Sun size={64} className="mx-auto opacity-10 mb-6" />
                <p className="text-slate-300 font-black uppercase tracking-[0.3em] text-sm">ไม่พบรายชื่อในกลุ่มนี้</p>
              </div>
            )}
          </div>
        </>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {historyRecords.length > 0 ? historyRecords.map((record) => {
            const student = students.find(s => s.id === record.studentId);
            return (
              <div key={record.id} className="bg-white p-6 rounded-[32px] border border-slate-200 flex flex-col gap-4 shadow-sm hover:shadow-md transition-all">
                <div className="flex justify-between items-start">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center shadow-inner"><ClipboardCheck size={20} /></div>
                    <div>
                       <p className="text-sm font-black text-slate-900 font-heading leading-none">{student?.name}</p>
                       <p className="text-[10px] text-slate-400 font-bold mt-1 uppercase tracking-widest">{record.date}</p>
                    </div>
                  </div>
                  <span className={`px-4 py-1.5 rounded-full text-[9px] font-black border uppercase tracking-widest shadow-sm ${STATUS_LABELS[record.status].color}`}>
                    {STATUS_LABELS[record.status].label}
                  </span>
                </div>
                {record.remark && (
                  <div className="p-3 bg-slate-50 rounded-2xl text-[10px] font-bold text-slate-600 flex items-center gap-3 border border-slate-100">
                    <MessageSquare size={14} className="text-slate-400" /> {record.remark}
                  </div>
                )}
                <div className="text-[9px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5 mt-1 opacity-60">
                   {/* Fixed: Used imported Clock icon */}
                   <Clock size={12} /> บันทึกเมื่อ {record.timestamp}
                </div>
              </div>
            );
          }) : (
            <div className="col-span-full py-24 text-center bg-white rounded-[40px] border-4 border-dashed border-slate-50">
               <History size={64} className="mx-auto text-slate-100 mb-6" />
               <p className="text-slate-300 font-black uppercase tracking-[0.3em] text-sm">ไม่พบข้อมูลประวัติ</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default MorningAttendance;

import React from 'react';
import { 
  LayoutDashboard, 
  Users, 
  BookOpen, 
  Award, 
  CheckCircle, 
  Clock, 
  XCircle, 
  FileText,
  UserPlus,
  Briefcase,
  Thermometer,
  Settings,
  ShieldCheck,
  Star,
  Activity,
  CreditCard,
  Banknote,
  MessageCircle,
  CloudCog,
  Scan
} from 'lucide-react';

export const COLORS = {
  primary: '#0f172a',
  secondary: '#334155',
  accent: '#2563eb',
  success: '#16a34a',
  warning: '#d97706',
  danger: '#dc2626',
  info: '#0891b2',
};

export const STATUS_LABELS: Record<string, { label: string; color: string; icon: React.ReactNode }> = {
  PRESENT: { 
    label: 'มาเรียน', 
    color: 'bg-green-100 text-green-800 border-green-200', 
    icon: <CheckCircle className="w-4 h-4" /> 
  },
  LATE: { 
    label: 'มาสาย', 
