export default QuickScan;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Student, AttendanceRecord, SystemConfig } from '../types';
import { 
  Scan, Loader2, Check, X, ShieldAlert, Sparkles, UserCheck, 
  History, Clock, Camera, Keyboard, Share2, MessageSquare, ChevronRight
} from 'lucide-react';

interface QuickScanProps {
  students: Student[];
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
}

const QuickScan: React.FC<QuickScanProps> = ({ students, attendanceRecords, setAttendanceRecords }) => {
  const [barcodeInput, setBarcodeInput] = useState('');
  const [lastScannedStudent, setLastScannedStudent] = useState<Student | null>(null);
  const [scanError, setScanError] = useState<string | null>(null);
  const [lastStatus, setLastStatus] = useState<'PRESENT' | 'LATE' | null>(null);
  const [isCameraActive, setIsCameraActive] = useState(false);
  const scanInputRef = useRef<HTMLInputElement>(null);

  // Filter settings for Line Sharing
  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).sort(), [students]);
  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).sort(), [students]);
  const availableRooms = useMemo(() => Array.from(new Set(students.map(s => s.room))).sort(), [students]);

  const [reportLevel, setReportLevel] = useState(availableLevels[0] || '');
  const [reportDept, setReportDept] = useState(availableDepts[0] || '');
  const [reportRoom, setReportRoom] = useState(availableRooms[0] || '');

  // Load System Settings
  const config: SystemConfig = useMemo(() => {
    const saved = localStorage.getItem('cms_system_config');
    return saved ? JSON.parse(saved) : { morningTimeLimit: '08:00', scanMode: 'BARCODE_SCANNER' };
  }, []);

  // Keep focus on input if using Barcode Scanner mode
  useEffect(() => {
    if (config.scanMode === 'BARCODE_SCANNER' && !isCameraActive) {
      const interval = setInterval(() => {
        if (document.activeElement !== scanInputRef.current) {
          scanInputRef.current?.focus();
        }
      }, 1000);
      return () => clearInterval(interval);
    }
  }, [config.scanMode, isCameraActive]);

  const todayDate = new Date().toISOString().split('T')[0];

  const todayScans = useMemo(() => {
    return attendanceRecords
      .filter(r => r.date === todayDate && r.type === 'MORNING')
      .sort((a, b) => b.timestamp.localeCompare(a.timestamp));
  }, [attendanceRecords, todayDate]);

  const handleScanLogic = (input: string) => {
    setScanError(null);
    const student = students.find(s => s.studentId === input);

    if (student) {
      const now = new Date();
      const timestamp = now.toLocaleString('th-TH');

      const [limitHour, limitMin] = config.morningTimeLimit.split(':').map(Number);
      const limitTime = new Date();
      limitTime.setHours(limitHour, limitMin, 0);

      const status = now > limitTime ? 'LATE' : 'PRESENT';
      setLastStatus(status as any);

      const newRecord: AttendanceRecord = {
        id: `MORNING_${todayDate}_${student.id}`,
        studentId: student.id,
        date: todayDate,
        type: 'MORNING',
        status: status as any,
        timestamp: timestamp
      };

      setAttendanceRecords(prev => {
        const filtered = prev.filter(r => !(r.studentId === student.id && r.date === todayDate && r.type === 'MORNING'));
        return [newRecord, ...filtered];
      });

      setLastScannedStudent(student);

      try {
        const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2571/2571-preview.mp3');
        audio.play();
      } catch (err) {}

      setTimeout(() => setLastScannedStudent(null), 3000);
    } else {
      setScanError(`ไม่พบรหัส: ${input}`);
      setTimeout(() => setScanError(null), 3000);
    }
    setBarcodeInput('');
  };

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    handleScanLogic(barcodeInput.trim());
  };

  const shareLineReport = () => {
    const roomStudents = students.filter(s => 
      s.level === reportLevel && s.department === reportDept && s.room === reportRoom
    );

    if (roomStudents.length === 0) return alert('ไม่พบรายชื่อในห้องที่เลือก');

    const rawDate = new Date().toLocaleDateString('th-TH', { 
      day: 'numeric', month: 'long', year: 'numeric' 
    });

    let text = `📋 รายงานเข้าแถว (Scan Terminal)\n`;
    text += `🗓️ วันที่: ${rawDate}\n`;
    text += `🏫 ${reportLevel} / ${reportDept} ห้อง ${reportRoom}\n`;
    text += `--------------------------\n`;

    roomStudents.forEach((s, idx) => {
      const record = attendanceRecords.find(r => 
        r.studentId === s.id && r.date === todayDate && r.type === 'MORNING'
      );
      let statusIcon = '❌';
      if (record?.status === 'PRESENT') statusIcon = '✅';
      else if (record?.status === 'LATE') statusIcon = '⏰';

      text += `${idx + 1}. ${s.name} ${statusIcon}\n`;
    });

    text += `--------------------------\n`;
    const presentCount = roomStudents.filter(s => 
      attendanceRecords.some(r => r.studentId === s.id && r.date === todayDate && r.type === 'MORNING' && (r.status === 'PRESENT' || r.status === 'LATE'))
    ).length;

    text += `✅ มา: ${presentCount} | 👥 รวม: ${roomStudents.length}\n`;
    text += `ระบบ EduSmart CMS (Terminal)`;

    window.open(`https://line.me/R/msg/text/?${encodeURIComponent(text)}`, '_blank');
  };

  return (
    <div className="grid grid-cols-1 xl:grid-cols-3 gap-8 animate-in fade-in duration-500 pb-20 max-w-[1600px] mx-auto">
      {/* Main Scan Terminal Area */}
      <div className="xl:col-span-2 space-y-8">
        <div className="bg-slate-950 p-10 md:p-14 rounded-[48px] shadow-2xl relative overflow-hidden border-4 border-amber-500">
          <div className="absolute inset-0 pointer-events-none opacity-10">
            <div className="w-full h-1 bg-amber-500 absolute animate-[scan-line_3s_linear_infinite]" />
          </div>

          <div className="flex flex-col items-center text-center space-y-10 relative z-10">
            <div className="space-y-3">
              <div className="flex items-center justify-center gap-4 text-amber-500">
                {config.scanMode === 'CAMERA' ? <Camera size={44} /> : <Scan size={44} className="animate-pulse" />}
                <h2 className="text-4xl font-black text-white font-heading uppercase tracking-tighter">
                  {config.scanMode === 'CAMERA' ? 'Camera Scanner' : 'Barcode Terminal'}
                </h2>
              </div>
              <div className="flex items-center justify-center gap-2">
                 <span className="px-3 py-1 bg-white/10 rounded-full text-[10px] font-black text-slate-400 uppercase tracking-widest border border-white/5">
                   เกณฑ์เวลา: {config.morningTimeLimit} น.
                 </span>
                 <span className="px-3 py-1 bg-blue-500/10 rounded-full text-[10px] font-black text-blue-400 uppercase tracking-widest border border-blue-500/20">
                   โหมด: {config.scanMode === 'CAMERA' ? 'กล้อง' : 'เครื่องยิง'}
                 </span>
              </div>
            </div>

            <div className="w-full max-w-xl space-y-6">
              {config.scanMode === 'CAMERA' ? (
                <div className="space-y-6">
                  {!isCameraActive ? (
                    <button 
                      onClick={() => setIsCameraActive(true)}
                      className="w-full bg-amber-500 text-slate-950 hover:bg-amber-400 py-10 rounded-[32px] flex flex-col items-center justify-center gap-4 transition-all shadow-2xl active:scale-95 group"
                    >
                      <div className="p-4 bg-slate-900/10 rounded-2xl group-hover:scale-110 transition-transform">
                        <Camera size={48} />
                      </div>
                      <span className="text-2xl font-black uppercase tracking-widest font-heading">เปิดกล้องสแกนบาร์โค้ด</span>
                    </button>
                  ) : (
                    <div className="relative w-full aspect-video bg-black rounded-[32px] border-4 border-white/10 overflow-hidden shadow-2xl">
                      <div className="absolute inset-0 flex items-center justify-center text-white/20">
                         <Loader2 className="animate-spin" size={48} />
                      </div>
                      {/* Simulating camera viewfinder */}
                      <div className="absolute inset-0 border-[60px] border-black/40 pointer-events-none"></div>
                      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-32 border-2 border-amber-400/50 rounded-lg"></div>

                      <button 
                        onClick={() => setIsCameraActive(false)}
                        className="absolute bottom-6 right-6 p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl"
                      >
                        <X size={24} />
                      </button>
                    </div>
                  )}
                  {/* Manual input fallback for camera mode */}
                  <form onSubmit={handleFormSubmit} className="flex gap-2">
                    <input 
                      type="text"
                      value={barcodeInput}
                      onChange={(e) => setBarcodeInput(e.target.value)}
                      placeholder="หรือพิมพ์รหัสที่นี่..."
                      className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white font-bold outline-none focus:border-amber-400"
                    />
                    <button type="submit" className="px-8 py-4 bg-white/10 text-white rounded-2xl font-black">ตกลง</button>
                  </form>
                </div>
              ) : (
                <form onSubmit={handleFormSubmit} className="relative group">
                  <input 
                    ref={scanInputRef}
                    type="text" 
                    value={barcodeInput}
                    onChange={(e) => setBarcodeInput(e.target.value)}
                    autoFocus
                    placeholder="สแกนบาร์โค้ด..."
                    className="w-full bg-white/5 border-2 border-white/20 focus:border-amber-400 rounded-[32px] px-10 py-10 text-5xl font-black text-white outline-none transition-all placeholder:text-white/5 text-center tracking-[0.2em] shadow-inner"
                  />
                  <div className="absolute left-8 top-1/2 -translate-y-1/2 text-white/10">
                    <Keyboard size={32} />
                  </div>
                </form>
              )}
            </div>

            <div className="h-40 flex items-center justify-center w-full">
              {lastScannedStudent ? (
                <div className={`flex items-center gap-8 px-10 py-8 rounded-[40px] shadow-2xl animate-in zoom-in duration-300 border-2 border-white/20 ${lastStatus === 'LATE' ? 'bg-amber-600' : 'bg-green-600'}`}>
                  <div className="p-5 bg-white/20 rounded-2xl shadow-inner"><Check size={44} strokeWidth={4} /></div>
                  <div className="text-left">
                    <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-80 mb-1">
                      {lastStatus === 'LATE' ? 'มาสาย (LATE)' : 'สแกนสำเร็จ (PRESENT)'}
                    </p>
                    <p className="text-4xl font-black font-heading leading-tight text-white">{lastScannedStudent.name}</p>
                    <p className="text-sm font-bold text-white/80 uppercase mt-1">{lastScannedStudent.level} • ห้อง {lastScannedStudent.room}</p>
                  </div>
                </div>
              ) : scanError ? (
                <div className="flex items-center gap-6 bg-red-600 text-white px-10 py-8 rounded-[40px] shadow-2xl animate-in shake duration-300 border-2 border-white/20">
                  <div className="p-5 bg-white/20 rounded-2xl"><ShieldAlert size={44} /></div>
                  <div className="text-left font-black uppercase tracking-widest text-2xl">{scanError}</div>
                </div>
              ) : (
                <div className="flex flex-col items-center gap-4 text-slate-500 animate-pulse">
                  <Sparkles size={24} className="text-amber-600" />
                  <p className="text-xs font-black uppercase tracking-[0.3em]">
                    {config.scanMode === 'CAMERA' ? 'เปิดกล้องและเล็งที่บาร์โค้ด' : 'ระบบพร้อมทำงาน... กรุณายิงบาร์โค้ด'}
                  </p>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Real-time History List */}
        <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-8 bg-slate-50/50 border-b flex items-center justify-between">
            <h3 className="text-lg font-black text-slate-900 font-heading flex items-center gap-3">
              <History className="text-blue-600" size={22} /> รายการสแกนล่าสุด ({todayScans.length})
            </h3>
            <div className="flex gap-4">
               <div className="flex items-center gap-2">
                  <div className="w-3 h-3 bg-green-500 rounded-full" />
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">มาเรียน</span>
               </div>
               <div className="flex items-center gap-2">
                  <div className="w-3 h-3 bg-amber-500 rounded-full" />
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">มาสาย</span>
               </div>
            </div>
          </div>
          <div className="overflow-y-auto max-h-[600px] scrollbar-hide">
            <table className="w-full text-left">
              <thead className="bg-white sticky top-0 border-b text-[10px] font-black text-slate-400 uppercase tracking-widest">
                <tr>
                  <th className="px-8 py-4">เวลา</th>
                  <th className="px-8 py-4">นักเรียน</th>
                  <th className="px-8 py-4">ห้องเรียน</th>
                  <th className="px-8 py-4 text-right">สถานะ</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {todayScans.map((r) => {
                  const student = students.find(s => s.id === r.studentId);
                  return (
                    <tr key={r.id} className="hover:bg-slate-50/50 transition-colors animate-in slide-in-from-left duration-300">
                      <td className="px-8 py-6">
                        <div className="flex items-center gap-2 text-slate-400 font-black text-sm">
                          <Clock size={14} /> {r.timestamp.split(' ')[1]}
                        </div>
                      </td>
                      <td className="px-8 py-6">
                        <p className="font-black text-slate-900">{student?.name}</p>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{student?.studentId}</p>
                      </td>
                      <td className="px-8 py-6">
                        <span className="text-xs font-bold text-slate-600">{student?.level} / {student?.room}</span>
                      </td>
                      <td className="px-8 py-6 text-right">
                        <span className={`px-4 py-1.5 rounded-xl text-[9px] font-black uppercase border ${r.status === 'LATE' ? 'bg-amber-50 text-amber-700 border-amber-100' : 'bg-green-50 text-green-700 border-green-100'}`}>
                          {r.status === 'LATE' ? 'มาสาย ⏰' : 'มาเรียน ✓'}
                        </span>
                      </td>
                    </tr>
                  );
                })}
                {todayScans.length === 0 && (
                  <tr>
                    <td colSpan={4} className="py-24 text-center">
                      <Scan size={48} className="mx-auto text-slate-100 mb-4" />
                      <p className="text-slate-300 font-black uppercase tracking-widest text-xs">ยังไม่มีประวัติการสแกนในวันนี้</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Side Panel: Room-based Reporting */}
      <div className="space-y-8">
        <div className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm space-y-8 sticky top-24">
          <div className="flex items-center gap-4">
            <div className="p-4 bg-green-50 text-green-600 rounded-[24px] shadow-sm"><Share2 size={24} /></div>
            <div>
              <h3 className="text-xl font-black text-slate-900 font-heading uppercase">แชร์รายงานรายห้อง</h3>
              <p className="text-[10px] text-slate-400 font-bold tracking-widest uppercase mt-0.5">สรุปยอดประจำวันส่งเข้า LINE</p>
            </div>
          </div>

          <div className="space-y-5">
            <div className="space-y-1.5">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 font-heading">ระดับชั้น</label>
              <select value={reportLevel} onChange={(e) => setReportLevel(e.target.value)} className="w-full bg-slate-50 border-2 border-slate-100 focus:border-green-500 rounded-xl px-4 py-3 font-bold text-sm outline-none transition-all appearance-none cursor-pointer">
