              <select value={reportRoom} onChange={(e) => setReportRoom(e.target.value)} className="w-full bg-slate-50 border-2 border-slate-100 focus:border-green-500 rounded-xl px-4 py-3 font-bold text-sm outline-none transition-all appearance-none cursor-pointer">
                {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
              </select>
            </div>

            <div className="pt-6 border-t border-slate-100 space-y-6">
               <div className="bg-slate-50 p-6 rounded-[32px] border border-slate-100 text-center">
