import React, { useState } from 'react';
import { StudyBlock } from '../types';
import { 
  Layers, 
  Sun, 
  Trash2, 
  X,
  CalendarDays
} from 'lucide-react';

interface SystemSettingsProps {
  studyBlocks: StudyBlock[];
  setStudyBlocks: (blocks: StudyBlock[]) => void;
}

const BLOCK_COLORS = ['bg-blue-600', 'bg-indigo-600', 'bg-purple-600', 'bg-pink-600', 'bg-emerald-600'];

const SystemSettings: React.FC<SystemSettingsProps> = ({ studyBlocks, setStudyBlocks }) => {
  const [deletingDate, setDeletingDate] = useState<{ blockId: number; date: string } | null>(null);

  const handleUpdateBlock = (id: number, field: keyof StudyBlock, value: any) => {
    const updated = studyBlocks.map(block => {
      if (block.id === id) {
        if (field === 'isActive' && value === true) {
          return { ...block, [field]: value };
        }
        return { ...block, [field]: value };
      }
      if (field === 'isActive' && value === true) {
        return { ...block, isActive: false };
      }
      return block;
    });
    setStudyBlocks(updated);
  };

  const processRemoveHoliday = (blockId: number, date: string) => {
    const updated = studyBlocks.map(block => block.id === blockId ? { ...block, holidays: block.holidays.filter(d => d !== date) } : block);
    setStudyBlocks(updated);
    setDeletingDate(null);
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20 max-w-7xl mx-auto">
      <div className="bg-white p-8 md:p-12 rounded-[48px] border border-slate-200 shadow-sm relative">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
          <div className="flex items-center gap-6">
            <div className="p-5 bg-slate-900 rounded-[24px] text-white shadow-2xl">
              <Layers size={32} />
            </div>
            <div>
              <h2 className="text-3xl font-black text-slate-900 tracking-tight font-heading">ตั้งค่าบล็อกเรียน (Study Blocks)</h2>
              <p className="text-sm font-bold text-slate-500 uppercase tracking-widest mt-1">กำหนดช่วงเวลาเรียนและวันหยุดพิเศษรายบล็อก</p>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 gap-12">
          {studyBlocks.map((block, idx) => (
            <div key={block.id} className={`p-8 md:p-10 rounded-[40px] border-2 transition-all duration-500 ${block.isActive ? 'border-blue-500 bg-blue-50/20 shadow-lg shadow-blue-100/50' : 'border-slate-100 bg-white'}`}>
              <div className="flex flex-col xl:flex-row items-start xl:items-center gap-10">
                <div className={`w-20 h-20 rounded-3xl flex items-center justify-center font-black text-3xl shadow-2xl text-white transition-transform duration-500 ${block.isActive ? 'scale-110 rotate-3' : ''} ${BLOCK_COLORS[idx % BLOCK_COLORS.length]}`}>
                  {block.id}
                </div>
                <div className="flex-1 space-y-4 w-full">
                   <div className="flex items-center justify-between w-full">
                     <input 
                        type="text" 
                        value={block.name} 
                        onChange={(e) => handleUpdateBlock(block.id, 'name', e.target.value)} 
                        className={`font-black text-2xl outline-none focus:ring-0 p-0 w-64 font-heading bg-transparent transition-colors ${block.isActive ? 'text-blue-900' : 'text-slate-900'}`} 
                     />

                     <div className="flex items-center gap-4">
                        <span className={`text-[10px] font-black uppercase tracking-widest hidden sm:block ${block.isActive ? 'text-blue-600' : 'text-slate-400'}`}>
                          {block.isActive ? 'เปิดใช้งานอยู่' : 'ปิดใช้งาน'}
                        </span>
                        <button 
                          onClick={() => handleUpdateBlock(block.id, 'isActive', !block.isActive)}
                          className={`relative inline-flex h-8 w-16 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-300 ease-in-out focus:outline-none ${block.isActive ? 'bg-blue-600' : 'bg-slate-200'}`}
                        >
                          <span
                            aria-hidden="true"
                            className={`pointer-events-none inline-block h-7 w-7 transform rounded-full bg-white shadow-lg ring-0 transition duration-300 ease-in-out ${block.isActive ? 'translate-x-8' : 'translate-x-0'}`}
                          />
                        </button>
                     </div>
                   </div>
                   <div className="flex flex-wrap gap-4">
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">วันที่เริ่มต้น</label>
                        <input type="date" value={block.startDate} onChange={(e) => handleUpdateBlock(block.id, 'startDate', e.target.value)} className="bg-white border-2 border-slate-100 focus:border-blue-400 rounded-xl px-4 py-2 font-bold text-sm outline-none transition-all" />
                      </div>
                      <div className="space-y-1">
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">วันที่สิ้นสุด</label>
                        <input type="date" value={block.endDate} onChange={(e) => handleUpdateBlock(block.id, 'endDate', e.target.value)} className="bg-white border-2 border-slate-100 focus:border-blue-400 rounded-xl px-4 py-2 font-bold text-sm outline-none transition-all" />
                      </div>
                   </div>
                </div>
              </div>

              <div className="mt-8 pt-8 border-t border-slate-100">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2 font-heading">
                  <Sun size={14} className="text-amber-500" /> วันหยุดพิเศษในบล็อกนี้ (ถือเป็นวันมาเรียน)
                </h4>
                <div className="flex flex-wrap gap-3">
                  {block.holidays.map(date => {
                    const isConfirming = deletingDate?.blockId === block.id && deletingDate?.date === date;
                    return (
                      <div key={date} className={`flex items-center gap-3 pl-5 pr-2 py-3 rounded-2xl border-2 font-bold text-sm transition-all ${isConfirming ? 'bg-red-600 border-red-700 text-white shadow-xl' : 'bg-slate-50 border-slate-100 text-slate-700'}`}>
                        <span>{new Date(date).toLocaleDateString('th-TH', { dateStyle: 'long' })}</span>
                        {isConfirming ? (
                          <div className="flex gap-1 animate-in slide-in-from-right-2">
                             <button onClick={() => setDeletingDate(null)} className="p-2 hover:bg-white/10 rounded-lg transition-all"><X size={16} /></button>
                             <button onClick={() => processRemoveHoliday(block.id, date)} className="p-2 hover:bg-white/10 rounded-lg transition-all font-black text-[10px] uppercase">ยืนยัน</button>
                          </div>
                        ) : (
                          <button onClick={() => setDeletingDate({ blockId: block.id, date })} className="p-2 text-slate-300 hover:text-red-600 transition-all"><Trash2 size={16} /></button>
                        )}
                      </div>
                    );
                  })}
                  <div className="relative group">
                    <CalendarDays className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 pointer-events-none" size={16} />
                    <input 
                      type="date" 
                      onChange={(e) => {
                        if (!e.target.value) return;
                        handleUpdateBlock(block.id, 'holidays', [...block.holidays, e.target.value]);
                        e.target.value = '';
                      }}
                      className="bg-white border-2 border-dashed border-slate-200 rounded-2xl pl-12 pr-5 py-3 text-xs font-bold outline-none hover:border-blue-400 transition-all cursor-pointer" 
                    />
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default SystemSettings;

import React, { useState, useEffect, useCallback } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import MorningAttendance from './components/MorningAttendance';
import QuickScan from './components/QuickScan';
import ScannerSettings from './components/ScannerSettings';
import ClassAttendance from './components/ClassAttendance';
import BehaviorSystem from './components/BehaviorSystem';
import StudentManagement from './components/StudentManagement';
import Reports from './components/Reports';
import FinanceReport from './components/FinanceReport';
import UserManagement from './components/UserManagement';
import SystemSettings from './components/SystemSettings';
import CloudConfig from './components/CloudConfig';
import LineConfig from './components/LineConfig';
import MorningScoreSummary from './components/MorningScoreSummary';
import TuitionSystem from './components/TuitionSystem';
import Login from './components/Login';
import { MOCK_STUDENTS, MOCK_ATTENDANCE, MOCK_BEHAVIOR, MOCK_SUBJECTS } from './data/mockData';
import { Student, AttendanceRecord, BehaviorRecord, Subject, User, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord } from './types';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeMenu, setActiveMenu] = useState('dashboard');
  const [isSyncingWithCloud, setIsSyncingWithCloud] = useState(false);

  const [students, setStudents] = useState<Student[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [behaviorRecords, setBehaviorRecords] = useState<BehaviorRecord[]>([]);
  const [notifications, setNotifications] = useState<NotificationRecord[]>([]);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);
  const [systemUsers, setSystemUsers] = useState<User[]>([]);
  const [tuitionConfigs, setTuitionConfigs] = useState<TuitionConfig[]>([]);
  const [paymentRecords, setPaymentRecords] = useState<PaymentRecord[]>([]);
  const [studyBlocks, setStudyBlocks] = useState<StudyBlock[]>([
    { id: 1, name: 'บล็อกที่ 1', startDate: '2024-05-15', endDate: '2024-06-15', isActive: true, holidays: [] },
    { id: 2, name: 'บล็อกที่ 2', startDate: '2024-06-16', endDate: '2024-07-16', isActive: false, holidays: [] },
    { id: 3, name: 'บล็อกที่ 3', startDate: '2024-07-17', endDate: '2024-08-17', isActive: false, holidays: [] },
    { id: 4, name: 'บล็อกที่ 4', startDate: '2024-08-18', endDate: '2024-09-18', isActive: false, holidays: [] },
    { id: 5, name: 'บล็อกที่ 5', startDate: '2024-09-19', endDate: '2024-10-19', isActive: false, holidays: [] },
  ]);

  const getScriptUrl = () => localStorage.getItem('cms_google_script_url') || '';

  const fetchDataFromCloud = useCallback(async () => {
    const url = getScriptUrl();
    if (!url) return;
    setIsSyncingWithCloud(true);
    try {
      const response = await fetch(`${url}?action=getAllData`);
      const cloudData = await response.json();
      if (cloudData.students) setStudents(cloudData.students);
      if (cloudData.attendance) setAttendance(cloudData.attendance);
      if (cloudData.behavior) setBehaviorRecords(cloudData.behavior);
      if (cloudData.payments) setPaymentRecords(cloudData.payments);
      if (cloudData.subjects) setSubjects(cloudData.subjects);
    } catch (error) {
      console.error("Cloud Sync Error:", error);
    } finally {
      setIsSyncingWithCloud(false);
    }
  }, []);

  const syncToCloud = async (type: string, data: any) => {
    const url = getScriptUrl();
    if (!url) return;
    try {
      await fetch(url, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'syncData', type, data })
      });
    } catch (e) {
      console.error("Auto Sync Failed", e);
    }
  };

  useEffect(() => {
    const savedBlocks = localStorage.getItem('cms_study_blocks');
    if (savedBlocks) setStudyBlocks(JSON.parse(savedBlocks));

    setStudents(MOCK_STUDENTS);
    setAttendance(MOCK_ATTENDANCE);
    setBehaviorRecords(MOCK_BEHAVIOR);
    setSubjects(MOCK_SUBJECTS);
    setSystemUsers([
      { id: 'A1', name: 'แอดมิน ระบบ', role: 'ADMIN', username: 'admin', password: '1234', department: 'ส่วนกลาง' },
      { id: 'T1', name: 'อ.สมพงษ์ ใจสว่าง', role: 'TEACHER', username: 'teacher', password: '1234', department: 'เทคโนโลยีสารสนเทศ' },
      { id: 'F1', name: 'ฝ่ายการเงิน', role: 'FINANCE', username: 'finance', password: '1234', department: 'ฝ่ายการเงิน' },
      { id: 'P1', name: 'คุณแม่ของนายสมชาย', role: 'PARENT', username: 'parent', password: '1234', studentId: '1' }
    ]);
    fetchDataFromCloud();
  }, [fetchDataFromCloud]);

  if (!user) return <Login onLogin={setUser} systemUsers={systemUsers} />;

  const renderContent = () => {
    switch (activeMenu) {
      case 'dashboard': return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} notifications={notifications} user={user} studyBlocks={studyBlocks} tuitionConfigs={tuitionConfigs} paymentRecords={paymentRecords} />;
      case 'quick_scan': return <QuickScan students={students} attendanceRecords={attendance} setAttendanceRecords={(val) => { setAttendance(val); syncToCloud('attendance', val); }} />;
      case 'students': return <StudentManagement students={students} setStudents={(val) => { setStudents(val); syncToCloud('students', val); }} />;
      case 'morning': return <MorningAttendance students={students} setStudents={setStudents} attendanceRecords={attendance} setAttendanceRecords={(val) => { setAttendance(val); syncToCloud('attendance', val); }} rooms={rooms} setRooms={setRooms} />;
      case 'subject': return <ClassAttendance students={students} setStudents={setStudents} subjects={subjects} setSubjects={(val) => { setSubjects(val); syncToCloud('subjects', val); }} rooms={rooms} setRooms={setRooms} attendanceRecords={attendance} setAttendanceRecords={(val) => { setAttendance(val); syncToCloud('attendance', val); }} currentUser={user} />;
      case 'behavior': return <BehaviorSystem students={students} setStudents={setStudents} behaviorRecords={behaviorRecords} setBehaviorRecords={(val) => { setBehaviorRecords(val); syncToCloud('behavior', val); }} />;
      case 'tuition': return <TuitionSystem students={students} tuitionConfigs={tuitionConfigs} setTuitionConfigs={setTuitionConfigs} paymentRecords={paymentRecords} setPaymentRecords={(val) => { setPaymentRecords(val); syncToCloud('payments', val); }} user={user} />;
      case 'finance_report': return <FinanceReport students={students} paymentRecords={paymentRecords} tuitionConfigs={tuitionConfigs} />;
      case 'report': return <Reports students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} paymentRecords={paymentRecords} tuitionConfigs={tuitionConfigs} />;
      case 'morning_scores': return <MorningScoreSummary students={students} attendance={attendance} studyBlocks={studyBlocks} />;
      case 'users': return <UserManagement users={systemUsers} setUsers={setSystemUsers} currentUser={user} students={students} />;
      case 'scanner_settings': return <ScannerSettings />;
      case 'settings': return <SystemSettings studyBlocks={studyBlocks} setStudyBlocks={(val) => { setStudyBlocks(val); localStorage.setItem('cms_study_blocks', JSON.stringify(val)); }} />;
      case 'cloud_config': return <CloudConfig students={students} attendance={attendance} behavior={behaviorRecords} payments={paymentRecords} subjects={subjects} />;
      case 'line_config': return <LineConfig />;
      default: return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} />;
    }
  };

  return (
    <Layout activeMenu={activeMenu} setActiveMenu={setActiveMenu} user={user} onLogout={() => setUser(null)} notifications={notifications} setNotifications={setNotifications}>
      {isSyncingWithCloud && (
        <div className="fixed bottom-8 right-8 z-[100] bg-slate-900 text-white px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 animate-bounce">
          <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
          <span className="text-xs font-black uppercase tracking-widest">กำลังดึงข้อมูลล่าสุดจากระบบ Cloud...</span>
        </div>
      )}
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Student, AttendanceRecord, SystemConfig } from '../types';
import { 
  Scan, Loader2, Check, X, ShieldAlert, Sparkles, 
  History, Clock, Camera, Keyboard, AlertCircle
} from 'lucide-react';

interface QuickScanProps {
  students: Student[];
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
}

const QuickScan: React.FC<QuickScanProps> = ({ students, attendanceRecords, setAttendanceRecords }) => {
  const [barcodeInput, setBarcodeInput] = useState('');
  const [lastScannedStudent, setLastScannedStudent] = useState<Student | null>(null);
  const [scanError, setScanError] = useState<string | null>(null);
  const [lastStatus, setLastStatus] = useState<'PRESENT' | 'LATE' | null>(null);
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [cameraError, setCameraError] = useState<string | null>(null);

  const scanInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  // Load System Settings
  const config: SystemConfig = useMemo(() => {
    const saved = localStorage.getItem('cms_system_config');
    return saved ? JSON.parse(saved) : { morningTimeLimit: '08:00', scanMode: 'BARCODE_SCANNER' };
  }, []);

  // Handle Focus for Barcode Scanner Mode
  useEffect(() => {
    if (config.scanMode === 'BARCODE_SCANNER' && !isCameraActive) {
      const interval = setInterval(() => {
        if (document.activeElement !== scanInputRef.current) {
          scanInputRef.current?.focus();
        }
      }, 1000);
      return () => clearInterval(interval);
    }
  }, [config.scanMode, isCameraActive]);

  // Camera Management
  useEffect(() => {
    if (isCameraActive) {
      startCamera();
    } else {
      stopCamera();
    }
    return () => stopCamera();
  }, [isCameraActive]);

  const startCamera = async () => {
    setCameraError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        streamRef.current = stream;
      }
    } catch (err: any) {
      console.error("Camera error:", err);
      setCameraError("ไม่สามารถเข้าถึงกล้องได้: " + (err.message || "โปรดตรวจสอบสิทธิ์การใช้งานกล้อง"));
      setIsCameraActive(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
  };

  const todayDate = new Date().toISOString().split('T')[0];

  const todayScans = useMemo(() => {
    return attendanceRecords
      .filter(r => r.date === todayDate && r.type === 'MORNING')
      .sort((a, b) => b.timestamp.localeCompare(a.timestamp));
  }, [attendanceRecords, todayDate]);

  const handleScanLogic = (input: string) => {
    if (!input) return;
    setScanError(null);
    const student = students.find(s => s.studentId === input);

    if (student) {
      const now = new Date();
      const timestamp = now.toLocaleString('th-TH');
      const [limitHour, limitMin] = config.morningTimeLimit.split(':').map(Number);
      const limitTime = new Date();
      limitTime.setHours(limitHour, limitMin, 0);

      const status = now > limitTime ? 'LATE' : 'PRESENT';
      setLastStatus(status as any);

      const newRecord: AttendanceRecord = {
        id: `MORNING_${todayDate}_${student.id}`,
        studentId: student.id,
        date: todayDate,
        type: 'MORNING',
        status: status as any,
        timestamp: timestamp
      };

      setAttendanceRecords(prev => {
        const filtered = prev.filter(r => !(r.studentId === student.id && r.date === todayDate && r.type === 'MORNING'));
        return [newRecord, ...filtered];
      });

      setLastScannedStudent(student);

      try {
        const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2571/2571-preview.mp3');
        audio.play();
      } catch (err) {}

      setTimeout(() => setLastScannedStudent(null), 3000);
    } else {
      setScanError(`ไม่พบรหัส: ${input}`);
      setTimeout(() => setScanError(null), 3000);
    }
    setBarcodeInput('');
  };

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    handleScanLogic(barcodeInput.trim());
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Main Scan Terminal Area */}
      <div className="bg-slate-950 p-10 md:p-14 rounded-[48px] shadow-2xl relative overflow-hidden border-4 border-amber-500">
        <div className="absolute inset-0 pointer-events-none opacity-10">
          <div className="w-full h-1 bg-amber-500 absolute animate-[scan-line_3s_linear_infinite]" />
        </div>

        <div className="flex flex-col items-center text-center space-y-10 relative z-10">
          <div className="space-y-3">
            <div className="flex items-center justify-center gap-4 text-amber-500">
              {config.scanMode === 'CAMERA' ? <Camera size={44} /> : <Scan size={44} className="animate-pulse" />}
              <h2 className="text-4xl font-black text-white font-heading uppercase tracking-tighter">
                {config.scanMode === 'CAMERA' ? 'Camera Scanner' : 'Barcode Terminal'}
              </h2>
            </div>
            <div className="flex items-center justify-center gap-2">
               <span className="px-3 py-1 bg-white/10 rounded-full text-[10px] font-black text-slate-400 uppercase tracking-widest border border-white/5">
                 สายหลัง: {config.morningTimeLimit} น.
               </span>
               <span className="px-3 py-1 bg-blue-500/10 rounded-full text-[10px] font-black text-blue-400 uppercase tracking-widest border border-blue-500/20">
                 โหมด: {config.scanMode === 'CAMERA' ? 'กล้อง' : 'เครื่องยิง'}
               </span>
            </div>
          </div>

          <div className="w-full max-w-xl space-y-6">
            {config.scanMode === 'CAMERA' ? (
              <div className="space-y-6">
                {cameraError && (
                  <div className="bg-red-500/20 border border-red-500/50 p-4 rounded-2xl flex items-center gap-3 text-red-400 text-sm mb-4">
                    <AlertCircle size={20} />
                    <span className="font-bold">{cameraError}</span>
                  </div>
                )}

                {!isCameraActive ? (
                  <button 
                    onClick={() => setIsCameraActive(true)}
                    className="w-full bg-amber-500 text-slate-950 hover:bg-amber-400 py-10 rounded-[32px] flex flex-col items-center justify-center gap-4 transition-all shadow-2xl active:scale-95 group"
                  >
                    <div className="p-4 bg-slate-900/10 rounded-2xl group-hover:scale-110 transition-transform">
                      <Camera size={48} />
                    </div>
                    <span className="text-2xl font-black uppercase tracking-widest font-heading">เปิดกล้องสแกนบาร์โค้ด</span>
                  </button>
                ) : (
                  <div className="relative w-full aspect-video bg-black rounded-[32px] border-4 border-white/10 overflow-hidden shadow-2xl">
                    <video 
                      ref={videoRef}
                      autoPlay 
                      playsInline 
                      muted
                      className="w-full h-full object-cover"
                    />
                    {/* Viewfinder overlay */}
                    <div className="absolute inset-0 border-[40px] md:border-[60px] border-black/40 pointer-events-none"></div>
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-32 border-2 border-amber-400/80 rounded-lg shadow-[0_0_30px_rgba(251,191,36,0.3)]">
                      <div className="w-full h-0.5 bg-amber-400 absolute top-1/2 -translate-y-1/2 animate-[pulse_1s_infinite]" />
                    </div>

                    <button 
                      onClick={() => setIsCameraActive(false)}
                      className="absolute bottom-6 right-6 p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl active:scale-90"
                    >
                      <X size={24} />
                    </button>

                    <div className="absolute bottom-6 left-1/2 -translate-x-1/2 bg-black/60 backdrop-blur-md px-4 py-2 rounded-full border border-white/10">
                       <p className="text-[10px] font-black text-amber-400 uppercase tracking-widest">เล็งบาร์โค้ดให้อยู่ในกรอบ</p>
                    </div>
                  </div>
                )}

                {/* Manual input fallback */}
                <form onSubmit={handleFormSubmit} className="flex gap-2">
                  <input 
                    type="text"
                    value={barcodeInput}
                    onChange={(e) => setBarcodeInput(e.target.value)}
                    placeholder="หรือพิมพ์รหัสที่นี่..."
                    className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white font-bold outline-none focus:border-amber-400"
                  />
                  <button type="submit" className="px-8 py-4 bg-white/10 text-white rounded-2xl font-black">ตกลง</button>
                </form>
              </div>
            ) : (
              <form onSubmit={handleFormSubmit} className="relative group">
                <input 
                  ref={scanInputRef}
                  type="text" 
                  value={barcodeInput}
                  onChange={(e) => setBarcodeInput(e.target.value)}
                  autoFocus
                  placeholder="สแกนบาร์โค้ด..."
                  className="w-full bg-white/5 border-2 border-white/20 focus:border-amber-400 rounded-[32px] px-10 py-10 text-5xl font-black text-white outline-none transition-all placeholder:text-white/5 text-center tracking-[0.2em] shadow-inner"
                />
                <div className="absolute left-8 top-1/2 -translate-y-1/2 text-white/10">
                  <Keyboard size={32} />
                </div>
              </form>
            )}
          </div>

          <div className="h-40 flex items-center justify-center w-full">
            {lastScannedStudent ? (
              <div className={`flex items-center gap-8 px-10 py-8 rounded-[40px] shadow-2xl animate-in zoom-in duration-300 border-2 border-white/20 ${lastStatus === 'LATE' ? 'bg-amber-600' : 'bg-green-600'}`}>
                <div className="p-5 bg-white/20 rounded-2xl shadow-inner"><Check size={44} strokeWidth={4} /></div>
                <div className="text-left">
                  <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-80 mb-1">
                    {lastStatus === 'LATE' ? 'มาสาย (LATE)' : 'สแกนสำเร็จ (PRESENT)'}
                  </p>
                  <p className="text-4xl font-black font-heading leading-tight text-white">{lastScannedStudent.name}</p>
                  <p className="text-sm font-bold text-white/80 uppercase mt-1">{lastScannedStudent.level} • ห้อง {lastScannedStudent.room}</p>
                </div>
              </div>
            ) : scanError ? (
              <div className="flex items-center gap-6 bg-red-600 text-white px-10 py-8 rounded-[40px] shadow-2xl animate-in shake duration-300 border-2 border-white/20">
                <div className="p-5 bg-white/20 rounded-2xl"><ShieldAlert size={44} /></div>
                <div className="text-left font-black uppercase tracking-widest text-2xl">{scanError}</div>
              </div>
            ) : (
              <div className="flex flex-col items-center gap-4 text-slate-500 animate-pulse">
                <Sparkles size={24} className="text-amber-600" />
                <p className="text-xs font-black uppercase tracking-[0.3em]">
                  {config.scanMode === 'CAMERA' ? (isCameraActive ? 'เล็งไปที่บาร์โค้ด' : 'กดปุ่มเปิดกล้องเพื่อเริ่มสแกน') : 'ระบบพร้อมทำงาน... กรุณายิงบาร์โค้ด'}
                </p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Real-time History List */}
      <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
