                </h2>
                <p className="text-[10px] font-bold text-[#00AEEF] uppercase tracking-widest mt-1">{student.name} ({student.studentId})</p>
              </div>
            </div>
          </div>

          <div className="bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
            <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest flex items-center gap-2 mb-6">
              <Bell className="text-red-500 animate-pulse" size={18} /> แจ้งเตือนล่าสุด
            </h4>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 flex-1">
              {studentNotifications.length > 0 ? studentNotifications.map(n => (
                <div key={n.id} className="p-4 bg-slate-50 rounded-2xl border border-slate-100 flex items-start gap-3 hover:bg-white transition-all group/notif">
                  <div className={`p-2 rounded-xl shrink-0 ${n.type === 'ABSENT' ? 'bg-red-100 text-red-600' : 'bg-blue-100 text-blue-600'}`}>
                    <Info size={14} />
                  </div>
                  <div>
                    <p className="text-xs font-black text-slate-900 leading-tight group-hover/notif:text-[#00AEEF] transition-colors">{n.title}</p>
                    <p className="text-[10px] text-slate-500 font-bold mt-1 line-clamp-1">{n.message}</p>
                    <p className="text-[9px] text-slate-400 font-bold mt-1">{n.date}</p>
                  </div>
                </div>
              )) : (
                <div className="col-span-full flex flex-col items-center justify-center py-6 opacity-20">
                  <MessageSquare size={32} />
                  <p className="text-[9px] font-black uppercase tracking-widest mt-2">ไม่มีแจ้งเตือนใหม่</p>
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <StatCard 
