import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Student, AttendanceRecord, SystemConfig } from '../types';
import { 
  Scan, Loader2, Check, X, ShieldAlert, Sparkles, 
  History, Clock, Camera, Keyboard, AlertCircle
} from 'lucide-react';

interface QuickScanProps {
  students: Student[];
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
}

const QuickScan: React.FC<QuickScanProps> = ({ students, attendanceRecords, setAttendanceRecords }) => {
  const [barcodeInput, setBarcodeInput] = useState('');
  const [lastScannedStudent, setLastScannedStudent] = useState<Student | null>(null);
  const [scanError, setScanError] = useState<string | null>(null);
  const [lastStatus, setLastStatus] = useState<'PRESENT' | 'LATE' | null>(null);
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [isCameraLoading, setIsCameraLoading] = useState(false);

  const scanInputRef = useRef<HTMLInputElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const config: SystemConfig = useMemo(() => {
    const saved = localStorage.getItem('cms_system_config');
    return saved ? JSON.parse(saved) : { morningTimeLimit: '08:00', scanMode: 'BARCODE_SCANNER' };
  }, []);

  useEffect(() => {
    if (config.scanMode === 'BARCODE_SCANNER' && !isCameraActive) {
      const interval = setInterval(() => {
        if (document.activeElement !== scanInputRef.current) {
          scanInputRef.current?.focus();
        }
      }, 1000);
      return () => clearInterval(interval);
    }
  }, [config.scanMode, isCameraActive]);

  useEffect(() => {
    if (isCameraActive) {
      startCamera();
    } else {
      stopCamera();
    }
    return () => stopCamera();
  }, [isCameraActive]);

  const startCamera = async () => {
    setCameraError(null);
    setIsCameraLoading(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { 
          facingMode: 'environment',
          width: { ideal: 1280 },
          height: { ideal: 720 }
        } 
      });

      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        streamRef.current = stream;

        videoRef.current.onloadedmetadata = () => {
          videoRef.current?.play().catch(console.error);
          setIsCameraLoading(false);
        };
      }
    } catch (err: any) {
      console.error("Camera error:", err);
      let errorMsg = "ไม่สามารถเข้าถึงกล้องได้";
      if (err.name === 'NotAllowedError') errorMsg = "โปรดอนุญาตสิทธิ์การเข้าถึงกล้องในเบราว์เซอร์";
      if (err.name === 'NotFoundError') errorMsg = "ไม่พบอุปกรณ์กล้องในเครื่องนี้";

      setCameraError(errorMsg);
      setIsCameraActive(false);
      setIsCameraLoading(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setIsCameraLoading(false);
  };

  const todayDate = new Date().toISOString().split('T')[0];

  const todayScans = useMemo(() => {
    return attendanceRecords
      .filter(r => r.date === todayDate && r.type === 'MORNING')
      .sort((a, b) => b.timestamp.localeCompare(a.timestamp));
  }, [attendanceRecords, todayDate]);

  const handleScanLogic = (input: string) => {
    // Sanitizing input to ensure it handles pure numeric strings from scanners
    const cleanInput = input.trim();
    if (!cleanInput) return;

    setScanError(null);
    // Support both internal ID and Student Display ID (studentId)
    const student = students.find(s => String(s.studentId) === cleanInput || String(s.id) === cleanInput);

    if (student) {
      const now = new Date();
      const timestamp = now.toLocaleString('th-TH');
      const [limitHour, limitMin] = config.morningTimeLimit.split(':').map(Number);
      const limitTime = new Date();
      limitTime.setHours(limitHour, limitMin, 0);

      const status = now > limitTime ? 'LATE' : 'PRESENT';
      setLastStatus(status as any);

      const newRecord: AttendanceRecord = {
        id: `MORNING_${todayDate}_${student.id}`,
        studentId: student.id,
        date: todayDate,
        type: 'MORNING',
        status: status as any,
        timestamp: timestamp
      };

      setAttendanceRecords(prev => {
        const filtered = prev.filter(r => !(r.studentId === student.id && r.date === todayDate && r.type === 'MORNING'));
        return [newRecord, ...filtered];
      });

      setLastScannedStudent(student);

      try {
        const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2571/2571-preview.mp3');
        audio.play();
      } catch (err) {}

      setTimeout(() => setLastScannedStudent(null), 3000);
    } else {
      setScanError(`ไม่พบรหัส: ${cleanInput}`);
      setTimeout(() => setScanError(null), 3000);
    }
    setBarcodeInput('');
  };

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    handleScanLogic(barcodeInput);
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-slate-950 p-10 md:p-14 rounded-[48px] shadow-2xl relative overflow-hidden border-4 border-amber-500">
        <div className="absolute inset-0 pointer-events-none opacity-10">
          <div className="w-full h-1 bg-amber-500 absolute animate-[scan-line_3s_linear_infinite]" />
        </div>

        <div className="flex flex-col items-center text-center space-y-10 relative z-10">
          <div className="space-y-3">
            <div className="flex items-center justify-center gap-4 text-amber-500">
              {config.scanMode === 'CAMERA' ? <Camera size={44} /> : <Scan size={44} className="animate-pulse" />}
              <h2 className="text-4xl font-black text-white font-heading uppercase tracking-tighter">
                {config.scanMode === 'CAMERA' ? 'Camera Scanner' : 'Barcode Terminal'}
              </h2>
            </div>
            <div className="flex items-center justify-center gap-2">
               <span className="px-3 py-1 bg-white/10 rounded-full text-[10px] font-black text-slate-400 uppercase tracking-widest border border-white/5">
                 สายหลัง: {config.morningTimeLimit} น.
               </span>
               <span className="px-3 py-1 bg-blue-500/10 rounded-full text-[10px] font-black text-blue-400 uppercase tracking-widest border border-blue-500/20">
                 โหมด: {config.scanMode === 'CAMERA' ? 'กล้อง' : 'เครื่องยิง'}
               </span>
            </div>
          </div>

          <div className="w-full max-w-xl space-y-6">
            {config.scanMode === 'CAMERA' ? (
              <div className="space-y-6">
                {cameraError && (
                  <div className="bg-red-500/20 border border-red-500/50 p-4 rounded-2xl flex items-center gap-3 text-red-400 text-sm mb-4">
                    <AlertCircle size={20} />
                    <span className="font-bold">{cameraError}</span>
                  </div>
                )}

                {!isCameraActive ? (
                  <button 
                    onClick={() => setIsCameraActive(true)}
                    className="w-full bg-amber-500 text-slate-950 hover:bg-amber-400 py-10 rounded-[32px] flex flex-col items-center justify-center gap-4 transition-all shadow-2xl active:scale-95 group"
                  >
                    <div className="p-4 bg-slate-900/10 rounded-2xl group-hover:scale-110 transition-transform">
                      <Camera size={48} />
                    </div>
                    <span className="text-2xl font-black uppercase tracking-widest font-heading">เปิดกล้องสแกนบาร์โค้ด</span>
                  </button>
                ) : (
                  <div className="relative w-full aspect-video bg-black rounded-[32px] border-4 border-white/10 overflow-hidden shadow-2xl">
                    {isCameraLoading && (
                      <div className="absolute inset-0 flex flex-col items-center justify-center text-white/40 bg-slate-900/80 z-20">
                         <Loader2 className="animate-spin mb-4" size={48} />
                         <p className="text-xs font-black uppercase tracking-widest">กำลังเชื่อมต่อกล้อง...</p>
                      </div>
                    )}
                    <video 
                      ref={videoRef}
                      autoPlay 
                      playsInline 
                      muted
                      className="w-full h-full object-cover"
                    />
                    <div className="absolute inset-0 border-[40px] md:border-[60px] border-black/40 pointer-events-none"></div>
                    <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-32 border-2 border-amber-400/80 rounded-lg shadow-[0_0_30px_rgba(251,191,36,0.3)]">
                      <div className="w-full h-0.5 bg-amber-400 absolute top-1/2 -translate-y-1/2 animate-[pulse_1s_infinite]" />
                    </div>

                    <button 
                      onClick={() => setIsCameraActive(false)}
                      className="absolute bottom-6 right-6 p-4 bg-red-600 text-white rounded-2xl hover:bg-red-700 transition-all shadow-xl active:scale-90 z-30"
                    >
                      <X size={24} />
                    </button>

                    <div className="absolute bottom-6 left-1/2 -translate-x-1/2 bg-black/60 backdrop-blur-md px-4 py-2 rounded-full border border-white/10 z-30">
                       <p className="text-[10px] font-black text-amber-400 uppercase tracking-widest">เล็งบาร์โค้ดให้อยู่ในกรอบ</p>
                    </div>
                  </div>
                )}

                <form onSubmit={handleFormSubmit} className="flex gap-2">
                  <input 
                    type="text"
                    value={barcodeInput}
                    onChange={(e) => setBarcodeInput(e.target.value)}
                    placeholder="ป้อนรหัส หรือ รอสแกน..."
                    className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white font-bold outline-none focus:border-amber-400"
                  />
                  <button type="submit" className="px-8 py-4 bg-white/10 text-white rounded-2xl font-black">ตกลง</button>
                </form>
              </div>
            ) : (
              <form onSubmit={handleFormSubmit} className="relative group">
                <input 
                  ref={scanInputRef}
                  type="text" 
                  value={barcodeInput}
                  onChange={(e) => setBarcodeInput(e.target.value)}
                  autoFocus
                  placeholder="สแกนบาร์โค้ด..."
                  className="w-full bg-white/5 border-2 border-white/20 focus:border-amber-400 rounded-[32px] px-10 py-10 text-5xl font-black text-white outline-none transition-all placeholder:text-white/5 text-center tracking-[0.2em] shadow-inner"
                />
                <div className="absolute left-8 top-1/2 -translate-y-1/2 text-white/10">
                  <Keyboard size={32} />
                </div>
              </form>
            )}
          </div>

          <div className="h-40 flex items-center justify-center w-full">
            {lastScannedStudent ? (
              <div className={`flex items-center gap-8 px-10 py-8 rounded-[40px] shadow-2xl animate-in zoom-in duration-300 border-2 border-white/20 ${lastStatus === 'LATE' ? 'bg-amber-600' : 'bg-green-600'}`}>
                <div className="p-5 bg-white/20 rounded-2xl shadow-inner"><Check size={44} strokeWidth={4} /></div>
                <div className="text-left">
                  <p className="text-[10px] font-black uppercase tracking-[0.2em] opacity-80 mb-1">
                    {lastStatus === 'LATE' ? 'มาสาย (LATE)' : 'สแกนสำเร็จ (PRESENT)'}
                  </p>
                  <p className="text-4xl font-black font-heading leading-tight text-white">{lastScannedStudent.name}</p>
                  <p className="text-sm font-bold text-white/80 uppercase mt-1">{lastScannedStudent.level} • ห้อง {lastScannedStudent.room}</p>
                </div>
              </div>
            ) : scanError ? (
              <div className="flex items-center gap-6 bg-red-600 text-white px-10 py-8 rounded-[40px] shadow-2xl animate-in shake duration-300 border-2 border-white/20">
                <div className="p-5 bg-white/20 rounded-2xl"><ShieldAlert size={44} /></div>
                <div className="text-left font-black uppercase tracking-widest text-2xl">{scanError}</div>
              </div>
            ) : (
              <div className="flex flex-col items-center gap-4 text-slate-500 animate-pulse">
                <Sparkles size={24} className="text-amber-600" />
                <p className="text-xs font-black uppercase tracking-[0.3em]">
                  {config.scanMode === 'CAMERA' ? (isCameraActive ? 'เล็งไปที่บาร์โค้ด' : 'กดปุ่มเปิดกล้องเพื่อเริ่มสแกน') : 'ระบบพร้อมทำงาน... กรุณายิงบาร์โค้ด'}
                </p>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-8 bg-slate-50/50 border-b flex items-center justify-between">
          <h3 className="text-lg font-black text-slate-900 font-heading flex items-center gap-3">
            <History className="text-blue-600" size={22} /> รายการสแกนล่าสุด ({todayScans.length})
          </h3>
          <div className="flex gap-4">
             <div className="flex items-center gap-2">
                <div className="w-3 h-3 bg-green-500 rounded-full" />
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">มาเรียน</span>
             </div>
             <div className="flex items-center gap-2">
                <div className="w-3 h-3 bg-amber-500 rounded-full" />
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">มาสาย</span>
             </div>
          </div>
        </div>
        <div className="overflow-y-auto max-h-[600px] scrollbar-hide">
          <table className="w-full text-left">
            <thead className="bg-white sticky top-0 border-b text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <tr>
                <th className="px-10 py-4">เวลา</th>
                <th className="px-10 py-4">นักเรียน</th>
                <th className="px-10 py-4">ห้องเรียน</th>
                <th className="px-10 py-4 text-right">สถานะ</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {todayScans.map((r) => {
                const student = students.find(s => s.id === r.studentId);
                return (
                  <tr key={r.id} className="hover:bg-slate-50/50 transition-colors animate-in slide-in-from-left duration-300">
                    <td className="px-10 py-6">
                      <div className="flex items-center gap-2 text-slate-400 font-black text-sm">
                        <Clock size={14} /> {r.timestamp.split(' ')[1]}
                      </div>
                    </td>
                    <td className="px-10 py-6">
                      <p className="font-black text-slate-900">{student?.name}</p>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">{student?.studentId}</p>
                    </td>
                    <td className="px-10 py-6">
                      <span className="text-xs font-bold text-slate-600">{student?.level} / {student?.room}</span>
                    </td>
                    <td className="px-10 py-6 text-right">
                      <span className={`px-4 py-1.5 rounded-xl text-[9px] font-black uppercase border ${r.status === 'LATE' ? 'bg-amber-50 text-amber-700 border-amber-100' : 'bg-green-50 text-green-700 border-green-100'}`}>
                        {r.status === 'LATE' ? 'มาสาย ⏰' : 'มาเรียน ✓'}
                      </span>
                    </td>
                  </tr>
                );
              })}
              {todayScans.length === 0 && (
                <tr>
                  <td colSpan={4} className="py-24 text-center">
                    <Scan size={48} className="mx-auto text-slate-100 mb-4" />
                    <p className="text-slate-300 font-black uppercase tracking-widest text-xs">ยังไม่มีประวัติการสแกนในวันนี้</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <style dangerouslySetInnerHTML={{ __html: `
        @keyframes scan-line {
          0% { top: 0%; }
          100% { top: 100%; }
        }
        @keyframes shake {
          0%, 100% { transform: translateX(0); }
          25% { transform: translateX(-5px); }
          75% { transform: translateX(5px); }
        }
        .shake { animation: shake 0.3s ease-in-out; }
        .scrollbar-hide::-webkit-scrollbar {
          display: none;
        }
        .scrollbar-hide {
          -ms-overflow-style: none;
          scrollbar-width: none;
        }
      `}} />
    </div>
  );
};

export default QuickScan;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Student, AttendanceRecord, SystemConfig } from '../types';
import { 
  Scan, Loader2, Check, X, ShieldAlert, Sparkles, 
  History, Clock, Camera, Keyboard, AlertCircle, RefreshCw
} from 'lucide-react';

// Declare html5-qrcode global
declare const Html5Qrcode: any;

interface QuickScanProps {
  students: Student[];
  attendanceRecords: AttendanceRecord[];
  setAttendanceRecords: React.Dispatch<React.SetStateAction<AttendanceRecord[]>>;
}

const QuickScan: React.FC<QuickScanProps> = ({ students, attendanceRecords, setAttendanceRecords }) => {
  const [barcodeInput, setBarcodeInput] = useState('');
  const [lastScannedStudent, setLastScannedStudent] = useState<Student | null>(null);
  const [scanError, setScanError] = useState<string | null>(null);
  const [lastStatus, setLastStatus] = useState<'PRESENT' | 'LATE' | null>(null);
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [cameraError, setCameraError] = useState<string | null>(null);

  const scanInputRef = useRef<HTMLInputElement>(null);
  const scannerRef = useRef<any>(null);

  const config: SystemConfig = useMemo(() => {
    const saved = localStorage.getItem('cms_system_config');
    return saved ? JSON.parse(saved) : { morningTimeLimit: '08:00', scanMode: 'BARCODE_SCANNER' };
  }, []);

  // Handle Hardware Scanner Focus
  useEffect(() => {
    if (config.scanMode === 'BARCODE_SCANNER' && !isCameraActive) {
      const interval = setInterval(() => {
        if (document.activeElement !== scanInputRef.current) {
          scanInputRef.current?.focus();
        }
      }, 500);
      return () => clearInterval(interval);
    }
  }, [config.scanMode, isCameraActive]);

  // Handle Camera Scanner Lifecycle
  useEffect(() => {
    if (isCameraActive) {
      startCamera();
    } else {
      stopCamera();
    }
    return () => stopCamera();
  }, [isCameraActive]);

  const startCamera = async () => {
    setCameraError(null);
    try {
      // Small delay to ensure DOM element exists
      setTimeout(() => {
        const html5QrCode = new Html5Qrcode("reader");
        scannerRef.current = html5QrCode;

        const qrCodeSuccessCallback = (decodedText: string) => {
          handleScanLogic(decodedText);
          // Briefly stop to show success then resume if needed, 
          // but handleScanLogic clears current anyway.
        };

        const config = { 
          fps: 15, 
          qrbox: { width: 300, height: 150 },
          aspectRatio: 1.777778 // 16:9
        };

        html5QrCode.start(
          { facingMode: "environment" }, 
          config, 
          qrCodeSuccessCallback,
          undefined // Error callback ignored for noise
        ).catch((err: any) => {
          setCameraError("ไม่สามารถเข้าถึงกล้องได้: " + err);
          setIsCameraActive(false);
        });
      }, 500);
    } catch (err: any) {
      setCameraError("เกิดข้อผิดพลาดในการเปิดกล้อง");
      setIsCameraActive(false);
    }
  };

  const stopCamera = async () => {
    if (scannerRef.current && scannerRef.current.isScanning) {
      try {
        await scannerRef.current.stop();
        scannerRef.current = null;
      } catch (err) {
        console.error("Failed to stop scanner", err);
      }
    }
  };

  const todayDate = new Date().toISOString().split('T')[0];

  const todayScans = useMemo(() => {
    return attendanceRecords
      .filter(r => r.date === todayDate && r.type === 'MORNING')
      .sort((a, b) => b.timestamp.localeCompare(a.timestamp));
  }, [attendanceRecords, todayDate]);

  const handleScanLogic = (input: string) => {
    // Crucial: Clear spaces and control characters (often sent by hardware scanners)
    const cleanInput = input.trim().replace(/[\u0000-\u001F\u007F-\u009F]/g, "");
    if (!cleanInput) return;

    setScanError(null);

    // Search by studentId (display id) or system id
    const student = students.find(s => 
      String(s.studentId) === cleanInput || 
      String(s.id) === cleanInput
    );

    if (student) {
      const now = new Date();
      const timestamp = now.toLocaleString('th-TH');
      const [limitHour, limitMin] = config.morningTimeLimit.split(':').map(Number);
      const limitTime = new Date();
      limitTime.setHours(limitHour, limitMin, 0);

      const status = now > limitTime ? 'LATE' : 'PRESENT';
      setLastStatus(status as any);

      const newRecord: AttendanceRecord = {
        id: `MORNING_${todayDate}_${student.id}`,
        studentId: student.id,
        date: todayDate,
        type: 'MORNING',
        status: status as any,
        timestamp: timestamp
      };

      setAttendanceRecords(prev => {
        // Remove existing today morning record if any, then add new one
        const filtered = prev.filter(r => !(r.studentId === student.id && r.date === todayDate && r.type === 'MORNING'));
        return [newRecord, ...filtered];
      });

      setLastScannedStudent(student);

      // Feedback Sound
      try {
        const audio = new Audio('https://assets.mixkit.co/active_storage/sfx/2571/2571-preview.mp3');
        audio.play();
      } catch (err) {}

      // Reset success message
      setTimeout(() => setLastScannedStudent(null), 3000);
    } else {
      setScanError(`ไม่พบรหัส: ${cleanInput}`);
      // Show error briefly
      setTimeout(() => setScanError(null), 3000);
    }
    setBarcodeInput('');
  };

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    handleScanLogic(barcodeInput);
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-slate-950 p-10 md:p-14 rounded-[48px] shadow-2xl relative overflow-hidden border-4 border-amber-500">
        <div className="absolute inset-0 pointer-events-none opacity-5">
          <div className="w-full h-1 bg-amber-500 absolute animate-[scan-line_4s_linear_infinite]" />
        </div>

        <div className="flex flex-col items-center text-center space-y-10 relative z-10">
          <div className="space-y-3">
            <div className="flex items-center justify-center gap-4 text-amber-500">
              {config.scanMode === 'CAMERA' ? <Camera size={44} /> : <Scan size={44} className="animate-pulse" />}
              <h2 className="text-4xl font-black text-white font-heading uppercase tracking-tighter">
                {config.scanMode === 'CAMERA' ? 'Camera Live Scanner' : 'Barcode Terminal'}
              </h2>
            </div>
            <div className="flex items-center justify-center gap-2">
               <span className="px-3 py-1 bg-white/10 rounded-full text-[10px] font-black text-slate-400 uppercase tracking-widest border border-white/5">
                 เวลาจำกัด: {config.morningTimeLimit} น.
               </span>
               <span className="px-3 py-1 bg-blue-500/10 rounded-full text-[10px] font-black text-blue-400 uppercase tracking-widest border border-blue-500/20">
                 โหมด: {config.scanMode === 'CAMERA' ? 'กล้องมือถือ' : 'เครื่องยิง USB/BT'}
               </span>
            </div>
          </div>

          <div className="w-full max-w-xl space-y-6">
            {config.scanMode === 'CAMERA' ? (
              <div className="space-y-6">
                {cameraError && (
                  <div className="bg-red-500/20 border border-red-500/50 p-4 rounded-2xl flex items-center gap-3 text-red-400 text-sm mb-4">
                    <AlertCircle size={20} />
                    <span className="font-bold">{cameraError}</span>
                  </div>
                )}

                {!isCameraActive ? (
                  <button 
                    onClick={() => setIsCameraActive(true)}
                    className="w-full bg-amber-500 text-slate-950 hover:bg-amber-400 py-12 rounded-[32px] flex flex-col items-center justify-center gap-4 transition-all shadow-2xl active:scale-95 group"
                  >
                    <div className="p-4 bg-slate-900/10 rounded-2xl group-hover:scale-110 transition-transform">
                      <Camera size={48} />
                    </div>
                    <span className="text-2xl font-black uppercase tracking-widest font-heading">เปิดกล้องสแกน</span>
                    <p className="text-[10px] font-black opacity-60">ระบบรองรับบาร์โค้ดแนวตั้งและแนวนอน</p>
                  </button>
                ) : (
                  <div className="space-y-4">
                    <div id="reader" className="w-full aspect-video bg-black rounded-[32px] border-4 border-white/10 overflow-hidden shadow-2xl relative">
                        {/* Status Overlay */}
                        <div className="absolute top-4 left-1/2 -translate-x-1/2 bg-black/60 px-4 py-2 rounded-full border border-white/20 z-10">
                            <p className="text-[9px] font-black text-amber-400 uppercase tracking-widest flex items-center gap-2">
                                <RefreshCw size={10} className="animate-spin" /> กำลังประมวลผลวิดีโอ...
                            </p>
                        </div>
                    </div>

                    <button 
                      onClick={() => setIsCameraActive(false)}
                      className="w-full py-4 bg-red-600 text-white rounded-2xl font-black uppercase tracking-widest text-xs hover:bg-red-700 transition-all flex items-center justify-center gap-2"
                    >
                      <X size={18} /> ปิดกล้องสแกน
                    </button>
                  </div>
                )}

                <form onSubmit={handleFormSubmit} className="flex gap-2">
                  <input 
                    type="text"
                    value={barcodeInput}
                    onChange={(e) => setBarcodeInput(e.target.value)}
                    placeholder="พิมพ์รหัสนักเรียน (ถ้ากล้องไม่ทำงาน)..."
                    className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white font-bold outline-none focus:border-amber-400 text-center"
                  />
                  <button type="submit" className="px-8 py-4 bg-white/10 text-white rounded-2xl font-black hover:bg-white/20">ตกลง</button>
                </form>
              </div>
            ) : (
              <div className="space-y-4">
                <form onSubmit={handleFormSubmit} className="relative group">
                    <input 
                    ref={scanInputRef}
                    type="text" 
                    value={barcodeInput}
                    onChange={(e) => setBarcodeInput(e.target.value)}
                    autoFocus
                    placeholder="รอรับข้อมูล..."
                    className="w-full bg-white/5 border-2 border-white/20 focus:border-amber-400 rounded-[32px] px-10 py-12 text-5xl font-black text-white outline-none transition-all placeholder:text-white/5 text-center tracking-[0.2em] shadow-inner"
                    />
                    <div className="absolute left-8 top-1/2 -translate-y-1/2 text-white/10">
                    <Keyboard size={32} />
                    </div>
                </form>
                <div className="flex justify-center gap-4">
                    <div className="flex items-center gap-2 text-slate-500 text-[10px] font-black uppercase tracking-widest">
                        <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
                        เชื่อมต่อแล้ว
                    </div>
                    <div className="text-slate-500 text-[10px] font-black uppercase tracking-widest">
                        รอยิงบาร์โค้ด...
