import React, { useState, useMemo } from 'react';
import { NewsRecord, Student, Department, ThaiLevel } from '../types';
import { 
  Megaphone, Plus, Search, X, Send, Users, User, Layout, 
  AlertCircle, Calendar, Trash2, Edit3, Loader2, Sparkles, Check,
  Building, GraduationCap, ArrowRight
} from 'lucide-react';

interface NewsBroadcastProps {
  students: Student[];
  news: NewsRecord[];
  setNews: React.Dispatch<React.SetStateAction<NewsRecord[]>>;
  currentUser: any;
}

const NewsBroadcast: React.FC<NewsBroadcastProps> = ({ students, news, setNews, currentUser }) => {
  const [showModal, setShowModal] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSending, setIsSending] = useState(false);

  const [formData, setFormData] = useState<Partial<NewsRecord>>({
    title: '',
    content: '',
    type: 'INFO',
    targetType: 'ALL',
    targetDept: '',
    targetLevel: 'ปวช. 1',
    targetRoom: '1',
    targetStudentId: ''
  });

  const availableDepts = useMemo(() => Array.from(new Set(students.map(s => s.department))).map(String).sort(), [students]);
  const availableLevels = useMemo(() => Array.from(new Set(students.map(s => s.level))).map(String).sort(), [students]);
  const availableRooms = useMemo(() => Array.from(new Set(students.map(s => s.room))).map(String).sort((a,b) => parseInt(a)-parseInt(b)), [students]);

  // Initial form values for dropdowns
  useMemo(() => {
    if (availableDepts.length > 0 && !formData.targetDept) {
      setFormData(prev => ({ ...prev, targetDept: availableDepts[0] }));
    }
  }, [availableDepts]);

  const filteredNews = useMemo(() => {
    return news
      .filter(n => n.title.toLowerCase().includes(searchTerm.toLowerCase()) || n.content.toLowerCase().includes(searchTerm.toLowerCase()))
      .sort((a, b) => b.timestamp.localeCompare(a.timestamp));
  }, [news, searchTerm]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.title || !formData.content) return;

    setIsSending(true);
    await new Promise(resolve => setTimeout(resolve, 800));

    const newRecord: NewsRecord = {
      id: `NEWS_${Date.now()}`,
      title: formData.title!,
      content: formData.content!,
      type: formData.type as any,
      targetType: formData.targetType as any,
      targetDept: formData.targetType === 'DEPT' ? formData.targetDept : undefined,
      targetLevel: formData.targetType === 'ROOM' ? formData.targetLevel : undefined,
      targetRoom: formData.targetType === 'ROOM' ? formData.targetRoom : undefined,
      targetStudentId: formData.targetType === 'INDIVIDUAL' ? formData.targetStudentId : undefined,
      authorName: currentUser.name,
      date: new Date().toLocaleDateString('th-TH'),
      timestamp: new Date().toISOString()
    };

    setNews(prev => [newRecord, ...prev]);
    setIsSending(false);
    setShowModal(false);
    setFormData({ 
      title: '', 
      content: '', 
      type: 'INFO', 
      targetType: 'ALL',
      targetDept: availableDepts[0] || '',
      targetLevel: availableLevels[0] || 'ปวช. 1',
      targetRoom: availableRooms[0] || '1',
      targetStudentId: ''
    });
  };

  const deleteNews = (id: string) => {
    if (confirm('ยืนยันการลบข่าวสารนี้?')) {
      setNews(prev => prev.filter(n => n.id !== id));
    }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div>
          <h2 className="text-3xl font-black text-slate-900 font-heading flex items-center gap-4">
            <div className="p-3 bg-blue-600 text-white rounded-2xl shadow-xl shadow-blue-100"><Megaphone size={32} /></div>
            ประชาสัมพันธ์ข่าวสาร
          </h2>
          <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px] mt-2 ml-1">วิทยาลัยเทคโนโลยีอาชีวศึกษา Portal</p>
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="w-full md:w-auto px-10 py-5 bg-slate-900 text-white rounded-2xl font-black flex items-center justify-center gap-3 shadow-2xl hover:bg-black transition-all active:scale-95 font-heading text-sm uppercase tracking-widest"
        >
          <Plus size={20} /> เขียนประกาศใหม่
        </button>
      </div>

      <div className="bg-white p-4 rounded-[32px] border border-slate-200 shadow-sm flex items-center gap-4">
        <Search className="text-slate-300 ml-4" size={24} />
        <input 
          type="text" 
          placeholder="ค้นหาข่าวสาร/ประกาศ..." 
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="flex-1 py-4 bg-transparent font-bold text-slate-900 outline-none text-lg"
        />
      </div>

      <div className="grid grid-cols-1 gap-6">
        {filteredNews.map(item => (
          <div key={item.id} className="bg-white p-8 rounded-[40px] border border-slate-200 shadow-sm hover:shadow-md transition-all group relative overflow-hidden">
            <div className={`absolute top-0 right-0 w-2 h-full ${item.type === 'URGENT' ? 'bg-red-500' : item.type === 'EVENT' ? 'bg-amber-500' : 'bg-blue-500'}`} />

            <div className="flex flex-col md:flex-row justify-between items-start gap-6">
              <div className="space-y-4 flex-1">
                <div className="flex flex-wrap items-center gap-3">
                  <span className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest border ${
                    item.type === 'URGENT' ? 'bg-red-50 text-red-600 border-red-100' : 
                    item.type === 'EVENT' ? 'bg-amber-50 text-amber-600 border-amber-100' : 
                    'bg-blue-50 text-blue-600 border-blue-100'
                  }`}>
                    {item.type === 'URGENT' ? 'ด่วนที่สุด' : item.type === 'EVENT' ? 'กิจกรรม' : 'ข่าวประชาสัมพันธ์'}
                  </span>
                  <span className="px-4 py-1.5 bg-slate-100 text-slate-500 rounded-full text-[10px] font-black uppercase tracking-widest border border-slate-200 flex items-center gap-2">
                    {item.targetType === 'ALL' ? <Users size={12} /> : 
                     item.targetType === 'DEPT' ? <Building size={12} /> : 
                     item.targetType === 'ROOM' ? <Layout size={12} /> : <User size={12} />}
                    ส่งถึง: {
                      item.targetType === 'ALL' ? 'ทุกคนในวิทยาลัย' : 
                      item.targetType === 'DEPT' ? `แผนก ${item.targetDept}` : 
                      item.targetType === 'ROOM' ? `${item.targetLevel} / ${item.targetRoom}` : 
                      `นักเรียนรหัส: ${item.targetStudentId}`
                    }
                  </span>
                </div>

                <h3 className="text-2xl font-black text-slate-900 font-heading leading-tight">{item.title}</h3>
                <p className="text-slate-600 font-medium leading-relaxed whitespace-pre-wrap">{item.content}</p>

                <div className="flex items-center gap-6 pt-4 border-t border-slate-50">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-slate-900 rounded-lg flex items-center justify-center text-white font-black text-[10px]">{item.authorName.charAt(0)}</div>
                    <p className="text-xs font-black text-slate-900 uppercase">โดย: {item.authorName}</p>
                  </div>
                  <div className="flex items-center gap-2 text-slate-400 font-bold text-xs uppercase">
                    <Calendar size={14} /> {item.date}
                  </div>
                </div>
              </div>

              <div className="flex gap-2">
                 <button onClick={() => deleteNews(item.id)} className="p-3 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-2xl transition-all"><Trash2 size={22} /></button>
              </div>
            </div>
          </div>
        ))}

        {filteredNews.length === 0 && (
          <div className="py-32 text-center bg-white rounded-[48px] border-4 border-dashed border-slate-100">
            <Megaphone size={64} className="mx-auto text-slate-100 mb-6" />
            <p className="text-slate-300 font-black uppercase tracking-[0.3em] text-sm">ไม่มีข่าวประชาสัมพันธ์ในขณะนี้</p>
          </div>
        )}
      </div>

      {/* Broadcast Modal */}
      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-slate-900/80 backdrop-blur-md">
          <div className="bg-white w-full max-w-2xl rounded-[48px] p-8 md:p-14 shadow-2xl animate-in zoom-in-95 duration-300 relative overflow-y-auto max-h-[90vh]">
            <button onClick={() => setShowModal(false)} className="absolute top-10 right-10 text-slate-400 hover:text-slate-900 transition-colors"><X size={28} /></button>

            <h3 className="text-2xl font-black text-slate-900 mb-10 font-heading flex items-center gap-4">
              <Megaphone className="text-blue-600" /> เขียนประกาศใหม่
            </h3>

            <form onSubmit={handleSubmit} className="space-y-8">
              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 font-heading">เลือกระดับกลุ่มเป้าหมาย</label>
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                   {[
                     { id: 'ALL', label: 'ทั้งวิทยาลัย', icon: <Users size={16} /> },
                     { id: 'DEPT', label: 'แยกแผนก', icon: <Building size={16} /> },
                     { id: 'ROOM', label: 'สาขา/ห้อง', icon: <Layout size={16} /> },
                     { id: 'INDIVIDUAL', label: 'รายบุคคล', icon: <User size={16} /> },
                   ].map(target => (
                     <button
                        key={target.id}
                        type="button"
                        onClick={() => setFormData({...formData, targetType: target.id as any})}
                        className={`flex flex-col items-center justify-center gap-2 p-4 rounded-2xl border-2 transition-all font-black text-[10px] uppercase tracking-tighter ${
                          formData.targetType === target.id 
                          ? 'bg-blue-600 border-blue-600 text-white shadow-lg' 
                          : 'bg-slate-50 border-slate-100 text-slate-500 hover:border-blue-300'
                        }`}
                     >
                       {target.icon}
                       {target.label}
                     </button>
                   ))}
                </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 font-heading">ประเภทประกาศ</label>
                  <select 
                    value={formData.type} 
                    onChange={(e) => setFormData({...formData, type: e.target.value as any})}
                    className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-5 py-4 font-black outline-none"
                  >
                    <option value="INFO">ข่าวทั่วไป (Information)</option>
                    <option value="URGENT">ด่วนที่สุด (Urgent)</option>
                    <option value="EVENT">กิจกรรม (Event)</option>
                  </select>
                </div>

                {formData.targetType === 'DEPT' && (
                  <div className="space-y-2 animate-in slide-in-from-top-4">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 font-heading">เลือกแผนกวิชา</label>
                    <select 
                      value={formData.targetDept} 
                      onChange={(e) => setFormData({...formData, targetDept: e.target.value})}
                      className="w-full bg-blue-50 border-2 border-blue-100 rounded-2xl px-5 py-4 font-black outline-none"
                    >
                      {availableDepts.map(d => <option key={d} value={d}>{d}</option>)}
                    </select>
                  </div>
                )}

                {formData.targetType === 'ALL' && (
                  <div className="space-y-2 flex items-end">
                    <div className="w-full bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl px-5 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">
                      ส่งถึงทุกคนในระบบ
                    </div>
                  </div>
                )}
              </div>

              {formData.targetType === 'ROOM' && (
                <div className="grid grid-cols-2 gap-6 animate-in slide-in-from-top-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">ระดับชั้น</label>
                    <select value={formData.targetLevel} onChange={(e) => setFormData({...formData, targetLevel: e.target.value})} className="w-full bg-blue-50 border-2 border-blue-100 rounded-2xl px-5 py-4 font-bold outline-none">
                      {availableLevels.map(v => <option key={v} value={v}>{v}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">ห้อง</label>
                    <select value={formData.targetRoom} onChange={(e) => setFormData({...formData, targetRoom: e.target.value})} className="w-full bg-blue-50 border-2 border-blue-100 rounded-2xl px-5 py-4 font-bold outline-none">
                      {availableRooms.map(v => <option key={v} value={v}>ห้อง {v}</option>)}
                    </select>
                  </div>
                </div>
              )}

              {formData.targetType === 'INDIVIDUAL' && (
                <div className="space-y-2 animate-in slide-in-from-top-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 font-heading">รหัสนักเรียน (6 หลัก)</label>
                  <div className="relative">
                    <User className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input 
                      type="text" 
                      value={formData.targetStudentId}
                      onChange={(e) => setFormData({...formData, targetStudentId: e.target.value})}
                      placeholder="ระบุรหัส เช่น 661001"
                      className="w-full bg-blue-50 border-2 border-blue-100 focus:border-blue-500 rounded-2xl px-12 py-4 font-black outline-none"
                    />
                  </div>
                </div>
              )}

              <div className="space-y-2 border-t border-slate-100 pt-8">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 font-heading">หัวข้อประกาศ</label>
                <input 
                  type="text" 
                  required
                  value={formData.title}
                  onChange={(e) => setFormData({...formData, title: e.target.value})}
                  placeholder="เช่น แจ้งกำหนดการวันไหว้ครู ปีการศึกษา 2567"
                  className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-2xl px-6 py-5 font-black text-lg outline-none"
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 font-heading">เนื้อหาประกาศ</label>
                <textarea 
                  required
                  rows={5}
                  value={formData.content}
                  onChange={(e) => setFormData({...formData, content: e.target.value})}
                  placeholder="ระบุรายละเอียดที่ต้องการแจ้งให้ผู้ปกครองและนักเรียนทราบ..."
                  className="w-full bg-slate-50 border-2 border-slate-100 focus:border-blue-500 rounded-3xl px-6 py-5 font-medium outline-none resize-none"
                />
              </div>

              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setShowModal(false)} className="flex-1 py-5 bg-slate-100 text-slate-600 rounded-[24px] font-black uppercase text-xs tracking-widest font-heading">ยกเลิก</button>
                <button 
                  type="submit" 
                  disabled={isSending}
                  className="flex-1 py-5 bg-blue-600 text-white rounded-[24px] font-black uppercase text-xs tracking-widest shadow-2xl shadow-blue-200 hover:bg-blue-700 transition-all flex items-center justify-center gap-3 font-heading"
                >
                  {isSending ? <Loader2 className="animate-spin" size={20} /> : <Send size={20} />}
                  {isSending ? 'กำลังส่งประกาศ...' : 'ส่งประกาศทันที'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default NewsBroadcast;

export type UserRole = 'ADMIN' | 'TEACHER' | 'PARENT' | 'FINANCE';

export interface User {
  id: string;
  name: string;
  role: UserRole;
  username: string;
  password: string;
  department?: string;
  studentId?: string; 
  email?: string;
}

export type AttendanceStatus = 'PRESENT' | 'LATE' | 'ABSENT' | 'BUSINESS_LEAVE' | 'SICK_LEAVE';

export enum ThaiLevel {
  VC1 = 'ปวช. 1',
  VC2 = 'ปวช. 2',
  VC3 = 'ปวช. 3',
  HVC1 = 'ปวส. 1',
  HVC2 = 'ปวส. 2'
}

export enum Department {
  IT = 'เทคโนโลยีสารสนเทศ',
  AUTO = 'ช่างยนต์',
  ELEC = 'ช่างไฟฟ้า',
  MECH = 'ช่างกลโรงงาน',
  ACCOUNT = 'การบัญชี'
}

export interface Student {
  id: string;
  studentId: string;
  name: string;
  level: string; 
  department: string; 
  room: string;
  behaviorScore: number;
}

export interface AttendanceRecord {
  id: string;
  studentId: string;
  date: string;
  type: 'MORNING' | 'SUBJECT';
  subjectId?: string;
  status: AttendanceStatus;
  remark?: string;
  timestamp: string;
}

export interface NewsRecord {
  id: string;
  title: string;
  content: string;
  type: 'INFO' | 'URGENT' | 'EVENT';
  targetType: 'ALL' | 'DEPT' | 'ROOM' | 'INDIVIDUAL';
  targetDept?: string;
  targetMajor?: string;
  targetLevel?: string;
  targetRoom?: string;
  targetStudentId?: string;
  authorName: string;
  date: string;
  timestamp: string;
}

export interface NotificationRecord {
  id: string;
  studentId: string;
  title: string;
  message: string;
  type: 'ABSENT' | 'LATE' | 'LEAVE' | 'INFO';
  date: string;
  timestamp: string;
  isRead: boolean;
}

export interface Subject {
  id: string;
  name: string;
  code: string;
  teacherId: string;
  level: string;
  department: string;
}

export interface BehaviorRecord {
  id: string;
  studentId: string;
  type: 'ADD' | 'DEDUCT';
  score: number;
  reason: string;
  date: string;
  recordedBy: string;
}

export interface TuitionConfig {
  id: string;
  level: string;
  department: string;
  amount: number;
  term: string; 
  blockId?: number;
  dueDate?: string;
}

export interface PaymentRecord {
  id: string;
  studentId: string;
  configId: string;
  amount: number;
  method: 'CASH' | 'TRANSFER';
  date: string;
  recordedBy: string;
  status: 'PAID' | 'PARTIAL' | 'PENDING';
}

export interface StudyBlock {
  id: number;
  name: string;
  startDate: string;
  endDate: string;
  isActive: boolean;
  holidays: string[];
}

export interface SystemConfig {
  morningTimeLimit: string;
  scanMode: 'BARCODE_SCANNER' | 'CAMERA';
}

import React, { useState, useMemo } from 'react';
import { 
  Users, Activity, Star, Clock, BarChart3, ShieldAlert,
  CheckCircle2, Sun, ArrowLeft, LayoutDashboard, ChevronRight, 
  Wallet, Banknote, Info, MessageSquare, Copy, Check, X,
  Bell, Sparkles, ExternalLink, Megaphone, Building
} from 'lucide-react';
import { Student, AttendanceRecord, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord, NewsRecord } from '../types';
import { 
  XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  BarChart, Bar
} from 'recharts';

interface DashboardProps {
  students: Student[];
  attendance: AttendanceRecord[];
  behavior: any[];
  news?: NewsRecord[];
  user: any;
  studyBlocks: StudyBlock[];
  tuitionConfigs?: TuitionConfig[];
  paymentRecords?: PaymentRecord[];
  notifications?: NotificationRecord[];
}

const StatCard = ({ title, value, sub, icon, color, textColor, extra }: any) => (
  <div className="bg-white p-5 md:p-7 rounded-[28px] border border-slate-200 shadow-sm flex flex-col hover:shadow-md transition-all group overflow-hidden h-full">
    <div className="flex items-start justify-between w-full mb-2">
      <div className="space-y-1.5 flex-1">
        <p className="text-slate-500 text-[9px] font-extrabold uppercase tracking-widest font-heading">{title}</p>
        <h3 className={`text-3xl md:text-4xl font-black ${textColor || 'text-slate-900'} font-heading`}>{value}</h3>
        <p className="text-[10px] text-slate-400 font-bold">{sub}</p>
      </div>
      <div className={`p-3 rounded-2xl ${color} text-white shadow-lg shrink-0`}>
        {React.isValidElement(icon) ? React.cloneElement(icon as React.ReactElement, { size: 20 }) : null}
      </div>
    </div>
    {extra && <div className="mt-4 pt-4 border-t border-slate-50">{extra}</div>}
  </div>
);

const Dashboard: React.FC<DashboardProps> = ({ 
  students = [], 
  attendance = [], 
  news = [],
  user, 
  studyBlocks = [],
  tuitionConfigs = [],
  paymentRecords = [],
  notifications = []
}) => {
  const [viewingStudentId, setViewingStudentId] = useState<string | null>(null);
  const [filterLevel, setFilterLevel] = useState<string>('ALL');
  const [filterDept, setFilterDept] = useState<string>('ALL');
  const [showBankDetails, setShowBankDetails] = useState(false);
  const [copied, setCopied] = useState(false);

  const isParent = user?.role === 'PARENT';

  const bankInfo = useMemo(() => {
    const saved = localStorage.getItem('cms_bank_info');
    return saved ? JSON.parse(saved) : {
      bankName: 'ธนาคารกรุงไทย (Krungthai)',
      accountNo: '012-3-45678-9',
      accountName: 'วิทยาลัยเทคโนโลยีอาชีวศึกษา'
    };
  }, []);

  const handleCopyAccount = () => {
    navigator.clipboard.writeText(bankInfo.accountNo);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const attendanceMap = useMemo(() => {
    const map = new Map<string, AttendanceRecord[]>();
    (attendance || []).forEach(record => {
      const sId = String(record.studentId);
      if (!map.has(sId)) map.set(sId, []);
      map.get(sId)?.push(record);
    });
    return map;
  }, [attendance]);

  const activeBlock = useMemo(() => 
    (studyBlocks || []).find(b => b.isActive) || (studyBlocks?.[0] || null)
  , [studyBlocks]);

  const getStudentStats = (studentObj: Student) => {
    const sIdStr = String(studentObj.id);
    const records = attendanceMap.get(sIdStr) || [];
    const morningRecords = records.filter(r => r.type === 'MORNING');

    let blockPresentDays = 0;
    if (activeBlock) {
      blockPresentDays = morningRecords.filter(r => 
        r.status === 'PRESENT' && r.date >= activeBlock.startDate && r.date <= activeBlock.endDate
      ).length;
    }
    const blockScore = Number(((blockPresentDays * 5) / 18).toFixed(2));
    const presentCount = morningRecords.filter(r => r.status === 'PRESENT').length;
    const attRate = morningRecords.length > 0 ? Math.round((presentCount / morningRecords.length) * 100) : 0;

    const config = (tuitionConfigs || []).find(c => c.level === studentObj.level && c.department === studentObj.department);
    const paid = (paymentRecords || []).filter(p => String(p.studentId) === sIdStr).reduce((sum, p) => sum + p.amount, 0);
    const remaining = config ? Math.max(0, config.amount - paid) : 0;

    return { blockScore, attRate, remaining, totalExpected: config?.amount || 0, paid };
  };

  const filteredStudents = useMemo(() => {
    return (students || []).filter(s => 
      (filterLevel === 'ALL' || s.level === filterLevel) &&
      (filterDept === 'ALL' || s.department === filterDept)
    );
  }, [students, filterLevel, filterDept]);

  const targetId = isParent ? user?.studentId : viewingStudentId;

  const currentViewStudent = useMemo(() => {
    if (!targetId) return null;
    const idStr = String(targetId);
    return (students || []).find(s => String(s.id) === idStr || String(s.studentId) === idStr);
  }, [students, targetId]);

  const relevantNews = useMemo(() => {
    if (!isParent || !currentViewStudent) return news.slice(0, 3);

    return news.filter(n => {
      if (n.targetType === 'ALL') return true;
      if (n.targetType === 'DEPT' && n.targetDept === currentViewStudent.department) return true;
      if (n.targetType === 'ROOM') {
        const matchDept = !n.targetMajor || n.targetMajor === currentViewStudent.department;
        const matchLevel = !n.targetLevel || n.targetLevel === currentViewStudent.level;
        const matchRoom = !n.targetRoom || n.targetRoom === currentViewStudent.room;
        return matchDept && matchLevel && matchRoom;
      }
      if (n.targetType === 'INDIVIDUAL' && n.targetStudentId === currentViewStudent.studentId) return true;
      return false;
    }).slice(0, 3);
  }, [news, isParent, currentViewStudent]);

  const handleShowStudentDetails = (id: string) => {
    setViewingStudentId(String(id));
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const behaviorWatchlist = useMemo(() => 
    filteredStudents.filter(s => s.behaviorScore < 70).sort((a,b) => a.behaviorScore - b.behaviorScore).slice(0, 6)
  , [filteredStudents]);

  const attendanceWatchlist = useMemo(() => 
    filteredStudents
      .map(s => ({ ...s, morningScore: getStudentStats(s).blockScore }))
      .filter(s => s.morningScore < 3.0)
      .sort((a,b) => a.morningScore - b.morningScore)
      .slice(0, 6)
  , [filteredStudents, attendanceMap, activeBlock]);

  const chartData = useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const presentCount = (attendance || []).filter(a => 
        a.date === date && a.status === 'PRESENT' && a.type === 'MORNING'
      ).length;
      return {
        name: new Date(date).toLocaleDateString('th-TH', { weekday: 'short' }),
        value: presentCount
      };
    });
  }, [attendance]);

  if (targetId && currentViewStudent) {
    const stats = getStudentStats(currentViewStudent);
    const studentNotifications = (notifications || []).filter(n => String(n.studentId) === String(currentViewStudent.id)).slice(0, 5);

    return (
      <div className="space-y-6 md:space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            {!isParent && (
              <button 
                onClick={() => setViewingStudentId(null)} 
                className="p-4 bg-white border border-slate-200 rounded-2xl shadow-sm hover:bg-slate-50 transition-all flex items-center justify-center group"
              >
                <ArrowLeft size={20} className="group-hover:-translate-x-1 transition-transform" />
              </button>
            )}
            <div>
              <h2 className="text-xl md:text-3xl font-black text-slate-900 font-heading uppercase tracking-tight">
                {isParent ? 'ข้อมูลบุตรหลาน' : 'สรุปข้อมูลรายบุคคล'}
              </h2>
              <p className="text-[10px] font-bold text-[#00AEEF] uppercase tracking-widest mt-1">
                {currentViewStudent.name} ({currentViewStudent.studentId})
              </p>
            </div>
          </div>
        </div>

        {/* Individual View News Feed */}
        <div className="bg-white p-8 md:p-10 rounded-[40px] border border-slate-200 shadow-sm">
          <h4 className="text-sm font-black text-slate-900 uppercase tracking-widest flex items-center gap-2 mb-6 font-heading">
            <Megaphone className="text-blue-600" size={18} /> ข่าวสารประชาสัมพันธ์สำหรับคุณ
          </h4>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
             {relevantNews.map(n => (
               <div key={n.id} className="p-6 bg-slate-50 rounded-[32px] border border-slate-100 flex flex-col gap-3 group hover:border-blue-300 transition-all">
                  <div className="flex items-center gap-2">
                    <span className={`px-3 py-1 rounded-full text-[8px] font-black uppercase tracking-widest ${
                      n.type === 'URGENT' ? 'bg-red-50 text-red-600' : 'bg-blue-50 text-blue-600'
                    }`}>
                      {n.type === 'URGENT' ? 'ด่วน' : 'ข่าวสาร'}
                    </span>
                    <span className="text-[9px] text-slate-400 font-bold uppercase">{n.date}</span>
                  </div>
                  <h5 className="font-black text-slate-900 text-sm font-heading line-clamp-1">{n.title}</h5>
                  <p className="text-[10px] text-slate-500 font-medium line-clamp-2 leading-relaxed">{n.content}</p>
               </div>
             ))}
             {relevantNews.length === 0 && (
               <div className="col-span-full py-10 text-center text-slate-300">ไม่มีประกาศใหม่</div>
             )}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <StatCard 
            title="เปอร์เซ็นต์เข้าแถว" 
            value={`${stats.attRate}%`} 
            sub="จากทุกวันที่มีการเช็คชื่อ" 
            icon={<CheckCircle2 />} 
            color="bg-[#00AEEF]" 
            textColor="text-[#00AEEF]" 
          />
          <StatCard 
            title="คะแนนพฤติกรรม" 
            value={currentViewStudent.behaviorScore} 
            sub="คะแนนคงเหลือปัจจุบัน" 
            icon={<Activity />} 
            color="bg-indigo-600" 
            textColor="text-indigo-600" 
          />
          <div className="bg-red-600 p-6 md:p-8 rounded-[32px] shadow-xl text-white flex flex-col justify-between hover:bg-red-700 transition-all">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-red-100 text-[9px] font-extrabold uppercase tracking-widest font-heading mb-1">ยอดค้างชำระค่าธรรมเนียม</p>
