const AuditLogs: React.FC<AuditLogsProps> = ({ logs, setLogs }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterRole, setFilterRole] = useState<string>('ALL');

  const filteredLogs = useMemo(() => {
    return logs
      .filter(log => {
        const matchesSearch = 
          log.userName.toLowerCase().includes(searchTerm.toLowerCase()) || 
          log.userId.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesRole = filterRole === 'ALL' || log.userRole === filterRole;
        return matchesSearch && matchesRole;
      })
      .sort((a, b) => b.timestamp.localeCompare(a.timestamp));
  }, [logs, searchTerm, filterRole]);

  const clearLogs = () => {
    if (confirm('คุณต้องการล้างประวัติการเข้าใช้งานทั้งหมดหรือไม่? (ข้อมูลนี้ไม่สามารถกู้คืนได้)')) {
      setLogs([]);
    }
  };

  const getDeviceIcon = (ua: string) => {
    if (/mobile|android|iphone/i.test(ua)) return <Smartphone size={16} className="text-blue-500" />;
    return <Monitor size={16} className="text-slate-500" />;
  };

  return (
    <div className="space-y-6 md:space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div className="flex items-center gap-4">
          <div className="p-4 bg-slate-900 rounded-[24px] text-white shadow-xl">
            <History size={28} />
          </div>
          <div>
            <h2 className="text-2xl md:text-3xl font-black text-slate-900 tracking-tight font-heading uppercase">Login Audit Logs</h2>
            <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">ประวัติการเข้าใช้งานระบบโดยละเอียด</p>
          </div>
        </div>
        <button 
          onClick={clearLogs}
          className="flex items-center gap-2 px-6 py-3 bg-red-50 text-red-600 rounded-xl text-xs font-black uppercase tracking-widest hover:bg-red-600 hover:text-white transition-all font-heading"
        >
          <Trash2 size={16} /> ล้างประวัติทั้งหมด
        </button>
      </div>

      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row items-center gap-4">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="ค้นหาชื่อผู้ใช้ หรือ User ID..." 
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl pl-12 pr-4 py-3.5 text-sm font-bold outline-none transition-all"
          />
        </div>
        <div className="flex items-center gap-3 w-full md:w-auto">
          <div className="p-3.5 bg-slate-100 rounded-2xl text-slate-400">
            <Filter size={18} />
          </div>
          <select 
            value={filterRole}
            onChange={(e) => setFilterRole(e.target.value)}
            className="flex-1 md:w-48 bg-slate-50 border-2 border-transparent focus:border-slate-900 rounded-2xl px-5 py-3.5 text-sm font-bold outline-none cursor-pointer"
          >
            <option value="ALL">ทุกบทบาท</option>
            <option value="ADMIN">ADMIN</option>
            <option value="TEACHER">TEACHER</option>
            <option value="PARENT">PARENT</option>
            <option value="FINANCE">FINANCE</option>
          </select>
        </div>
      </div>

      <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50/50 border-b text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <tr>
                <th className="px-8 py-5">วันเวลาที่เข้าใช้งาน</th>
                <th className="px-8 py-5">ผู้ใช้งาน</th>
                <th className="px-8 py-5">บทบาท</th>
                <th className="px-8 py-5">อุปกรณ์ / ข้อมูลเบราว์เซอร์</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredLogs.length > 0 ? filteredLogs.map((log) => (
                <tr key={log.id} className="hover:bg-slate-50/50 transition-colors group">
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-slate-100 rounded-xl flex items-center justify-center text-slate-400 group-hover:bg-slate-900 group-hover:text-white transition-colors">
                        <Clock size={18} />
                      </div>
                      <div>
                        <p className="text-sm font-black text-slate-900">{log.timestamp.split(' ')[0]}</p>
                        <p className="text-[10px] font-bold text-slate-400 uppercase">{log.timestamp.split(' ')[1]} น.</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-3">
                      <div className="w-9 h-9 bg-blue-50 rounded-lg flex items-center justify-center text-blue-600 font-black text-xs">
                        {log.userName.charAt(0)}
                      </div>
                      <div>
                        <p className="text-sm font-black text-slate-900">{log.userName}</p>
                        <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">ID: {log.userId}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-8 py-6">
                    <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest border ${
                      log.userRole === 'ADMIN' ? 'bg-indigo-50 text-indigo-600 border-indigo-100' :
                      log.userRole === 'TEACHER' ? 'bg-amber-50 text-amber-600 border-amber-100' :
                      log.userRole === 'PARENT' ? 'bg-blue-50 text-blue-600 border-blue-100' :
                      'bg-slate-50 text-slate-600 border-slate-100'
                    }`}>
                      {log.userRole}
                    </span>
                  </td>
                  <td className="px-8 py-6">
                    <div className="flex items-center gap-3 bg-slate-50 p-3 rounded-2xl border border-slate-100 max-w-xs md:max-w-md">
                      <div className="p-2 bg-white rounded-lg shadow-sm shrink-0">
                        {getDeviceIcon(log.deviceInfo)}
                      </div>
                      <p className="text-[10px] font-bold text-slate-500 line-clamp-1 leading-tight uppercase tracking-tighter">
                        {log.deviceInfo}
                      </p>
                    </div>
                  </td>
                </tr>
              )) : (
                <tr>
                  <td colSpan={4} className="py-32 text-center">
                    <div className="flex flex-col items-center gap-4 opacity-20">
                      <History size={64} />
                      <p className="text-sm font-black uppercase tracking-[0.3em]">ยังไม่มีข้อมูลประวัติการใช้งาน</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <div className="p-6 bg-blue-50 rounded-[32px] border border-blue-100 flex gap-4">
        <Info className="text-blue-600 shrink-0" size={24} />
        <div>
          <p className="text-sm font-black text-blue-900 font-heading uppercase">Security Note</p>
          <p className="text-xs text-blue-800 font-bold leading-relaxed mt-1">
            ระบบจะบันทึกทุกครั้งที่มีการเข้าสู่ระบบสำเร็จ ข้อมูลนี้ช่วยให้ผู้ดูแลระบบตรวจสอบความผิดปกติ เช่น การเข้าใช้งานจากสถานที่หรืออุปกรณ์ที่ไม่คุ้นเคยได้
          </p>
        </div>
      </div>
    </div>
  );
};

export default AuditLogs;

import React, { useState, useEffect, useCallback } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import MorningAttendance from './components/MorningAttendance';
import QuickScan from './components/QuickScan';
import ScannerSettings from './components/ScannerSettings';
import ClassAttendance from './components/ClassAttendance';
import BehaviorSystem from './components/BehaviorSystem';
import StudentManagement from './components/StudentManagement';
import Reports from './components/Reports';
import FinanceReport from './components/FinanceReport';
import UserManagement from './components/UserManagement';
import SystemSettings from './components/SystemSettings';
import CloudConfig from './components/CloudConfig';
import LineConfig from './components/LineConfig';
import MorningScoreSummary from './components/MorningScoreSummary';
import TuitionSystem from './components/TuitionSystem';
import NewsBroadcast from './components/NewsBroadcast';
import AuditLogs from './components/AuditLogs';
import Login from './components/Login';
import { MOCK_STUDENTS, MOCK_ATTENDANCE, MOCK_BEHAVIOR, MOCK_SUBJECTS } from './data/mockData';
import { Student, AttendanceRecord, BehaviorRecord, Subject, User, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord, NewsRecord, LoginLog } from './types';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeMenu, setActiveMenu] = useState('dashboard');
  const [isSyncingWithCloud, setIsSyncingWithCloud] = useState(false);

  const [students, setStudents] = useState<Student[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [behaviorRecords, setBehaviorRecords] = useState<BehaviorRecord[]>([]);
  const [notifications, setNotifications] = useState<NotificationRecord[]>([]);
  const [loginLogs, setLoginLogs] = useState<LoginLog[]>([]);
  const [news, setNews] = useState<NewsRecord[]>([
    {
      id: 'N1',
      title: 'แจ้งวันหยุดราชการ กรณีพิเศษ',
      content: 'วิทยาลัยขอแจ้งหยุดเรียนในวันที่ 24 กรกฎาคม นี้ เพื่อให้นักเรียนได้ทำกิจกรรมจิตอาสา...',
      type: 'INFO',
      targetType: 'ALL',
      authorName: 'อ.สมพงษ์ ใจสว่าง',
      date: '10/06/2567',
      timestamp: new Date().toISOString()
    }
  ]);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);
  const [systemUsers, setSystemUsers] = useState<User[]>([]);
  const [tuitionConfigs, setTuitionConfigs] = useState<TuitionConfig[]>([]);
  const [paymentRecords, setPaymentRecords] = useState<PaymentRecord[]>([]);
  const [studyBlocks, setStudyBlocks] = useState<StudyBlock[]>([
    { id: 1, name: 'บล็อกที่ 1', startDate: '2024-05-15', endDate: '2024-06-15', isActive: true, holidays: [] },
    { id: 2, name: 'บล็อกที่ 2', startDate: '2024-06-16', endDate: '2024-07-16', isActive: false, holidays: [] },
    { id: 3, name: 'บล็อกที่ 3', startDate: '2024-07-17', endDate: '2024-08-17', isActive: false, holidays: [] },
    { id: 4, name: 'บล็อกที่ 4', startDate: '2024-08-18', endDate: '2024-09-18', isActive: false, holidays: [] },
    { id: 5, name: 'บล็อกที่ 5', startDate: '2024-09-19', endDate: '2024-10-19', isActive: false, holidays: [] },
  ]);

  const getScriptUrl = () => localStorage.getItem('cms_google_script_url') || '';

  const fetchDataFromCloud = useCallback(async () => {
    const url = getScriptUrl();
    if (!url) return;
    setIsSyncingWithCloud(true);
    try {
      const response = await fetch(`${url}?action=getAllData`);
      const cloudData = await response.json();
      if (cloudData.students) setStudents(cloudData.students);
      if (cloudData.attendance) setAttendance(cloudData.attendance);
      if (cloudData.behavior) setBehaviorRecords(cloudData.behavior);
      if (cloudData.payments) setPaymentRecords(cloudData.payments);
      if (cloudData.subjects) setSubjects(cloudData.subjects);
      if (cloudData.news) setNews(cloudData.news);
      if (cloudData.logs) setLoginLogs(cloudData.logs);
    } catch (error) {
      console.error("Cloud Sync Error:", error);
    } finally {
      setIsSyncingWithCloud(false);
    }
  }, []);

  const syncToCloud = async (type: string, data: any) => {
    const url = getScriptUrl();
    if (!url) return;
    try {
      await fetch(url, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'syncData', type, data })
      });
    } catch (e) {
      console.error("Auto Sync Failed", e);
    }
  };

  useEffect(() => {
    const savedBlocks = localStorage.getItem('cms_study_blocks');
    if (savedBlocks) setStudyBlocks(JSON.parse(savedBlocks));

    const savedLogs = localStorage.getItem('cms_audit_logs');
    if (savedLogs) setLoginLogs(JSON.parse(savedLogs));

    setStudents(MOCK_STUDENTS);
    setAttendance(MOCK_ATTENDANCE);
    setBehaviorRecords(MOCK_BEHAVIOR);
    setSubjects(MOCK_SUBJECTS);
    setSystemUsers([
      { id: 'A1', name: 'แอดมิน ระบบ', role: 'ADMIN', username: 'admin', password: '1234', department: 'ส่วนกลาง' },
      { id: 'T1', name: 'อ.สมพงษ์ ใจสว่าง', role: 'TEACHER', username: 'teacher', password: '1234', department: 'เทคโนโลยีสารสนเทศ' },
      { id: 'F1', name: 'ฝ่ายการเงิน', role: 'FINANCE', username: 'finance', password: '1234', department: 'ฝ่ายการเงิน' },
      { id: 'P1', name: 'คุณแม่ของนายสมชาย', role: 'PARENT', username: 'parent', password: '1234', studentId: '1' }
    ]);
    fetchDataFromCloud();
  }, [fetchDataFromCloud]);

  const handleLogin = (userData: User) => {
    const newLog: LoginLog = {
      id: `LOG_${Date.now()}`,
      userId: userData.username,
      userName: userData.name,
      userRole: userData.role,
      timestamp: new Date().toLocaleString('th-TH'),
      deviceInfo: navigator.userAgent
    };

    setLoginLogs(prev => {
      const updated = [newLog, ...prev].slice(0, 1000); // เก็บไว้สูงสุด 1000 รายการ
      localStorage.setItem('cms_audit_logs', JSON.stringify(updated));
      syncToCloud('logs', updated);
      return updated;
    });

    setUser(userData);
  };

  if (!user) return <Login onLogin={handleLogin} systemUsers={systemUsers} />;

  const renderContent = () => {
    switch (activeMenu) {
      case 'dashboard': return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} news={news} notifications={notifications} user={user} studyBlocks={studyBlocks} tuitionConfigs={tuitionConfigs} paymentRecords={paymentRecords} />;
      case 'broadcast': return <NewsBroadcast students={students} news={news} setNews={(val) => { setNews(val); syncToCloud('news', val); }} currentUser={user} />;
      case 'quick_scan': return <QuickScan students={students} attendanceRecords={attendance} setAttendanceRecords={(val) => { setAttendance(val); syncToCloud('attendance', val); }} />;
      case 'students': return <StudentManagement students={students} setStudents={(val) => { setStudents(val); syncToCloud('students', val); }} />;
      case 'morning': return <MorningAttendance students={students} setStudents={setStudents} attendanceRecords={attendance} setAttendanceRecords={(val) => { setAttendance(val); syncToCloud('attendance', val); }} rooms={rooms} setRooms={setRooms} />;
      case 'subject': return <ClassAttendance students={students} setStudents={setStudents} subjects={subjects} setSubjects={(val) => { setSubjects(val); syncToCloud('subjects', val); }} rooms={rooms} setRooms={setRooms} attendanceRecords={attendance} setAttendanceRecords={(val) => { setAttendance(val); syncToCloud('attendance', val); }} currentUser={user} />;
      case 'behavior': return <BehaviorSystem students={students} setStudents={setStudents} behaviorRecords={behaviorRecords} setBehaviorRecords={(val) => { setBehaviorRecords(val); syncToCloud('behavior', val); }} />;
      case 'tuition': return <TuitionSystem students={students} tuitionConfigs={tuitionConfigs} setTuitionConfigs={setTuitionConfigs} paymentRecords={paymentRecords} setPaymentRecords={(val) => { setPaymentRecords(val); syncToCloud('payments', val); }} user={user} />;
      case 'finance_report': return <FinanceReport students={students} paymentRecords={paymentRecords} tuitionConfigs={tuitionConfigs} />;
      case 'report': return <Reports students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} paymentRecords={paymentRecords} tuitionConfigs={tuitionConfigs} />;
      case 'morning_scores': return <MorningScoreSummary students={students} attendance={attendance} studyBlocks={studyBlocks} />;
      case 'users': return <UserManagement users={systemUsers} setUsers={setSystemUsers} currentUser={user} students={students} />;
      case 'audit_logs': return <AuditLogs logs={loginLogs} setLogs={(val) => { setLoginLogs(val); localStorage.setItem('cms_audit_logs', JSON.stringify(val)); syncToCloud('logs', val); }} />;
      case 'scanner_settings': return <ScannerSettings />;
      case 'settings': return <SystemSettings studyBlocks={studyBlocks} setStudyBlocks={(val) => { setStudyBlocks(val); localStorage.setItem('cms_study_blocks', JSON.stringify(val)); }} />;
      case 'cloud_config': return <CloudConfig students={students} attendance={attendance} behavior={behaviorRecords} payments={paymentRecords} subjects={subjects} />;
      case 'line_config': return <LineConfig />;
      default: return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} news={news} />;
    }
  };

  return (
    <Layout activeMenu={activeMenu} setActiveMenu={setActiveMenu} user={user} onLogout={() => setUser(null)} notifications={notifications} setNotifications={setNotifications}>
      {isSyncingWithCloud && (
        <div className="fixed bottom-8 right-8 z-[100] bg-slate-900 text-white px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 animate-bounce">
          <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
          <span className="text-xs font-black uppercase tracking-widest">กำลังดึงข้อมูลล่าสุดจากระบบ Cloud...</span>
        </div>
      )}
      {renderContent()}
    </Layout>
  );
};

export default App;

