                     <p className="text-xs font-bold text-white/80 uppercase tracking-widest">
                       {upcomingExam.blockName} • สอบวันที่ {new Date(upcomingExam.date).toLocaleDateString('th-TH', { dateStyle: 'long' })} ({upcomingExam.time} น.)
