                   <button onClick={handlePrint} className="flex-1 py-4 bg-[#00AEEF] text-white rounded-2xl font-black text-xs uppercase tracking-widest font-heading shadow-xl shadow-sky-100 flex items-center justify-center gap-2 hover:bg-sky-600 transition-all">
                      <Printer size={18} /> สั่งพิมพ์ใบเสร็จ
                   </button>
                </div>
             </div>
          </div>
        </div>
      )}

      {/* Global CSS for Printing */}
      <style dangerouslySetInnerHTML={{ __html: `
        @media print {
          body * {
            visibility: hidden;
          }
          #receipt-content, #receipt-content * {
            visibility: visible;
          }
          #receipt-content {
            position: fixed;
            left: 0;
            top: 0;
            width: 100%;
            padding: 40px !important;
            background: white !important;
          }
          .no-print {
            display: none !important;
          }
        }
        .scrollbar-hide::-webkit-scrollbar { display: none; }
      `}} />
    </div>
  );
};

export default TuitionSystem;

import React, { useState, useMemo, useEffect } from 'react';
