  CreditCard, Plus, Save, Trash2, Banknote, History, Search, CheckCircle2, 
  User, Wallet, Building2, X, Loader2,
  Printer, FileText, MapPin, Phone
} from 'lucide-react';

interface ReceiptSettings {
  schoolName: string;
  address: string;
  phone: string;
  receiverName: string;
}

