                   </button>
                </div>
             </div>
          </div>
        </div>
      )}

      {/* Global CSS for Printing A5 */}
      <style dangerouslySetInnerHTML={{ __html: `
        @media print {
          @page {
            size: A5 landscape;
            margin: 0;
          }
          body * {
