            .sign-section { margin-top: 30px; display: grid; grid-template-columns: 1fr 1fr; gap: 40px; text-align: center; font-size: 12px; }
          </style>
        </head>
        <body onload="window.print(); window.close();">
          <div class="receipt-container">
            ${printContent.innerHTML}
          </div>
        </body>
      </html>
    `;

    printWindow.document.write(html);
