                      <Printer size={18} /> สั่งพิมพ์ใบเสร็จ (Landscape)
                   </button>
                </div>
             </div>
          </div>
        </div>
      )}

      <style dangerouslySetInnerHTML={{ __html: `
        .no-print { display: block; }
