              font-family: 'Sarabun', sans-serif; 
              margin: 0; 
              padding: 0; 
              -webkit-print-color-adjust: exact;
            }
            .receipt-container {
              width: 210mm;
              height: 148mm;
              padding: 12mm;
              box-sizing: border-box;
              display: flex;
              flex-direction: column;
              overflow: hidden;
              background: white;
            }
