              border: 1.5px solid #000; 
              padding: 4px 15px; 
              display: inline-block; 
              font-weight: bold; 
              margin-top: 8px;
              border-radius: 4px;
            }
            .line-double { border-bottom: 3.5px double #000; }
            .flex-grow { flex-grow: 1; }
            .signature-area {
