              display: grid;
              grid-template-columns: 1fr 1fr;
              gap: 50px;
              padding-bottom: 10mm;
              text-align: center;
            }
          </style>
        </head>
        <body onload="window.print(); window.close();">
          <div class="receipt-container">
            ${printContent.innerHTML}
          </div>
        </body>
      </html>
    `;

