                  </div>
                </div>
                <div className="flex-1 bg-slate-200 p-4 md:p-8">
                  <iframe 
                    src={`${selectedCalendar.url}#toolbar=0`} 
                    className="w-full h-full rounded-[24px] shadow-2xl bg-white border-none"
                    title="PDF Preview"
