import React, { useState, useEffect, useCallback } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import MorningAttendance from './components/MorningAttendance';
import QuickScan from './components/QuickScan';
import ScannerSettings from './components/ScannerSettings';
import ClassAttendance from './components/ClassAttendance';
import BehaviorSystem from './components/BehaviorSystem';
import StudentManagement from './components/StudentManagement';
import Reports from './components/Reports';
import FinanceReport from './components/FinanceReport';
import UserManagement from './components/UserManagement';
import SystemSettings from './components/SystemSettings';
import ExamManager from './components/ExamManager';
import CloudConfig from './components/CloudConfig';
import LineConfig from './components/LineConfig';
import MorningScoreSummary from './components/MorningScoreSummary';
import TuitionSystem from './components/TuitionSystem';
import NewsBroadcast from './components/NewsBroadcast';
import AuditLogs from './components/AuditLogs';
import JobPortal from './components/JobPortal'; 
import AcademicCalendar from './components/AcademicCalendar';
import Login from './components/Login';
import { MOCK_STUDENTS, MOCK_ATTENDANCE, MOCK_BEHAVIOR, MOCK_SUBJECTS } from './data/mockData';
import { Student, AttendanceRecord, BehaviorRecord, Subject, User, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord, NewsRecord, LoginLog } from './types';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeMenu, setActiveMenu] = useState('dashboard');
  const [isSyncingWithCloud, setIsSyncingWithCloud] = useState(false);

  const [students, setStudents] = useState<Student[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [behaviorRecords, setBehaviorRecords] = useState<BehaviorRecord[]>([]);
  const [notifications, setNotifications] = useState<NotificationRecord[]>([]);
  const [loginLogs, setLoginLogs] = useState<LoginLog[]>([]);
  const [news, setNews] = useState<NewsRecord[]>([
    {
      id: 'N1',
      title: 'แจ้งวันหยุดราชการ กรณีพิเศษ',
      content: 'วิทยาลัยขอแจ้งหยุดเรียนในวันที่ 24 กรกฎาคม นี้ เพื่อให้นักเรียนได้ทำกิจกรรมจิตอาสา...',
      type: 'INFO',
      targetType: 'ALL',
      authorName: 'อ.สมพงษ์ ใจสว่าง',
      date: '10/06/2567',
      timestamp: new Date().toISOString()
    }
  ]);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);
  const [systemUsers, setSystemUsers] = useState<User[]>([]);
  const [tuitionConfigs, setTuitionConfigs] = useState<TuitionConfig[]>([]);
  const [paymentRecords, setPaymentRecords] = useState<PaymentRecord[]>([]);
  const [studyBlocks, setStudyBlocks] = useState<StudyBlock[]>([
    { id: 1, name: 'บล็อกที่ 1', startDate: '2024-05-15', endDate: '2024-06-15', isActive: true, holidays: [], examDate: '2024-06-15' },
    { id: 2, name: 'บล็อกที่ 2', startDate: '2024-06-16', endDate: '2024-07-16', isActive: false, holidays: [], examDate: '2024-07-16' },
    { id: 3, name: 'บล็อกที่ 3', startDate: '2024-07-17', endDate: '2024-08-17', isActive: false, holidays: [], examDate: '2024-08-17' },
    { id: 4, name: 'บล็อกที่ 4', startDate: '2024-08-18', endDate: '2024-09-18', isActive: false, holidays: [], examDate: '2024-09-18' },
    { id: 5, name: 'บล็อกที่ 5', startDate: '2024-09-19', endDate: '2024-10-19', isActive: false, holidays: [], examDate: '2024-10-19' },
  ]);

  const getScriptUrl = () => localStorage.getItem('cms_google_script_url') || '';

  const fetchDataFromCloud = useCallback(async () => {
    const url = getScriptUrl();
    if (!url) return;
    setIsSyncingWithCloud(true);
    try {
      const response = await fetch(`${url}?action=getAllData`);
      const cloudData = await response.json();
      if (cloudData.students) setStudents(cloudData.students);
      if (cloudData.attendance) setAttendance(cloudData.attendance);
      if (cloudData.behavior) setBehaviorRecords(cloudData.behavior);
      if (cloudData.payments) setPaymentRecords(cloudData.payments);
      if (cloudData.subjects) setSubjects(cloudData.subjects);
      if (cloudData.news) setNews(cloudData.news);
      if (cloudData.logs) setLoginLogs(cloudData.logs);
      if (cloudData.blocks) setStudyBlocks(cloudData.blocks);
    } catch (error) {
      console.error("Cloud Sync Error:", error);
    } finally {
      setIsSyncingWithCloud(false);
    }
  }, []);

  const syncToCloud = async (type: string, data: any) => {
    const url = getScriptUrl();
    if (!url) return;
    try {
      await fetch(url, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'syncData', type, data })
      });
    } catch (e) {
      console.error("Auto Sync Failed", e);
    }
  };

  useEffect(() => {
    const savedBlocks = localStorage.getItem('cms_study_blocks');
    if (savedBlocks) setStudyBlocks(JSON.parse(savedBlocks));

    const savedLogs = localStorage.getItem('cms_audit_logs');
    if (savedLogs) setLoginLogs(JSON.parse(savedLogs));

    setStudents(MOCK_STUDENTS);
    setAttendance(MOCK_ATTENDANCE);
    setBehaviorRecords(MOCK_BEHAVIOR);
    setSubjects(MOCK_SUBJECTS);
    setSystemUsers([
      { id: 'A1', name: 'แอดมิน ระบบ', role: 'ADMIN', username: 'admin', password: '1234', department: 'ส่วนกลาง' },
      { id: 'AC1', name: 'หัวหน้างานฝ่ายวิชาการ', role: 'ACADEMIC', username: 'academic', password: '1234', department: 'งานวิชาการ' },
      { id: 'T1', name: 'อ.สมพงษ์ ใจสว่าง', role: 'TEACHER', username: 'teacher', password: '1234', department: 'เทคโนโลยีสารสนเทศ' },
      { id: 'C1', name: 'บจก. นวัตกรรมซอฟต์แวร์', role: 'COMPANY', username: 'company', password: '1234', companyName: 'บริษัท นวัตกรรมซอฟต์แวร์ จำกัด' },
      { id: 'F1', name: 'ฝ่ายการเงิน', role: 'FINANCE', username: 'finance', password: '1234', department: 'ฝ่ายการเงิน' },
      { id: 'P1', name: 'คุณแม่ของนายสมชาย', role: 'PARENT', username: 'parent', password: '1234', studentId: '1' }
    ]);
    fetchDataFromCloud();
  }, [fetchDataFromCloud]);

  const handleLogin = (userData: User) => {
    const newLog: LoginLog = {
      id: `LOG_${Date.now()}`,
      userId: userData.username,
      userName: userData.name,
      userRole: userData.role,
      timestamp: new Date().toLocaleString('th-TH'),
      deviceInfo: navigator.userAgent
    };

    setLoginLogs(prev => {
      const updated = [newLog, ...prev].slice(0, 1000); 
      localStorage.setItem('cms_audit_logs', JSON.stringify(updated));
      syncToCloud('logs', updated);
      return updated;
    });

    setUser(userData);
    if (userData.role === 'COMPANY') {
      setActiveMenu('job_portal');
    } else {
      setActiveMenu('dashboard');
    }
  };

  if (!user) return <Login onLogin={handleLogin} systemUsers={systemUsers} />;

  const renderContent = () => {
    switch (activeMenu) {
      case 'dashboard': return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} news={news} notifications={notifications} user={user} studyBlocks={studyBlocks} tuitionConfigs={tuitionConfigs} paymentRecords={paymentRecords} />;
      case 'academic_calendar': return <AcademicCalendar currentUser={user} />;
      case 'job_portal': return <JobPortal currentUser={user} students={students} />; 
      case 'broadcast': return <NewsBroadcast students={students} news={news} setNews={(val) => { setNews(val); syncToCloud('news', val); }} currentUser={user} />;
      case 'quick_scan': return <QuickScan students={students} attendanceRecords={attendance} setAttendanceRecords={(val) => { setAttendance(val); syncToCloud('attendance', val); }} />;
      case 'students': return <StudentManagement students={students} setStudents={(val) => { setStudents(val); syncToCloud('students', val); }} />;
      case 'morning': return <MorningAttendance students={students} setStudents={setStudents} attendanceRecords={attendance} setAttendanceRecords={(val) => { setAttendance(val); syncToCloud('attendance', val); }} rooms={rooms} setRooms={setRooms} />;
      case 'subject': return <ClassAttendance students={students} setStudents={setStudents} subjects={subjects} setSubjects={(val) => { setSubjects(val); syncToCloud('subjects', val); }} rooms={rooms} setRooms={setRooms} attendanceRecords={attendance} setAttendanceRecords={(val) => { setAttendance(val); syncToCloud('attendance', val); }} currentUser={user} />;
      case 'behavior': return <BehaviorSystem students={students} setStudents={setStudents} behaviorRecords={behaviorRecords} setBehaviorRecords={(val) => { setBehaviorRecords(val); syncToCloud('behavior', val); }} />;
      case 'tuition': return <TuitionSystem students={students} tuitionConfigs={tuitionConfigs} setTuitionConfigs={setTuitionConfigs} paymentRecords={paymentRecords} setPaymentRecords={(val) => { setPaymentRecords(val); syncToCloud('payments', val); }} user={user} />;
      case 'finance_report': return <FinanceReport students={students} paymentRecords={paymentRecords} tuitionConfigs={tuitionConfigs} />;
      case 'report': return <Reports students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} paymentRecords={paymentRecords} tuitionConfigs={tuitionConfigs} />;
      case 'morning_scores': return <MorningScoreSummary students={students} attendance={attendance} studyBlocks={studyBlocks} />;
      case 'users': return <UserManagement users={systemUsers} setUsers={setSystemUsers} currentUser={user} students={students} />;
      case 'audit_logs': return <AuditLogs logs={loginLogs} setLogs={(val) => { setLoginLogs(val); localStorage.setItem('cms_audit_logs', JSON.stringify(val)); syncToCloud('logs', val); }} />;
      case 'exam_manager': return <ExamManager studyBlocks={studyBlocks} setStudyBlocks={(val) => { setStudyBlocks(val); localStorage.setItem('cms_study_blocks', JSON.stringify(val)); syncToCloud('blocks', val); }} />;
      case 'scanner_settings': return <ScannerSettings />;
      case 'settings': return <SystemSettings studyBlocks={studyBlocks} setStudyBlocks={(val) => { setStudyBlocks(val); localStorage.setItem('cms_study_blocks', JSON.stringify(val)); }} />;
      case 'cloud_config': return <CloudConfig students={students} attendance={attendance} behavior={behaviorRecords} payments={paymentRecords} subjects={subjects} />;
      case 'line_config': return <LineConfig />;
      default: return <JobPortal currentUser={user} students={students} />;
    }
  };

  return (
    <Layout activeMenu={activeMenu} setActiveMenu={setActiveMenu} user={user} onLogout={() => setUser(null)} notifications={notifications} setNotifications={setNotifications}>
      {isSyncingWithCloud && (
        <div className="fixed bottom-8 right-8 z-[100] bg-slate-900 text-white px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 animate-bounce">
          <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
          <span className="text-xs font-black uppercase tracking-widest">กำลังดึงข้อมูลล่าสุดจากระบบ Cloud...</span>
        </div>
      )}
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Calendar, 
  FileUp, 
  FileText, 
  Trash2, 
  ExternalLink, 
  Download,
  AlertCircle,
  Eye,
  Loader2,
  Sparkles
} from 'lucide-react';

interface CalendarFile {
  id: string;
  name: string;
  url: string;
  date: string;
  size: string;
}

interface AcademicCalendarProps {
  currentUser: any;
}

// ตัวอย่างไฟล์ PDF จำลอง (Base64 ของไฟล์ PDF เปล่าที่มีข้อความต้อนรับ)
const MOCK_PDF_URL = "data:application/pdf;base64,";

const AcademicCalendar: React.FC<AcademicCalendarProps> = ({ currentUser }) => {
  const [calendars, setCalendars] = useState<CalendarFile[]>([]);
  const [selectedCalendar, setSelectedCalendar] = useState<CalendarFile | null>(null);
  const [isUploading, setIsUploading] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('cms_academic_calendars');
    if (saved) {
      const parsed = JSON.parse(saved);
      setCalendars(parsed);
      if (parsed.length > 0) setSelectedCalendar(parsed[0]);
    } else {
      // เพิ่มตัวอย่างข้อมูลครั้งแรก
      const mockData: CalendarFile[] = [
        {
          id: 'CAL_SAMPLE_1',
          name: 'ปฏิทินการศึกษา_ภาคเรียนที่_1_2567.pdf',
          url: MOCK_PDF_URL,
          date: '20/05/2567',
          size: '0.45 MB'
        },
        {
          id: 'CAL_SAMPLE_2',
          name: 'กำหนดการสอบปลายภาค_บล็อกที่_1.pdf',
          url: MOCK_PDF_URL,
          date: '15/05/2567',
          size: '0.22 MB'
        }
      ];
      setCalendars(mockData);
      setSelectedCalendar(mockData[0]);
      localStorage.setItem('cms_academic_calendars', JSON.stringify(mockData));
    }
  }, []);

  const isAdminOrAcademic = currentUser.role === 'ADMIN' || currentUser.role === 'ACADEMIC';

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.type !== 'application/pdf') {
      alert('กรุณาอัปโหลดไฟล์ PDF เท่านั้น');
      return;
    }

    setIsUploading(true);

    const reader = new FileReader();
    reader.onload = (event) => {
      const base64Url = event.target?.result as string;
      const newCal: CalendarFile = {
        id: `CAL_${Date.now()}`,
        name: file.name,
        url: base64Url,
        date: new Date().toLocaleDateString('th-TH'),
        size: (file.size / (1024 * 1024)).toFixed(2) + ' MB'
      };

      const updated = [newCal, ...calendars];
      setCalendars(updated);
      setSelectedCalendar(newCal);
      localStorage.setItem('cms_academic_calendars', JSON.stringify(updated));
      setIsUploading(false);
      if (e.target) e.target.value = '';
    };
    reader.readAsDataURL(file);
  };

  const deleteCalendar = (id: string) => {
    if (!confirm('ยืนยันการลบไฟล์ปฏิทินนี้?')) return;
    const updated = calendars.filter(c => c.id !== id);
    setCalendars(updated);
    localStorage.setItem('cms_academic_calendars', JSON.stringify(updated));
    if (selectedCalendar?.id === id) {
      setSelectedCalendar(updated.length > 0 ? updated[0] : null);
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20 max-w-7xl mx-auto">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div className="flex items-center gap-5">
          <div className="p-4 bg-blue-600 text-white rounded-[24px] shadow-xl shadow-blue-100 ring-4 ring-blue-50">
            <Calendar size={32} />
          </div>
          <div>
            <div className="flex items-center gap-2">
               <h2 className="text-3xl font-black text-slate-900 font-heading uppercase tracking-tight">Academic Calendar</h2>
               <Sparkles className="text-amber-500 hidden sm:block" size={20} />
            </div>
            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">ปฏิทินกิจกรรมและการศึกษาประจำปี</p>
          </div>
        </div>

        {isAdminOrAcademic && (
          <div className="relative group">
            <input 
              type="file" 
              accept=".pdf" 
              onChange={handleFileUpload}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
            />
            <button className="flex items-center justify-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-[11px] uppercase tracking-widest shadow-2xl transition-all group-hover:bg-black group-hover:scale-105 active:scale-95 font-heading">
              {isUploading ? <Loader2 className="animate-spin" size={18} /> : <FileUp size={18} />}
              {isUploading ? 'กำลังอัปโหลด...' : 'อัปโหลดปฏิทินใหม่ (PDF)'}
            </button>
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* File List */}
        <div className="lg:col-span-4 space-y-4">
          <div className="flex items-center justify-between px-1">
             <h3 className="text-sm font-black text-slate-900 uppercase tracking-widest flex items-center gap-2 font-heading">
               <FileText size={18} className="text-blue-500" /> เอกสารปฏิทิน ({calendars.length})
             </h3>
          </div>
          <div className="space-y-3 max-h-[700px] overflow-y-auto pr-2 scrollbar-hide">
            {calendars.map(cal => (
              <div 
                key={cal.id}
                onClick={() => setSelectedCalendar(cal)}
                className={`p-5 rounded-[28px] border-2 transition-all cursor-pointer group flex flex-col gap-3 relative overflow-hidden ${
                  selectedCalendar?.id === cal.id 
                  ? 'bg-white border-blue-600 shadow-xl shadow-blue-100 ring-1 ring-blue-600/10' 
                  : 'bg-white border-slate-100 hover:border-blue-300'
                }`}
              >
                {selectedCalendar?.id === cal.id && (
                   <div className="absolute top-0 right-0 p-2 text-blue-600 opacity-20">
                      <Calendar size={40} />
                   </div>
                )}

                <div className="flex justify-between items-start relative z-10">
                  <div className="flex items-center gap-3">
                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-colors ${selectedCalendar?.id === cal.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-200' : 'bg-slate-100 text-slate-400 group-hover:bg-blue-100 group-hover:text-blue-600'}`}>
                      <FileText size={20} />
                    </div>
                    <div className="min-w-0">
                      <p className={`font-black text-sm truncate leading-tight transition-colors ${selectedCalendar?.id === cal.id ? 'text-blue-600' : 'text-slate-900'}`}>{cal.name}</p>
                      <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase tracking-tighter">{cal.date} • {cal.size}</p>
                    </div>
                  </div>
                </div>

                <div className="flex items-center justify-between mt-1 relative z-10">
                   <div className="flex gap-2">
                      <span className="text-[8px] font-black text-blue-600 px-2 py-0.5 bg-blue-50 rounded-md uppercase tracking-widest">PDF Document</span>
                   </div>
                   {isAdminOrAcademic && (
                    <button 
                      onClick={(e) => { e.stopPropagation(); deleteCalendar(cal.id); }}
                      className="p-2 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                      title="ลบไฟล์"
                    >
                      <Trash2 size={14} />
                    </button>
                  )}
                </div>
              </div>
            ))}
            {calendars.length === 0 && (
              <div className="py-24 text-center bg-white rounded-[40px] border-4 border-dashed border-slate-50">
                <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-6">
                  <Calendar size={40} className="text-slate-200" />
                </div>
                <p className="text-slate-400 font-black uppercase tracking-[0.2em] text-xs">ยังไม่มีการอัปโหลดไฟล์</p>
                <p className="text-slate-300 text-[10px] font-bold mt-2">โปรดใช้ปุ่มด้านบนเพื่อเพิ่มปฏิทิน</p>
              </div>
            )}
          </div>
        </div>

        {/* Preview Area */}
        <div className="lg:col-span-8">
          <div className="bg-white rounded-[48px] border border-slate-200 shadow-sm overflow-hidden h-[850px] flex flex-col relative group/preview">
            {selectedCalendar ? (
              <>
                <div className="p-7 bg-slate-50 border-b flex flex-col sm:flex-row items-center justify-between gap-4">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-blue-600 text-white rounded-2xl flex items-center justify-center shadow-2xl shadow-blue-200">
                      <Eye size={24} />
                    </div>
                    <div>
                      <h4 className="text-base font-black text-slate-900 font-heading leading-none uppercase tracking-tight truncate max-w-[200px] md:max-w-md">{selectedCalendar.name}</h4>
                      <p className="text-[10px] font-bold text-slate-400 mt-1.5 uppercase tracking-[0.15em] flex items-center gap-2">
                         <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" /> ระบบดูตัวอย่างแบบเรียลไทม์
                      </p>
                    </div>
                  </div>
                  <div className="flex gap-2 w-full sm:w-auto">
                    <a 
                      href={selectedCalendar.url} 
                      download={selectedCalendar.name}
                      className="flex-1 sm:flex-none p-3.5 bg-white border border-slate-200 text-slate-600 rounded-2xl hover:bg-slate-900 hover:text-white transition-all shadow-sm flex items-center justify-center gap-2"
                    >
                      <Download size={18} />
                      <span className="sm:hidden text-xs font-black uppercase">Download</span>
                    </a>
                    <button 
                      onClick={() => window.open(selectedCalendar.url, '_blank')}
                      className="flex-1 sm:flex-none p-3.5 bg-white border border-slate-200 text-slate-600 rounded-2xl hover:bg-slate-900 hover:text-white transition-all shadow-sm flex items-center justify-center gap-2"
                    >
                      <ExternalLink size={18} />
                      <span className="sm:hidden text-xs font-black uppercase">Open Full</span>
                    </button>
                  </div>
                </div>
                <div className="flex-1 bg-slate-100 p-4 md:p-8 flex items-center justify-center relative">
                  {/* Background branding inside viewer */}
                  <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.03]">
                     <h1 className="text-[120px] font-black uppercase rotate-12 select-none">EDUSMART</h1>
                  </div>
                  <iframe 
                    src={`${selectedCalendar.url}#toolbar=0&navpanes=0`} 
                    className="w-full h-full rounded-[32px] shadow-[0_20px_50px_-20px_rgba(0,0,0,0.3)] bg-white border-none relative z-10"
                    title="PDF Preview"
                  />
                </div>
              </>
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center p-20 text-center bg-slate-50">
                <div className="w-28 h-28 bg-white rounded-[40px] flex items-center justify-center text-slate-100 mb-8 animate-pulse shadow-inner border border-slate-100">
                  <Eye size={54} />
                </div>
                <h3 className="text-3xl font-black text-slate-900 font-heading uppercase tracking-widest">Interactive Viewer</h3>
                <p className="text-slate-400 text-sm mt-4 font-bold max-w-sm mx-auto leading-relaxed uppercase tracking-tight">
                  เลือกไฟล์จากรายการด้านซ้ายเพื่อเปิดดูปฏิทินวิชาการ ตารางสอบ และวันสำคัญประจำปีการศึกษา
                </p>
                <div className="mt-10 flex gap-2">
                   <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce" />
                   <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce delay-150" />
                   <div className="w-2 h-2 bg-blue-500 rounded-full animate-bounce delay-300" />
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-8 md:p-12 rounded-[56px] shadow-2xl relative overflow-hidden text-white">
        <div className="absolute top-0 right-0 p-12 opacity-10 pointer-events-none transform translate-x-12 -translate-y-12">
           <AlertCircle size={250} />
        </div>
        <div className="flex flex-col md:flex-row gap-8 items-center relative z-10">
          <div className="p-5 bg-white/20 backdrop-blur-xl rounded-[32px] text-white shadow-xl shrink-0">
             <AlertCircle size={40} strokeWidth={2.5} />
          </div>
          <div className="space-y-2 text-center md:text-left">
            <h3 className="text-2xl font-black font-heading uppercase tracking-tight">ข้อแนะนำการใช้งานระบบปฏิทิน</h3>
            <p className="text-sm text-blue-100 font-medium leading-relaxed max-w-3xl">
              ไฟล์ที่อัปโหลดจะถูกจัดเก็บไว้ในหน่วยความจำของเบราว์เซอร์ (Local Storage) เครื่องนี้เท่านั้น 
              หากต้องการแชร์ให้ผู้ใช้อื่นหรือเครื่องอื่นเห็นข้อมูล แนะนำให้ใช้เมนู <span className="underline font-bold">"ประชาสัมพันธ์ข่าวสาร"</span> เพื่อส่งไฟล์ หรืออัปโหลดซ้ำในแต่ละเครื่องที่ใช้งาน
            </p>
          </div>
          <div className="md:ml-auto">
             <div className="px-6 py-3 bg-white/10 backdrop-blur-md rounded-2xl border border-white/20 text-[10px] font-black uppercase tracking-[0.2em]">
                Secured Local Storage
             </div>
          </div>
        </div>
      </div>

      <style dangerouslySetInnerHTML={{ __html: `
        .scrollbar-hide::-webkit-scrollbar { display: none; }
        .origin-center { transform-origin: center center; }
        iframe {
          -ms-zoom: 0.75;
          -moz-transform: scale(0.75);
          -moz-transform-origin: 0 0;
          -o-transform: scale(0.75);
          -o-transform-origin: 0 0;
          -webkit-transform: scale(0.75);
          -webkit-transform-origin: 0 0;
        }
      `}} />
    </div>
  );
};

export default AcademicCalendar;

import React, { useState, useEffect, useCallback } from 'react';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import MorningAttendance from './components/MorningAttendance';
import QuickScan from './components/QuickScan';
import ScannerSettings from './components/ScannerSettings';
import ClassAttendance from './components/ClassAttendance';
import BehaviorSystem from './components/BehaviorSystem';
import StudentManagement from './components/StudentManagement';
import Reports from './components/Reports';
import FinanceReport from './components/FinanceReport';
import UserManagement from './components/UserManagement';
import SystemSettings from './components/SystemSettings';
import ExamManager from './components/ExamManager';
import CloudConfig from './components/CloudConfig';
import LineConfig from './components/LineConfig';
import MorningScoreSummary from './components/MorningScoreSummary';
import TuitionSystem from './components/TuitionSystem';
import NewsBroadcast from './components/NewsBroadcast';
import AuditLogs from './components/AuditLogs';
import JobPortal from './components/JobPortal'; 
import Login from './components/Login';
import { MOCK_STUDENTS, MOCK_ATTENDANCE, MOCK_BEHAVIOR, MOCK_SUBJECTS } from './data/mockData';
import { Student, AttendanceRecord, BehaviorRecord, Subject, User, StudyBlock, TuitionConfig, PaymentRecord, NotificationRecord, NewsRecord, LoginLog } from './types';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [activeMenu, setActiveMenu] = useState('dashboard');
  const [isSyncingWithCloud, setIsSyncingWithCloud] = useState(false);

  const [students, setStudents] = useState<Student[]>([]);
  const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
  const [behaviorRecords, setBehaviorRecords] = useState<BehaviorRecord[]>([]);
  const [notifications, setNotifications] = useState<NotificationRecord[]>([]);
  const [loginLogs, setLoginLogs] = useState<LoginLog[]>([]);
  const [news, setNews] = useState<NewsRecord[]>([
    {
      id: 'N1',
      title: 'แจ้งวันหยุดราชการ กรณีพิเศษ',
      content: 'วิทยาลัยขอแจ้งหยุดเรียนในวันที่ 24 กรกฎาคม นี้ เพื่อให้นักเรียนได้ทำกิจกรรมจิตอาสา...',
      type: 'INFO',
      targetType: 'ALL',
      authorName: 'อ.สมพงษ์ ใจสว่าง',
      date: '10/06/2567',
      timestamp: new Date().toISOString()
    }
  ]);
  const [subjects, setSubjects] = useState<Subject[]>([]);
  const [rooms, setRooms] = useState<string[]>(['1', '2', '3']);
  const [systemUsers, setSystemUsers] = useState<User[]>([]);
  const [tuitionConfigs, setTuitionConfigs] = useState<TuitionConfig[]>([]);
  const [paymentRecords, setPaymentRecords] = useState<PaymentRecord[]>([]);
  const [studyBlocks, setStudyBlocks] = useState<StudyBlock[]>([
    { id: 1, name: 'บล็อกที่ 1', startDate: '2024-05-15', endDate: '2024-06-15', isActive: true, holidays: [], examDate: '2024-06-15' },
    { id: 2, name: 'บล็อกที่ 2', startDate: '2024-06-16', endDate: '2024-07-16', isActive: false, holidays: [], examDate: '2024-07-16' },
    { id: 3, name: 'บล็อกที่ 3', startDate: '2024-07-17', endDate: '2024-08-17', isActive: false, holidays: [], examDate: '2024-08-17' },
    { id: 4, name: 'บล็อกที่ 4', startDate: '2024-08-18', endDate: '2024-09-18', isActive: false, holidays: [], examDate: '2024-09-18' },
    { id: 5, name: 'บล็อกที่ 5', startDate: '2024-09-19', endDate: '2024-10-19', isActive: false, holidays: [], examDate: '2024-10-19' },
  ]);

  const getScriptUrl = () => localStorage.getItem('cms_google_script_url') || '';

  const fetchDataFromCloud = useCallback(async () => {
    const url = getScriptUrl();
    if (!url) return;
    setIsSyncingWithCloud(true);
    try {
      const response = await fetch(`${url}?action=getAllData`);
      const cloudData = await response.json();
      if (cloudData.students) setStudents(cloudData.students);
      if (cloudData.attendance) setAttendance(cloudData.attendance);
      if (cloudData.behavior) setBehaviorRecords(cloudData.behavior);
      if (cloudData.payments) setPaymentRecords(cloudData.payments);
      if (cloudData.subjects) setSubjects(cloudData.subjects);
      if (cloudData.news) setNews(cloudData.news);
      if (cloudData.logs) setLoginLogs(cloudData.logs);
      if (cloudData.blocks) setStudyBlocks(cloudData.blocks);
    } catch (error) {
      console.error("Cloud Sync Error:", error);
    } finally {
      setIsSyncingWithCloud(false);
    }
  }, []);

  const syncToCloud = async (type: string, data: any) => {
    const url = getScriptUrl();
    if (!url) return;
    try {
      await fetch(url, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'syncData', type, data })
      });
    } catch (e) {
      console.error("Auto Sync Failed", e);
    }
  };

  useEffect(() => {
    const savedBlocks = localStorage.getItem('cms_study_blocks');
    if (savedBlocks) setStudyBlocks(JSON.parse(savedBlocks));

    const savedLogs = localStorage.getItem('cms_audit_logs');
    if (savedLogs) setLoginLogs(JSON.parse(savedLogs));

    setStudents(MOCK_STUDENTS);
    setAttendance(MOCK_ATTENDANCE);
    setBehaviorRecords(MOCK_BEHAVIOR);
    setSubjects(MOCK_SUBJECTS);
    setSystemUsers([
      { id: 'A1', name: 'แอดมิน ระบบ', role: 'ADMIN', username: 'admin', password: '1234', department: 'ส่วนกลาง' },
      { id: 'AC1', name: 'หัวหน้างานฝ่ายวิชาการ', role: 'ACADEMIC', username: 'academic', password: '1234', department: 'งานวิชาการ' },
      { id: 'T1', name: 'อ.สมพงษ์ ใจสว่าง', role: 'TEACHER', username: 'teacher', password: '1234', department: 'เทคโนโลยีสารสนเทศ' },
      { id: 'C1', name: 'บจก. นวัตกรรมซอฟต์แวร์', role: 'COMPANY', username: 'company', password: '1234', companyName: 'บริษัท นวัตกรรมซอฟต์แวร์ จำกัด' },
      { id: 'F1', name: 'ฝ่ายการเงิน', role: 'FINANCE', username: 'finance', password: '1234', department: 'ฝ่ายการเงิน' },
      { id: 'P1', name: 'คุณแม่ของนายสมชาย', role: 'PARENT', username: 'parent', password: '1234', studentId: '1' }
    ]);
    fetchDataFromCloud();
  }, [fetchDataFromCloud]);

  const handleLogin = (userData: User) => {
    const newLog: LoginLog = {
      id: `LOG_${Date.now()}`,
      userId: userData.username,
      userName: userData.name,
      userRole: userData.role,
      timestamp: new Date().toLocaleString('th-TH'),
      deviceInfo: navigator.userAgent
    };

    setLoginLogs(prev => {
      const updated = [newLog, ...prev].slice(0, 1000); 
      localStorage.setItem('cms_audit_logs', JSON.stringify(updated));
      syncToCloud('logs', updated);
      return updated;
    });

    setUser(userData);
    if (userData.role === 'COMPANY') {
      setActiveMenu('job_portal');
    } else {
      setActiveMenu('dashboard');
    }
  };

  if (!user) return <Login onLogin={handleLogin} systemUsers={systemUsers} />;

  const renderContent = () => {
    switch (activeMenu) {
      case 'dashboard': return <Dashboard students={students} attendance={attendance} behavior={behaviorRecords} news={news} notifications={notifications} user={user} studyBlocks={studyBlocks} tuitionConfigs={tuitionConfigs} paymentRecords={paymentRecords} />;
      case 'job_portal': return <JobPortal currentUser={user} students={students} />; 
      case 'broadcast': return <NewsBroadcast students={students} news={news} setNews={(val) => { setNews(val); syncToCloud('news', val); }} currentUser={user} />;
      case 'quick_scan': return <QuickScan students={students} attendanceRecords={attendance} setAttendanceRecords={(val) => { setAttendance(val); syncToCloud('attendance', val); }} />;
      case 'students': return <StudentManagement students={students} setStudents={(val) => { setStudents(val); syncToCloud('students', val); }} />;
      case 'morning': return <MorningAttendance students={students} setStudents={setStudents} attendanceRecords={attendance} setAttendanceRecords={(val) => { setAttendance(val); syncToCloud('attendance', val); }} rooms={rooms} setRooms={setRooms} />;
      case 'subject': return <ClassAttendance students={students} setStudents={setStudents} subjects={subjects} setSubjects={(val) => { setSubjects(val); syncToCloud('subjects', val); }} rooms={rooms} setRooms={setRooms} attendanceRecords={attendance} setAttendanceRecords={(val) => { setAttendance(val); syncToCloud('attendance', val); }} currentUser={user} />;
      case 'behavior': return <BehaviorSystem students={students} setStudents={setStudents} behaviorRecords={behaviorRecords} setBehaviorRecords={(val) => { setBehaviorRecords(val); syncToCloud('behavior', val); }} />;
      case 'tuition': return <TuitionSystem students={students} tuitionConfigs={tuitionConfigs} setTuitionConfigs={setTuitionConfigs} paymentRecords={paymentRecords} setPaymentRecords={(val) => { setPaymentRecords(val); syncToCloud('payments', val); }} user={user} />;
      case 'finance_report': return <FinanceReport students={students} paymentRecords={paymentRecords} tuitionConfigs={tuitionConfigs} />;
      case 'report': return <Reports students={students} attendance={attendance} behavior={behaviorRecords} user={user} studyBlocks={studyBlocks} paymentRecords={paymentRecords} tuitionConfigs={tuitionConfigs} />;
      case 'morning_scores': return <MorningScoreSummary students={students} attendance={attendance} studyBlocks={studyBlocks} />;
      case 'users': return <UserManagement users={systemUsers} setUsers={setSystemUsers} currentUser={user} students={students} />;
      case 'audit_logs': return <AuditLogs logs={loginLogs} setLogs={(val) => { setLoginLogs(val); localStorage.setItem('cms_audit_logs', JSON.stringify(val)); syncToCloud('logs', val); }} />;
      case 'exam_manager': return <ExamManager studyBlocks={studyBlocks} setStudyBlocks={(val) => { setStudyBlocks(val); localStorage.setItem('cms_study_blocks', JSON.stringify(val)); syncToCloud('blocks', val); }} />;
      case 'scanner_settings': return <ScannerSettings />;
      case 'settings': return <SystemSettings studyBlocks={studyBlocks} setStudyBlocks={(val) => { setStudyBlocks(val); localStorage.setItem('cms_study_blocks', JSON.stringify(val)); }} />;
      case 'cloud_config': return <CloudConfig students={students} attendance={attendance} behavior={behaviorRecords} payments={paymentRecords} subjects={subjects} />;
      case 'line_config': return <LineConfig />;
      default: return <JobPortal currentUser={user} students={students} />;
    }
  };

  return (
    <Layout activeMenu={activeMenu} setActiveMenu={setActiveMenu} user={user} onLogout={() => setUser(null)} notifications={notifications} setNotifications={setNotifications}>
      {isSyncingWithCloud && (
        <div className="fixed bottom-8 right-8 z-[100] bg-slate-900 text-white px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 animate-bounce">
          <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
          <span className="text-xs font-black uppercase tracking-widest">กำลังดึงข้อมูลล่าสุดจากระบบ Cloud...</span>
        </div>
      )}
      {renderContent()}
    </Layout>
  );
};

export default App;
